INSERT INTO exercise (
    id, name, muscle_group, equipment, level, instructions,
    source, source_exercise_id, name_en, category_code, category_name, category_sort,
    equipment_code, muscle_group_code, target_code, target_name, secondary_muscles,
    instructions_en, image_url, gif_url, attribution, popularity_rank
) VALUES
('100001', '四分之三仰卧起坐', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0001', '3/4 sit-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0001-2gPfomN.jpg', '/static/exercises/gifs/0001-2gPfomN.gif', '© Gym visual — https://gymvisual.com/', '160004'),
('100002', '45度侧屈', '腹斜肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂在身体两侧笔直向下伸展。保持背部挺直，核心肌群参与，慢慢将躯干向一侧弯曲，将手向膝盖方向放低。在底部停顿片刻，然后慢慢回到起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '0002', '45° side bend', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides. Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee. Pause for a moment at the bottom, then slowly return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0002-Hy9D21L.jpg', '/static/exercises/gifs/0002-Hy9D21L.gif', '© Gym visual — https://gymvisual.com/', '900007'),
('100003', '空中自行车卷腹', '髋屈肌', '自重', '未分级', '平躺，双手放在脑后。将双腿抬离地面，并以 90 度角弯曲膝盖。将右肘靠近左膝盖，同时伸直右腿。返回起始位置，在另一侧重复该动作，将左肘拉向右膝盖，同时伸直左腿。继续交替进行蹬踏动作，达到所需的重复次数。', 'exercise-dataset', '0003', 'air bike', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your hands placed behind your head. Lift your legs off the ground and bend your knees at a 90-degree angle. Bring your right elbow towards your left knee while simultaneously straightening your right leg. Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg. Continue alternating sides in a pedaling motion for the desired number of repetitions.', '/static/exercises/images/0003-1ZFqTDN.jpg', '/static/exercises/gifs/0003-1ZFqTDN.gif', '© Gym visual — https://gymvisual.com/', '900006'),
('101512', '四点支撑深蹲拉伸', '腘绳肌', '自重', '未分级', '从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。将一条腿向后伸直，保持膝盖弯曲和脚弯曲。慢慢地将臀部降低到地面，感觉股四头肌的伸展。保持这个姿势20-30秒。换腿并在另一侧重复拉伸。', 'exercise-dataset', '1512', 'all fours squad stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌"]', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Extend one leg straight back, keeping your knee bent and your foot flexed. Slowly lower your hips towards the ground, feeling a stretch in your quads. Hold this position for 20-30 seconds. Switch legs and repeat the stretch on the other side.', '/static/exercises/images/1512-qBcKorM.jpg', '/static/exercises/gifs/1512-qBcKorM.gif', '© Gym visual — https://gymvisual.com/', '900011'),
('100006', '交替脚跟触碰', '腹斜肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双臂伸直至两侧，与地面平行。收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。返回起始位置并在左侧重复，将左手伸向左脚跟。继续交替进行所需的重复次数。', 'exercise-dataset', '0006', 'alternate heel touchers', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight out to the sides, parallel to the ground. Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel. Return to the starting position and repeat on the left side, reaching your left hand towards your left heel. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0006-qaZVsGk.jpg', '/static/exercises/gifs/0006-qaZVsGk.gif', '© Gym visual — https://gymvisual.com/', '900010'),
('100007', '交替侧向下拉', '肱二头肌', '绳索器械', '未分级', '坐在缆绳机上，背部挺直，双脚平放在地面上。正手握住手柄，握距略宽于肩宽。稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0007', 'alternate lateral pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌"]', 'Sit on the cable machine with your back straight and feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0007-4IKbhHV.jpg', '/static/exercises/gifs/0007-4IKbhHV.gif', '© Gym visual — https://gymvisual.com/', '80311'),
('101368', '踝关节环绕', '踝关节稳定肌', '自重', '未分级', '坐在地上，双腿在身前伸展。将一条腿抬离地面，并以圆周运动旋转脚踝。在一个方向上转所需的圈数，然后切换到另一个方向。换另一条腿重复上述步骤。', 'exercise-dataset', '1368', 'ankle circles', 'lower legs', '小腿', '70', 'body weight', 'ankle stabilizers', 'calves', '小腿肌群', '["踝关节稳定肌"]', 'Sit on the ground with your legs extended in front of you. Lift one leg off the ground and rotate your ankle in a circular motion. Perform the desired number of circles in one direction, then switch to the other direction. Repeat with the other leg.', '/static/exercises/images/1368-uL9CsKm.jpg', '/static/exercises/gifs/1368-uL9CsKm.gif', '© Gym visual — https://gymvisual.com/', '160010'),
('103293', '弓箭手引体向上', '肱二头肌', '自重', '未分级', '首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。启动你的核心并将肩胛骨向下拉和向后拉。当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。每次重复时交替进行。', 'exercise-dataset', '3293', 'archer pull up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight. Continue pulling until your chin is above the bar and your bent arm is fully flexed. Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side. Alternate sides with each repetition.', '/static/exercises/images/3293-72BC5Za.jpg', '/static/exercises/gifs/3293-72BC5Za.gif', '© Gym visual — https://gymvisual.com/', '900013'),
('103294', '弓箭手俯卧撑', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽。将一只手臂伸直至一侧，与地面平行。弯曲肘部降低身体，保持背部挺直，核心参与。推回到起始位置。在另一侧重复上述步骤，将另一只手臂伸出到一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '3294', 'archer push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart. Extend one arm straight out to the side, parallel to the ground. Lower your body by bending your elbows, keeping your back straight and core engaged. Push back up to the starting position. Repeat on the other side, extending the opposite arm out to the side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3294-A9qxk2F.jpg', '/static/exercises/gifs/3294-A9qxk2F.gif', '© Gym visual — https://gymvisual.com/', '900014'),
('102355', '臂摆动悬垂屈曲膝双腿', '肩部', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，膝盖弯曲成 90 度角。收紧核心并将膝盖抬向胸部，尽可能靠近肘部。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2355', 'arm slingers hanging bent knee legs', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","后侧"]', 'Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle. Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2355-uWpxD4v.jpg', '/static/exercises/gifs/2355-uWpxD4v.gif', '© Gym visual — https://gymvisual.com/', '900021'),
('102333', '臂摆动悬垂直双腿', '肩部', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，双腿伸直向下。启动你的核心并将双腿抬起到你面前，直到它们与地面平行。在顶部保持片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2333', 'arm slingers hanging straight legs', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","后侧"]', 'Hang from a pull-up bar with your arms fully extended and your legs straight down. Engage your core and lift your legs up in front of you until they are parallel to the ground. Hold for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2333-PXTIwgu.jpg', '/static/exercises/gifs/2333-PXTIwgu.gif', '© Gym visual — https://gymvisual.com/', '900020'),
('103214', '双臂分开环绕脚尖触碰（男）', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂向两侧伸展。保持双腿伸直，腰部向前弯曲，右手向下伸向脚趾。当你向下伸展时，同时将左腿在身后伸直，保持平衡。返回起始位置，重复该动作，左手伸向脚趾，右腿在身后抬起。继续交替进行所需的重复次数。', 'exercise-dataset', '3214', 'arms apart circular toe touch (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and arms extended to the sides. Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand. As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance. Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3214-RtyAsy1.jpg', '/static/exercises/gifs/3214-RtyAsy1.gif', '© Gym visual — https://gymvisual.com/', '900023'),
('103204', '双臂过顶全程仰卧起坐（男）', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将手臂伸过头顶，保持伸直。收紧腹肌，慢慢将上半身抬离地面，向前卷曲直到躯干直立。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3204', 'arms overhead full sit-up (male)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms overhead, keeping them straight. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3204-NAkmgdx.jpg', '/static/exercises/gifs/3204-NAkmgdx.gif', '© Gym visual — https://gymvisual.com/', '160022'),
('100009', '辅助双杠臂屈伸跪姿', '肱三头肌', '固定器械', '未分级', '将机器调整到您想要的高度，并将膝盖固定在垫子上。手掌朝下，抓住手柄，双臂完全伸展。弯曲肘部降低身体，直到上臂与地板平行。暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0009', 'assisted chest dip (kneeling)', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with your palms facing down and your arms fully extended. Lower your body by bending your elbows until your upper arms are parallel to the floor. Pause for a moment, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0009-PAgTVaK.jpg', '/static/exercises/gifs/0009-PAgTVaK.gif', '© Gym visual — https://gymvisual.com/', '320421'),
('100011', '辅助悬垂举膝', '髋屈肌', '辅助器械', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。调动你的核心肌肉，将膝盖抬向胸部，弯曲臀部和膝盖。在动作的最高点暂停片刻，挤压腹肌。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0011', 'assisted hanging knee raise', 'waist', '腰腹', '60', 'assisted', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core muscles and lift your knees towards your chest, bending at the hips and knees. Pause for a moment at the top of the movement, squeezing your abs. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0011-03lzqwk.jpg', '/static/exercises/gifs/0011-03lzqwk.gif', '© Gym visual — https://gymvisual.com/', '320922'),
('100010', '辅助悬垂举膝抗阻下压', '髋屈肌', '辅助器械', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。收紧核心并将膝盖抬向胸部，保持双腿并拢。一旦你的膝盖与胸部齐平，爆发性地将你的双腿向地面扔去，将它们完全伸展。让双腿向后摆动并重复该动作达到所需的重复次数。', 'exercise-dataset', '0010', 'assisted hanging knee raise with throw down', 'waist', '腰腹', '60', 'assisted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees towards your chest, keeping your legs together. Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully. Allow your legs to swing back up and repeat the movement for the desired number of repetitions.', '/static/exercises/images/0010-8K0w2yA.jpg', '/static/exercises/gifs/0010-8K0w2yA.gif', '© Gym visual — https://gymvisual.com/', '320929'),
('101708', '辅助仰卧小腿拉伸', '腘绳肌', '辅助器械', '未分级', '仰卧，双腿伸展。弯曲一侧膝盖，将脚平放在地上。用手或毛巾轻轻地将脚趾拉向身体，感受小腿的拉伸。保持拉伸 20-30 秒。松开拉伸并在另一条腿上重复。', 'exercise-dataset', '1708', 'assisted lying calves stretch', 'lower legs', '小腿', '70', 'assisted', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Lie on your back with your legs extended. Bend one knee and place your foot flat on the ground. Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other leg.', '/static/exercises/images/1708-GxDwDX0.jpg', '/static/exercises/gifs/1708-GxDwDX0.gif', '© Gym visual — https://gymvisual.com/', '900924'),
('101709', '辅助仰卧臀肌拉伸', '腘绳肌', '辅助器械', '未分级', '仰卧，双腿伸展。弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。用双手抓住左大腿，轻轻地将其拉向胸部。保持拉伸 20-30 秒。松开并在另一侧重复。', 'exercise-dataset', '1709', 'assisted lying glutes stretch', 'upper legs', '大腿', '40', 'assisted', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Lie on your back with your legs extended. Bend your right knee and place your right ankle on your left thigh, just above the knee. Grasp your left thigh with both hands and gently pull it towards your chest. Hold the stretch for 20-30 seconds. Release and repeat on the other side.', '/static/exercises/images/1709-yn0LjwL.jpg', '/static/exercises/gifs/1709-yn0LjwL.gif', '© Gym visual — https://gymvisual.com/', '900925'),
('101710', '辅助仰卧臀肌梨状肌拉伸', '腘绳肌', '辅助器械', '未分级', '仰卧，双腿伸展。弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。用双手抓住左大腿，轻轻地将其拉向胸部。保持拉伸 20-30 秒。松开拉伸并在另一侧重复。', 'exercise-dataset', '1710', 'assisted lying gluteus and piriformis stretch', 'upper legs', '大腿', '40', 'assisted', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Lie on your back with your legs extended. Bend your right knee and place your right ankle on your left thigh, just above the knee. Grasp your left thigh with both hands and gently pull it towards your chest. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other side.', '/static/exercises/images/1710-RQNVT10.jpg', '/static/exercises/gifs/1710-RQNVT10.gif', '© Gym visual — https://gymvisual.com/', '900930'),
('100012', '辅助仰卧侧向抗阻举腿', '髋屈肌', '辅助器械', '未分级', '平躺，双腿伸展，双臂放在身体两侧。将双手放在臀部下方以获得支撑。收紧腹肌，将双腿抬离地面，保持伸直。双腿并拢的同时，将它们降低到一侧，直到离地几英寸。暂停片刻，然后抬起双腿回到起始位置。到另一侧重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0012', 'assisted lying leg raise with lateral throw down', 'waist', '腰腹', '60', 'assisted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","腹斜肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your abs and lift your legs off the ground, keeping them straight. While keeping your legs together, lower them to one side until they are a few inches above the ground. Pause for a moment, then lift your legs back to the starting position. Repeat the movement to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0012-UGhRD1A.jpg', '/static/exercises/gifs/0012-UGhRD1A.gif', '© Gym visual — https://gymvisual.com/', '240935'),
('100013', '辅助仰卧抗阻举腿', '髋屈肌', '辅助器械', '未分级', '平躺，双腿伸展，双臂放在身体两侧。将双手放在臀部下方以获得支撑。启动你的核心并将双腿抬离地面，保持伸直。抬起双腿，直到它们垂直于地面。将双腿放低回到起始位置。同时，将双腿向地面放下，保持伸直。将双腿抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0013', 'assisted lying leg raise with throw down', 'waist', '腰腹', '60', 'assisted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","股四头肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your core and lift your legs off the ground, keeping them straight. Raise your legs until they are perpendicular to the ground. Lower your legs back down to the starting position. Simultaneously, throw your legs down towards the ground, keeping them straight. Raise your legs back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0013-VX5YKR5.jpg', '/static/exercises/gifs/0013-VX5YKR5.gif', '© Gym visual — https://gymvisual.com/', '240934'),
('100014', '辅助动态俄罗斯转体', '腹斜肌', '药球', '未分级', '坐在地上，膝盖弯曲，双脚平放在地板上。双手将健身球放在胸前。稍微向后倾斜，收紧腹肌并保持背部挺直。慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0014', 'assisted motion russian twist', 'waist', '腰腹', '60', 'medicine ball', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on the ground with your knees bent and feet flat on the floor. Hold the medicine ball with both hands in front of your chest. Lean back slightly, engaging your abs and keeping your back straight. Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0014-r7cT9YD.jpg', '/static/exercises/gifs/0014-r7cT9YD.gif', '© Gym visual — https://gymvisual.com/', '400929'),
('100015', '辅助平行握窄距握引体向上', '肱二头肌', '固定器械', '未分级', '将机器调整到您想要的重量和高度。将双手紧紧握在双杠上，手掌相对。悬挂在杠上，双臂完全伸展，双脚离开地面。收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。继续拉，直到下巴高于杠铃。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0015', 'assisted parallel close grip pull-up', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the machine to your desired weight and height. Place your hands on the parallel bars with a close grip, palms facing each other. Hang from the bars with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body. Continue pulling until your chin is above the bars. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0015-vrhHa6D.jpg', '/static/exercises/gifs/0015-vrhHa6D.gif', '© Gym visual — https://gymvisual.com/', '432'),
('100016', '辅助俯卧腘绳肌', '臀肌', '辅助器械', '未分级', '脸朝下躺在垫子或长凳上，双腿完全伸展。找一个伙伴或使用阻力带来固定脚踝。收紧腿筋，将双腿抬向臀肌，保持膝盖伸直。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0016', 'assisted prone hamstring', 'upper legs', '大腿', '40', 'assisted', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","下背部"]', 'Lie face down on a mat or bench with your legs fully extended. Have a partner or use a resistance band to secure your ankles. Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0016-VedGSby.jpg', '/static/exercises/gifs/0016-VedGSby.gif', '© Gym visual — https://gymvisual.com/', '900929'),
('101713', '辅助俯卧仰卧股四头肌拉伸', '腘绳肌', '辅助器械', '未分级', '脸朝下躺在地上，双腿伸直。弯曲左膝，用左手向后抓住左脚或脚踝。轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。保持拉伸 20-30 秒，然后放松。右腿重复上述动作。', 'exercise-dataset', '1713', 'assisted prone lying quads stretch', 'upper legs', '大腿', '40', 'assisted', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌"]', 'Lie face down on the ground with your legs extended. Bend your left knee and reach back with your left hand to grab your left foot or ankle. Gently pull your left foot towards your glutes, feeling a stretch in your left quad. Hold the stretch for 20-30 seconds, then release. Repeat with your right leg.', '/static/exercises/images/1713-YUYAMEj.jpg', '/static/exercises/gifs/1713-YUYAMEj.gif', '© Gym visual — https://gymvisual.com/', '900934'),
('101714', '辅助俯卧直肌股直肌拉伸', '股四头肌', '辅助器械', '未分级', '脸朝下躺在地上，双腿伸直。弯曲右膝，用右手向后伸抓住右脚或脚踝。轻轻地将右脚或脚踝拉向臀部，感受右大腿前部的拉伸。保持拉伸 20-30 秒。松开并在另一侧重复。', 'exercise-dataset', '1714', 'assisted prone rectus femoris stretch', 'waist', '腰腹', '60', 'assisted', 'quadriceps', 'abs', '腹肌', '["股四头肌"]', 'Lie face down on the ground with your legs straight. Bend your right knee and reach back with your right hand to grab your right foot or ankle. Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh. Hold the stretch for 20-30 seconds. Release and repeat on the other side.', '/static/exercises/images/1714-2Ryn564.jpg', '/static/exercises/gifs/1714-2Ryn564.gif', '© Gym visual — https://gymvisual.com/', '900935'),
('100017', '辅助引体向上', '肱二头肌', '固定器械', '未分级', '将机器调整至您所需的体重和高度设置。正手握住手柄，握距略宽于肩宽。双臂完全伸展，双脚离开地面。收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。继续拉，直到下巴位于手柄上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0017', 'assisted pull-up', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the machine to your desired weight and height settings. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body. Continue pulling until your chin is above the handles. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0017-kiJ4Z2K.jpg', '/static/exercises/gifs/0017-kiJ4Z2K.gif', '© Gym visual — https://gymvisual.com/', '430'),
('101716', '辅助坐姿胸肌大肌拉伸瑞士球', '肩部', '辅助器械', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。双手握住稳定球，并将双臂伸直至身前。慢慢地将稳定球降低到胸部，感受胸肌的拉伸。保持伸展几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1716', 'assisted seated pectoralis major stretch with stability ball', 'chest', '胸部', '10', 'assisted', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a stability ball with both hands and extend your arms straight out in front of you. Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1716-RoV1Rfa.jpg', '/static/exercises/gifs/1716-RoV1Rfa.gif', '© Gym visual — https://gymvisual.com/', '900943'),
('101712', '辅助侧向仰卧内收肌拉伸', '腘绳肌', '辅助器械', '未分级', '侧躺，双腿伸直并叠放在一起。稍微弯曲下面的腿以保持稳定。将上脚放在稳定的表面上，例如长凳或台阶上。保持上腿伸直，慢慢将其降低到地面，感觉大腿内侧有拉伸感。保持拉伸 20-30 秒。返回起始位置并在另一侧重复。', 'exercise-dataset', '1712', 'assisted side lying adductor stretch', 'upper legs', '大腿', '40', 'assisted', 'hamstrings', 'adductors', '内收肌群', '["腘绳肌","臀肌"]', 'Lie on your side with your legs straight and stacked on top of each other. Bend your bottom leg slightly for stability. Place your top foot on a stable surface, such as a bench or step. Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh. Hold the stretch for 20-30 seconds. Return to the starting position and repeat on the other side.', '/static/exercises/images/1712-hC6oYY5.jpg', '/static/exercises/gifs/1712-hC6oYY5.gif', '© Gym visual — https://gymvisual.com/', '900938'),
('101758', '辅助坐向上', '髋屈肌', '辅助器械', '未分级', '坐在长凳边缘或让某人按住你的脚。平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1758', 'assisted sit-up', 'waist', '腰腹', '60', 'assisted', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the edge of a bench or have someone hold your feet down. Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1758-aumB2IV.jpg', '/static/exercises/gifs/1758-aumB2IV.gif', '© Gym visual — https://gymvisual.com/', '160933'),
('101431', '辅助站姿反手引体向上', '肱二头肌', '固定器械', '未分级', '将机器调整至您所需的辅助级别。站在脚踏板上，正手握住手柄，握距略宽于肩宽。保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。弯曲肘部并将肘部向身体两侧压低，将身体向上拉。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1431', 'assisted standing chin-up', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the machine to your desired assistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your chest up and shoulders back, engage your core, and slightly bend your knees. Pull your body up by flexing your elbows and driving your elbows down towards your sides. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1431-7OeHptV.jpg', '/static/exercises/gifs/1431-7OeHptV.gif', '© Gym visual — https://gymvisual.com/', '900436'),
('101432', '辅助站姿引体向上', '肱二头肌', '固定器械', '未分级', '将机器调整至您所需的体重和高度设置。面向机器站立，双脚分开与肩同宽。正手握住手柄，握距略宽于肩宽。启动你的背阔肌和二头肌，并将自己拉向手柄。在顶部暂停片刻，挤压背部肌肉。慢慢地将自己放回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1432', 'assisted standing pull-up', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the machine to your desired weight and height settings. Stand facing the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Engage your lats and biceps, and pull yourself up towards the handles. Pause for a moment at the top, squeezing your back muscles. Slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1432-f4xtKBj.jpg', '/static/exercises/gifs/1432-f4xtKBj.gif', '© Gym visual — https://gymvisual.com/', '437'),
('100018', '辅助站姿肱三头肌臂屈伸毛巾', '肩部', '辅助器械', '未分级', '双脚分开与肩同宽站立，双手握住毛巾放在脑后。保持肘部靠近耳朵，上臂保持静止。慢慢向上伸展前臂，在顶部挤压三头肌。暂停片刻，然后慢慢将毛巾放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0018', 'assisted standing triceps extension (with towel)', 'upper arms', '上臂', '50', 'assisted', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a towel with both hands behind your head. Keep your elbows close to your ears and your upper arms stationary. Slowly extend your forearms upward, squeezing your triceps at the top. Pause for a moment, then slowly lower the towel back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0018-7HcfMBP.jpg', '/static/exercises/gifs/0018-7HcfMBP.gif', '© Gym visual — https://gymvisual.com/', '400944'),
('100019', '辅助肱三头肌臂屈伸跪姿', '胸肌', '固定器械', '未分级', '将机器调整到您想要的重量和高度。跪在面向机器的垫子上，双手握住手柄。弯曲肘部降低身体，保持背部挺直并靠近机器。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0019', 'assisted triceps dip (kneeling)', 'upper arms', '上臂', '50', 'leverage machine', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Adjust the machine to your desired weight and height. Kneel down on the pad facing the machine, with your hands gripping the handles. Lower your body by bending your elbows, keeping your back straight and close to the machine. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0019-J60bN17.jpg', '/static/exercises/gifs/0019-J60bN17.gif', '© Gym visual — https://gymvisual.com/', '480441'),
('102364', '辅助宽握双杠臂屈伸跪姿', '肱三头肌', '固定器械', '未分级', '将机器调整到您想要的高度，并将膝盖固定在垫子上。宽握手柄并保持肘部稍微弯曲。弯曲肘部降低身体，直到上臂与地板平行。伸展双臂，将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2364', 'assisted wide-grip chest dip (kneeling)', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the machine to your desired height and secure your knees on the pad. Grasp the handles with a wide grip and keep your elbows slightly bent. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2364-PnZJIrk.jpg', '/static/exercises/gifs/2364-PnZJIrk.gif', '© Gym visual — https://gymvisual.com/', '320444'),
('103220', '跨立跳跃（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将身体降低至蹲姿。爆发性向上跳跃，伸展双腿和手臂。在空中时，将双腿分开，并将双臂向两侧伸出。双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。重复所需的重复次数。', 'exercise-dataset', '3220', 'astride jumps (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively upwards, extending your legs and arms. While in the air, spread your legs apart and bring your arms out to the sides. Land softly with your feet shoulder-width apart, bending your knees to absorb the impact. Repeat for the desired number of repetitions.', '/static/exercises/images/3220-f9lVSSI.jpg', '/static/exercises/gifs/3220-f9lVSSI.gif', '© Gym visual — https://gymvisual.com/', '560041'),
('103672', '后侧向前踏步', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。右脚向前迈出一步，弯曲膝盖，将身体降低到弓步位置。用右脚蹬地，然后回到起始位置。用左脚重复该动作，每一步交替双腿。继续来回走动，保持稳定的步伐。重复所需的持续时间或重复次数。', 'exercise-dataset', '3672', 'back and forth step', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Step forward with your right foot, bending your knee and lowering your body into a lunge position. Push off with your right foot and step back to the starting position. Repeat the movement with your left foot, alternating legs with each step. Continue stepping back and forth, maintaining a steady pace. Repeat for the desired duration or number of repetitions.', '/static/exercises/images/3672-fNGumX0.jpg', '/static/exercises/gifs/3672-fNGumX0.gif', '© Gym visual — https://gymvisual.com/', '900044'),
('101314', '山羊挺身健身球', '臀肌', '瑞士球', '未分级', '将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。将双手放在脑后或交叉在胸前。启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1314', 'back extension on exercise ball', 'back', '背部', '20', 'stability ball', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface. Position your hands behind your head or crossed over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1314-qLpO4vV.jpg', '/static/exercises/gifs/1314-qLpO4vV.gif', '© Gym visual — https://gymvisual.com/', '480947'),
('103297', '后侧器械', '肱二头肌', '自重', '未分级', '首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。启动你的核心并将肩胛骨向下拉和向后拉。弯曲膝盖并将其向胸部靠拢。慢慢抬起双腿，保持伸直，直到身体与地面平行。保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3297', 'back lever', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂","核心肌群"]', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest. Slowly lift your legs up, keeping them straight, until your body is parallel to the ground. Hold this position for a few seconds, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3297-GaSzzuh.jpg', '/static/exercises/gifs/3297-GaSzzuh.gif', '© Gym visual — https://gymvisual.com/', '900042'),
('101405', '后侧胸肌拉伸', '肩部', '自重', '未分级', '站直，双脚分开与肩同宽。将双臂伸直在身前，与地面平行。双臂交叉在身体前方，右臂放在左臂上方。手指交叉，手掌旋转远离身体。慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。保持拉伸 15-30 秒，然后放松。在另一侧重复。', 'exercise-dataset', '1405', 'back pec stretch', 'back', '背部', '20', 'body weight', 'shoulders', 'lats', '背阔肌', '["肩部","胸肌"]', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you, parallel to the ground. Cross your arms in front of your body, with your right arm over your left arm. Interlock your fingers and rotate your palms away from your body. Slowly raise your arms up and away from your body, feeling a stretch in your back and chest. Hold the stretch for 15-30 seconds, then release. Repeat on the opposite side.', '/static/exercises/images/1405-chfnQnM.jpg', '/static/exercises/gifs/1405-chfnQnM.gif', '© Gym visual — https://gymvisual.com/', '900045'),
('101473', '向后跳跃', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立。稍微弯曲膝盖，向后跳跃，用双脚蹬地。脚掌轻轻着地，弯曲膝盖以吸收冲击力。重复所需的重复次数。', 'exercise-dataset', '1473', 'backward jump', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump backwards, pushing off with both feet. Land softly on the balls of your feet, bending your knees to absorb the impact. Repeat for the desired number of repetitions.', '/static/exercises/images/1473-SaDOwk7.jpg', '/static/exercises/gifs/1473-SaDOwk7.gif', '© Gym visual — https://gymvisual.com/', '900044'),
('100020', '平衡木板', '小腿肌群', '自重', '未分级', '将平衡板放在平坦的表面上。用一只脚踩在平衡板上，确保其居中。慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。在保持该姿势所需的时间内保持平衡和稳定。用另一只脚重复该练习。', 'exercise-dataset', '0020', 'balance board', 'upper legs', '大腿', '40', 'body weight', 'calves', 'quads', '股四头肌', '["小腿肌群","腘绳肌","臀肌"]', 'Place the balance board on a flat surface. Step onto the balance board with one foot, ensuring it is centered. Slowly shift your weight onto the foot on the balance board, keeping your core engaged. Maintain your balance and stability as you hold the position for a desired amount of time. Repeat the exercise with the other foot.', '/static/exercises/images/0020-xAySMB0.jpg', '/static/exercises/gifs/0020-xAySMB0.gif', '© Gym visual — https://gymvisual.com/', '900045'),
('100968', '弹力带交替弯举', '前臂', '弹力带', '未分级', '双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。将手臂放回起始位置，然后用另一只手臂重复此动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0968', 'band alternating biceps curl', 'upper arms', '上臂', '50', 'band', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up. Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top. Lower the arm back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0968-3omWx6P.jpg', '/static/exercises/gifs/0968-3omWx6P.gif', '© Gym visual — https://gymvisual.com/', '650'),
('100969', '弹力带交替V字卷腹', '髋屈肌', '弹力带', '未分级', '平躺，双腿伸直，手臂伸过头顶，握住弹力带。收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。重复该动作，每次重复时交替变换双腿的位置。继续进行所需的重复次数。', 'exercise-dataset', '0969', 'band alternating v-up', 'waist', '腰腹', '60', 'band', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes. As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other. Repeat the movement, alternating the position of your legs with each repetition. Continue for the desired number of repetitions.', '/static/exercises/images/0969-ztAa1RK.jpg', '/static/exercises/gifs/0969-ztAa1RK.gif', '© Gym visual — https://gymvisual.com/', '480649'),
('100970', '弹力带辅助引体向上', '肱二头肌', '弹力带', '未分级', '将弹力带固定在上拉杆或坚固的锚点上。踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0970', 'band assisted pull-up', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach the band to a pull-up bar or sturdy anchor point. Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your core engaged and your shoulders down and back. Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0970-r1XNRYB.jpg', '/static/exercises/gifs/0970-r1XNRYB.gif', '© Gym visual — https://gymvisual.com/', '650'),
('100971', '弹力带辅助健腹轮滚轮前伸', '下背部', '弹力带', '未分级', '跪在地板上，双手握住弹力带的手柄，手掌朝下。将弹力带放在您面前的地面上，双手分开与肩同宽。启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0971', 'band assisted wheel rollerout', 'waist', '腰腹', '60', 'band', 'lower back', 'abs', '腹肌', '["下背部"]', 'Kneel on the floor and hold the handles of the band with both hands, palms facing down. Place the band on the ground in front of you and position your hands shoulder-width apart. Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control. Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0971-zhF9lW4.jpg', '/static/exercises/gifs/0971-zhF9lW4.gif', '© Gym visual — https://gymvisual.com/', '560653'),
('101254', '弹力带卧推', '肱三头肌', '弹力带', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。正手握住带子手柄，间距略宽于肩宽。充分伸展双臂，将弹力带推离胸部。慢慢将弹力带放回到胸部，保持肘部呈 90 度角。重复所需的重复次数。', 'exercise-dataset', '1254', 'band bench press', 'chest', '胸部', '10', 'band', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart. Extend your arms fully, pushing the bands away from your chest. Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle. Repeat for the desired number of repetitions.', '/static/exercises/images/1254-khlHMqs.jpg', '/static/exercises/gifs/1254-khlHMqs.gif', '© Gym visual — https://gymvisual.com/', '652'),
('100980', '弹力带屈曲越过伸髋', '腘绳肌', '弹力带', '未分级', '将带子固定在脚踝高度的坚固锚点上。背对锚点站立，双脚与肩同宽。向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。铰接臀部并向前倾斜，保持脊柱中立。将右腿向后伸直，在顶部挤压臀部。将右腿放回原位，然后换左腿重复此动作。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '0980', 'band bent-over hip extension', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Attach the band to a sturdy anchor point at ankle height. Stand facing away from the anchor point with your feet shoulder-width apart. Step back to create tension in the band, keeping your knees slightly bent. Hinge at the hips and lean forward, maintaining a neutral spine. Extend your right leg straight back, squeezing your glutes at the top. Lower your right leg back down and repeat with the left leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/0980-wSScovH.jpg', '/static/exercises/gifs/0980-wSScovH.gif', '© Gym visual — https://gymvisual.com/', '900655'),
('100972', '弹力带自行车卷腹', '髋屈肌', '弹力带', '未分级', '平躺，双手放在脑后，膝盖弯曲。将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。重复所需的重复次数。', 'exercise-dataset', '0972', 'band bicycle crunch', 'waist', '腰腹', '60', 'band', 'hip flexors', 'abs', '腹肌', '["髋屈肌","腹斜肌"]', 'Lie flat on your back with your hands behind your head and your knees bent. Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee. Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee. Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0972-tZkGYZ9.jpg', '/static/exercises/gifs/0972-tZkGYZ9.gif', '© Gym visual — https://gymvisual.com/', '80654'),
('100974', '弹力带窄距握下拉', '肱二头肌', '弹力带', '未分级', '将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。面向锚点站立，用反手抓住弹力带，双手与肩同宽。后退一步，在弹力带上产生张力，双脚分开与臀部同宽。当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0974', 'band close-grip pulldown', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam. Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart. Step back to create tension in the band, keeping your feet hip-width apart. Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0974-DptumMx.jpg', '/static/exercises/gifs/0974-DptumMx.gif', '© Gym visual — https://gymvisual.com/', '80655'),
('100975', '弹力带窄距握俯卧撑', '胸肌', '弹力带', '未分级', '将一条带子绕在你的上臂上，就在肘部上方。采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0975', 'band close-grip push-up', 'upper arms', '上臂', '50', 'band', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Place a band around your upper arms, just above the elbows. Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels. Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0975-ufaxB52.jpg', '/static/exercises/gifs/0975-ufaxB52.gif', '© Gym visual — https://gymvisual.com/', '900656'),
('100976', '弹力带集中弯举', '前臂', '弹力带', '未分级', '坐在长凳或椅子上，双腿分开，双脚平放在地上。用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。稍微向前倾，将肘部放在大腿内侧，膝盖上方。手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。在顶部暂停片刻，然后慢慢将手放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0976', 'band concentration curl', 'upper arms', '上臂', '50', 'band', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench or chair with your legs spread apart and your feet flat on the ground. Hold one end of the band in your hand and step on the other end with your foot on the same side. Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee. With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top, then slowly lower your hand back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0976-kmVVAfu.jpg', '/static/exercises/gifs/0976-kmVVAfu.gif', '© Gym visual — https://gymvisual.com/', '80657'),
('103117', '弹力带固定后侧窄距握下拉', '肱二头肌', '弹力带', '未分级', '将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。紧紧握住弹力带，手掌朝向您。保持背部挺直并启动核心肌群。将弹力带向下拉向胸部，将肩胛骨挤压在一起。在动作的底部暂停片刻，感受背阔肌的收缩。慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。重复所需的重复次数。', 'exercise-dataset', '3117', 'band fixed back close grip pulldown', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam. Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent. Grasp the band with a close grip, palms facing towards you. Keep your back straight and engage your core. Pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the band back to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/3117-4LoWllp.jpg', '/static/exercises/gifs/3117-4LoWllp.gif', '© Gym visual — https://gymvisual.com/', '80664'),
('103116', '弹力带固定后侧反握下拉', '肱二头肌', '弹力带', '未分级', '将带子固定在头顶上方坚固的锚点上。面向锚点站立，双脚分开与肩同宽。反手握住弹力带，双手间距略宽于肩宽。后退一步，在弹力带上产生张力，保持手臂完全伸展。启动你的核心并将肩胛骨挤压在一起。将弹力带向下拉向胸部，用肘部引导。在动作的底部暂停片刻，感受背阔肌的收缩。慢慢释放带子的张力并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3116', 'band fixed back underhand pulldown', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Attach the band to a sturdy anchor point above your head. Stand facing the anchor point with your feet shoulder-width apart. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart. Step back to create tension in the band, keeping your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull the band down towards your chest, leading with your elbows. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the tension in the band and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3116-ZH68exZ.jpg', '/static/exercises/gifs/3116-ZH68exZ.gif', '© Gym visual — https://gymvisual.com/', '80663'),
('100977', '弹力带前侧侧平举', '斜方肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。在顶部暂停片刻，然后慢慢将弹力带放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0977', 'band front lateral raise', 'shoulders', '肩部', '30', 'band', 'traps', 'delts', '三角肌', '["斜方肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down. Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the band back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0977-sTg7iys.jpg', '/static/exercises/gifs/0977-sTg7iys.gif', '© Gym visual — https://gymvisual.com/', '160662'),
('100978', '弹力带前侧上举', '肱三头肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。保持手臂伸直，慢慢向前举起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0978', 'band front raise', 'shoulders', '肩部', '30', 'band', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down. Keep your arms straight and slowly raise them forward until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0978-TFA88iB.jpg', '/static/exercises/gifs/0978-TFA88iB.gif', '© Gym visual — https://gymvisual.com/', '240661'),
('101408', '弹力带髋部抬举', '腘绳肌', '弹力带', '未分级', '仰卧，膝盖弯曲，双脚平放在地上。将阻力带放在膝盖上方。调动你的臀肌和核心肌肉。将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1408', 'band hip lift', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie on your back with your knees bent and feet flat on the ground. Place a resistance band just above your knees. Engage your glutes and core muscles. Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1408-E4R8Hz1.jpg', '/static/exercises/gifs/1408-E4R8Hz1.gif', '© Gym visual — https://gymvisual.com/', '900662'),
('100979', '弹力带水平帕洛夫抗旋推', '腹斜肌', '弹力带', '未分级', '将带子固定在腰部高度的坚固锚点上。垂直于锚点站立，双脚分开与肩同宽。用双手抓住带子手柄并远离锚点以在带子中产生张力。将双手放在胸前，保持肘部弯曲并靠近身体。调动你的核心并保持稳定的姿势。将手臂伸直至前方，将弹力带推离身体。保持伸展姿势几秒钟，专注于保持核心紧张。慢慢地将双手放回胸前，抵抗弹力带的拉力。重复所需的重复次数。', 'exercise-dataset', '0979', 'band horizontal pallof press', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌","臀肌"]', 'Attach the band to a sturdy anchor point at waist height. Stand perpendicular to the anchor point with your feet shoulder-width apart. Grasp the band handle with both hands and step away from the anchor point to create tension in the band. Bring your hands to your chest, keeping your elbows bent and close to your body. Engage your core and maintain a stable stance. Extend your arms straight out in front of you, pushing the band away from your body. Hold the extended position for a few seconds, focusing on maintaining tension in your core. Slowly bring your hands back to your chest, resisting the pull of the band. Repeat for the desired number of repetitions.', '/static/exercises/images/0979-9pa4H5m.jpg', '/static/exercises/gifs/0979-9pa4H5m.gif', '© Gym visual — https://gymvisual.com/', '900665'),
('100981', '弹力带折刀仰卧起坐', '髋屈肌', '弹力带', '未分级', '平躺，双腿伸直，手臂伸过头顶，握住弹力带。收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0981', 'band jack knife sit-up', 'waist', '腰腹', '60', 'band', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0981-KCBKjma.jpg', '/static/exercises/gifs/0981-KCBKjma.gif', '© Gym visual — https://gymvisual.com/', '160666'),
('100983', '弹力带跪姿单臂下拉', '肱二头肌', '弹力带', '未分级', '将带子固定在头顶上方坚固的锚点上。跪下，用一只手握住弹力带，手掌朝下。将手臂完全伸过头顶，保持肘部稍微弯曲。调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。在底部停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0983', 'band kneeling one arm pulldown', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌"]', 'Attach the band to a sturdy anchor point above your head. Kneel down and hold the band with one hand, palm facing down. Extend your arm fully overhead, keeping your elbow slightly bent. Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage. Pause for a moment at the bottom, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0983-pmnrOp0.jpg', '/static/exercises/gifs/0983-pmnrOp0.gif', '© Gym visual — https://gymvisual.com/', '80669'),
('100985', '弹力带跪姿转体卷腹', '腹斜肌', '弹力带', '未分级', '将带子固定在腰部高度的坚固锚点上。面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。暂停片刻，然后慢慢回到起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '0985', 'band kneeling twisting crunch', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach the band to a sturdy anchor point at waist height. Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides. Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip. Pause for a moment, then slowly return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0985-225x2Vd.jpg', '/static/exercises/gifs/0985-225x2Vd.gif', '© Gym visual — https://gymvisual.com/', '80668'),
('100984', '弹力带仰卧髋内旋', '腘绳肌', '弹力带', '未分级', '仰卧，双腿伸直，将阻力带绕在脚上。弯曲膝盖并将其靠近胸部，双脚并拢。慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。旋转结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0984', 'band lying hip internal rotation', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie on your back with your legs straight and a resistance band looped around your feet. Bend your knees and bring them towards your chest, keeping your feet together. Slowly rotate your knees outwards, away from each other, while keeping your feet together. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0984-vIICElP.jpg', '/static/exercises/gifs/0984-vIICElP.gif', '© Gym visual — https://gymvisual.com/', '900671'),
('101002', '弹力带仰卧直举腿', '髋屈肌', '弹力带', '未分级', '平躺，双腿伸直，双脚并拢。将带子放在脚弓周围，并用手握住带子的末端。收紧腹肌，将双腿抬离地面，直到它们垂直于地板。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1002', 'band lying straight leg raise', 'waist', '腰腹', '60', 'band', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs straight and your feet together. Place the band around the arches of your feet and hold the ends of the band with your hands. Engaging your abs, lift both legs off the ground until they are perpendicular to the floor. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1002-bbLR7fB.jpg', '/static/exercises/gifs/1002-bbLR7fB.gif', '© Gym visual — https://gymvisual.com/', '240672'),
('100986', '弹力带单臂过顶肱二头肌弯举', '前臂', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带的一端放在脚下。握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。在顶部停顿片刻，然后慢慢将前臂放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0986', 'band one arm overhead biceps curl', 'upper arms', '上臂', '50', 'band', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart and place one end of the band under your foot. Hold the other end of the band with your arm fully extended overhead, palm facing forward. Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps. Pause for a moment at the top, then slowly lower your forearm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0986-UNAB8ak.jpg', '/static/exercises/gifs/0986-UNAB8ak.gif', '© Gym visual — https://gymvisual.com/', '675'),
('100987', '弹力带单臂负重单腿分腿蹲', '臀肌', '弹力带', '未分级', '双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。向前伸出一条腿，将脚尖放在长凳上或身后的一步上。用一只手握住支撑物以保持平衡。弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。推动脚后跟返回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0987', 'band one arm single leg split squat', 'upper legs', '大腿', '40', 'band', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌"]', 'Stand with your feet hip-width apart and place a resistance band around your ankles. Extend one leg forward and rest the top of your foot on a bench or step behind you. Hold onto a support with one hand for balance. Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes. Push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0987-arsYEd3.jpg', '/static/exercises/gifs/0987-arsYEd3.gif', '© Gym visual — https://gymvisual.com/', '678'),
('100988', '弹力带单臂站姿低位划船', '肱二头肌', '弹力带', '未分级', '将带子固定在腰部高度的稳定锚点上。面向锚点站立，双脚分开与肩同宽。用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将带子拉向腰部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0988', 'band one arm standing low row', 'back', '背部', '20', 'band', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Attach the band to a stable anchor point at waist height. Stand facing the anchor point with your feet shoulder-width apart. Hold the band with one hand, palm facing inward, and step back to create tension in the band. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the band towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the band back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0988-km0sQC0.jpg', '/static/exercises/gifs/0988-km0sQC0.gif', '© Gym visual — https://gymvisual.com/', '900677'),
('100989', '弹力带单臂转体胸推', '肩部', '弹力带', '未分级', '将带子固定在胸部高度的坚固锚点上。站立，一侧面向锚点，用一只手抓住带子。远离锚点以在带子中产生张力。将双脚分开与肩同宽，并稍微弯曲膝盖。将握住弹力带的手穿过身体，朝向对侧的肩膀。在保持弹力带张力的同时，将手向前推离身体，伸展手臂。慢慢回到起始位置并重复所需的重复次数。换边并用另一只手重复练习。', 'exercise-dataset', '0989', 'band one arm twisting chest press', 'chest', '胸部', '10', 'band', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Attach the band to a sturdy anchor point at chest height. Stand with your side facing the anchor point and grab the band with one hand. Step away from the anchor point to create tension in the band. Position your feet shoulder-width apart and slightly bend your knees. Bring your hand holding the band across your body, towards the opposite shoulder. While maintaining tension in the band, push your hand forward and away from your body, extending your arm. Slowly return to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other hand.', '/static/exercises/images/0989-c16nYGA.jpg', '/static/exercises/gifs/0989-c16nYGA.gif', '© Gym visual — https://gymvisual.com/', '160678'),
('100990', '弹力带单臂转体坐姿划船', '肱二头肌', '弹力带', '未分级', '坐在长凳或椅子上，双脚平放在地上，背部挺直。用一只手握住弹力带，并将手臂完全伸到身前。保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。同时，将躯干向拉动手臂的一侧扭转。在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0990', 'band one arm twisting seated row', 'back', '背部', '20', 'band', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Sit on a bench or chair with your feet flat on the ground and your back straight. Hold the band with one hand and extend your arm fully in front of you. Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together. At the same time, twist your torso towards the side of the pulling arm. Pause for a moment at the top, then slowly release the tension in the band and return to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0990-DKBwJrL.jpg', '/static/exercises/gifs/0990-DKBwJrL.gif', '© Gym visual — https://gymvisual.com/', '240679'),
('100991', '弹力带绳索胯下拉', '腘绳肌', '弹力带', '未分级', '将阻力带连接到地面上坚固的锚点上。背对锚点站立，双脚与肩同宽。向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。铰接臀部并将臀部向后推，保持膝盖轻微弯曲。降低躯干直到与地面平行，感觉腿筋被拉伸。向前推动臀部并挤压臀部以返回起始位置。重复所需的重复次数。', 'exercise-dataset', '0991', 'band pull through', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Attach a resistance band to a sturdy anchor point at ground level. Stand facing away from the anchor point with your feet shoulder-width apart. Step forward to create tension in the band, keeping your knees slightly bent. Hinge at the hips and push your glutes back, maintaining a slight bend in your knees. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Drive your hips forward and squeeze your glutes to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0991-VtTbiP3.jpg', '/static/exercises/gifs/0991-VtTbiP3.gif', '© Gym visual — https://gymvisual.com/', '900674'),
('100992', '弹力带推坐向上', '肩部', '弹力带', '未分级', '将带子牢固地固定在稳定的锚点上。平躺，膝盖弯曲，双脚平放在地上。用双手握住弹力带，并将双臂伸向天花板。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0992', 'band push sit-up', 'waist', '腰腹', '60', 'band', 'shoulders', 'abs', '腹肌', '["肩部","胸肌"]', 'Attach the band securely to a stable anchor point. Lie flat on your back with your knees bent and feet flat on the ground. Hold the band with both hands and extend your arms straight up towards the ceiling. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0992-zFzbBfL.jpg', '/static/exercises/gifs/0992-zFzbBfL.gif', '© Gym visual — https://gymvisual.com/', '160675'),
('100993', '弹力带反向飞鸟', '上背部', '弹力带', '未分级', '将带子固定在胸部高度的固定物体上。双脚分开与肩同宽站立，双手握住弹力带放在身前。保持手臂伸直并将其向两侧抬起，直到与地面平行。在动作的最高点将肩胛骨挤压在一起。慢慢地将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0993', 'band reverse fly', 'shoulders', '肩部', '30', 'band', 'upper back', 'delts', '三角肌', '["上背部","斜方肌"]', 'Attach the band to a stationary object at chest height. Stand with your feet shoulder-width apart and hold the band with both hands in front of you. Keep your arms straight and lift them out to the sides until they are parallel to the ground. Squeeze your shoulder blades together at the top of the movement. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0993-sTfvVsG.jpg', '/static/exercises/gifs/0993-sTfvVsG.gif', '© Gym visual — https://gymvisual.com/', '320676'),
('100994', '弹力带反向腕弯举', '前臂', '弹力带', '未分级', '坐在长凳或椅子上，双脚平放在地面上。正手握住弹力带，手掌朝下，然后将其缠绕在手指上。将前臂放在大腿上，手腕悬在边缘上。慢慢向上弯曲手腕，挤压前臂。在顶部暂停片刻，然后慢慢将手腕放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0994', 'band reverse wrist curl', 'lower arms', '前臂', '80', 'band', 'forearms', 'forearms', '前臂肌群', '["前臂"]', 'Sit on a bench or chair with your feet flat on the ground. Hold the band with an overhand grip, palms facing down, and wrap it around your fingers. Rest your forearms on your thighs, with your wrists hanging off the edge. Slowly curl your wrists upward, squeezing your forearms. Pause for a moment at the top, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0994-Ezpnw9d.jpg', '/static/exercises/gifs/0994-Ezpnw9d.gif', '© Gym visual — https://gymvisual.com/', '679'),
('100996', '弹力带坐姿髋内旋', '腘绳肌', '弹力带', '未分级', '坐在椅子或长凳上，背部挺直，双脚平放在地面上。在大腿周围、膝盖上方放置一条阻力带。保持膝盖弯曲 90 度，双脚分开与肩同宽。收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0996', 'band seated hip internal rotation', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Sit on a chair or bench with your back straight and feet flat on the ground. Place a resistance band around your thighs, just above your knees. Keep your knees bent at a 90-degree angle and your feet shoulder-width apart. Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0996-9gbyYKk.jpg', '/static/exercises/gifs/0996-9gbyYKk.gif', '© Gym visual — https://gymvisual.com/', '900682'),
('101011', '弹力带坐姿转体', '腹斜肌', '弹力带', '未分级', '坐在地上，双腿向前伸展，背部挺直。将带子绕在腰上，并用双手握住两端。收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。扭转结束时暂停片刻，然后慢慢回到起始位置。重复扭转到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '1011', 'band seated twist', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on the ground with your legs extended in front of you and your back straight. Wrap the band around your waist and hold the ends with both hands. Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1011-S1JXDAG.jpg', '/static/exercises/gifs/1011-S1JXDAG.gif', '© Gym visual — https://gymvisual.com/', '900679'),
('100997', '弹力带肩上推举', '肱三头肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在脚下。手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。将弹力带压过头顶，充分伸展双臂。在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。重复所需的重复次数。', 'exercise-dataset', '0997', 'band shoulder press', 'shoulders', '肩部', '30', 'band', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent. Press the band overhead, fully extending your arms. Pause for a moment at the top, then slowly lower the band back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0997-peAeMR3.jpg', '/static/exercises/gifs/0997-peAeMR3.gif', '© Gym visual — https://gymvisual.com/', '680'),
('101018', '弹力带耸肩', '肩部', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。保持手臂伸直并放松，让弹力带悬挂在大腿前面。向上耸肩，尽可能高地举起弹力带，以启动斜方肌。保持收缩一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1018', 'band shrug', 'back', '背部', '20', 'band', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands. Keep your arms straight and relaxed, and let the band hang in front of your thighs. Engage your traps by shrugging your shoulders upward, lifting the band as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1018-trmte8s.jpg', '/static/exercises/gifs/1018-trmte8s.gif', '© Gym visual — https://gymvisual.com/', '560679'),
('100998', '弹力带侧向肱三头肌臂屈伸', '肩部', '弹力带', '未分级', '双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。将手臂伸直至两侧，保持与地面平行。慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。暂停片刻，然后慢慢将手臂伸回起始位置。重复所需的重复次数。', 'exercise-dataset', '0998', 'band side triceps extension', 'upper arms', '上臂', '50', 'band', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down. Extend your arms straight out to the sides, keeping them parallel to the ground. Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still. Pause for a moment, then slowly extend your arms back out to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0998-obe5LMq.jpg', '/static/exercises/gifs/0998-obe5LMq.gif', '© Gym visual — https://gymvisual.com/', '400684'),
('100999', '弹力带单侧腿提踵', '踝部肌群', '弹力带', '未分级', '双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。如果需要，请抓住一个稳定的物体以保持平衡。慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。重复所需的重复次数，然后换右腿。', 'exercise-dataset', '0999', 'band single leg calf raise', 'lower legs', '小腿', '70', 'band', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand with your feet hip-width apart and place the band around the ball of your left foot. Hold onto a stable object for balance if needed. Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot. Pause for a moment at the top, then slowly lower your left heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the right leg.', '/static/exercises/images/0999-9JprnPh.jpg', '/static/exercises/gifs/0999-9JprnPh.gif', '© Gym visual — https://gymvisual.com/', '687'),
('101000', '弹力带单侧腿反向提踵', '腘绳肌', '弹力带', '未分级', '双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。抓住稳定的物体以保持平衡。慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换另一条腿。', 'exercise-dataset', '1000', 'band single leg reverse calf raise', 'lower legs', '小腿', '70', 'band', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your feet hip-width apart and place the band around the ball of your foot. Hold onto a stable object for balance. Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the other leg.', '/static/exercises/images/1000-QsSQWbf.jpg', '/static/exercises/gifs/1000-QsSQWbf.gif', '© Gym visual — https://gymvisual.com/', '690'),
('101001', '弹力带单侧腿分腿蹲', '臀肌', '弹力带', '未分级', '双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。右脚向前迈一大步，左脚向后退一小步。弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。推动右脚跟回到起始位置。在另一侧重复。', 'exercise-dataset', '1001', 'band single leg split squat', 'upper legs', '大腿', '40', 'band', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌"]', 'Stand with your feet hip-width apart and place a resistance band around your ankles. Take a big step forward with your right foot and a smaller step back with your left foot. Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground. Push through your right heel to return to the starting position. Repeat on the other side.', '/static/exercises/images/1001-y8bYM8w.jpg', '/static/exercises/gifs/1001-y8bYM8w.gif', '© Gym visual — https://gymvisual.com/', '689'),
('101004', '弹力带深蹲', '股四头肌', '弹力带', '未分级', '双脚分开站立，与肩同宽，弹力带放在膝盖上方。保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。确保膝盖位于脚趾上方，并且重量位于脚后跟。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1004', 'band squat', 'upper legs', '大腿', '40', 'band', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, with the band placed just above your knees. Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position. Make sure your knees are tracking over your toes and your weight is in your heels. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1004-TUZLh71.jpg', '/static/exercises/gifs/1004-TUZLh71.gif', '© Gym visual — https://gymvisual.com/', '684'),
('101003', '弹力带深蹲划船', '腘绳肌', '弹力带', '未分级', '将带子固定在腰部高度的坚固锚点上。面向锚点站立，双脚分开与肩同宽。双手握住弹力带手柄，手掌相对，双臂向前伸展。弯曲膝盖并蹲下，保持背部挺直，挺胸。从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。在最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1003', 'band squat row', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","后侧"]', 'Attach the band to a sturdy anchor point at waist height. Stand facing the anchor point with your feet shoulder-width apart. Hold the band handles with your palms facing each other and your arms extended in front of you. Bend your knees and lower into a squat position, keeping your back straight and chest lifted. From the squat position, pull the band handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1003-w1NOByi.jpg', '/static/exercises/gifs/1003-w1NOByi.gif', '© Gym visual — https://gymvisual.com/', '687'),
('101005', '弹力带站姿卷腹', '腹斜肌', '弹力带', '未分级', '将带子固定在腰部高度的坚固锚点上。背对锚点站立，双脚与肩同宽。用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。在卷腹的最高点暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1005', 'band standing crunch', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach the band to a sturdy anchor point at waist height. Stand facing away from the anchor point with your feet shoulder-width apart. Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body. Engage your abs and slowly crunch forward, bringing your chest towards your knees. Pause for a moment at the top of the crunch, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1005-Kzg30R7.jpg', '/static/exercises/gifs/1005-Kzg30R7.gif', '© Gym visual — https://gymvisual.com/', '80688'),
('101022', '弹力带站姿三角肌后束划船', '斜方肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在脚下。双手握住弹力带手柄，手掌相对，双臂向前伸展。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将弹力带拉向胸部，将肩胛骨挤压在一起。在最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1022', 'band standing rear delt row', 'shoulders', '肩部', '30', 'band', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band handles with your palms facing each other and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the band towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1022-tc5dYrf.jpg', '/static/exercises/gifs/1022-tc5dYrf.gif', '© Gym visual — https://gymvisual.com/', '400693'),
('101007', '弹力带站姿转体卷腹', '腹斜肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。用手握住带子的末端，保持肘部弯曲并靠近身体两侧。收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。暂停片刻，然后回到起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '1007', 'band standing twisting crunch', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest. Hold the ends of the band with your hands, keeping your elbows bent and close to your sides. Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee. Pause for a moment, then return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1007-euq4pwp.jpg', '/static/exercises/gifs/1007-euq4pwp.gif', '© Gym visual — https://gymvisual.com/', '80692'),
('101008', '弹力带踏步向上', '股四头肌', '弹力带', '未分级', '将一条带子绕在大腿上，就在膝盖上方。面向台阶或平台站立，双脚分开与臀部同宽。用右脚踩上平台，用脚后跟推动。将左腿伸到身后，保持伸直。将左脚放回地面。重复左脚踩上平台的动作。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '1008', 'band step-up', 'upper legs', '大腿', '40', 'band', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Place a band around your thighs, just above your knees. Stand facing a step or platform with your feet hip-width apart. Step up onto the platform with your right foot, pushing through your heel. Extend your left leg behind you, keeping it straight. Lower your left foot back down to the ground. Repeat with your left foot stepping up onto the platform. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/1008-d5bTEPV.jpg', '/static/exercises/gifs/1008-d5bTEPV.gif', '© Gym visual — https://gymvisual.com/', '900689'),
('101009', '弹力带直腿硬拉', '腘绳肌', '弹力带', '未分级', '双脚分开站立，与肩同宽，将弹力带绕在脚踝上。用双手将弹力带放在大腿前面，手掌朝向身体。保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。当你降低时，将臀部向后推，并让膝盖稍微弯曲。将弹力带降低至地面，感受腿筋的拉伸。在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1009', 'band stiff leg deadlift', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart and place the band around your ankles. Hold the band with both hands in front of your thighs, palms facing your body. Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground. As you lower, push your hips back and allow your knees to bend slightly. Lower the band towards the ground, feeling a stretch in your hamstrings. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1009-kuMiR2T.jpg', '/static/exercises/gifs/1009-kuMiR2T.gif', '© Gym visual — https://gymvisual.com/', '80694'),
('101023', '弹力带直背直腿硬拉', '腘绳肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带绕在大腿上。用双手将弹力带放在大腿前面，手掌朝向身体。保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。当你降低弹力带时，感受腿筋的拉伸。启动臀肌和腿筋，将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1023', 'band straight back stiff leg deadlift', 'upper legs', '大腿', '40', 'band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart and place the band around your upper legs. Hold the band with both hands in front of your thighs, palms facing your body. Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground. Feel the stretch in your hamstrings as you lower the band. Engage your glutes and hamstrings to lift your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1023-lHeUULr.jpg', '/static/exercises/gifs/1023-lHeUULr.gif', '© Gym visual — https://gymvisual.com/', '80699'),
('101010', '弹力带直腿硬拉', '腘绳肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带绕在脚上。双手握住弹力带，手掌朝向身体，手臂伸直。收紧核心并保持膝盖轻微弯曲。慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。将弹力带降低至地面，同时保持双腿伸直。在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1010', 'band straight leg deadlift', 'back', '背部', '20', 'band', 'hamstrings', 'spine', '竖脊肌', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart and place the band around your feet. Hold the band with both hands, palms facing your body, and keep your arms straight. Engage your core and maintain a slight bend in your knees. Slowly hinge forward at your hips, keeping your back straight and chest lifted. Lower the band towards the ground while keeping your legs straight. Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1010-KUaoUV8.jpg', '/static/exercises/gifs/1010-KUaoUV8.gif', '© Gym visual — https://gymvisual.com/', '900696'),
('101012', '弹力带转体过顶推举', '肱三头肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在脚下。将弹力带手柄保持在与肩同高的位置，手掌朝前。启动你的核心并将弹力带压过头顶，充分伸展你的手臂。当你按压时，将你的躯干扭转到一侧，保持臀部稳定。在顶部暂停片刻，然后回到起始位置。在另一侧重复按压和扭转。继续交替进行所需的重复次数。', 'exercise-dataset', '1012', 'band twisting overhead press', 'shoulders', '肩部', '30', 'band', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and place the band under your feet. Hold the band handles at shoulder height with your palms facing forward. Engage your core and press the band overhead, fully extending your arms. As you press, twist your torso to one side, keeping your hips stable. Pause for a moment at the top, then return to the starting position. Repeat the press and twist on the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1012-u4bAmKp.jpg', '/static/exercises/gifs/1012-u4bAmKp.gif', '© Gym visual — https://gymvisual.com/', '80697'),
('101369', '弹力带双双腿提踵弹力带下方双侧双腿版本第二式', '踝部肌群', '弹力带', '未分级', '双脚分开与肩同宽站立，并将阻力带放在双脚下方。用手握住带子的末端以保持稳定。用小腿将脚跟抬离地面，尽可能高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1369', 'band two legs calf raise - (band under both legs) v. 2', 'lower legs', '小腿', '70', 'band', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand with your feet shoulder-width apart and place a resistance band under both feet. Hold the ends of the band with your hands for stability. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1369-jl6uxZV.jpg', '/static/exercises/gifs/1369-jl6uxZV.gif', '© Gym visual — https://gymvisual.com/', '714'),
('101013', '弹力带反握下拉', '肱二头肌', '弹力带', '未分级', '将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。面向锚点站立，双脚分开与肩同宽。反手握住弹力带，双手间距略宽于肩宽。将手臂完全伸过头顶，保持肘部稍微弯曲。收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1013', 'band underhand pulldown', 'back', '背部', '20', 'band', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam. Stand facing the anchor point with your feet shoulder-width apart. Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart. Extend your arms fully overhead, keeping your elbows slightly bent. Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1013-k6tUeqS.jpg', '/static/exercises/gifs/1013-k6tUeqS.gif', '© Gym visual — https://gymvisual.com/', '80697'),
('101014', '弹力带V字卷腹', '髋屈肌', '弹力带', '未分级', '平躺，双腿伸直，手臂伸过头顶，握住弹力带。收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1014', 'band v-up', 'waist', '腰腹', '60', 'band', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band. Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1014-H6ETwO9.jpg', '/static/exercises/gifs/1014-H6ETwO9.gif', '© Gym visual — https://gymvisual.com/', '480696'),
('101015', '弹力带垂直帕洛夫抗旋推', '腹斜肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。用双手握住弹力带并远离锚点，在弹力带中产生张力。使自己垂直于锚点，一侧面向弹力带。将双臂伸直在身前，保持双手与胸同高。收紧核心肌群，将弹力带压离胸部，充分伸展手臂。保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。重复所需的重复次数，然后换边。', 'exercise-dataset', '1015', 'band vertical pallof press', 'waist', '腰腹', '60', 'band', 'obliques', 'abs', '腹肌', '["腹斜肌","臀肌"]', 'Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height. Hold the band with both hands and step away from the anchor point, creating tension in the band. Position yourself perpendicular to the anchor point, with your side facing the band. Extend your arms straight out in front of you, keeping your hands at chest height. Engage your core and press the band away from your chest, fully extending your arms. Hold the position for a few seconds, then slowly bring the band back towards your chest. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1015-G7PXMlT.jpg', '/static/exercises/gifs/1015-G7PXMlT.gif', '© Gym visual — https://gymvisual.com/', '900701'),
('101016', '弹力带腕弯举', '肱二头肌', '弹力带', '未分级', '坐在长凳或椅子上，双脚平放在地面上。双手握住弹力带，手掌朝上，前臂放在大腿上。慢慢向上弯曲手腕，挤压前臂。在顶部暂停片刻，然后慢慢将手腕放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1016', 'band wrist curl', 'lower arms', '前臂', '80', 'band', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Sit on a bench or chair with your feet flat on the ground. Hold the band with both hands, palms facing up, and rest your forearms on your thighs. Slowly curl your wrists upward, squeezing your forearms. Pause for a moment at the top, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1016-vUTfFHw.jpg', '/static/exercises/gifs/1016-vUTfFHw.gif', '© Gym visual — https://gymvisual.com/', '700'),
('101017', '弹力带Y字上举', '斜方肌', '弹力带', '未分级', '双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。在动作的最高点将肩胛骨挤压在一起。慢慢地将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1017', 'band y-raise', 'shoulders', '肩部', '30', 'band', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards. Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1017-aHDy5O5.jpg', '/static/exercises/gifs/1017-aHDy5O5.gif', '© Gym visual — https://gymvisual.com/', '900699'),
('100023', '杠铃交替肱二头肌弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢开始将杠铃放回起始位置。重复所需的重复次数，交替手臂。', 'exercise-dataset', '0023', 'barbell alternate biceps curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to lower the barbells back to the starting position. Repeat for the desired number of repetitions, alternating arms.', '/static/exercises/images/0023-Yza7XrQ.jpg', '/static/exercises/gifs/0023-Yza7XrQ.gif', '© Gym visual — https://gymvisual.com/', '204'),
('100024', '杠铃训练凳前蹲', '腘绳肌', '杠铃', '未分级', '首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。正手握住杠铃，保持肘部向上，上臂与地面平行。弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '0024', 'barbell bench front squat', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone. Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground. Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0024-Y7YcmIJ.jpg', '/static/exercises/gifs/0024-Y7YcmIJ.gif', '© Gym visual — https://gymvisual.com/', '205'),
('100025', '杠铃卧推', '肱三头肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。将杠铃慢慢降低到胸部，保持肘部内收。当杠铃触及胸部时暂停片刻。伸展双臂，将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0025', 'barbell bench press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0025-EIeI8Vf.jpg', '/static/exercises/gifs/0025-EIeI8Vf.gif', '© Gym visual — https://gymvisual.com/', '204'),
('100026', '杠铃训练凳深蹲', '臀肌', '杠铃', '未分级', '将杠铃放在深蹲架上，与胸部同高。背对架子站立，双脚与肩同宽。弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。降低身体蹲下，保持膝盖与脚趾在一条线上。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0026', 'barbell bench squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Set up a barbell on a squat rack at chest height. Stand facing away from the rack, with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart. Lower your body down into a squat, keeping your knees in line with your toes. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0026-W9pFVv1.jpg', '/static/exercises/gifs/0026-W9pFVv1.gif', '© Gym visual — https://gymvisual.com/', '205'),
('101316', '杠铃屈臂上拉', '肱三头肌', '杠铃', '未分级', '平躺在长凳上，头放在一端，双脚放在地板上。握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。将杠铃放在脑后，同时保持手臂稍微弯曲。暂停片刻，然后将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '1316', 'barbell bent arm pullover', 'back', '背部', '20', 'barbell', 'triceps', 'lats', '背阔肌', '["肱三头肌","胸肌"]', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Lower the barbell behind your head while keeping your arms slightly bent. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1316-cA9FuWG.jpg', '/static/exercises/gifs/1316-cA9FuWG.gif', '© Gym visual — https://gymvisual.com/', '900208'),
('100027', '杠铃俯身划船', '肱二头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。臀部向前弯曲，同时保持背部挺直、挺胸。正手握住杠铃，双手间距略宽于肩宽。通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0027', 'barbell bent over row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the hips while keeping your back straight and chest up. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0027-eZyBC3j.jpg', '/static/exercises/gifs/0027-eZyBC3j.gif', '© Gym visual — https://gymvisual.com/', '160209'),
('102407', '杠铃肱二头肌弯举臂弯举托板', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。将上臂靠在手臂冲击波上，保持肘部靠近躯干。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2407', 'barbell biceps curl (with arm blaster)', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping your elbows close to your torso. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2407-aee2Fcj.jpg', '/static/exercises/gifs/2407-aee2Fcj.gif', '© Gym visual — https://gymvisual.com/', '214'),
('100028', '杠铃翻举推举', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，杠铃放在你面前的地板上。弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。将杠铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0028', 'barbell clean and press', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌","肩部","肱三头肌"]', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you. Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body. As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest. As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up. From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0028-SGY8Zui.jpg', '/static/exercises/gifs/0028-SGY8Zui.gif', '© Gym visual — https://gymvisual.com/', '900211'),
('100029', '杠铃翻举握前蹲', '股四头肌', '杠铃', '未分级', '首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '0029', 'barbell clean-grip front squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward. Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair. Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/0029-qi996YS.jpg', '/static/exercises/gifs/0029-qi996YS.gif', '© Gym visual — https://gymvisual.com/', '212'),
('100030', '杠铃窄握卧推', '胸肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。紧紧握住杠铃，握距略窄于肩宽。松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0030', 'barbell close-grip bench press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0030-J6Dx1Mu.jpg', '/static/exercises/gifs/0030-J6Dx1Mu.gif', '© Gym visual — https://gymvisual.com/', '900213'),
('100031', '杠铃弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0031', 'barbell curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to lower the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0031-25GPyDY.jpg', '/static/exercises/gifs/0031-25GPyDY.gif', '© Gym visual — https://gymvisual.com/', '80210'),
('100032', '杠铃硬拉', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，杠铃放在你面前的地面上。弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。当你站直时，挤压你的臀部并保持你的核心参与。弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。重复所需的重复次数。', 'exercise-dataset', '0032', 'barbell deadlift', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart and the barbell on the ground in front of you. Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees. As you stand up straight, squeeze your glutes and keep your core engaged. Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight. Repeat for the desired number of repetitions.', '/static/exercises/images/0032-ila4NZS.jpg', '/static/exercises/gifs/0032-ila4NZS.gif', '© Gym visual — https://gymvisual.com/', '80211'),
('100033', '杠铃下斜卧推', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。正手握住杠铃，握距略宽于肩宽。松开杠铃，慢慢将其降低到胸部，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0033', 'barbell decline bench press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0033-GrO65fd.jpg', '/static/exercises/gifs/0033-GrO65fd.gif', '© Gym visual — https://gymvisual.com/', '216'),
('100034', '杠铃下斜屈臂上拉', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，头部低于臀部，双脚固定。旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。有控制地将杠铃降低到头后，保持手臂稍微弯曲。暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0034', 'barbell decline bent arm pullover', 'back', '背部', '20', 'barbell', 'triceps', 'lats', '背阔肌', '["肱三头肌","胸肌"]', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent. Pause for a moment, then raise the barbell back to the starting position by contracting your lats. Repeat for the desired number of repetitions.', '/static/exercises/images/0034-hMEptv0.jpg', '/static/exercises/gifs/0034-hMEptv0.gif', '© Gym visual — https://gymvisual.com/', '900219'),
('100035', '杠铃下斜窄握仰卧臂屈伸', '胸肌', '杠铃', '未分级', '躺在下斜长凳上，头低于脚，紧紧握住杠铃。弯曲肘部，将杠铃向前额降低，保持上臂静止。暂停片刻，然后伸展双臂将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0035', 'barbell decline close grip to skull press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip. Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms to press the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0035-LMGXZn8.jpg', '/static/exercises/gifs/0035-LMGXZn8.gif', '© Gym visual — https://gymvisual.com/', '900224'),
('101255', '杠铃下斜上拉', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，头部低于臀部，双脚固定。旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。将手臂伸至胸部上方，保持肘部轻微弯曲。以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。暂停片刻，然后反向动作将杠铃恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '1255', 'barbell decline pullover', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie down on a decline bench with your head lower than your hips and your feet secured. Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart. Extend your arms above your chest, keeping a slight bend in your elbows. Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders. Pause for a moment, then return the barbell to the starting position by reversing the motion. Repeat for the desired number of repetitions.', '/static/exercises/images/1255-9sgNE2O.jpg', '/static/exercises/gifs/1255-9sgNE2O.gif', '© Gym visual — https://gymvisual.com/', '400217'),
('100036', '杠铃下斜宽距握推举', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。宽握距抓住杠铃，握距略宽于肩宽。将杠铃降低到胸部，保持肘部向两侧伸出。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0036', 'barbell decline wide-grip press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows out to the sides. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0036-hl8DUh8.jpg', '/static/exercises/gifs/0036-hl8DUh8.gif', '© Gym visual — https://gymvisual.com/', '900220'),
('100037', '杠铃下斜宽距握上拉', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，头部低于臀部，双脚固定。宽握距握住杠铃，并将双臂伸直至胸部上方。有控制地将杠铃降低到头后，保持手臂伸直。暂停片刻，然后将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0037', 'barbell decline wide-grip pullover', 'back', '背部', '20', 'barbell', 'triceps', 'lats', '背阔肌', '["肱三头肌","胸肌"]', 'Lie on a decline bench with your head lower than your hips and your feet secured. Hold a barbell with a wide grip and extend your arms straight above your chest. Lower the barbell behind your head in a controlled manner, keeping your arms straight. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0037-Hj4FOCd.jpg', '/static/exercises/gifs/0037-Hj4FOCd.gif', '© Gym visual — https://gymvisual.com/', '900221'),
('100038', '杠铃拖拽式弯举', '前臂', '杠铃', '未分级', '双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。让杠铃悬挂在大腿前面，与手臂保持一定距离。保持上臂静止，通过收缩二头肌将杠铃向上卷曲至胸部。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0038', 'barbell drag curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Let the barbell hang at arm''s length in front of your thighs. Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0038-IENzBdA.jpg', '/static/exercises/gifs/0038-IENzBdA.gif', '© Gym visual — https://gymvisual.com/', '80220'),
('101370', '杠铃地板提踵', '腘绳肌', '杠铃', '未分级', '将杠铃放在您面前的地板上。站立，脚掌放在杠铃边缘，脚跟悬垂。如果需要，请抓住一个稳定的物体以保持平衡。尽可能高地抬高脚后跟，用小腿来抬起身体。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1370', 'barbell floor calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Place a barbell on the floor in front of you. Stand with the balls of your feet on the edge of the barbell, with your heels hanging off. Hold onto a stable object for balance if needed. Raise your heels as high as possible, using your calves to lift your body. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1370-2IHEa2T.jpg', '/static/exercises/gifs/1370-2IHEa2T.gif', '© Gym visual — https://gymvisual.com/', '223'),
('100039', '杠铃前侧胸部深蹲', '股四头肌', '杠铃', '未分级', '首先站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在胸前，双手与肩同宽，肘部向前。当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0039', 'barbell front chest squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0039-IeTIEqg.jpg', '/static/exercises/gifs/0039-IeTIEqg.gif', '© Gym visual — https://gymvisual.com/', '224'),
('100041', '杠铃前侧上举', '肱二头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃于大腿前方。保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0041', 'barbell front raise', 'shoulders', '肩部', '30', 'barbell', 'biceps', 'delts', '三角肌', '["肱二头肌","肱三头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0041-b2Uoz54.jpg', '/static/exercises/gifs/0041-b2Uoz54.gif', '© Gym visual — https://gymvisual.com/', '240223'),
('100040', '杠铃前侧上举上拉', '三角肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。保持双臂伸直，将杠铃举至身前，直至达到肩膀高度。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。接下来，将杠铃放低到头后，保持手臂伸直。在底部停顿片刻，然后将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0040', 'barbell front raise and pullover', 'chest', '胸部', '10', 'barbell', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your arms straight and raise the barbell in front of you until it reaches shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Next, lower the barbell behind your head, keeping your arms straight. Pause for a moment at the bottom, then raise the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0040-33AzZeV.jpg', '/static/exercises/gifs/0040-33AzZeV.gif', '© Gym visual — https://gymvisual.com/', '400228'),
('100042', '杠铃前蹲', '股四头肌', '杠铃', '未分级', '首先站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在肩膀前面，将其放在锁骨和肩膀上。当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0042', 'barbell front squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Start by standing with your feet shoulder-width apart, toes slightly turned out. Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0042-zG0zs85.jpg', '/static/exercises/gifs/0042-zG0zs85.gif', '© Gym visual — https://gymvisual.com/', '225'),
('100043', '杠铃深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。当你开始降低身体时，启动你的核心并保持胸部挺直。弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。放低身体，直到大腿与地面平行或稍低于地面。保持膝盖与脚趾对齐，并将重量放在脚后跟上。通过脚后跟站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '0043', 'barbell full squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower yourself until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/0043-qXTaZnJ.jpg', '/static/exercises/gifs/0043-qXTaZnJ.gif', '© Gym visual — https://gymvisual.com/', '226'),
('101461', '杠铃全程深蹲后侧视角', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。当你开始降低身体时，启动你的核心并保持胸部挺直。弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。降低身体，直到大腿与地面平行或稍低于地面。保持膝盖与脚趾对齐，并将重量放在脚后跟上。通过脚后跟站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '1461', 'barbell full squat (back pov)', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower your body until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/1461-DhMl549.jpg', '/static/exercises/gifs/1461-DhMl549.gif', '© Gym visual — https://gymvisual.com/', '231'),
('101462', '杠铃全程深蹲侧向视角', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。当你开始降低身体时，启动你的核心并保持胸部挺直。弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。降低身体，直到大腿与地面平行或稍低于地面。保持膝盖与脚趾对齐，并将重量放在脚后跟上。通过脚后跟站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '1462', 'barbell full squat (side pov)', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you begin to lower your body down. Bend at the knees and hips, pushing your hips back and down as if sitting into a chair. Lower your body until your thighs are parallel to the ground or slightly below. Keep your knees in line with your toes and your weight in your heels. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/1462-iYzB0Cz.jpg', '/static/exercises/gifs/1462-iYzB0Cz.gif', '© Gym visual — https://gymvisual.com/', '232'),
('101545', '杠铃全程泽奇深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。保持膝盖与脚趾对齐，并将重量放在脚后跟上。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。通过脚跟发力站起来，在动作的最高点挤压臀部。重复所需的重复次数。', 'exercise-dataset', '1545', 'barbell full zercher squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position. Keep your knees in line with your toes and your weight in your heels. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top of the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/1545-vR1vold.jpg', '/static/exercises/gifs/1545-vR1vold.gif', '© Gym visual — https://gymvisual.com/', '231'),
('101409', '杠铃臀桥', '腘绳肌', '杠铃', '未分级', '首先平躺在地上，膝盖弯曲，双脚平放在地板上。将杠铃放在臀部上，用双手牢牢握住它。锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，挤压臀部。慢慢地将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1409', 'barbell glute bridge', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Start by lying flat on your back on the ground with your knees bent and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1409-qKBpF7I.jpg', '/static/exercises/gifs/1409-qKBpF7I.gif', '© Gym visual — https://gymvisual.com/', '640230'),
('103562', '杠铃臀桥双双腿训练凳（男）', '腘绳肌', '杠铃', '未分级', '首先坐在长凳边缘，上背部靠在长凳上，双脚平放在地面上，与臀部同宽。将杠铃放在臀部上，用双手牢牢握住它。锻炼臀肌和核心肌肉，然后用脚后跟将臀部抬离长凳，形成从膝盖到肩膀的一条直线。在顶部暂停片刻，挤压臀部。慢慢地将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3562', 'barbell glute bridge two legs on bench (male)', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","核心肌群"]', 'Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart. Place a barbell across your hips, holding it securely with both hands. Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3562-qg2PGl6.jpg', '/static/exercises/gifs/3562-qg2PGl6.gif', '© Gym visual — https://gymvisual.com/', '640241'),
('100044', '杠铃早安式', '下背部', '杠铃', '未分级', '首先站立，双脚分开与肩同宽，将杠铃放在上背部。保持背部挺直，核心肌群参与，臀部向前转动，将臀部向后推，就好像你试图用臀部触碰身后的墙壁一样。降低躯干直到与地面平行，感觉腿筋被拉伸。暂停片刻，然后通过挤压臀部并将臀部向前推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0044', 'barbell good morning', 'upper legs', '大腿', '40', 'barbell', 'lower back', 'hamstrings', '腘绳肌', '["下背部"]', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward. Repeat for the desired number of repetitions.', '/static/exercises/images/0044-XlZ4lAC.jpg', '/static/exercises/gifs/0044-XlZ4lAC.gif', '© Gym visual — https://gymvisual.com/', '900232'),
('100045', '杠铃断头台式卧推', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。正手握住杠铃，握距略宽于肩宽。慢慢地将杠铃降低到颈部，保持肘部朝外。当杠铃位于颈部上方时，暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0045', 'barbell guillotine bench press', 'chest', '胸部', '10', 'barbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell slowly towards your neck, keeping your elbows pointed outwards. Pause for a moment when the barbell is just above your neck. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0045-GXoaSgn.jpg', '/static/exercises/gifs/0045-GXoaSgn.gif', '© Gym visual — https://gymvisual.com/', '235'),
('100046', '杠铃哈克深蹲', '股四头肌', '杠铃', '未分级', '首先站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在腿后面，将其放在大腿上部。弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。继续降低，直到大腿与地面平行，或者尽可能低。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0046', 'barbell hack squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart and your toes slightly turned out. Hold the barbell behind your legs, resting it on your upper thighs. Lower your body by bending at the knees and hips, keeping your back straight and your chest up. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0046-5VCj6iH.jpg', '/static/exercises/gifs/0046-5VCj6iH.gif', '© Gym visual — https://gymvisual.com/', '234'),
('101436', '杠铃高位杆深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，放在斜方肌上。当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。通过脚后跟站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '1436', 'barbell high bar squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell on your upper back, resting it on your traps. Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/1436-Gnfo4FM.jpg', '/static/exercises/gifs/1436-Gnfo4FM.gif', '© Gym visual — https://gymvisual.com/', '237'),
('100047', '上斜杠铃卧推', '肩部', '杠铃', '未分级', '设置一个 45 度角的上斜凳。躺在长凳上，双脚平放在地上。正手握住杠铃，握距略宽于肩宽。松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0047', 'barbell incline bench press', 'chest', '胸部', '10', 'barbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0047-3TZduzM.jpg', '/static/exercises/gifs/0047-3TZduzM.gif', '© Gym visual — https://gymvisual.com/', '238'),
('101719', '杠铃上斜窄握卧推', '胸肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。躺在长凳上，双脚平放在地上。紧紧握住杠铃，握距略窄于肩宽。松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1719', 'barbell incline close grip bench press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1719-gx7s7uF.jpg', '/static/exercises/gifs/1719-gx7s7uF.gif', '© Gym visual — https://gymvisual.com/', '900243'),
('100048', '杠铃上斜反向握推举', '胸肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。松开杠铃并将其向上胸部降低，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0048', 'barbell incline reverse-grip press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0048-641mIfk.jpg', '/static/exercises/gifs/0048-641mIfk.gif', '© Gym visual — https://gymvisual.com/', '900240'),
('100049', '杠铃上斜划船', '肱二头肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。正手握住杠铃，握距略宽于肩宽。保持背部挺直，核心肌群参与。将杠铃拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0049', 'barbell incline row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest against the pad and your feet flat on the ground. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the barbell towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0049-dmgMp3n.jpg', '/static/exercises/gifs/0049-dmgMp3n.gif', '© Gym visual — https://gymvisual.com/', '900239'),
('100050', '杠铃上斜肩部上举', '三角肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，背部靠在垫子上，双脚平放在地面上。正手握住杠铃，杠铃间距略宽于肩宽。将杠铃举至肩膀高度，保持肘部稍微弯曲。慢慢地将杠铃举过头顶，充分伸展双臂。在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。重复所需的重复次数。', 'exercise-dataset', '0050', 'barbell incline shoulder raise', 'chest', '胸部', '10', 'barbell', 'deltoids', 'serratus anterior', '前锯肌', '["三角肌","斜方肌"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell up to shoulder height, keeping your elbows slightly bent. Slowly raise the barbell overhead, extending your arms fully. Pause for a moment at the top, then slowly lower the barbell back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0050-xi0yckC.jpg', '/static/exercises/gifs/0050-xi0yckC.gif', '© Gym visual — https://gymvisual.com/', '900242'),
('100051', '杠铃杰斐逊深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。正手握住杠铃，将其放在身体前部、腰部下方。左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。脚后跟用力，站回起始位置。重复该动作，每次重复时交替使用前脚和后脚。', 'exercise-dataset', '0051', 'barbell jefferson squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist. Step your left foot forward and your right foot back, keeping your feet shoulder-width apart. Bend your knees and lower your body down into a squat position, keeping your back straight and chest up. Push through your heels to stand back up to the starting position. Repeat the movement, alternating your forward and back foot with each repetition.', '/static/exercises/images/0051-pkSoCW9.jpg', '/static/exercises/gifs/0051-pkSoCW9.gif', '© Gym visual — https://gymvisual.com/', '241'),
('100052', '杠铃JM卧推', '胸肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。正手握住杠铃，握距略宽于肩宽。将杠铃降低到胸部，保持肘部靠近身体。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0052', 'barbell jm bench press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0052-ZsiqXYa.jpg', '/static/exercises/gifs/0052-ZsiqXYa.gif', '© Gym visual — https://gymvisual.com/', '900244'),
('100053', '杠铃跳跃深蹲', '股四头肌', '杠铃', '未分级', '首先，双脚分开与肩同宽站立，将杠铃放在上背部。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。一旦到达深蹲底部，就从地面跳起向上爆发。跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。', 'exercise-dataset', '0053', 'barbell jump squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Once you reach the bottom of the squat, explode upwards by jumping off the ground. As you jump, extend your hips, knees, and ankles, pushing through your toes. Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.', '/static/exercises/images/0053-1gFNTZV.jpg', '/static/exercises/gifs/0053-1gFNTZV.gif', '© Gym visual — https://gymvisual.com/', '243'),
('101410', '杠铃侧弓步', '股四头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。右脚向一侧迈出一大步，保持左脚踩地。弯曲右膝，将身体降低到弓步位置，保持左腿伸直。用右脚推出并返回到起始位置。在另一侧重复，用左脚迈步。', 'exercise-dataset', '1410', 'barbell lateral lunge', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a lunge position, keeping your left leg straight. Push off with your right foot and return to the starting position. Repeat on the other side, stepping with your left foot.', '/static/exercises/images/1410-py1HSzx.jpg', '/static/exercises/gifs/1410-py1HSzx.gif', '© Gym visual — https://gymvisual.com/', '320244'),
('101435', '杠铃低位杆深蹲', '股四头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，杠铃放在上背部。保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。继续降低，直到大腿与地面平行或略低于地面。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1435', 'barbell low bar squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and the barbell resting on your upper back. Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1435-bTpEUcm.jpg', '/static/exercises/gifs/1435-bTpEUcm.gif', '© Gym visual — https://gymvisual.com/', '247'),
('100054', '杠铃弓步', '股四头肌', '杠铃', '未分级', '首先，双脚分开与肩同宽，将杠铃放在上背部。右脚向前迈出一步，保持躯干直立。弯曲右膝降低身体，直到大腿与地面平行。推动右脚跟回到起始位置。用左腿重复上述动作，交替腿进行所需的重复次数。', 'exercise-dataset', '0054', 'barbell lunge', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step forward with your right foot, keeping your torso upright. Lower your body by bending your right knee until your thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg, alternating legs for the desired number of repetitions.', '/static/exercises/images/0054-t8iSghb.jpg', '/static/exercises/gifs/0054-t8iSghb.gif', '© Gym visual — https://gymvisual.com/', '320244'),
('101720', '杠铃仰卧后侧头后肱三头肌伸展', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1720', 'barbell lying back of the head tricep extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1720-yg8Totb.jpg', '/static/exercises/gifs/1720-yg8Totb.gif', '© Gym visual — https://gymvisual.com/', '900257'),
('100055', '杠铃仰卧窄距握推举', '胸肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。慢慢地将杠铃降低到胸部，保持肘部靠近身体。当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0055', 'barbell lying close-grip press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0055-EcaV7aL.jpg', '/static/exercises/gifs/0055-EcaV7aL.gif', '© Gym visual — https://gymvisual.com/', '900250'),
('100056', '杠铃仰卧窄握肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。紧握杠铃，双手与肩同宽，掌心向上。充分伸展双臂，将杠铃举至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。在底部停顿片刻，然后将手臂伸展回起始位置。重复所需的重复次数。', 'exercise-dataset', '0056', 'barbell lying close-grip triceps extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up. Extend your arms fully, lifting the barbell above your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0056-HJ63mSO.jpg', '/static/exercises/gifs/0056-HJ63mSO.gif', '© Gym visual — https://gymvisual.com/', '400253'),
('100057', '杠铃仰卧伸展', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0057', 'barbell lying extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0057-EMpUwRI.jpg', '/static/exercises/gifs/0057-EMpUwRI.gif', '© Gym visual — https://gymvisual.com/', '900250'),
('100058', '杠铃仰卧抬举髋部', '腘绳肌', '杠铃', '未分级', '仰卧在长凳上，双脚平放在地上，膝盖弯曲。正手握住杠铃并将其放在臀部上。收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0058', 'barbell lying lifting (on hip)', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent. Hold the barbell with an overhand grip and position it on your hips. Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0058-SNFfUff.jpg', '/static/exercises/gifs/0058-SNFfUff.gif', '© Gym visual — https://gymvisual.com/', '900255'),
('100059', '杠铃仰卧牧师凳弯举', '前臂', '杠铃', '未分级', '坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0059', 'barbell lying preacher curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0059-SYJ4Bkt.jpg', '/static/exercises/gifs/0059-SYJ4Bkt.gif', '© Gym visual — https://gymvisual.com/', '80254'),
('100061', '杠铃仰卧肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数。', 'exercise-dataset', '0061', 'barbell lying triceps extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0061-iZop9xO.jpg', '/static/exercises/gifs/0061-iZop9xO.gif', '© Gym visual — https://gymvisual.com/', '400255'),
('100060', '杠铃仰卧肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。重复所需的重复次数。', 'exercise-dataset', '0060', 'barbell lying triceps extension skull crusher', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0060-h8LFzo9.jpg', '/static/exercises/gifs/0060-h8LFzo9.gif', '© Gym visual — https://gymvisual.com/', '400260'),
('100063', '杠铃窄距深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。继续降低，直到大腿与地面平行或略低于地面。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0063', 'barbell narrow stance squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0063-elhhVgj.jpg', '/static/exercises/gifs/0063-elhhVgj.gif', '© Gym visual — https://gymvisual.com/', '257'),
('100064', '杠铃单臂俯身划船', '肱二头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。臀部向前弯曲，保持背部挺直，头部处于中立位置。将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。以受控的方式将杠铃降低回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0064', 'barbell one arm bent over row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip. Bend forward at the hips, keeping your back straight and your head in a neutral position. Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Lower the barbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0064-Jsgsc27.jpg', '/static/exercises/gifs/0064-Jsgsc27.gif', '© Gym visual — https://gymvisual.com/', '160262'),
('100065', '杠铃单臂地板推举', '胸肌', '杠铃', '未分级', '仰卧在地板上，膝盖弯曲，双脚平放在地面上。用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。慢慢地将杠铃降低到胸部，保持肘部靠近身体。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0065', 'barbell one arm floor press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest. Slowly lower the barbell towards your chest, keeping your elbow close to your body. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0065-vtusOWT.jpg', '/static/exercises/gifs/0065-vtusOWT.gif', '© Gym visual — https://gymvisual.com/', '900261'),
('100066', '杠铃单臂侧向硬拉', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，一只手握住杠铃，正握。保持背部挺直，核心肌群参与。臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。尽可能降低杠铃，同时保持良好的姿势。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0066', 'barbell one arm side deadlift', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","下背部"]', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip. Keep your back straight and your core engaged. Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up. Lower the barbell as far as you can while maintaining good form. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0066-2DxtqHL.jpg', '/static/exercises/gifs/0066-2DxtqHL.gif', '© Gym visual — https://gymvisual.com/', '80262'),
('100067', '杠铃单臂抓举', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。正手握住杠铃，双手分开略宽于肩宽。弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。爆发性伸展臀部、膝盖和脚踝，将杠铃向上推。当杠铃到达胸部水平时，用手臂将其向上拉，使其靠近身体。将肘部旋转到杠铃下方，并将手臂完全伸过头顶，锁定肘部。以受控的方式将杠铃降低回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0067', 'barbell one arm snatch', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","前臂","核心肌群"]', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up. Explosively extend your hips, knees, and ankles, driving the barbell upwards. As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body. Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow. Lower the barbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0067-xHKN2s8.jpg', '/static/exercises/gifs/0067-xHKN2s8.gif', '© Gym visual — https://gymvisual.com/', '900261'),
('100068', '杠铃单腿深蹲', '臀肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。将一只脚抬离地面并向前伸展，保持与地面平行。弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '0068', 'barbell one leg squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Lift one foot off the ground and extend it forward, keeping it parallel to the ground. Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight. Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/0068-uKyN64F.jpg', '/static/exercises/gifs/0068-uKyN64F.gif', '© Gym visual — https://gymvisual.com/', '262'),
('100069', '杠铃过顶深蹲', '臀肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。宽握距握住杠铃，将其置于头顶，双臂完全伸展。收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0069', 'barbell overhead squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell with a wide grip, positioning it overhead with your arms fully extended. Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0069-gfk9kD4.jpg', '/static/exercises/gifs/0069-gfk9kD4.gif', '© Gym visual — https://gymvisual.com/', '261'),
('101411', '杠铃反握腕弯举越过训练凳', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。正手握住杠铃，双手与肩同宽。弯曲手腕，将杠铃降低到地面，保持前臂静止。在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。重复所需的重复次数。', 'exercise-dataset', '1411', 'barbell palms down wrist curl over a bench', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down. Hold a barbell with an overhand grip, hands shoulder-width apart. Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary. Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists. Repeat for the desired number of repetitions.', '/static/exercises/images/1411-yzYH9pI.jpg', '/static/exercises/gifs/1411-yzYH9pI.gif', '© Gym visual — https://gymvisual.com/', '272'),
('101412', '杠铃正握腕弯举越过训练凳', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。将前臂放在长凳上，让手腕悬在长凳边缘。保持前臂静止，呼气并尽可能向上弯曲手腕。保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1412', 'barbell palms up wrist curl over a bench', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1412-SJAA2IQ.jpg', '/static/exercises/gifs/1412-SJAA2IQ.gif', '© Gym visual — https://gymvisual.com/', '273'),
('103017', '杠铃彭德雷划船', '肱二头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。臀部向前弯曲，保持背部挺直，挺胸。正手握住杠铃，握距略宽于肩宽。将杠铃拉向上腹部，将肩胛骨挤压在一起。将杠铃降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3017', 'barbell pendlay row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Bend forward at the hips, keeping your back straight and your chest up. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3017-r0z6xzQ.jpg', '/static/exercises/gifs/3017-r0z6xzQ.gif', '© Gym visual — https://gymvisual.com/', '900264'),
('101751', '杠铃安全销推举', '肩部', '杠铃', '未分级', '将杠铃放在与胸部同高的力量架上。面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。将杠铃向胸部方向降低，保持肘部靠近身体。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1751', 'barbell pin presses', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Set up a barbell on a power rack at chest height. Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart. Grip the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended. Lower the barbell down towards your chest, keeping your elbows tucked in close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1751-bndCa3Q.jpg', '/static/exercises/gifs/1751-bndCa3Q.gif', '© Gym visual — https://gymvisual.com/', '900265'),
('100070', '杠铃牧师凳弯举', '前臂', '杠铃', '未分级', '坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。反手握住杠铃，握距略宽于肩宽。保持上臂静止，呼气并将杠铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0070', 'barbell preacher curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0070-qOgPVf6.jpg', '/static/exercises/gifs/0070-qOgPVf6.gif', '© Gym visual — https://gymvisual.com/', '80266'),
('100071', '杠铃推举坐向上', '肩部', '杠铃', '未分级', '平躺在垫子上，膝盖弯曲，双脚平放在地上。正手握住杠铃，将其放在胸前。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0071', 'barbell press sit-up', 'waist', '腰腹', '60', 'barbell', 'shoulders', 'abs', '腹肌', '["肩部","胸肌"]', 'Lie flat on your back on a mat with your knees bent and feet flat on the ground. Hold the barbell with an overhand grip, resting it on your chest. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0071-wnEscH8.jpg', '/static/exercises/gifs/0071-wnEscH8.gif', '© Gym visual — https://gymvisual.com/', '160267'),
('100072', '杠铃俯卧上斜弯举', '前臂', '杠铃', '未分级', '设置一个 45 度角的上斜凳。脸朝下躺在长凳上，胸部和腹部靠在长凳上。反手握住杠铃，距离与肩同宽。充分伸展双臂，让杠铃垂向地板。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0072', 'barbell prone incline curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Set up an incline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a barbell with an underhand grip, shoulder-width apart. Extend your arms fully, allowing the barbell to hang down towards the floor. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0072-WLvTAv5.jpg', '/static/exercises/gifs/0072-WLvTAv5.gif', '© Gym visual — https://gymvisual.com/', '80270'),
('100073', '杠铃上拉', '胸肌', '杠铃', '未分级', '平躺在长凳上，头放在一端，双脚放在地板上。握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。暂停片刻，然后将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0073', 'barbell pullover', 'back', '背部', '20', 'barbell', 'chest', 'lats', '背阔肌', '["胸肌","肱三头肌"]', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a barbell with a shoulder-width grip and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats. Pause for a moment, then raise the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0073-i6LWjok.jpg', '/static/exercises/gifs/0073-i6LWjok.gif', '© Gym visual — https://gymvisual.com/', '900267'),
('100022', '杠铃上拉推举', '肱三头肌', '杠铃', '未分级', '平躺在长凳上，头朝一端，双脚着地。旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。重复所需的重复次数。', 'exercise-dataset', '0022', 'barbell pullover to press', 'back', '背部', '20', 'barbell', 'triceps', 'lats', '背阔肌', '["肱三头肌","胸肌","肩部"]', 'Lie flat on a bench with your head at one end and your feet on the ground. Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest. Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats. Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/0022-znLogoF.jpg', '/static/exercises/gifs/0022-znLogoF.gif', '© Gym visual — https://gymvisual.com/', '900272'),
('100074', '杠铃深蹲架拉', '腘绳肌', '杠铃', '未分级', '将杠铃放在膝盖高度的架子上。双脚分开与肩同宽站立，脚趾稍微向外。弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。弯曲臀部和膝盖，将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0074', 'barbell rack pull', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Set up a barbell on a rack at knee height. Stand with your feet shoulder-width apart, toes pointing slightly outwards. Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart. Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top. Lower the barbell back down to the starting position by bending at the hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/0074-za9Ni4z.jpg', '/static/exercises/gifs/0074-za9Ni4z.gif', '© Gym visual — https://gymvisual.com/', '900271'),
('100075', '杠铃三角肌后束上举', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0075', 'barbell rear delt raise', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0075-Ln9iTbU.jpg', '/static/exercises/gifs/0075-Ln9iTbU.gif', '© Gym visual — https://gymvisual.com/', '400274'),
('100076', '杠铃三角肌后束划船', '斜方肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，双手分开略宽于肩宽。臀部向前弯曲，保持背部挺直，挺胸。将杠铃拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0076', 'barbell rear delt row', 'shoulders', '肩部', '30', 'barbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up. Pull the barbell towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0076-S9zHIvU.jpg', '/static/exercises/gifs/0076-S9zHIvU.gif', '© Gym visual — https://gymvisual.com/', '400275'),
('100078', '杠铃后侧弓步', '股四头肌', '杠铃', '未分级', '首先，双脚分开与肩同宽，将杠铃放在上背部。右脚向后退一步，用脚掌着地。弯曲双膝降低身体，直到左大腿与地面平行。推动左脚跟返回到起始位置。换另一条腿重复上述步骤。', 'exercise-dataset', '0078', 'barbell rear lunge', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground. Push through your left heel to return to the starting position. Repeat with the other leg.', '/static/exercises/images/0078-VaP75jl.jpg', '/static/exercises/gifs/0078-VaP75jl.gif', '© Gym visual — https://gymvisual.com/', '320274'),
('100077', '杠铃后侧弓步版本第二式', '股四头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。右脚向后退一步，用脚掌着地。弯曲双膝降低身体，直到左大腿与地面平行。推动左脚跟返回到起始位置。换另一条腿重复上述步骤。', 'exercise-dataset', '0077', 'barbell rear lunge v. 2', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Take a step backward with your right foot, landing on the ball of your foot. Bend both knees to lower your body until your left thigh is parallel to the ground. Push through your left heel to return to the starting position. Repeat with the other leg.', '/static/exercises/images/0077-62Nw60O.jpg', '/static/exercises/gifs/0077-62Nw60O.gif', '© Gym visual — https://gymvisual.com/', '320279'),
('100079', '杠铃反向腕弯举版本第二式', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地上，膝盖弯曲。正手握住杠铃，手掌朝下，双手与肩同宽。将前臂放在大腿上，让手腕悬在边缘。保持前臂静止，呼气并尽可能向上弯曲手腕。保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0079', 'barbell revers wrist curl v. 2', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0079-qDnGfDb.jpg', '/static/exercises/gifs/0079-qDnGfDb.gif', '© Gym visual — https://gymvisual.com/', '282'),
('102187', '杠铃反向窄握卧推', '胸肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。反握抓住杠铃，双手与肩同宽。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。慢慢地将杠铃向胸部降低，保持肘部靠近身体。当杠铃位于胸部正上方时，暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '2187', 'barbell reverse close-grip bench press', 'upper arms', '上臂', '50', 'barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a reverse grip, hands shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell down towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell is just above your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2187-YqJw82s.jpg', '/static/exercises/gifs/2187-YqJw82s.gif', '© Gym visual — https://gymvisual.com/', '900281'),
('100080', '杠铃反向弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，正手握住杠铃，手掌朝下。保持上臂静止，向上弯举杠铃时呼气，收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将杠铃放回起始位置，保持上臂静止。重复所需的重复次数。', 'exercise-dataset', '0080', 'barbell reverse curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down. Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary. Repeat for the desired number of repetitions.', '/static/exercises/images/0080-xNrS20v.jpg', '/static/exercises/gifs/0080-xNrS20v.gif', '© Gym visual — https://gymvisual.com/', '80278'),
('100118', '杠铃反向握俯身划船', '肱二头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，手掌朝下，双手分开略宽于肩宽。臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。将杠铃拉向下胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0118', 'barbell reverse grip bent over row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor. Pull the barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0118-SzX3uzM.jpg', '/static/exercises/gifs/0118-SzX3uzM.gif', '© Gym visual — https://gymvisual.com/', '160285'),
('101256', '杠铃反向握下斜卧推', '肱三头肌', '杠铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。反握抓住杠铃，握距略宽于肩宽。松开杠铃，慢慢将其降低到胸部，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1256', 'barbell reverse grip decline bench press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie on a decline bench with your feet secured and your head lower than your hips. Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1256-DotAgEF.jpg', '/static/exercises/gifs/1256-DotAgEF.gif', '© Gym visual — https://gymvisual.com/', '286'),
('101257', '杠铃反向握上斜卧推', '肱三头肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。躺在长凳上，双脚平放在地上。反握抓住杠铃，双手分开略宽于肩宽。松开杠铃，慢慢将其降低到胸部，保持肘部内收。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1257', 'barbell reverse grip incline bench press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1257-DU7I633.jpg', '/static/exercises/gifs/1257-DU7I633.gif', '© Gym visual — https://gymvisual.com/', '287'),
('101317', '杠铃反向握上斜训练凳划船', '肱二头肌', '杠铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，面向靠背，胸部靠在靠背上。反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。保持背部挺直，核心参与。将杠铃拉向上腹部，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢地将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1317', 'barbell reverse grip incline bench row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench facing the backrest with your chest against it. Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart. Keep your back straight and core engaged. Pull the barbell towards your upper abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1317-8d8qJQI.jpg', '/static/exercises/gifs/1317-8d8qJQI.gif', '© Gym visual — https://gymvisual.com/', '900288'),
('101721', '杠铃反向握仰卧臂屈伸', '前臂', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。反握握住杠铃，手掌朝向脸部，双手与肩同宽。将手臂伸直越过胸部，保持肘部内收和手腕伸直。弯曲肘部，慢慢将杠铃降低到前额，保持上臂静止。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数。', 'exercise-dataset', '1721', 'barbell reverse grip skullcrusher', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart. Extend your arms straight up over your chest, keeping your elbows in and your wrists straight. Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1721-yRLPCLu.jpg', '/static/exercises/gifs/1721-yRLPCLu.gif', '© Gym visual — https://gymvisual.com/', '900285'),
('100081', '杠铃反向牧师凳弯举', '前臂', '杠铃', '未分级', '坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0081', 'barbell reverse preacher curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip. Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0081-4LIG9xr.jpg', '/static/exercises/gifs/0081-4LIG9xr.gif', '© Gym visual — https://gymvisual.com/', '80286'),
('100082', '杠铃反向腕弯举', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地上，正手握住杠铃，手掌朝下。将前臂放在大腿上，让手腕悬在边缘。慢慢向上弯曲手腕，将杠铃拉向身体。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0082', 'barbell reverse wrist curl', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your body. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0082-LsZkfU6.jpg', '/static/exercises/gifs/0082-LsZkfU6.gif', '© Gym visual — https://gymvisual.com/', '287'),
('100084', '杠铃滚轮前伸', '下背部', '杠铃', '未分级', '跪在地板上，双手握住杠铃，距离与肩同宽。向前滚动杠铃，伸展手臂并保持核心收紧。继续向前滚动，直到身体完全伸展并且手臂举过头顶。暂停片刻，然后慢慢将杠铃向膝盖方向滚动，保持控制。重复所需的重复次数。', 'exercise-dataset', '0084', 'barbell rollerout', 'waist', '腰腹', '60', 'barbell', 'lower back', 'abs', '腹肌', '["下背部"]', 'Kneel on the floor and hold a barbell with both hands, shoulder-width apart. Roll the barbell forward, extending your arms and keeping your core engaged. Continue rolling forward until your body is fully extended and your arms are overhead. Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control. Repeat for the desired number of repetitions.', '/static/exercises/images/0084-7M66AVi.jpg', '/static/exercises/gifs/0084-7M66AVi.gif', '© Gym visual — https://gymvisual.com/', '900284'),
('100083', '杠铃滚轮前伸从训练凳', '肩部', '杠铃', '未分级', '首先跪在地板上，将杠铃放在你面前的长凳上。正手握住杠铃，握距略宽于肩宽。保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0083', 'barbell rollerout from bench', 'waist', '腰腹', '60', 'barbell', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌"]', 'Start by kneeling on the floor with a barbell placed on a bench in front of you. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you. Continue rolling the barbell forward until your body is fully extended and your arms are overhead. Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0083-Gxg9lDc.jpg', '/static/exercises/gifs/0083-Gxg9lDc.gif', '© Gym visual — https://gymvisual.com/', '900289'),
('100085', '杠铃罗马尼亚硬拉', '腘绳肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾指向前方。正手握住杠铃，双手分开略宽于肩宽。弯曲臀部，保持背部挺直，膝盖稍微弯曲。将杠铃向地面降低，使其靠近身体。当你降低杠铃时，感受腿筋的拉伸。一旦感觉到腿筋拉伸，就将臀部向前推并站直。在动作的最高点挤压臀部。将杠铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0085', 'barbell romanian deadlift', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at the hips, keeping your back straight and your knees slightly bent. Lower the barbell towards the ground, keeping it close to your body. Feel the stretch in your hamstrings as you lower the barbell. Once you feel a stretch in your hamstrings, push your hips forward and stand up straight. Squeeze your glutes at the top of the movement. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0085-wQ2c4XD.jpg', '/static/exercises/gifs/0085-wQ2c4XD.gif', '© Gym visual — https://gymvisual.com/', '80288'),
('100086', '杠铃坐姿颈后头后军事推举', '肱三头肌', '杠铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。正手握住杠铃，杠铃间距略宽于肩宽。将杠铃从架子上提起，然后将其降至与肩同高，位于头后。向上推杠铃，直到手臂完全伸展。将杠铃降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0086', 'barbell seated behind head military press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, behind your head. Press the barbell upward until your arms are fully extended. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0086-ngPpyRS.jpg', '/static/exercises/gifs/0086-ngPpyRS.gif', '© Gym visual — https://gymvisual.com/', '900295'),
('100087', '杠铃坐姿布拉德福德洛奇式推举', '肱三头肌', '杠铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。正手握住杠铃，杠铃间距略宽于肩宽。将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。将杠铃推过头顶，充分伸展双臂。将杠铃降低回肩部高度，然后重复所需的重复次数。', 'exercise-dataset', '0087', 'barbell seated bradford rocky press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward. Press the barbell overhead, fully extending your arms. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '/static/exercises/images/0087-0dCyly0.jpg', '/static/exercises/gifs/0087-0dCyly0.gif', '© Gym visual — https://gymvisual.com/', '900294'),
('100088', '杠铃坐姿提踵', '腘绳肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地板上，杠铃放在大腿上。将脚掌放在升高的平台上，例如木块或台阶。将杠铃放在大腿上，并用手牢牢握住它。保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0088', 'barbell seated calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Position the barbell across your thighs and hold it securely with your hands. Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0088-ktsFQAZ.jpg', '/static/exercises/gifs/0088-ktsFQAZ.gif', '© Gym visual — https://gymvisual.com/', '293'),
('101371', '杠铃坐姿提踵', '腘绳肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地板上，杠铃放在大腿上。将脚掌放在升高的平台上，例如木块或台阶。尽可能降低脚后跟，感受小腿的拉伸。尽可能高地抬高脚后跟，收缩小腿。重复所需的重复次数。', 'exercise-dataset', '1371', 'barbell seated calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs. Place the balls of your feet on a raised platform, such as a block or step. Lower your heels as far as possible, feeling a stretch in your calves. Raise your heels as high as possible, contracting your calves. Repeat for the desired number of repetitions.', '/static/exercises/images/1371-ipvgBnC.jpg', '/static/exercises/gifs/1371-ipvgBnC.gif', '© Gym visual — https://gymvisual.com/', '294'),
('101718', '杠铃坐姿窄距握颈后颈部肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。紧紧抓住颈后的杠铃，手掌朝前。保持肘部靠近头部，慢慢将杠铃放低至脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1718', 'barbell seated close grip behind neck triceps extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with a close grip behind your neck, palms facing forward. Keep your elbows close to your head and slowly lower the barbell towards the back of your head. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1718-4CBIBOM.jpg', '/static/exercises/gifs/1718-4CBIBOM.gif', '© Gym visual — https://gymvisual.com/', '400303'),
('100089', '杠铃坐姿窄距握集中弯举', '前臂', '杠铃', '未分级', '坐在长凳上，双脚平放在地板上，反手握住杠铃，双手与肩同宽。将你的上臂靠在大腿内侧，就在膝盖上方，让杠铃垂在你面前。保持上臂静止，呼气并将杠铃向上卷曲至肩膀，收缩二头肌。保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0089', 'barbell seated close-grip concentration curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0089-1V1gj1u.jpg', '/static/exercises/gifs/0089-1V1gj1u.gif', '© Gym visual — https://gymvisual.com/', '80298'),
('100090', '杠铃坐姿早安式', '腘绳肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地上，上背部放一个杠铃。保持背部挺直，挺胸。慢慢地向前转动臀部，将躯干降低到地面。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0090', 'barbell seated good morning', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back. Keep your back straight and your chest up. Slowly hinge forward at the hips, lowering your torso towards the ground. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0090-d960PgE.jpg', '/static/exercises/gifs/0090-d960PgE.gif', '© Gym visual — https://gymvisual.com/', '900297'),
('100091', '杠铃坐姿过顶推举', '肱三头肌', '杠铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。正手握住杠铃，杠铃间距略宽于肩宽。将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。充分伸展双臂，将杠铃压过头顶。在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。重复所需的重复次数。', 'exercise-dataset', '0091', 'barbell seated overhead press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward. Press the barbell overhead by extending your arms fully. Pause for a moment at the top, then slowly lower the barbell back to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0091-kTbSH9h.jpg', '/static/exercises/gifs/0091-kTbSH9h.gif', '© Gym visual — https://gymvisual.com/', '80298'),
('100092', '杠铃坐姿过顶肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。正手握住杠铃，双手与肩同宽，并将其举过头顶。弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。暂停片刻，然后伸展双臂将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0092', 'barbell seated overhead triceps extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead. Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head. Pause for a moment, then extend your arms to raise the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0092-5uFK1xr.jpg', '/static/exercises/gifs/0092-5uFK1xr.gif', '© Gym visual — https://gymvisual.com/', '400301'),
('100094', '杠铃坐姿转体', '腹斜肌', '杠铃', '未分级', '坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。双手握住杠铃于胸前，保持肘部稍微弯曲。启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。扭转结束时暂停片刻，然后慢慢旋转回到起始位置。重复扭转到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0094', 'barbell seated twist', 'waist', '腰腹', '60', 'barbell', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on a flat bench with your feet flat on the ground and your knees bent. Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent. Engage your core and slowly twist your torso to one side, keeping your back straight. Pause for a moment at the end of the twist, then slowly rotate back to the starting position. Repeat the twist to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0094-dFSNDOA.jpg', '/static/exercises/gifs/0094-dFSNDOA.gif', '© Gym visual — https://gymvisual.com/', '900298'),
('100095', '杠铃耸肩', '肩部', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃。在整个练习过程中保持手臂伸直和背部挺直。将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。保持一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0095', 'barbell shrug', 'back', '背部', '20', 'barbell', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip. Keep your arms straight and your back straight throughout the exercise. Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top. Hold for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0095-dG7tG5y.jpg', '/static/exercises/gifs/0095-dG7tG5y.gif', '© Gym visual — https://gymvisual.com/', '560297'),
('100096', '杠铃侧向屈曲版本第二式', '腹斜肌', '杠铃', '未分级', '双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。在整个练习过程中保持背部挺直并保持核心参与。慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。暂停片刻，然后回到起始位置。在左侧重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0096', 'barbell side bent v. 2', 'waist', '腰腹', '60', 'barbell', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down. Keep your back straight and core engaged throughout the exercise. Slowly bend your torso to the right side, lowering the barbell towards your right knee. Pause for a moment, then return to the starting position. Repeat the movement on the left side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0096-i4JkUaL.jpg', '/static/exercises/gifs/0096-i4JkUaL.gif', '© Gym visual — https://gymvisual.com/', '900304'),
('100098', '杠铃侧向分腿蹲', '臀肌', '杠铃', '未分级', '站立，双脚分开比肩宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌上。当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0098', 'barbell side split squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips. As you lower, push your knees out to the sides and keep your weight on your heels. Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0098-W31mMjd.jpg', '/static/exercises/gifs/0098-W31mMjd.gif', '© Gym visual — https://gymvisual.com/', '303'),
('100097', '杠铃侧向分腿蹲版本第二式', '臀肌', '杠铃', '未分级', '站立，双脚分开比肩宽，脚趾稍微向外。将杠铃放在上背部，将其放在肩膀上。右脚向一侧迈出一大步，保持左脚踩地。弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。推动右脚跟回到起始位置。在另一侧重复，左脚迈出。继续交替进行所需的重复次数。', 'exercise-dataset', '0097', 'barbell side split squat v. 2', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards. Hold a barbell across your upper back, resting it on your shoulders. Take a big step to the side with your right foot, keeping your left foot planted. Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight. Push through your right heel to return to the starting position. Repeat on the other side, stepping out with your left foot. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0097-HUEqZ1y.jpg', '/static/exercises/gifs/0097-HUEqZ1y.gif', '© Gym visual — https://gymvisual.com/', '308'),
('101756', '杠铃单侧腿硬拉', '腘绳肌', '杠铃', '未分级', '站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。将重心转移到左脚上，并将右脚稍微抬离地面。臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1756', 'barbell single leg deadlift', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip. Shift your weight onto your left foot and lift your right foot slightly off the ground. Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance. Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1756-gEyURal.jpg', '/static/exercises/gifs/1756-gEyURal.gif', '© Gym visual — https://gymvisual.com/', '80305'),
('100099', '杠铃单侧腿分腿蹲', '臀肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。单腿向前迈出一大步，保持躯干直立。弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。继续降低，直到大腿前侧与地面平行。暂停片刻，然后推动前脚跟回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0099', 'barbell single leg split squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with one leg, keeping your torso upright. Lower your body by bending your front knee and hip, while keeping your back leg straight. Continue lowering until your front thigh is parallel to the ground. Pause for a moment, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0099-gGNQmVt.jpg', '/static/exercises/gifs/0099-gGNQmVt.gif', '© Gym visual — https://gymvisual.com/', '308'),
('102799', '杠铃坐姿交替举腿', '髋屈肌', '杠铃', '未分级', '坐在长凳上，背部挺直，将杠铃放在大腿上。保持双腿伸直，将一条腿尽可能高地抬起，同时将另一条腿放在地上。将抬起的腿放回原位，然后换另一条腿重复上述步骤。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '2799', 'barbell sitted alternate leg raise', 'waist', '腰腹', '60', 'barbell', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on a bench with your back straight and hold a barbell across your thighs. Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground. Lower the raised leg back down and repeat with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/2799-G7xoEzr.jpg', '/static/exercises/gifs/2799-G7xoEzr.gif', '© Gym visual — https://gymvisual.com/', '240309'),
('102800', '杠铃坐姿交替举腿（女）', '髋屈肌', '杠铃', '未分级', '坐在长凳上，背部挺直，将杠铃放在大腿上。将双手放在长凳两侧以获得支撑。保持双腿伸直，将一条腿尽可能抬高，同时保持与地面平行。将腿放回原位，然后换另一条腿重复此动作。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '2800', 'barbell sitted alternate leg raise (female)', 'waist', '腰腹', '60', 'barbell', 'hip flexors', 'abs', '腹肌', '["髋屈肌","股四头肌"]', 'Sit on a bench with your back straight and hold a barbell across your thighs. Place your hands on the sides of the bench for support. Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground. Lower the leg back down and repeat with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/2800-BCs0G2F.jpg', '/static/exercises/gifs/2800-BCs0G2F.gif', '© Gym visual — https://gymvisual.com/', '240312'),
('100100', '杠铃滑雪式', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃于大腿前方。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。同时将杠铃举向肩膀，同时稍微离开地面。当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0100', 'barbell skier', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground. As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0100-4Leypho.jpg', '/static/exercises/gifs/0100-4Leypho.gif', '© Gym visual — https://gymvisual.com/', '900305'),
('100101', '杠铃快速深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。通过脚跟发力站起来，在顶部挤压臀部。重复所需的重复次数。', 'exercise-dataset', '0101', 'barbell speed squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', '/static/exercises/images/0101-euI1BwR.jpg', '/static/exercises/gifs/0101-euI1BwR.gif', '© Gym visual — https://gymvisual.com/', '308'),
('102810', '杠铃分腿蹲版本第二式', '臀肌', '杠铃', '未分级', '首先，双脚分开与肩同宽站立，将杠铃放在上背部。右脚向前迈出一大步，保持躯干直立。弯曲膝盖和臀部，降低身体，直到右大腿与地面平行。暂停片刻，然后推动右脚跟回到起始位置。左腿向前重复此动作，达到所需的重复次数。', 'exercise-dataset', '2810', 'barbell split squat v. 2', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Take a large step forward with your right foot, keeping your torso upright. Lower your body by bending your knees and hips until your right thigh is parallel to the ground. Pause for a moment, then push through your right heel to return to the starting position. Repeat with your left leg forward for the desired number of repetitions.', '/static/exercises/images/2810-HBYyX94.jpg', '/static/exercises/gifs/2810-HBYyX94.gif', '© Gym visual — https://gymvisual.com/', '313'),
('100102', '杠铃深蹲双膝', '臀肌', '杠铃', '未分级', '首先跪在地上，膝盖分开与臀部同宽，脚趾向前。将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0102', 'barbell squat (on knees)', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward. Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart. Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0102-oR7O9LW.jpg', '/static/exercises/gifs/0102-oR7O9LW.gif', '© Gym visual — https://gymvisual.com/', '312'),
('102798', '杠铃深蹲跳跃踏步后侧弓步', '臀肌', '杠铃', '未分级', '首先，双脚分开与肩同宽站立，将杠铃放在上背部。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。向上爆炸，尽可能高地跳离地面。双脚轻轻落地，然后立即单腿向后退一步，形成反向弓步。降低身体，直到大腿前侧与地面平行，保持背部挺直。推动前脚跟以返回到起始位置。在另一条腿上重复跳跃和弓步序列。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '2798', 'barbell squat jump step rear lunge', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back. Lower your body into a squat position by bending your knees and pushing your hips back. Explode upwards, jumping off the ground as high as you can. Land softly on your feet and immediately step back with one leg into a reverse lunge. Lower your body down until your front thigh is parallel to the ground, keeping your back straight. Push through your front heel to return to the starting position. Repeat the jump and lunge sequence on the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/2798-RYcV1kH.jpg', '/static/exercises/gifs/2798-RYcV1kH.gif', '© Gym visual — https://gymvisual.com/', '317'),
('100103', '杠铃站姿腹肌滚轮前伸', '肩部', '杠铃', '未分级', '站直，双脚分开与肩同宽，双手握住杠铃于大腿前方。启动你的核心肌群，慢慢地将杠铃向地面滚动，保持背部挺直，手臂伸展。继续向前滚动杠铃，直到身体完全伸展，双手位于头顶正上方。暂停片刻，然后慢慢地将杠铃向大腿方向滚动，保持控制并保持核心参与。重复所需的重复次数。', 'exercise-dataset', '0103', 'barbell standing ab rollerout', 'waist', '腰腹', '60', 'barbell', 'shoulders', 'abs', '腹肌', '["肩部","下背部"]', 'Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs. Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended. Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head. Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged. Repeat for the desired number of repetitions.', '/static/exercises/images/0103-xnInPfE.jpg', '/static/exercises/gifs/0103-xnInPfE.gif', '© Gym visual — https://gymvisual.com/', '900314'),
('100104', '杠铃站姿后侧腕弯举', '肱二头肌', '杠铃', '未分级', '站直，双脚分开与肩同宽，正手握住杠铃。将杠铃放在手背上，手掌朝下，手指指向身体。保持上臂静止，呼气并尽可能向上弯曲手腕。保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0104', 'barbell standing back wrist curl', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip. Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body. Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible. Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0104-2qTvJAZ.jpg', '/static/exercises/gifs/0104-2qTvJAZ.gif', '© Gym visual — https://gymvisual.com/', '317'),
('100105', '杠铃站姿布拉德福德推举', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃于肩前。将杠铃推过头顶，充分伸展双臂。将杠铃降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0105', 'barbell standing bradford press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip. Press the barbell overhead, fully extending your arms. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0105-dCPESfR.jpg', '/static/exercises/gifs/0105-dCPESfR.gif', '© Gym visual — https://gymvisual.com/', '900316'),
('101372', '杠铃站姿提踵', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。仅用脚趾将脚后跟抬离地面，尽可能高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1372', 'barbell standing calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using only your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1372-8ozhUIZ.jpg', '/static/exercises/gifs/1372-8ozhUIZ.gif', '© Gym visual — https://gymvisual.com/', '317'),
('100106', '杠铃站姿窄距握弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，双手并拢。在整个运动过程中，保持肘部靠近躯干，上臂保持静止。弯举哑铃时呼气，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢开始将杠铃拉回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0106', 'barbell standing close grip curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale as you slowly begin to bring the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0106-4dUn2iv.jpg', '/static/exercises/gifs/0106-4dUn2iv.gif', '© Gym visual — https://gymvisual.com/', '80320'),
('101456', '杠铃站姿窄距握军事推举', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，双手距离略小于肩宽。将杠铃举至肩膀高度，保持肘部靠近身体。将杠铃推过头顶，充分伸展双臂。将杠铃降低回肩部高度。重复所需的重复次数。', 'exercise-dataset', '1456', 'barbell standing close grip military press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart. Lift the barbell to shoulder height, keeping your elbows close to your body. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/1456-wdRZISl.jpg', '/static/exercises/gifs/1456-wdRZISl.gif', '© Gym visual — https://gymvisual.com/', '900323'),
('102414', '杠铃站姿集中弯举', '前臂', '杠铃', '未分级', '双脚分开与肩同宽站立，一手握住杠铃，掌心朝上。将另一只手放在大腿上以获得支撑。保持上臂静止，呼气并将重量向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将重量放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '2414', 'barbell standing concentration curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up. Rest your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the weight back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/2414-vsMcDi9.jpg', '/static/exercises/gifs/2414-vsMcDi9.gif', '© Gym visual — https://gymvisual.com/', '80320'),
('100107', '杠铃站姿前侧上举越过头后', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃于大腿前方。保持背部挺直并启动核心肌群。慢慢地将杠铃举到你面前，保持手臂伸直，手掌朝下。继续举起杠铃，直到杠铃略高于肩部水平。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0107', 'barbell standing front raise over head', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip. Keep your back straight and engage your core. Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down. Continue lifting until the barbell is slightly above shoulder level. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0107-S8mo30S.jpg', '/static/exercises/gifs/0107-S8mo30S.gif', '© Gym visual — https://gymvisual.com/', '240325'),
('100108', '杠铃站姿腿提踵', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。用小腿将脚跟抬离地面，尽可能高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0108', 'barbell standing leg calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart and place a barbell across your upper back. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0108-rGwhJ5o.jpg', '/static/exercises/gifs/0108-rGwhJ5o.gif', '© Gym visual — https://gymvisual.com/', '324'),
('100109', '杠铃站姿过顶肱三头肌臂屈伸', '肩部', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃。将杠铃举过头顶，充分伸展双臂。保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后伸展双臂将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0109', 'barbell standing overhead triceps extension', 'upper arms', '上臂', '50', 'barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip. Raise the barbell overhead, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then raise the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0109-dZl9Q27.jpg', '/static/exercises/gifs/0109-dZl9Q27.gif', '© Gym visual — https://gymvisual.com/', '400325'),
('100110', '杠铃站姿反向握弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。保持肘部靠近躯干，上臂保持静止。呼气并弯举杠铃，同时收缩二头肌，使杠铃尽可能靠近肩膀。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0110', 'barbell standing reverse grip curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0110-LWuA3aZ.jpg', '/static/exercises/gifs/0110-LWuA3aZ.gif', '© Gym visual — https://gymvisual.com/', '80326'),
('100111', '杠铃站姿摇摆腿提踵', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，将杠铃放在上背部。将脚跟抬离地面，尽可能高，用脚掌保持平衡。慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0111', 'barbell standing rocking leg calf raise', 'lower legs', '小腿', '70', 'barbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back. Raise your heels off the ground as high as possible, balancing on the balls of your feet. Slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0111-6HiHHe0.jpg', '/static/exercises/gifs/0111-6HiHHe0.gif', '© Gym visual — https://gymvisual.com/', '329'),
('100112', '杠铃站姿转体', '腹斜肌', '杠铃', '未分级', '双脚分开与肩同宽站立，双手握住杠铃于胸前，掌心朝下。在整个练习过程中启动你的核心并保持背部挺直。慢慢地将躯干向右扭转，以脚和臀部为轴，同时保持下半身稳定。扭转结束时暂停片刻，然后慢慢回到起始位置。向左侧重复扭转。继续交替扭转所需的重复次数。', 'exercise-dataset', '0112', 'barbell standing twist', 'waist', '腰腹', '60', 'barbell', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down. Engage your core and keep your back straight throughout the exercise. Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the left side. Continue alternating twists for the desired number of repetitions.', '/static/exercises/images/0112-yQe5HpE.jpg', '/static/exercises/gifs/0112-yQe5HpE.gif', '© Gym visual — https://gymvisual.com/', '900324'),
('101629', '杠铃站姿宽距握肱二头肌弯举', '前臂', '杠铃', '未分级', '双脚分开与肩同宽站立，反握握住杠铃，双手分开比肩宽。保持背部挺直，肘部靠近躯干。呼气并将杠铃向上弯向肩膀，保持上臂静止。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1629', 'barbell standing wide grip biceps curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart. Keep your back straight and your elbows close to your torso. Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1629-faHKVkK.jpg', '/static/exercises/gifs/1629-faHKVkK.gif', '© Gym visual — https://gymvisual.com/', '331'),
('101457', '杠铃站姿宽距军事推举', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握杠铃，握距略宽于肩。将杠铃举至肩膀高度，保持肘部稍微位于杠铃前方。将杠铃推过头顶，充分伸展双臂。将杠铃降低回肩部高度，然后重复所需的重复次数。', 'exercise-dataset', '1457', 'barbell standing wide military press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width. Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '/static/exercises/images/1457-Kyd9Rz5.jpg', '/static/exercises/gifs/1457-Kyd9Rz5.gif', '© Gym visual — https://gymvisual.com/', '900330'),
('100113', '杠铃站姿宽距握弯举', '前臂', '杠铃', '未分级', '站直，双脚分开与肩同宽，正手握住杠铃，双手分开比肩宽。让杠铃悬挂在大腿前面，与手掌保持一臂距离，手掌背向身体。保持上臂静止，呼气并通过收缩二头肌向上弯曲杠铃。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0113', 'barbell standing wide-grip curl', 'upper arms', '上臂', '50', 'barbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body. Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0113-NdIb5Z1.jpg', '/static/exercises/gifs/0113-NdIb5Z1.gif', '© Gym visual — https://gymvisual.com/', '80329'),
('100114', '杠铃踏步向上', '股四头肌', '杠铃', '未分级', '站在长凳或台阶前，将杠铃放在上背部。将一只脚放在长凳或台阶上，确保整个脚与表面接触。穿过你的脚后跟，走上长凳或台阶，充分伸展你的臀部和膝盖。在顶部短暂停顿，然后放低自己回到起始位置。用另一条腿重复上述步骤。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '0114', 'barbell step-up', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand in front of a bench or step with a barbell resting on your upper back. Place one foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your heel and step up onto the bench or step, fully extending your hip and knee. Pause briefly at the top, then lower yourself back down to the starting position. Repeat with the opposite leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/0114-Kxquu2E.jpg', '/static/exercises/gifs/0114-Kxquu2E.gif', '© Gym visual — https://gymvisual.com/', '900326'),
('100115', '杠铃直腿早安式', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将杠铃放在上背部，将其放在斜方肌上。保持背部挺直，臀部向前转动，将臀部向后推。降低躯干直到与地面平行，感觉腿筋被拉伸。启动臀肌和腿筋以返回起始位置。重复所需的重复次数。', 'exercise-dataset', '0115', 'barbell stiff leg good morning', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the barbell across your upper back, resting it on your traps. Keeping your back straight, hinge forward at the hips, pushing your glutes back. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Engage your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0115-JrOHAZc.jpg', '/static/exercises/gifs/0115-JrOHAZc.gif', '© Gym visual — https://gymvisual.com/', '900333'),
('100116', '杠铃直腿硬拉', '臀肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾指向前方。正手握住杠铃，双手分开略宽于肩宽。弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。降低杠铃，直到感觉到腿筋拉伸。启动腿筋和臀肌，将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0116', 'barbell straight leg deadlift', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","下背部"]', 'Stand with your feet shoulder-width apart and your toes pointing forward. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent. Lower the barbell until you feel a stretch in your hamstrings. Engage your hamstrings and glutes to lift the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0116-hrVQWvE.jpg', '/static/exercises/gifs/0116-hrVQWvE.gif', '© Gym visual — https://gymvisual.com/', '80332'),
('100117', '杠铃相扑硬拉', '腘绳肌', '杠铃', '未分级', '站立，双脚分开比肩宽，脚趾朝外。将杠铃放在您面前的地面上，位于双脚之间的中心。弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。重复所需的重复次数。', 'exercise-dataset', '0117', 'barbell sumo deadlift', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","下背部"]', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Place a barbell on the ground in front of you, centered between your feet. Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip. Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously. As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes. Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0117-KgI0tqW.jpg', '/static/exercises/gifs/0117-KgI0tqW.gif', '© Gym visual — https://gymvisual.com/', '80331'),
('103305', '杠铃深蹲推举', '股四头肌', '杠铃', '未分级', '首先，双脚分开与肩同宽站立，正手握住杠铃，与肩同高。弯曲膝盖并将臀部向后推，降低至蹲姿。当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将杠铃压过头顶。当你回到深蹲位置时，将杠铃降低到肩膀高度。重复所需的重复次数。', 'exercise-dataset', '3305', 'barbell thruster', 'shoulders', '肩部', '30', 'barbell', 'quadriceps', 'delts', '三角肌', '["股四头肌","臀肌","腘绳肌","核心肌群"]', 'Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip. Lower into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead. Lower the barbell back to shoulder height as you lower back into the squat position. Repeat for the desired number of repetitions.', '/static/exercises/images/3305-f7Y9eDZ.jpg', '/static/exercises/gifs/3305-f7Y9eDZ.gif', '© Gym visual — https://gymvisual.com/', '900330'),
('100120', '杠铃直立划船', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。让杠铃悬挂在大腿前面，双臂完全伸展。保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0120', 'barbell upright row', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0120-UDlhcO8.jpg', '/static/exercises/gifs/0120-UDlhcO8.gif', '© Gym visual — https://gymvisual.com/', '480333'),
('100119', '杠铃直立划船版本第二式', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。让杠铃悬挂在大腿前面，双臂完全伸展。保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0119', 'barbell upright row v. 2', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0119-83HoW9X.jpg', '/static/exercises/gifs/0119-83HoW9X.gif', '© Gym visual — https://gymvisual.com/', '480338'),
('100121', '杠铃直立划船版本第三式', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。让杠铃悬挂在大腿前面，双臂完全伸展。保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0121', 'barbell upright row v. 3', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0121-fI18Rbc.jpg', '/static/exercises/gifs/0121-fI18Rbc.gif', '© Gym visual — https://gymvisual.com/', '480339'),
('100122', '杠铃宽距卧推', '肩部', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。宽握距抓住杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。慢慢地将杠铃向胸部降低，保持肘部稍微张开。当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0122', 'barbell wide bench press', 'chest', '胸部', '10', 'barbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows slightly flared out. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0122-JsKq9so.jpg', '/static/exercises/gifs/0122-JsKq9so.gif', '© Gym visual — https://gymvisual.com/', '338'),
('101258', '杠铃宽距反握卧推', '肱三头肌', '杠铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。反握宽握杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1258', 'barbell wide reverse grip bench press', 'chest', '胸部', '10', 'barbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight. Pause for a moment when the barbell touches your chest, then push it back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1258-945zpRg.jpg', '/static/exercises/gifs/1258-945zpRg.gif', '© Gym visual — https://gymvisual.com/', '343'),
('100124', '杠铃宽距深蹲', '臀肌', '杠铃', '未分级', '站立，双脚分开比肩宽，脚趾稍微向外。将杠铃放在上背部，将其放在斜方肌或三角肌后束上。当你下蹲时，收紧你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0124', 'barbell wide squat', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold the barbell across your upper back, resting it on your traps or rear delts. Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0124-s7HX1BY.jpg', '/static/exercises/gifs/0124-s7HX1BY.gif', '© Gym visual — https://gymvisual.com/', '338'),
('100123', '杠铃宽距握直立划船', '斜方肌', '杠铃', '未分级', '双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。让杠铃悬挂在大腿前面，双臂完全伸展。保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0123', 'barbell wide-grip upright row', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart. Let the barbell hang in front of your thighs, arms fully extended. Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0123-RgJDRR1.jpg', '/static/exercises/gifs/0123-RgJDRR1.gif', '© Gym visual — https://gymvisual.com/', '480341'),
('100126', '杠铃腕弯举', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地面上，前臂放在大腿上，反握杠铃。让杠铃向下滚动到指尖，保持手腕伸直。弯曲手腕，慢慢地将杠铃向上卷向前臂。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0126', 'barbell wrist curl', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip. Allow the barbell to roll down to your fingertips, keeping your wrists straight. Slowly curl the barbell up towards your forearms by flexing your wrists. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0126-82LxxkW.jpg', '/static/exercises/gifs/0126-82LxxkW.gif', '© Gym visual — https://gymvisual.com/', '340'),
('100125', '杠铃腕弯举版本第二式', '肱二头肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地上，膝盖弯曲。反手握住杠铃，手掌朝上，双手与肩同宽。将前臂放在大腿上，让手腕悬在边缘。慢慢向上弯曲手腕，将杠铃拉向前臂。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0125', 'barbell wrist curl v. 2', 'lower arms', '前臂', '80', 'barbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and your knees bent. Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the barbell towards your forearms. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0125-6kSxYnw.jpg', '/static/exercises/gifs/0125-6kSxYnw.gif', '© Gym visual — https://gymvisual.com/', '345'),
('100127', '杠铃泽奇深蹲', '股四头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。保持膝盖与脚趾对齐，并将重量放在脚后跟上。在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '0127', 'barbell zercher squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability. Engage your core and keep your chest lifted as you lower your hips back and down into a squat position. Keep your knees in line with your toes and your weight in your heels. Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0127-LSTChY9.jpg', '/static/exercises/gifs/0127-LSTChY9.gif', '© Gym visual — https://gymvisual.com/', '342'),
('103212', '基础式脚尖触碰（男）', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂放在身体两侧。腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。双手向下伸向脚趾，尽可能保持双腿伸直。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3212', 'basic toe touch (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with your hands, keeping your legs as straight as possible. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3212-BbfB8Gb.jpg', '/static/exercises/gifs/3212-BbfB8Gb.gif', '© Gym visual — https://gymvisual.com/', '900245'),
('100128', '战绳', '前臂', '绳索', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。双手握住绳子的一端，手掌相对。将手臂举至肩膀高度，保持肘部稍微弯曲。快速抬起和放下每只手臂，开始用绳索产生交替的波浪。继续所需的持续时间或重复次数。', 'exercise-dataset', '0128', 'battling ropes', 'shoulders', '肩部', '30', 'rope', 'forearms', 'delts', '三角肌', '["前臂","核心肌群"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold one end of the rope in each hand, with your palms facing each other. Raise your arms to shoulder height, keeping your elbows slightly bent. Begin making alternating waves with the ropes by rapidly raising and lowering each arm. Continue for the desired duration or number of repetitions.', '/static/exercises/images/0128-RJa4tCo.jpg', '/static/exercises/gifs/0128-RJa4tCo.gif', '© Gym visual — https://gymvisual.com/', '901142'),
('103360', '熊爬式爬行', '核心肌群', '自重', '未分级', '从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。将膝盖稍微抬离地面，保持背部平坦并收紧核心。同时向前移动右手和左脚，然后是左手和右脚。继续向前爬行，手脚交替动作。在整个练习过程中保持稳定的节奏并保持核心紧张。继续所需的距离或时间。', 'exercise-dataset', '3360', 'bear crawl', 'cardio', '有氧', '90', 'body weight', 'core', 'cardiovascular system', '心肺系统', '["核心肌群","肩部","肱三头肌"]', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips. Lift your knees slightly off the ground, keeping your back flat and your core engaged. Move your right hand and left foot forward simultaneously, followed by your left hand and right foot. Continue crawling forward, alternating your hand and foot movements. Maintain a steady pace and keep your core tight throughout the exercise. Continue for the desired distance or time.', '/static/exercises/images/3360-0Yz8WdV.jpg', '/static/exercises/gifs/3360-0Yz8WdV.gif', '© Gym visual — https://gymvisual.com/', '900243'),
('101259', '颈后头后胸部拉伸', '肩部', '辅助器械', '未分级', '站直，双脚分开与肩同宽。将手指交叉放在脑后，肘部朝外。慢慢地将肩胛骨挤压在一起，并将胸部向前推。保持拉伸 15-30 秒。松开拉伸并根据需要重复。', 'exercise-dataset', '1259', 'behind head chest stretch', 'chest', '胸部', '10', 'assisted', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Stand tall with your feet shoulder-width apart. Interlace your fingers behind your head with your elbows pointing outwards. Slowly squeeze your shoulder blades together and push your chest forward. Hold the stretch for 15-30 seconds. Release the stretch and repeat as desired.', '/static/exercises/images/1259-QoHIhPl.jpg', '/static/exercises/gifs/1259-QoHIhPl.gif', '© Gym visual — https://gymvisual.com/', '901148'),
('100129', '训练凳臂屈伸双膝屈曲', '胸肌', '自重', '未分级', '坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。将臀部从长凳上滑下来，在身前伸直双腿，脚后跟保持在地面上。弯曲肘部，将身体放低至地面，保持背部靠近长凳。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0129', 'bench dip (knees bent)', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0129-RrLske5.jpg', '/static/exercises/gifs/0129-RrLske5.gif', '© Gym visual — https://gymvisual.com/', '480249'),
('101399', '训练凳臂屈伸地板', '胸肌', '自重', '未分级', '坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。将臀部滑离长凳，用手支撑体重。弯曲肘部降低身体，直到上臂与地板平行。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '1399', 'bench dip on floor', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1399-9RT8oQW.jpg', '/static/exercises/gifs/1399-9RT8oQW.gif', '© Gym visual — https://gymvisual.com/', '480250'),
('100130', '训练凳伸髋', '腘绳肌', '自重', '未分级', '坐在长凳上，背部靠在长凳上，双脚平放在地上。将双手放在长凳上以获得支撑。收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0130', 'bench hip extension', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Sit on a bench with your back against the bench and your feet flat on the ground. Place your hands on the bench for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0130-u27Kcdz.jpg', '/static/exercises/gifs/0130-u27Kcdz.gif', '© Gym visual — https://gymvisual.com/', '900249'),
('103019', '训练凳拉上撑', '肱二头肌', '自重', '未分级', '将自己置于与胸部同高的横杆或坚固的水平表面下方。正手握住杠铃或杠铃表面，握距略宽于肩宽。双臂完全伸展，身体伸直。将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。继续拉，直到下巴位于杆或表面上方。有控制地降低自己回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3019', 'bench pull-ups', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Position yourself under a bar or a sturdy horizontal surface that is at chest height. Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight. Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows. Continue pulling until your chin is above the bar or surface. Lower yourself back down to the starting position with control. Repeat for the desired number of repetitions.', '/static/exercises/images/3019-mExgrF9.jpg', '/static/exercises/gifs/3019-mExgrF9.gif', '© Gym visual — https://gymvisual.com/', '248'),
('103639', '屈曲膝仰卧转体（男）', '腹斜肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将手臂向两侧伸展，与身体垂直。保持膝盖并拢，慢慢地将它们降低到一侧，旨在用膝盖接触地面。暂停片刻，然后启动核心并慢慢将膝盖抬回到起始位置。到另一侧重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '3639', 'bent knee lying twist (male)', 'upper legs', '大腿', '40', 'body weight', 'obliques', 'glutes', '臀肌', '["腹斜肌","髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms out to the sides, perpendicular to your body. Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees. Pause for a moment, then engage your core and slowly lift your knees back to the starting position. Repeat the movement to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3639-6sYyrRX.jpg', '/static/exercises/gifs/3639-6sYyrRX.gif', '© Gym visual — https://gymvisual.com/', '900255'),
('101770', '肱二头肌腿集中弯举', '前臂', '自重', '未分级', '坐在长凳上，双腿分开，双脚平放在地上。一只手握住哑铃，将肘部放在大腿内侧，膝盖上方。手掌朝上，将哑铃向肩膀弯曲，同时保持上臂静止。在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1770', 'biceps leg concentration curl', 'upper arms', '上臂', '50', 'body weight', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your legs spread apart and your feet flat on the ground. Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee. With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1770-sJFIDIp.jpg', '/static/exercises/gifs/1770-sJFIDIp.gif', '© Gym visual — https://gymvisual.com/', '80254'),
('100139', '肱二头肌窄距拉上撑', '前臂', '自重', '未分级', '悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。在最高点暂停片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0139', 'biceps narrow pull-ups', 'upper arms', '上臂', '50', 'body weight', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart. Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0139-50BETrz.jpg', '/static/exercises/gifs/0139-50BETrz.gif', '© Gym visual — https://gymvisual.com/', '900253'),
('100140', '肱二头肌引体向上', '前臂', '自重', '未分级', '悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。在动作的最高点暂停，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0140', 'biceps pull-up', 'upper arms', '上臂', '50', 'body weight', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart. Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0140-guT8YnS.jpg', '/static/exercises/gifs/0140-guT8YnS.gif', '© Gym visual — https://gymvisual.com/', '900252'),
('100137', '身体向上', '胸肌', '自重', '未分级', '首先将双手放在凸起的表面上，例如长凳或双杠上，手掌朝下，手指向前。将双腿向前方伸展，脚跟保持在地面上，身体伸直。弯曲肘部降低身体，使其靠近身体两侧，直到上臂与地面平行。暂停片刻，然后用手掌伸直手臂，将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0137', 'body-up', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward. Extend your legs out in front of you, keeping your heels on the ground and your body straight. Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground. Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0137-U6G2gk9.jpg', '/static/exercises/gifs/0137-U6G2gk9.gif', '© Gym visual — https://gymvisual.com/', '900251'),
('103543', '自重下落跳跃深蹲', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。爆发性地跳起来，伸展臀部、膝盖和脚踝。在半空中时，快速将双脚并拢。脚掌轻轻着地，然后立即回到蹲姿。重复所需的重复次数。', 'exercise-dataset', '3543', 'bodyweight drop jump squat', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump up explosively, extending your hips, knees, and ankles. While in mid-air, quickly bring your feet together. Land softly on the balls of your feet and immediately drop back into a squat position. Repeat for the desired number of repetitions.', '/static/exercises/images/3543-wfotm7S.jpg', '/static/exercises/gifs/3543-wfotm7S.gif', '© Gym visual — https://gymvisual.com/', '258'),
('103544', '自重上斜侧平板支撑', '腹斜肌', '自重', '未分级', '首先侧躺，双腿伸展并叠放在一起。将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。启动你的核心并将臀部抬离地面，从头到脚形成一条直线。保持此位置所需的时间。将臀部放回到地面，然后在另一侧重复。', 'exercise-dataset', '3544', 'bodyweight incline side plank', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. Hold this position for the desired amount of time. Lower your hips back down to the ground and repeat on the other side.', '/static/exercises/images/3544-5VXmnV5.jpg', '/static/exercises/gifs/3544-5VXmnV5.gif', '© Gym visual — https://gymvisual.com/', '259'),
('101771', '自重跪姿肱三头肌臂屈伸', '肩部', '自重', '未分级', '跪在地上，膝盖分开与臀部同宽。将双手放在身前的地面上，与肩同宽，手指指向前方。将双腿伸直在身后，用脚趾和双手保持平衡，从头到脚跟形成一条直线。弯曲肘部，将上半身向地面降低，保持肘部靠近身体两侧。在底部停顿片刻，然后双手用力伸直手臂，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1771', 'bodyweight kneeling triceps extension', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌"]', 'Kneel down on the ground with your knees hip-width apart. Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward. Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels. Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides. Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1771-s0HKO2I.jpg', '/static/exercises/gifs/1771-s0HKO2I.gif', '© Gym visual — https://gymvisual.com/', '400260'),
('101769', '自重侧向仰卧肱二头肌弯举', '前臂', '自重', '未分级', '侧躺，双腿伸直，用手臂支撑头部。将上臂靠在身体两侧，弯曲肘部，将前臂卷向肩膀。在顶部暂停片刻，然后慢慢将前臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1769', 'bodyweight side lying biceps curl', 'upper arms', '上臂', '50', 'body weight', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie on your side with your legs extended and your head supported by your arm. Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1769-gscGLOU.jpg', '/static/exercises/gifs/1769-gscGLOU.gif', '© Gym visual — https://gymvisual.com/', '263'),
('103168', '自重深蹲划船', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，伸直手臂抓住坚固的物体或悬挂训练器。将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。从蹲姿开始，将身体向上拉向物体或悬挂训练器，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3168', 'bodyweight squatting row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended. Lower your body into a squat position, keeping your back straight and your knees behind your toes. From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3168-3xK09Sk.jpg', '/static/exercises/gifs/3168-3xK09Sk.gif', '© Gym visual — https://gymvisual.com/', '900260'),
('103167', '自重深蹲划船毛巾', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，手掌朝下，将毛巾放在身前。弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。当你下蹲时，同时将毛巾拉向胸部，将肩胛骨挤压在一起。在深蹲底部停顿片刻，然后慢慢回到起始位置，同时伸展双臂。重复所需的重复次数。', 'exercise-dataset', '3167', 'bodyweight squatting row (with towel)', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down. Bend your knees and lower your body into a squat position, keeping your back straight and your chest up. As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3167-BReCuOn.jpg', '/static/exercises/gifs/3167-BReCuOn.gif', '© Gym visual — https://gymvisual.com/', '900265'),
('101373', '自重站姿提踵', '踝部肌群', '自重', '未分级', '双脚分开与肩同宽站立，脚趾指向前方。将手放在墙壁或稳定的表面上以保持平衡。慢慢地将脚后跟抬离地面，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1373', 'bodyweight standing calf raise', 'lower legs', '小腿', '70', 'body weight', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand with your feet shoulder-width apart, toes pointing forward. Place your hands on a wall or stable surface for balance. Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1373-bJYHBIN.jpg', '/static/exercises/gifs/1373-bJYHBIN.gif', '© Gym visual — https://gymvisual.com/', '264'),
('103156', '自重站姿窄距握单臂划船', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，一只手握住哑铃，握姿中立。臀部向前弯曲，保持背部挺直，核心肌群参与。将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '3156', 'bodyweight standing close-grip one arm row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip. Bend forward at the hips, keeping your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/3156-v2DfH14.jpg', '/static/exercises/gifs/3156-v2DfH14.gif', '© Gym visual — https://gymvisual.com/', '400269'),
('103158', '自重站姿窄距握划船', '肱二头肌', '自重', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。腰部向前弯曲，保持背部挺直，核心肌群参与。将双臂伸直在身前，紧紧抓住杆或手柄。将杠铃或手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢松开并回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3158', 'bodyweight standing close-grip row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight in front of you, gripping the bar or handles with a close grip. Pull the bar or handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3158-tig3PXb.jpg', '/static/exercises/gifs/3158-tig3PXb.gif', '© Gym visual — https://gymvisual.com/', '900266'),
('103162', '自重站姿单臂划船', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，一手握住哑铃。臀部向前弯曲，保持背部挺直，核心肌群参与。让哑铃垂直悬挂在您面前，手臂完全伸展。将哑铃向上拉向胸部，保持肘部靠近身体。在动作的最高点将肩胛骨挤压在一起。将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '3162', 'bodyweight standing one arm row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand. Bend forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down in front of you, with your arm fully extended. Pull the dumbbell up towards your chest, keeping your elbow close to your body. Squeeze your shoulder blades together at the top of the movement. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/3162-xbkPfaw.jpg', '/static/exercises/gifs/3162-xbkPfaw.gif', '© Gym visual — https://gymvisual.com/', '400269'),
('103161', '自重站姿单臂划船毛巾', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。臀部向前弯曲，保持背部挺直，核心肌群参与。将毛巾拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将毛巾放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '3161', 'bodyweight standing one arm row (with towel)', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand. Bend forward at the hips, keeping your back straight and your core engaged. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the towel back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/3161-O4oIqQD.jpg', '/static/exercises/gifs/3161-O4oIqQD.gif', '© Gym visual — https://gymvisual.com/', '400274'),
('103166', '自重站姿划船', '肱二头肌', '自重', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杆或手柄，手掌朝下。保持背部挺直，核心参与。将杠铃或手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢释放并伸展双臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3166', 'bodyweight standing row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Grasp a bar or handles with an overhand grip, palms facing down. Keep your back straight and core engaged. Pull the bar or handles towards your body, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3166-wd4ds3s.jpg', '/static/exercises/gifs/3166-wd4ds3s.gif', '© Gym visual — https://gymvisual.com/', '900267'),
('103165', '自重站姿划船毛巾', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，双手握住毛巾放在身前。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将毛巾拉向胸部，将肩胛骨挤压在一起。在最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3165', 'bodyweight standing row (with towel)', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Stand with your feet shoulder-width apart and hold a towel in front of you with both hands. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3165-uTv34oq.jpg', '/static/exercises/gifs/3165-uTv34oq.gif', '© Gym visual — https://gymvisual.com/', '900272'),
('100138', '倒置', '腹斜肌', '自重', '未分级', '平躺，双腿伸展，双臂放在身体两侧。弯曲膝盖并将其靠近胸部，保持双脚离开地面。收紧腹肌，将臀部抬离地面，将膝盖靠近头部。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0138', 'bottoms-up', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and bring them towards your chest, keeping your feet off the ground. Engaging your abs, lift your hips off the ground, bringing your knees towards your head. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0138-CI6baTY.jpg', '/static/exercises/gifs/0138-CI6baTY.gif', '© Gym visual — https://gymvisual.com/', '900265'),
('101374', '跳箱跳跃向下单腿稳定', '股四头肌', '自重', '未分级', '站在盒子或平台前，双脚分开与肩同宽。弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。将放在盒子上的脚慢慢放下，回到起始位置。用另一条腿重复该练习。', 'exercise-dataset', '1374', 'box jump down with one leg stabilization', 'lower legs', '小腿', '70', 'body weight', 'quadriceps', 'calves', '小腿肌群', '["股四头肌","腘绳肌","臀肌"]', 'Stand in front of a box or platform with your feet shoulder-width apart. Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge. Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground. Hold this position for a few seconds, engaging your calf muscles to maintain balance. Slowly step down with the foot that is on the box, returning to the starting position. Repeat the exercise with the other leg.', '/static/exercises/images/1374-iPm26QU.jpg', '/static/exercises/gifs/1374-iPm26QU.gif', '© Gym visual — https://gymvisual.com/', '900278'),
('102466', '桥式登山跑跨体', '臀肌', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。启动你的核心并将右脚抬离地面，将右膝移向左肘。将右脚放回到起始位置，然后将左脚朝向右肘重复该动作。继续交替两侧，以受控的速度移动。保持臀部水平，避免臀部抬得太高或下垂得太低。在整个练习过程中保持稳定的呼吸模式。重复所需的重复次数。', 'exercise-dataset', '2466', 'bridge - mountain climber (cross body)', 'waist', '腰腹', '60', 'body weight', 'glutes', 'abs', '腹肌', '["臀肌","股四头肌","腘绳肌","肩部","肱三头肌"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow. Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow. Continue alternating sides, moving at a controlled pace. Keep your hips level and avoid lifting your hips too high or sagging them too low. Maintain a steady breathing pattern throughout the exercise. Repeat for the desired number of repetitions.', '/static/exercises/images/2466-9c6T1YX.jpg', '/static/exercises/gifs/2466-9c6T1YX.gif', '© Gym visual — https://gymvisual.com/', '900277'),
('101160', '波比跳', '股四头肌', '自重', '未分级', '从站立位置开始，双脚分开与肩同宽。弯曲膝盖并将双手放在身前的地板上，将身体降低至蹲姿。将脚踢回到俯卧撑位置。进行俯卧撑，保持身体呈一条直线。将双脚跳回蹲姿。爆发性地跳起，将双臂举过头顶。轻轻落地并立即回到蹲姿，开始下一次重复。', 'exercise-dataset', '1160', 'burpee', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群","肩部","胸肌"]', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position. Perform a push-up, keeping your body in a straight line. Jump your feet back into the squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into a squat position to begin the next repetition.', '/static/exercises/images/1160-dK9394r.jpg', '/static/exercises/gifs/1160-dK9394r.gif', '© Gym visual — https://gymvisual.com/', '240268'),
('100870', '臀部上抬上撑', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在身体两侧，掌心朝下。收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。在动作的最高点，挤压腹肌并暂停片刻。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0870', 'butt-ups', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest. At the top of the movement, squeeze your abs and pause for a moment. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0870-qcNN2FN.jpg', '/static/exercises/gifs/0870-qcNN2FN.gif', '© Gym visual — https://gymvisual.com/', '900269'),
('101494', '蝴蝶式瑜伽姿势', '腘绳肌', '自重', '未分级', '坐在地板上，双腿伸到身前。弯曲膝盖，将脚底并拢，让膝盖向两侧倾斜。用手抓住脚踝或脚。坐直并拉长脊柱。轻轻地将膝盖压向地板，感觉大腿内侧有拉伸感。保持这个姿势几个呼吸。要放松，请慢慢抬起膝盖并伸展双腿。', 'exercise-dataset', '1494', 'butterfly yoga pose', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'adductors', '内收肌群', '["腘绳肌","腹股沟"]', 'Sit on the floor with your legs extended in front of you. Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides. Hold onto your ankles or feet with your hands. Sit up tall and lengthen your spine. Gently press your knees down towards the floor, feeling a stretch in your inner thighs. Hold this position for a few breaths. To release, slowly bring your knees back up and extend your legs.', '/static/exercises/images/1494-bWlZvXh.jpg', '/static/exercises/gifs/1494-bWlZvXh.gif', '© Gym visual — https://gymvisual.com/', '900274'),
('100148', '绳索交替肩上推举', '肱三头肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，并用正手握住绳索机的手柄。将双手放在与肩同高的位置，手掌朝前。保持核心参与并保持背部挺直。向上并向前按下一个手柄，直到您的手臂完全伸展。在最高点暂停片刻，然后慢慢将手柄放回起始位置。用另一只手臂重复上述步骤。双臂交替进行所需的重复次数。', 'exercise-dataset', '0148', 'cable alternate shoulder press', 'shoulders', '肩部', '30', 'cable', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip. Position your hands at shoulder height, with your palms facing forward. Keep your core engaged and your back straight. Press one handle up and forward until your arm is fully extended. Pause for a moment at the top, then slowly lower the handle back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', '/static/exercises/images/0148-KHPZL0b.jpg', '/static/exercises/gifs/0148-KHPZL0b.gif', '© Gym visual — https://gymvisual.com/', '577'),
('100149', '绳索交替肱三头肌臂屈伸', '肩部', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。右手握住电缆手柄，抬起手臂，使上臂与地面平行，肘部弯曲成 90 度角。保持上臂静止，前臂向后伸展，完全伸直手臂。暂停片刻，然后慢慢回到起始位置。用左臂重复此动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0149', 'cable alternate triceps extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle. Keep your upper arm stationary and extend your forearm backward, fully straightening your arm. Pause for a moment, then slowly return to the starting position. Repeat with your left arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0149-Gchi5Tr.jpg', '/static/exercises/gifs/0149-Gchi5Tr.gif', '© Gym visual — https://gymvisual.com/', '400578'),
('103235', '绳索辅助反向腿弯举', '臀肌', '绳索器械', '未分级', '调整缆绳机，使脚踝附件处于最低设置。面朝下躺在长凳上，双腿伸直，将脚踝固定装置固定在脚踝上。握住长凳的把手以保持稳定。保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。在动作的最高点暂停片刻，挤压你的腿筋。吸气并慢慢降低双腿回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3235', 'cable assisted inverse leg curl', 'upper legs', '大腿', '40', 'cable', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Adjust the cable machine so that the ankle attachment is at the lowest setting. Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles. Hold onto the handles of the bench for stability. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees. Pause for a moment at the top of the movement, squeezing your hamstrings. Inhale and slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3235-zHEpuuc.jpg', '/static/exercises/gifs/3235-zHEpuuc.gif', '© Gym visual — https://gymvisual.com/', '480581'),
('100150', '绳索杆侧向下拉', '肱二头肌', '绳索器械', '未分级', '将电缆滑轮调整至较高位置并安装直杆。面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。正手握住杠铃，握距略宽于肩宽。稍微向后倾斜，挺胸，保持下背部轻微的拱形。将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0150', 'cable bar lateral pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the cable pulley to a high position and attach a straight bar. Sit facing the cable machine with your feet flat on the ground and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back. Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0150-eYnzaCm.jpg', '/static/exercises/gifs/0150-eYnzaCm.gif', '© Gym visual — https://gymvisual.com/', '80580'),
('100151', '绳索卧推', '肱三头肌', '绳索器械', '未分级', '将绳索机调整至胸部高度并安装手柄。背对机器站立，双脚与肩同宽。正手握住手柄并向前迈一步，以在电缆中产生张力。将双脚牢牢放在地面上并启动核心。弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。向前推动手柄，将双臂完全伸展到身前。暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。重复所需的重复次数。', 'exercise-dataset', '0151', 'cable bench press', 'chest', '胸部', '10', 'cable', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the cable machine to chest height and attach the handles. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step forward to create tension in the cables. Position your feet firmly on the ground and engage your core. Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle. Push the handles forward, extending your arms fully in front of you. Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0151-7xI5MXA.jpg', '/static/exercises/gifs/0151-7xI5MXA.gif', '© Gym visual — https://gymvisual.com/', '579'),
('101630', '绳索窄距握弯举', '前臂', '绳索器械', '未分级', '将直杆连接到低滑轮电缆机上。面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。反手握住杠铃，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。呼气并将杠铃向上卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1630', 'cable close grip curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1630-BCGQ6J5.jpg', '/static/exercises/gifs/1630-BCGQ6J5.gif', '© Gym visual — https://gymvisual.com/', '80582'),
('101631', '绳索集中弯举', '前臂', '绳索器械', '未分级', '坐在长凳或椅子上，双脚平放在地板上，膝盖稍微弯曲。用手握住电缆手柄，并将肘部靠在大腿内侧。保持上臂静止，呼气并将电缆手柄向肩膀卷曲，同时收缩二头肌。在动作的最高点暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1631', 'cable concentration curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench or chair with your feet flat on the floor and your knees slightly bent. Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh. Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps. Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1631-NvfE43H.jpg', '/static/exercises/gifs/1631-NvfE43H.gif', '© Gym visual — https://gymvisual.com/', '80581'),
('100152', '绳索集中式伸展膝', '前臂', '绳索器械', '未分级', '坐在长凳或椅子上，膝盖弯曲，双脚平放在地上。用右手握住电缆手柄，并将肘部放在右膝盖内侧。充分伸展手臂，保持肘部静止并靠近膝盖。在顶部停顿片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0152', 'cable concentration extension (on knee)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Sit on a bench or chair with your knees bent and feet flat on the ground. Hold the cable handle with your right hand and place your elbow on the inside of your right knee. Extend your arm fully, keeping your elbow stationary and close to your knee. Pause for a moment at the top, then slowly lower your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0152-Db7eEgw.jpg', '/static/exercises/gifs/0152-Db7eEgw.gif', '© Gym visual — https://gymvisual.com/', '900586'),
('100153', '绳索交叉越过侧向下拉', '肱二头肌', '绳索器械', '未分级', '将电缆手柄连接到电缆机器两侧与肩同高的位置。站在机器中间，双脚分开与肩同宽。正手握住手柄并后退以在电缆中产生张力。从臀部开始稍微向前倾，保持背部挺直，挺胸。将手柄向下拉并穿过身体，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0153', 'cable cross-over lateral pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Attach a cable handle to each side of a cable machine at shoulder height. Stand in the middle of the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and step back to create tension in the cables. Lean forward slightly from the hips, keeping your back straight and your chest up. Pull the handles down and across your body, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0153-OQ1otBN.jpg', '/static/exercises/gifs/0153-OQ1otBN.gif', '© Gym visual — https://gymvisual.com/', '80585'),
('100154', '绳索交叉越过反向飞鸟', '菱形肌', '绳索器械', '未分级', '将 D 形手柄连接到每根低滑轮电缆上，并站在电缆交叉机的中间。旋前抓住手柄（手掌朝下），向前迈出一步，双脚分开与肩同宽。稍微弯曲膝盖，腰部前倾，保持背部挺直，腹部收紧。双臂向两侧伸展，肘部稍微弯曲，呼气并将肩胛骨挤压在一起，同时以反向飞翔动作向后和向上拉动绳索。在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0154', 'cable cross-over revers fly', 'shoulders', '肩部', '30', 'cable', 'rhomboids', 'delts', '三角肌', '["菱形肌","斜方肌"]', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine. Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart. Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged. With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0154-aqvSOQE.jpg', '/static/exercises/gifs/0154-aqvSOQE.gif', '© Gym visual — https://gymvisual.com/', '900586'),
('100155', '绳索交叉越过变式', '三角肌', '绳索器械', '未分级', '将电缆滑轮调整至胸部高度。站在电缆机的中央，一只脚在另一只脚前面。手掌朝下抓住手柄，手臂向两侧伸展。向前迈出一步，保持手臂稍微弯曲。肘部稍微弯曲，双手并拢放在胸前。暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0155', 'cable cross-over variation', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Adjust the cable pulleys to chest height. Stand in the center of the cable machine with one foot in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides. Take a step forward, keeping your arms slightly bent. With a slight bend in your elbows, bring your hands together in front of your chest. Pause for a moment, then slowly return your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0155-0CXGHya.jpg', '/static/exercises/gifs/0155-0CXGHya.gif', '© Gym visual — https://gymvisual.com/', '900585'),
('100868', '绳索弯举', '前臂', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。用手握住电缆附件，手掌朝上。保持肘部靠近身体两侧，上臂保持静止。呼气并将电缆附件卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并缓慢地将电缆附件放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0868', 'cable curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0868-G08RZcQ.jpg', '/static/exercises/gifs/0868-G08RZcQ.gif', '© Gym visual — https://gymvisual.com/', '80584'),
('100157', '绳索硬拉', '腘绳肌', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。弯曲臀部和膝盖，降低躯干，直到背部与地面平行。正手握住电缆手柄，保持手臂伸直，肩膀向后。调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0157', 'cable deadlift', 'upper legs', '大腿', '40', 'cable', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","下背部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Bend at the hips and knees, lowering your torso until your back is parallel to the ground. Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back. Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight. Pause for a moment at the top, then slowly lower the cable handles back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0157-eGDudUV.jpg', '/static/exercises/gifs/0157-eGDudUV.gif', '© Gym visual — https://gymvisual.com/', '80585'),
('100158', '绳索下斜飞鸟', '肩部', '绳索器械', '未分级', '将拉线机调整至下降位置。背对机器站立，双脚与肩同宽。握住手柄，手掌朝前，双臂在身前伸直。保持肘部轻微弯曲，以受控的动作向两侧张开双臂。在完全伸展位置停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0158', 'cable decline fly', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the cable machine to a decline position. Stand facing away from the machine with your feet shoulder-width apart. Hold the handles with your palms facing forward and your arms extended straight out in front of you. Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion. Pause for a moment at the fully extended position, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0158-7saC5zz.jpg', '/static/exercises/gifs/0158-7saC5zz.gif', '© Gym visual — https://gymvisual.com/', '900588'),
('101260', '绳索下斜单臂推举', '肱三头肌', '绳索器械', '未分级', '将拉线机调整至下降位置。背对机器站立，用一只手抓住手柄。将背部靠在下斜长凳上，手臂伸直在身前。弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。在底部暂停片刻，然后将手柄推回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1260', 'cable decline one arm press', 'chest', '胸部', '10', 'cable', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the cable machine to a decline position. Stand facing away from the machine and grab the handle with one hand. Position yourself with your back against the decline bench and your arm extended straight in front of you. Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary. Pause for a moment at the bottom, then push the handle back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1260-KHGNa16.jpg', '/static/exercises/gifs/1260-KHGNa16.gif', '© Gym visual — https://gymvisual.com/', '900593'),
('101261', '绳索下斜推举', '肱三头肌', '绳索器械', '未分级', '将拉线机调整至下降位置。坐在面向缆绳机的下降长凳上。正手握住手柄并将其置于胸部水平。将双脚平放在地面上，并将背部牢牢靠在长凳上。呼气并将手柄推离身体，充分伸展双臂。动作结束时暂停片刻，挤压胸部肌肉。吸气并慢慢地将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1261', 'cable decline press', 'chest', '胸部', '10', 'cable', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the cable machine to a decline position. Sit on the decline bench facing the cable machine. Grasp the handles with an overhand grip and position them at chest level. Keep your feet flat on the ground and your back firmly against the bench. Exhale and push the handles away from your body, extending your arms fully. Pause for a moment at the end of the movement, squeezing your chest muscles. Inhale and slowly return the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1261-2Pya1cP.jpg', '/static/exercises/gifs/1261-2Pya1cP.gif', '© Gym visual — https://gymvisual.com/', '900590'),
('100159', '绳索下斜坐姿宽距握划船', '肱二头肌', '绳索器械', '未分级', '坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。用宽的正手握法抓住电缆附件，手掌朝下。稍微向后倾斜，保持背部挺直，核心肌群参与。将电缆拉向下胸部，将肩胛骨挤压在一起。在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0159', 'cable decline seated wide-grip row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the decline bench facing the cable machine with your feet securely placed on the footrests. Grasp the cable attachment with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your core engaged. Pull the cable towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0159-kesXOpB.jpg', '/static/exercises/gifs/0159-kesXOpB.gif', '© Gym visual — https://gymvisual.com/', '900595'),
('101632', '绳索拖拽式弯举', '前臂', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。用手握住电缆附件，手掌朝上，手臂完全伸展。保持上臂静止，呼气并通过收缩二头肌将电缆附件卷曲至肩膀。在动作的最高点暂停片刻，挤压你的二头肌。吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1632', 'cable drag curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended. Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1632-dXz8zjF.jpg', '/static/exercises/gifs/1632-dXz8zjF.gif', '© Gym visual — https://gymvisual.com/', '80592'),
('100160', '绳索地板坐姿宽距握划船', '肱二头肌', '绳索器械', '未分级', '坐在地板上，双腿伸直，背部挺直。将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。正手宽握握住手柄，手掌朝下。稍微向后倾斜，保持背部挺直，挺胸。将手柄拉向腰部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0160', 'cable floor seated wide-grip row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the floor with your legs extended and your back straight. Attach a cable handle to a low pulley and position the cable machine behind you. Grasp the handle with a wide overhand grip, palms facing down. Lean back slightly, keeping your back straight and your chest lifted. Pull the handle towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0160-veXwo0D.jpg', '/static/exercises/gifs/0160-veXwo0D.gif', '© Gym visual — https://gymvisual.com/', '900597'),
('100161', '绳索向前上举', '肱三头肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住电缆手柄，手掌朝下，双臂在身前完全伸展。保持手臂伸直，将电缆手柄抬高至肩部水平。在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0161', 'cable forward raise', 'shoulders', '肩部', '30', 'cable', 'triceps', 'delts', '三角肌', '["肱三头肌","前臂"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you. Keeping your arms straight, raise the cable handle up to shoulder level. Pause for a moment at the top, then slowly lower the cable handle back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0161-hvHhCv8.jpg', '/static/exercises/gifs/0161-hvHhCv8.gif', '© Gym visual — https://gymvisual.com/', '900594'),
('100162', '绳索前侧上举', '肱三头肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，并用正手握住电缆手柄。保持背部挺直，核心肌群参与。将电缆手柄举到您面前，保持手臂伸直，手掌朝下。继续抬起，直到手臂与地板平行。在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0162', 'cable front raise', 'shoulders', '肩部', '30', 'cable', 'triceps', 'delts', '三角肌', '["肱三头肌","前臂"]', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down. Continue lifting until your arms are parallel to the floor. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0162-u2X71Np.jpg', '/static/exercises/gifs/0162-u2X71Np.gif', '© Gym visual — https://gymvisual.com/', '240595'),
('100164', '绳索前侧肩部上举', '斜方肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，并用正手握住电缆手柄。保持背部挺直，核心肌群参与。将电缆手柄举到您面前，保持手臂伸直，手掌朝下。继续抬起，直到手臂与地板平行。在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0164', 'cable front shoulder raise', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip. Keep your back straight and your core engaged. Raise the cable handle in front of you, keeping your arms straight and your palms facing down. Continue lifting until your arms are parallel to the floor. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0164-mTT3KLn.jpg', '/static/exercises/gifs/0164-mTT3KLn.gif', '© Gym visual — https://gymvisual.com/', '900598'),
('100165', '绳索锤式弯举绳索', '前臂', '绳索器械', '未分级', '站直，双脚分开与肩同宽，膝盖稍微弯曲。双手握住缆绳附件，手掌相对，手臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续提升缆绳附件，直到您的二头肌完全收缩并且绳索与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将缆绳附件降低回起始位置。重复所需的重复次数。', 'exercise-dataset', '0165', 'cable hammer curl (with rope)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand upright with your feet shoulder-width apart and a slight bend in your knees. Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the cable rope attachment back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0165-HPlPoQA.jpg', '/static/exercises/gifs/0165-HPlPoQA.gif', '© Gym visual — https://gymvisual.com/', '80601'),
('101722', '绳索高位滑轮过顶肱三头肌伸展', '肩部', '绳索器械', '未分级', '将绳子连接到高滑轮上，背对机器站立。双手抓住绳子，并将双臂伸过头顶。保持肘部靠近头部，上臂保持静止。弯曲肘部，慢慢将绳子降低到头后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1722', 'cable high pulley overhead tricep extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope to a high pulley and stand facing away from the machine. Grasp the rope with both hands and extend your arms overhead. Keep your elbows close to your head and your upper arms stationary. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1722-1xHyxys.jpg', '/static/exercises/gifs/1722-1xHyxys.gif', '© Gym visual — https://gymvisual.com/', '900604'),
('100167', '绳索高位划船跪姿', '肱二头肌', '绳索器械', '未分级', '将直杆连接到胸部高度的缆绳机上。跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。坐在脚后跟上，保持背部挺直，核心肌群参与。将杠铃拉向上腹部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0167', 'cable high row (kneeling)', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Attach a straight bar to a cable machine at chest height. Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart. Sit back on your heels, keeping your back straight and your core engaged. Pull the bar towards your upper abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0167-ZSJNetl.jpg', '/static/exercises/gifs/0167-ZSJNetl.gif', '© Gym visual — https://gymvisual.com/', '900601'),
('100168', '绳索髋内收', '臀肌', '绳索器械', '未分级', '将脚踝套戴到脚踝上，面向电缆机站立。将自己放置在距离机器足够远的位置，以便电缆上有张力。将手放在机器上以获得支撑。保持腿伸直，慢慢将腿移向身体中线。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0168', 'cable hip adduction', 'upper legs', '大腿', '40', 'cable', 'glutes', 'adductors', '内收肌群', '["臀肌","股四头肌"]', 'Attach the ankle cuff to your ankle and stand facing the cable machine. Position yourself far enough away from the machine so that there is tension on the cable. Place your hands on the machine for support. Keeping your leg straight, slowly move your leg across your body towards the midline. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0168-hBGWILP.jpg', '/static/exercises/gifs/0168-hBGWILP.gif', '© Gym visual — https://gymvisual.com/', '900600'),
('100169', '绳索上斜卧推', '三角肌', '绳索器械', '未分级', '将长凳调整至 45 度倾斜。将电缆手柄连接到高滑轮上。坐在长凳上，面向电缆机，双脚平放在地面上。正手握住手柄，并将其拉至肩部高度。向前和向上推动手柄，直到手臂完全伸展。暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0169', 'cable incline bench press', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Adjust the bench to a 45-degree incline. Attach the cable handles to the high pulleys. Sit on the bench facing the cable machine with your feet flat on the ground. Grasp the handles with an overhand grip and bring them to shoulder height. Push the handles forward and upward until your arms are fully extended. Pause for a moment, then slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0169-Vh0GsK4.jpg', '/static/exercises/gifs/0169-Vh0GsK4.gif', '© Gym visual — https://gymvisual.com/', '603'),
('101318', '绳索上斜训练凳划船', '肱二头肌', '绳索器械', '未分级', '以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。正手握住电缆手柄，并将双臂完全伸展到身前。从臀部开始向前倾，同时保持背部挺直，核心肌群参与。缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1318', 'cable incline bench row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","后侧DELTOIDS"]', 'Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley. Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the cable handle with an overhand grip and extend your arms fully in front of you. Lean forward from your hips while keeping your back straight and your core engaged. Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows. Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1318-yaMIo4D.jpg', '/static/exercises/gifs/1318-yaMIo4D.gif', '© Gym visual — https://gymvisual.com/', '900604'),
('100171', '绳索上斜飞鸟', '三角肌', '绳索器械', '未分级', '将电缆机调整至较低位置并安装手柄。坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地板上。正手握住手柄，并将双臂伸直至身前。保持肘部轻微弯曲，以受控的动作向两侧张开双臂。在完全伸展位置停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0171', 'cable incline fly', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Adjust the cable machine to a low position and attach the handles. Sit on an incline bench with your back against the pad and feet flat on the floor. Grasp the handles with an overhand grip and extend your arms straight out in front of you. Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion. Pause for a moment at the fully extended position, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0171-tBWXbIT.jpg', '/static/exercises/gifs/0171-tBWXbIT.gif', '© Gym visual — https://gymvisual.com/', '900603'),
('100170', '绳索上斜飞鸟瑞士球', '三角肌', '绳索器械', '未分级', '以倾斜角度设置稳定球。将电缆手柄连接到电缆机的高滑轮上。背对机器坐在稳定球上，双脚牢牢踩在地面上。正手握住电缆手柄，手掌朝前。稍微向前倾，保持背部挺直，核心参与。控制动作，将手臂向两侧伸出，保持肘部轻微弯曲。继续这个动作，直到手臂与地面平行。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0170', 'cable incline fly (on stability ball)', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Set up a stability ball at an incline angle. Attach the cable handles to the high pulleys of a cable machine. Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground. Grasp the cable handles with an overhand grip, palms facing forward. Lean forward slightly, keeping your back straight and core engaged. With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows. Continue the motion until your arms are parallel to the ground. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0170-27NNGFr.jpg', '/static/exercises/gifs/0170-27NNGFr.gif', '© Gym visual — https://gymvisual.com/', '900610'),
('100172', '绳索上斜下压', '肱三头肌', '绳索器械', '未分级', '将直杆连接到高滑轮电缆机上。背对机器站立，双脚与肩同宽。正手握住杠铃，双手距离略宽于肩宽。稍微向前倾并保持背部挺直。伸展肘部，将杠铃向下拉向大腿。在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0172', 'cable incline pushdown', 'back', '背部', '20', 'cable', 'triceps', 'lats', '背阔肌', '["肱三头肌","肩部"]', 'Attach a straight bar to a high pulley cable machine. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Lean forward slightly and keep your back straight. Pull the bar down towards your thighs by extending your elbows. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0172-1PK5Uo3.jpg', '/static/exercises/gifs/0172-1PK5Uo3.gif', '© Gym visual — https://gymvisual.com/', '900605'),
('100173', '绳索上斜肱三头肌臂屈伸', '肩部', '绳索器械', '未分级', '将拉索机调整至低滑轮位置。将直杆连接到电缆上。背对机器站立，双脚与肩同宽。正手握住杠铃，并将手臂伸直过头顶。稍微向前倾，保持背部挺直，核心参与。弯曲肘部，将杠铃放低到脑后，保持上臂靠近耳朵。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0173', 'cable incline triceps extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Adjust the cable machine to a low pulley position. Attach a straight bar to the cable. Stand facing away from the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip and extend your arms straight overhead. Lean forward slightly, keeping your back straight and core engaged. Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0173-Hx1WC8I.jpg', '/static/exercises/gifs/0173-Hx1WC8I.gif', '© Gym visual — https://gymvisual.com/', '400608'),
('100174', '绳索柔道式翻转', '腹斜肌', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。用双手握住电缆手柄，使其与胸部齐平，手掌朝下。启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。当你旋转时，转动后脚并让臀部自然旋转。充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。通过反向运动返回起始位置，将躯干旋转回中心。在另一侧重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0174', 'cable judo flip', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands at chest level, palms facing down. Engage your core and rotate your torso to the right, pulling the cable across your body. As you rotate, pivot your back foot and allow your hips to rotate naturally. Extend your arms fully and finish the movement by flipping the cable handle over your shoulder. Return to the starting position by reversing the movement, rotating your torso back to the center. Repeat the movement on the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0174-MvQPqVW.jpg', '/static/exercises/gifs/0174-MvQPqVW.gif', '© Gym visual — https://gymvisual.com/', '900607'),
('100860', '绳索后踢', '肩部', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。用右手握住电缆手柄并后退以在电缆中产生张力。稍微弯曲膝盖，髋部向前转动，保持背部挺直。保持上臂靠近身体，肘部弯曲成 90 度角。向后伸展前臂，完全伸直手臂。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0860', 'cable kickback', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable handle with your right hand and step back to create tension in the cable. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Keep your upper arm close to your body and your elbow bent at a 90-degree angle. Extend your forearm backward, straightening your arm fully. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0860-HEJ6DIX.jpg', '/static/exercises/gifs/0860-HEJ6DIX.gif', '© Gym visual — https://gymvisual.com/', '560606'),
('100175', '绳索跪姿卷腹', '腹斜肌', '绳索器械', '未分级', '将绳索手柄连接到高滑轮上，然后面向远离机器的方向跪下。双手握住绳柄，将其放在脑后，肘部向两侧伸出。保持臀部不动，弯曲腰部并将躯干向大腿方向挤压。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0175', 'cable kneeling crunch', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach a rope handle to a high pulley and kneel down facing away from the machine. Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides. Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0175-WW95auq.jpg', '/static/exercises/gifs/0175-WW95auq.gif', '© Gym visual — https://gymvisual.com/', '80609'),
('103697', '绳索跪姿三角肌后束划船绳索（男）', '斜方肌', '绳索器械', '未分级', '将绳索手柄连接到低电缆滑轮上，面向机器跪下。以中立握法（手掌相对）抓住绳子，并将双臂完全伸展到身前。保持背部挺直，核心收紧，通过收缩肩胛骨将绳子拉向身体。在动作结束时将肩胛骨挤压在一起并保持短暂的停顿。慢慢释放张力并回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3697', 'cable kneeling rear delt row (with rope) (male)', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Attach a rope handle to a low cable pulley and kneel down facing the machine. Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you. Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades. Squeeze your shoulder blades together at the end of the movement and hold for a brief pause. Slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3697-G61cXLk.jpg', '/static/exercises/gifs/3697-G61cXLk.gif', '© Gym visual — https://gymvisual.com/', '400620'),
('100176', '绳索跪姿肱三头肌臂屈伸', '肩部', '绳索器械', '未分级', '将绳索手柄连接到高滑轮上，面向绳索机跪下。以中立握法（手掌相对）抓住绳子，并将双手放在头的两侧。在整个练习过程中，保持肘部靠近头部，上臂保持静止。通过收缩三头肌来伸展前臂，直到手臂完全伸展。暂停片刻，然后弯曲肘部慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0176', 'cable kneeling triceps extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope handle to a high pulley and kneel down facing the cable machine. Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head. Keep your elbows close to your head and your upper arms stationary throughout the exercise. Extend your forearms by contracting your triceps until your arms are fully extended. Pause for a moment, then slowly return to the starting position by bending your elbows. Repeat for the desired number of repetitions.', '/static/exercises/images/0176-KWdF2JI.jpg', '/static/exercises/gifs/0176-KWdF2JI.gif', '© Gym visual — https://gymvisual.com/', '400613'),
('102330', '绳索高位下拉全程幅度动态', '肱二头肌', '绳索器械', '未分级', '坐在高位下拉机上，膝盖位于护垫下方。正手握住电缆杆，握距略宽于肩宽。稍微向后倾斜，挺胸，保持下背部轻微的拱形。将杠铃向下拉至上胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2330', 'cable lat pulldown full range of motion', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Sit on the lat pulldown machine with your knees positioned under the pads. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and keep your chest up, maintaining a slight arch in your lower back. Pull the bar down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2330-LEprlgG.jpg', '/static/exercises/gifs/2330-LEprlgG.gif', '© Gym visual — https://gymvisual.com/', '80620'),
('100177', '绳索侧向下拉绳索把手', '肱二头肌', '绳索器械', '未分级', '将绳索附件连接到电缆机的高位置。面向机器站立，双脚分开与肩同宽。正手握住绳子，手掌相对。保持背部挺直并稍微向后倾斜。将绳子向下拉向身体两侧，将肩胛骨挤压在一起。在动作的底部停顿片刻。慢慢释放张力，让绳子回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0177', 'cable lateral pulldown (with rope attachment)', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach a rope attachment to the cable machine at a high position. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing each other. Keep your back straight and lean slightly back. Pull the rope down towards your sides, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement. Slowly release the tension and allow the rope to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0177-CuaWCmC.jpg', '/static/exercises/gifs/0177-CuaWCmC.gif', '© Gym visual — https://gymvisual.com/', '80619'),
('102616', '绳索侧向下拉V字杆', '肱二头肌', '绳索器械', '未分级', '坐在电缆下拉机上，用正手抓住 V 形杆附件。调整护膝，使大腿固定在其下方。保持背部挺直并稍微向后倾斜。将 V 形杆向下拉至上胸部，同时保持肘部靠近身体。在动作底部挤压背部肌肉。慢慢地将 v 形杆返回到起始位置，然后重复所需的重复次数。', 'exercise-dataset', '2616', 'cable lateral pulldown with v-bar', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip. Adjust the knee pad so that your thighs are secured under it. Keep your back straight and lean back slightly. Pull the v-bar down towards your upper chest while keeping your elbows close to your body. Squeeze your back muscles at the bottom of the movement. Slowly return the v-bar to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/2616-4c9BhzB.jpg', '/static/exercises/gifs/2616-4c9BhzB.gif', '© Gym visual — https://gymvisual.com/', '80618'),
('100178', '绳索侧平举', '斜方肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，并用正手握住电缆手柄。保持双臂伸直，核心肌群参与。将手臂向两侧举起，直到与地板平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0178', 'cable lateral raise', 'shoulders', '肩部', '30', 'cable', 'traps', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip. Keep your arms straight and your core engaged. Raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0178-goJ6ezq.jpg', '/static/exercises/gifs/0178-goJ6ezq.gif', '© Gym visual — https://gymvisual.com/', '160615'),
('100179', '绳索低位飞鸟', '三角肌', '绳索器械', '未分级', '将手柄连接到缆绳机的低滑轮上，并选择合适的重量。站在机器中间，双脚分开与肩同宽，膝盖稍微弯曲。正手握住手柄，将手臂向两侧伸展，肘部保持轻微弯曲。保持控制，以扫过的动作缓慢地将手臂向前伸，交叉在身体前面。在运动的最高点暂停片刻，感受胸部肌肉的拉伸。反转动作，慢慢将手臂恢复到起始位置，始终保持胸部肌肉紧张。重复所需的重复次数。', 'exercise-dataset', '0179', 'cable low fly', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Attach the handles to the low pulleys of a cable machine and select an appropriate weight. Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows. Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body. Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles. Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout. Repeat for the desired number of repetitions.', '/static/exercises/images/0179-FVmZVhk.jpg', '/static/exercises/gifs/0179-FVmZVhk.gif', '© Gym visual — https://gymvisual.com/', '900616'),
('100180', '绳索低位坐姿划船', '肱二头肌', '绳索器械', '未分级', '坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。正手握住手柄，手掌朝下。保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。将手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0180', 'cable low seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with an overhand grip, palms facing down. Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0180-hvV79Si.jpg', '/static/exercises/gifs/0180-hvV79Si.gif', '© Gym visual — https://gymvisual.com/', '240619'),
('101634', '绳索仰卧肱二头肌弯举', '前臂', '绳索器械', '未分级', '将直杆连接到低滑轮电缆机上。面朝上躺在平坦的长凳上，双脚平放在地上。反手握住杠铃，双手与肩同宽。充分伸展双臂，保持肘部靠近身体两侧。保持上臂静止，呼气并将杠铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1634', 'cable lying bicep curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a straight bar to a low pulley cable machine. Lie face up on a flat bench with your feet flat on the ground. Grasp the bar with an underhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your sides. Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1634-otqIxU4.jpg', '/static/exercises/gifs/1634-otqIxU4.gif', '© Gym visual — https://gymvisual.com/', '80620'),
('100182', '绳索仰卧窄距握弯举', '前臂', '绳索器械', '未分级', '将直杆连接到低滑轮电缆机上。面朝上躺在平坦的长凳上，双脚平放在地上。反手握住杠铃，双手与肩同宽。充分伸展双臂，保持肘部靠近身体两侧。保持上臂静止，通过收缩二头肌将杠铃卷向胸部。在顶部暂停片刻，挤压你的二头肌。慢慢地将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0182', 'cable lying close-grip curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a straight bar to a low pulley cable machine. Lie face up on a flat bench with your feet flat on the ground. Grasp the bar with an underhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your sides. Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps. Pause for a moment at the top, squeezing your biceps. Slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0182-61GrD55.jpg', '/static/exercises/gifs/0182-61GrD55.gif', '© Gym visual — https://gymvisual.com/', '80621'),
('100184', '绳索仰卧伸展上拉绳索把手', '肱三头肌', '绳索器械', '未分级', '将绳子连接到缆绳机上，并将滑轮设置在最高位置。躺在长凳上，头朝向电缆机。双手握住绳子，将双臂伸直至胸部上方。保持双臂伸直，在保持控制的同时慢慢将绳子放到脑后。在底部停顿片刻，然后慢慢将绳子拉回起始位置。重复所需的重复次数。', 'exercise-dataset', '0184', 'cable lying extension pullover (with rope attachment)', 'back', '背部', '20', 'cable', 'triceps', 'lats', '背阔肌', '["肱三头肌","肩部"]', 'Attach a rope to a cable machine and set the pulley at the highest position. Lie down on a bench with your head towards the cable machine. Hold the rope with both hands and extend your arms straight up above your chest. Keeping your arms straight, slowly lower the rope behind your head while maintaining control. Pause for a moment at the bottom, then slowly raise the rope back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0184-Q2Eu1Ax.jpg', '/static/exercises/gifs/0184-Q2Eu1Ax.gif', '© Gym visual — https://gymvisual.com/', '900628'),
('100185', '绳索仰卧飞鸟', '三角肌', '绳索器械', '未分级', '将手柄连接到电缆上，平放在长凳上，双脚平放在地面上。手掌相对，握住手柄，双臂伸直至胸部上方。保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0185', 'cable lying fly', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Attach the handles to the cables and lie flat on a bench with your feet flat on the ground. Hold the handles with your palms facing each other and your arms extended straight above your chest. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0185-lJJ7Yq8.jpg', '/static/exercises/gifs/0185-lJJ7Yq8.gif', '© Gym visual — https://gymvisual.com/', '900621'),
('100186', '绳索仰卧肱三头肌臂屈伸版本第二式', '肩部', '绳索器械', '未分级', '将绳索手柄连接到低滑轮电缆机器上。面朝上躺在平坦的长凳上，头朝向电缆机。双手抓住绳柄，掌心相对，将双臂伸直至胸前。保持上臂静止，弯曲肘部，慢慢将绳索手柄放低至前额。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数。', 'exercise-dataset', '0186', 'cable lying triceps extension v. 2', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope handle to a low pulley cable machine. Lie down on a flat bench facing up, with your head towards the cable machine. Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows. Pause for a moment at the bottom, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0186-uxJcFUU.jpg', '/static/exercises/gifs/0186-uxJcFUU.gif', '© Gym visual — https://gymvisual.com/', '400628'),
('100188', '绳索中间飞鸟', '三角肌', '绳索器械', '未分级', '将电缆连接到电缆机两侧胸部高度处。站在机器的中央，一只脚稍微在另一只脚前面。正手握住手柄，并将手臂向两侧伸展。保持肘部轻微弯曲并保持轻微前倾。收紧胸部肌肉，并以扫过的动作将手臂向前伸。在中心停顿片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0188', 'cable middle fly', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Attach cables to both sides of a cable machine at chest height. Stand in the center of the machine with one foot slightly in front of the other. Grasp the handles with an overhand grip and extend your arms out to the sides. Keep a slight bend in your elbows and maintain a slight forward lean. Engage your chest muscles and bring your arms forward in a sweeping motion. Pause for a moment at the center, then slowly return your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0188-xLYSdtg.jpg', '/static/exercises/gifs/0188-xLYSdtg.gif', '© Gym visual — https://gymvisual.com/', '900623'),
('100189', '绳索单臂俯身划船', '肱二头肌', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。稍微弯曲膝盖，髋部向前转动，保持背部挺直。用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。暂停片刻，然后慢慢将手臂伸回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0189', 'cable one arm bent over row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand facing a cable machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the cable handle with one hand, palm facing inward, and extend your arm fully. Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest. Pause for a moment, then slowly extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0189-EIsE3u8.jpg', '/static/exercises/gifs/0189-EIsE3u8.gif', '© Gym visual — https://gymvisual.com/', '160630'),
('100190', '绳索单臂弯举', '前臂', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。反手握住电缆手柄，手掌朝上。保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。在顶部暂停片刻，然后慢慢将前臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0190', 'cable one arm curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palm facing up. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0190-YTur5nR.jpg', '/static/exercises/gifs/0190-YTur5nR.gif', '© Gym visual — https://gymvisual.com/', '80627'),
('101262', '绳索单臂下斜夹胸飞鸟', '肩部', '绳索器械', '未分级', '将 D 形手柄连接到低滑轮绳索机器上，并将长凳设置为下降角度。躺在长凳上，头朝向机器，用右手抓住手柄。将手臂伸直至胸部上方，保持肘部轻微弯曲。控制动作，将手臂向一侧放低，直到手与肩膀在一条直线上。暂停片刻，然后反转动作并将手臂恢复到起始位置。重复所需的重复次数，然后切换到左臂并重复练习。', 'exercise-dataset', '1262', 'cable one arm decline chest fly', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Attach a D-handle to a low pulley cable machine and set the bench to a decline angle. Lie down on the bench with your head towards the machine and grab the handle with your right hand. Extend your arm straight up above your chest, keeping a slight bend in your elbow. With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder. Pause for a moment, then reverse the motion and bring your arm back to the starting position. Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise.', '/static/exercises/images/1262-w4dLzSx.jpg', '/static/exercises/gifs/1262-w4dLzSx.gif', '© Gym visual — https://gymvisual.com/', '240632'),
('101263', '绳索单臂飞鸟健身球', '三角肌', '绳索器械', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住电缆手柄，并将手臂向一侧伸出，与地面平行。保持肘部稍微弯曲，手掌朝前。慢慢地将手臂放在身体上，挤压胸部肌肉。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1263', 'cable one arm fly on exercise ball', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground. Keep your elbow slightly bent and your palm facing forward. Slowly bring your arm across your body, squeezing your chest muscles. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1263-hHy8tQG.jpg', '/static/exercises/gifs/1263-hHy8tQG.gif', '© Gym visual — https://gymvisual.com/', '900635'),
('101264', '绳索单臂上斜飞鸟健身球', '三角肌', '绳索器械', '未分级', '坐在健身球上，双脚平放在地面上，背部靠在倾斜的长凳上。一只手握住电缆手柄，手臂伸展，手掌朝内。保持肘部轻微弯曲，慢慢地将手臂向一侧放低，直到手与肩膀在一条直线上。暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1264', 'cable one arm incline fly on exercise ball', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and your back against an incline bench. Hold a cable handle in one hand with your arm extended and palm facing inward. Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder. Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1264-P14Dz9D.jpg', '/static/exercises/gifs/1264-P14Dz9D.gif', '© Gym visual — https://gymvisual.com/', '900638'),
('101265', '绳索单臂上斜推举', '三角肌', '绳索器械', '未分级', '将拉索机调整至低滑轮位置。坐在倾斜的长凳上，背对缆绳机。用一只手抓住手柄并将其举至肩膀高度。将双脚牢牢放在地面上并保持稳定的位置。向前和向上按下手柄，充分伸展手臂。在最高点暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1265', 'cable one arm incline press', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Adjust the cable machine to a low pulley position. Sit on an incline bench facing away from the cable machine. Grasp the handle with one hand and bring it up to shoulder height. Position your feet firmly on the ground and maintain a stable position. Press the handle forward and upward, extending your arm fully. Pause for a moment at the top, then slowly lower the handle back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1265-GKEH6jj.jpg', '/static/exercises/gifs/1265-GKEH6jj.gif', '© Gym visual — https://gymvisual.com/', '900633'),
('101266', '绳索单臂上斜推举健身球', '肩部', '绳索器械', '未分级', '坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。向前和向上按下电缆手柄，完全伸展手臂。在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1266', 'cable one arm incline press on exercise ball', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench. Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent. Press the cable handle forward and upward, extending your arm fully. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1266-6t00BsF.jpg', '/static/exercises/gifs/1266-6t00BsF.gif', '© Gym visual — https://gymvisual.com/', '900640'),
('100191', '绳索单臂侧向屈曲越过', '三角肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，面向缆绳机。用一只手抓住手柄并向后退一步以在电缆上产生张力。腰部向前弯曲，保持背部挺直，核心肌群参与。将手臂向侧面伸展，与地面平行，肘部稍微弯曲。慢慢地将手臂放回起始位置，在整个运动过程中保持控制。重复所需的重复次数，然后换边。', 'exercise-dataset', '0191', 'cable one arm lateral bent-over', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","斜方肌"]', 'Stand with your feet shoulder-width apart, facing a cable machine. Grasp the handle with one hand and step back to create tension on the cable. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow. Slowly bring your arm back to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0191-dB07vDu.jpg', '/static/exercises/gifs/0191-dB07vDu.gif', '© Gym visual — https://gymvisual.com/', '900635'),
('100192', '绳索单臂侧平举', '斜方肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，面向绳索机。用一只手握住电缆手柄，手掌朝下，站得离机器足够远，以便电缆上有张力。保持手臂伸直，慢慢向一侧举起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0192', 'cable one arm lateral raise', 'shoulders', '肩部', '30', 'cable', 'traps', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable. Keep your arm straight and slowly raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0192-wEulIzp.jpg', '/static/exercises/gifs/0192-wEulIzp.gif', '© Gym visual — https://gymvisual.com/', '160636'),
('101633', '绳索单臂牧师凳弯举', '前臂', '绳索器械', '未分级', '调整绳索机，使牧师弯举垫处于胸部高度。面对电缆机站立，双脚与肩同宽。用手握住电缆手柄，并将上臂靠在牧师弯举垫上。保持背部挺直，核心肌群参与。慢慢地将电缆手柄卷向肩膀，保持上臂靠在垫子上。在动作的最高点暂停片刻，挤压你的二头肌。慢慢地将电缆手柄放回起始位置。重复所需的重复次数。交换手臂并重复练习。', 'exercise-dataset', '1633', 'cable one arm preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the cable machine so that the preacher curl pad is at chest height. Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad. Keep your back straight and your core engaged. Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad. Pause for a moment at the top of the movement, squeezing your biceps. Slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', '/static/exercises/images/1633-eHBlPsa.jpg', '/static/exercises/gifs/1633-eHBlPsa.gif', '© Gym visual — https://gymvisual.com/', '80637'),
('101267', '绳索单臂推举健身球', '肩部', '绳索器械', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。将另一只手放在臀部上以保持稳定。向前按电缆手柄，完全伸展手臂。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1267', 'cable one arm press on exercise ball', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a cable handle in one hand and position your arm at chest height, elbow bent. Place your other hand on your hip for stability. Press the cable handle forward, extending your arm fully. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1267-MKIelrR.jpg', '/static/exercises/gifs/1267-MKIelrR.gif', '© Gym visual — https://gymvisual.com/', '900642'),
('103563', '绳索单臂下拉', '肱二头肌', '绳索器械', '未分级', '将单个手柄连接到高滑轮电缆机上。面向机器站立，双脚分开与肩同宽。正手握住手柄并完全伸展手臂。保持背部挺直，核心肌群参与。将手柄向一侧拉，同时保持肘部靠近身体。在动作底部暂停片刻，挤压背阔肌。慢慢松开手柄回到起始位置。重复所需的重复次数。换边并用另一只手臂重复练习。', 'exercise-dataset', '3563', 'cable one arm pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach a single handle to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip and extend your arm fully. Keep your back straight and your core engaged. Pull the handle down towards your side while keeping your elbow close to your body. Pause for a moment at the bottom of the movement, squeezing your lat muscle. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other arm.', '/static/exercises/images/3563-U5INZY6.jpg', '/static/exercises/gifs/3563-U5INZY6.gif', '© Gym visual — https://gymvisual.com/', '80637'),
('101635', '绳索单臂反向牧师凳弯举', '前臂', '绳索器械', '未分级', '调整拉索机，使滑轮处于最低位置。面对电缆机站立，双脚与肩同宽。用反手抓住电缆手柄，并将上臂靠在牧师凳垫上。在整个练习过程中保持背部挺直，核心肌群参与其中。慢慢地将前臂向二头肌方向卷曲，保持上臂固定在垫子上。在动作的最高点暂停片刻，挤压你的二头肌。慢慢地将电缆手柄放回起始位置。重复所需的重复次数。交换手臂并重复练习。', 'exercise-dataset', '1635', 'cable one arm reverse preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the cable machine so that the pulley is at the lowest position. Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad. Keep your back straight and your core engaged throughout the exercise. Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad. Pause for a moment at the top of the movement, squeezing your bicep. Slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', '/static/exercises/images/1635-ZXnjcOQ.jpg', '/static/exercises/gifs/1635-ZXnjcOQ.gif', '© Gym visual — https://gymvisual.com/', '80642'),
('100193', '绳索单臂直后侧高位划船跪姿', '肱二头肌', '绳索器械', '未分级', '将手柄连接到腰部高度的缆绳机上。面向电缆机跪下，用一只手抓住手柄。保持背部挺直，核心肌群参与。将手柄拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢松开手柄回到起始位置。重复所需的重复次数。换边并用另一只手臂重复练习。', 'exercise-dataset', '0193', 'cable one arm straight back high row (kneeling)', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Attach a handle to a cable machine at waist height. Kneel down facing the cable machine and grab the handle with one hand. Keep your back straight and your core engaged. Pull the handle towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with the other arm.', '/static/exercises/images/0193-WrYPP2g.jpg', '/static/exercises/gifs/0193-WrYPP2g.gif', '© Gym visual — https://gymvisual.com/', '900647'),
('101723', '绳索单臂肱三头肌下压', '前臂', '绳索器械', '未分级', '面向缆绳机站立，并在胸部高度处安装直杆附件。正手握住杠铃，然后后退以在绳索上产生张力。将双脚分开与肩同宽，并稍微弯曲膝盖。在整个练习过程中保持背部挺直并保持核心参与。首先，手臂完全伸展并垂直于地板。保持上臂静止，呼气并将杠铃向下推，直到手臂完全伸展。暂停片刻，然后吸气，慢慢回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1723', 'cable one arm tricep pushdown', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Stand facing a cable machine with a straight bar attachment at chest height. Grasp the bar with an overhand grip and step back to create tension in the cable. Position your feet shoulder-width apart and slightly bend your knees. Keep your back straight and core engaged throughout the exercise. Start with your arm fully extended and perpendicular to the floor. Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended. Pause for a moment, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1723-qRZ5S1N.jpg', '/static/exercises/gifs/1723-qRZ5S1N.gif', '© Gym visual — https://gymvisual.com/', '320642'),
('101636', '绳索过顶弯举', '前臂', '绳索器械', '未分级', '将直杆连接到高滑轮电缆机上。面向机器站立，双脚分开与肩同宽。反手握住杠铃，双手与肩同宽。保持肘部靠近身体两侧，上臂保持静止。呼气并将杠铃向下卷向前额，保持上臂静止。在动作底部暂停片刻，挤压二头肌。吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1636', 'cable overhead curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the bar down towards your forehead, keeping your upper arms stationary. Pause for a moment at the bottom of the movement, squeezing your biceps. Inhale and slowly return the bar to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1636-wDUqY2u.jpg', '/static/exercises/gifs/1636-wDUqY2u.gif', '© Gym visual — https://gymvisual.com/', '80639'),
('101637', '绳索过顶弯举健身球', '前臂', '绳索器械', '未分级', '坐在健身球上，用反手握住电缆手柄。将手臂完全伸过头顶，保持肘部靠近耳朵。慢慢地将电缆朝前额卷曲，保持上臂静止。在动作底部暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1637', 'cable overhead curl on exercise ball', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Sit on an exercise ball and hold the cable handle with an underhand grip. Extend your arms fully overhead, keeping your elbows close to your ears. Slowly curl the cable down towards your forehead, keeping your upper arms stationary. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1637-ioTf098.jpg', '/static/exercises/gifs/1637-ioTf098.gif', '© Gym visual — https://gymvisual.com/', '80646'),
('100194', '绳索过顶肱三头肌臂屈伸绳索把手', '肩部', '绳索器械', '未分级', '将绳索连接到高处的缆绳机上。背对机器站立，双脚与肩同宽。双手抓住绳子，掌心相对，将双手举过头顶。保持上臂靠近头部，肘部向前。弯曲肘部，慢慢将绳子降低到头后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0194', 'cable overhead triceps extension (rope attachment)', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope to a cable machine at a high position. Stand facing away from the machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing each other, and bring your hands above your head. Keep your upper arms close to your head and your elbows pointing forward. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0194-2IxROQ1.jpg', '/static/exercises/gifs/0194-2IxROQ1.gif', '© Gym visual — https://gymvisual.com/', '400647'),
('101319', '绳索掌心旋转划船', '肱二头肌', '绳索器械', '未分级', '将手柄连接到腰部高度的缆绳机上。面向机器站立，双脚分开与肩同宽。正手握住手柄，手掌朝下。向后退一步，在绳索上产生张力，保持背部挺直，膝盖稍微弯曲。将手柄拉向身体，同时将手掌旋转至向上。在动作结束时将肩胛骨挤压在一起。慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1319', 'cable palm rotational row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Attach a handle to a cable machine at waist height. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with an overhand grip, palms facing down. Step back to create tension on the cable, keeping your back straight and knees slightly bent. Pull the handle towards your body, rotating your palms to face upwards as you do so. Squeeze your shoulder blades together at the end of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1319-OmQ8w0p.jpg', '/static/exercises/gifs/1319-OmQ8w0p.gif', '© Gym visual — https://gymvisual.com/', '900644'),
('100195', '绳索牧师凳弯举', '前臂', '绳索器械', '未分级', '调整绳索机，使牧师弯举垫处于胸部高度。坐在牧师弯举凳上，将上臂放在垫子上，用反手抓住电缆附件。保持背部挺直，肘部放在身体两侧。慢慢地将电缆附件向肩膀方向卷曲，在动作的最高点挤压二头肌。暂停片刻，然后慢慢将电缆附件放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0195', 'cable preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the cable machine so that the preacher curl pad is at chest height. Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip. Keep your back straight and your elbows tucked in at your sides. Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement. Pause for a moment, then slowly lower the cable attachment back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0195-P2lNrGL.jpg', '/static/exercises/gifs/0195-P2lNrGL.gif', '© Gym visual — https://gymvisual.com/', '80643'),
('101268', '绳索推举健身球', '肩部', '绳索器械', '未分级', '坐在健身球上，双脚平放在地上，膝盖呈 90 度角。将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。收紧核心并向前按压缆索手柄，直到手臂完全伸展。暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。重复所需的重复次数。', 'exercise-dataset', '1268', 'cable press on exercise ball', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle. Hold the cable handles at chest height with your palms facing down and your elbows bent. Engage your core and press the cable handles forward until your arms are fully extended. Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1268-vAwm6rK.jpg', '/static/exercises/gifs/1268-vAwm6rK.gif', '© Gym visual — https://gymvisual.com/', '900648'),
('100196', '绳索绳索胯下拉绳索', '腘绳肌', '绳索器械', '未分级', '背对缆绳机站立，双脚与肩同宽。双手抓住绳索附件并向前迈一步，在绳索中产生张力。弯曲臀部并降低上身直至与地面平行，保持背部挺直。启动臀肌和腿筋，将身体拉回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0196', 'cable pull through (with rope)', 'upper legs', '大腿', '40', 'cable', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand facing away from the cable machine with your feet shoulder-width apart. Grab the rope attachment with both hands and step forward, creating tension in the cable. Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight. Engage your glutes and hamstrings to pull your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0196-OM46QHm.jpg', '/static/exercises/gifs/0196-OM46QHm.gif', '© Gym visual — https://gymvisual.com/', '900649'),
('100198', '绳索下拉', '肱二头肌', '绳索器械', '未分级', '调整拉索下拉机，使座椅处于舒适的高度并固定护膝。坐在座位上，背部挺直，双脚平放在地面上。正手握住电缆杆，握距略宽于肩宽。稍微向后倾斜并启动你的核心。将电缆杆向下拉向胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0198', 'cable pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured. Sit on the seat with your back straight and your feet flat on the ground. Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart. Lean back slightly and engage your core. Pull the cable bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0198-RVwzP10.jpg', '/static/exercises/gifs/0198-RVwzP10.gif', '© Gym visual — https://gymvisual.com/', '80644'),
('100197', '绳索下拉进阶式背阔肌杆', '肱二头肌', '绳索器械', '未分级', '调整座椅高度，使大腿与地面平行，双脚平放在地板上。正手握住背阔肌杠铃，握距略宽于肩宽。坐下来，稍微向后倾斜，保持挺胸、背部挺直。将杠铃向下拉向胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0197', 'cable pulldown (pro lat bar)', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor. Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart. Sit down and lean back slightly, keeping your chest up and your back straight. Pull the bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0197-qdRxqCj.jpg', '/static/exercises/gifs/0197-qdRxqCj.gif', '© Gym visual — https://gymvisual.com/', '80651'),
('101638', '绳索下拉肱二头肌弯举', '前臂', '绳索器械', '未分级', '在最高设置下将直杆连接到电缆机上。面向机器站立，双脚分开与肩同宽。反手握住杠铃，双手与肩同宽。保持肘部靠近身体两侧，上臂保持静止。呼气，慢慢将杠铃向大腿方向卷曲，保持手腕伸直。在动作底部暂停片刻，挤压二头肌。吸气，慢慢地将杠铃返回到起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1638', 'cable pulldown bicep curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a straight bar to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight. Pause for a moment at the bottom of the movement, squeezing your biceps. Inhale and slowly return the bar to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1638-QTXKWPh.jpg', '/static/exercises/gifs/1638-QTXKWPh.gif', '© Gym visual — https://gymvisual.com/', '80650'),
('100201', '绳索下压', '前臂', '绳索器械', '未分级', '将直杆连接到高滑轮电缆机上。面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，双手与肩同宽。保持肘部靠近身体两侧，上臂保持静止。呼气并将杠铃向下推，直到肘部完全伸展。暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0201', 'cable pushdown', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and push the bar down until your elbows are fully extended. Pause for a moment, then inhale and slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0201-3ZflifB.jpg', '/static/exercises/gifs/0201-3ZflifB.gif', '© Gym visual — https://gymvisual.com/', '320647'),
('100199', '绳索下压直臂版本第二式', '肱三头肌', '绳索器械', '未分级', '将直杆连接到高滑轮电缆机上。面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，保持手臂伸直，手掌朝下。呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0199', 'cable pushdown (straight arm) v. 2', 'back', '背部', '20', 'cable', 'triceps', 'lats', '背阔肌', '["肱三头肌","肩部"]', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down. Engage your core and keep your back straight as you exhale and push the bar down towards your thighs. Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling. Repeat for the desired number of repetitions.', '/static/exercises/images/0199-PskORrA.jpg', '/static/exercises/gifs/0199-PskORrA.gif', '© Gym visual — https://gymvisual.com/', '900656'),
('100200', '绳索下压绳索把手', '前臂', '绳索器械', '未分级', '将绳索附件连接到缆绳机上的高滑轮上。面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住绳子，手掌相对。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。呼气并伸展肘部将绳子向下推，直到手臂完全伸展。暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0200', 'cable pushdown (with rope attachment)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a rope attachment to a high pulley on a cable machine. Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees. Grasp the rope with an overhand grip, palms facing each other. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and push the rope downward by extending your elbows until your arms are fully extended. Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex. Repeat for the desired number of repetitions.', '/static/exercises/images/0200-dU605di.jpg', '/static/exercises/gifs/0200-dU605di.gif', '© Gym visual — https://gymvisual.com/', '320655'),
('100202', '绳索三角肌后束划船脚蹬', '斜方肌', '绳索器械', '未分级', '将马镫手柄连接到低电缆滑轮上，面向机器站立。左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。在动作的最高点暂停片刻，挤压肩胛骨。慢慢地将手柄释放回起始位置，然后重复所需的重复次数。换边并用右臂重复练习。', 'exercise-dataset', '0202', 'cable rear delt row (stirrups)', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Attach a stirrup handle to a low cable pulley and stand facing the machine. Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade. Pause for a moment at the top of the movement, squeezing your shoulder blade. Slowly release the handle back to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the exercise with your right arm.', '/static/exercises/images/0202-yUdIGNs.jpg', '/static/exercises/gifs/0202-yUdIGNs.gif', '© Gym visual — https://gymvisual.com/', '400656'),
('100203', '绳索三角肌后束划船绳索', '斜方肌', '绳索器械', '未分级', '将绳索手柄连接到低滑轮电缆机器上。面向机器站立，双脚分开与肩同宽。正手握住绳索手柄，手掌相对。稍微弯曲膝盖，髋部向前转动，保持背部挺直。保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0203', 'cable rear delt row (with rope)', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an overhand grip, palms facing each other. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0203-wqNPGCg.jpg', '/static/exercises/gifs/0203-wqNPGCg.gif', '© Gym visual — https://gymvisual.com/', '400659'),
('100204', '绳索后侧蹬伸', '肩部', '绳索器械', '未分级', '将手柄连接到低滑轮电缆机器上，并背对机器站立。正手握住手柄，并将双臂伸直至身前。保持肘部不动，将手柄拉回身体，在动作结束时挤压三头肌。慢慢地将手柄返回到起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0204', 'cable rear drive', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Attach a handle to a low pulley cable machine and stand facing away from the machine. Grasp the handle with an overhand grip and extend your arms straight out in front of you. Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement. Slowly return the handle to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0204-c3QQLPi.jpg', '/static/exercises/gifs/0204-c3QQLPi.gif', '© Gym visual — https://gymvisual.com/', '900654'),
('100205', '绳索后侧下拉', '肱二头肌', '绳索器械', '未分级', '调整拉索机，使滑轮处于最高位置。面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。正手握住电缆附件，双手之间的距离略大于肩宽。稍微向后倾斜，保持背部挺直，挺胸。将电缆附件向下拉向胸部，将肩胛骨挤压在一起。在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0205', 'cable rear pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the cable machine so that the pulley is at the highest position. Sit facing the machine with your feet flat on the ground and your knees slightly bent. Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart. Lean back slightly, keeping your back straight and your chest up. Pull the cable attachment down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0205-SpsOSXk.jpg', '/static/exercises/gifs/0205-SpsOSXk.gif', '© Gym visual — https://gymvisual.com/', '80655'),
('100873', '绳索反向卷腹', '髋屈肌', '绳索器械', '未分级', '将电缆连接到低滑轮上，然后面朝上躺在垫子上。用双手握住电缆，并将双臂伸向天花板。弯曲膝盖并抬起双腿，使大腿靠近胸部。在保持上半身稳定的同时，将骨盆向胸部弯曲，将臀部抬离垫子。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0873', 'cable reverse crunch', 'waist', '腰腹', '60', 'cable', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Attach a cable to a low pulley and lie down facing up on a mat. Hold the cable with both hands and extend your arms straight up towards the ceiling. Bend your knees and lift your legs up, bringing your thighs towards your chest. While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0873-RqOtqD7.jpg', '/static/exercises/gifs/0873-RqOtqD7.gif', '© Gym visual — https://gymvisual.com/', '80656'),
('100206', '绳索反向弯举', '前臂', '绳索器械', '未分级', '将直杆连接到低滑轮电缆机上。面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。反手握住杠铃，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。呼气并将杠铃向上卷向肩膀，收缩二头肌。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0206', 'cable reverse curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an underhand grip, hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0206-eOG0r6v.jpg', '/static/exercises/gifs/0206-eOG0r6v.gif', '© Gym visual — https://gymvisual.com/', '80657'),
('102406', '绳索反向握肱三头肌下压曲杆杆臂弯举托板', '前臂', '绳索器械', '未分级', '在最高设置下将直杆连接到电缆机上。面对电缆机站立，双脚与肩同宽。反手握住杠铃，手掌朝上，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。启动你的三头肌，慢慢地向下推杠铃，直到你的手臂完全伸展。在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2406', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a straight bar to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and slowly push the bar down until your arms are fully extended. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2406-ThKP69G.jpg', '/static/exercises/gifs/2406-ThKP69G.gif', '© Gym visual — https://gymvisual.com/', '320670'),
('101413', '绳索反向单臂弯举', '前臂', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。反手握住电缆手柄，手掌朝下。保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。在顶部暂停片刻，然后慢慢将前臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1413', 'cable reverse one arm curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palm facing down. Keep your elbow close to your side and slowly curl your forearm up towards your shoulder. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1413-gVlnLIJ.jpg', '/static/exercises/gifs/1413-gVlnLIJ.gif', '© Gym visual — https://gymvisual.com/', '80663'),
('100209', '绳索反向牧师凳弯举', '前臂', '绳索器械', '未分级', '调整绳索机，使牧师弯举垫处于胸部高度。坐在牧师弯举凳上，将上臂放在垫子上，手掌朝下，肘部完全伸展。反手抓住电缆手柄，距离与肩同宽。保持上臂静止，呼气并将手柄向肩膀卷曲，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将手柄放回起始位置，充分伸展肘部。重复所需的重复次数。', 'exercise-dataset', '0209', 'cable reverse preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the cable machine so that the preacher curl pad is at chest height. Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended. Grab the cable handles with an underhand grip, shoulder-width apart. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your elbows. Repeat for the desired number of repetitions.', '/static/exercises/images/0209-IwX5NqK.jpg', '/static/exercises/gifs/0209-IwX5NqK.gif', '© Gym visual — https://gymvisual.com/', '80662'),
('100210', '绳索反向腕弯举', '前臂', '绳索器械', '未分级', '将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。正手握住电缆手柄，手掌朝下。将前臂放在大腿上，手腕悬在边缘上。保持前臂静止，呼气并尽可能向上弯曲手腕。在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0210', 'cable reverse wrist curl', 'lower arms', '前臂', '80', 'cable', 'forearms', 'forearms', '前臂肌群', '["前臂","手腕"]', 'Attach a cable to a low pulley and sit on a bench facing the cable machine. Grasp the cable handle with an overhand grip, palms facing down. Rest your forearms on your thighs, with your wrists hanging off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0210-eYmsEPR.jpg', '/static/exercises/gifs/0210-eYmsEPR.gif', '© Gym visual — https://gymvisual.com/', '663'),
('100207', '绳索反向握下压', '前臂', '绳索器械', '未分级', '将直杆连接到高滑轮电缆机上。面向机器站立，双脚分开与肩同宽。反手握住杠铃，手掌朝上，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。暂停片刻，然后慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0207', 'cable reverse-grip pushdown', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a straight bar to a high pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted. Pause for a moment, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0207-VjYliFZ.jpg', '/static/exercises/gifs/0207-VjYliFZ.gif', '© Gym visual — https://gymvisual.com/', '320662'),
('100208', '绳索反向握直后侧坐姿高位划船', '肱二头肌', '绳索器械', '未分级', '坐在面向电缆机的座位上，双脚平放在地板上。用手握住电缆附件，手掌朝上，双手与肩同宽。保持背部挺直，并从臀部稍微向前倾斜。通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0208', 'cable reverse-grip straight back seated high row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the seat facing the cable machine with your feet flat on the floor. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your back straight and lean slightly forward from your hips. Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0208-PNtsX17.jpg', '/static/exercises/gifs/0208-PNtsX17.gif', '© Gym visual — https://gymvisual.com/', '900671'),
('101320', '绳索绳索交叉坐姿划船', '肱二头肌', '绳索器械', '未分级', '坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。正手握住缆绳，手掌相对。稍微向后倾斜，保持背部挺直，核心肌群参与。将缆绳拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1320', 'cable rope crossover seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent. Grasp the cable ropes with an overhand grip, palms facing each other. Lean back slightly, keeping your back straight and your core engaged. Pull the cable ropes towards your chest, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1320-UFGF6gk.jpg', '/static/exercises/gifs/1320-UFGF6gk.gif', '© Gym visual — https://gymvisual.com/', '240668'),
('101321', '绳索绳索抬高坐姿划船', '肱二头肌', '绳索器械', '未分级', '坐在面向电缆机的高架座椅上。正手握住缆绳手柄，手掌相对。保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。在完全收缩的位置暂停片刻。慢慢释放压力并将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1321', 'cable rope elevated seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the elevated seat facing the cable machine. Grab the cable rope handles with an overhand grip, palms facing each other. Keep your back straight and lean slightly back, maintaining a slight bend in your knees. Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the fully contracted position. Slowly release the tension and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1321-c8oybX6.jpg', '/static/exercises/gifs/1321-c8oybX6.gif', '© Gym visual — https://gymvisual.com/', '240669'),
('101322', '绳索绳索伸展上斜训练凳划船', '肱二头肌', '绳索器械', '未分级', '以 45 度角设置上斜凳，并将绳索机连接到低滑轮上。将绳索手柄连接到缆绳机上，然后坐在面向机器的倾斜长凳上。正手抓住绳索把手，身体前倾，保持背部挺直。充分伸展双臂，将绳子拉向上胸部，同时保持肘部靠近身体。在动作结束时将肩胛骨挤压在一起。慢慢释放张力并回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1322', 'cable rope extension incline bench row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley. Attach a rope handle to the cable machine and sit on the incline bench facing the machine. Grab the rope handle with an overhand grip and lean forward, keeping your back straight. Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body. Squeeze your shoulder blades together at the end of the movement. Slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1322-MgKwAAo.jpg', '/static/exercises/gifs/1322-MgKwAAo.gif', '© Gym visual — https://gymvisual.com/', '900672'),
('101639', '绳索绳索锤式牧师凳弯举', '前臂', '绳索器械', '未分级', '将绳索附件连接到低滑轮缆绳机上。面向机器站立，双脚分开与肩同宽。以中立握法（手掌相对）抓住绳子。将上臂靠在牧师凳垫上，保持肘部稍微弯曲。保持上臂静止，呼气并通过收缩二头肌将绳子卷向肩膀。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将绳子放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1639', 'cable rope hammer preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a rope attachment to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with a neutral grip (palms facing each other). Position your upper arms against the preacher bench pad, keeping your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the rope back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1639-PcPe0P5.jpg', '/static/exercises/gifs/1639-PcPe0P5.gif', '© Gym visual — https://gymvisual.com/', '80671'),
('101724', '绳索绳索高位滑轮过顶肱三头肌伸展', '肩部', '绳索器械', '未分级', '将绳子连接到高滑轮上并相应地调整重量。背对滑轮机站立，双脚与肩同宽。双手抓住绳子，掌心朝下，双手举过头顶。保持上臂靠近头部并垂直于地板。弯曲肘部，慢慢将绳子降低到头后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1724', 'cable rope high pulley overhead tricep extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope to a high pulley and adjust the weight accordingly. Stand facing away from the pulley machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing down, and bring your hands above your head. Keep your upper arms close to your head and perpendicular to the floor. Slowly lower the rope behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1724-NN8nSNT.jpg', '/static/exercises/gifs/1724-NN8nSNT.gif', '© Gym visual — https://gymvisual.com/', '900676'),
('101725', '绳索绳索上斜肱三头肌伸展', '肩部', '绳索器械', '未分级', '将绳子连接到高滑轮上，并将倾斜长凳调整到舒适的角度。背对滑轮站立，双脚与肩同宽。正手抓住绳子，并将双臂伸直过头顶。在整个练习过程中，保持肘部靠近头部，上臂保持静止。弯曲肘部，直到前臂接触二头肌，将绳子降低到头后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1725', 'cable rope incline tricep extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope to a high pulley and adjust the incline bench to a comfortable angle. Stand facing away from the pulley with your feet shoulder-width apart. Grasp the rope with an overhand grip and extend your arms straight overhead. Keep your elbows close to your head and your upper arms stationary throughout the exercise. Lower the rope behind your head by bending your elbows until your forearms touch your biceps. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1725-ZujAdR9.jpg', '/static/exercises/gifs/1725-ZujAdR9.gif', '© Gym visual — https://gymvisual.com/', '900673'),
('101726', '绳索绳索仰卧地板肱三头肌伸展', '肩部', '绳索器械', '未分级', '将绳子连接到缆绳机上并将其设置到最低位置。面朝上躺在地板上，头朝向电缆机。双手握住绳子，掌心相对，双臂伸直向上伸向天花板。保持上臂静止，慢慢地将绳子放低到前额，弯曲肘部。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1726', 'cable rope lying on floor tricep extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Attach a rope to a cable machine and set it to the lowest position. Lie on the floor facing up, with your head towards the cable machine. Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling. Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1726-U3ffHlY.jpg', '/static/exercises/gifs/1726-U3ffHlY.gif', '© Gym visual — https://gymvisual.com/', '900678'),
('101640', '绳索绳索单臂锤式牧师凳弯举', '前臂', '绳索器械', '未分级', '将绳索手柄连接到低滑轮电缆机器上。面向机器站立，双脚分开与肩同宽。反手握住绳索手柄，手掌朝上。将上臂靠在牧师凳垫上，保持肘部稍微弯曲。在整个练习过程中保持背部挺直，核心肌群参与其中。慢慢地将绳索手柄卷向肩膀，保持上臂静止。在动作的最高点挤压二头肌，然后慢慢将绳柄放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1640', 'cable rope one arm hammer preacher curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a rope handle to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the rope handle with an underhand grip, palms facing up. Position your upper arm against the preacher bench pad, keeping your elbow slightly bent. Keep your back straight and your core engaged throughout the exercise. Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1640-4hATdoB.jpg', '/static/exercises/gifs/1640-4hATdoB.gif', '© Gym visual — https://gymvisual.com/', '80679'),
('101323', '绳索绳索坐姿划船', '肱二头肌', '绳索器械', '未分级', '坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。正手握住缆绳，手掌相对。保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。将缆绳拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1323', 'cable rope seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the rowing machine with your feet flat on the footrests and knees slightly bent. Grasp the cable ropes with an overhand grip, palms facing each other. Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows. Pull the cable ropes towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1323-SJqRxOt.jpg', '/static/exercises/gifs/1323-SJqRxOt.gif', '© Gym visual — https://gymvisual.com/', '240674'),
('100211', '绳索俄罗斯式转体瑞士球', '腹斜肌', '绳索器械', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。双手握住电缆手柄，并将双臂伸直至前方。稍微向后倾斜，同时保持背部挺直并且核心参与。将躯干向右扭转，将电缆手柄拉向右臀部。暂停片刻，然后将躯干向左扭转，将电缆手柄拉向左臀部。继续交替扭转所需的重复次数。', 'exercise-dataset', '0211', 'cable russian twists (on stability ball)', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold the cable handle with both hands and extend your arms straight out in front of you. Lean back slightly while keeping your back straight and your core engaged. Twist your torso to the right, bringing the cable handle towards your right hip. Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip. Continue alternating twists for the desired number of repetitions.', '/static/exercises/images/0211-d9Xaxq6.jpg', '/static/exercises/gifs/0211-d9Xaxq6.gif', '© Gym visual — https://gymvisual.com/', '400679'),
('102144', '绳索坐姿胸推', '肩部', '绳索器械', '未分级', '将座椅高度和电缆手柄调整至舒适的位置。坐在长凳上，背部挺直，双脚平放在地板上。正手握住电缆手柄，与肩同高。向前推动手柄并使其远离身体，充分伸展双臂。暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2144', 'cable seated chest press', 'chest', '胸部', '10', 'cable', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the seat height and cable handles to a comfortable position. Sit on the bench with your back straight and feet flat on the floor. Grasp the cable handles with an overhand grip at shoulder height. Push the handles forward and away from your body, extending your arms fully. Pause for a moment, then slowly bring the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2144-nIR4Rwl.jpg', '/static/exercises/gifs/2144-nIR4Rwl.gif', '© Gym visual — https://gymvisual.com/', '160676'),
('100212', '绳索坐姿卷腹', '腹斜肌', '绳索器械', '未分级', '坐在缆绳机上，双脚平放在地面上，膝盖弯曲。用双手握住电缆手柄并将其放在脑后。收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。在顶部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0212', 'cable seated crunch', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on a cable machine with your feet flat on the ground and your knees bent. Hold the cable handle with both hands and position it behind your head. Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0212-8xUv4J7.jpg', '/static/exercises/gifs/0212-8xUv4J7.gif', '© Gym visual — https://gymvisual.com/', '80675'),
('101641', '绳索坐姿弯举', '前臂', '绳索器械', '未分级', '坐在缆绳机上，双脚平放在地面上，背部挺直。反手抓住电缆附件，手掌朝上，双臂完全伸展。保持上臂静止，呼气并将电缆附件卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1641', 'cable seated curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a cable machine with your feet flat on the ground and your back straight. Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1641-8oYqOt9.jpg', '/static/exercises/gifs/1641-8oYqOt9.gif', '© Gym visual — https://gymvisual.com/', '80676'),
('100213', '绳索坐姿高位划船V字杆', '肱二头肌', '绳索器械', '未分级', '坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。正手握住 V 形杆附件，手掌相对，双手与肩同宽。保持背部挺直，并从臀部稍微向前倾斜。通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0213', 'cable seated high row (v-bar)', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Sit on the cable machine with your feet flat on the floor and your knees slightly bent. Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart. Keep your back straight and lean slightly forward from the hips. Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles. Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0213-pwt0pnM.jpg', '/static/exercises/gifs/0213-pwt0pnM.gif', '© Gym visual — https://gymvisual.com/', '900681'),
('100214', '绳索坐姿单臂交替划船', '肱二头肌', '绳索器械', '未分级', '坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。用一只手抓住手柄，并将手臂完全伸展到身前。将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。在动作的最高点暂停片刻，挤压背部肌肉。慢慢松开手柄回到起始位置。用另一只手臂重复上述步骤。双臂交替进行所需的重复次数。', 'exercise-dataset', '0214', 'cable seated one arm alternate row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent. Grasp the handle with one hand and keep your arm fully extended in front of you. Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side. Pause for a moment at the top of the movement, squeezing your back muscles. Slowly release the handle back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', '/static/exercises/images/0214-vpp9Ku2.jpg', '/static/exercises/gifs/0214-vpp9Ku2.gif', '© Gym visual — https://gymvisual.com/', '900684'),
('101642', '绳索坐姿单臂集中弯举', '前臂', '绳索器械', '未分级', '坐在长凳上，双脚平放在地板上，背部挺直。用一只手握住电缆手柄，并将肘部放在大腿内侧、膝盖上方。呼气时，保持上臂静止并将电缆手柄向肩膀卷曲。在动作的最高点暂停片刻，挤压你的二头肌。吸气时慢慢将电缆手柄放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1642', 'cable seated one arm concentration curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the floor and your back straight. Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee. Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling. Pause for a moment at the top of the movement, squeezing your biceps. Slowly lower the cable handle back to the starting position while inhaling. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1642-rZ80Gbp.jpg', '/static/exercises/gifs/1642-rZ80Gbp.gif', '© Gym visual — https://gymvisual.com/', '80685'),
('101643', '绳索坐姿过顶弯举', '前臂', '绳索器械', '未分级', '坐在长凳上，面向电缆机，双脚平放在地面上。用手握住电缆附件，手掌朝上，双手与肩同宽。保持上臂不动，肘部靠近身体两侧。呼气并将电缆附件卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并慢慢将电缆附件放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1643', 'cable seated overhead curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart. Keep your upper arms stationary and your elbows close to your sides. Exhale and curl the cable attachment towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1643-DpWMFP5.jpg', '/static/exercises/gifs/1643-DpWMFP5.gif', '© Gym visual — https://gymvisual.com/', '80682'),
('100215', '绳索坐姿后侧侧平举', '斜方肌', '绳索器械', '未分级', '坐在长凳上，面向电缆机，双脚平放在地面上。正手握住电缆手柄，并将双臂伸直至前方。保持手臂伸直，慢慢向两侧举起，直到与地板平行。在顶部停顿片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0215', 'cable seated rear lateral raise', 'shoulders', '肩部', '30', 'cable', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Sit on a bench facing the cable machine with your feet flat on the ground. Grasp the cable handles with an overhand grip and extend your arms straight in front of you. Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0215-x825CZm.jpg', '/static/exercises/gifs/0215-x825CZm.gif', '© Gym visual — https://gymvisual.com/', '160685'),
('100861', '坐姿绳索划船', '肱二头肌', '绳索器械', '未分级', '坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。正手握住手柄，保持背部挺直，肩膀放松。将手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0861', 'cable seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0861-fUBheHs.jpg', '/static/exercises/gifs/0861-fUBheHs.gif', '© Gym visual — https://gymvisual.com/', '240682'),
('100216', '绳索坐姿肩部内旋旋转', '肩袖肌群', '绳索器械', '未分级', '坐在长凳或椅子上，面向电缆机，双脚平放在地面上。握住电缆手柄，手臂在身前伸直，与地面平行。保持肘部稍微弯曲，肩胛骨向后和向下拉。慢慢向内旋转手臂，将电缆手柄拉向身体中心。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0216', 'cable seated shoulder internal rotation', 'shoulders', '肩部', '30', 'cable', 'rotator cuff', 'delts', '三角肌', '["肩袖肌群","肱三头肌"]', 'Sit on a bench or chair facing the cable machine with your feet flat on the ground. Hold the cable handle with your arm extended straight out in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back and down. Slowly rotate your arm inward, bringing the cable handle towards the center of your body. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0216-YPoVrBi.jpg', '/static/exercises/gifs/0216-YPoVrBi.gif', '© Gym visual — https://gymvisual.com/', '900687'),
('102399', '绳索坐姿转体', '腹斜肌', '绳索器械', '未分级', '坐在缆绳机上，双脚平放在地面上，膝盖稍微弯曲。双手握住电缆手柄，并将双臂伸直至身前。保持核心参与，慢慢地将躯干旋转到一侧，将电缆拉过身体。在动作范围结束时暂停片刻，然后慢慢旋转回到起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '2399', 'cable seated twist', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on a cable machine with your feet flat on the ground and your knees slightly bent. Hold the cable handle with both hands and extend your arms straight in front of you. Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body. Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2399-UEjSrKI.jpg', '/static/exercises/gifs/2399-UEjSrKI.gif', '© Gym visual — https://gymvisual.com/', '900684'),
('100218', '绳索坐姿宽距握划船', '肱二头肌', '绳索器械', '未分级', '坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。正手宽握握住手柄，手掌朝下。保持背部挺直，并从臀部稍微向前倾斜。将手柄拉向下胸部，将肩胛骨挤压在一起。在收缩高峰时暂停片刻。慢慢松开手柄回到起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0218', 'cable seated wide-grip row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the handle with a wide overhand grip, palms facing down. Keep your back straight and lean slightly forward from the hips. Pull the handle towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the peak of the contraction. Slowly release the handle back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0218-qcY50ZD.jpg', '/static/exercises/gifs/0218-qcY50ZD.gif', '© Gym visual — https://gymvisual.com/', '900687'),
('100219', '绳索肩上推举', '肱三头肌', '绳索器械', '未分级', '调整绳索机，使手柄位于肩部高度。背对机器站立，双脚与肩同宽。正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。向上按压手柄，直到手臂完全伸过头顶。在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。重复所需的重复次数。', 'exercise-dataset', '0219', 'cable shoulder press', 'shoulders', '肩部', '30', 'cable', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the cable machine so that the handles are at shoulder height. Stand facing away from the machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards. Press the handles upwards until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0219-PzQanLE.jpg', '/static/exercises/gifs/0219-PzQanLE.gif', '© Gym visual — https://gymvisual.com/', '686'),
('100220', '绳索耸肩', '肩部', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。正手握住电缆手柄，让手臂垂在身前。保持手臂伸直，耸肩向耳朵方向向上。保持收缩一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0220', 'cable shrug', 'back', '背部', '20', 'cable', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the cable handles with an overhand grip and let your arms hang down in front of you. Keeping your arms straight, shrug your shoulders up towards your ears. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0220-Eg98Ft9.jpg', '/static/exercises/gifs/0220-Eg98Ft9.gif', '© Gym visual — https://gymvisual.com/', '560685'),
('100222', '绳索侧向侧屈', '腹斜肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，用一只手抓住电缆手柄。保持背部挺直，核心肌群参与。腰部慢慢向侧面弯曲，将电缆手柄向膝盖方向降低。暂停片刻，然后回到起始位置。在另一侧重复。交替进行所需的重复次数。', 'exercise-dataset', '0222', 'cable side bend', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand with your feet shoulder-width apart and grasp the cable handle with one hand. Keep your back straight and your core engaged. Slowly bend sideways at the waist, lowering the cable handle towards your knee. Pause for a moment, then return to the starting position. Repeat on the other side. Alternate sides for the desired number of repetitions.', '/static/exercises/images/0222-wPypxFY.jpg', '/static/exercises/gifs/0222-wPypxFY.gif', '© Gym visual — https://gymvisual.com/', '900688'),
('100221', '绳索侧向侧屈卷腹BOSU球', '腹斜肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，一只手握住电缆手柄。将另一只手放在臀部上。启动你的核心，慢慢向握住电缆的手侧弯，保持背部挺直。在动作底部暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0221', 'cable side bend crunch (bosu ball)', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand with your feet shoulder-width apart, holding a cable handle in one hand. Place the other hand on your hip. Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0221-qatbkEd.jpg', '/static/exercises/gifs/0221-qatbkEd.gif', '© Gym visual — https://gymvisual.com/', '80695'),
('100223', '绳索侧向卷腹', '腹斜肌', '绳索器械', '未分级', '将电缆手柄连接到低滑轮上并站在机器旁边。用距离机器最远的手抓住手柄，并将另一只手放在臀部上。双脚分开与肩同宽，膝盖稍微弯曲。收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0223', 'cable side crunch', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach a cable handle to a low pulley and stand sideways to the machine. Grasp the handle with the hand furthest from the machine and place your other hand on your hip. Keep your feet shoulder-width apart and your knees slightly bent. With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0223-q2ADGqV.jpg', '/static/exercises/gifs/0223-q2ADGqV.gif', '© Gym visual — https://gymvisual.com/', '80690'),
('101717', '绳索深蹲划船绳索把手', '肱二头肌', '绳索器械', '未分级', '将绳子连接到腰部高度的缆绳机上。面对电缆机站立，双脚与肩同宽。弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。正手握住绳子，双手与肩同宽。收紧核心并将绳子拉向身体，将肩胛骨挤压在一起。保持肘部靠近身体并继续拉，直到双手到达胸部。在动作的最高点停顿片刻，然后慢慢松开绳子，并将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1717', 'cable squat row (with rope attachment)', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Attach a rope to a cable machine at waist height. Stand facing the cable machine with your feet shoulder-width apart. Bend your knees and lower your body into a squat position, keeping your back straight and chest up. Grasp the rope with an overhand grip, with your hands shoulder-width apart. Engage your core and pull the rope towards your body, squeezing your shoulder blades together. Keep your elbows close to your body and continue pulling until your hands reach your chest. Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1717-f7fnAIB.jpg', '/static/exercises/gifs/1717-f7fnAIB.gif', '© Gym visual — https://gymvisual.com/', '900697'),
('101644', '绳索深蹲弯举', '前臂', '绳索器械', '未分级', '将电缆手柄连接到电缆机器上的最低设置。面向机器站立，双脚分开与肩同宽。反手握住电缆手柄，手掌朝上，手臂完全伸展。将身体降低至蹲姿，保持背部挺直，膝盖位于脚趾后面。当你蹲下时，将电缆手柄卷向肩膀，保持肘部靠近身体两侧。在弯举的顶部暂停片刻，挤压二头肌。慢慢地将电缆手柄放回起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1644', 'cable squatting curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Attach a cable handle to the lowest setting on a cable machine. Stand facing the machine with your feet shoulder-width apart. Hold the cable handle with an underhand grip, palms facing up, and arms fully extended. Lower your body into a squat position, keeping your back straight and knees behind your toes. As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides. Pause for a moment at the top of the curl, squeezing your biceps. Slowly lower the cable handle back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1644-3XFdb1Z.jpg', '/static/exercises/gifs/1644-3XFdb1Z.gif', '© Gym visual — https://gymvisual.com/', '80692'),
('100224', '绳索站姿后侧腕弯举', '肱二头肌', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。正手握住电缆手柄，手掌朝下。保持手臂伸直，肘部靠近身体两侧。慢慢向上弯曲手腕，将电缆手柄拉向身体。在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0224', 'cable standing back wrist curl', 'lower arms', '前臂', '80', 'cable', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable handle with an overhand grip, palms facing down. Keep your arms straight and your elbows close to your sides. Slowly curl your wrists upward, bringing the cable handle towards your body. Pause for a moment at the top, then slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0224-VhX2JdE.jpg', '/static/exercises/gifs/0224-VhX2JdE.gif', '© Gym visual — https://gymvisual.com/', '697'),
('101375', '绳索站姿提踵', '腘绳肌', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。握住电缆机手柄或将电缆脚踝带固定在脚踝上。尽可能高地伸展脚踝，将脚后跟抬离地面。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1375', 'cable standing calf raise', 'lower legs', '小腿', '70', 'cable', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand facing a cable machine with your feet shoulder-width apart. Hold onto the cable machine handles or attach a cable ankle strap to your ankles. Raise your heels off the ground by extending your ankles as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1375-yl2IYyy.jpg', '/static/exercises/gifs/1375-yl2IYyy.gif', '© Gym visual — https://gymvisual.com/', '696'),
('100225', '绳索站姿交叉越过高位反向飞鸟', '斜方肌', '绳索器械', '未分级', '将 D 形手柄安装到缆绳机两侧与肩同高的位置。站在缆绳机的中间，双脚分开与肩同宽。正手握住手柄，并将手臂向两侧伸展，手掌朝前。在整个练习过程中保持肘部轻微弯曲并保持背部挺直。当您将手柄拉向身体前方时，收紧肩部肌肉并将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0225', 'cable standing cross-over high reverse fly', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","后侧DELTOIDS"]', 'Attach a D-handle to each side of a cable machine at shoulder height. Stand in the middle of the cable machine with your feet shoulder-width apart. Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward. Keep a slight bend in your elbows and maintain a straight back throughout the exercise. Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body. Pause for a moment at the peak of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0225-P5p0j8B.jpg', '/static/exercises/gifs/0225-P5p0j8B.gif', '© Gym visual — https://gymvisual.com/', '320701'),
('100226', '绳索站姿卷腹', '腹斜肌', '绳索器械', '未分级', '将电缆手柄连接到高滑轮上，并背对机器站立。双手握住手柄并将其放在脑后，保持肘部弯曲。双脚分开与肩同宽站立，膝盖稍微弯曲。保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。在动作底部暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0226', 'cable standing crunch', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach a cable handle to a high pulley and stand facing away from the machine. Hold the handle with both hands and place it behind your head, keeping your elbows bent. Stand with your feet shoulder-width apart and your knees slightly bent. Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs. Pause for a moment at the bottom of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0226-jpgqxiS.jpg', '/static/exercises/gifs/0226-jpgqxiS.gif', '© Gym visual — https://gymvisual.com/', '80696'),
('100874', '绳索站姿卷腹绳索把手', '腹斜肌', '绳索器械', '未分级', '将一根绳子连接到胸部高度的缆绳机上。背对机器站立，双脚与肩同宽。双手握住绳子并将其放在脑后，保持肘部弯曲。收紧腹肌，慢慢向前挤压躯干，使肘部靠近膝盖。在卷腹的最高点暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0874', 'cable standing crunch (with rope attachment)', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Attach a rope to a cable machine at chest height. Stand facing away from the machine with your feet shoulder-width apart. Hold the rope with both hands and bring it behind your head, keeping your elbows bent. Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees. Pause for a moment at the top of the crunch, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0874-XU3ePuv.jpg', '/static/exercises/gifs/0874-XU3ePuv.gif', '© Gym visual — https://gymvisual.com/', '80703'),
('100227', '绳索站姿飞鸟', '三角肌', '绳索器械', '未分级', '将手柄连接到胸部高度的电缆上。双脚分开与肩同宽站立，背对缆绳机。正手握住手柄，手掌朝前。稍微向前一步以在缆绳中产生张力。在整个练习过程中保持核心参与并保持背部挺直。肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。在运动的最高点挤压胸部肌肉。慢慢扭转动作，将手臂恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '0227', 'cable standing fly', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Attach the handles to the cables at chest height. Stand with your feet shoulder-width apart, facing away from the cable machine. Grasp the handles with an overhand grip, palms facing forward. Step forward slightly to create tension in the cables. Keep your core engaged and your back straight throughout the exercise. With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest. Squeeze your chest muscles at the peak of the movement. Slowly reverse the movement, returning your arms to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0227-Pr9Rhf4.jpg', '/static/exercises/gifs/0227-Pr9Rhf4.gif', '© Gym visual — https://gymvisual.com/', '900698'),
('100228', '绳索站姿伸髋', '腘绳肌', '绳索器械', '未分级', '将电缆连接到低滑轮上，并背对机器站立。将电缆绕在脚踝上，双脚分开与肩同宽站立。在整个练习过程中保持核心参与并保持背部挺直。慢慢地将腿向后伸直，在动作的最高点挤压臀部。暂停片刻，然后回到起始位置。重复所需的重复次数。换边并用另一条腿重复。', 'exercise-dataset', '0228', 'cable standing hip extension', 'upper legs', '大腿', '40', 'cable', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Attach a cable to a low pulley and stand facing away from the machine. Place the cable around your ankle and stand with your feet shoulder-width apart. Keep your core engaged and your back straight throughout the exercise. Slowly extend your leg straight back, squeezing your glutes at the top of the movement. Pause for a moment, then return to the starting position. Repeat for the desired number of repetitions. Switch sides and repeat with the other leg.', '/static/exercises/images/0228-Kpajagk.jpg', '/static/exercises/gifs/0228-Kpajagk.gif', '© Gym visual — https://gymvisual.com/', '900701'),
('100229', '绳索站姿内侧弯举', '前臂', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。反手握住电缆手柄，手掌朝上。保持肘部靠近身体两侧，上臂保持静止。呼气并将绳索手柄卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并缓慢地将电缆手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0229', 'cable standing inner curl', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand facing a cable machine with your feet shoulder-width apart. Grasp the cable handle with an underhand grip, palms facing up. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the cable handle towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0229-YwnI4ja.jpg', '/static/exercises/gifs/0229-YwnI4ja.gif', '© Gym visual — https://gymvisual.com/', '80702'),
('100230', '绳索站姿抬举', '腹斜肌', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。双手握住电缆手柄并将其置于腰部高度。在整个练习过程中启动核心并保持背部挺直。保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0230', 'cable standing lift', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Hold the cable handle with both hands and position it at waist height. Engage your core and maintain a straight back throughout the exercise. Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso. Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0230-qFpAkpP.jpg', '/static/exercises/gifs/0230-qFpAkpP.gif', '© Gym visual — https://gymvisual.com/', '900701'),
('100231', '绳索站姿单臂肱三头肌臂屈伸', '肩部', '绳索器械', '未分级', '双脚分开与肩同宽站立，面向绳索机。用右手握住电缆手柄，掌心朝下，调整手臂位置，使其完全伸展并与地面平行。保持肘部静止并靠近身体。慢慢弯曲肘部，将电缆手柄向脑后降低。在动作底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数，然后换边并用左臂进行练习。', 'exercise-dataset', '0231', 'cable standing one arm triceps extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground. Keep your elbow stationary and close to your body. Slowly bend your elbow, lowering the cable handle towards the back of your head. Pause for a moment at the bottom of the movement, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.', '/static/exercises/images/0231-sYCcnon.jpg', '/static/exercises/gifs/0231-sYCcnon.gif', '© Gym visual — https://gymvisual.com/', '400708'),
('101376', '绳索站姿单腿提踵', '踝部肌群', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。抓住电缆机以获得支撑。将一条腿抬离地面并用另一条腿保持平衡。慢慢地将脚跟抬离地面，将身体抬起到脚趾上。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '1376', 'cable standing one leg calf raise', 'lower legs', '小腿', '70', 'cable', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand facing a cable machine with your feet shoulder-width apart. Hold onto the cable machine for support. Lift one leg off the ground and balance on the other leg. Slowly raise your heel off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/1376-fgc9Xdl.jpg', '/static/exercises/gifs/1376-fgc9Xdl.gif', '© Gym visual — https://gymvisual.com/', '709'),
('100232', '绳索站姿下拉绳索', '前臂', '绳索器械', '未分级', '将绳索连接到最高设置的缆绳机上。面向机器站立，双脚分开与肩同宽。正手握住绳子，手掌朝下。在整个练习过程中保持背部挺直并保持核心参与。将绳子向下拉向大腿，挤压二头肌。在底部停顿片刻，然后慢慢地将绳子放回原位。重复所需的重复次数。', 'exercise-dataset', '0232', 'cable standing pulldown (with rope)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Attach a rope to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing down. Keep your back straight and core engaged throughout the exercise. Pull the rope down towards your thighs, squeezing your biceps. Pause for a moment at the bottom, then slowly release the rope back up. Repeat for the desired number of repetitions.', '/static/exercises/images/0232-CvPn9WV.jpg', '/static/exercises/gifs/0232-CvPn9WV.gif', '© Gym visual — https://gymvisual.com/', '900708'),
('100233', '绳索站姿三角肌后束划船绳索', '斜方肌', '绳索器械', '未分级', '面向缆绳机站立，双脚与肩同宽。用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。保持背部挺直，核心肌群参与。将电缆拉向您的身体，将肩胛骨挤压在一起。在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0233', 'cable standing rear delt row (with rope)', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Stand facing a cable machine with your feet shoulder-width apart. Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable. Keep your back straight and your core engaged. Pull the cable towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0233-ZfyAGhK.jpg', '/static/exercises/gifs/0233-ZfyAGhK.gif', '© Gym visual — https://gymvisual.com/', '400713'),
('101727', '绳索站姿反向握单臂过顶肱三头肌伸展', '肩部', '绳索器械', '未分级', '背对缆绳机站立，双脚与肩同宽。用手握住电缆手柄，并将手臂伸过头顶，保持肘部靠近头部。保持上臂静止，弯曲肘部，慢慢将电缆手柄降低到脑后。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1727', 'cable standing reverse grip one arm overhead tricep extension', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand facing away from the cable machine with your feet shoulder-width apart. Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head. Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1727-i11JWU7.jpg', '/static/exercises/gifs/1727-i11JWU7.gif', '© Gym visual — https://gymvisual.com/', '900718'),
('100234', '绳索站姿划船V字杆', '肱二头肌', '绳索器械', '未分级', '面对电缆机站立，双脚与肩同宽。正手握住 V 形杆附件，手掌朝下。保持背部挺直，核心肌群参与。将 V 形杆拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0234', 'cable standing row (v-bar)', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar attachment with an overhand grip, palms facing down. Keep your back straight and your core engaged. Pull the v-bar towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0234-4f8RXP8.jpg', '/static/exercises/gifs/0234-4f8RXP8.gif', '© Gym visual — https://gymvisual.com/', '900709'),
('100235', '绳索站姿肩部外旋旋转', '肩袖肌群', '绳索器械', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将手臂伸向前方，与地面平行，握住电缆手柄。保持肘部稍微弯曲，肩胛骨向后拉。慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0235', 'cable standing shoulder external rotation', 'shoulders', '肩部', '30', 'cable', 'rotator cuff', 'delts', '三角肌', '["肩袖肌群","斜方肌"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Hold the cable handle with your arm extended in front of you, parallel to the ground. Keep your elbow slightly bent and your shoulder blades pulled back. Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0235-FWdVhcW.jpg', '/static/exercises/gifs/0235-FWdVhcW.gif', '© Gym visual — https://gymvisual.com/', '900712'),
('100236', '绳索站姿转体划船V字杆', '肱二头肌', '绳索器械', '未分级', '将 V 形杆附件连接到胸部高度的缆绳机上。面对电缆机站立，双脚与肩同宽。正手握住 V 形杆，手掌朝下。后退一步以在电缆中产生张力。在整个练习过程中保持背部挺直并保持核心参与。缩回肩胛骨并弯曲肘部，将 V 形杆拉向躯干。当你拉的时候，将你的躯干扭转到一侧，将肩胛骨挤压在一起。在动作的最高点暂停片刻，感受上背部的收缩。慢慢释放紧张并回到起始位置，松开躯干。重复该动作达到所需的重复次数，每次重复交替扭转方向。', 'exercise-dataset', '0236', 'cable standing twist row (v-bar)', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Attach a v-bar attachment to a cable machine at chest height. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down. Take a step back to create tension in the cable. Keep your back straight and core engaged throughout the exercise. Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows. As you pull, twist your torso to one side, squeezing your shoulder blades together. Pause for a moment at the top of the movement, feeling the contraction in your upper back. Slowly release the tension and return to the starting position, untwisting your torso. Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep.', '/static/exercises/images/0236-JOZhu2h.jpg', '/static/exercises/gifs/0236-JOZhu2h.gif', '© Gym visual — https://gymvisual.com/', '900713'),
('101269', '绳索站姿向上直交叉', '三角肌', '绳索器械', '未分级', '站在缆绳机中间，双脚分开与肩同宽。手掌朝下握住电缆手柄，手臂伸直至两侧。保持双臂伸直，将双手放在身体前面，相互交叉。暂停片刻，然后慢慢回到起始位置，保持双臂伸展。重复所需的重复次数。', 'exercise-dataset', '1269', 'cable standing up straight crossovers', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Stand in the middle of a cable machine with your feet shoulder-width apart. Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides. Keeping your arms straight, bring your hands together in front of your body, crossing them over each other. Pause for a moment, then slowly return to the starting position, keeping your arms extended. Repeat for the desired number of repetitions.', '/static/exercises/images/1269-UKWTJWR.jpg', '/static/exercises/gifs/1269-UKWTJWR.gif', '© Gym visual — https://gymvisual.com/', '900714'),
('100238', '绳索直臂下拉', '肩部', '绳索器械', '未分级', '将直杆连接到缆绳机的高滑轮上。面向机器站立，双脚分开与肩同宽。正手握住杠铃，保持手臂伸直，手掌朝下。收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0238', 'cable straight arm pulldown', 'back', '背部', '20', 'cable', 'shoulders', 'lats', '背阔肌', '["肩部","肱二头肌"]', 'Attach a straight bar to the high pulley of a cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down. Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement. Pause for a moment at the bottom, then slowly return the bar to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0238-x69MAlq.jpg', '/static/exercises/gifs/0238-x69MAlq.gif', '© Gym visual — https://gymvisual.com/', '80713'),
('100237', '绳索直臂下拉绳索', '肱二头肌', '绳索器械', '未分级', '将绳索连接到最高设置的缆绳机上。面向机器站立，双脚分开与肩同宽。双手抓住绳子，掌心朝下。将手臂完全伸展到身前，保持肘部稍微弯曲。收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。在底部停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0237', 'cable straight arm pulldown (with rope)', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Attach a rope to the cable machine at the highest setting. Stand facing the machine with your feet shoulder-width apart. Grasp the rope with both hands, palms facing down. Extend your arms fully in front of you, keeping your elbows slightly bent. Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight. Pause for a moment at the bottom, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0237-DT14T9T.jpg', '/static/exercises/gifs/0237-DT14T9T.gif', '© Gym visual — https://gymvisual.com/', '80718'),
('100239', '绳索直后侧坐姿划船', '肱二头肌', '绳索器械', '未分级', '坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。正手握住电缆手柄，手掌朝下。保持背部挺直，并从臀部稍微向前倾斜。将电缆手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0239', 'cable straight back seated row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂","肩部"]', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent. Grasp the cable handles with an overhand grip, palms facing down. Keep your back straight and lean slightly forward from the hips. Pull the cable handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0239-Tq6gbK6.jpg', '/static/exercises/gifs/0239-Tq6gbK6.gif', '© Gym visual — https://gymvisual.com/', '240717'),
('100240', '绳索仰卧反向飞鸟', '斜方肌', '绳索器械', '未分级', '将 D 形手柄连接到低滑轮缆绳机上，并面朝下躺在平凳上。每只手握住 D 形手柄，手掌朝下，并将双臂伸直至前方。保持手臂伸直，将它们向两侧举起，直到与地板平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0240', 'cable supine reverse fly', 'shoulders', '肩部', '30', 'cable', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Attach a D-handle to a low pulley cable machine and lie face down on a flat bench. Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you. Keeping your arms straight, raise them out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0240-PQcUlDi.jpg', '/static/exercises/gifs/0240-PQcUlDi.gif', '© Gym visual — https://gymvisual.com/', '320716'),
('102464', '绳索蒂博杜式皮划艇式划船', '肱二头肌', '绳索器械', '未分级', '将电缆手柄连接到低滑轮上，面向机器坐着，双脚平放在地板上。用右手抓住手柄，完全伸展手臂，保持肘部轻微弯曲。从臀部开始向前倾斜，保持背部挺直并收紧腹肌。缩回肩胛骨并弯曲肘部，将手柄拉向躯干，保持手臂靠近身体。在动作的最高点挤压背部肌肉，然后慢慢回到起始位置。重复所需的重复次数，然后换边并用左臂执行。', 'exercise-dataset', '2464', 'cable thibaudeau kayak row', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor. Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow. Lean forward from your hips, keeping your back straight and your abs engaged. Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body. Squeeze your back muscles at the top of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and perform with your left arm.', '/static/exercises/images/2464-ZgwWBoC.jpg', '/static/exercises/gifs/2464-ZgwWBoC.gif', '© Gym visual — https://gymvisual.com/', '900717'),
('100241', '绳索肱三头肌下压V字杆', '前臂', '绳索器械', '未分级', '在最高设置下将 V 形杆附件连接到电缆机上。面对电缆机站立，双脚与肩同宽。正手握住 V 形杆，手掌朝下，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。在动作的底部暂停片刻，挤压你的三头肌。吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。重复所需的重复次数。', 'exercise-dataset', '0241', 'cable triceps pushdown (v-bar)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a v-bar attachment to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and exhale as you push the v-bar down until your arms are fully extended. Pause for a moment at the bottom of the movement, squeezing your triceps. Inhale as you slowly return the v-bar to the starting position, maintaining control. Repeat for the desired number of repetitions.', '/static/exercises/images/0241-gAwDzB3.jpg', '/static/exercises/gifs/0241-gAwDzB3.gif', '© Gym visual — https://gymvisual.com/', '320718'),
('102405', '绳索肱三头肌下压V字杆臂弯举托板', '前臂', '绳索器械', '未分级', '在最高设置下将 V 形杆附件连接到电缆机上。面对电缆机站立，双脚与肩同宽。正手握住 V 形杆，手掌朝下，双手与肩同宽。在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。在动作的底部暂停片刻，挤压你的三头肌。吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。重复所需的重复次数。', 'exercise-dataset', '2405', 'cable triceps pushdown (v-bar) (with arm blaster)', 'upper arms', '上臂', '50', 'cable', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Attach a v-bar attachment to the cable machine at the highest setting. Stand facing the cable machine with your feet shoulder-width apart. Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary throughout the exercise. Engage your triceps and exhale as you push the v-bar down until your arms are fully extended. Pause for a moment at the bottom of the movement, squeezing your triceps. Inhale as you slowly return the v-bar to the starting position, maintaining control. Repeat for the desired number of repetitions.', '/static/exercises/images/2405-OxJk1fg.jpg', '/static/exercises/gifs/2405-OxJk1fg.gif', '© Gym visual — https://gymvisual.com/', '320725'),
('100242', '绳索团身反向卷腹', '髋屈肌', '绳索器械', '未分级', '将电缆连接到低滑轮上，然后面朝上躺在垫子上。用双手握住电缆并将双臂伸直至胸部上方。弯曲膝盖并抬起双腿，使膝盖靠近胸部。同时，将骨盆向胸部弯曲，将臀部抬离地面。在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0242', 'cable tuck reverse crunch', 'waist', '腰腹', '60', 'cable', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Attach a cable to a low pulley and lie down on a mat facing up. Hold the cable with both hands and extend your arms straight up above your chest. Bend your knees and lift your legs up, bringing your knees towards your chest. At the same time, curl your pelvis up towards your chest, lifting your hips off the ground. Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0242-TXtXc84.jpg', '/static/exercises/gifs/0242-TXtXc84.gif', '© Gym visual — https://gymvisual.com/', '80720'),
('100243', '绳索转体', '腹斜肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，面向绳索机。双手握住电缆手柄于胸前，保持双臂略微弯曲。启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。动作结束时暂停片刻，感受腹肌和斜肌的收缩。缓慢返回起始位置，抵抗绳索的拉力。向左侧重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0243', 'cable twist', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and twist your torso to the right, pulling the cable across your body. Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques. Slowly return to the starting position, resisting the cable''s pull. Repeat the movement to the left side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0243-aVs3BR3.jpg', '/static/exercises/gifs/0243-aVs3BR3.gif', '© Gym visual — https://gymvisual.com/', '900717'),
('100862', '绳索转体向上向下', '腹斜肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，面向绳索机。双手握住电缆手柄于胸前，保持双臂略微弯曲。启动你的核心并慢慢地将你的躯干旋转到一侧，保持你的臀部和腿部稳定。旋转结束时暂停片刻，然后慢慢回到起始位置。向另一侧重复旋转。继续交替进行所需的重复次数。', 'exercise-dataset', '0862', 'cable twist (up-down)', 'waist', '腰腹', '60', 'cable', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Stand with your feet shoulder-width apart, facing the cable machine. Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent. Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat the rotation to the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0862-fhZQPlV.jpg', '/static/exercises/gifs/0862-fhZQPlV.gif', '© Gym visual — https://gymvisual.com/', '900720'),
('100244', '绳索转体拉', '肩部', '绳索器械', '未分级', '将电缆手柄连接到低滑轮上并面向机器站立。用左手抓住手柄，离开机器，完全伸展手臂。双脚分开与肩同宽，膝盖稍微弯曲。在整个练习过程中保持背部挺直，核心肌群参与其中。将手柄拉向您的身体，同时将您的躯干向右旋转。动作结束时挤压背部肌肉。慢慢回到起始位置，保持绳索的张力。重复所需的重复次数，然后换边并用右手执行。', 'exercise-dataset', '0244', 'cable twisting pull', 'back', '背部', '20', 'cable', 'shoulders', 'lats', '背阔肌', '["肩部","肱二头肌"]', 'Attach a cable handle to a low pulley and stand facing the machine. Grasp the handle with your left hand and step away from the machine, extending your arm fully. Position your feet shoulder-width apart, with your knees slightly bent. Keep your back straight and your core engaged throughout the exercise. Pull the handle towards your body, rotating your torso to the right as you do so. Squeeze your back muscles at the end of the movement. Slowly return to the starting position, keeping tension on the cable. Repeat for the desired number of repetitions, then switch sides and perform with your right hand.', '/static/exercises/images/0244-zCgxPbV.jpg', '/static/exercises/gifs/0244-zCgxPbV.gif', '© Gym visual — https://gymvisual.com/', '900721'),
('101645', '绳索双臂弯举上斜训练凳', '前臂', '绳索器械', '未分级', '坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地面上。反手握住电缆手柄，手掌朝上，手臂完全伸展。保持上臂静止，呼气并将手柄向肩膀弯曲，同时收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将手柄放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1645', 'cable two arm curl on incline bench', 'upper arms', '上臂', '50', 'cable', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an incline bench with your back against the pad and your feet flat on the ground. Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1645-H9y3Dkr.jpg', '/static/exercises/gifs/1645-H9y3Dkr.gif', '© Gym visual — https://gymvisual.com/', '80730'),
('101728', '绳索双臂肱三头肌后踢', '肩部', '绳索器械', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。双手握住电缆手柄，手掌朝内，手臂弯曲成 90 度角。保持上臂静止，向后伸展前臂，直到手臂完全伸展。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1728', 'cable two arm tricep kickback', 'upper arms', '上臂', '50', 'cable', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle. Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1728-vvNjDJS.jpg', '/static/exercises/gifs/1728-vvNjDJS.gif', '© Gym visual — https://gymvisual.com/', '560727'),
('100245', '绳索反握下拉', '肱二头肌', '绳索器械', '未分级', '调整缆绳机，使下拉杆位于您头部上方的高度。坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。保持背部挺直并稍微向后倾斜。将杠铃向下拉向胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0245', 'cable underhand pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the cable machine so that the pulldown bar is at a height above your head. Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and lean back slightly. Pull the bar down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0245-xBYcQHj.jpg', '/static/exercises/gifs/0245-xBYcQHj.gif', '© Gym visual — https://gymvisual.com/', '80724'),
('101270', '绳索上部胸部交叉', '三角肌', '绳索器械', '未分级', '将手柄连接到胸部高度的电缆上。站在绳索机的中央，一只脚稍微在另一只脚前面。手掌朝下抓住手柄，手臂向两侧伸展。保持肘部轻微弯曲并启动核心肌群。将电缆在胸前拉到一起，使它们相互交叉。在运动的最高点挤压胸部肌肉。慢慢地将电缆释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1270', 'cable upper chest crossovers', 'chest', '胸部', '10', 'cable', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Attach the handles to the cables at chest height. Stand in the center of the cable machine with one foot slightly in front of the other. Grasp the handles with your palms facing down and your arms extended out to the sides. Keep a slight bend in your elbows and engage your core. Pull the cables together in front of your chest, crossing them over each other. Squeeze your chest muscles at the peak of the movement. Slowly release the cables back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1270-j7XMAyn.jpg', '/static/exercises/gifs/1270-j7XMAyn.gif', '© Gym visual — https://gymvisual.com/', '900727'),
('101324', '绳索上部划船', '肱二头肌', '绳索器械', '未分级', '将直杆连接到胸部高度的缆绳机上。面向机器站立，双脚分开与肩同宽。正手握住杠铃，双手距离略宽于肩宽。保持背部挺直，核心肌群参与。将杠铃拉向上胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢地将杠铃释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1324', 'cable upper row', 'back', '背部', '20', 'cable', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Attach a straight bar to a cable machine at chest height. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the bar towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement. Slowly release the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1324-PQStVXH.jpg', '/static/exercises/gifs/1324-PQStVXH.gif', '© Gym visual — https://gymvisual.com/', '900726'),
('100246', '绳索直立划船', '斜方肌', '绳索器械', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。在整个练习过程中保持背部挺直，核心肌群参与其中。用肘部引导，将电缆附件笔直向上拉向下巴。在顶部暂停片刻，将肩胛骨挤压在一起。缓慢地将电缆附件放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0246', 'cable upright row', 'shoulders', '肩部', '30', 'cable', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip. Keep your back straight and your core engaged throughout the exercise. Pull the cable attachment straight up towards your chin, leading with your elbows. Pause for a moment at the top, squeezing your shoulder blades together. Slowly lower the cable attachment back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0246-cALKspW.jpg', '/static/exercises/gifs/0246-cALKspW.gif', '© Gym visual — https://gymvisual.com/', '480727'),
('101325', '绳索宽距握后侧下拉颈后颈部', '肱二头肌', '绳索器械', '未分级', '调整缆绳机，使下拉杆位于您头部上方的高度。坐在座椅上，用宽的正手握法抓住下拉杆。稍微向后倾斜时，保持背部挺直，挺胸。将杠铃向下拉至上胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1325', 'cable wide grip rear pulldown behind neck', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the cable machine so that the pulldown bar is at a height above your head. Sit down on the seat and grab the pulldown bar with a wide overhand grip. Keep your back straight and your chest up as you lean back slightly. Pull the bar down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1325-CmEr4pM.jpg', '/static/exercises/gifs/1325-CmEr4pM.gif', '© Gym visual — https://gymvisual.com/', '80736'),
('100247', '绳索腕弯举', '肱二头肌', '绳索器械', '未分级', '将直杆连接到低滑轮电缆机上。面向机器站立，双脚分开与肩同宽。反手握住杠铃，手掌朝上，双手与肩同宽。将前臂放在长凳或垫子上，手腕悬在边缘上。保持前臂静止，呼气并尽可能向上弯曲手腕。在顶部暂停片刻，然后吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0247', 'cable wrist curl', 'lower arms', '前臂', '80', 'cable', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Attach a straight bar to a low pulley cable machine. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your forearms on a bench or pad, with your wrists hanging off the edge. Keeping your forearms stationary, exhale and curl your wrists upward as far as possible. Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0247-LrV4s90.jpg', '/static/exercises/gifs/0247-LrV4s90.gif', '© Gym visual — https://gymvisual.com/', '729'),
('101407', '小腿推拉伸双手抵住靠墙', '腘绳肌', '自重', '未分级', '面向墙壁站立，双脚分开与臀部同宽。将双手靠在墙上，与肩同高。一只脚向后退一步，脚跟保持在地面上，腿伸直。稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。保持拉伸 20-30 秒。换腿并重复拉伸。', 'exercise-dataset', '1407', 'calf push stretch with hands against wall', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Stand facing a wall with your feet hip-width apart. Place your hands against the wall at shoulder height. Step back with one foot, keeping your heel on the ground and your leg straight. Bend your front knee slightly and lean forward, feeling a stretch in your calf. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', '/static/exercises/images/1407-PzNxakt.jpg', '/static/exercises/gifs/1407-PzNxakt.gif', '© Gym visual — https://gymvisual.com/', '900438'),
('101377', '小腿拉伸双手抵住靠墙', '腘绳肌', '自重', '未分级', '面向墙壁站立，双脚分开与臀部同宽。将双手靠在墙上，与肩同高。右脚向后退一步，保持脚后跟着地，腿伸直。弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。保持拉伸 20-30 秒。换腿并重复拉伸。', 'exercise-dataset', '1377', 'calf stretch with hands against wall', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Stand facing a wall with your feet hip-width apart. Place your hands against the wall at shoulder height. Step your right foot back, keeping your heel on the ground and your leg straight. Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', '/static/exercises/images/1377-m0tCHqc.jpg', '/static/exercises/gifs/1377-m0tCHqc.gif', '© Gym visual — https://gymvisual.com/', '900437'),
('101378', '小腿拉伸绳索', '腘绳肌', '绳索', '未分级', '面向墙壁或坚固物体站立，双脚分开与臀部同宽。双手握住绳子的两端，将绳子的中间放在右脚掌周围。左脚向后退一步，脚跟保持在地面上，腿伸直。身体前倾，保持背部挺直，轻轻拉动绳子以伸展小腿。保持拉伸 20-30 秒，然后放松。在另一条腿上重复。', 'exercise-dataset', '1378', 'calf stretch with rope', 'lower legs', '小腿', '70', 'rope', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Stand facing a wall or sturdy object with your feet hip-width apart. Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot. Step back with your left foot, keeping your heel on the ground and your leg straight. Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf. Hold the stretch for 20-30 seconds, then release. Repeat on the other leg.', '/static/exercises/images/1378-1LVFcEn.jpg', '/static/exercises/gifs/1378-1LVFcEn.gif', '© Gym visual — https://gymvisual.com/', '901334'),
('100248', '弯杆杆仰卧划船', '肱二头肌', '杠铃', '未分级', '在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。向下伸手，正手抓住杠铃，距离略宽于肩宽。双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。将杠铃拉向胸部，将肩胛骨挤压在一起。将杠铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0248', 'cambered bar lying row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a barbell on the floor and lie face down on a bench with your chest just off the edge. Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart. With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms. Pull the barbell towards your chest, squeezing your shoulder blades together. Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0248-R5swFnc.jpg', '/static/exercises/gifs/0248-R5swFnc.gif', '© Gym visual — https://gymvisual.com/', '900535'),
('102963', '船长椅椅上直举腿', '髋屈肌', '自重', '未分级', '坐在船长椅上，背部靠在靠背上，前臂放在扶手垫上。保持上半身稳定，背部挺直。收紧腹肌并将双腿抬起到身前，保持伸直。继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2963', 'captains chair straight leg raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads. Keep your upper body stable and your back straight. Engage your abs and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2963-weoDEpH.jpg', '/static/exercises/gifs/2963-weoDEpH.gif', '© Gym visual — https://gymvisual.com/', '240438'),
('101548', '椅上腿伸展拉伸', '腘绳肌', '自重', '未分级', '坐在椅子边缘，背部挺直，双脚平放在地面上。将一只腿伸直在身前，脚跟保持在地面上。稍微向前倾，感受股四头肌的拉伸。保持这个姿势20-30秒。换腿并重复拉伸。', 'exercise-dataset', '1548', 'chair leg extended stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","小腿肌群"]', 'Sit on the edge of a chair with your back straight and feet flat on the ground. Extend one leg straight out in front of you, keeping your heel on the ground. Lean forward slightly, feeling a stretch in your quadriceps. Hold this position for 20-30 seconds. Switch legs and repeat the stretch.', '/static/exercises/images/1548-xGgAGPm.jpg', '/static/exercises/gifs/1548-xGgAGPm.gif', '© Gym visual — https://gymvisual.com/', '900437'),
('101271', '胸部前侧肩部拉伸', '三角肌', '自重', '未分级', '站直，双脚分开与肩同宽。将双臂伸直至前方，与肩同高。双臂交叉在身体前方，右臂放在左臂上方。手指交叉并将手掌压在一起。轻轻地将肩胛骨挤压在一起，然后将双手向前推，感觉胸部和肩膀前部有拉伸感。保持拉伸 20-30 秒，然后放松。重复所需的重复次数。', 'exercise-dataset', '1271', 'chest and front of shoulder stretch', 'chest', '胸部', '10', 'body weight', 'deltoids', 'pectorals', '胸肌', '["三角肌"]', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out in front of you at shoulder height. Cross your arms in front of your body, with your right arm on top of your left arm. Interlace your fingers and press your palms together. Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders. Hold the stretch for 20-30 seconds, then release. Repeat for the desired number of repetitions.', '/static/exercises/images/1271-Uto7l43.jpg', '/static/exercises/gifs/1271-Uto7l43.gif', '© Gym visual — https://gymvisual.com/', '900442'),
('100251', '双杠臂屈伸', '肱三头肌', '自重', '未分级', '将自己置于双杠上，双臂完全伸展，身体伸直。弯曲肘部，降低身体，直到肩膀低于肘部。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0251', 'chest dip', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Position yourself on parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0251-9WTm7dq.jpg', '/static/exercises/gifs/0251-9WTm7dq.gif', '© Gym visual — https://gymvisual.com/', '320435'),
('101430', '双杠臂屈伸臂屈伸引体向上深蹲架', '肱三头肌', '自重', '未分级', '将倾斜杆调整到您可以舒适地握住它们的高度。站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。跳起来并伸直双臂，将体重支撑在杠上。弯曲膝盖并将脚踝交叉在身后。弯曲肘部降低身体，保持胸部向上，肩膀向下。继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。推动手掌并伸展肘部，将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1430', 'chest dip (on dip-pull-up cage)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the dip bars to a height that allows you to comfortably grip them. Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart. Jump up and straighten your arms, supporting your body weight on the bars. Bend your knees and cross your ankles behind you. Lower your body by bending your elbows, keeping your chest up and your shoulders down. Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest. Push through your palms and extend your elbows to raise your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1430-XgWyAiA.jpg', '/static/exercises/gifs/1430-XgWyAiA.gif', '© Gym visual — https://gymvisual.com/', '320442'),
('102462', '双杠臂屈伸直杆', '肱三头肌', '自重', '未分级', '手掌朝下，双臂完全伸展，抓住双杠。弯曲膝盖并交叉脚踝。弯曲手臂，降低身体，直到肩膀低于肘部。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '2462', 'chest dip on straight bar', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Grab the parallel bars with your palms facing down and your arms fully extended. Bend your knees and cross your ankles. Lower your body by bending your arms until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2462-LQFOrMn.jpg', '/static/exercises/gifs/2462-LQFOrMn.gif', '© Gym visual — https://gymvisual.com/', '320443'),
('101272', '胸部拉伸健身球', '肩部', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。双手握住健身球，并将双臂伸直至身前。慢慢地将健身球移向胸部，感受胸部肌肉的拉伸。保持伸展几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1272', 'chest stretch with exercise ball', 'chest', '胸部', '10', 'stability ball', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold the exercise ball with both hands and extend your arms straight out in front of you. Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1272-ykA5tU7.jpg', '/static/exercises/gifs/1272-ykA5tU7.gif', '© Gym visual — https://gymvisual.com/', '901344'),
('103216', '胸部触碰俯卧撑（男）', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。当你降低身体时，用右手拍打胸部。将自己推回到起始位置。重复这个动作，这次用左手敲击胸部。继续交替进行所需的重复次数。', 'exercise-dataset', '3216', 'chest tap push-up (male)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you lower yourself, tap your chest with your right hand. Push yourself back up to the starting position. Repeat the movement, this time tapping your chest with your left hand. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3216-7E06s6d.jpg', '/static/exercises/gifs/3216-7E06s6d.gif', '© Gym visual — https://gymvisual.com/', '80443'),
('101326', '反手引体向上', '肱二头肌', '自重', '未分级', '悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。启动核心肌群，将身体拉向杠铃杆，以胸部为主导。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1326', 'chin-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart. Engage your core and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1326-T2mxWqc.jpg', '/static/exercises/gifs/1326-T2mxWqc.gif', '© Gym visual — https://gymvisual.com/', '900438'),
('100253', '引体上撑窄距平行握握', '肱二头肌', '自重', '未分级', '用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0253', 'chin-ups (narrow parallel grip)', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Hang from a pull-up bar with a narrow parallel grip, palms facing towards you. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0253-G70mEAJ.jpg', '/static/exercises/gifs/0253-G70mEAJ.gif', '© Gym visual — https://gymvisual.com/', '900445'),
('100257', '环绕膝拉伸', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双手放在臀部。稍微弯曲膝盖，将脚跟抬离地面，用脚掌保持平衡。保持膝盖弯曲，先顺时针旋转膝盖，然后逆时针旋转膝盖。执行所需的重复运动次数。', 'exercise-dataset', '0257', 'circles knee stretch', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Stand with your feet shoulder-width apart and your hands on your hips. Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet. Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise. Perform the movement for the desired number of repetitions.', '/static/exercises/images/0257-X7jbxra.jpg', '/static/exercises/gifs/0257-X7jbxra.gif', '© Gym visual — https://gymvisual.com/', '900444'),
('101273', '击掌俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手分开略宽于肩宽。弯曲肘部，将身体降低到地面，保持核心参与。爆发性地推动手掌，将身体推离地面。在半空中时，拍手，然后回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1273', 'clap push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your body towards the ground by bending your elbows, keeping your core engaged. Push through your palms explosively to propel your body off the ground. While in mid-air, clap your hands together before landing back in the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1273-wigSg76.jpg', '/static/exercises/gifs/1273-wigSg76.gif', '© Gym visual — https://gymvisual.com/', '900445'),
('100258', '时钟式俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。向上推回到起始位置，同时将身体旋转到中心。重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。每次重复时继续交替进行。', 'exercise-dataset', '0258', 'clock push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you lower, rotate your body to the left, extending your left arm straight out to the side. Push back up to the starting position, while rotating your body to the center. Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side. Continue alternating sides with each repetition.', '/static/exercises/images/0258-CMAxnsG.jpg', '/static/exercises/gifs/0258-CMAxnsG.gif', '© Gym visual — https://gymvisual.com/', '80444'),
('101327', '窄距握反手引体向上', '肱二头肌', '自重', '未分级', '抓住引体向上杆，手掌朝向自己，双手与肩同宽。悬挂在杠上，双臂完全伸展，双脚离开地面。收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1327', 'close grip chin-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart. Hang from the bar with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1327-VnfUNW7.jpg', '/static/exercises/gifs/1327-VnfUNW7.gif', '© Gym visual — https://gymvisual.com/', '900447'),
('100259', '窄距握俯卧撑', '胸肌', '自重', '未分级', '从高位平板支撑开始，双手并拢，位于肩膀正下方。收紧核心，将身体降低到地面，保持肘部靠近身体两侧。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0259', 'close-grip push-up', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start in a high plank position with your hands placed close together, directly under your shoulders. Engage your core and lower your body towards the ground, keeping your elbows close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0259-x6KpKpq.jpg', '/static/exercises/gifs/0259-x6KpKpq.gif', '© Gym visual — https://gymvisual.com/', '900446'),
('102398', '窄距握俯卧撑双膝', '胸肌', '自重', '未分级', '首先双手和膝盖着地，双手与肩同宽，膝盖与臀部同宽。弯曲肘部，将上身压向地面，使其靠近身体两侧。当你的胸部刚好高于地面时，暂停片刻。推动手掌以伸直手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2398', 'close-grip push-up (on knees)', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart. Lower your upper body towards the ground by bending your elbows, keeping them close to your sides. Pause for a moment when your chest is just above the ground. Push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2398-v3vLFW0.jpg', '/static/exercises/gifs/2398-v3vLFW0.gif', '© Gym visual — https://gymvisual.com/', '900451'),
('100260', '茧式卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0260', 'cocoons', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0260-SLKj2pX.jpg', '/static/exercises/gifs/0260-SLKj2pX.gif', '© Gym visual — https://gymvisual.com/', '900446'),
('101468', '螃蟹式转体脚尖触碰', '腹斜肌', '自重', '未分级', '首先坐在地上，膝盖弯曲，双脚平放在地板上。将双手放在身后，手指指向脚部，并将臀部抬离地面。将一条腿伸直到您面前，同时将另一只手伸向脚趾。返回起始位置并在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '1468', 'crab twist toe touch', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Start by sitting on the ground with your knees bent and feet flat on the floor. Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground. Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes. Return to the starting position and repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1468-xgsGFVM.jpg', '/static/exercises/gifs/1468-xgsGFVM.gif', '© Gym visual — https://gymvisual.com/', '900453'),
('100262', '跨体卷腹', '腹斜肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将上半身抬离地面，然后扭转，使右肘靠近左膝盖。在顶部停顿片刻，然后慢慢将上半身放回起始位置。在另一侧重复，将左肘靠近右膝盖。重复所需的重复次数。', 'exercise-dataset', '0262', 'cross body crunch', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat on the other side, bringing your left elbow towards your right knee. Repeat for the desired number of repetitions.', '/static/exercises/images/0262-rbu5UUb.jpg', '/static/exercises/gifs/0262-rbu5UUb.gif', '© Gym visual — https://gymvisual.com/', '80452'),
('100267', '卷腹双手过顶', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双臂伸直至头顶上方。收紧腹肌，将上半身抬离地面，向前向膝盖弯曲。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0267', 'crunch (hands overhead)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Extend your arms straight above your head. Engaging your abs, lift your upper body off the ground, curling forward towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0267-kjJ3VoQ.jpg', '/static/exercises/gifs/0267-kjJ3VoQ.gif', '© Gym visual — https://gymvisual.com/', '80453'),
('100271', '卷腹瑞士球', '髋屈肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。仰卧在球上，直到下背部得到支撑并且上半身与地板平行。将双手放在脑后或放在胸前。收紧腹肌，将上身抬向膝盖，躯干向前卷曲。在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0271', 'crunch (on stability ball)', 'waist', '腰腹', '60', 'stability ball', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso forward. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0271-MCUhf1F.jpg', '/static/exercises/gifs/0271-MCUhf1F.gif', '© Gym visual — https://gymvisual.com/', '81356'),
('100272', '卷腹瑞士球双臂直', '髋屈肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。仰卧在球上，直到下背部得到支撑并且上半身与地板平行。将双手放在脑后或交叉放在胸前。收紧腹肌，将上半身抬离球，将肩膀向臀部弯曲。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0272', 'crunch (on stability ball, arms straight)', 'waist', '腰腹', '60', 'stability ball', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Lie back on the ball until your lower back is supported and your upper body is parallel to the floor. Place your hands behind your head or cross them over your chest. Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0272-Sn8wxAI.jpg', '/static/exercises/gifs/0272-Sn8wxAI.gif', '© Gym visual — https://gymvisual.com/', '81361'),
('100274', '卷腹地板', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将肩膀抬离地面，向前向膝盖弯曲。在顶部停顿片刻，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0274', 'crunch floor', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your shoulders off the ground, curling forward towards your knees. Pause for a moment at the top, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0274-TFqbd8t.jpg', '/static/exercises/gifs/0274-TFqbd8t.gif', '© Gym visual — https://gymvisual.com/', '80454'),
('103016', '弯举向上', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3016', 'curl-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3016-g2oKspu.jpg', '/static/exercises/gifs/3016-g2oKspu.gif', '© Gym visual — https://gymvisual.com/', '900453'),
('103769', '屈膝礼弓步深蹲', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。右脚向斜后方跨出一步，跨过身体，交叉在左腿后面。弯曲双膝，就像行屈膝礼一样，将身体降低到地面。保持躯干直立，将体重放在前脚上。推动前脚返回起始位置。在另一侧重复，用左脚斜向后方跨过身体。', 'exercise-dataset', '3769', 'curtsey squat', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg. Bend both knees as if you were curtsying, lowering your body towards the ground. Keep your torso upright and your weight on your front foot. Push through your front foot to return to the starting position. Repeat on the other side, stepping diagonally behind and across your body with your left foot.', '/static/exercises/images/3769-gUjqdei.jpg', '/static/exercises/gifs/3769-gUjqdei.gif', '© Gym visual — https://gymvisual.com/', '456'),
('102331', '骑行交叉训练机', '股四头肌', '固定器械', '未分级', '调整座椅高度并将自己放在自行车交叉训练机上。将脚放在踏板上并抓住车把。开始以平稳且受控的动作踩踏。保持稳定的步伐并根据需要增加阻力。继续踩踏您的有氧运动所需的持续时间。', 'exercise-dataset', '2331', 'cycle cross trainer', 'cardio', '有氧', '90', 'leverage machine', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌"]', 'Adjust the seat height and position yourself on the cycle cross trainer. Place your feet on the pedals and grip the handlebars. Start pedaling in a smooth and controlled motion. Maintain a steady pace and increase the resistance if desired. Continue pedaling for the desired duration of your cardio workout.', '/static/exercises/images/2331-XSCHmiI.jpg', '/static/exercises/gifs/2331-XSCHmiI.gif', '© Gym visual — https://gymvisual.com/', '900859'),
('100276', '死虫式', '髋屈肌', '自重', '未分级', '平躺，双臂伸向天花板。弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。接合你的核心和下背部，将你的下背部压入地面。慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。暂停片刻，然后回到起始位置。用左臂和右腿重复该动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0276', 'dead bug', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your arms extended towards the ceiling. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees. Engage your core and lower back to press your lower back into the ground. Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor. Pause for a moment, then return to the starting position. Repeat the movement with your left arm and right leg. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0276-iny3m5y.jpg', '/static/exercises/gifs/0276-iny3m5y.gif', '© Gym visual — https://gymvisual.com/', '900458'),
('100277', '下斜卷腹', '髋屈肌', '自重', '未分级', '躺在倾斜的长凳上，双脚固定，膝盖弯曲成 90 度角。将双手放在脑后或放在胸前。收紧腹肌，将上半身抬向膝盖，卷曲躯干。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0277', 'decline crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle. Place your hands behind your head or across your chest. Engage your abs and lift your upper body towards your knees, curling your torso. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0277-9Ap7miY.jpg', '/static/exercises/gifs/0277-9Ap7miY.gif', '© Gym visual — https://gymvisual.com/', '80459'),
('100279', '下斜俯卧撑', '肱三头肌', '自重', '未分级', '将双手放在地面上，距离略宽于肩宽，双脚放在稳定的表面上。保持身体从头到脚呈一条直线，锻炼核心肌肉。弯曲肘部，使胸部靠近地面，使胸部靠近地面。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0279', 'decline push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface. Keep your body in a straight line from head to toe, engaging your core muscles. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0279-i5cEhka.jpg', '/static/exercises/gifs/0279-i5cEhka.gif', '© Gym visual — https://gymvisual.com/', '80460'),
('100282', '下斜坐向上', '髋屈肌', '自重', '未分级', '躺在倾斜的长凳上，双脚固定，膝盖弯曲。将双手放在脑后或放在胸前。收紧腹肌，将上半身抬离长凳，向前向膝盖弯曲。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0282', 'decline sit-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie on a decline bench with your feet secured and your knees bent. Place your hands behind your head or across your chest. Engage your abs and lift your upper body off the bench, curling forward towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0282-QLL2gdc.jpg', '/static/exercises/gifs/0282-QLL2gdc.gif', '© Gym visual — https://gymvisual.com/', '160461'),
('101274', '深幅俯卧撑', '肱三头肌', '哑铃', '未分级', '从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。弯曲肘部，使胸部靠近地面，使胸部靠近地面。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1274', 'deep push up', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1274-vptOQ4N.jpg', '/static/exercises/gifs/1274-vptOQ4N.gif', '© Gym visual — https://gymvisual.com/', '900664'),
('100283', '钻石俯卧撑', '胸肌', '自重', '未分级', '从高位平板支撑开始，双手并拢，拇指和食指形成菱形。让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。将胸部降低至双手形成的菱形，保持肘部靠近身体。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0283', 'diamond push-up', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers. Keep your body in a straight line from head to toe, engaging your core and glutes. Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0283-soIB2rj.jpg', '/static/exercises/gifs/0283-soIB2rj.gif', '© Gym visual — https://gymvisual.com/', '900463'),
('100284', '骑驴式提踵', '腘绳肌', '自重', '未分级', '将脚趾站立在升高的表面上，例如台阶或木块。将双手放在稳定的支撑物上，例如墙壁或栏杆，以保持平衡。尽可能高地抬高脚后跟，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0284', 'donkey calf raise', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your toes on an elevated surface, such as a step or block. Place your hands on a stable support, such as a wall or railing, for balance. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0284-u5ESqzH.jpg', '/static/exercises/gifs/0284-u5ESqzH.gif', '© Gym visual — https://gymvisual.com/', '466'),
('101275', '下落俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手分开略宽于肩宽。将胸部压向地面，保持肘部靠近身体。当你的胸部刚好高于地面时，迅速将膝盖放在地上。伸展双臂，将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1275', 'drop push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your chest towards the ground, keeping your elbows close to your body. Once your chest is just above the ground, quickly drop your knees to the ground. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1275-Q497lAE.jpg', '/static/exercises/gifs/1275-Q497lAE.gif', '© Gym visual — https://gymvisual.com/', '900467'),
('100285', '哑铃交替肱二头肌弯举', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数，交替手臂。', 'exercise-dataset', '0285', 'dumbbell alternate biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions, alternating arms.', '/static/exercises/images/0285-BU15nH4.jpg', '/static/exercises/gifs/0285-BU15nH4.gif', '© Gym visual — https://gymvisual.com/', '670'),
('102403', '哑铃交替肱二头肌弯举臂弯举托板', '前臂', '哑铃', '未分级', '站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝前。将手臂冲击波放在上臂上，确保牢固贴合。保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '2403', 'dumbbell alternate biceps curl (with arm blaster)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Place the arm blaster on your upper arms, ensuring a secure fit. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/2403-CfKsRbG.jpg', '/static/exercises/gifs/2403-CfKsRbG.gif', '© Gym visual — https://gymvisual.com/', '677'),
('101646', '哑铃交替锤式牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，双手各持一个哑铃，手掌面向躯干，双臂完全伸展。保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '1646', 'dumbbell alternate hammer preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended. Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', '/static/exercises/images/1646-fy7Tgy4.jpg', '/static/exercises/gifs/1646-fy7Tgy4.gif', '© Gym visual — https://gymvisual.com/', '80674'),
('101647', '哑铃交替牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，每只手各握一个哑铃，手掌朝上。将上臂放在牧师凳的垫子上，让手臂完全伸展。保持上臂静止，呼气并弯曲右手的哑铃，同时收缩二头肌。继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。暂停片刻，然后吸气，慢慢将哑铃放回起始位置。用左臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1647', 'dumbbell alternate preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with a dumbbell in each hand, palms facing up. Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend. Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps. Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with your left arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1647-NlfIbzq.jpg', '/static/exercises/gifs/1647-NlfIbzq.gif', '© Gym visual — https://gymvisual.com/', '80673'),
('101648', '哑铃交替坐姿锤式弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂向下伸展。保持背部挺直，肘部靠近躯干。呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。暂停片刻，然后吸气，慢慢将哑铃放回起始位置。用左臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1648', 'dumbbell alternate seated hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with your left arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1648-6em2Dxj.jpg', '/static/exercises/gifs/1648-6em2Dxj.gif', '© Gym visual — https://gymvisual.com/', '80676'),
('100286', '哑铃交替侧向推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。继续交替进行所需的重复次数。', 'exercise-dataset', '0286', 'dumbbell alternate side press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height. Press one dumbbell overhead while keeping the other dumbbell at shoulder height. Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0286-izMnLqz.jpg', '/static/exercises/gifs/0286-izMnLqz.gif', '© Gym visual — https://gymvisual.com/', '900675'),
('101649', '哑铃交替肱二头肌弯举腿抬高健身球', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。将健身球放在身后，并将一只脚放在上面，保持平衡。双臂完全伸展，肘部靠近身体两侧，将一只哑铃向肩膀弯曲，同时保持上臂静止。将哑铃放回起始位置，然后用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1649', 'dumbbell alternating bicep curl with leg raised on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Place an exercise ball behind you and position one foot on top of it, keeping your balance. With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary. Lower the dumbbell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1649-Zwiw7XR.jpg', '/static/exercises/gifs/1649-Zwiw7XR.gif', '© Gym visual — https://gymvisual.com/', '80688'),
('101650', '哑铃交替坐姿肱二头肌弯举健身球', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。每只手握住一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举一只哑铃，同时旋转前臂，直到手掌面向肩膀。吸气，慢慢将哑铃放回起始位置。用另一只手臂重复弯举动作。继续交替卷发达到所需的重复次数。', 'exercise-dataset', '1650', 'dumbbell alternating seated bicep curl on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder. Inhale and slowly lower the dumbbell back to the starting position. Repeat the curl with the other arm. Continue alternating curls for the desired number of repetitions.', '/static/exercises/images/1650-J74XlNf.jpg', '/static/exercises/gifs/1650-J74XlNf.gif', '© Gym visual — https://gymvisual.com/', '80685'),
('102137', '哑铃阿诺德推举', '肱三头肌', '哑铃', '未分级', '坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。向上推哑铃，直到手臂完全伸展，手掌朝前。抬起时旋转手腕，使手掌在动作的最高点朝前。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2137', 'dumbbell arnold press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上部胸部"]', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2137-Xy4jlWA.jpg', '/static/exercises/gifs/2137-Xy4jlWA.gif', '© Gym visual — https://gymvisual.com/', '900676'),
('100287', '哑铃阿诺德推举版本第二式', '肱三头肌', '哑铃', '未分级', '坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。向上推哑铃，直到手臂完全伸展，手掌朝前。抬起时旋转手腕，使手掌在动作的最高点朝前。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0287', 'dumbbell arnold press v. 2', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上部胸部"]', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent. Press the dumbbells upward until your arms are fully extended and your palms are facing forward. Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0287-eOrFCnx.jpg', '/static/exercises/gifs/0287-eOrFCnx.gif', '© Gym visual — https://gymvisual.com/', '900681'),
('100288', '哑铃环绕上拉', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，头放在一端，双脚牢牢踩在地上。双手握住哑铃，将手臂伸直至胸部上方。保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。在底部停顿片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0288', 'dumbbell around pullover', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","背阔肌"]', 'Lie flat on a bench with your head at one end and your feet firmly on the ground. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion. Pause for a moment at the bottom, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0288-vi8EhoE.jpg', '/static/exercises/gifs/0288-vi8EhoE.gif', '© Gym visual — https://gymvisual.com/', '400678'),
('100289', '哑铃卧推', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0289', 'dumbbell bench press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0289-SpYC0Kp.jpg', '/static/exercises/gifs/0289-SpYC0Kp.gif', '© Gym visual — https://gymvisual.com/', '679'),
('100290', '哑铃训练凳坐姿推举', '肱三头肌', '哑铃', '未分级', '坐在长凳上，每只手各拿一个哑铃，放在大腿上。向后倾斜，将哑铃放在胸部两侧，手掌朝前。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0290', 'dumbbell bench seated press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Sit on a bench with a dumbbell in each hand, resting on your thighs. Lean back and position the dumbbells to the sides of your chest, palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0290-3d7wHyd.jpg', '/static/exercises/gifs/0290-3d7wHyd.gif', '© Gym visual — https://gymvisual.com/', '900682'),
('100291', '哑铃训练凳深蹲', '股四头肌', '哑铃', '未分级', '将哑铃放在长凳前的地面上。背对长凳站立，双脚与肩同宽。弯曲膝盖和臀部，将自己降低到长凳上，保持胸部挺直，背部挺直。一旦你的臀部接触到长凳，就用脚后跟站起来，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0291', 'dumbbell bench squat', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Place a dumbbell on the ground in front of a bench. Stand facing away from the bench with your feet shoulder-width apart. Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight. Once your glutes touch the bench, push through your heels to stand back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0291-mnzcrIB.jpg', '/static/exercises/gifs/0291-mnzcrIB.gif', '© Gym visual — https://gymvisual.com/', '681'),
('100293', '哑铃俯身划船', '肱二头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。臀部向前弯曲，保持背部挺直，核心肌群参与。让你的手臂垂直垂向地板，肘部稍微弯曲。将哑铃拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0293', 'dumbbell bent over row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Let your arms hang straight down towards the floor, with your elbows slightly bent. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0293-BJ0Hz5L.jpg', '/static/exercises/gifs/0293-BJ0Hz5L.gif', '© Gym visual — https://gymvisual.com/', '160684'),
('101651', '哑铃肱二头肌弯举弓步保龄球式动态', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。右脚向前迈出一步，弯曲右膝，将身体降低至弓步位置。当你向前弓步时，将哑铃向上弯向肩膀，保持肘部靠近身体。在弓步底部，将躯干向右旋转，就像打保龄球一样。反转动作，右脚向后退一步，回到起始位置，同时放下哑铃。重复弓步和弯举动作，这次将躯干向左旋转。继续交替进行所需的重复次数。', 'exercise-dataset', '1651', 'dumbbell bicep curl lunge with bowling motion', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position. As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body. At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball. Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down. Repeat the lunge and curl motion, this time rotating your torso to the left. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1651-1VpF8db.jpg', '/static/exercises/gifs/1651-1VpF8db.gif', '© Gym visual — https://gymvisual.com/', '80691'),
('101652', '哑铃肱二头肌弯举健身球腿抬高', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。每只手握住一个哑铃，手掌朝前，双臂完全伸展。慢慢地将哑铃向肩膀弯曲，保持肘部靠近身体两侧。在动作的最高点暂停片刻，然后慢慢将哑铃放回起始位置。在进行二头肌弯举时，将一条腿抬离地面，并在整个练习过程中将其保持在空中。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1652', 'dumbbell bicep curl on exercise ball with leg raised', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides. Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position. While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1652-2NImIAG.jpg', '/static/exercises/gifs/1652-2NImIAG.gif', '© Gym visual — https://gymvisual.com/', '80696'),
('101653', '哑铃肱二头肌弯举鹳式站姿', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。将一条腿伸到身后，用脚趾保持平衡。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1653', 'dumbbell bicep curl with stork stance', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Extend one leg behind you, balancing on the toes of that foot. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1653-uSkDMYl.jpg', '/static/exercises/gifs/1653-uSkDMYl.gif', '© Gym visual — https://gymvisual.com/', '80691'),
('100294', '哑铃弯举', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0294', 'dumbbell biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0294-NbVPDMW.jpg', '/static/exercises/gifs/0294-NbVPDMW.gif', '© Gym visual — https://gymvisual.com/', '686'),
('102401', '哑铃肱二头肌弯举臂弯举托板', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝前。保持肘部靠近躯干，上臂保持静止。呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2401', 'dumbbell biceps curl (with arm blaster)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2401-nlJsbkW.jpg', '/static/exercises/gifs/2401-nlJsbkW.gif', '© Gym visual — https://gymvisual.com/', '693'),
('101654', '哑铃肱二头肌弯举反向', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1654', 'dumbbell biceps curl reverse', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1654-nFc4FyV.jpg', '/static/exercises/gifs/1654-nFc4FyV.gif', '© Gym visual — https://gymvisual.com/', '690'),
('101655', '哑铃肱二头肌弯举深蹲', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。保持背部挺直，肘部靠近身体两侧，呼气并将哑铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1655', 'dumbbell biceps curl squat', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1655-niXESDw.jpg', '/static/exercises/gifs/1655-niXESDw.gif', '© Gym visual — https://gymvisual.com/', '691'),
('101656', '哑铃肱二头肌弯举V字坐BOSU球', '前臂', '哑铃', '未分级', '坐在博苏球上，双脚平放在地上，膝盖弯曲成 90 度角。每只手握住一个哑铃，手掌朝前，双臂在身体两侧完全向下伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1656', 'dumbbell biceps curl v sit on bosu ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1656-H1XAdpk.jpg', '/static/exercises/gifs/1656-H1XAdpk.gif', '© Gym visual — https://gymvisual.com/', '700'),
('101201', '哑铃波比跳', '股四头肌', '哑铃', '未分级', '从站立位置开始，双脚分开与肩同宽，每只手各拿一个哑铃。将身体降低至蹲姿，将哑铃放在您面前的地面上。将双脚踢回到俯卧撑位置，保持身体呈一条直线。进行俯卧撑，弯曲肘部并将胸部降低到地面。将脚向后跳向双手，以蹲姿着地。爆发性地站起来，将哑铃从地上举起，放到肩膀上。将哑铃举过头顶，充分伸展手臂。将哑铃放回到肩膀上，然后重复整个序列，达到所需的重复次数。', 'exercise-dataset', '1201', 'dumbbell burpee', 'cardio', '有氧', '90', 'dumbbell', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群","肩部","肱三头肌","核心肌群"]', 'Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand. Lower your body into a squat position, placing the dumbbells on the ground in front of you. Kick your feet back into a push-up position, keeping your body in a straight line. Perform a push-up, bending your elbows and lowering your chest towards the ground. Jump your feet back towards your hands, landing in a squat position. Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders. Press the dumbbells overhead, fully extending your arms. Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions.', '/static/exercises/images/1201-0JtKWum.jpg', '/static/exercises/gifs/1201-0JtKWum.gif', '© Gym visual — https://gymvisual.com/', '240689'),
('100295', '哑铃翻举', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。通过反向运动将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0295', 'dumbbell clean', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend your knees and lower your hips into a squat position, keeping your back straight and chest up. Explosively extend your hips and knees, driving through your heels to jump off the ground. As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body. Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up. Lower the dumbbells back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0295-7Hg55JG.jpg', '/static/exercises/gifs/0295-7Hg55JG.gif', '© Gym visual — https://gymvisual.com/', '900690'),
('101731', '哑铃窄距握推举', '胸肌', '哑铃', '未分级', '坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。呼气时，用三头肌将哑铃举回到起始位置。确保只使用三头肌，不要使用前臂或二头肌来帮助举起哑铃。在收缩位置第二次暂停后，重复该动作达到规定的重复次数。', 'exercise-dataset', '1731', 'dumbbell close grip press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest. As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells. After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.', '/static/exercises/images/1731-7jGOBF3.jpg', '/static/exercises/gifs/1731-7jGOBF3.gif', '© Gym visual — https://gymvisual.com/', '900695'),
('100296', '哑铃窄距握推举', '胸肌', '哑铃', '未分级', '坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。呼气时，用三头肌将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0296', 'dumbbell close-grip press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs. Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest. As you exhale, use your triceps to lift the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0296-RxayqAZ.jpg', '/static/exercises/gifs/0296-RxayqAZ.gif', '© Gym visual — https://gymvisual.com/', '900694'),
('100297', '哑铃集中弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。完全伸展手臂并用反手握住哑铃。保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0297', 'dumbbell concentration curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh. Fully extend your arm and hold the dumbbell with an underhand grip. Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0297-gvsWLQw.jpg', '/static/exercises/gifs/0297-gvsWLQw.gif', '© Gym visual — https://gymvisual.com/', '80695'),
('103635', '哑铃对侧向前弓步', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。右脚向前迈出一步，保持背部挺直并启动核心。弯曲双膝降低身体，直到右大腿与地面平行。推动右脚跟回到起始位置。左腿重复上述动作。交替腿进行所需的重复次数。', 'exercise-dataset', '3635', 'dumbbell contralateral forward lunge', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, keeping your back straight and core engaged. Lower your body by bending both knees until your right thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg. Alternate legs for the desired number of repetitions.', '/static/exercises/images/3635-ecl28tP.jpg', '/static/exercises/gifs/3635-ecl28tP.gif', '© Gym visual — https://gymvisual.com/', '320698'),
('100298', '哑铃跨体锤式弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向身体。保持肘部靠近躯干，上臂保持静止。呼气并弯举哑铃，同时收缩二头肌，将哑铃穿过身体拉向对侧的肩膀。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0298', 'dumbbell cross body hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0298-Qyk5J3p.jpg', '/static/exercises/gifs/0298-Qyk5J3p.gif', '© Gym visual — https://gymvisual.com/', '80701'),
('101657', '哑铃跨体锤式弯举版本第二式', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向身体。保持肘部靠近躯干，上臂保持静止。呼气并弯举哑铃，同时收缩二头肌，使哑铃尽可能靠近另一侧的肩膀。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1657', 'dumbbell cross body hammer curl v. 2', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1657-HDYiZcY.jpg', '/static/exercises/gifs/1657-HDYiZcY.gif', '© Gym visual — https://gymvisual.com/', '80706'),
('100299', '哑铃古巴式推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。旋转手腕，使手掌朝前。慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。重复所需的重复次数。', 'exercise-dataset', '0299', 'dumbbell cuban press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down. Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended. Rotate your wrists so that your palms are facing forward. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so. Repeat for the desired number of repetitions.', '/static/exercises/images/0299-QfAKy1G.jpg', '/static/exercises/gifs/0299-QfAKy1G.gif', '© Gym visual — https://gymvisual.com/', '900699'),
('102136', '哑铃古巴式推举版本第二式', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。保持核心收紧，背部挺直，将哑铃垂直推过头顶，直到手臂完全伸展。旋转手腕，使手掌朝前。将哑铃放回至肩膀高度，将手腕旋转回起始位置。重复所需的重复次数。', 'exercise-dataset', '2136', 'dumbbell cuban press v. 2', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down. Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended. Rotate your wrists so that your palms are facing forward. Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2136-BqgCRif.jpg', '/static/exercises/gifs/2136-BqgCRif.gif', '© Gym visual — https://gymvisual.com/', '900704'),
('100300', '哑铃硬拉', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，脚趾指向前方。双手各握一个哑铃，手掌朝向身体，手臂向下伸展。弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0300', 'dumbbell deadlift', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart, toes pointing forward. Hold a dumbbell in each hand, palms facing your body, arms extended downwards. Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight. Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0300-nUwVh7b.jpg', '/static/exercises/gifs/0300-nUwVh7b.gif', '© Gym visual — https://gymvisual.com/', '80699'),
('100301', '哑铃下斜卧推', '肱三头肌', '哑铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。双手各握一个哑铃，双臂伸直至胸部上方，手掌朝前。慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。将哑铃推回起始位置，充分伸展手臂。重复所需的重复次数。', 'exercise-dataset', '0301', 'dumbbell decline bench press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie down on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0301-DwhEmmE.jpg', '/static/exercises/gifs/0301-DwhEmmE.gif', '© Gym visual — https://gymvisual.com/', '704'),
('100302', '哑铃下斜飞鸟', '肩部', '哑铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。双手各握一个哑铃，手掌相对，双臂伸至胸部上方。将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0302', 'dumbbell decline fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Lie on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0302-xXm4nYq.jpg', '/static/exercises/gifs/0302-xXm4nYq.gif', '© Gym visual — https://gymvisual.com/', '900703'),
('100303', '哑铃下斜锤式推举', '肱三头肌', '哑铃', '未分级', '躺在倾斜的长凳上，双脚固定，头部低于臀部。双手各握一个哑铃，手掌相对，双臂伸至胸部上方。将哑铃降低到胸部两侧，保持肘部稍微弯曲。将哑铃推回到起始位置，充分伸展手臂。重复所需的重复次数。', 'exercise-dataset', '0303', 'dumbbell decline hammer press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie on a decline bench with your feet secured and your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent. Press the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0303-1qrWgZ2.jpg', '/static/exercises/gifs/0303-1qrWgZ2.gif', '© Gym visual — https://gymvisual.com/', '900706'),
('101276', '哑铃下斜单臂飞鸟', '肩部', '哑铃', '未分级', '躺在斜凳上，一只手拿着哑铃，将其放在大腿上。用大腿帮助举起哑铃，将其举至与肩同宽，手掌朝向躯干。旋转手腕，使手掌朝前。吸气时，将哑铃慢慢降低到一侧，直到感觉到胸部有拉伸感。呼气并使用胸部肌肉将哑铃拉回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1276', 'dumbbell decline one arm fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh. Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso. Rotate your wrist so that the palm of your hand is facing forward. As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest. Exhale and use your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1276-NL6YBwN.jpg', '/static/exercises/gifs/1276-NL6YBwN.gif', '© Gym visual — https://gymvisual.com/', '900709'),
('101617', '哑铃下斜单臂锤式推举', '胸肌', '哑铃', '未分级', '躺在下斜长凳上，一只手握住哑铃，放在胸前。将手臂伸直向上，保持肘部稍微弯曲。将哑铃向肩膀方向降低，保持肘部靠近身体。将哑铃推回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1617', 'dumbbell decline one arm hammer press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie on a decline bench with a dumbbell in one hand, resting on your chest. Extend your arm straight up, keeping your elbow slightly bent. Lower the dumbbell down towards your shoulder, keeping your elbow close to your body. Press the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1617-SHUMp5H.jpg', '/static/exercises/gifs/1617-SHUMp5H.gif', '© Gym visual — https://gymvisual.com/', '900712'),
('100305', '哑铃下斜耸肩', '肩部', '哑铃', '未分级', '设置一个 45 度角的下斜凳。脸朝下躺在长凳上，胸部和腹部靠在长凳上。每只手握住一个哑铃，双臂完全伸向地板。保持手臂伸直，将肩膀尽可能高地抬向耳朵。保持收缩一会儿，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0305', 'dumbbell decline shrug', 'back', '背部', '20', 'dumbbell', 'shoulders', 'traps', '斜方肌', '["肩部","菱形肌"]', 'Set up a decline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your arms fully extended towards the floor. Keeping your arms straight, raise your shoulders towards your ears as high as possible. Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0305-cwsAI4G.jpg', '/static/exercises/gifs/0305-cwsAI4G.gif', '© Gym visual — https://gymvisual.com/', '560707'),
('100304', '哑铃下斜耸肩版本第二式', '肩部', '哑铃', '未分级', '设置一个 45 度角的下斜凳。脸朝下躺在长凳上，胸部和腹部靠在长凳上。每只手握住一个哑铃，手掌相对，双臂完全伸展。保持手臂伸直，尽可能高地抬高肩膀，同时将肩胛骨挤压在一起。保持收缩短暂停顿，然后将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0304', 'dumbbell decline shrug v. 2', 'back', '背部', '20', 'dumbbell', 'shoulders', 'traps', '斜方肌', '["肩部","菱形肌"]', 'Set up a decline bench at a 45-degree angle. Lie face down on the bench with your chest and stomach resting on it. Hold a dumbbell in each hand with your palms facing each other and your arms fully extended. Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together. Hold the contraction for a brief pause, then lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0304-bRlbdjK.jpg', '/static/exercises/gifs/0304-bRlbdjK.gif', '© Gym visual — https://gymvisual.com/', '560712'),
('100306', '哑铃下斜肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '躺在斜凳上，头低于脚，双手各握一个哑铃，手掌相对。充分伸展双臂，保持肘部靠近头部。将哑铃慢慢降低到脑后，弯曲肘部。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0306', 'dumbbell decline triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other. Extend your arms fully, keeping your elbows close to your head. Lower the dumbbells slowly behind your head, bending your elbows. Pause for a moment, then raise the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0306-OTgkHwR.jpg', '/static/exercises/gifs/0306-OTgkHwR.gif', '© Gym visual — https://gymvisual.com/', '400711'),
('100307', '哑铃下斜转体飞鸟', '肩部', '哑铃', '未分级', '躺在倾斜的长凳上，头部低于臀部。双手各握一个哑铃，手掌相对，双臂伸直越过胸部。将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。当你降低哑铃时，扭转手腕，使手掌在动作底部朝前。反转动作，将哑铃拉回到起始位置，在顶部挤压胸部肌肉。重复所需的重复次数。', 'exercise-dataset', '0307', 'dumbbell decline twist fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Lie down on a decline bench with your head lower than your hips. Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top. Repeat for the desired number of repetitions.', '/static/exercises/images/0307-reFHapa.jpg', '/static/exercises/gifs/0307-reFHapa.gif', '© Gym visual — https://gymvisual.com/', '900712'),
('101437', '哑铃手指弯举', '腕屈肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地上，背部挺直。一只手握住哑铃，反手握住，将前臂放在大腿上，手掌朝上。让哑铃向下滚动到指尖，然后弯曲手指将其卷起。重复所需的重复次数，然后换另一只手。', 'exercise-dataset', '1437', 'dumbbell finger curls', 'lower arms', '前臂', '80', 'dumbbell', 'wrist flexors', 'forearms', '前臂肌群', '["腕屈肌","腕伸肌"]', 'Sit on a bench or chair with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up. Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers. Repeat for the desired number of repetitions, then switch to the other hand.', '/static/exercises/images/1437-mtXengz.jpg', '/static/exercises/gifs/1437-mtXengz.gif', '© Gym visual — https://gymvisual.com/', '900711'),
('100308', '哑铃飞鸟', '肩部', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对。将手臂伸直越过胸部，肘部稍微弯曲。保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后反转动作，将哑铃拉回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0308', 'dumbbell fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, with a slight bend in your elbows. Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0308-yz9nUhF.jpg', '/static/exercises/gifs/0308-yz9nUhF.gif', '© Gym visual — https://gymvisual.com/', '900710'),
('101277', '哑铃飞鸟健身球', '肩部', '哑铃', '未分级', '坐在健身球上，每只手各握一个哑铃。双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。将双臂伸直至胸部上方，手掌相对。稍微弯曲肘部，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后反向运动并挤压胸部肌肉，同时将​​哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1277', 'dumbbell fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball and hold a dumbbell in each hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball. Extend your arms straight up above your chest, palms facing each other. Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1277-Lt3iWnf.jpg', '/static/exercises/gifs/1277-Lt3iWnf.gif', '© Gym visual — https://gymvisual.com/', '900717'),
('101732', '哑铃向前弓步肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。右脚向前迈出一步，将身体降低至弓步位置。保持背部挺直，挺胸。将手臂伸直过头顶，保持肘部靠近耳朵。弯曲肘部，将哑铃降低到脑后。暂停片刻，然后伸直手臂回到起始位置。重复该动作达到所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1732', 'dumbbell forward lunge triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, lowering your body into a lunge position. Keep your back straight and your chest up. Extend your arms straight overhead, keeping your elbows close to your ears. Lower the dumbbells behind your head by bending your elbows. Pause for a moment, then straighten your arms to return to the starting position. Repeat the movement for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1732-XalXcvM.jpg', '/static/exercises/gifs/1732-XalXcvM.gif', '© Gym visual — https://gymvisual.com/', '400718'),
('100310', '哑铃前侧上举', '肱二头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0310', 'dumbbell front raise', 'shoulders', '肩部', '30', 'dumbbell', 'biceps', 'delts', '三角肌', '["肱二头肌","斜方肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0310-3eGE2JC.jpg', '/static/exercises/gifs/0310-3eGE2JC.gif', '© Gym visual — https://gymvisual.com/', '240715'),
('100309', '哑铃前侧上举版本第二式', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。保持背部挺直并启动核心肌群。慢慢举起你面前的哑铃，手臂伸直，直到与肩齐平。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0309', 'dumbbell front raise v. 2', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keep your back straight and engage your core. Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0309-Rr7S3yg.jpg', '/static/exercises/gifs/0309-Rr7S3yg.gif', '© Gym visual — https://gymvisual.com/', '240720'),
('100311', '哑铃全程满杯式侧平举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持背部挺直并启动核心肌群。将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0311', 'dumbbell full can lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","肩袖肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0311-AQ0mC4Y.jpg', '/static/exercises/gifs/0311-AQ0mC4Y.gif', '© Gym visual — https://gymvisual.com/', '160721'),
('101760', '哑铃高脚杯深蹲', '臀肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手握住哑铃垂直放在胸前。保持胸部挺直，核心收紧，通过向后推臀部并弯曲膝盖，将身体降低至蹲姿。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1760', 'dumbbell goblet squat', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1760-yn8yg1r.jpg', '/static/exercises/gifs/1760-yn8yg1r.gif', '© Gym visual — https://gymvisual.com/', '718'),
('100313', '哑铃锤式弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，并旋转手掌，直到手掌朝前。这将是您的起始位置。现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。然后，吸气并慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '0313', 'dumbbell hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', '/static/exercises/images/0313-slDvUAU.jpg', '/static/exercises/gifs/0313-slDvUAU.gif', '© Gym visual — https://gymvisual.com/', '80719'),
('101659', '哑铃锤式弯举健身球', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1659', 'dumbbell hammer curl on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1659-fY68AyX.jpg', '/static/exercises/gifs/1659-fY68AyX.gif', '© Gym visual — https://gymvisual.com/', '80726'),
('100312', '哑铃锤式弯举版本第二式', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，并旋转手掌，直到手掌朝前。这将是您的起始位置。现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。然后，吸气并慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '0312', 'dumbbell hammer curl v. 2', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', '/static/exercises/images/0312-2NpxjC1.jpg', '/static/exercises/gifs/0312-2NpxjC1.gif', '© Gym visual — https://gymvisual.com/', '80725'),
('102402', '哑铃锤式弯举臂弯举托板', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，并旋转手掌，直到手掌朝前。这将是您的起始位置。现在，保持上臂不动，呼气并卷曲哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。然后，吸气并慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '2402', 'dumbbell hammer curls (with arm blaster)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', '/static/exercises/images/2402-GNhAeJ0.jpg', '/static/exercises/gifs/2402-GNhAeJ0.gif', '© Gym visual — https://gymvisual.com/', '80728'),
('101664', '哑铃高位弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝前。保持上臂静止，将哑铃尽可能高地卷起，同时收缩二头肌。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1664', 'dumbbell high curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1664-qAmNMJY.jpg', '/static/exercises/gifs/1664-qAmNMJY.gif', '© Gym visual — https://gymvisual.com/', '80723'),
('103545', '哑铃上斜交替推举', '肩部', '哑铃', '未分级', '坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。向后靠在长凳上，用大腿帮助将哑铃举至肩高，手掌朝前。到达肩膀高度后，旋转手腕，使手掌朝前。用胸部和肩膀将哑铃向上推，充分伸展手臂。将哑铃放回起始位置，保持肘部稍微弯曲。重复所需的重复次数，交替手臂。', 'exercise-dataset', '3545', 'dumbbell incline alternate press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward. Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward. Push the dumbbells up with your chest and shoulders, extending your arms fully. Lower the dumbbells back down to the starting position, keeping your elbows slightly bent. Repeat for the desired number of repetitions, alternating arms.', '/static/exercises/images/3545-TVdivgY.jpg', '/static/exercises/gifs/3545-TVdivgY.gif', '© Gym visual — https://gymvisual.com/', '900726'),
('100314', '哑铃上斜卧推', '肩部', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，双脚平放在地上，背部紧贴长凳。双手各握一个哑铃，掌心向前，将哑铃举至肩高。慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。将哑铃推回起始位置，充分伸展手臂。重复所需的重复次数。', 'exercise-dataset', '0314', 'dumbbell incline bench press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench. Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height. Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0314-ns0SIbU.jpg', '/static/exercises/gifs/0314-ns0SIbU.gif', '© Gym visual — https://gymvisual.com/', '727'),
('100315', '哑铃上斜肱二头肌弯举', '前臂', '哑铃', '未分级', '坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0315', 'dumbbell incline biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0315-F3xgbjF.jpg', '/static/exercises/gifs/0315-F3xgbjF.gif', '© Gym visual — https://gymvisual.com/', '728'),
('100316', '哑铃上斜扩胸式', '肩部', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，背部靠在垫子上，双脚平放在地面上。双手各握一个哑铃，正手握握，手掌朝前。首先，双臂完全伸展，垂直于地面。慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。在底部暂停片刻，然后将哑铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0316', 'dumbbell incline breeding', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing forward. Start with your arms fully extended, perpendicular to the ground. Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle. Pause for a moment at the bottom, then push the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0316-B3Rxp6L.jpg', '/static/exercises/gifs/0316-B3Rxp6L.gif', '© Gym visual — https://gymvisual.com/', '900727'),
('100318', '哑铃上斜弯举', '前臂', '哑铃', '未分级', '将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向前。将上臂放在上斜凳上，让肘部下垂，充分伸展手臂。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0318', 'dumbbell incline curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward. Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0318-ae9UoXQ.jpg', '/static/exercises/gifs/0318-ae9UoXQ.gif', '© Gym visual — https://gymvisual.com/', '80728'),
('100317', '哑铃上斜弯举版本第二式', '前臂', '哑铃', '未分级', '坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0317', 'dumbbell incline curl v. 2', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0317-RaflbWD.jpg', '/static/exercises/gifs/0317-RaflbWD.gif', '© Gym visual — https://gymvisual.com/', '80733'),
('100319', '哑铃上斜飞鸟', '肩部', '哑铃', '未分级', '将上斜凳设置为 45 度角。坐在长凳上，双手各握一个哑铃，手掌相对。仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。重复所需的重复次数。', 'exercise-dataset', '0319', 'dumbbell incline fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Set an incline bench to a 45-degree angle. Sit on the bench with a dumbbell in each hand, palms facing each other. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0319-ESOd5Pl.jpg', '/static/exercises/gifs/0319-ESOd5Pl.gif', '© Gym visual — https://gymvisual.com/', '900730'),
('101278', '哑铃上斜飞鸟健身球', '肩部', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在健身球上，向前滚动，直到上背部靠在倾斜的长凳上。双手各握一个哑铃，手掌相对，双臂伸至胸部上方。将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1278', 'dumbbell incline fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Set up an incline bench at a 45-degree angle. Sit on an exercise ball and roll forward until your upper back is resting on the incline bench. Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1278-HYe1ZqR.jpg', '/static/exercises/gifs/1278-HYe1ZqR.gif', '© Gym visual — https://gymvisual.com/', '900737'),
('100320', '哑铃上斜锤式弯举', '前臂', '哑铃', '未分级', '坐在上斜凳上，每只手各握一个哑铃，手掌朝向躯干，手臂完全伸展。背部靠在长凳上，双脚平放在地板上。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0320', 'dumbbell incline hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended. Keep your back against the bench and your feet flat on the floor. While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0320-ByX0WxV.jpg', '/static/exercises/gifs/0320-ByX0WxV.gif', '© Gym visual — https://gymvisual.com/', '80734'),
('100321', '哑铃上斜锤式推举', '肩部', '哑铃', '未分级', '将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。将哑铃向上推离身体，直到手臂完全伸展。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0321', 'dumbbell incline hammer press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs. Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other. Press the dumbbells up and away from your body until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0321-PG1kcIb.jpg', '/static/exercises/gifs/0321-PG1kcIb.gif', '© Gym visual — https://gymvisual.com/', '900735'),
('101618', '哑铃上斜锤式推举健身球', '胸肌', '哑铃', '未分级', '坐在健身球上，双手各握一个哑铃，手掌相对。双脚向前走，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。将哑铃向上并稍微向内推，保持手掌相对。充分伸展双臂，在动作的最高点挤压三头肌。慢慢地将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1618', 'dumbbell incline hammer press on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other. Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides. Press the dumbbells up and slightly inward, keeping your palms facing each other. Extend your arms fully, squeezing your triceps at the top of the movement. Slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1618-wkgnGfb.jpg', '/static/exercises/gifs/1618-wkgnGfb.gif', '© Gym visual — https://gymvisual.com/', '900742'),
('100322', '哑铃上斜内侧肱二头肌弯举', '前臂', '哑铃', '未分级', '坐在上斜凳上，双手各握一个哑铃，手掌相对。将上臂放在长凳上，让肘部下垂，手掌朝前。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0322', 'dumbbell incline inner biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an incline bench with a dumbbell in each hand, palms facing each other. Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0322-LCtQPn8.jpg', '/static/exercises/gifs/0322-LCtQPn8.gif', '© Gym visual — https://gymvisual.com/', '739'),
('101279', '哑铃上斜单臂飞鸟', '三角肌', '哑铃', '未分级', '将倾斜凳调整至 30-45 度角。坐在长凳上，一只手拿着哑铃，将其放在大腿上。向后躺在长凳上，双脚平放在地面上。握住哑铃，手臂伸直越过胸部。将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1279', 'dumbbell incline one arm fly', 'chest', '胸部', '10', 'dumbbell', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Adjust the incline bench to a 30-45 degree angle. Sit on the bench with a dumbbell in one hand, resting it on your thigh. Lie back on the bench, keeping your feet flat on the ground. Hold the dumbbell with your arm extended straight up over your chest. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow. Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1279-Gw2HFvW.jpg', '/static/exercises/gifs/1279-Gw2HFvW.gif', '© Gym visual — https://gymvisual.com/', '900740'),
('101280', '哑铃上斜单臂飞鸟健身球', '肩部', '哑铃', '未分级', '坐在健身球上，一只手拿着哑铃。双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。握住哑铃，手臂伸直越过胸部，手掌朝内。慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。当手臂与地面平行时暂停片刻。启动胸部肌肉，将哑铃拉回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1280', 'dumbbell incline one arm fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Sit on an exercise ball with a dumbbell in one hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball. Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment when your arm is parallel to the ground. Engage your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1280-LLNh6q5.jpg', '/static/exercises/gifs/1280-LLNh6q5.gif', '© Gym visual — https://gymvisual.com/', '900747'),
('101619', '哑铃上斜单臂锤式推举', '肩部', '哑铃', '未分级', '坐在上斜凳上，一只手拿着哑铃，放在大腿上。向后靠在长凳上，用大腿帮助将哑铃举至肩膀高度。旋转手腕，使手掌朝内，朝向身体。将哑铃向上推离身体，完全伸展手臂。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1619', 'dumbbell incline one arm hammer press', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌"]', 'Sit on an incline bench with a dumbbell in one hand, resting on your thigh. Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height. Rotate your wrist so that your palm is facing inward, towards your body. Press the dumbbell up and away from your body, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1619-LL1UiTX.jpg', '/static/exercises/gifs/1619-LL1UiTX.gif', '© Gym visual — https://gymvisual.com/', '900744'),
('101620', '哑铃上斜单臂锤式推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，一只手拿着哑铃。双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。握住哑铃，手掌朝内，肘部弯曲成 90 度角。将哑铃向上推向天花板，伸直手臂。将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1620', 'dumbbell incline one arm hammer press on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌"]', 'Sit on an exercise ball with a dumbbell in one hand. Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball. Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle. Press the dumbbell up towards the ceiling, straightening your arm. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1620-jDnrkar.jpg', '/static/exercises/gifs/1620-jDnrkar.gif', '© Gym visual — https://gymvisual.com/', '900751'),
('100323', '哑铃上斜单臂侧平举', '斜方肌', '哑铃', '未分级', '坐在上斜凳上，一只手拿着哑铃，将其放在大腿上。身体前倾，将上臂靠在大腿内侧。将哑铃举到一侧，保持手臂稍微弯曲，手掌朝下。继续抬起，直到手臂与地板平行。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0323', 'dumbbell incline one arm lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Sit on an incline bench with a dumbbell in one hand, resting it on your thigh. Lean forward and position your upper arm against the inside of your thigh. Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down. Continue lifting until your arm is parallel to the floor. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0323-aTNKZiC.jpg', '/static/exercises/gifs/0323-aTNKZiC.gif', '© Gym visual — https://gymvisual.com/', '160746'),
('101281', '哑铃上斜单臂推举', '肩部', '哑铃', '未分级', '坐在上斜凳上，一只手拿着哑铃，放在大腿上。仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。将哑铃向上并稍微向内推，充分伸展手臂。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1281', 'dumbbell incline one arm press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an incline bench with a dumbbell in one hand, resting on your thigh. Lie back on the bench and position the dumbbell at shoulder level, palm facing forward. Press the dumbbell upward and slightly inward, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1281-rDAiRf9.jpg', '/static/exercises/gifs/1281-rDAiRf9.gif', '© Gym visual — https://gymvisual.com/', '900745'),
('101282', '哑铃上斜单臂推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，一只手拿着哑铃，双脚平放在地上。慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。将哑铃握在与肩同高的位置，手掌朝前。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1282', 'dumbbell incline one arm press on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground. Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbell at shoulder height with your palm facing forward. Press the dumbbell upward until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1282-Bg5JKSH.jpg', '/static/exercises/gifs/1282-Bg5JKSH.gif', '© Gym visual — https://gymvisual.com/', '900752'),
('100324', '哑铃上斜掌心推举', '肩部', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，双手各握一个哑铃，手掌相对。将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。从与肩同高的哑铃开始，肘部弯曲，手掌相对。将哑铃向上推离身体，充分伸展手臂。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0324', 'dumbbell incline palm-in press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with a dumbbell in each hand, palms facing each other. Plant your feet firmly on the ground and keep your back straight against the bench. Start with the dumbbells at shoulder level, elbows bent and palms facing each other. Press the dumbbells up and away from your body, extending your arms fully. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0324-OVLmUuL.jpg', '/static/exercises/gifs/0324-OVLmUuL.gif', '© Gym visual — https://gymvisual.com/', '900745'),
('101283', '哑铃上斜推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，每只手各握一个哑铃，手掌朝前。双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。向上推哑铃，充分伸展手臂。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1283', 'dumbbell incline press on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with a dumbbell in each hand, palms facing forward. Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball. Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides. Press the dumbbells upward, extending your arms fully. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1283-bfiHMpI.jpg', '/static/exercises/gifs/1283-bfiHMpI.gif', '© Gym visual — https://gymvisual.com/', '900750'),
('100325', '哑铃上斜上举', '斜方肌', '哑铃', '未分级', '坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。向后靠在长凳上，将哑铃举至肩高，手掌朝前。背部靠在长凳上，呼气并将哑铃举过头顶，充分伸展双臂。在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。重复所需的重复次数。', 'exercise-dataset', '0325', 'dumbbell incline raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward. Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0325-nxW6BkN.jpg', '/static/exercises/gifs/0325-nxW6BkN.gif', '© Gym visual — https://gymvisual.com/', '900745'),
('100326', '哑铃上斜后侧侧平举', '斜方肌', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，胸部靠在靠背上，双手各握一个哑铃。双臂伸直向下，手掌相对。保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0326', 'dumbbell incline rear lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and hold a dumbbell in each hand. Extend your arms straight down with your palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0326-vYk8lqw.jpg', '/static/exercises/gifs/0326-vYk8lqw.gif', '© Gym visual — https://gymvisual.com/', '160750'),
('100327', '哑铃上斜划船', '肱二头肌', '哑铃', '未分级', '设置一个 45 度角的上斜凳。双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。充分伸展双臂，让哑铃从肩膀上垂直垂下。将哑铃拉向胸部，将肩胛骨挤压在一起。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0327', 'dumbbell incline row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Grab a dumbbell in each hand and sit on the bench with your chest against the incline. Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0327-7vG5o25.jpg', '/static/exercises/gifs/0327-7vG5o25.gif', '© Gym visual — https://gymvisual.com/', '900747'),
('100328', '哑铃上斜肩部上举', '三角肌', '哑铃', '未分级', '将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心朝下。将哑铃放在大腿上，然后靠在长凳上。用大腿帮助将哑铃举至肩膀高度，然后旋转手腕，使手掌朝前。呼气，慢慢将哑铃举过头顶，保持肘部轻微弯曲。在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。重复所需的重复次数。', 'exercise-dataset', '0328', 'dumbbell incline shoulder raise', 'chest', '胸部', '10', 'dumbbell', 'deltoids', 'serratus anterior', '前锯肌', '["三角肌","斜方肌"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down. Rest the dumbbells on your thighs and lean back onto the bench. Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward. Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows. Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0328-6e2DcYX.jpg', '/static/exercises/gifs/0328-6e2DcYX.gif', '© Gym visual — https://gymvisual.com/', '900750'),
('100329', '哑铃上斜耸肩', '肩部', '哑铃', '未分级', '将上斜凳设置为 45 度角，坐在上面，双手各握一个哑铃。将双脚平放在地面上，让双臂笔直下垂，手掌朝向身体。保持手臂伸直，耸肩，尽可能高地靠近耳朵。保持收缩一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0329', 'dumbbell incline shrug', 'back', '背部', '20', 'dumbbell', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand. Place your feet flat on the ground and let your arms hang straight down with your palms facing your body. Keeping your arms straight, shrug your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0329-JymLInS.jpg', '/static/exercises/gifs/0329-JymLInS.gif', '© Gym visual — https://gymvisual.com/', '560749'),
('103542', '哑铃上斜T字上举', '斜方肌', '哑铃', '未分级', '将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。向前倾斜，让手臂笔直向下垂，垂直于地板。保持手臂伸直，将它们向两侧举起，直到与地板平行，与身体形成“T”形。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3542', 'dumbbell incline t-raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards. Lean forward and let your arms hang straight down, perpendicular to the floor. Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3542-jgbvVJ0.jpg', '/static/exercises/gifs/3542-jgbvVJ0.gif', '© Gym visual — https://gymvisual.com/', '900750'),
('100330', '哑铃上斜肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '坐在上斜凳上，双手各握一个哑铃，掌心向内。将手臂完全伸过头顶，保持肘部靠近头部。弯曲肘部，将哑铃降低到头后，保持上臂静止。暂停片刻，然后伸展双臂将哑铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0330', 'dumbbell incline triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on an incline bench with a dumbbell in each hand, palms facing inwards. Extend your arms fully overhead, keeping your elbows close to your head. Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary. Pause for a moment, then raise the dumbbells back to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0330-OVIKwsd.jpg', '/static/exercises/gifs/0330-OVIKwsd.gif', '© Gym visual — https://gymvisual.com/', '400753'),
('100331', '哑铃上斜扭转飞鸟', '肩部', '哑铃', '未分级', '将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心相对。仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方，双臂伸展。将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。放下哑铃时，旋转手腕，使手掌在动作底部朝前。反转动作，将哑铃拉回起始位置，在顶部将胸部肌肉挤压在一起。重复所需的重复次数。', 'exercise-dataset', '0331', 'dumbbell incline twisted flyes', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other. Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended. Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement. Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top. Repeat for the desired number of repetitions.', '/static/exercises/images/0331-1PLE8e9.jpg', '/static/exercises/gifs/0331-1PLE8e9.gif', '© Gym visual — https://gymvisual.com/', '900754'),
('101733', '哑铃上斜双臂伸展', '肩部', '哑铃', '未分级', '坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。慢慢地躺在长凳上，保持哑铃靠近胸部。完全躺下后，将手臂伸向天花板，保持肘部稍微弯曲。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1733', 'dumbbell incline two arm extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs. Slowly lie back on the bench, keeping the dumbbells close to your chest. Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1733-U7D9Fx3.jpg', '/static/exercises/gifs/1733-U7D9Fx3.gif', '© Gym visual — https://gymvisual.com/', '900757'),
('103541', '哑铃上斜Y字上举', '肩部', '哑铃', '未分级', '将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向内。稍微向前倾，让手臂伸直垂下，肘部保持轻微弯曲。将手臂向两侧抬起并呈 Y 形，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3541', 'dumbbell incline y-raise', 'back', '背部', '20', 'dumbbell', 'shoulders', 'upper back', '上背部', '["肩部","后侧DELTOIDS"]', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards. Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows. Raise your arms out to the sides and up in a Y shape until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3541-PbzNu7c.jpg', '/static/exercises/gifs/3541-PbzNu7c.gif', '© Gym visual — https://gymvisual.com/', '900754'),
('100332', '哑铃铁板交叉', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。将双臂向两侧举起，直至与地面平行，与身体形成T字形。暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0332', 'dumbbell iron cross', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body. Pause for a moment, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0332-cALkHHX.jpg', '/static/exercises/gifs/0332-cALkHHX.gif', '© Gym visual — https://gymvisual.com/', '900755'),
('100333', '哑铃后踢', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将上臂靠近身体两侧，肘部弯曲成 90 度角。将手臂向后伸直，在动作的最高点挤压三头肌。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0333', 'dumbbell kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0333-W6PxUkg.jpg', '/static/exercises/gifs/0333-W6PxUkg.gif', '© Gym visual — https://gymvisual.com/', '560754'),
('101734', '哑铃后踢健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。双手各握一个哑铃，掌心向内，手臂弯曲成 90 度角。将手臂向后伸直，在动作的最高点挤压三头肌。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1734', 'dumbbell kickbacks on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1734-cAvTaSg.jpg', '/static/exercises/gifs/1734-cAvTaSg.gif', '© Gym visual — https://gymvisual.com/', '560761'),
('101660', '哑铃跪姿肱二头肌弯举健身球', '前臂', '哑铃', '未分级', '跪在地板上，面前放一个健身球。将肘部放在健身球上，双手各握一个哑铃，手掌朝上。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1660', 'dumbbell kneeling bicep curl exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Kneel on the floor with an exercise ball in front of you. Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1660-2JCuFTU.jpg', '/static/exercises/gifs/1660-2JCuFTU.gif', '© Gym visual — https://gymvisual.com/', '80764'),
('100334', '哑铃侧平举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持背部挺直并启动核心肌群。将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0334', 'dumbbell lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0334-DsgkuIt.jpg', '/static/exercises/gifs/0334-DsgkuIt.gif', '© Gym visual — https://gymvisual.com/', '160759'),
('100335', '哑铃侧向前侧上举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持背部挺直并启动核心肌群。将手臂向两侧举起，直到与地面平行，保持肘部稍微弯曲。在顶部暂停片刻，然后慢慢将手臂放回起始位置。接下来，将手臂举到身前，直到它们与地面平行，再次保持肘部稍微弯曲。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0335', 'dumbbell lateral to front raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0335-xMjBKwn.jpg', '/static/exercises/gifs/0335-xMjBKwn.gif', '© Gym visual — https://gymvisual.com/', '240764'),
('100336', '哑铃弓步', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。右脚向前迈出一步，将身体降低至弓步位置。降低身体时保持背部挺直、挺胸。推动右脚跟回到起始位置。左腿重复上述动作。交替腿进行所需的重复次数。', 'exercise-dataset', '0336', 'dumbbell lunge', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with your right foot, lowering your body into a lunge position. Keep your back straight and your chest up as you lower your body. Push through your right heel to return to the starting position. Repeat with your left leg. Alternate legs for the desired number of repetitions.', '/static/exercises/images/0336-RRWFUcw.jpg', '/static/exercises/gifs/0336-RRWFUcw.gif', '© Gym visual — https://gymvisual.com/', '320759'),
('101658', '哑铃弓步肱二头肌弯举', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。右脚向前迈出一步，将身体降低至弓步位置。你的右膝应该弯曲成 90 度角，左膝应该悬停在地面上方。当你向前弓步时，同时将哑铃向肩膀弯曲，保持肘部靠近身体。在弓步底部停顿片刻，然后通过右脚跟推动回到起始位置，将哑铃放回身体两侧。在另一侧重复弓步和二头肌弯举，左脚向前迈出。继续交替进行所需的重复次数。', 'exercise-dataset', '1658', 'dumbbell lunge with bicep curl', 'upper arms', '上臂', '50', 'dumbbell', 'quadriceps', 'biceps', '肱二头肌', '["股四头肌","腘绳肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground. As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body. Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides. Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1658-Mz6lLcW.jpg', '/static/exercises/gifs/1658-Mz6lLcW.gif', '© Gym visual — https://gymvisual.com/', '80766'),
('100337', '哑铃仰卧伸展横向面部', '肩部', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。双手握住哑铃，双臂伸直至胸部上方，手掌相对。保持上臂静止，将哑铃在头后呈弧形缓慢降低，直到前臂与地面平行。暂停片刻，然后收缩三头肌，将哑铃带回起始位置。重复所需的重复次数。', 'exercise-dataset', '0337', 'dumbbell lying extension (across face)', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other. Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground. Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0337-L2V5Nan.jpg', '/static/exercises/gifs/0337-L2V5Nan.gif', '© Gym visual — https://gymvisual.com/', '900767'),
('101729', '哑铃仰卧交替伸展', '肩部', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对。将手臂伸直越过胸部，保持肘部轻微弯曲。将一个哑铃朝头部方向放下，肘部弯曲，同时保持另一只手臂伸展。在底部停顿片刻，然后将哑铃举回到起始位置。用另一只手臂重复上述动作，交替进行所需的重复次数。', 'exercise-dataset', '1729', 'dumbbell lying alternate extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended. Pause for a moment at the bottom, then raise the dumbbell back up to the starting position. Repeat with the other arm, alternating sides for the desired number of repetitions.', '/static/exercises/images/1729-NfP83rA.jpg', '/static/exercises/gifs/1729-NfP83rA.gif', '© Gym visual — https://gymvisual.com/', '900766'),
('100338', '哑铃仰卧肘推举', '胸肌', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0338', 'dumbbell lying elbow press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest. Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary. Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows. Repeat for the desired number of repetitions.', '/static/exercises/images/0338-eOCOwIR.jpg', '/static/exercises/gifs/0338-eOCOwIR.gif', '© Gym visual — https://gymvisual.com/', '900767'),
('100863', '哑铃仰卧外旋肩部旋转', '肩袖肌群', '哑铃', '未分级', '侧躺在平坦的长凳上，上臂靠在身体两侧，肘部弯曲 90 度。手中握住哑铃，手掌朝下。保持上臂靠在身体两侧，尽可能缓慢地向上旋转前臂。在顶部暂停片刻，然后慢慢将前臂放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0863', 'dumbbell lying external shoulder rotation', 'shoulders', '肩部', '30', 'dumbbell', 'rotator cuff', 'delts', '三角肌', '["肩袖肌群","肱三头肌"]', 'Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees. Hold a dumbbell in your hand with your palm facing down. Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible. Pause for a moment at the top, then slowly lower your forearm back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0863-bmBf7LN.jpg', '/static/exercises/gifs/0863-bmBf7LN.gif', '© Gym visual — https://gymvisual.com/', '900770'),
('100339', '哑铃仰卧股部', '臀肌', '哑铃', '未分级', '平躺，双腿伸直，将哑铃放在下腹部。弯曲膝盖，将哑铃拉向臀部，保持双脚平放在地面上。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0339', 'dumbbell lying femoral', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen. Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0339-FkBIE6a.jpg', '/static/exercises/gifs/0339-FkBIE6a.gif', '© Gym visual — https://gymvisual.com/', '900767'),
('100340', '哑铃仰卧锤式推举', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。将哑铃放低至胸部两侧，保持肘部呈 90 度角。将哑铃推回到起始位置，充分伸展手臂。重复所需的重复次数。', 'exercise-dataset', '0340', 'dumbbell lying hammer press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up. Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle. Press the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0340-7gdLIXa.jpg', '/static/exercises/gifs/0340-7gdLIXa.gif', '© Gym visual — https://gymvisual.com/', '900770'),
('102470', '哑铃仰卧地板三角肌后束上举', '斜方肌', '哑铃', '未分级', '脸朝下躺在地板上，双手各握一个哑铃，手掌相对。将手臂伸直在身前，保持肘部轻微弯曲。调动肩部肌肉，将手臂向上并向两侧抬起，将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2470', 'dumbbell lying on floor rear delt raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Lie face down on the floor with a dumbbell in each hand, palms facing each other. Extend your arms straight out in front of you, keeping a slight bend in your elbows. Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2470-Ion0XWz.jpg', '/static/exercises/gifs/2470-Ion0XWz.gif', '© Gym visual — https://gymvisual.com/', '400777'),
('100341', '哑铃仰卧单臂三角肌后侧', '斜方肌', '哑铃', '未分级', '脸朝下躺在平坦的长凳上，一只手握住哑铃，手掌朝内。将手臂笔直向下伸向地板，保持靠近身体。向上和向后举起手臂，将肩胛骨挤压向脊柱。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0341', 'dumbbell lying one arm deltoid rear', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards. Extend your arm straight down towards the floor, keeping it close to your body. Raise your arm up and back, squeezing your shoulder blade towards your spine. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0341-gSw59a4.jpg', '/static/exercises/gifs/0341-gSw59a4.gif', '© Gym visual — https://gymvisual.com/', '900776'),
('100343', '哑铃仰卧单臂推举', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，一只手拿着哑铃，双脚平放在地上。将哑铃举至肩部水平，手掌朝前。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0343', 'dumbbell lying one arm press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground. Hold the dumbbell at shoulder level with your palm facing forward. Press the dumbbell upward until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0343-zGSIWQi.jpg', '/static/exercises/gifs/0343-zGSIWQi.gif', '© Gym visual — https://gymvisual.com/', '900775'),
('100342', '哑铃仰卧单臂推举版本第二式', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，背部支撑，双脚平放在地面上。一只手握住哑铃，手掌朝向脚部。将手臂伸向天花板，保持肘部稍微弯曲。慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。在底部暂停片刻，然后将哑铃推回到起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0342', 'dumbbell lying one arm press v. 2', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your back supported and feet flat on the ground. Hold a dumbbell in one hand with your palm facing towards your feet. Extend your arm straight up towards the ceiling, keeping your elbow slightly bent. Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body. Pause for a moment at the bottom, then push the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0342-K3dIO25.jpg', '/static/exercises/gifs/0342-K3dIO25.gif', '© Gym visual — https://gymvisual.com/', '900780'),
('100344', '哑铃仰卧单臂正握肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。一只手握住哑铃，手掌朝下，将手臂伸直至肩膀上方。保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0344', 'dumbbell lying one arm pronated triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0344-wyaqzOS.jpg', '/static/exercises/gifs/0344-wyaqzOS.gif', '© Gym visual — https://gymvisual.com/', '400781'),
('100345', '哑铃仰卧单臂后侧侧平举', '斜方肌', '哑铃', '未分级', '脸朝下躺在平坦的长凳上，一只手拿着哑铃，垂向地板。保持手臂伸直，将哑铃举到一侧，远离身体。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0345', 'dumbbell lying one arm rear lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor. Keep your arm straight and lift the dumbbell out to the side, away from your body. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0345-KwFGiEP.jpg', '/static/exercises/gifs/0345-KwFGiEP.gif', '© Gym visual — https://gymvisual.com/', '160782'),
('100346', '哑铃仰卧单臂反握肱三头肌臂屈伸', '前臂', '哑铃', '未分级', '平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。一只手握住哑铃，反握，将手臂伸直至肩膀上方。保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。在底部停顿片刻，然后将手臂伸回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0346', 'dumbbell lying one arm supinated triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder. Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow. Pause for a moment at the bottom, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0346-zZlORz6.jpg', '/static/exercises/gifs/0346-zZlORz6.gif', '© Gym visual — https://gymvisual.com/', '400783'),
('100347', '哑铃仰卧前臂旋前', '肱二头肌', '哑铃', '未分级', '平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。旋转手掌，使手掌朝上。保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。吸气并慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0347', 'dumbbell lying pronation', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand. Rotate your palms so they are facing up. Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down. Inhale and slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0347-mym4hJo.jpg', '/static/exercises/gifs/0347-mym4hJo.gif', '© Gym visual — https://gymvisual.com/', '240776'),
('102705', '哑铃仰卧前臂旋前地板', '肱二头肌', '哑铃', '未分级', '平躺在地板上，脸朝下，双臂伸直在身前，每只手各握一个哑铃。旋转手掌，使其朝下朝向地板。保持手臂伸直，收缩前臂将哑铃提离地板。继续举起，直到前臂完全收缩并且哑铃与肩部齐平。保持一会儿，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2705', 'dumbbell lying pronation on floor', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand. Rotate your palms so they are facing down towards the floor. Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms. Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level. Hold for a moment, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2705-7RWNjiB.jpg', '/static/exercises/gifs/2705-7RWNjiB.gif', '© Gym visual — https://gymvisual.com/', '240781'),
('101284', '哑铃仰卧上拉健身球', '肱三头肌', '哑铃', '未分级', '坐在健身球上，向前滚动，直到上背部靠在球上。双手握住哑铃，将手臂伸直至胸部上方。慢慢地将哑铃放到脑后，同时保持手臂伸直。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1284', 'dumbbell lying pullover on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","后侧"]', 'Sit on an exercise ball and roll forward until your upper back is resting on the ball. Hold a dumbbell with both hands and extend your arms straight up over your chest. Slowly lower the dumbbell behind your head while keeping your arms straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1284-iK59oEA.jpg', '/static/exercises/gifs/1284-iK59oEA.gif', '© Gym visual — https://gymvisual.com/', '400784'),
('101328', '哑铃仰卧三角肌后束划船', '肩部', '哑铃', '未分级', '脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。将手臂伸直向下伸向地板，肘部保持轻微弯曲。调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1328', 'dumbbell lying rear delt row', 'back', '背部', '20', 'dumbbell', 'shoulders', 'upper back', '上背部', '["肩部","肱二头肌"]', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards. Extend your arms straight down towards the floor, keeping a slight bend in your elbows. Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1328-XUUD0Fs.jpg', '/static/exercises/gifs/1328-XUUD0Fs.gif', '© Gym visual — https://gymvisual.com/', '900783'),
('100348', '哑铃仰卧后侧侧平举', '斜方肌', '哑铃', '未分级', '脸朝下躺在平坦的长凳上，双手各握一个哑铃，手掌相对。将手臂伸直向下伸向地板，肘部保持轻微弯曲。调动肩部肌肉，将手臂向两侧抬起，直到与地板平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0348', 'dumbbell lying rear lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing each other. Extend your arms straight down towards the floor, keeping a slight bend in your elbows. Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0348-53Ttlck.jpg', '/static/exercises/gifs/0348-53Ttlck.gif', '© Gym visual — https://gymvisual.com/', '160784'),
('101735', '哑铃仰卧单侧伸展', '肩部', '哑铃', '未分级', '平躺在长凳上，一只手拿着哑铃，手臂完全伸展到胸部上方。以受控的方式将哑铃降低到前额，保持上臂静止。在动作底部短暂暂停，然后将手臂伸展回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1735', 'dumbbell lying single extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest. Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary. Pause briefly at the bottom of the movement, then extend your arm back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1735-6MfS53i.jpg', '/static/exercises/gifs/1735-6MfS53i.gif', '© Gym visual — https://gymvisual.com/', '900783'),
('100349', '哑铃仰卧前臂旋后', '肱二头肌', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上。每只手握住一个哑铃，手掌朝上，双臂完全伸展。保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0349', 'dumbbell lying supination', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0349-M2Pm3zj.jpg', '/static/exercises/gifs/0349-M2Pm3zj.gif', '© Gym visual — https://gymvisual.com/', '320782'),
('102706', '哑铃仰卧前臂旋后地板', '肱二头肌', '哑铃', '未分级', '仰卧在地板上，双腿伸直，双臂放在身体两侧，每只手各握一个哑铃。将手掌旋转至向上，保持肘部靠近身体两侧。慢慢地将哑铃向肩膀弯曲，挤压前臂。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2706', 'dumbbell lying supination on floor', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand. Rotate your palms to face up, keeping your elbows close to your sides. Slowly curl the dumbbells towards your shoulders, squeezing your forearms. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2706-rEhi2o5.jpg', '/static/exercises/gifs/2706-rEhi2o5.gif', '© Gym visual — https://gymvisual.com/', '320787'),
('101661', '哑铃仰卧仰卧肱二头肌弯举', '前臂', '哑铃', '未分级', '平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。每只手握住一个哑铃，手掌朝上，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1661', 'dumbbell lying supine biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1661-XVzF3iZ.jpg', '/static/exercises/gifs/1661-XVzF3iZ.gif', '© Gym visual — https://gymvisual.com/', '788'),
('100350', '哑铃仰卧仰卧弯举', '前臂', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0350', 'dumbbell lying supine curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0350-KUaZst7.jpg', '/static/exercises/gifs/0350-KUaZst7.gif', '© Gym visual — https://gymvisual.com/', '80787'),
('100351', '哑铃仰卧肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对。将手臂伸直越过胸部，保持肘部靠近身体。将哑铃向前额方向降低，弯曲肘部。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0351', 'dumbbell lying triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, keeping your elbows close to your body. Lower the dumbbells down towards your forehead, bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0351-mpKZGWz.jpg', '/static/exercises/gifs/0351-mpKZGWz.gif', '© Gym visual — https://gymvisual.com/', '400788'),
('101662', '哑铃仰卧宽距弯举', '前臂', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1662', 'dumbbell lying wide curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1662-qm9veZw.jpg', '/static/exercises/gifs/1662-qm9veZw.gif', '© Gym visual — https://gymvisual.com/', '80789'),
('100352', '哑铃中立握握卧推', '胸肌', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。慢慢地将哑铃降低到胸部，保持肘部靠近身体。在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。重复所需的重复次数。', 'exercise-dataset', '0352', 'dumbbell neutral grip bench press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest. Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body. Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0352-pP8wP2P.jpg', '/static/exercises/gifs/0352-pP8wP2P.gif', '© Gym visual — https://gymvisual.com/', '900792'),
('101285', '哑铃单臂训练凳飞鸟', '肩部', '哑铃', '未分级', '坐在平坦的长凳上，一只手拿着哑铃，将其放在大腿上方。向后躺在长凳上，将哑铃压在大腿上。用空着的那只手帮助将哑铃举至起始位置。将哑铃握在肩膀正上方，手臂伸展，手掌朝内。将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。当手臂与地面平行时暂停，然后反向运动并将哑铃带回起始位置。重复所需的重复次数，然后换臂重复。', 'exercise-dataset', '1285', 'dumbbell one arm bench fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh. Lie back on the bench, keeping the dumbbell pressed against your thigh. Using your free hand, help lift the dumbbell up to the starting position. Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward. Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow. Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', '/static/exercises/images/1285-o5Jsk92.jpg', '/static/exercises/gifs/1285-o5Jsk92.gif', '© Gym visual — https://gymvisual.com/', '900793'),
('100292', '哑铃单臂俯身划船', '肱二头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。让哑铃垂直垂向地板，手臂完全伸展。将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0292', 'dumbbell one arm bent-over row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. Let the dumbbell hang straight down towards the floor, with your arm fully extended. Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0292-C0MA9bC.jpg', '/static/exercises/gifs/0292-C0MA9bC.gif', '© Gym visual — https://gymvisual.com/', '900794'),
('101286', '哑铃单臂夹胸飞鸟健身球', '肩部', '哑铃', '未分级', '坐在健身球上，一只手拿着哑铃，双脚平放在地上。双脚向前走，滚动球，直到你的上背部受到球的支撑，并且你的头、脖子和肩膀离开球。将手臂伸直，将哑铃举至胸部上方，手掌朝内。慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。当手臂与地面平行时暂停片刻。启动胸部肌肉，将哑铃拉回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1286', 'dumbbell one arm chest fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground. Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball. Extend your arm with the dumbbell straight up above your chest, palm facing inward. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment when your arm is parallel to the ground. Engage your chest muscles to bring the dumbbell back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1286-Bpkf41o.jpg', '/static/exercises/gifs/1286-Bpkf41o.gif', '© Gym visual — https://gymvisual.com/', '240801'),
('100353', '哑铃单臂集中弯举瑞士球', '前臂', '哑铃', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。一只手握住哑铃，手掌朝上，手臂向下伸向地板。将肘部放在大腿内侧、膝盖上方。保持上臂静止，呼气并将哑铃向上弯向肩膀，同时收缩二头肌。在动作的最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂重复。', 'exercise-dataset', '0353', 'dumbbell one arm concentration curl (on stability ball)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor. Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps. Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', '/static/exercises/images/0353-k5IpyHg.jpg', '/static/exercises/gifs/0353-k5IpyHg.gif', '© Gym visual — https://gymvisual.com/', '80802'),
('101287', '哑铃单臂下斜胸推', '肱三头肌', '哑铃', '未分级', '躺在下斜长凳上，一只手握住哑铃，放在胸前。将双脚平放在地面上，并将背部压在长凳上。伸展手臂，将哑铃推向天花板，充分伸展肘部。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1287', 'dumbbell one arm decline chest press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie on a decline bench with a dumbbell in one hand, resting on your chest. Place your feet flat on the ground and keep your back pressed against the bench. Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1287-REGM1dE.jpg', '/static/exercises/gifs/1287-REGM1dE.gif', '© Gym visual — https://gymvisual.com/', '160799'),
('101288', '哑铃单臂飞鸟健身球', '肩部', '哑铃', '未分级', '坐在健身球上，一只手拿着哑铃，双脚平放在地上。双脚向前走，身体向下滚动，直到上背部靠在健身球上。将手臂伸直，将哑铃举至胸部上方，手掌朝内。慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1288', 'dumbbell one arm fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground. Walk your feet forward and roll your body down until your upper back is resting on the exercise ball. Extend your arm with the dumbbell straight up above your chest, palm facing inwards. Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow. Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1288-Am02iPd.jpg', '/static/exercises/gifs/1288-Am02iPd.gif', '© Gym visual — https://gymvisual.com/', '900802'),
('101736', '哑铃单臂法式推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住哑铃，手掌朝上，肘部弯曲成 90 度角。将手臂伸向天花板，保持肘部不动。慢慢地将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1736', 'dumbbell one arm french press on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle. Extend your arm straight up towards the ceiling, keeping your elbow stationary. Slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1736-ziFKQXP.jpg', '/static/exercises/gifs/1736-ziFKQXP.gif', '© Gym visual — https://gymvisual.com/', '900805'),
('101663', '哑铃单臂锤式牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，一只手拿着哑铃，上臂放在垫子上。以中立握法握住哑铃（手掌朝向身体）。保持上臂静止，呼气并将哑铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1663', 'dumbbell one arm hammer preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad. Hold the dumbbell with a neutral grip (palms facing your body). Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1663-4dF3maG.jpg', '/static/exercises/gifs/1663-4dF3maG.gif', '© Gym visual — https://gymvisual.com/', '80802'),
('101621', '哑铃单臂锤式推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住哑铃，掌心向内，肘部弯曲成 90 度角。将另一只手放在臀部上以保持稳定。向上推哑铃，充分伸展手臂。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1621', 'dumbbell one arm hammer press on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle. Place your other hand on your hip for stability. Press the dumbbell upwards, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1621-VYmYxK5.jpg', '/static/exercises/gifs/1621-VYmYxK5.gif', '© Gym visual — https://gymvisual.com/', '900807'),
('101289', '哑铃单臂上斜胸推', '肩部', '哑铃', '未分级', '将上斜凳调整至 45 度角。坐在长凳上，背部靠在垫子上，双脚平放在地面上。一只手握住哑铃，正手握住，将其放在肩膀上。将哑铃向上推离身体，完全伸展手臂。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1289', 'dumbbell one arm incline chest press', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the incline bench to a 45-degree angle. Sit on the bench with your back against the pad and feet flat on the ground. Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder. Push the dumbbell up and away from your body, extending your arm fully. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1289-PDaMuyV.jpg', '/static/exercises/gifs/1289-PDaMuyV.gif', '© Gym visual — https://gymvisual.com/', '160804'),
('100354', '哑铃单臂后踢', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，右手握住哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将右肘举至身体一侧，保持弯曲 90 度角。将右臂向后伸直，在动作的最高点挤压三头肌。慢慢地将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0354', 'dumbbell one arm kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your right elbow up to your side, keeping it bent at a 90-degree angle. Extend your right arm straight back, squeezing your triceps at the top of the movement. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0354-bQy2Eni.jpg', '/static/exercises/gifs/0354-bQy2Eni.gif', '© Gym visual — https://gymvisual.com/', '560801'),
('100355', '哑铃单臂侧平举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。在整个练习过程中保持背部挺直，核心肌群参与其中。将哑铃举至一侧，保持手臂伸直，手掌朝下。继续抬起，直到手臂与地面平行。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0355', 'dumbbell one arm lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body. Keep your back straight and your core engaged throughout the exercise. Raise the dumbbell to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0355-n5cWCsI.jpg', '/static/exercises/gifs/0355-n5cWCsI.gif', '© Gym visual — https://gymvisual.com/', '160804'),
('100356', '哑铃单臂侧平举支撑', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。将另一只手放在稳定的表面（例如长凳或墙壁）上以获得支撑。保持背部挺直并启动核心肌群。将哑铃向一侧举起，保持手臂伸直，手掌朝下。继续抬起，直到手臂与地面平行。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0356', 'dumbbell one arm lateral raise with support', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肩袖肌群"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body. Place your other hand on a stable surface, such as a bench or wall, for support. Keep your back straight and engage your core. Raise the dumbbell out to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0356-Yg7MJAT.jpg', '/static/exercises/gifs/0356-Yg7MJAT.gif', '© Gym visual — https://gymvisual.com/', '160809'),
('101290', '哑铃单臂推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。一只手握住哑铃，将其置于与肩同高的位置，肘部弯曲，手掌朝前。慢慢向上推哑铃，直到手臂完全伸展，同时保持核心收紧并在健身球上保持平衡。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1290', 'dumbbell one arm press on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌","核心肌群"]', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward. Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1290-QZFv5ui.jpg', '/static/exercises/gifs/1290-QZFv5ui.gif', '© Gym visual — https://gymvisual.com/', '900810'),
('101665', '哑铃单臂俯卧弯举', '前臂', '哑铃', '未分级', '脸朝下躺在平坦的长凳上，一只手握住哑铃，掌心朝下。完全伸展你的手臂，让它垂直垂向地板。保持上臂静止，通过收缩二头肌将哑铃向上卷曲至肩膀。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1665', 'dumbbell one arm prone curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing down. Extend your arm fully, letting it hang straight down towards the floor. Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1665-JWjujiY.jpg', '/static/exercises/gifs/1665-JWjujiY.gif', '© Gym visual — https://gymvisual.com/', '80807'),
('101666', '哑铃单臂俯卧锤式弯举', '前臂', '哑铃', '未分级', '面朝下躺在平坦的长凳上，一只手拿着哑铃，手掌面向身体，手臂完全伸展。保持上臂静止，将哑铃向肩膀弯曲，收缩二头肌。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1666', 'dumbbell one arm prone hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended. Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1666-LIGZSTA.jpg', '/static/exercises/gifs/1666-LIGZSTA.gif', '© Gym visual — https://gymvisual.com/', '80810'),
('101291', '哑铃单臂上拉健身球', '肱三头肌', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。用一只手握住哑铃，将手臂伸直至胸部上方。慢慢地将哑铃放到脑后，同时保持手臂伸直。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1291', 'dumbbell one arm pullover on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","背阔肌","菱形肌"]', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell with one hand and extend your arm straight up above your chest. Slowly lower the dumbbell behind your head while keeping your arm straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1291-bQHPBU3.jpg', '/static/exercises/gifs/1291-bQHPBU3.gif', '© Gym visual — https://gymvisual.com/', '400813'),
('100358', '哑铃单臂反向腕弯举', '腕伸肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上。一只手握住哑铃，正手握住，手掌朝下。将前臂放在大腿上，手腕悬在边缘。弯曲手腕，慢慢地将哑铃降低到地面。在底部停顿片刻，然后慢慢地将手腕向上卷向身体。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0358', 'dumbbell one arm reverse wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'wrist extensors', 'forearms', '前臂肌群', '["腕伸肌"]', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an overhand grip, palm facing down. Rest your forearm on your thigh, with your wrist hanging off the edge. Slowly lower the dumbbell towards the ground by flexing your wrist. Pause for a moment at the bottom, then slowly curl your wrist back up towards your body. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0358-BwSNDGt.jpg', '/static/exercises/gifs/0358-BwSNDGt.gif', '© Gym visual — https://gymvisual.com/', '812'),
('100359', '哑铃单臂反向飞鸟支撑', '斜方肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，背部挺直。一只手握住哑铃，手掌朝内。身体前倾，将空着的手放在长凳上以获得支撑。保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0359', 'dumbbell one arm reverse fly (with support)', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Sit on a bench with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing inwards. Lean forward and place your free hand on the bench for support. Keep your arm slightly bent and raise it out to the side until it is parallel to the ground. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0359-e25F58f.jpg', '/static/exercises/gifs/0359-e25F58f.gif', '© Gym visual — https://gymvisual.com/', '320815'),
('101622', '哑铃单臂反向握推举', '肱三头肌', '哑铃', '未分级', '坐在平坦的长凳上，一只手拿着哑铃，手掌朝向身体。将双脚平放在地面上，并保持背部挺直。将哑铃举至肩膀高度，保持肘部靠近身体。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1622', 'dumbbell one arm reverse grip press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Sit on a flat bench with a dumbbell in one hand, palm facing towards your body. Place your feet flat on the ground and keep your back straight. Raise the dumbbell to shoulder height, keeping your elbow close to your body. Press the dumbbell upwards until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1622-Ze7MoIb.jpg', '/static/exercises/gifs/1622-Ze7MoIb.gif', '© Gym visual — https://gymvisual.com/', '900814'),
('101414', '哑铃单臂反向牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。慢慢降低哑铃，直到手臂完全伸展。将哑铃向后弯向肩膀，保持上臂静止。在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1414', 'dumbbell one arm reverse preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip. Lower the dumbbell slowly until your arm is fully extended. Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1414-bWxq4op.jpg', '/static/exercises/gifs/1414-bWxq4op.gif', '© Gym visual — https://gymvisual.com/', '80815'),
('101667', '哑铃单臂反向蜘蛛式弯举', '前臂', '哑铃', '未分级', '站直，一只手握住哑铃，手掌朝下，手臂完全伸展。保持上臂静止，弯曲肘部，将哑铃向肩膀方向卷曲。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1667', 'dumbbell one arm reverse spider curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1667-VdLZ3nB.jpg', '/static/exercises/gifs/1667-VdLZ3nB.gif', '© Gym visual — https://gymvisual.com/', '80816'),
('101668', '哑铃单臂坐姿肱二头肌弯举健身球', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住哑铃，手掌朝上，手臂完全伸展。保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1668', 'dumbbell one arm seated bicep curl on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your arm fully extended. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1668-s999Hdo.jpg', '/static/exercises/gifs/1668-s999Hdo.gif', '© Gym visual — https://gymvisual.com/', '80823'),
('101669', '哑铃单臂坐姿锤式弯举', '前臂', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。一只手握住哑铃，保持中立握姿（手掌相对）。将肘部放在大腿内侧、膝盖上方。保持上臂静止，呼气并将哑铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1669', 'dumbbell one arm seated hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand with a neutral grip (palms facing each other). Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1669-jK2hZ6n.jpg', '/static/exercises/gifs/1669-jK2hZ6n.gif', '© Gym visual — https://gymvisual.com/', '80818'),
('101415', '哑铃单臂坐姿中立握腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。将前臂放在大腿上，让手腕悬在边缘。保持前臂静止，尽可能向上弯曲手腕。在顶部暂停片刻，然后慢慢将手腕放回起始位置。重复所需的重复次数，然后换另一只手。', 'exercise-dataset', '1415', 'dumbbell one arm seated neutral wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up. Rest your forearm on your thigh, allowing your wrist to hang off the edge. Keeping your forearm stationary, curl your wrist upward as far as possible. Pause for a moment at the top, then slowly lower your wrist back down to the starting position. Repeat for the desired number of repetitions, then switch to the other hand.', '/static/exercises/images/1415-YtaCTYl.jpg', '/static/exercises/gifs/1415-YtaCTYl.gif', '© Gym visual — https://gymvisual.com/', '821'),
('100361', '哑铃单臂肩上推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。向上推哑铃，直到手臂完全伸过头顶。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0361', 'dumbbell one arm shoulder press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Press the dumbbell upward until your arm is fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0361-84RyJf8.jpg', '/static/exercises/gifs/0361-84RyJf8.gif', '© Gym visual — https://gymvisual.com/', '818'),
('100360', '哑铃单臂肩上推举版本第二式', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0360', 'dumbbell one arm shoulder press v. 2', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward. Engage your core and press the dumbbell straight up overhead, fully extending your arm. Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0360-1TkiAFK.jpg', '/static/exercises/gifs/0360-1TkiAFK.gif', '© Gym visual — https://gymvisual.com/', '823'),
('103888', '哑铃单臂抓举', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃，正握。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。将哑铃向地面放低，使其靠近身体。爆发性伸展臀部、膝盖和脚踝，将哑铃沿直线向上推。当哑铃到达肩膀高度时，快速旋转你的手并将其击打过头顶，充分伸展你的手臂。将哑铃举过头顶，膝盖和臀部稍微弯曲。以受控的方式将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '3888', 'dumbbell one arm snatch', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Lower the dumbbell towards the ground, keeping it close to your body. Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line. As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm. Catch the dumbbell overhead with a slight bend in your knees and hips. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/3888-6pTkI99.jpg', '/static/exercises/gifs/3888-6pTkI99.gif', '© Gym visual — https://gymvisual.com/', '900818'),
('101670', '哑铃单臂站姿弯举', '前臂', '哑铃', '未分级', '站直，一手握哑铃，手掌朝前，手臂完全伸展。保持上臂静止，呼气并向上弯曲重量，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1670', 'dumbbell one arm standing curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended. Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1670-ffQsyBj.jpg', '/static/exercises/gifs/1670-ffQsyBj.gif', '© Gym visual — https://gymvisual.com/', '80821'),
('101671', '哑铃单臂站姿锤式弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，上臂保持静止。呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1671', 'dumbbell one arm standing hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and your upper arms stationary. Exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1671-2sQGZ5b.jpg', '/static/exercises/gifs/1671-2sQGZ5b.gif', '© Gym visual — https://gymvisual.com/', '80824'),
('100362', '哑铃单臂肱三头肌臂屈伸训练凳', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。一手握住哑铃，另一只手放在长凳上以获得支撑。将哑铃举过头顶，保持上臂靠近头部，肘部向前。弯曲肘部，将哑铃降低到头后，保持上臂静止。将手臂向后伸展至起始位置，完全伸直肘部。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0362', 'dumbbell one arm triceps extension (on bench)', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in one hand and place your other hand on the bench for support. Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary. Extend your arm back up to the starting position, fully straightening your elbow. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0362-nAuHPcD.jpg', '/static/exercises/gifs/0362-nAuHPcD.gif', '© Gym visual — https://gymvisual.com/', '400827'),
('100363', '哑铃单臂直立划船', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃，正握。让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0363', 'dumbbell one arm upright row', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip. Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body. Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0363-6cKQC5E.jpg', '/static/exercises/gifs/0363-6cKQC5E.gif', '© Gym visual — https://gymvisual.com/', '480824'),
('100364', '哑铃单臂腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上。一只手握住哑铃，反握，将前臂放在大腿上。让你的手腕伸展，让哑铃向你的手指方向滚动。慢慢地向后弯曲手腕，将哑铃拉向前臂。重复所需的重复次数，然后换另一只手。', 'exercise-dataset', '0364', 'dumbbell one arm wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh. Allow your wrist to extend, letting the dumbbell roll down towards your fingers. Slowly curl your wrist back up, bringing the dumbbell towards your forearm. Repeat for the desired number of repetitions, then switch to the other hand.', '/static/exercises/images/0364-q8aHNoF.jpg', '/static/exercises/gifs/0364-q8aHNoF.gif', '© Gym visual — https://gymvisual.com/', '825'),
('101672', '哑铃单臂佐特曼牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师弯举凳上，单手握哑铃，反握。将上臂放在牧师凳垫上，让手臂完全伸展。将哑铃向上弯向肩膀，保持上臂静止。在卷曲的顶部，旋转手腕，使手掌朝上。慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1672', 'dumbbell one arm zottman preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip. Rest your upper arm on the preacher bench pad, allowing your arm to fully extend. Curl the dumbbell up towards your shoulder, keeping your upper arm stationary. At the top of the curl, rotate your wrist so that your palm faces up. Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1672-sxY5Biu.jpg', '/static/exercises/gifs/1672-sxY5Biu.gif', '© Gym visual — https://gymvisual.com/', '80828'),
('101292', '哑铃单腿飞鸟健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双手各握一个哑铃，手掌相对。将一只脚放在地面上，并将另一条腿伸直到您面前。稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1292', 'dumbbell one leg fly on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other. Place one foot on the ground and extend the other leg straight out in front of you. Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows. Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest. Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1292-pH2x2jj.jpg', '/static/exercises/gifs/1292-pH2x2jj.gif', '© Gym visual — https://gymvisual.com/', '900831'),
('100365', '哑铃越过训练凳中立握腕弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。将前臂放在长凳上，让手腕悬在长凳边缘。保持上臂静止，呼气并将哑铃向上弯向肩膀。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0365', 'dumbbell over bench neutral wrist curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your forearms on the bench, allowing your wrists to hang off the edge. Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0365-BKa8dmT.jpg', '/static/exercises/gifs/0365-BKa8dmT.gif', '© Gym visual — https://gymvisual.com/', '80830'),
('100366', '哑铃越过训练凳单臂中立握腕弯举', '前臂', '哑铃', '未分级', '坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0366', 'dumbbell over bench one arm neutral wrist curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up. Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0366-IvV6C9M.jpg', '/static/exercises/gifs/0366-IvV6C9M.gif', '© Gym visual — https://gymvisual.com/', '80835'),
('101441', '哑铃越过训练凳单臂反向腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。将前臂放在长凳上，手腕悬在长凳边缘。慢慢向上弯曲手腕，将哑铃拉向前臂。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1441', 'dumbbell over bench one arm reverse wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1441-4Jc36XM.jpg', '/static/exercises/gifs/1441-4Jc36XM.gif', '© Gym visual — https://gymvisual.com/', '836'),
('100367', '哑铃越过训练凳单臂腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。将前臂放在长凳上，手腕悬在长凳边缘。慢慢向上弯曲手腕，将哑铃拉向前臂。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0367', 'dumbbell over bench one arm wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down. Rest your forearm on the bench with your wrist hanging off the edge. Slowly curl your wrist upwards, bringing the dumbbell towards your forearm. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0367-KI1DjNN.jpg', '/static/exercises/gifs/0367-KI1DjNN.gif', '© Gym visual — https://gymvisual.com/', '835'),
('100368', '哑铃越过训练凳反向腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。将前臂放在长凳上，让手腕悬在长凳边缘。慢慢向上弯曲手腕，将哑铃拉向身体。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0368', 'dumbbell over bench revers wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down. Rest your forearms on the bench, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0368-3tAXPQ6.jpg', '/static/exercises/gifs/0368-3tAXPQ6.gif', '© Gym visual — https://gymvisual.com/', '834'),
('100369', '哑铃越过训练凳腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。让手腕悬在长凳边缘。慢慢向上弯曲手腕，在动作的最高点挤压前臂。暂停片刻，然后慢慢将手腕放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0369', 'dumbbell over bench wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand. Allow your wrists to hang over the edge of the bench. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then slowly lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0369-D1xYJAU.jpg', '/static/exercises/gifs/0369-D1xYJAU.gif', '© Gym visual — https://gymvisual.com/', '833'),
('101329', '哑铃掌心旋转俯身划船', '肱二头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。让你的手臂笔直下垂，手掌朝向身体。收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。当你向上拉哑铃时，旋转手掌，使其背向身体。在动作的最高点将肩胛骨挤压在一起。慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。重复所需的重复次数。', 'exercise-dataset', '1329', 'dumbbell palm rotational bent over row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Bend forward at the hips, keeping your back straight and your knees slightly bent. Let your arms hang straight down, palms facing your body. Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body. As you pull the dumbbells up, rotate your palms so they face away from your body. Squeeze your shoulder blades together at the top of the movement. Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1329-wt6rwjk.jpg', '/static/exercises/gifs/1329-wt6rwjk.gif', '© Gym visual — https://gymvisual.com/', '160836'),
('101623', '哑铃掌心上斜卧推', '胸肌', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，背部靠在靠背上，双脚平放在地上。双手各握一个哑铃，正手握握，手掌朝内。将手臂伸直至胸部上方，保持肘部轻微弯曲。将哑铃慢慢向肩膀方向降低，保持肘部靠近身体。在底部暂停片刻，然后将哑铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1623', 'dumbbell palms in incline bench press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the backrest and feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing inwards. Extend your arms straight up above your chest, keeping a slight bend in your elbows. Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body. Pause for a moment at the bottom, then press the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1623-8eqjhOl.jpg', '/static/exercises/gifs/1623-8eqjhOl.gif', '© Gym visual — https://gymvisual.com/', '900837'),
('100370', '哑铃牧师凳锤式弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，并旋转手掌，直到手掌朝前。这将是您的起始位置。现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。然后，吸气并慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '0370', 'dumbbell peacher hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the recommended amount of repetitions.', '/static/exercises/images/0370-F1KxjBa.jpg', '/static/exercises/gifs/0370-F1KxjBa.gif', '© Gym visual — https://gymvisual.com/', '80834'),
('100371', '哑铃增强式深蹲', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。当你到达深蹲底部时，向上爆发，跳离地面。在空中时，快速改变双脚的位置，落地时另一只脚向前。立即将身体放回蹲姿，然后重复跳跃，再次换脚。每次跳跃时继续交替双脚的位置，达到所需的重复次数。', 'exercise-dataset', '0371', 'dumbbell plyo squat', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Lower your body into a squat position by bending your knees and pushing your hips back. As you reach the bottom of the squat, explode upward, jumping off the ground. While in the air, quickly switch the position of your feet, landing with your opposite foot forward. Immediately lower your body back into a squat position and repeat the jump, switching your feet again. Continue alternating the position of your feet with each jump for the desired number of repetitions.', '/static/exercises/images/0371-S4pwGlc.jpg', '/static/exercises/gifs/0371-S4pwGlc.gif', '© Gym visual — https://gymvisual.com/', '833'),
('100372', '哑铃牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。每只手握住一个哑铃，手掌朝上，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0372', 'dumbbell preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it. Hold a dumbbell in each hand with your palms facing up and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0372-jivWf8n.jpg', '/static/exercises/gifs/0372-jivWf8n.gif', '© Gym visual — https://gymvisual.com/', '80834'),
('101673', '哑铃牧师凳弯举越过健身球', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住哑铃，反握，将肘部放在健身球上。保持上臂静止，呼气并将哑铃向上弯向肩膀。在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1673', 'dumbbell preacher curl over exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1673-hwygydB.jpg', '/static/exercises/gifs/1673-hwygydB.gif', '© Gym visual — https://gymvisual.com/', '80841'),
('101293', '哑铃推举健身球', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。将哑铃举至肩高，手掌朝前。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1293', 'dumbbell press on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs. Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle. Raise the dumbbells to shoulder height, palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1293-O8o7q4d.jpg', '/static/exercises/gifs/1293-O8o7q4d.gif', '© Gym visual — https://gymvisual.com/', '900840'),
('100373', '哑铃旋前握肱三头肌臂屈伸', '前臂', '哑铃', '未分级', '坐在长凳或椅子上，背部挺直，双脚平放在地面上。双手握住哑铃，掌心朝下，双臂伸直举过头顶。保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0373', 'dumbbell pronate-grip triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'triceps', '肱三头肌', '["前臂"]', 'Sit on a bench or chair with your back straight and feet flat on the ground. Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead. Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0373-bpJL2Qs.jpg', '/static/exercises/gifs/0373-bpJL2Qs.gif', '© Gym visual — https://gymvisual.com/', '400839'),
('100374', '哑铃俯卧上斜弯举', '前臂', '哑铃', '未分级', '将长凳调整至 45 度倾斜。脸朝下躺在长凳上，胸部和腹部靠在长凳上。每只手握住一个哑铃，手掌朝下，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0374', 'dumbbell prone incline curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the bench to a 45-degree incline. Lie face down on the bench with your chest and stomach resting against it. Hold a dumbbell in each hand with your palms facing down and your arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0374-mwpPcr1.jpg', '/static/exercises/gifs/0374-mwpPcr1.gif', '© Gym visual — https://gymvisual.com/', '80840'),
('101674', '哑铃俯卧上斜锤式弯举', '前臂', '哑铃', '未分级', '将长凳调整至 45 度倾斜。脸朝下躺在长凳上，双手各握一个哑铃，手掌相对。让你的手臂垂直垂向地板，保持肘部稍微弯曲。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1674', 'dumbbell prone incline hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the bench to a 45-degree incline. Lie face down on the bench with a dumbbell in each hand, palms facing each other. Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1674-cWemPG8.jpg', '/static/exercises/gifs/1674-cWemPG8.gif', '© Gym visual — https://gymvisual.com/', '80843'),
('100375', '哑铃上拉', '背阔肌', '哑铃', '未分级', '平躺在长凳上，头放在一端，双脚放在地板上。双手握住哑铃，将手臂伸直至胸部上方。保持肘部轻微弯曲，慢慢地将哑铃放到脑后，直到感觉胸部和肩膀有拉伸感。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0375', 'dumbbell pullover', 'chest', '胸部', '10', 'dumbbell', 'latissimus dorsi', 'pectorals', '胸肌', '["背阔肌","肱三头肌"]', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0375-9XjtHvS.jpg', '/static/exercises/gifs/0375-9XjtHvS.gif', '© Gym visual — https://gymvisual.com/', '400838'),
('101294', '哑铃上拉伸髋健身球', '肱三头肌', '哑铃', '未分级', '坐在健身球上，双脚平放在地面上，哑铃放在大腿上。慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。将哑铃放在脑后，保持手臂伸直并保持控制。暂停片刻，然后将哑铃举回到起始位置。在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。将臀部放低至起始位置。重复所需的重复次数。', 'exercise-dataset', '1294', 'dumbbell pullover hip extension on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs. Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball. Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower the dumbbell behind your head, keeping your arms straight and maintaining control. Pause for a moment, then raise the dumbbell back to the starting position. While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core. Lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1294-lI7easp.jpg', '/static/exercises/gifs/1294-lI7easp.gif', '© Gym visual — https://gymvisual.com/', '400849'),
('101295', '哑铃上拉健身球', '肱三头肌', '哑铃', '未分级', '坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。慢慢地将哑铃放到脑后，同时保持手臂伸直。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1295', 'dumbbell pullover on exercise ball', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","背阔肌"]', 'Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended. Slowly lower the dumbbell behind your head while keeping your arms straight. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1295-FSD6PGL.jpg', '/static/exercises/gifs/1295-FSD6PGL.gif', '© Gym visual — https://gymvisual.com/', '400846'),
('101700', '哑铃推推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。稍微弯曲膝盖，身体下沉，然后爆发性伸展双腿，将哑铃压过头顶。在动作的最高点锁定手臂，然后将哑铃放回肩部水平。重复所需的重复次数。', 'exercise-dataset', '1700', 'dumbbell push press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level. Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead. Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/1700-FS63wTN.jpg', '/static/exercises/gifs/1700-FS63wTN.gif', '© Gym visual — https://gymvisual.com/', '900843'),
('100376', '哑铃上举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持背部挺直并启动核心肌群。将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0376', 'dumbbell raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keep your back straight and engage your core. Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0376-c9MnDRp.jpg', '/static/exercises/gifs/0376-c9MnDRp.gif', '© Gym visual — https://gymvisual.com/', '900842'),
('102292', '哑铃三角肌后束上举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2292', 'dumbbell rear delt raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2292-mu5Guxt.jpg', '/static/exercises/gifs/2292-mu5Guxt.gif', '© Gym visual — https://gymvisual.com/', '400847'),
('100377', '哑铃三角肌后束划船肩部', '斜方肌', '哑铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。每只手握住一个哑铃，手掌朝向身体。腰部向前弯曲，保持背部挺直，核心肌群参与。将手臂伸直向下伸向地板，肘部稍微弯曲。将哑铃向两侧举起，将肩胛骨挤压在一起。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0377', 'dumbbell rear delt row_shoulder', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with your palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arms straight down towards the floor, with a slight bend in your elbows. Raise the dumbbells out to the sides, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0377-EKXOMEh.jpg', '/static/exercises/gifs/0377-EKXOMEh.gif', '© Gym visual — https://gymvisual.com/', '400848'),
('100378', '哑铃后侧飞鸟', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将双臂笔直向下伸向地面，手掌相对。保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0378', 'dumbbell rear fly', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down towards the ground, palms facing each other. Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0378-8DiFDVA.jpg', '/static/exercises/gifs/0378-8DiFDVA.gif', '© Gym visual — https://gymvisual.com/', '900847'),
('100380', '哑铃后侧侧平举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0380', 'dumbbell rear lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0380-v1qBec9.jpg', '/static/exercises/gifs/0380-v1qBec9.gif', '© Gym visual — https://gymvisual.com/', '160850'),
('100379', '哑铃后侧侧平举支撑头后', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0379', 'dumbbell rear lateral raise (support head)', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0379-UzkLrem.jpg', '/static/exercises/gifs/0379-UzkLrem.gif', '© Gym visual — https://gymvisual.com/', '160855'),
('100381', '哑铃后侧弓步', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。右脚向后退一步，将身体降低至弓步位置。弯曲左膝并降低身体，直到左大腿与地面平行。暂停片刻，然后推动左脚跟回到起始位置。在另一侧重复，左脚向后退一步。', 'exercise-dataset', '0381', 'dumbbell rear lunge', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step backward with your right foot, lowering your body into a lunge position. Bend your left knee and lower your body until your left thigh is parallel to the ground. Pause for a moment, then push through your left heel to return to the starting position. Repeat on the other side, stepping back with your left foot.', '/static/exercises/images/0381-SSsBDwB.jpg', '/static/exercises/gifs/0381-SSsBDwB.gif', '© Gym visual — https://gymvisual.com/', '320850'),
('100382', '哑铃反向握肱二头肌弯举', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0382', 'dumbbell revers grip biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0382-e4ojVhP.jpg', '/static/exercises/gifs/0382-e4ojVhP.gif', '© Gym visual — https://gymvisual.com/', '855'),
('101624', '哑铃反向卧推', '肱三头肌', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上，膝盖弯曲。双手各握一个哑铃，正手握住，手掌朝向脚部。将手臂伸直向上伸向天花板，保持肘部轻微弯曲。慢慢地将哑铃降低到胸部，让肘部向两侧张开。在底部暂停片刻，然后将哑铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1624', 'dumbbell reverse bench press', 'chest', '胸部', '10', 'dumbbell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your knees bent. Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet. Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows. Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides. Pause for a moment at the bottom, then push the dumbbells back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1624-UIbGx6H.jpg', '/static/exercises/gifs/1624-UIbGx6H.gif', '© Gym visual — https://gymvisual.com/', '854'),
('100383', '哑铃反向飞鸟', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将双臂伸直在身前，手掌相对。保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0383', 'dumbbell reverse fly', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight down in front of you, palms facing each other. Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0383-EAs3xL9.jpg', '/static/exercises/gifs/0383-EAs3xL9.gif', '© Gym visual — https://gymvisual.com/', '320853'),
('101330', '哑铃反向握上斜训练凳单臂划船', '肱二头肌', '哑铃', '未分级', '设置一个 45 度角的上斜凳。将哑铃放在长凳旁边的地板上。面对长凳站立，双脚分开与肩同宽。弯曲腰部，将左膝和左手放在长凳上以获得支撑。用右手反握（手掌朝下）拿起哑铃。保持背部挺直，核心肌群参与。将哑铃向上拉向胸部，保持肘部靠近身体。在动作的最高点挤压背部肌肉。以受控的方式将哑铃放回起始位置。重复所需的重复次数。换边并用左臂重复练习。', 'exercise-dataset', '1330', 'dumbbell reverse grip incline bench one arm row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Place a dumbbell on the floor next to the bench. Stand facing the bench with your feet shoulder-width apart. Bend at the waist and place your left knee and left hand on the bench for support. Pick up the dumbbell with your right hand using a reverse grip (palm facing down). Keep your back straight and your core engaged. Pull the dumbbell up towards your chest, keeping your elbow close to your body. Squeeze your back muscles at the top of the movement. Lower the dumbbell back down to the starting position in a controlled manner. Repeat for the desired number of repetitions. Switch sides and repeat the exercise with your left arm.', '/static/exercises/images/1330-ZIViNh1.jpg', '/static/exercises/gifs/1330-ZIViNh1.gif', '© Gym visual — https://gymvisual.com/', '400864'),
('101331', '哑铃反向握上斜训练凳双臂划船', '肱二头肌', '哑铃', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，胸部靠在靠背上，双脚平放在地上。双手各握一个哑铃，反握。身体前倾，双臂伸直下垂，完全伸展。将哑铃拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1331', 'dumbbell reverse grip incline bench two arm row', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your chest against the backrest and your feet flat on the ground. Hold a dumbbell in each hand with an underhand grip. Lean forward and let your arms hang straight down, fully extended. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1331-9pQSkH8.jpg', '/static/exercises/gifs/1331-9pQSkH8.gif', '© Gym visual — https://gymvisual.com/', '900865'),
('102327', '哑铃反向握划船（女）', '肱二头肌', '哑铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。双手各握一个哑铃，正手握握，手掌朝向身体。腰部向前弯曲，保持背部挺直，核心肌群参与。让你的手臂伸直垂下，完全伸展，肘部稍微弯曲。将哑铃拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2327', 'dumbbell reverse grip row (female)', 'back', '背部', '20', 'dumbbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand with an overhand grip, palms facing your body. Bend forward at the waist, keeping your back straight and your core engaged. Let your arms hang straight down, fully extended, with a slight bend in your elbows. Pull the dumbbells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2327-Nh3mvOO.jpg', '/static/exercises/gifs/2327-Nh3mvOO.gif', '© Gym visual — https://gymvisual.com/', '900860'),
('100384', '哑铃反向牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。每只手握住一个哑铃，反握，手掌朝上。保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0384', 'dumbbell reverse preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support. Hold a dumbbell in each hand with an underhand grip, palms facing up. Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps. Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0384-O8Aq69u.jpg', '/static/exercises/gifs/0384-O8Aq69u.gif', '© Gym visual — https://gymvisual.com/', '80859'),
('101675', '哑铃反向蜘蛛式弯举', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝向身体，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1675', 'dumbbell reverse spider curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1675-6sMAmNv.jpg', '/static/exercises/gifs/1675-6sMAmNv.gif', '© Gym visual — https://gymvisual.com/', '80860'),
('100385', '哑铃反向腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上。双手各握一个哑铃，正手握握，手掌朝下。将前臂放在大腿上，让手腕悬在边缘。慢慢向上弯曲手腕，将哑铃拉向身体。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0385', 'dumbbell reverse wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench or chair with your feet flat on the ground. Hold a dumbbell in each hand with an overhand grip, palms facing down. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, bringing the dumbbells towards your body. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0385-BLCvwr2.jpg', '/static/exercises/gifs/0385-BLCvwr2.gif', '© Gym visual — https://gymvisual.com/', '861'),
('101459', '哑铃罗马尼亚硬拉', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让膝盖稍微弯曲。降低哑铃，直到感觉到腿筋拉伸，然后推动脚后跟并收紧臀肌，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1459', 'dumbbell romanian deadlift', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly. Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1459-rR0LJzx.jpg', '/static/exercises/gifs/1459-rR0LJzx.gif', '© Gym visual — https://gymvisual.com/', '80860'),
('100386', '哑铃旋转反向飞鸟', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。旋转手臂，使手掌朝下。慢慢地将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0386', 'dumbbell rotation reverse fly', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor. Rotate your arms so that your palms are facing downwards. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0386-prbWx1D.jpg', '/static/exercises/gifs/0386-prbWx1D.gif', '© Gym visual — https://gymvisual.com/', '320863'),
('102397', '哑铃斯科特推举', '肱三头肌', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝前。将哑铃举至肩部高度，肘部弯曲，手掌朝前。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2397', 'dumbbell scott press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2397-5vfAI0I.jpg', '/static/exercises/gifs/2397-5vfAI0I.gif', '© Gym visual — https://gymvisual.com/', '900862'),
('100387', '哑铃坐姿交替前侧上举', '斜方肌', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。用另一只手臂重复上述步骤。双臂交替进行所需的重复次数。', 'exercise-dataset', '0387', 'dumbbell seated alternate front raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides. Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', '/static/exercises/images/0387-gH5fRsC.jpg', '/static/exercises/gifs/0387-gH5fRsC.gif', '© Gym visual — https://gymvisual.com/', '240867'),
('101676', '哑铃坐姿交替锤式弯举健身球', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。每只手握住一个哑铃，手掌朝向身体，双臂完全伸展。保持上臂静止，呼气并将一只哑铃向上弯向肩膀，同时保持手掌朝向身体。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1676', 'dumbbell seated alternate hammer curl on exercise ball', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing your body and your arms fully extended. Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1676-QLRmNeT.jpg', '/static/exercises/gifs/1676-QLRmNeT.gif', '© Gym visual — https://gymvisual.com/', '80874'),
('100388', '哑铃坐姿交替推举', '肱三头肌', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝前。将哑铃举至肩部高度，肘部弯曲，手掌朝前。将一只哑铃举过头顶，完全伸展手臂。将哑铃放回至肩膀高度。用另一只手臂重复上述步骤。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0388', 'dumbbell seated alternate press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward. Press one dumbbell up overhead, fully extending your arm. Lower the dumbbell back down to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0388-QT5Q0nK.jpg', '/static/exercises/gifs/0388-QT5Q0nK.gif', '© Gym visual — https://gymvisual.com/', '900867'),
('103546', '哑铃坐姿交替肩部', '肱三头肌', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。双手各握一个哑铃，掌心向内，将哑铃举至肩高。将一个哑铃举过头顶，同时将另一个哑铃保持在与肩同高的位置。将举起的哑铃放回肩高，同时将另一个哑铃推过头顶。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '3546', 'dumbbell seated alternate shoulder', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height. Press one dumbbell up overhead while keeping the other dumbbell at shoulder height. Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead. Continue alternating between arms for the desired number of repetitions.', '/static/exercises/images/3546-q7qkONO.jpg', '/static/exercises/gifs/3546-q7qkONO.gif', '© Gym visual — https://gymvisual.com/', '900868'),
('100389', '哑铃坐姿训练凳伸展', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。双手握住哑铃，将手臂伸直至头顶上方。慢慢地将哑铃放到脑后，保持肘部靠近耳朵。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0389', 'dumbbell seated bench extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up above your head. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears. Pause for a moment, then raise the dumbbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0389-JhYSVwT.jpg', '/static/exercises/gifs/0389-JhYSVwT.gif', '© Gym visual — https://gymvisual.com/', '900869'),
('102317', '哑铃坐姿屈曲臂侧平举', '斜方肌', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。双手各握一个哑铃，手掌朝向身体，手臂弯曲成 90 度角。保持肘部弯曲，将手臂向两侧抬起，直到与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2317', 'dumbbell seated bent arm lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle. Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2317-JzQbv7J.jpg', '/static/exercises/gifs/2317-JzQbv7J.gif', '© Gym visual — https://gymvisual.com/', '160874'),
('101730', '哑铃坐姿屈曲越过交替后踢', '肩部', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝内。腰部向前弯曲，保持背部挺直并与地面平行。将一只手臂向后伸直，保持靠近身体，直到手臂完全伸展。暂停片刻，然后慢慢将哑铃放回起始位置。用另一只手臂重复上述步骤。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1730', 'dumbbell seated bent over alternate kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Sit on a bench with a dumbbell in each hand, palms facing inwards. Bend forward at the waist, keeping your back straight and parallel to the ground. Extend one arm straight back, keeping it close to your body, until your arm is fully extended. Pause for a moment, then slowly lower the dumbbell back to the starting position. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1730-x0lwvfq.jpg', '/static/exercises/gifs/1730-x0lwvfq.gif', '© Gym visual — https://gymvisual.com/', '560875'),
('101737', '哑铃坐姿屈曲越过肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，每只手各握一个哑铃。腰部向前弯曲，保持背部挺直，头部抬起。将手臂向后伸直，保持肘部靠近头部。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1737', 'dumbbell seated bent over triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand. Bend forward at the waist, keeping your back straight and your head up. Extend your arms straight back, keeping your elbows close to your head. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1737-4ievMJ9.jpg', '/static/exercises/gifs/1737-4ievMJ9.gif', '© Gym visual — https://gymvisual.com/', '400876'),
('101677', '哑铃坐姿肱二头肌弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。保持背部挺直，肘部靠近躯干。呼气并将哑铃向上弯向肩膀，收缩二头肌。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1677', 'dumbbell seated bicep curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbells up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1677-xiA6lRr.jpg', '/static/exercises/gifs/1677-xiA6lRr.gif', '© Gym visual — https://gymvisual.com/', '80873'),
('100390', '哑铃坐姿肱二头肌弯举瑞士球', '前臂', '哑铃', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。每只手握住一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0390', 'dumbbell seated biceps curl (on stability ball)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0390-WgJnBH5.jpg', '/static/exercises/gifs/0390-WgJnBH5.gif', '© Gym visual — https://gymvisual.com/', '880'),
('103547', '哑铃坐姿肱二头肌弯举肩上推举', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。每只手握住一个哑铃，手掌朝前，双臂完全伸展。保持肘部靠近身体两侧，将哑铃向上弯向肩膀。前臂垂直后，旋转手腕，使手掌朝前。将哑铃推过头顶，直到手臂完全伸展。通过反向运动将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3547', 'dumbbell seated biceps curl to shoulder press', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'biceps', '肱二头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing forward and arms fully extended. Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders. Once your forearms are vertical, rotate your wrists so that your palms are facing forward. Press the dumbbells overhead until your arms are fully extended. Lower the dumbbells back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/3547-OeL23VY.jpg', '/static/exercises/gifs/3547-OeL23VY.gif', '© Gym visual — https://gymvisual.com/', '881'),
('101379', '哑铃坐姿提踵', '腘绳肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。握住哑铃以保持稳定。尽可能高地抬高脚后跟，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1379', 'dumbbell seated calf raise', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs. Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge. Hold onto the dumbbell for stability. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1379-r29jP7S.jpg', '/static/exercises/gifs/1379-r29jP7S.gif', '© Gym visual — https://gymvisual.com/', '876'),
('100391', '哑铃坐姿弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地面上，每只手各握一个哑铃，手掌朝前。保持背部挺直，肘部靠近躯干。呼气并将哑铃向上弯向肩膀，收缩二头肌。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0391', 'dumbbell seated curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbells up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0391-TiaZTxx.jpg', '/static/exercises/gifs/0391-TiaZTxx.gif', '© Gym visual — https://gymvisual.com/', '80875'),
('100392', '哑铃坐姿前侧上举', '斜方肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。保持背部挺直，核心参与。将哑铃举到身前，手掌朝下，直到与肩同高。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0392', 'dumbbell seated front raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0392-Ys97II0.jpg', '/static/exercises/gifs/0392-Ys97II0.gif', '© Gym visual — https://gymvisual.com/', '240878'),
('101678', '哑铃坐姿锤式弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝向躯干，手臂伸直向下。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1678', 'dumbbell seated hammer curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1678-IGtBdNT.jpg', '/static/exercises/gifs/1678-IGtBdNT.gif', '© Gym visual — https://gymvisual.com/', '80879'),
('100393', '哑铃坐姿内侧肱二头肌弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。将上臂放在大腿上，让哑铃垂下。保持上臂不动，通过收缩二头肌将哑铃向肩膀方向卷曲。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0393', 'dumbbell seated inner biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your upper arms on your thighs, allowing the dumbbells to hang down. Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0393-KXyoEtA.jpg', '/static/exercises/gifs/0393-KXyoEtA.gif', '© Gym visual — https://gymvisual.com/', '882'),
('100394', '哑铃坐姿后踢', '肩部', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，每只手各握一个哑铃。稍微弯曲膝盖，从臀部向前倾斜，保持背部挺直。将上臂靠近身体两侧，并保持肘部弯曲成 90 度角。将手臂向后伸直，在动作的最高点挤压三头肌。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0394', 'dumbbell seated kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand. Bend your knees slightly and lean forward from your hips, keeping your back straight. Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0394-en550rk.jpg', '/static/exercises/gifs/0394-en550rk.gif', '© Gym visual — https://gymvisual.com/', '560879'),
('100396', '哑铃坐姿侧平举', '斜方肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。保持背部挺直，核心参与。将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0396', 'dumbbell seated lateral raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","上背部"]', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0396-hxyTtWj.jpg', '/static/exercises/gifs/0396-hxyTtWj.gif', '© Gym visual — https://gymvisual.com/', '160882'),
('100395', '哑铃坐姿侧平举版本第二式', '斜方肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。保持背部挺直，核心参与。将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0395', 'dumbbell seated lateral raise v. 2', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","肱三头肌"]', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0395-hrrS0Ed.jpg', '/static/exercises/gifs/0395-hrrS0Ed.gif', '© Gym visual — https://gymvisual.com/', '160887'),
('100397', '哑铃坐姿中立握腕弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，手掌相对。将前臂放在大腿上，让哑铃垂下。保持手腕处于中立位置，将哑铃向上弯向肩膀。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0397', 'dumbbell seated neutral wrist curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other. Rest your forearms on your thighs, allowing the dumbbells to hang down. Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0397-uJmK7Z1.jpg', '/static/exercises/gifs/0397-uJmK7Z1.gif', '© Gym visual — https://gymvisual.com/', '80886'),
('101679', '哑铃坐姿单臂肱二头肌弯举健身球腿抬高', '前臂', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，背部挺直。一只手握住哑铃，手掌朝上，手臂完全伸展。将另一只手放在臀部上以保持稳定。慢慢地将哑铃向肩膀弯曲，保持上臂静止。在动作的最高点暂停片刻，挤压你的二头肌。慢慢地将哑铃放回起始位置。重复所需的重复次数。交换手臂并重复练习。', 'exercise-dataset', '1679', 'dumbbell seated one arm bicep curl on exercise ball with leg raised', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your arm fully extended. Place your other hand on your hip for stability. Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top of the movement, squeezing your bicep. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', '/static/exercises/images/1679-84sESNy.jpg', '/static/exercises/gifs/1679-84sESNy.gif', '© Gym visual — https://gymvisual.com/', '80901'),
('100398', '哑铃坐姿单臂后踢', '肩部', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，一手握住哑铃。将躯干的腰部向前弯曲，保持背部挺直并与地面平行。将手臂向后伸直，保持肘部靠近身体。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0398', 'dumbbell seated one arm kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand. Bend your torso forward at the waist, keeping your back straight and parallel to the ground. Extend your arm straight back, keeping your elbow close to your body. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0398-VQ3sNCn.jpg', '/static/exercises/gifs/0398-VQ3sNCn.gif', '© Gym visual — https://gymvisual.com/', '560888'),
('100399', '哑铃坐姿单臂旋转', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，一只手握住哑铃，将其放在大腿上。将哑铃举至肩膀高度，保持肘部靠近身体。向外旋转前臂，远离身体，同时保持上臂静止。在顶部停顿片刻，然后慢慢旋转前臂回到起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0399', 'dumbbell seated one arm rotate', 'lower arms', '前臂', '80', 'dumbbell', 'shoulders', 'forearms', '前臂肌群', '["肩部","肱二头肌"]', 'Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh. Raise the dumbbell up to shoulder height, keeping your elbow close to your body. Rotate your forearm outward, away from your body, while keeping your upper arm stationary. Pause for a moment at the top, then slowly rotate your forearm back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0399-7f2jsqP.jpg', '/static/exercises/gifs/0399-7f2jsqP.gif', '© Gym visual — https://gymvisual.com/', '900889'),
('100400', '哑铃坐姿单腿提踵', '腘绳肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上，将哑铃放在右大腿上。将左腿伸直到身前，保持脚部弯曲。将右脚掌放在升高的表面上，例如台阶或配重板。使用小腿肌肉，尽可能高地抬高右脚跟。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0400', 'dumbbell seated one leg calf raise', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh. Extend your left leg straight out in front of you, keeping your foot flexed. Place the ball of your right foot on an elevated surface, such as a step or weight plate. Using your calf muscles, raise your right heel as high as possible. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0400-Ia7tumC.jpg', '/static/exercises/gifs/0400-Ia7tumC.gif', '© Gym visual — https://gymvisual.com/', '892'),
('101380', '哑铃坐姿单腿提踵锤式握', '腘绳肌', '哑铃', '未分级', '坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。将一只脚放在凸起的表面上，例如台阶或木块，脚跟悬在边缘之外。用锤式握法握住哑铃，这意味着您的手掌相对，手指缠绕在手柄上。保持核心收紧，背部挺直，通过脚掌推动，将脚后跟慢慢抬高，尽可能高。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换另一条腿。', 'exercise-dataset', '1380', 'dumbbell seated one leg calf raise - hammer grip', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs. Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge. Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle. Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the other leg.', '/static/exercises/images/1380-FxhcxUW.jpg', '/static/exercises/gifs/1380-FxhcxUW.gif', '© Gym visual — https://gymvisual.com/', '899'),
('101381', '哑铃坐姿单腿提踵掌心向上', '腘绳肌', '哑铃', '未分级', '坐在长凳或椅子上，背部挺直，双脚平放在地面上。一只手握住哑铃，将其放在大腿上方，掌心朝上。将一条腿抬离地面并将其延伸到您面前，保持膝盖稍微弯曲。通过脚掌推动，尽可能高地抬起脚后跟。在顶部停顿片刻，然后慢慢降低脚跟。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1381', 'dumbbell seated one leg calf raise - palm up', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Sit on a bench or chair with your back straight and your feet flat on the ground. Hold a dumbbell in one hand and place it on top of your thigh, palm facing up. Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent. Raise your heel as high as possible by pushing through the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1381-VW88JNd.jpg', '/static/exercises/gifs/1381-VW88JNd.gif', '© Gym visual — https://gymvisual.com/', '900'),
('100401', '哑铃坐姿正握腕弯举', '肱二头肌', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。将前臂放在大腿上，让手腕悬在边缘。慢慢向上弯曲手腕，在动作的最高点挤压前臂。暂停片刻，然后将手腕放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0401', 'dumbbell seated palms up wrist curl', 'lower arms', '前臂', '80', 'dumbbell', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肩部"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0401-2dImyQ8.jpg', '/static/exercises/gifs/0401-2dImyQ8.gif', '© Gym visual — https://gymvisual.com/', '895'),
('100402', '哑铃坐姿牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师弯举凳上，双脚平放在地板上。一只手握住哑铃，反手握住，将上臂靠在讲道垫上。保持上臂静止，呼气并将哑铃向上弯向肩膀。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0402', 'dumbbell seated preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher curl bench with your feet flat on the floor. Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0402-7D5bgLT.jpg', '/static/exercises/gifs/0402-7D5bgLT.gif', '© Gym visual — https://gymvisual.com/', '80892'),
('100403', '哑铃坐姿反向握集中弯举', '前臂', '哑铃', '未分级', '坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。将肘部放在大腿内侧、膝盖上方。保持上臂静止，呼气并将哑铃向肩膀弯曲。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0403', 'dumbbell seated revers grip concentration curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up. Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0403-lyKCLmK.jpg', '/static/exercises/gifs/0403-lyKCLmK.gif', '© Gym visual — https://gymvisual.com/', '80897'),
('101738', '哑铃坐姿反向握单臂过顶肱三头肌伸展', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。反手握住哑铃，将手臂伸直至头顶。弯曲肘部，将哑铃降低到头后，保持上臂静止。暂停片刻，然后将手臂伸回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1738', 'dumbbell seated reverse grip one arm overhead tricep extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with an underhand grip and extend your arm straight up overhead. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary. Pause for a moment, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1738-5fKX7wi.jpg', '/static/exercises/gifs/1738-5fKX7wi.gif', '© Gym visual — https://gymvisual.com/', '900904'),
('100405', '哑铃坐姿肩上推举', '肱三头肌', '哑铃', '未分级', '坐在长凳上，每只手各拿一个哑铃，放在大腿上。将哑铃举至肩高，手掌朝前。向上推哑铃，直到手臂完全伸过头顶。在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。重复所需的重复次数。', 'exercise-dataset', '0405', 'dumbbell seated shoulder press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with a dumbbell in each hand, resting on your thighs. Raise the dumbbells to shoulder height, palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0405-znQUdHY.jpg', '/static/exercises/gifs/0405-znQUdHY.gif', '© Gym visual — https://gymvisual.com/', '895'),
('100404', '哑铃坐姿肩上推举平行握握', '肱三头肌', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，掌心向内。将哑铃举至肩高，肘部弯曲，手掌朝前。向上推哑铃，直到手臂完全伸过头顶。在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。重复所需的重复次数。', 'exercise-dataset', '0404', 'dumbbell seated shoulder press (parallel grip)', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with a dumbbell in each hand, palms facing inward. Raise the dumbbells to shoulder height, elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0404-f1jf47L.jpg', '/static/exercises/gifs/0404-f1jf47L.gif', '© Gym visual — https://gymvisual.com/', '900'),
('102188', '哑铃坐姿肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。双手握住哑铃，双臂伸直举过头顶。弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。暂停片刻，然后伸直手臂，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2188', 'dumbbell seated triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up overhead. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears. Pause for a moment, then straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2188-kont8Ut.jpg', '/static/exercises/gifs/2188-kont8Ut.gif', '© Gym visual — https://gymvisual.com/', '400897'),
('100406', '哑铃耸肩', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持手臂伸直，让哑铃垂在身体两侧。尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。保持收缩一秒钟，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0406', 'dumbbell shrug', 'back', '背部', '20', 'dumbbell', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body. Keep your arms straight and let the dumbbells hang by your sides. Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders. Hold the contraction for a second, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0406-NJzBsGJ.jpg', '/static/exercises/gifs/0406-NJzBsGJ.gif', '© Gym visual — https://gymvisual.com/', '560894'),
('100407', '哑铃侧向侧屈', '腹斜肌', '哑铃', '未分级', '站直，双脚分开与肩同宽，一手握住哑铃，让它垂在身侧。保持背部挺直，核心肌群参与，慢慢地将腰部向哑铃的另一侧侧弯，在舒适的范围内尽可能降低重量。暂停片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边重复。', 'exercise-dataset', '0407', 'dumbbell side bend', 'waist', '腰腹', '60', 'dumbbell', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side. Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat.', '/static/exercises/images/0407-IpONWYv.jpg', '/static/exercises/gifs/0407-IpONWYv.gif', '© Gym visual — https://gymvisual.com/', '900897'),
('100408', '哑铃侧向仰卧单手上举', '斜方肌', '哑铃', '未分级', '侧躺，双腿伸直，用手臂支撑头部。用你的上手握住哑铃，手掌朝下。保持手臂伸直，将哑铃举至肩膀高度。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0408', 'dumbbell side lying one hand raise', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Lie on your side with your legs extended and your head supported by your arm. Hold a dumbbell in your top hand with your palm facing down. Keeping your arm straight, raise the dumbbell up to shoulder height. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0408-fTlkJop.jpg', '/static/exercises/gifs/0408-fTlkJop.gif', '© Gym visual — https://gymvisual.com/', '900904'),
('103664', '哑铃侧平板支撑后侧飞鸟', '肩部', '哑铃', '未分级', '首先侧躺，双腿伸展并叠放在一起。将前臂放在肩膀正下方的地面上，保持肘部弯曲成 90 度角。用你的上手握住哑铃，手臂垂直向下伸向地面。收紧核心并将臀部抬离地面，从头部到脚后跟形成一条直线。在保持侧平板支撑位置的同时，将哑铃向天花板方向举起，将肩胛骨挤压在一起。将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '3664', 'dumbbell side plank with rear fly', 'back', '背部', '20', 'dumbbell', 'shoulders', 'upper back', '上背部', '["肩部","核心肌群"]', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle. Hold a dumbbell in your top hand, with your arm extended straight down towards the ground. Engage your core and lift your hips off the ground, creating a straight line from your head to your heels. While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/3664-X6ytgYZ.jpg', '/static/exercises/gifs/3664-X6ytgYZ.gif', '© Gym visual — https://gymvisual.com/', '900905'),
('103548', '哑铃单侧臂过顶行走负重', '斜方肌', '哑铃', '未分级', '站直，双脚分开与肩同宽，一手握住哑铃。将哑铃举过头顶，充分伸展手臂。向前行走时，启动核心肌群并保持背部挺直，将哑铃举过头顶。继续步行所需的距离或时间。交换双手并重复练习。', 'exercise-dataset', '3548', 'dumbbell single arm overhead carry', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","核心肌群"]', 'Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand. Raise the dumbbell overhead, fully extending your arm. Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead. Continue walking for the desired distance or time. Switch hands and repeat the exercise.', '/static/exercises/images/3548-mWBtgmb.jpg', '/static/exercises/gifs/3548-mWBtgmb.gif', '© Gym visual — https://gymvisual.com/', '900904'),
('100409', '哑铃单侧腿提踵', '踝部肌群', '哑铃', '未分级', '站在台阶或平台的边缘，脚后跟悬垂，脚趾放在台阶上。一手握住哑铃，另一只手放在墙壁或栏杆上以获得支撑。尽可能高地抬高脚跟，将身体抬起到脚趾上。在顶部停顿片刻，然后慢慢将脚跟放回到台阶下方。重复所需的重复次数，然后换另一条腿。', 'exercise-dataset', '0409', 'dumbbell single leg calf raise', 'lower legs', '小腿', '70', 'dumbbell', 'ankles', 'calves', '小腿肌群', '["踝部肌群"]', 'Stand on the edge of a step or platform with your heels hanging off and your toes on the step. Hold a dumbbell in one hand and place your other hand on a wall or railing for support. Raise your heel as high as possible, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heel back down below the step. Repeat for the desired number of repetitions, then switch to the other leg.', '/static/exercises/images/0409-1kB3Wmk.jpg', '/static/exercises/gifs/0409-1kB3Wmk.gif', '© Gym visual — https://gymvisual.com/', '905'),
('101757', '哑铃单侧腿硬拉', '腘绳肌', '哑铃', '未分级', '双脚分开与臀部同宽站立，右手握住哑铃。将体重转移到左腿上，并将右脚稍微抬离地面。保持背部挺直，臀部向前转动，将哑铃放低至地面。同时，将右腿伸直在身后，保持左膝轻微弯曲。降低哑铃，直到躯干和右腿与地面平行。暂停片刻，然后收紧臀肌和腿筋，回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1757', 'dumbbell single leg deadlift', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand. Shift your weight onto your left leg and lift your right foot slightly off the ground. Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground. At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee. Lower the dumbbell until your torso and right leg are parallel to the ground. Pause for a moment, then engage your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1757-gKozT8X.jpg', '/static/exercises/gifs/1757-gKozT8X.gif', '© Gym visual — https://gymvisual.com/', '80904'),
('102805', '哑铃单侧腿硬拉登阶箱支撑', '腘绳肌', '哑铃', '未分级', '双脚分开与臀部同宽站立，右手握住哑铃。将左脚放在身后的台阶或高架表面上。保持背部挺直，核心收紧，髋部向前转动，将哑铃放低至地面。当你放下哑铃时，同时将左腿抬起到身后，从头到脚跟保持一条直线。降低哑铃，直到感觉到右腿筋拉伸，然后回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '2805', 'dumbbell single leg deadlift with stepbox support', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand. Place your left foot on a stepbox or elevated surface behind you. Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground. As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel. Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/2805-daBmy1Y.jpg', '/static/exercises/gifs/2805-daBmy1Y.gif', '© Gym visual — https://gymvisual.com/', '80911'),
('100410', '哑铃单侧腿分腿蹲', '臀肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。一只脚向前迈出一步，调整双脚的位置，使前脚平放在地面上，后脚抬高在长凳或台阶上。弯曲前膝盖和臀部，降低身体，保持后膝盖稍微弯曲，后脚跟离开地面。继续降低，直到大腿前部与地面平行，然后通过前脚跟推回到起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '0410', 'dumbbell single leg split squat', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step. Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground. Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/0410-qx4fgX7.jpg', '/static/exercises/gifs/0410-qx4fgX7.gif', '© Gym visual — https://gymvisual.com/', '908'),
('100411', '哑铃单侧腿深蹲', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。向前伸展一条腿，并在整个练习过程中保持其离开地面。弯曲站立的腿并降低身体，就像坐回椅子上一样。保持挺胸、背部挺直。在底部停顿片刻，然后用脚跟推动回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0411', 'dumbbell single leg squat', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Extend one leg forward and keep it off the ground throughout the exercise. Bend your standing leg and lower your body down as if sitting back into a chair. Keep your chest up and your back straight. Pause for a moment at the bottom, then push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0411-H6ybluc.jpg', '/static/exercises/gifs/0411-H6ybluc.gif', '© Gym visual — https://gymvisual.com/', '907'),
('100413', '哑铃深蹲', '股四头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。保持胸部挺直，核心收紧，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0413', 'dumbbell squat', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0413-HsvHqgf.jpg', '/static/exercises/gifs/0413-HsvHqgf.gif', '© Gym visual — https://gymvisual.com/', '904'),
('103560', '哑铃站姿交替锤式弯举推举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向身体。保持肘部靠近躯干，背部挺直。呼气，将右手的哑铃向肩膀弯曲，保持上臂静止。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。吸气，慢慢将哑铃放回起始位置。用左手重复卷发动作。左手完成弯举后，呼气，将右手的哑铃压过头顶。完全伸展手臂并在顶部保持片刻。吸气，慢慢将哑铃放回起始位置。用左手重复按压。继续交替进行弯举和推举，达到所需的重复次数。', 'exercise-dataset', '3560', 'dumbbell standing alternate hammer curl and press', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your back straight. Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Inhale and slowly lower the dumbbell back to the starting position. Repeat the curl with your left hand. After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead. Extend your arm fully and hold for a moment at the top. Inhale and slowly lower the dumbbell back to the starting position. Repeat the press with your left hand. Continue alternating between curls and presses for the desired number of repetitions.', '/static/exercises/images/3560-LeaZOIz.jpg', '/static/exercises/gifs/3560-LeaZOIz.gif', '© Gym visual — https://gymvisual.com/', '80915'),
('100414', '哑铃站姿交替过顶推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。将一只哑铃举过头顶，完全伸展手臂。将哑铃放低至肩部水平。用另一只手臂重复上述步骤。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0414', 'dumbbell standing alternate overhead press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward. Press one dumbbell overhead, fully extending your arm. Lower the dumbbell back to shoulder level. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0414-bBi35y3.jpg', '/static/exercises/gifs/0414-bBi35y3.gif', '© Gym visual — https://gymvisual.com/', '80912'),
('100415', '哑铃站姿交替上举', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。保持背部挺直，核心肌群参与。将一个哑铃举到一侧，保持手臂伸直，手掌朝下。继续抬起，直到手臂与地面平行。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。用另一只手臂重复上述步骤。双臂交替进行所需的重复次数。', 'exercise-dataset', '0415', 'dumbbell standing alternate raise', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and your core engaged. Raise one dumbbell to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', '/static/exercises/images/0415-SxHteRW.jpg', '/static/exercises/gifs/0415-SxHteRW.gif', '© Gym visual — https://gymvisual.com/', '900911'),
('101739', '哑铃站姿交替肱三头肌后踢', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。双臂向后伸直，保持肘部靠近身体。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。用另一只手臂重复上述动作，每次重复时交替进行。', 'exercise-dataset', '1739', 'dumbbell standing alternating tricep kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight back, keeping your elbows close to your body. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat with the other arm, alternating sides with each repetition.', '/static/exercises/images/1739-Gi2BXfK.jpg', '/static/exercises/gifs/1739-Gi2BXfK.gif', '© Gym visual — https://gymvisual.com/', '560914'),
('102143', '哑铃站姿环绕全球式', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。将手臂伸直至两侧，与肩同高，手掌朝下。保持手臂伸直，慢慢地以圆周运动旋转手臂，将哑铃放在身体前面，然后举过头顶。继续圆周运动，将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2143', 'dumbbell standing around world', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","前臂"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Extend your arms straight out to the sides at shoulder height, palms facing down. Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead. Continue the circular motion, bringing the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2143-RSOsp5d.jpg', '/static/exercises/gifs/2143-RSOsp5d.gif', '© Gym visual — https://gymvisual.com/', '900913'),
('101740', '哑铃站姿屈曲越过单臂肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃。腰部向前弯曲，保持背部挺直并与地面平行。将手臂向后伸直，保持肘部靠近身体。慢慢地将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1740', 'dumbbell standing bent over one arm triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Bend forward at the waist, keeping your back straight and parallel to the ground. Extend your arm straight back, keeping your elbow close to your body. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1740-CJwa0vD.jpg', '/static/exercises/gifs/1740-CJwa0vD.gif', '© Gym visual — https://gymvisual.com/', '400922'),
('101741', '哑铃站姿屈曲越过双臂肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。双臂向后伸直，保持肘部靠近身体。慢慢地将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1741', 'dumbbell standing bent over two arm triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部","后侧"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend forward at the waist, keeping your back straight and your knees slightly bent. Extend your arms straight back, keeping your elbows close to your body. Slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1741-3T12T87.jpg', '/static/exercises/gifs/1741-3T12T87.gif', '© Gym visual — https://gymvisual.com/', '400923'),
('100416', '哑铃站姿肱二头肌弯举', '前臂', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0416', 'dumbbell standing biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0416-3s4NnTh.jpg', '/static/exercises/gifs/0416-3s4NnTh.gif', '© Gym visual — https://gymvisual.com/', '916'),
('100417', '哑铃站姿提踵', '踝部肌群', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。用小腿将脚跟抬离地面，尽可能高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0417', 'dumbbell standing calf raise', 'lower legs', '小腿', '70', 'dumbbell', 'ankles', 'calves', '小腿肌群', '["踝部肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0417-dPmaUaU.jpg', '/static/exercises/gifs/0417-dPmaUaU.gif', '© Gym visual — https://gymvisual.com/', '917'),
('100418', '哑铃站姿集中弯举', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，一手握住哑铃，手臂完全伸展，手掌朝内。将另一只手放在大腿上以获得支撑。保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0418', 'dumbbell standing concentration curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards. Place your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0418-7inpWch.jpg', '/static/exercises/gifs/0418-7inpWch.gif', '© Gym visual — https://gymvisual.com/', '80918'),
('100419', '哑铃站姿前侧上举上方头后', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。保持双臂伸直，将哑铃举至身前，举过头顶。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0419', 'dumbbell standing front raise above head', 'shoulders', '肩部', '30', 'dumbbell', 'trapezius', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keep your arms straight and lift the dumbbells in front of you, raising them above your head. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0419-laVRfDf.jpg', '/static/exercises/gifs/0419-laVRfDf.gif', '© Gym visual — https://gymvisual.com/', '240923'),
('102321', '哑铃站姿内侧肱二头肌弯举版本第二式', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向躯干。保持肘部靠近躯干，并旋转手掌，直到手掌朝前。保持上臂不动，弯曲哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气时慢慢开始将哑铃放回起始位置。重复建议的重复次数。', 'exercise-dataset', '2321', 'dumbbell standing inner biceps curl v. 2', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. While holding your upper arms stationary, curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Slowly begin to bring the dumbbells back to the starting position as your breathe in. Repeat for the recommended amount of repetitions.', '/static/exercises/images/2321-vKilzz3.jpg', '/static/exercises/gifs/2321-vKilzz3.gif', '© Gym visual — https://gymvisual.com/', '926'),
('100420', '哑铃站姿后踢', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将手臂向后伸直，在动作的最高点挤压三头肌。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0420', 'dumbbell standing kickback', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0420-UmpPAAe.jpg', '/static/exercises/gifs/0420-UmpPAAe.gif', '© Gym visual — https://gymvisual.com/', '560919'),
('100421', '哑铃站姿单臂集中弯举', '前臂', '哑铃', '未分级', '站直，双脚分开与肩同宽，一手握住哑铃，掌心朝上。将空着的手放在大腿上以获得支撑。保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0421', 'dumbbell standing one arm concentration curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up. Place your free hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0421-8fgqP5a.jpg', '/static/exercises/gifs/0421-8fgqP5a.gif', '© Gym visual — https://gymvisual.com/', '80926'),
('100422', '哑铃站姿单臂弯举越过上斜训练凳', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，一手握住哑铃，手掌朝前。将另一只手放在倾斜的长凳上以获得支撑。保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '0422', 'dumbbell standing one arm curl (over incline bench)', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward. Place your other hand on an incline bench for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/0422-BIb1tGo.jpg', '/static/exercises/gifs/0422-BIb1tGo.gif', '© Gym visual — https://gymvisual.com/', '80931'),
('101680', '哑铃站姿单臂弯举越过上斜训练凳', '前臂', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃。将另一只手放在倾斜的长凳上以获得支撑。保持上臂静止，通过收缩二头肌将哑铃向肩膀弯曲。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1680', 'dumbbell standing one arm curl over incline bench', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Place your other hand on an incline bench for support. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1680-EmlJR2y.jpg', '/static/exercises/gifs/1680-EmlJR2y.gif', '© Gym visual — https://gymvisual.com/', '80932'),
('100423', '哑铃站姿单臂伸展', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃。将哑铃举过头顶，充分伸展手臂。保持上臂靠近头部并垂直于地面。慢慢地将哑铃放到脑后，弯曲肘部。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0423', 'dumbbell standing one arm extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Raise the dumbbell overhead, fully extending your arm. Keep your upper arm close to your head and perpendicular to the ground. Slowly lower the dumbbell behind your head, bending your elbow. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0423-BCUR88E.jpg', '/static/exercises/gifs/0423-BCUR88E.gif', '© Gym visual — https://gymvisual.com/', '900927'),
('100424', '哑铃站姿单臂掌心推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝内。启动你的核心并保持背部挺直。向上推哑铃，直到手臂完全伸展。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0424', 'dumbbell standing one arm palm in press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards. Engage your core and keep your back straight. Press the dumbbell upwards until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0424-ocYc6Db.jpg', '/static/exercises/gifs/0424-ocYc6Db.gif', '© Gym visual — https://gymvisual.com/', '900932'),
('100425', '哑铃站姿单臂反向弯举', '前臂', '哑铃', '未分级', '站直，双脚分开与肩同宽，一只手握住哑铃，正握。保持手臂完全伸展并靠近身体，手掌朝下。慢慢地将哑铃向上弯向肩膀，保持上臂静止。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0425', 'dumbbell standing one arm reverse curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip. Keep your arm fully extended and close to your body, with your palm facing down. Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0425-DU5Kkj2.jpg', '/static/exercises/gifs/0425-DU5Kkj2.gif', '© Gym visual — https://gymvisual.com/', '80931'),
('100426', '哑铃站姿过顶推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。向上推哑铃，直到手臂完全伸过头顶。在顶部停顿片刻，然后慢慢将哑铃放回至肩部水平。重复所需的重复次数。', 'exercise-dataset', '0426', 'dumbbell standing overhead press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0426-A6wtbuL.jpg', '/static/exercises/gifs/0426-A6wtbuL.gif', '© Gym visual — https://gymvisual.com/', '80928'),
('100427', '哑铃站姿掌心推举', '肱三头肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝内。保持核心收紧，背部挺直，向上推哑铃，直到手臂完全伸过头顶。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0427', 'dumbbell standing palms in press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards. Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0427-UilDHSs.jpg', '/static/exercises/gifs/0427-UilDHSs.gif', '© Gym visual — https://gymvisual.com/', '900931'),
('100428', '哑铃站姿牧师凳弯举', '前臂', '哑铃', '未分级', '站直，双脚分开与肩同宽，每只手各握一个哑铃，手掌朝前。将上臂后部靠在牧师凳或上斜凳上，肘部稍微弯曲。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0428', 'dumbbell standing preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0428-hq2hyDH.jpg', '/static/exercises/gifs/0428-hq2hyDH.gif', '© Gym visual — https://gymvisual.com/', '80930'),
('100429', '哑铃站姿反向弯举', '前臂', '哑铃', '未分级', '站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝向身体。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0429', 'dumbbell standing reverse curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0429-0IgNjSM.jpg', '/static/exercises/gifs/0429-0IgNjSM.gif', '© Gym visual — https://gymvisual.com/', '80931'),
('100430', '哑铃站姿肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃。将哑铃举过头顶，保持手臂伸直。弯曲肘部，将哑铃放到脑后，保持上臂静止。将手臂向后伸展至起始位置。重复所需的重复次数。', 'exercise-dataset', '0430', 'dumbbell standing triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Raise the dumbbell overhead, keeping your arm straight. Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary. Extend your arm back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0430-PdmaD0N.jpg', '/static/exercises/gifs/0430-PdmaD0N.gif', '© Gym visual — https://gymvisual.com/', '400932'),
('102293', '哑铃站姿佐特曼牧师凳弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝前。将上臂靠在牧师凳上，并保持肘部稍微弯曲。将哑铃向上弯向肩膀，同时保持上臂静止。在动作的最高点，旋转手腕，使手掌朝下。慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。重复所需的重复次数。', 'exercise-dataset', '2293', 'dumbbell standing zottman preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing forward. Place your upper arms against the preacher bench and keep your elbows slightly bent. Curl the dumbbells up towards your shoulders while keeping your upper arms stationary. At the top of the movement, rotate your wrists so that your palms are facing downward. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well. Repeat for the desired number of repetitions.', '/static/exercises/images/2293-P2nRiUa.jpg', '/static/exercises/gifs/2293-P2nRiUa.gif', '© Gym visual — https://gymvisual.com/', '80935'),
('101684', '哑铃踏步向上单侧腿平衡肱二头肌弯举', '股四头肌', '哑铃', '未分级', '站在台阶或平台前，每只手各握一个哑铃，手掌朝向身体。将右脚放在台阶上，确保整个脚与表面接触。启动核心并推动右脚跟，将身体抬起到台阶上，将左膝抬向胸部。在动作的最高点，弯曲肘部并将哑铃拉向肩膀，进行二头肌弯举。将哑铃放回原处，同时将左脚放回地面。在另一侧重复该动作，左脚向上并弯举哑铃。继续交替进行所需的重复次数。', 'exercise-dataset', '1684', 'dumbbell step up single leg balance with bicep curl', 'upper arms', '上臂', '50', 'dumbbell', 'quadriceps', 'biceps', '肱二头肌', '["股四头肌","臀肌","腘绳肌"]', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your body. Place your right foot on the step, ensuring your entire foot is in contact with the surface. Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest. At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders. Lower the dumbbells back down and simultaneously lower your left foot back to the ground. Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1684-76vfTdU.jpg', '/static/exercises/gifs/1684-76vfTdU.gif', '© Gym visual — https://gymvisual.com/', '80944'),
('100431', '哑铃踏步向上', '股四头肌', '哑铃', '未分级', '站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。将右脚放在长凳或台阶上，确保整个脚与表面接触。推动右脚跟，将身体抬起到长凳或台阶上，伸直右腿。将左脚放在长凳或台阶上，完全直立。左脚向后退一步，然后是右脚，回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0431', 'dumbbell step-up', 'upper legs', '大腿', '40', 'dumbbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your right heel and lift your body up onto the bench or step, straightening your right leg. Bring your left foot up onto the bench or step, standing fully upright. Step back down with your left foot, followed by your right foot, returning to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0431-aXtJhlg.jpg', '/static/exercises/gifs/0431-aXtJhlg.gif', '© Gym visual — https://gymvisual.com/', '900931'),
('102796', '哑铃踏步向上弓步', '臀肌', '哑铃', '未分级', '站在台阶或平台前，每只手各持一个哑铃，手掌朝向身体两侧。将右脚放在台阶上，确保整个脚都踩在台阶上。推动右脚跟，将身体抬起到台阶上，同时将左脚抬起。双脚踩在台阶上后，将左脚放回起始位置，并将右脚保持在台阶上。重复该动作，每次交替使用哪只脚。继续进行所需的重复次数。', 'exercise-dataset', '2796', 'dumbbell step-up lunge', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides. Place your right foot on the step, ensuring your entire foot is on the surface. Push through your right heel and lift your body up onto the step, bringing your left foot up as well. Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step. Repeat the movement, alternating which foot you step up with each time. Continue for the desired number of repetitions.', '/static/exercises/images/2796-gFyFj9z.jpg', '/static/exercises/gifs/2796-gFyFj9z.gif', '© Gym visual — https://gymvisual.com/', '320934'),
('102812', '哑铃踏步向上分腿蹲', '臀肌', '哑铃', '未分级', '站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。将右脚放在长凳或台阶上，确保整个脚与表面接触。走到长凳上或用右脚踩上，用脚跟推动身体抬起。当你向上迈步时，同时将左膝抬向胸部。在动作的最高点暂停，然后慢慢将左脚放回地面，同时将右脚放在长凳或台阶上。将左脚放在长凳或台阶上，重复该动作。继续交替左右脚，达到所需的重复次数。', 'exercise-dataset', '2812', 'dumbbell step-up split squat', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface. Step up onto the bench or step with your right foot, pushing through your heel to lift your body up. As you step up, simultaneously lift your left knee towards your chest. Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step. Repeat the movement with your left foot on the bench or step. Continue alternating between your right and left foot for the desired number of repetitions.', '/static/exercises/images/2812-QjE2DcA.jpg', '/static/exercises/gifs/2812-QjE2DcA.gif', '© Gym visual — https://gymvisual.com/', '937'),
('100432', '哑铃直腿硬拉', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0432', 'dumbbell stiff leg deadlift', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees. Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0432-5eLRITT.jpg', '/static/exercises/gifs/0432-5eLRITT.gif', '© Gym visual — https://gymvisual.com/', '80938'),
('100433', '哑铃直臂上拉', '背阔肌', '哑铃', '未分级', '平躺在长凳上，头朝一端，双脚牢牢踩在地上。双手握住哑铃，将手臂伸直至胸部上方。保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0433', 'dumbbell straight arm pullover', 'chest', '胸部', '10', 'dumbbell', 'latissimus dorsi', 'pectorals', '胸肌', '["背阔肌","肱三头肌"]', 'Lie flat on a bench with your head at one end and your feet planted firmly on the ground. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0433-i8BdLTK.jpg', '/static/exercises/gifs/0433-i8BdLTK.gif', '© Gym visual — https://gymvisual.com/', '400939'),
('100434', '哑铃直腿硬拉', '腘绳肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让躯干向前倾斜。继续降低哑铃，直到感觉到腿筋拉伸，保持膝盖稍微弯曲。在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0434', 'dumbbell straight leg deadlift', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward. Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0434-oom75KC.jpg', '/static/exercises/gifs/0434-oom75KC.gif', '© Gym visual — https://gymvisual.com/', '80940'),
('102808', '哑铃相扑式绳索胯下拉', '腘绳肌', '哑铃', '未分级', '站立，双脚分开比肩宽，脚趾朝外。双手握住哑铃置于身体前方，双臂伸展。弯曲膝盖，将臀部放低至下蹲位置，保持背部挺直。将哑铃放在两腿之间，保持手臂伸直。通过脚后跟发力，向前伸展臀部，将哑铃向上拉至身体前方。在动作的最高点挤压臀部，然后将哑铃放回双腿之间。重复所需的重复次数。', 'exercise-dataset', '2808', 'dumbbell sumo pull through', 'upper legs', '大腿', '40', 'dumbbell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","核心肌群"]', 'Stand with your feet wider than shoulder-width apart, toes pointed outwards. Hold a dumbbell with both hands in front of your body, arms extended. Bend your knees and lower your hips down into a squat position, keeping your back straight. Lower the dumbbell down between your legs, keeping your arms straight. Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body. Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs. Repeat for the desired number of repetitions.', '/static/exercises/images/2808-BmrwWzo.jpg', '/static/exercises/gifs/2808-BmrwWzo.gif', '© Gym visual — https://gymvisual.com/', '900941'),
('102803', '哑铃支撑深蹲', '臀肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2803', 'dumbbell supported squat', 'upper legs', '大腿', '40', 'dumbbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2803-r5DgrW9.jpg', '/static/exercises/gifs/2803-r5DgrW9.gif', '© Gym visual — https://gymvisual.com/', '940'),
('100436', '哑铃泰特推举', '肩部', '哑铃', '未分级', '坐在平坦的长凳上，双手各握一个哑铃，手掌相对。将哑铃举至肩膀高度，然后旋转手腕，使手掌背向自己。向上推哑铃，直到手臂完全伸展，然后将其放回至肩膀高度。将手腕旋转回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0436', 'dumbbell tate press', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a flat bench with a dumbbell in each hand, palms facing each other. Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you. Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height. Rotate your wrists back to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0436-s5PdDyY.jpg', '/static/exercises/gifs/0436-s5PdDyY.gif', '© Gym visual — https://gymvisual.com/', '900941'),
('101742', '哑铃肱三头肌后踢鹳式站姿', '肩部', '哑铃', '未分级', '双脚分开与肩同宽站立，右手握住哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将右肘举至身体一侧，保持弯曲 90 度角。将右臂向后伸直，挤压三头肌。暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1742', 'dumbbell tricep kickback with stork stance', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your right elbow up to your side, keeping it bent at a 90-degree angle. Extend your right arm straight back, squeezing your triceps. Pause for a moment, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1742-wOLmCXc.jpg', '/static/exercises/gifs/1742-wOLmCXc.gif', '© Gym visual — https://gymvisual.com/', '560948'),
('101743', '哑铃转体卧推', '胸肌', '哑铃', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。双手各握一个哑铃，正手握握，手掌背向自己。将手臂伸直越过胸部，保持肘部轻微弯曲。将哑铃向胸部方向降低，保持肘部靠近身体。放下哑铃时，扭转手腕，使手掌在动作底部面向自己。在底部暂停片刻，然后通过将哑铃推回到起始位置来反转动作。当你向上推哑铃时，将手腕扭转回起始位置，手掌背向自己。重复所需的重复次数。', 'exercise-dataset', '1743', 'dumbbell twisting bench press', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand with an overhand grip, palms facing away from you. Extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower the dumbbells down towards your chest, keeping your elbows close to your body. As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement. Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position. As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you. Repeat for the desired number of repetitions.', '/static/exercises/images/1743-z6TAHoT.jpg', '/static/exercises/gifs/1743-z6TAHoT.gif', '© Gym visual — https://gymvisual.com/', '900945'),
('100437', '哑铃直立划船', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。让哑铃悬挂在大腿前面，双臂完全伸展。保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0437', 'dumbbell upright row', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let the dumbbells hang in front of your thighs, with your arms fully extended. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0437-ainizkb.jpg', '/static/exercises/gifs/0437-ainizkb.gif', '© Gym visual — https://gymvisual.com/', '480944'),
('101765', '哑铃直立划船后侧视角', '斜方肌', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，正握。让哑铃悬挂在大腿前面，双臂完全伸展，手掌面向身体。保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。继续举起哑铃，直到哑铃与肩同高，肘部指向两侧。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1765', 'dumbbell upright row (back pov)', 'shoulders', '肩部', '30', 'dumbbell', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows. Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1765-Iptlv6x.jpg', '/static/exercises/gifs/1765-Iptlv6x.gif', '© Gym visual — https://gymvisual.com/', '480949'),
('100864', '哑铃直立肩部外旋旋转', '肩袖肌群', '哑铃', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。在最高点暂停片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0864', 'dumbbell upright shoulder external rotation', 'shoulders', '肩部', '30', 'dumbbell', 'rotator cuff', 'delts', '三角肌', '["肩袖肌群","斜方肌"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body. Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent. Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0864-x306lCW.jpg', '/static/exercises/gifs/0864-x306lCW.gif', '© Gym visual — https://gymvisual.com/', '900950'),
('105201', '哑铃托举式肱二头肌弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝前。保持上臂靠近身体，肘部内收。慢慢地将哑铃向上弯向肩膀，保持手腕伸直。在顶部停顿片刻，然后慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '5201', 'dumbbell waiter biceps curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your upper arms close to your body and your elbows tucked in. Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/5201-KOpzGBL.jpg', '/static/exercises/gifs/5201-KOpzGBL.gif', '© Gym visual — https://gymvisual.com/', '949'),
('100438', '哑铃W字推举', '肱三头肌', '哑铃', '未分级', '坐在长凳上，双手各握一个哑铃，手掌朝前。将哑铃举至肩高，肘部弯曲，手掌朝前。向上推哑铃，直到手臂完全伸过头顶。将哑铃放低至肩部高度。重复所需的重复次数。', 'exercise-dataset', '0438', 'dumbbell w-press', 'shoulders', '肩部', '30', 'dumbbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0438-vmwLyCg.jpg', '/static/exercises/gifs/0438-vmwLyCg.gif', '© Gym visual — https://gymvisual.com/', '900946'),
('100439', '哑铃佐特曼弯举', '前臂', '哑铃', '未分级', '站直，双手各持一个哑铃，手掌朝向身体。保持肘部靠近躯干，并旋转手掌以面向前方。将哑铃举至肩膀处，同时保持上臂静止。在动作的最高点，旋转手腕，使手掌背向身体。慢慢地将哑铃放回起始位置，将手掌旋转回面向身体。重复所需的重复次数。', 'exercise-dataset', '0439', 'dumbbell zottman curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and rotate your palms to face forward. Curl the dumbbells up to your shoulders while keeping your upper arms stationary. At the top of the movement, rotate your wrists so that your palms are facing away from your body. Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body. Repeat for the desired number of repetitions.', '/static/exercises/images/0439-kXaIn5A.jpg', '/static/exercises/gifs/0439-kXaIn5A.gif', '© Gym visual — https://gymvisual.com/', '80949'),
('102294', '哑铃佐特曼牧师凳弯举', '前臂', '哑铃', '未分级', '坐在牧师凳上，双手各持一个哑铃，手掌朝上，肘部放在垫子上。将哑铃向上弯向肩膀，保持上臂静止，手掌朝上。在弯举的顶部，旋转手腕，使手掌朝下。慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。重复所需的重复次数。', 'exercise-dataset', '2294', 'dumbbell zottman preacher curl', 'upper arms', '上臂', '50', 'dumbbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad. Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up. At the top of the curl, rotate your wrists so that your palms are facing down. Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so. Repeat for the desired number of repetitions.', '/static/exercises/images/2294-y5U5B9Y.jpg', '/static/exercises/gifs/2294-y5U5B9Y.gif', '© Gym visual — https://gymvisual.com/', '80952'),
('102189', '哑铃坐姿肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。双手握住哑铃，正握，将其举过头顶。弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。伸展双臂，将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2189', 'dumbbells seated triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in both hands with an overhand grip, and raise it above your head. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears. Extend your arms and raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2189-FQXdXzY.jpg', '/static/exercises/gifs/2189-FQXdXzY.gif', '© Gym visual — https://gymvisual.com/', '400953'),
('101167', '动态胸部拉伸（男）', '肩部', '自重', '未分级', '站直，双脚分开与肩同宽。将双臂伸直至两侧，与地面平行。慢慢地将双臂向前伸，交叉在身体前面。感受胸部肌肉的伸展。保持拉伸 10-30 秒。返回起始位置并重复所需的重复次数。', 'exercise-dataset', '1167', 'dynamic chest stretch (male)', 'chest', '胸部', '10', 'body weight', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out to the sides, parallel to the ground. Slowly bring your arms forward, crossing them in front of your body. Feel the stretch in your chest muscles. Hold the stretch for 10-30 seconds. Return to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/1167-3uj0Ozg.jpg', '/static/exercises/gifs/1167-3uj0Ozg.gif', '© Gym visual — https://gymvisual.com/', '900754'),
('103287', '肘臂屈伸', '胸肌', '自重', '未分级', '坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。将臀部向前滑离长凳，伸直双腿，保持脚后跟着地。弯曲肘部，将身体放低至地面，保持背部靠近长凳。在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3287', 'elbow dips', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3287-LkoAWAE.jpg', '/static/exercises/gifs/3287-LkoAWAE.gif', '© Gym visual — https://gymvisual.com/', '480751'),
('101772', '肘抬举反向俯卧撑', '肱三头肌', '自重', '未分级', '首先，脸朝下躺在地上，双腿伸展，双手直接放在肩膀下方。收紧核心并用手掌按压，将上半身抬离地面，保持肘部靠近身体两侧。在顶部暂停片刻，挤压上背部肌肉。慢慢地将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1772', 'elbow lift - reverse push-up', 'back', '背部', '20', 'body weight', 'triceps', 'upper back', '上背部', '["肱三头肌","肩部"]', 'Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders. Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides. Pause at the top for a moment, squeezing your upper back muscles. Slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1772-wbUYILZ.jpg', '/static/exercises/gifs/1772-wbUYILZ.gif', '© Gym visual — https://gymvisual.com/', '900758'),
('100443', '肘膝', '腹斜肌', '自重', '未分级', '首先平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。同时，将左膝移向右肘，形成扭转动作。在顶部停顿片刻，然后慢慢降低上半身并将双腿伸展回到起始位置。重复该动作，这次将左肘移向右膝，将右膝移向左肘。继续交替进行所需的重复次数。', 'exercise-dataset', '0443', 'elbow-to-knee', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Start by lying flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee. At the same time, bring your left knee towards your right elbow, creating a twisting motion. Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position. Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0443-jvp6DiD.jpg', '/static/exercises/gifs/0443-jvp6DiD.gif', '© Gym visual — https://gymvisual.com/', '900751'),
('103292', '电梯式', '肩部', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双手放在臀部或交叉放在胸前。保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。在底部停顿片刻，然后慢慢抬起上半身回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3292', 'elevator', 'back', '背部', '20', 'body weight', 'shoulders', 'upper back', '上背部', '["肩部","斜方肌"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Place your hands on your hips or cross them in front of your chest. Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground. Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3292-zYmNaoY.jpg', '/static/exercises/gifs/3292-zYmNaoY.gif', '© Gym visual — https://gymvisual.com/', '900752'),
('101332', '健身球交替臂上撑', '肩部', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。双手各握一个哑铃，手掌朝内，双臂在身体两侧向下伸展。启动你的核心，慢慢地将一只手臂向肩膀抬起，保持肘部稍微弯曲。在顶部暂停片刻，然后慢慢将手臂放回起始位置。用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '1332', 'exercise ball alternating arm ups', 'back', '背部', '20', 'stability ball', 'shoulders', 'lats', '背阔肌', '["肩部","核心肌群"]', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides. Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat the movement with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/1332-EyLrNC2.jpg', '/static/exercises/gifs/1332-EyLrNC2.gif', '© Gym visual — https://gymvisual.com/', '901661'),
('101333', '健身球山羊挺身双臂伸展', '臀肌', '瑞士球', '未分级', '将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。将双臂伸直在身前，手掌朝下。启动你的核心，慢慢地将上半身抬离球，保持背部挺直，颈部与脊柱成一直线。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1333', 'exercise ball back extension with arms extended', 'back', '背部', '20', 'stability ball', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability. Extend your arms straight out in front of you, with your palms facing down. Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1333-PERjVm8.jpg', '/static/exercises/gifs/1333-PERjVm8.gif', '© Gym visual — https://gymvisual.com/', '481666'),
('101334', '健身球山羊挺身双手颈后头后', '臀肌', '瑞士球', '未分级', '将稳定球放在地上，面朝下躺在上面，臀部放在球上。将脚靠在墙壁或其他稳定的表面上以获得支撑。双臂交叉于脑后，双手触碰后脑勺。启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到臀部形成一条直线。在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1334', 'exercise ball back extension with hands behind head', 'back', '背部', '20', 'stability ball', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball. Position your feet against a wall or other stable surface for support. Cross your arms behind your head, with your hands touching the back of your head. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1334-o1HGDSq.jpg', '/static/exercises/gifs/1334-o1HGDSq.gif', '© Gym visual — https://gymvisual.com/', '481669'),
('101335', '健身球山羊挺身双膝离地地面', '臀肌', '瑞士球', '未分级', '将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。将双手放在脑后或交叉在胸前。启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1335', 'exercise ball back extension with knees off ground', 'back', '背部', '20', 'stability ball', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability. Position your hands behind your head or crossed over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1335-WME869U.jpg', '/static/exercises/gifs/1335-WME869U.gif', '© Gym visual — https://gymvisual.com/', '481670'),
('101336', '健身球山羊挺身旋转', '臀肌', '瑞士球', '未分级', '首先，面朝下躺在稳定球上，臀部放在球上，双脚牢牢踩在地面上。将双手放在脑后或交叉放在胸前。启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。在顶部停顿片刻，然后慢慢将躯干旋转到一侧，保持臀部和腿部稳定。返回中心并重复旋转到另一侧。将上半身放低至起始位置，然后重复所需的重复次数。', 'exercise-dataset', '1336', 'exercise ball back extension with rotation', 'back', '背部', '20', 'stability ball', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground. Place your hands behind your head or cross them over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable. Return to the center and repeat the rotation to the other side. Lower your upper body back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/1336-WVD66ff.jpg', '/static/exercises/gifs/1336-WVD66ff.gif', '© Gym visual — https://gymvisual.com/', '481667'),
('101744', '健身球臂屈伸', '胸肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。将双手放在臀部旁边的球上，手指指向前方。启动你的三头肌并用力推动你的身体，将你的身体抬离球，伸直你的手臂。弯曲肘部，将身体放低，使其靠近身体两侧。重复所需的重复次数。', 'exercise-dataset', '1744', 'exercise ball dip', 'upper arms', '上臂', '50', 'stability ball', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands on the ball beside your hips, fingers pointing forward. Engage your triceps and push through your hands to lift your body off the ball, straightening your arms. Lower your body back down by bending your elbows, keeping them close to your sides. Repeat for the desired number of repetitions.', '/static/exercises/images/1744-kprile3.jpg', '/static/exercises/gifs/1744-kprile3.gif', '© Gym visual — https://gymvisual.com/', '481662'),
('101559', '健身球髋部屈肌拉伸', '股四头肌', '瑞士球', '未分级', '将稳定球放在地上并跪在其前面。将右脚放在稳定球上，膝盖弯曲成 90 度角。将左腿伸到身后，保持伸直。身体前倾，将臀部推向稳定球，直到感觉到右髋屈肌有拉伸感。保持拉伸 20-30 秒，然后换边重复。', 'exercise-dataset', '1559', 'exercise ball hip flexor stretch', 'upper legs', '大腿', '40', 'stability ball', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌"]', 'Place the stability ball on the ground and kneel in front of it. Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle. Extend your left leg behind you, keeping it straight. Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '/static/exercises/images/1559-2LQkNPW.jpg', '/static/exercises/gifs/1559-2LQkNPW.gif', '© Gym visual — https://gymvisual.com/', '901667'),
('101338', '健身球抱球', '肩部', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。用双手握住稳定球，将其抱在靠近胸部的位置。启动你的核心肌肉，慢慢向后倾斜，保持背部挺直，双脚踩在地上。继续向后倾斜，直到感觉到背部肌肉伸展。保持该姿势几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1338', 'exercise ball hug', 'back', '背部', '20', 'stability ball', 'shoulders', 'spine', '竖脊肌', '["肩部","胸肌"]', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold the stability ball with both hands, hugging it close to your chest. Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground. Continue leaning back until you feel a stretch in your back muscles. Hold the position for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1338-d7z1Y7V.jpg', '/static/exercises/gifs/1338-d7z1Y7V.gif', '© Gym visual — https://gymvisual.com/', '901664'),
('101339', '健身球背阔肌拉伸', '肩部', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。一只手握住哑铃，然后将手臂伸直至头顶。慢慢地向另一侧倾斜，感受背阔肌的拉伸。保持伸展动作 20-30 秒，然后回到起始位置。在另一侧重复。', 'exercise-dataset', '1339', 'exercise ball lat stretch', 'back', '背部', '20', 'stability ball', 'shoulders', 'lats', '背阔肌', '["肩部","肱三头肌"]', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand and extend your arm straight up overhead. Slowly lean to the opposite side, feeling a stretch in your lat muscle. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat on the other side.', '/static/exercises/images/1339-sM84pE4.jpg', '/static/exercises/gifs/1339-sM84pE4.gif', '© Gym visual — https://gymvisual.com/', '901667'),
('101341', '健身球下部后侧拉伸金字塔式', '臀肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。慢慢地向前移动你的脚，将球沿着你的背部滚动，直到你的下背部靠在球上。将双手放在脑后或交叉放在胸前。启动你的核心，慢慢地将你的上半身降低到地面，让你的下背部伸展到球上方。保持伸展几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1341', 'exercise ball lower back stretch (pyramid)', 'back', '背部', '20', 'stability ball', 'glutes', 'lats', '背阔肌', '["臀肌","腘绳肌"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball. Place your hands behind your head or cross them over your chest. Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1341-yU7w7CA.jpg', '/static/exercises/gifs/1341-yU7w7CA.gif', '© Gym visual — https://gymvisual.com/', '901672'),
('101342', '健身球仰卧侧向背阔肌拉伸', '肩部', '瑞士球', '未分级', '侧躺，双腿伸展，头部由稳定球支撑。将上臂放在球上以保持稳定性。将上臂举过头顶，让躯干稍微旋转。感受身体一侧背阔肌的拉伸。保持拉伸 20-30 秒，然后换边重复。', 'exercise-dataset', '1342', 'exercise ball lying side lat stretch', 'back', '背部', '20', 'stability ball', 'shoulders', 'lats', '背阔肌', '["肩部","肱三头肌"]', 'Lie on your side with your legs extended and your head supported by the stability ball. Place your top arm on the ball for stability. Reach your top arm overhead and allow your torso to rotate slightly. Feel the stretch in your lat muscles on the side of your body. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '/static/exercises/images/1342-rTbyBYV.jpg', '/static/exercises/gifs/1342-rTbyBYV.gif', '© Gym visual — https://gymvisual.com/', '901673'),
('101382', '健身球靠墙提踵', '腘绳肌', '哑铃', '未分级', '背靠墙站立，将健身球放在下背部和墙壁之间。双脚分开与肩同宽，脚趾指向前方。每只手握住一个哑铃，双臂伸向身体两侧。将脚跟抬离地面，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1382', 'exercise ball on the wall calf raise', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall. Position your feet shoulder-width apart, with your toes pointing forward. Hold a dumbbell in each hand, with your arms extended by your sides. Raise your heels off the ground, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1382-xo6sENf.jpg', '/static/exercises/gifs/1382-xo6sENf.gif', '© Gym visual — https://gymvisual.com/', '976'),
('103241', '健身球靠墙提踵网球球之间双踝', '腘绳肌', '哑铃', '未分级', '面向墙壁站立，双脚分开与肩同宽。在墙壁和下背部之间放置一个健身球。每只手握住一个哑铃，双臂伸向身体两侧。将网球放在脚踝之间。将脚后跟抬离地面，将身体抬起到脚趾上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3241', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'lower legs', '小腿', '70', 'dumbbell', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Stand facing a wall with your feet shoulder-width apart. Place an exercise ball between the wall and your lower back. Hold a dumbbell in each hand, with your arms extended by your sides. Place a tennis ball between your ankles. Raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3241-FY3UdNT.jpg', '/static/exercises/gifs/3241-FY3UdNT.gif', '© Gym visual — https://gymvisual.com/', '985'),
('103240', '健身球靠墙提踵网球球之间双膝', '股四头肌', '哑铃', '未分级', '背靠墙站立，将健身球放在下背部和墙壁之间。将双脚分开与肩同宽，并稍微位于您的前方。每只手握住一个哑铃，双臂伸向身体两侧。将网球放在膝盖之间。将脚后跟抬离地面，将身体抬起到脚趾上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3240', 'exercise ball on the wall calf raise (tennis ball between knees)', 'lower legs', '小腿', '70', 'dumbbell', 'quadriceps', 'calves', '小腿肌群', '["股四头肌","腘绳肌"]', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall. Position your feet shoulder-width apart and slightly in front of you. Hold a dumbbell in each hand, with your arms extended by your sides. Place a tennis ball between your knees. Raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3240-j74M6Zn.jpg', '/static/exercises/gifs/3240-j74M6Zn.gif', '© Gym visual — https://gymvisual.com/', '986'),
('101416', '健身球单腿俯卧下部身体旋转', '腘绳肌', '瑞士球', '未分级', '面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。将双手放在身前的地面上以获得支撑。调动你的臀肌和核心肌肉来稳定你的身体。慢慢地将一条腿抬离地面，保持笔直并与地板平行。向外旋转腿部，远离身体，同时保持臀部和上半身稳定。旋转结束时暂停片刻，然后慢慢地将腿放回起始位置。用另一条腿重复旋转。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '1416', 'exercise ball one leg prone lower body rotation', 'upper legs', '大腿', '40', 'stability ball', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","核心肌群"]', 'Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you. Place your hands on the ground in front of you for support. Engage your glutes and core muscles to stabilize your body. Slowly lift one leg off the ground, keeping it straight and parallel to the floor. Rotate your leg outward, away from your body, while keeping your hips and upper body stable. Pause for a moment at the end of the rotation, then slowly return your leg to the starting position. Repeat the rotation with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/1416-M72BExt.jpg', '/static/exercises/gifs/1416-M72BExt.gif', '© Gym visual — https://gymvisual.com/', '901681'),
('101417', '健身球单腿对角踢腿腘绳肌弯举', '腘绳肌', '瑞士球', '未分级', '首先仰卧，双腿伸展，脚跟放在稳定球上。将手臂放在身体两侧以保持稳定。调动臀肌和核心肌肉，将臀部抬离地面，从肩膀到脚后跟形成一条直线。弯曲右膝并将其靠近胸部，保持左腿伸展，脚部弯曲。将右腿斜踢过身体，完全伸展并拉动腿筋。慢慢地将右腿返回到起始位置，保持控制和稳定性。用左腿重复该动作，交替进行所需的重复次数。', 'exercise-dataset', '1417', 'exercise ball one legged diagonal kick hamstring curl', 'upper legs', '大腿', '40', 'stability ball', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","小腿肌群"]', 'Start by lying on your back with your legs extended and your heels resting on top of the stability ball. Place your arms by your sides for stability. Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels. Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed. Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings. Slowly return your right leg to the starting position, maintaining control and stability. Repeat the movement with your left leg, alternating sides for the desired number of repetitions.', '/static/exercises/images/1417-GOJKFfO.jpg', '/static/exercises/gifs/1417-GOJKFfO.gif', '© Gym visual — https://gymvisual.com/', '901682'),
('101296', '健身球折刀式俯卧撑', '肩部', '瑞士球', '未分级', '从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。收紧核心肌群，将臀部抬向天花板，将球滚向双手。保持双腿伸直，身体呈屈体姿势，形成倒V字形。弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。用手推动并伸展双臂以返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1296', 'exercise ball pike push up', 'chest', '胸部', '10', 'stability ball', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌","核心肌群"]', 'Start in a push-up position with your hands on the floor and your shins resting on the stability ball. Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands. Keep your legs straight and your body in a pike position, forming an inverted V shape. Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands. Push through your hands and extend your arms to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1296-sVvXT5J.jpg', '/static/exercises/gifs/1296-sVvXT5J.gif', '© Gym visual — https://gymvisual.com/', '901677'),
('101343', '健身球俯卧举腿', '腹肌', '瑞士球', '未分级', '面朝下躺在垫子上，双腿伸展，脚趾放在稳定球上。将双手放在地上，与肩同宽，锻炼核心肌肉。保持双腿伸直，慢慢将它们抬离地面，用下背部和臀部将它们尽可能抬高。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1343', 'exercise ball prone leg raise', 'back', '背部', '20', 'stability ball', 'abdominals', 'spine', '竖脊肌', '["腹肌","臀肌"]', 'Lie face down on a mat with your legs extended and your toes resting on top of the stability ball. Place your hands on the ground, shoulder-width apart, and engage your core muscles. Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1343-lCKm4Rs.jpg', '/static/exercises/gifs/1343-lCKm4Rs.gif', '© Gym visual — https://gymvisual.com/', '901678'),
('101560', '健身球坐姿腘绳肌拉伸', '臀肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。慢慢地向前滚动球，双脚向外走，直到上背部靠在球上，双腿在身前伸直。将双手放在臀部上以获得支撑。启动你的核心，慢慢地将上半身降低到地面，保持背部挺直，胸部抬起。当您感觉到腿筋拉伸时停止，并保持该姿势 20-30 秒。通过推动脚后跟并使用腿筋将自己拉回来，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1560', 'exercise ball seated hamstring stretch', 'upper legs', '大腿', '40', 'stability ball', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","下背部"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you. Place your hands on your hips for support. Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted. Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds. Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up. Repeat for the desired number of repetitions.', '/static/exercises/images/1560-yRYyfdA.jpg', '/static/exercises/gifs/1560-yRYyfdA.gif', '© Gym visual — https://gymvisual.com/', '901679'),
('101745', '健身球坐姿肱三头肌拉伸', '肩部', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。一只手握住哑铃，将手臂伸直至头顶上方。弯曲肘部，将哑铃放在脑后，保持上臂靠近耳朵。保持伸展几秒钟，然后回到起始位置。用另一只手臂重复上述步骤。', 'exercise-dataset', '1745', 'exercise ball seated triceps stretch', 'upper arms', '上臂', '50', 'stability ball', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand and extend your arm straight up above your head. Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear. Hold the stretch for a few seconds, then return to the starting position. Repeat with the other arm.', '/static/exercises/images/1745-7ePTw4B.jpg', '/static/exercises/gifs/1745-7ePTw4B.gif', '© Gym visual — https://gymvisual.com/', '901680'),
('101746', '健身球仰卧肱三头肌臂屈伸', '肩部', '哑铃', '未分级', '坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。双手握住哑铃，双臂伸直向天花板方向伸展。慢慢地将哑铃放到脑后，保持肘部靠近耳朵。暂停片刻，然后将哑铃举回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1746', 'exercise ball supine triceps extension', 'upper arms', '上臂', '50', 'dumbbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell with both hands and extend your arms straight up towards the ceiling. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears. Pause for a moment, then raise the dumbbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1746-Gm2Uv1z.jpg', '/static/exercises/gifs/1746-Gm2Uv1z.gif', '© Gym visual — https://gymvisual.com/', '400981'),
('101747', 'EZ杠杆法式推举健身球', '肩部', 'EZ杠', '未分级', '坐在健身球上，正手握住 EZ 杠铃。向上伸展双臂，保持肘部靠近头部。弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1747', 'ez bar french press on exercise ball', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on an exercise ball and hold an EZ barbell with an overhand grip. Extend your arms straight up, keeping your elbows close to your head. Slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1747-CFN9P8G.jpg', '/static/exercises/gifs/1747-CFN9P8G.gif', '© Gym visual — https://gymvisual.com/', '901686'),
('103010', 'EZ杠杆仰卧屈曲双臂上拉', '肱三头肌', 'EZ杠', '未分级', '平躺在长凳上，头放在一端，双脚放在地板上。旋前握住 EZ 杠铃（手掌背向您），双手与肩同宽。将手臂伸直至胸部上方，保持肘部轻微弯曲。以弧线动作将杠铃降低到头后，保持肘部轻微弯曲。暂停片刻，然后通过反向弧线运动将杠铃返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3010', 'ez bar lying bent arms pullover', 'back', '背部', '20', 'ez barbell', 'triceps', 'lats', '背阔肌', '["肱三头肌","胸肌"]', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart. Extend your arms straight above your chest, keeping a slight bend in your elbows. Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows. Pause for a moment, then return the barbell to the starting position by reversing the arc motion. Repeat for the desired number of repetitions.', '/static/exercises/images/3010-nDK1HJ0.jpg', '/static/exercises/gifs/3010-nDK1HJ0.gif', '© Gym visual — https://gymvisual.com/', '901685'),
('101748', 'EZ杠杆仰卧窄握肱三头肌臂屈伸颈后头后', '肩部', 'EZ杠', '未分级', '平躺在长凳上，双脚平放在地上，头放在长凳的末端。紧紧握住 ez 杠铃，手掌朝上，将手臂伸直至胸部上方。保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1748', 'ez bar lying close grip triceps extension behind head', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1748-6CKUx7o.jpg', '/static/exercises/gifs/1748-6CKUx7o.gif', '© Gym visual — https://gymvisual.com/', '401692'),
('101344', 'EZ杠杆反向握俯身划船', '肱二头肌', 'EZ杠', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。反手握住 ez 杠铃，手掌朝上，双手与肩同宽。臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1344', 'ez bar reverse grip bent over row', 'back', '背部', '20', 'ez barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor. Pull the ez barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the ez barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1344-G8dXpNG.jpg', '/static/exercises/gifs/1344-G8dXpNG.gif', '© Gym visual — https://gymvisual.com/', '161689'),
('101682', 'EZ杠杆坐姿窄距握集中弯举', '前臂', 'EZ杠', '未分级', '坐在长凳上，双脚平放在地面上，反手握住 EZ 杠铃。将肘部放在大腿内侧、膝盖上方。将杠铃向上弯向肩膀，同时保持上臂静止。在动作的最高点挤压二头肌，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1682', 'ez bar seated close grip concentration curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip. Rest your elbow on the inside of your thigh, just above the knee. Curl the barbell up towards your shoulder while keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1682-Dsfz0Id.jpg', '/static/exercises/gifs/1682-Dsfz0Id.gif', '© Gym visual — https://gymvisual.com/', '81690'),
('101749', 'EZ杠杆站姿法式推举', '肩部', 'EZ杠', '未分级', '双脚分开与肩同宽站立，正手握住杠铃。将杠铃举过头顶，充分伸展双臂。保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1749', 'ez bar standing french press', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip. Raise the barbell above your head, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1749-1cTf2Ux.jpg', '/static/exercises/gifs/1749-1cTf2Ux.gif', '© Gym visual — https://gymvisual.com/', '901687'),
('100445', 'EZ杠杠铃抗重力推举', '肱三头肌', 'EZ杠', '未分级', '首先，双脚分开与肩同宽站立，并用正手握住杠铃。将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。将杠铃推过头顶，充分伸展双臂。将杠铃降低回肩部高度，然后重复所需的重复次数。', 'exercise-dataset', '0445', 'ez barbell anti gravity press', 'shoulders', '肩部', '30', 'ez barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip. Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', '/static/exercises/images/0445-fprd84i.jpg', '/static/exercises/gifs/0445-fprd84i.gif', '© Gym visual — https://gymvisual.com/', '901688'),
('101627', 'EZ杠杠铃窄距握牧师凳弯举', '前臂', 'EZ杠', '未分级', '坐在牧师弯举凳上，将上臂放在垫子上，反手握住 ez 杠铃。将三头肌放在垫子上，充分伸展手臂，保持背部挺直。慢慢地将杠铃向肩膀弯曲，收缩二头肌。在顶部暂停片刻，挤压你的二头肌。将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1627', 'ez barbell close grip preacher curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip. Rest your triceps on the pad and fully extend your arms, keeping your back straight. Slowly curl the barbell towards your shoulders, contracting your biceps. Pause for a moment at the top, squeezing your biceps. Lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1627-hacCyUv.jpg', '/static/exercises/gifs/1627-hacCyUv.gif', '© Gym visual — https://gymvisual.com/', '81691'),
('100446', 'EZ杠杠铃窄距握弯举', '前臂', 'EZ杠', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，双手分开与肩同宽。在整个运动过程中，保持肘部靠近躯干，上臂保持静止。将杠铃向上弯向肩膀，收缩二头肌。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0446', 'ez barbell close-grip curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Curl the barbell up towards your shoulders, contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0446-V4ryaZa.jpg', '/static/exercises/gifs/0446-V4ryaZa.gif', '© Gym visual — https://gymvisual.com/', '81688'),
('100447', 'EZ杠杠铃弯举', '前臂', 'EZ杠', '未分级', '站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。在整个运动过程中，保持肘部靠近躯干，上臂保持静止。当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0447', 'ez barbell curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the barbell up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0447-6TG6x2w.jpg', '/static/exercises/gifs/0447-6TG6x2w.gif', '© Gym visual — https://gymvisual.com/', '81687'),
('100448', 'EZ杠杠铃下斜窄距握面部推举', '胸肌', 'EZ杠', '未分级', '躺在倾斜的长凳上，头低于脚。紧紧抓住 ez 杠铃，手掌相对。将手臂伸直至胸部上方，保持肘部靠近身体。弯曲肘部，将杠铃降低到前额。暂停片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0448', 'ez barbell decline close grip face press', 'upper arms', '上臂', '50', 'ez barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie on a decline bench with your head lower than your feet. Grasp the ez barbell with a close grip, palms facing each other. Extend your arms straight up above your chest, keeping your elbows close to your body. Lower the barbell towards your forehead by bending your elbows. Pause for a moment, then press the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0448-DgZQ11d.jpg', '/static/exercises/gifs/0448-DgZQ11d.gif', '© Gym visual — https://gymvisual.com/', '901696'),
('102186', 'EZ杠杠铃下斜肱三头肌臂屈伸', '肩部', 'EZ杠', '未分级', '躺在倾斜的长凳上，头低于脚，双脚固定。正手握住 ez 杠铃，双手与肩同宽。充分伸展双臂，保持肘部靠近头部。将杠铃慢慢降低到前额，弯曲肘部。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2186', 'ez barbell decline triceps extension', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Lie on a decline bench with your head lower than your feet and your feet secured. Hold the ez barbell with an overhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your head. Lower the barbell slowly towards your forehead, bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2186-CQHoDm0.jpg', '/static/exercises/gifs/2186-CQHoDm0.gif', '© Gym visual — https://gymvisual.com/', '401693'),
('100449', 'EZ杠杠铃上斜肱三头肌臂屈伸', '肩部', 'EZ杠', '未分级', '设置一个 45 度角的上斜凳。坐在长凳上，背部靠在垫子上，正手握住 ez 杠铃。将手臂完全伸过头顶，保持肘部靠近头部。弯曲肘部，将杠铃降低到头后，保持上臂静止。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0449', 'ez barbell incline triceps extension', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip. Extend your arms fully overhead, keeping your elbows close to your head. Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0449-KyLtiLT.jpg', '/static/exercises/gifs/0449-KyLtiLT.gif', '© Gym visual — https://gymvisual.com/', '401694'),
('100450', 'EZ杠杠铃JM卧推', '胸肌', 'EZ杠', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。正手握住杠铃，握距略宽于肩宽。将杠铃降低到胸部，保持肘部靠近身体。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0450', 'ez barbell jm bench press', 'upper arms', '上臂', '50', 'ez barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0450-hnOYgH3.jpg', '/static/exercises/gifs/0450-hnOYgH3.gif', '© Gym visual — https://gymvisual.com/', '901695'),
('100451', 'EZ杠杠铃反向握弯举', '前臂', 'EZ杠', '未分级', '站直，双脚分开与肩同宽，反手握住 ez 杠铃。在整个练习过程中，保持肘部靠近躯干，上臂保持静止。通过收缩二头肌将杠铃向上卷曲，同时呼气。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气时慢慢开始将杠铃拉回起始位置。重复所需的重复次数。', 'exercise-dataset', '0451', 'ez barbell reverse grip curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip. Keep your elbows close to your torso and your upper arms stationary throughout the exercise. Curl the barbell upwards by contracting your biceps, while exhaling. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Slowly begin to bring the barbell back to the starting position as you inhale. Repeat for the desired number of repetitions.', '/static/exercises/images/0451-Y5X65IB.jpg', '/static/exercises/gifs/0451-Y5X65IB.gif', '© Gym visual — https://gymvisual.com/', '81696'),
('100452', 'EZ杠杠铃反向握牧师凳弯举', '前臂', 'EZ杠', '未分级', '坐在牧师凳上，胸部靠在垫子上，双脚平放在地板上。反手抓住 ez 杠铃，双手与肩同宽。将上臂放在垫子上，让前臂下垂。保持上臂静止，呼气并将杠铃向上弯向肩膀。在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0452', 'ez barbell reverse grip preacher curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a preacher bench with your chest against the pad and your feet flat on the floor. Grasp the ez barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms on the pad, allowing your forearms to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0452-vBNyir7.jpg', '/static/exercises/gifs/0452-vBNyir7.gif', '© Gym visual — https://gymvisual.com/', '81699'),
('101458', 'EZ杠杠铃坐姿弯举', '前臂', 'EZ杠', '未分级', '坐在长凳上，双脚平放在地上，背部挺直。反手握住 ez 杠铃，手掌朝上，双手与肩同宽。将上臂放在大腿上，让 ez 杠铃垂在您面前。保持上臂静止，呼气并将杠铃向上卷曲至肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并缓慢地将 ez 杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1458', 'ez barbell seated curls', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a bench with your feet flat on the ground and your back straight. Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you. Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the ez barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1458-jtFKbt5.jpg', '/static/exercises/gifs/1458-jtFKbt5.gif', '© Gym visual — https://gymvisual.com/', '81696'),
('100453', 'EZ杠杠铃坐姿肱三头肌臂屈伸', '肩部', 'EZ杠', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。正手握住 ez 杠铃，双手与肩同宽。将杠铃举过头顶，充分伸展双臂。保持上臂静止，弯曲肘部将杠铃降低到脑后。暂停片刻，然后伸展双臂将杠铃举回起始位置。重复所需的重复次数。', 'exercise-dataset', '0453', 'ez barbell seated triceps extension', 'upper arms', '上臂', '50', 'ez barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold the ez barbell with an overhand grip, hands shoulder-width apart. Raise the barbell overhead, fully extending your arms. Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows. Pause for a moment, then raise the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0453-iaapw0g.jpg', '/static/exercises/gifs/0453-iaapw0g.gif', '© Gym visual — https://gymvisual.com/', '401699'),
('100454', 'EZ杠杠铃蜘蛛式弯举', '前臂', 'EZ杠', '未分级', '双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。将上臂放在牧师凳或稳定球上，让肘部下垂。保持上臂静止，呼气并将杠铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0454', 'ez barbell spider curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0454-Ye5Qxb0.jpg', '/static/exercises/gifs/0454-Ye5Qxb0.gif', '© Gym visual — https://gymvisual.com/', '81698'),
('101628', 'EZ杠杠铃蜘蛛式弯举', '前臂', 'EZ杠', '未分级', '双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。将上臂放在牧师凳或稳定球上，让肘部下垂。保持上臂静止，呼气并将杠铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1628', 'ez barbell spider curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1628-2kattbR.jpg', '/static/exercises/gifs/1628-2kattbR.gif', '© Gym visual — https://gymvisual.com/', '81699'),
('102404', 'EZ杠杆肱二头肌弯举臂弯举托板', '前臂', 'EZ杠', '未分级', '站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。将上臂靠在手臂冲击波上，在整个练习过程中保持静止。保持肘部靠近身体，呼气并将杠铃向上弯向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气，慢慢将杠铃放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '2404', 'ez-bar biceps curl (with arm blaster)', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping them stationary throughout the exercise. Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2404-tJ5nYqo.jpg', '/static/exercises/gifs/2404-tJ5nYqo.gif', '© Gym visual — https://gymvisual.com/', '1704'),
('102432', 'EZ杠杆窄握卧推', '胸肌', 'EZ杠', '未分级', '平躺在长凳上，双脚平放在地上，背部紧贴长凳。紧握杠铃，双手与肩同宽，掌心向前。将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。慢慢地将杠铃降低到胸部，保持肘部靠近身体。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '2432', 'ez-bar close-grip bench press', 'upper arms', '上臂', '50', 'ez barbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2432-da4cXST.jpg', '/static/exercises/gifs/2432-da4cXST.gif', '© Gym visual — https://gymvisual.com/', '901701'),
('102741', 'EZ杠杠铃站姿宽距握肱二头肌弯举', '前臂', 'EZ杠', '未分级', '站直，双脚分开与肩同宽，反手握住杠铃，双手分开比肩宽。在整个运动过程中，保持肘部靠近躯干，上臂保持静止。收缩二头肌，将杠铃向上弯向肩膀。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2741', 'ez-barbell standing wide grip biceps curl', 'upper arms', '上臂', '50', 'ez barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Curl the barbell up towards your shoulders by contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2741-OVTZ65k.jpg', '/static/exercises/gifs/2741-OVTZ65k.gif', '© Gym visual — https://gymvisual.com/', '1706'),
('102133', '农夫行走', '小腿肌群', '哑铃', '未分级', '站直，双手各握一个哑铃，手掌朝向身体两侧。保持背部挺直，肩膀向后。向前迈出小步，控制住，保持直立姿势。继续步行所需的距离或时间。最后，停止行走并小心地将哑铃降低到身体两侧。', 'exercise-dataset', '2133', 'farmers walk', 'upper legs', '大腿', '40', 'dumbbell', 'calves', 'quads', '股四头肌', '["小腿肌群","前臂","核心肌群"]', 'Stand up straight with a dumbbell in each hand, palms facing your sides. Keep your back straight and your shoulders back. Take small, controlled steps forward, maintaining an upright posture. Continue walking for the desired distance or time. To finish, stop walking and carefully lower the dumbbells to your sides.', '/static/exercises/images/2133-qPEzJjA.jpg', '/static/exercises/gifs/2133-qPEzJjA.gif', '© Gym visual — https://gymvisual.com/', '900999'),
('100455', '手指弯举', '腕屈肌', '杠铃', '未分级', '坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。将前臂放在大腿上，让手腕悬在边缘。慢慢地将手指向手掌弯曲，紧紧挤压杠铃。保持收缩一会儿，然后慢慢松开手指回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0455', 'finger curls', 'lower arms', '前臂', '80', 'barbell', 'wrist flexors', 'forearms', '前臂肌群', '["腕屈肌","握MUSCLES"]', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your fingers towards your palms, squeezing the barbell tightly. Hold the contraction for a moment, then slowly release your fingers back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0455-awG04cF.jpg', '/static/exercises/gifs/0455-awG04cF.gif', '© Gym visual — https://gymvisual.com/', '900900'),
('103303', '旗式', '腹斜肌', '自重', '未分级', '首先，双手握住一根垂直杆，手掌相对，双臂完全伸展。启动你的核心并将双腿抬离地面，保持伸直。利用核心和上半身的力量，抬起双腿，直到它们与地面平行。尽可能长时间地保持这个姿势，保持身体线条笔直。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3303', 'flag', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended. Engage your core and lift your legs off the ground, keeping them straight. Using your core and upper body strength, raise your legs until they are parallel to the ground. Hold this position for as long as you can, maintaining a straight body line. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3303-pQ0Mx1Z.jpg', '/static/exercises/gifs/3303-pQ0Mx1Z.gif', '© Gym visual — https://gymvisual.com/', '900799'),
('100456', '屈曲腿坐向上屈曲膝', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。同时，将双腿抬离地面，弯曲膝盖并将其拉向胸部。在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0456', 'flexion leg sit up (bent knee)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0456-AR0ig3o.jpg', '/static/exercises/gifs/0456-AR0ig3o.gif', '© Gym visual — https://gymvisual.com/', '900810'),
('100457', '屈曲腿坐向上直臂', '髋屈肌', '自重', '未分级', '平躺，双腿伸直，双臂伸直至头顶上方。收紧腹肌，将上半身抬离地面，同时将双腿抬向胸部。抬起上半身和腿部时，将双手伸向脚趾。在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0457', 'flexion leg sit up (straight arm)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","股四头肌"]', 'Lie flat on your back with your legs extended and arms straight above your head. Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest. Reach your hands towards your toes as you lift your upper body and legs. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0457-KZn52RC.jpg', '/static/exercises/gifs/0457-KZn52RC.gif', '© Gym visual — https://gymvisual.com/', '900811'),
('100458', '地板飞鸟杠铃', '三角肌', '杠铃', '未分级', '仰卧在地板上，膝盖弯曲，双脚平放在地面上。正手握住杠铃，双臂伸直越过胸部。慢慢地将杠铃向两侧放低，保持肘部轻微弯曲。降低杠铃，直到手臂与地板平行，感觉胸部有拉伸感。暂停片刻，然后挤压胸部肌肉，使杠铃回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0458', 'floor fly (with barbell)', 'chest', '胸部', '10', 'barbell', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold a barbell with an overhand grip, arms extended straight up over your chest. Slowly lower the barbell out to the sides, keeping a slight bend in your elbows. Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0458-neonEDL.jpg', '/static/exercises/gifs/0458-neonEDL.gif', '© Gym visual — https://gymvisual.com/', '900908'),
('100459', '交替摆腿踢腿', '髋屈肌', '自重', '未分级', '平躺，双腿伸展，双手放在身体两侧。收紧核心肌群并将双腿抬离地面约 6 英寸。保持双腿伸直，交替将一条腿抬得比另一条腿稍高。继续这个颤动动作达到所需的重复次数。', 'exercise-dataset', '0459', 'flutter kicks', 'upper legs', '大腿', '40', 'body weight', 'hip flexors', 'glutes', '臀肌', '["髋屈肌","下部ABS"]', 'Lie flat on your back with your legs extended and your hands by your sides. Engage your core and lift your legs off the ground about 6 inches. Keeping your legs straight, alternate lifting one leg slightly higher than the other. Continue this fluttering motion for the desired number of repetitions.', '/static/exercises/images/0459-UVo2Qs2.jpg', '/static/exercises/gifs/0459-UVo2Qs2.gif', '© Gym visual — https://gymvisual.com/', '900805'),
('101472', '向前跳跃', '小腿肌群', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将身体降低至蹲姿。向后摆动手臂以获得动力。爆发性地向前跳跃，伸展臀部、膝盖和脚踝。脚掌轻轻落地，然后立即进入下一个跳跃。重复所需的重复次数。', 'exercise-dataset', '1472', 'forward jump', 'upper legs', '大腿', '40', 'body weight', 'calves', 'quads', '股四头肌', '["小腿肌群","腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Swing your arms back for momentum. Jump forward explosively, extending your hips, knees, and ankles. Land softly on the balls of your feet and immediately go into the next jump. Repeat for the desired number of repetitions.', '/static/exercises/images/1472-uZKq7lo.jpg', '/static/exercises/gifs/1472-uZKq7lo.gif', '© Gym visual — https://gymvisual.com/', '900806'),
('103470', '向前弓步（男）', '股四头肌', '自重', '未分级', '站立，双脚分开与臀部同宽，双手放在臀部。右脚向前迈出一大步，将身体降低到弓步位置。将右膝盖弯曲约 90 度，保持膝盖与脚踝对齐。用右脚推出并返回到起始位置。用左腿重复上述动作，交替进行所需的重复次数。', 'exercise-dataset', '3470', 'forward lunge (male)', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet hip-width apart and hands on your hips. Take a big step forward with your right foot, lowering your body into a lunge position. Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle. Push off with your right foot and return to the starting position. Repeat with your left leg, alternating sides for the desired number of repetitions.', '/static/exercises/images/3470-kMzUs9Y.jpg', '/static/exercises/gifs/3470-kMzUs9Y.gif', '© Gym visual — https://gymvisual.com/', '320809'),
('103194', '弗兰肯斯坦式深蹲', '股四头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，双臂伸直将杠铃举在身体前方。保持背部挺直，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。继续降低，直到大腿与地面平行，或者尽可能低。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3194', 'frankenstein squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms. Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3194-bdWcbaU.jpg', '/static/exercises/gifs/3194-bdWcbaU.gif', '© Gym visual — https://gymvisual.com/', '908'),
('102429', '青蛙式卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将上半身抬离地面，向前卷曲直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2429', 'frog crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2429-FFRP97T.jpg', '/static/exercises/gifs/2429-FFRP97T.gif', '© Gym visual — https://gymvisual.com/', '80809'),
('103301', '青蛙式水平支撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手与肩同宽，双脚并拢。弯曲肘部，将身体放低至地面，保持背部挺直。当你降低身体时，将双脚抬离地面，并将膝盖靠近胸部。保持这个姿势几秒钟，然后向后伸展双腿，并将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3301', 'frog planche', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌","肱三头肌"]', 'Start in a push-up position with your hands shoulder-width apart and your feet together. Bend your elbows and lower your body towards the ground, keeping your back straight. As you lower your body, lift your feet off the ground and bring your knees towards your chest. Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3301-rQhGcin.jpg', '/static/exercises/gifs/3301-rQhGcin.gif', '© Gym visual — https://gymvisual.com/', '900810'),
('103296', '前侧器械', '背阔肌', '自重', '未分级', '首先，用正手握法悬挂在引体向上杆上，双手与肩同宽。启动你的核心并将肩胛骨向下拉和向后拉。弯曲膝盖并将其向胸部靠拢。同时，抬起双腿并将其伸直在您面前，保持身体与地面平行。尽可能长时间地保持此位置，以达到完全前杆位置。要释放，请慢慢降低双腿并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3296', 'front lever', 'waist', '腰腹', '60', 'body weight', 'lats', 'abs', '腹肌', '["背阔肌","肩部","前臂"]', 'Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest. Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground. Hold this position for as long as you can, aiming for a full front lever position. To release, slowly lower your legs back down and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3296-PkCN2lv.jpg', '/static/exercises/gifs/3296-PkCN2lv.gif', '© Gym visual — https://gymvisual.com/', '900811'),
('103295', '前侧器械重复', '核心肌群', '自重', '未分级', '正手握住引体向上杆，手掌背向自己。启动你的核心并将肩胛骨向下拉和向后拉。保持身体挺直，抬起双腿直至与地面平行。尽可能长时间地保持这个姿势，目标是 10-20 秒。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3295', 'front lever reps', 'back', '背部', '20', 'body weight', 'core', 'upper back', '上背部', '["核心肌群","肩部"]', 'Hang from a pull-up bar with an overhand grip, palms facing away from you. Engage your core and pull your shoulder blades down and back. Keeping your body straight, lift your legs up until they are parallel to the ground. Hold this position for as long as you can, aiming for 10-20 seconds. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3295-hbY9wqG.jpg', '/static/exercises/gifs/3295-hbY9wqG.gif', '© Gym visual — https://gymvisual.com/', '900814'),
('100464', '前侧平板支撑转体', '腹斜肌', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。调动你的核心和臀部以保持稳定的位置。将躯干向右旋转，抬起右臂并向天花板延伸。扭转时保持臀部和腿部稳定。保持片刻，然后回到起始位置。在左侧重复扭转。继续交替进行所需的重复次数。', 'exercise-dataset', '0464', 'front plank with twist', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe. Engage your core and glutes to maintain a stable position. Rotate your torso to the right, lifting your right arm and extending it towards the ceiling. Keep your hips and legs stable as you twist. Hold for a moment, then return to the starting position. Repeat the twist on the left side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0464-CosupLu.jpg', '/static/exercises/gifs/0464-CosupLu.gif', '© Gym visual — https://gymvisual.com/', '817'),
('103315', '全程马耳他式', '肩部', '自重', '未分级', '首先站立，双脚分开与肩同宽，双臂伸直至两侧。慢慢向前倾斜，保持手臂伸直，直到上半身与地面平行。启动你的核心并保持这个姿势几秒钟。通过双脚推动并站起来，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3315', 'full maltese', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌"]', 'Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides. Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground. Engage your core and hold this position for a few seconds. Return to the starting position by pushing through your feet and standing back up. Repeat for the desired number of repetitions.', '/static/exercises/images/3315-YRaCa5Y.jpg', '/static/exercises/gifs/3315-YRaCa5Y.gif', '© Gym visual — https://gymvisual.com/', '900814'),
('103299', '全程水平支撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手与肩同宽，手指指向前方。启动你的核心并缓慢地将你的重心向前移动，将你的脚抬离地面。继续向前移动体重，直到身体与地面平行，并用双手保持平衡。尽可能长时间地保持这个姿势，保持身体线条笔直。慢慢地将双脚放回地面，然后回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3299', 'full planche', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌","肱三头肌"]', 'Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward. Engage your core and slowly shift your weight forward, lifting your feet off the ground. Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands. Hold this position for as long as you can, maintaining a straight body line. Slowly lower your feet back to the ground and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3299-YZ4961r.jpg', '/static/exercises/gifs/3299-YZ4961r.gif', '© Gym visual — https://gymvisual.com/', '900815'),
('103327', '全程水平支撑俯卧撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽。收紧核心肌群，将身体放低至地面，保持肘部靠近身体两侧。当你降低身体高度时，身体向前倾斜，双脚离开地面，用双手保持平衡。继续降低身体，直到胸部略高于地面。用手推动并伸展双臂，将身体抬回到起始位置。在整个运动过程中，从头部到脚后跟保持一条直线。重复所需的重复次数。', 'exercise-dataset', '3327', 'full planche push-up', 'chest', '胸部', '10', 'body weight', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌","核心肌群"]', 'Start in a push-up position with your hands placed slightly wider than shoulder-width apart. Engage your core and lower your body down towards the ground, keeping your elbows close to your sides. As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands. Continue to lower your body until your chest is just above the ground. Push through your hands and extend your arms to lift your body back up to the starting position. Maintain a straight line from your head to your heels throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/3327-gw9PqGk.jpg', '/static/exercises/gifs/3327-gw9PqGk.gif', '© Gym visual — https://gymvisual.com/', '80818'),
('100466', '吉隆达胸骨引体', '肱二头肌', '自重', '未分级', '面向高杠站立，双脚分开与肩同宽。向上伸手，正手握住杠铃，握距略宽于肩宽。悬挂在杠上，双臂完全伸展，身体伸直。用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。在最高点暂停片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0466', 'gironda sternum chin', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Stand facing a high bar with your feet shoulder-width apart. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0466-IL0JUxR.jpg', '/static/exercises/gifs/0466-IL0JUxR.gif', '© Gym visual — https://gymvisual.com/', '900819'),
('103561', '臀桥原地踏步', '腘绳肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。在保持臀部抬起的同时，将一只脚抬离地面，并将膝盖靠近胸部。将脚放回地面，然后用另一条腿重复该动作。继续交替双腿进行行进动作，同时保持桥式姿势。重复所需的重复次数。', 'exercise-dataset', '3561', 'glute bridge march', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest. Lower your foot back to the ground and repeat the movement with the other leg. Continue alternating legs in a marching motion while maintaining the bridge position. Repeat for the desired number of repetitions.', '/static/exercises/images/3561-GibBPPg.jpg', '/static/exercises/gifs/3561-GibBPPg.gif', '© Gym visual — https://gymvisual.com/', '640820'),
('103523', '臀桥双双腿训练凳（男）', '腘绳肌', '自重', '未分级', '坐在长凳边缘，背靠着长凳，双脚平放在地上。将双手放在臀部旁边的长凳上以获得支撑。收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3523', 'glute bridge two legs on bench (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","核心肌群"]', 'Sit on the edge of a bench with your back against it and your feet flat on the ground. Place your hands on the bench beside your hips for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3523-aWedzZX.jpg', '/static/exercises/gifs/3523-aWedzZX.gif', '© Gym visual — https://gymvisual.com/', '640829'),
('103193', '臀腿挺身', '臀肌', '自重', '未分级', '调整臀肌提升机以适合您的身体。将自己面朝下放在机器上，固定脚踝。将双手放在胸前或交叉在胸前。调动腿筋和臀肌，将上半身抬向天花板。继续抬起，直到身体从头部到脚后跟成一条直线。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3193', 'glute-ham raise', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","下背部"]', 'Adjust the glute-ham raise machine to fit your body. Position yourself face down on the machine with your ankles secured. Place your hands on your chest or cross them over your chest. Engage your hamstrings and glutes to lift your upper body up towards the ceiling. Continue lifting until your body is in a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3193-Vvwjz6N.jpg', '/static/exercises/gifs/3193-Vvwjz6N.gif', '© Gym visual — https://gymvisual.com/', '900820'),
('100467', '大猩猩式引体', '前臂', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住引体向上杆，握距略宽于肩宽。悬挂在杠上，双臂完全伸展，手掌背向自己。收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0467', 'gorilla chin', 'waist', '腰腹', '60', 'body weight', 'forearms', 'abs', '腹肌', '["前臂","肱二头肌"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your palms facing away from you. Engage your core and pull your body up towards the bar, bringing your chin above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0467-bmwlYvD.jpg', '/static/exercises/gifs/0467-bmwlYvD.gif', '© Gym visual — https://gymvisual.com/', '900821'),
('100469', '腹股沟卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0469', 'groin crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","内侧THIGHS"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0469-mWppALS.jpg', '/static/exercises/gifs/0469-mWppALS.gif', '© Gym visual — https://gymvisual.com/', '80822'),
('101383', '哈克提踵', '腘绳肌', '雪橇机', '未分级', '将雪橇机调整至舒适的重量。站在雪橇机上，脚趾放在平台上，脚后跟悬空。握住手柄以保持稳定性。通过推动脚掌将脚后跟尽可能抬高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1383', 'hack calf raise', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the sled machine to a comfortable weight. Stand on the sled machine with your toes on the platform and your heels hanging off. Hold onto the handles for stability. Raise your heels as high as possible by pushing through the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1383-2ORFMoR.jpg', '/static/exercises/gifs/1383-2ORFMoR.gif', '© Gym visual — https://gymvisual.com/', '1725'),
('101384', '哈克单腿提踵', '腘绳肌', '雪橇机', '未分级', '将雪橇机调整到合适的重量。一脚站在雪橇机上，另一只脚离开地面。握住手柄以保持稳定性。尽可能高地抬高脚跟，用脚掌抬起身体。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数。换腿并重复练习。', 'exercise-dataset', '1384', 'hack one leg calf raise', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the sled machine to an appropriate weight. Stand on the sled machine with one foot, keeping the other foot off the ground. Hold onto the handles for stability. Raise your heel as high as possible, lifting your body up on the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions. Switch legs and repeat the exercise.', '/static/exercises/images/1384-AxFoqAD.jpg', '/static/exercises/gifs/1384-AxFoqAD.gif', '© Gym visual — https://gymvisual.com/', '1730'),
('103221', '半程膝屈膝（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并降低身体，就像坐回椅子上一样。保持挺胸，将体重放在脚后跟上。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3221', 'half knee bends (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body down as if you were sitting back into a chair. Keep your chest up and your weight in your heels. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3221-ia6kIIl.jpg', '/static/exercises/gifs/3221-ia6kIIl.gif', '© Gym visual — https://gymvisual.com/', '900829'),
('103202', '半程坐向上（男）', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3202', 'half sit-up (male)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3202-iQ241UP.jpg', '/static/exercises/gifs/3202-iQ241UP.gif', '© Gym visual — https://gymvisual.com/', '160828'),
('101511', '腘绳肌拉伸', '臀肌', '自重', '未分级', '双脚分开与肩同宽站立。右脚向前迈出一步，将重心转移到右腿上。保持背部挺直，臀部慢慢向前弯曲，双手伸向右脚。保持伸展动作 20-30 秒，然后回到起始位置。在另一侧重复。', 'exercise-dataset', '1511', 'hamstring stretch', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Stand with your feet shoulder-width apart. Step forward with your right foot and shift your weight onto your right leg. Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat on the other side.', '/static/exercises/images/1511-99rWm7w.jpg', '/static/exercises/gifs/1511-99rWm7w.gif', '© Gym visual — https://gymvisual.com/', '900827'),
('102139', '双手自行车', '肱三头肌', '上肢功率车', '未分级', '将座椅高度和车把位置调整至舒适的水平。坐在测力计上，背部挺直，双脚放在踏板上。双手抓住手柄，并将手臂呈 90 度角。开始用手踩踏板，以受控的动作推拉手柄。继续踩踏所需的持续时间或重复次数。', 'exercise-dataset', '2139', 'hands bike', 'chest', '胸部', '10', 'upper body ergometer', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and handlebar position to a comfortable level. Sit on the ergometer with your back straight and feet on the pedals. Grasp the handles with your hands and position your arms at a 90-degree angle. Start pedaling with your hands, pushing and pulling the handles in a controlled motion. Continue pedaling for the desired duration or number of repetitions.', '/static/exercises/images/2139-pAIWRGu.jpg', '/static/exercises/gifs/2139-pAIWRGu.gif', '© Gym visual — https://gymvisual.com/', '901728'),
('103218', '双手交握环绕脚尖触碰（男）', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双手合十放在胸前。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将双手向脚趾方向以打圈的方式降低，尽量伸得尽可能远，但不要用力。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3218', 'hands clasped circular toe touch (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and your hands clasped together in front of your chest. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your hands towards your toes in a circular motion, reaching as far as you can without straining. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3218-B5xca8s.jpg', '/static/exercises/gifs/3218-B5xca8s.gif', '© Gym visual — https://gymvisual.com/', '900837'),
('103215', '双手反向交握环绕脚尖触碰（男）', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂向两侧伸展。腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。双手向下伸，并在腿后将它们握在一起。慢慢地将双手举过头顶，做圆周运动，保持双腿伸直。继续圆周运动，直到双手触及脚趾。反转动作并将双手放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3215', 'hands reversed clasped circular toe touch (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and your arms extended to the sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down with your hands and clasp them together behind your legs. Slowly raise your hands up and over your head in a circular motion, keeping your legs straight. Continue the circular motion until your hands touch your toes. Reverse the motion and bring your hands back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3215-yq3GAJX.jpg', '/static/exercises/gifs/3215-yq3GAJX.gif', '© Gym visual — https://gymvisual.com/', '900840'),
('103302', '倒立', '肩部', '自重', '未分级', '找到一个有足够空间的空地来进行倒立。将双手放在地上，与肩同宽，手指指向前方。将双腿向上踢向墙壁，用核心和肩膀保持平衡。处于倒立位置后，用三头肌来支撑体重。只要能保持平衡，就保持倒立。下降时，慢慢将双腿放回地面。重复所需的重复次数。', 'exercise-dataset', '3302', 'handstand', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部","核心肌群"]', 'Find an open space with enough room to perform a handstand. Place your hands on the ground shoulder-width apart, fingers pointing forward. Kick your legs up towards the wall, using your core and shoulders to maintain balance. Once in a handstand position, engage your triceps to support your body weight. Hold the handstand for as long as you can maintain balance. To come down, slowly lower your legs back to the ground. Repeat for the desired number of repetitions.', '/static/exercises/images/3302-XooAdhl.jpg', '/static/exercises/gifs/3302-XooAdhl.gif', '© Gym visual — https://gymvisual.com/', '900829'),
('100471', '倒立俯卧撑', '肩部', '自重', '未分级', '找到一堵墙，背对墙，站在几英尺远的地方。将双手放在地面上，与肩同宽，然后将脚踢到墙上，形成倒立姿势。弯曲肘部，将头低向地面，保持身体呈一条直线。用手推动并伸展双臂以返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0471', 'handstand push-up', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌","核心肌群"]', 'Find a wall and face away from it, standing a few feet away. Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position. Bend your elbows and lower your head towards the ground, keeping your body in a straight line. Push through your hands and extend your arms to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0471-rQxwMxO.jpg', '/static/exercises/gifs/0471-rQxwMxO.gif', '© Gym visual — https://gymvisual.com/', '900832'),
('101764', '悬垂腿髋部上举', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。弯曲臀部和膝盖，收紧核心并抬起双腿，直到大腿与地面平行。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1764', 'hanging leg hip raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1764-VEcJRo2.jpg', '/static/exercises/gifs/1764-VEcJRo2.gif', '© Gym visual — https://gymvisual.com/', '900837'),
('100472', '悬垂举腿', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。启动你的核心并将双腿抬起到你面前，保持伸直。继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0472', 'hanging leg raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0472-I3tsCnC.jpg', '/static/exercises/gifs/0472-I3tsCnC.gif', '© Gym visual — https://gymvisual.com/', '240836'),
('101761', '悬垂腹斜肌举膝', '腹斜肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。收紧核心并将膝盖抬向胸部，同时将躯干扭转到一侧。在顶部暂停片刻，然后慢慢将双腿放回起始位置。在另一侧重复上述步骤，向相反方向扭转躯干。继续交替进行所需的重复次数。', 'exercise-dataset', '1761', 'hanging oblique knee raise', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat on the other side, twisting your torso in the opposite direction. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1761-BaE7O6U.jpg', '/static/exercises/gifs/1761-BaE7O6U.gif', '© Gym visual — https://gymvisual.com/', '320839'),
('100473', '悬垂折刀式', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。收紧核心肌群，将双腿向杠铃方向抬起，保持伸直。继续抬起身体，直到身体形成“V”形，双腿与地面平行。保持该姿势片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0473', 'hanging pike', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","肩部"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up towards the bar, keeping them straight. Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground. Hold the position for a moment, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0473-nuBF9MO.jpg', '/static/exercises/gifs/0473-nuBF9MO.gif', '© Gym visual — https://gymvisual.com/', '900836'),
('100474', '悬垂直腿髋部上举', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。启动你的核心并将双腿抬起到你面前，直到它们与地面平行。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0474', 'hanging straight leg hip raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0474-pj0X0tF.jpg', '/static/exercises/gifs/0474-pj0X0tF.gif', '© Gym visual — https://gymvisual.com/', '900843'),
('100475', '悬垂直举腿', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。启动你的核心并将双腿抬起到你面前，保持伸直。继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0475', 'hanging straight leg raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0475-4Ml7QFO.jpg', '/static/exercises/gifs/0475-4Ml7QFO.gif', '© Gym visual — https://gymvisual.com/', '240842'),
('100476', '悬垂直转体腿髋部上举', '腹斜肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，双腿伸直。启动你的核心并将双腿抬向胸部，保持伸直。一旦双腿与地面平行，将臀部向一侧扭转，将双腿移向一侧。暂停片刻，然后回到起始位置。重复这个动作，但这次将臀部扭向另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0476', 'hanging straight twisting leg hip raise', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your legs straight. Engage your core and lift your legs up towards your chest, keeping them straight. Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side. Pause for a moment, then return to the starting position. Repeat the movement, but this time twist your hips to the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0476-Q6bvyen.jpg', '/static/exercises/gifs/0476-Q6bvyen.gif', '© Gym visual — https://gymvisual.com/', '900847'),
('103636', '高位膝抵住靠墙', '股四头肌', '自重', '未分级', '面向墙壁站立，双脚分开与臀部同宽。将双手放在墙上以获得支撑。启动你的核心并将右膝抬向胸部，同时将左脚保持在地面上。快速换腿，将左膝抬向胸部，然后将右脚放低。继续交替双腿进行跑步动作，将膝盖尽可能抬高。在整个练习过程中保持快节奏并保持上半身稳定。重复所需的持续时间或重复次数。', 'exercise-dataset', '3636', 'high knee against wall', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Stand facing a wall with your feet hip-width apart. Place your hands on the wall for support. Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground. Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down. Continue alternating legs in a running motion, bringing your knees up as high as possible. Maintain a fast pace and keep your upper body stable throughout the exercise. Repeat for the desired duration or number of repetitions.', '/static/exercises/images/3636-ealLwvX.jpg', '/static/exercises/gifs/3636-ealLwvX.gif', '© Gym visual — https://gymvisual.com/', '900844'),
('100484', '髋部上举屈曲膝', '臀肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在身体两侧，掌心朝下。收紧核心肌群和臀肌，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0484', 'hip raise (bent knee)', 'waist', '腰腹', '60', 'body weight', 'glutes', 'abs', '腹肌', '["臀肌","腘绳肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0484-196HJGw.jpg', '/static/exercises/gifs/0484-196HJGw.gif', '© Gym visual — https://gymvisual.com/', '900845'),
('101418', '抱球基恩斯式胸部', '腘绳肌', '自重', '未分级', '首先站立，双脚分开与肩同宽。弯曲膝盖并将身体降低至蹲姿。当你蹲下时，将膝盖抬向胸部，并用手臂抱住它们。保持这个姿势一会儿，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1418', 'hug keens to chest', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Start by standing with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position. As you squat down, bring your knees up towards your chest and hug them with your arms. Hold this position for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1418-znP9SIh.jpg', '/static/exercises/gifs/1418-znP9SIh.gif', '© Gym visual — https://gymvisual.com/', '900846'),
('103234', '海特式哑铃飞鸟', '肩部', '哑铃', '未分级', '平躺在长凳上，双手各握一个哑铃，手掌相对。将手臂伸直越过胸部，肘部稍微弯曲。保持肘部轻微弯曲，以宽弧线将哑铃向两侧放低，直到感觉到胸部有拉伸感。暂停片刻，然后反转动作，将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3234', 'hyght dumbbell fly', 'chest', '胸部', '10', 'dumbbell', 'shoulders', 'pectorals', '胸肌', '["肩部"]', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, with a slight bend in your elbows. Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3234-P9ZRyLT.jpg', '/static/exercises/gifs/3234-P9ZRyLT.gif', '© Gym visual — https://gymvisual.com/', '901045'),
('100489', '超伸展', '臀肌', '自重', '未分级', '调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。双臂交叉放在胸前或将双手放在脑后。将上半身压向地面，同时保持背部挺直。在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。重复所需的重复次数。', 'exercise-dataset', '0489', 'hyperextension', 'back', '背部', '20', 'body weight', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured. Cross your arms over your chest or place your hands behind your head. Lower your upper body towards the ground while keeping your back straight. Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs. Repeat for the desired number of repetitions.', '/static/exercises/images/0489-zhMwOwE.jpg', '/static/exercises/gifs/0489-zhMwOwE.gif', '© Gym visual — https://gymvisual.com/', '900842'),
('100488', '超伸展训练凳', '臀肌', '自重', '未分级', '调整过度伸展凳，使臀部舒适地放在垫子上，并且双脚固定。双臂交叉放在胸前或将双手放在脑后。慢慢地将上半身降低到地面，同时保持背部挺直。在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。重复所需的重复次数。', 'exercise-dataset', '0488', 'hyperextension (on bench)', 'back', '背部', '20', 'body weight', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured. Cross your arms over your chest or place your hands behind your head. Slowly lower your upper body towards the ground while keeping your back straight. Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs. Repeat for the desired number of repetitions.', '/static/exercises/images/0488-zkgRrbK.jpg', '/static/exercises/gifs/0488-zkgRrbK.gif', '© Gym visual — https://gymvisual.com/', '900847'),
('103289', '高难度臂屈伸', '胸肌', '自重', '未分级', '将自己定位在两个双杠之间，双臂完全伸展，身体悬浮在空中。弯曲膝盖并交叉脚踝。弯曲肘部降低身体，直到上臂与地面平行。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '3289', 'impossible dips', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Position yourself between two parallel bars with your arms fully extended and your body suspended in the air. Bend your knees and cross your ankles. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3289-05Cf2v8.jpg', '/static/exercises/gifs/3289-05Cf2v8.gif', '© Gym visual — https://gymvisual.com/', '480846'),
('101471', '毛毛虫式', '肩部', '自重', '未分级', '从站立位置开始，双脚分开与臀部同宽。腰部向前弯曲，双手放在身前的地面上。双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。暂停片刻，然后将双手移回双脚，尽可能保持双腿伸直。一旦你的手到达你的脚，站回起始位置。重复所需的重复次数。', 'exercise-dataset', '1471', 'inchworm', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","腘绳肌"]', 'Start in a standing position with your feet hip-width apart. Bend forward at the waist and place your hands on the ground in front of you. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe. Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible. Once your hands reach your feet, stand back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1471-ZgsNQ6d.jpg', '/static/exercises/gifs/1471-ZgsNQ6d.gif', '© Gym visual — https://gymvisual.com/', '900845'),
('103698', '毛毛虫式版本第二式', '肩部', '自重', '未分级', '从站立位置开始，双脚分开与臀部同宽。腰部向前弯曲，双手放在身前的地面上。双手向前移动，直到处于高位平板支撑位置，身体从头到脚成一条直线。保持双腿伸直，将脚移向双手，将臀部抬向天花板。继续向前移动双手，重复该动作达到所需的重复次数。', 'exercise-dataset', '3698', 'inchworm v. 2', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","腘绳肌"]', 'Start in a standing position with your feet hip-width apart. Bend forward at the waist and place your hands on the ground in front of you. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe. Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling. Continue walking your hands forward, repeating the movement for the desired number of repetitions.', '/static/exercises/images/3698-TV87DNB.jpg', '/static/exercises/gifs/3698-TV87DNB.gif', '© Gym visual — https://gymvisual.com/', '900850'),
('100490', '上斜窄距握俯卧撑', '胸肌', '自重', '未分级', '将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。将双腿伸到身后，放在脚掌上，身体从头到脚跟形成一条直线。弯曲肘部，使肘部靠近身体两侧，将胸部降低到升高的表面。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0490', 'incline close-grip push-up', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels. Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0490-1YB40kg.jpg', '/static/exercises/gifs/0490-1YB40kg.gif', '© Gym visual — https://gymvisual.com/', '900851'),
('100491', '上斜腿髋部上举腿直', '髋屈肌', '自重', '未分级', '躺在倾斜的长凳上，背部平放在长凳上，双腿伸直在身前。将双手放在长凳两侧以获得支撑。收紧腹肌，将双腿抬离长凳，尽可能抬高双腿，同时保持伸直。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0491', 'incline leg hip raise (leg straight)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you. Place your hands on the sides of the bench for support. Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0491-eVxAzgz.jpg', '/static/exercises/gifs/0491-eVxAzgz.gif', '© Gym visual — https://gymvisual.com/', '900858'),
('100492', '上斜俯卧撑深度跳跃', '肱三头肌', '自重', '未分级', '找到一个较高的表面，例如长凳或台阶，并将双手与肩同宽放在边缘。双脚向后退一步，保持身体从头到脚跟呈一条直线。将胸部向水面边缘降低，弯曲肘部并保持身体对齐。推动手掌以伸展手臂并返回到起始位置。从水面边缘跳下，膝盖稍微弯曲，轻轻落地。重复俯卧撑和深度跳跃达到所需的重复次数。', 'exercise-dataset', '0492', 'incline push up depth jump', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge. Step your feet back, keeping your body in a straight line from head to heels. Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned. Push through your palms to extend your arms and return to the starting position. Jump off the edge of the surface, landing softly with your knees slightly bent. Repeat the push-up and depth jump for the desired number of repetitions.', '/static/exercises/images/0492-CB8WET1.jpg', '/static/exercises/gifs/0492-CB8WET1.gif', '© Gym visual — https://gymvisual.com/', '900857'),
('100493', '上斜俯卧撑', '肱三头肌', '自重', '未分级', '将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。弯曲肘部，将胸部向升高的表面降低，保持身体呈一条直线。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0493', 'incline push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0493-B1EVP9F.jpg', '/static/exercises/gifs/0493-B1EVP9F.gif', '© Gym visual — https://gymvisual.com/', '80852'),
('103785', '上斜俯卧撑跳箱', '肱三头肌', '自重', '未分级', '将双手放在盒子或高架表面的边缘，距离略宽于肩宽。将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。弯曲肘部，将胸部向箱子方向降低，保持身体呈一条直线。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '3785', 'incline push-up (on box)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the box by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3785-F7vjXqT.jpg', '/static/exercises/gifs/3785-F7vjXqT.gif', '© Gym visual — https://gymvisual.com/', '80857'),
('100494', '上斜反向握俯卧撑', '肱三头肌', '自重', '未分级', '将双手放在长凳或高架表面的边缘，距离略宽于肩宽。将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。弯曲肘部，将胸部向长凳方向降低，使其靠近身体两侧。在底部暂停片刻，然后伸展双臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0494', 'incline reverse grip push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the bench by bending your elbows, keeping them close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0494-XaaRnRn.jpg', '/static/exercises/gifs/0494-XaaRnRn.gif', '© Gym visual — https://gymvisual.com/', '80858'),
('103011', '上斜肩胛骨俯卧撑', '肱三头肌', '自重', '未分级', '设置一个 45 度角的上斜凳。将双手放在长凳上，距离略比肩宽。将双脚放在地面上，距离与臀部同宽。将胸部向长凳方向降低，保持肘部内收。当你降低时，缩回肩胛骨，将肩胛骨挤压在一起。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3011', 'incline scapula push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'serratus anterior', '前锯肌', '["肱三头肌","肩部"]', 'Set up an incline bench at a 45-degree angle. Place your hands on the bench slightly wider than shoulder-width apart. Position your feet on the ground, hip-width apart. Lower your chest towards the bench, keeping your elbows tucked in. As you lower, retract your shoulder blades, squeezing your scapulae together. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3011-GdMa1ET.jpg', '/static/exercises/gifs/3011-GdMa1ET.gif', '© Gym visual — https://gymvisual.com/', '900859'),
('100495', '上斜转体坐向上', '腹斜肌', '自重', '未分级', '设置一个 45 度角的上斜凳。躺在长凳上，双脚固定在脚垫下。将双手放在脑后或放在胸前。收紧腹肌，将上半身抬离长凳，向前卷曲。当你蜷缩起来时，将你的躯干扭转到一侧，将你的肘部拉向另一侧的膝盖。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复这个动作，这次将你的躯干扭转到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0495', 'incline twisting sit-up', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet secured under the foot pads. Place your hands behind your head or across your chest. Engage your abs and lift your upper body off the bench, curling forward. As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat the movement, this time twisting your torso to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0495-9ZGZuOD.jpg', '/static/exercises/gifs/0495-9ZGZuOD.gif', '© Gym visual — https://gymvisual.com/', '160858'),
('101564', '中级髋部屈肌股四头肌拉伸', '腘绳肌', '绳索', '未分级', '站直，双脚分开与肩同宽。抓住一个稳定的物体作为支撑。弯曲右膝，将右脚移向臀部，用右手抓住绳子。慢慢地将右脚拉向臀部，感受右股四头肌的拉伸。保持拉伸 20-30 秒。松开拉伸并在左侧重复。', 'exercise-dataset', '1564', 'intermediate hip flexor and quad stretch', 'upper legs', '大腿', '40', 'rope', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌"]', 'Stand upright with your feet shoulder-width apart. Hold onto a stable object for support. Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand. Slowly pull your right foot towards your glutes, feeling a stretch in your right quad. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the left side.', '/static/exercises/images/1564-tFGKm99.jpg', '/static/exercises/gifs/1564-tFGKm99.gif', '© Gym visual — https://gymvisual.com/', '901765'),
('100496', '反向腿弯举训练凳支撑', '臀肌', '自重', '未分级', '脸朝下躺在长凳上，臀部位于边缘，双腿伸直在身后。抓住长凳以获得支撑。保持上半身不动，弯曲膝盖并将双腿向臀部弯曲。在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。重复所需的重复次数。', 'exercise-dataset', '0496', 'inverse leg curl (bench support)', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Lie face down on a bench with your hips at the edge and your legs extended straight behind you. Hold onto the bench for support. Keeping your upper body still, bend your knees and curl your legs towards your glutes. Pause for a moment at the top, then slowly extend your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0496-ms7tjSG.jpg', '/static/exercises/gifs/0496-ms7tjSG.gif', '© Gym visual — https://gymvisual.com/', '480864'),
('102400', '反向腿弯举引体向上绳索器械', '臀肌', '自重', '未分级', '调整缆绳机，使踝带处于最低设置。面朝下躺在长凳上，双腿伸展，脚踝带固定在脚上。握住长凳的把手以保持稳定。弯曲膝盖，将双腿向臀部弯曲，挤压腿筋。在动作的最高点暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2400', 'inverse leg curl (on pull-up cable machine)', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Adjust the cable machine so that the ankle straps are at the lowest setting. Lie face down on the bench with your legs extended and the ankle straps attached to your feet. Hold onto the handles of the bench for stability. Bend your knees and curl your legs towards your glutes, squeezing your hamstrings. Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2400-0rHfvy9.jpg', '/static/exercises/gifs/2400-0rHfvy9.gif', '© Gym visual — https://gymvisual.com/', '480869'),
('100499', '反向划船', '肱二头肌', '自重', '未分级', '在腰部高度设置一个杠铃或使用悬挂训练器。面向杠铃或悬吊训练器站立，双脚分开与肩同宽。正手握住杠铃或手柄，握距略宽于肩宽。向后倾斜，保持身体挺直，脚后跟着地。将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0499', 'inverted row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a bar at waist height or use a suspension trainer. Stand facing the bar or suspension trainer, with your feet shoulder-width apart. Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart. Lean back, keeping your body straight and your heels on the ground. Pull your chest towards the bar or handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0499-bZGHsAZ.jpg', '/static/exercises/gifs/0499-bZGHsAZ.gif', '© Gym visual — https://gymvisual.com/', '900860'),
('102300', '反向划船屈曲双膝', '肱二头肌', '自重', '未分级', '在腰部高度设置一根横杆，然后躺在其下方。正手握住杠铃，握距略宽于肩宽。调整身体位置，使脚后跟着地，身体伸直。将肩胛骨挤压在一起，将胸部向上拉向杠铃。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2300', 'inverted row bent knees', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a bar at waist height and lie underneath it. Grab the bar with an overhand grip, slightly wider than shoulder-width apart. Position your body so that your heels are on the ground and your body is straight. Pull your chest up towards the bar by squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2300-VPPtusI.jpg', '/static/exercises/gifs/2300-VPPtusI.gif', '© Gym visual — https://gymvisual.com/', '900865'),
('102298', '反向划船训练凳', '肱二头肌', '自重', '未分级', '设置一张长凳，其高度应让您的身体可以自由地悬挂在其下方。面朝上躺在地上，头朝向长凳。向上伸手，正手握住长凳，握距略宽于肩宽。调整身体位置，使脚后跟着地，手臂完全伸展。当你将胸部拉向长凳时，启动你的核心并将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2298', 'inverted row on bench', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a bench at a height that allows your body to hang freely underneath it. Lie face up on the ground with your head towards the bench. Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart. Position your body so that your heels are on the ground and your arms are fully extended. Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2298-Mxa7Cr8.jpg', '/static/exercises/gifs/2298-Mxa7Cr8.gif', '© Gym visual — https://gymvisual.com/', '900866'),
('100497', '反向划船版本第二式', '肱二头肌', '自重', '未分级', '在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。双脚向前走，向后倾斜，直到身体呈轻微角度。保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。在最高点暂停片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0497', 'inverted row v. 2', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a bar at waist height on a Smith machine or use a suspension trainer. Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart. Walk your feet forward, leaning back until your body is at a slight angle. Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0497-uX3sUBz.jpg', '/static/exercises/gifs/0497-uX3sUBz.gif', '© Gym visual — https://gymvisual.com/', '900867'),
('100498', '反向划船拉力带', '肱二头肌', '自重', '未分级', '在胸部高度设置悬挂训练器或带子。面向锚点站立，并用正手握住手柄。双脚向前走，向后倾斜，直到身体呈一定角度。保持身体挺直并启动核心。将胸部拉向手柄，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0498', 'inverted row with straps', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up a suspension trainer or straps at chest height. Stand facing the anchor point and grab the handles with an overhand grip. Walk your feet forward, leaning back until your body is at an angle. Keep your body straight and engage your core. Pull your chest towards the handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0498-jdiExfW.jpg', '/static/exercises/gifs/0498-jdiExfW.gif', '© Gym visual — https://gymvisual.com/', '900868'),
('101419', '铁板交叉拉伸', '腘绳肌', '自重', '未分级', '平躺，双臂向两侧伸展。将双腿抬向天花板，保持伸直。慢慢地将双腿降低到一侧，旨在用脚接触地板。保持伸展几秒钟，然后将双腿恢复到起始位置。在另一侧重复拉伸。继续交替进行所需的重复次数。', 'exercise-dataset', '1419', 'iron cross stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie flat on your back with your arms extended out to the sides. Raise your legs up towards the ceiling, keeping them straight. Slowly lower your legs to one side, aiming to touch the floor with your feet. Hold the stretch for a few seconds, then return your legs to the starting position. Repeat the stretch on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1419-pZwUsKB.jpg', '/static/exercises/gifs/1419-pZwUsKB.gif', '© Gym visual — https://gymvisual.com/', '900867'),
('101297', '等长胸部挤压', '肱三头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双臂伸直在身前，与地面平行，手掌相对。尽可能用力挤压胸部肌肉，同时保持手臂伸直。保持这个姿势几秒钟，专注于收缩胸部肌肉。释放挤压并放松胸部肌肉。重复所需的重复次数。', 'exercise-dataset', '1297', 'isometric chest squeeze', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other. Squeeze your chest muscles together as hard as you can, while keeping your arms straight. Hold this position for a few seconds, focusing on contracting your chest muscles. Release the squeeze and relax your chest muscles. Repeat for the desired number of repetitions.', '/static/exercises/images/1297-HbSG1Pw.jpg', '/static/exercises/gifs/1297-HbSG1Pw.gif', '© Gym visual — https://gymvisual.com/', '900868'),
('100500', '等长雨刷式', '肩部', '自重', '未分级', '首先平躺在垫子或长凳上。将手臂伸直至两侧，与身体垂直。启动你的核心并将双腿抬离地面，保持它们并拢并伸直。慢慢地将双腿向一侧降低，目标是用脚接触地面，同时保持控制。暂停片刻，然后用核心力量将双腿抬回到起始位置。重复该动作，这次将双腿降低到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0500', 'isometric wipers', 'chest', '胸部', '10', 'body weight', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌","核心肌群"]', 'Start by lying flat on your back on a mat or bench. Extend your arms straight out to the sides, perpendicular to your body. Engage your core and lift both legs off the ground, keeping them together and straight. Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control. Pause for a moment, then use your core to lift your legs back to the starting position. Repeat the movement, this time lowering your legs to the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0500-11wrviz.jpg', '/static/exercises/gifs/0500-11wrviz.gif', '© Gym visual — https://gymvisual.com/', '900867'),
('100501', '开合跳波比跳', '股四头肌', '自重', '未分级', '从站立位置开始，双脚分开与肩同宽。将身体降低至蹲姿，将双手放在身前的地面上。双脚向后踢，以俯卧撑姿势落地。进行俯卧撑，将胸部降低到地面，然后再向上推。双脚向前跳，以蹲姿落地。爆发性地跳起，将双臂举过头顶。轻轻落地并立即回到蹲姿，开始下一次重复。', 'exercise-dataset', '0501', 'jack burpee', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群","肩部","肱三头肌","核心肌群"]', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position, placing your hands on the ground in front of you. Kick your feet back, landing in a push-up position. Perform a push-up, lowering your chest to the ground and then pushing back up. Jump your feet forward, landing in a squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into the squat position to begin the next repetition.', '/static/exercises/images/0501-mr7pkqP.jpg', '/static/exercises/gifs/0501-mr7pkqP.gif', '© Gym visual — https://gymvisual.com/', '240868'),
('103224', '开合跳跳跃（男）', '股四头肌', '自重', '未分级', '双脚并拢站立，双臂放在身体两侧。跳起来，分开双脚，将手臂举过头顶。当你落地时，迅速跳回起始位置。重复所需的重复次数。', 'exercise-dataset', '3224', 'jack jump (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","小腿肌群"]', 'Stand with your feet together and your arms by your sides. Jump up, spreading your feet apart and raising your arms above your head. As you land, quickly jump back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3224-1g5bPpA.jpg', '/static/exercises/gifs/3224-1g5bPpA.gif', '© Gym visual — https://gymvisual.com/', '560871'),
('100507', '折刀式坐向上', '髋屈肌', '自重', '未分级', '平躺，双腿伸展，双臂举过头顶。启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0507', 'jackknife sit-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs extended and your arms overhead. Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0507-mbkgB44.jpg', '/static/exercises/gifs/0507-mbkgB44.gif', '© Gym visual — https://gymvisual.com/', '160870'),
('100508', '扬达坐向上', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0508', 'janda sit-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0508-1GPHRyK.jpg', '/static/exercises/gifs/0508-1GPHRyK.gif', '© Gym visual — https://gymvisual.com/', '160871'),
('102612', '跳跃绳索', '小腿肌群', '绳索', '未分级', '双手握住跳绳的手柄，掌心向内。站立，双脚分开与肩同宽，膝盖稍微弯曲。将绳子甩过头顶，当绳子靠近你的脚时跳过它。轻轻地用脚掌着地，当绳子再次绕回时重复跳跃。继续跳跃所需的持续时间或重复次数。', 'exercise-dataset', '2612', 'jump rope', 'cardio', '有氧', '90', 'rope', 'calves', 'cardiovascular system', '心肺系统', '["小腿肌群","股四头肌","腘绳肌","臀肌"]', 'Hold the handles of the jump rope with your hands, palms facing inward. Stand with your feet shoulder-width apart and knees slightly bent. Swing the rope over your head and jump over it as it comes towards your feet. Land softly on the balls of your feet and repeat the jump as the rope comes around again. Continue jumping for the desired duration or number of repetitions.', '/static/exercises/images/2612-e1e76I2.jpg', '/static/exercises/gifs/2612-e1e76I2.gif', '© Gym visual — https://gymvisual.com/', '561772'),
('100514', '跳跃深蹲', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。爆发性地跳离地面，伸展臀部、膝盖和脚踝。在半空中时，快速将手臂向前伸以保持平衡。脚掌轻轻落地，然后立即进入下一个重复动作。重复所需的重复次数。', 'exercise-dataset', '0514', 'jump squat', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively off the ground, extending your hips, knees, and ankles. While in mid-air, quickly bring your arms forward for balance. Land softly on the balls of your feet and immediately go into the next repetition. Repeat for the desired number of repetitions.', '/static/exercises/images/0514-LIlE5Tn.jpg', '/static/exercises/gifs/0514-LIlE5Tn.gif', '© Gym visual — https://gymvisual.com/', '873'),
('100513', '跳跃深蹲版本第二式', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。爆发力跳跃，充分伸展臀部和膝盖。脚掌轻轻着地，然后立即将身体放回蹲姿。重复所需的重复次数。', 'exercise-dataset', '0513', 'jump squat v. 2', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively, extending your hips and knees fully. Land softly on the balls of your feet and immediately lower your body back into a squat position. Repeat for the desired number of repetitions.', '/static/exercises/images/0513-TDYiji6.jpg', '/static/exercises/gifs/0513-TDYiji6.gif', '© Gym visual — https://gymvisual.com/', '878'),
('100517', '壶铃高级风车式', '腹斜肌', '壶铃', '未分级', '站立，双脚分开比肩宽，脚趾稍微向外。右手握住壶铃，手臂伸过头顶，手掌朝前。将左脚稍微向右旋转，并将重量转移到左腿上。弯曲左膝并铰接在臀部，将躯干向左侧降低。保持右臂伸过头顶，眼睛盯着壶铃。当你降低躯干时，让右腿伸直，右脚稍微转动。降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。暂停片刻，然后启动核心并推动左脚跟返回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0517', 'kettlebell advanced windmill', 'waist', '腰腹', '60', 'kettlebell', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward. Rotate your left foot slightly to the right, and shift your weight onto your left leg. Bend your left knee and hinge at the hip, lowering your torso towards the left side. Keep your right arm extended overhead and your eyes on the kettlebell. As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly. Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground. Pause for a moment, then engage your core and push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0517-Kal9cQQ.jpg', '/static/exercises/gifs/0517-Kal9cQQ.gif', '© Gym visual — https://gymvisual.com/', '901577'),
('100518', '壶铃交替悬挂翻举', '肩部', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。让壶铃悬挂在身体前方，双臂完全伸展。以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。将壶铃放回起始位置，然后用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0518', 'kettlebell alternating hang clean', 'lower arms', '前臂', '80', 'kettlebell', 'shoulders', 'forearms', '前臂肌群', '["肩部","斜方肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang in front of your body with your arms fully extended. In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms. Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0518-I4tibZG.jpg', '/static/exercises/gifs/0518-I4tibZG.gif', '© Gym visual — https://gymvisual.com/', '901580'),
('100520', '壶铃交替推举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。将一只壶铃按过头顶，完全伸展手臂。将壶铃降低至肩膀高度。用另一只手臂重复上述步骤。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0520', 'kettlebell alternating press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead, fully extending your arm. Lower the kettlebell back to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0520-5KLbZWx.jpg', '/static/exercises/gifs/0520-5KLbZWx.gif', '© Gym visual — https://gymvisual.com/', '901579'),
('100519', '壶铃交替推举地板', '肩部', '壶铃', '未分级', '首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。继续用每个壶铃交替进行推举动作，达到所需的重复次数。', 'exercise-dataset', '0519', 'kettlebell alternating press on floor', 'chest', '胸部', '10', 'kettlebell', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling. Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up. Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder. Continue alternating the press motion with each kettlebell for the desired number of repetitions.', '/static/exercises/images/0519-7w6i0vE.jpg', '/static/exercises/gifs/0519-7w6i0vE.gif', '© Gym visual — https://gymvisual.com/', '901584'),
('100521', '壶铃交替俯卧式划船', '核心肌群', '壶铃', '未分级', '从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。收紧核心肌群，保持身体从头到脚跟呈一条直线。将一个壶铃向上拉向胸部，保持肘部靠近身体。将壶铃放回起始位置，然后用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0521', 'kettlebell alternating renegade row', 'back', '背部', '20', 'kettlebell', 'core', 'upper back', '上背部', '["核心肌群","肩部"]', 'Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart. Engage your core and keep your body in a straight line from head to heels. Pull one kettlebell up towards your chest, keeping your elbow close to your body. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0521-b9kqlBy.jpg', '/static/exercises/gifs/0521-b9kqlBy.gif', '© Gym visual — https://gymvisual.com/', '901583'),
('100522', '壶铃交替划船', '肱二头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。臀部向前弯曲，保持背部挺直，核心肌群参与。将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。将壶铃放回起始位置，然后用另一只手臂重复该动作。继续交替手臂进行所需的重复次数。', 'exercise-dataset', '0522', 'kettlebell alternating row', 'back', '背部', '20', 'kettlebell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', '/static/exercises/images/0522-Ca76jUE.jpg', '/static/exercises/gifs/0522-Ca76jUE.gif', '© Gym visual — https://gymvisual.com/', '901582'),
('100523', '壶铃阿诺德推举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。在动作的最高点暂停，然后慢慢将壶铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0523', 'kettlebell arnold press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you. Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms. Pause at the top of the movement, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0523-UM8mgyG.jpg', '/static/exercises/gifs/0523-UM8mgyG.gif', '© Gym visual — https://gymvisual.com/', '901583'),
('100524', '壶铃屈曲推举', '肩部', '壶铃', '未分级', '双脚分开与肩同宽站立，右手握住壶铃。稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。将躯干向左旋转，将重量转移到左脚上。弯曲左膝，将躯干压向地面，保持右臂伸过头顶。当你下降时，眼睛盯着壶铃，胸部抬起。左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0524', 'kettlebell bent press', 'waist', '腰腹', '60', 'kettlebell', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌","腹斜肌"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked. Rotate your torso to the left, shifting your weight onto your left foot. Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead. As you lower, keep your eyes on the kettlebell and your chest lifted. Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward. As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0524-kjE55n5.jpg', '/static/exercises/gifs/0524-kjE55n5.gif', '© Gym visual — https://gymvisual.com/', '901584'),
('100525', '壶铃倒置翻举从悬挂姿势', '前臂', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，正手握住。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。让壶铃垂在双腿之间，手臂完全伸展。以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。通过反向运动将壶铃降低回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0525', 'kettlebell bottoms up clean from the hang position', 'upper arms', '上臂', '50', 'kettlebell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebell to hang down between your legs, with your arm fully extended. In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up. Catch the kettlebell at shoulder height with your elbow bent and your palm facing up. Lower the kettlebell back down to the starting position by reversing the movement. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0525-4KJEpzb.jpg', '/static/exercises/gifs/0525-4KJEpzb.gif', '© Gym visual — https://gymvisual.com/', '901595'),
('100526', '壶铃双侧交替悬挂翻举', '前臂', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。让壶铃垂直悬挂在身体前方。以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0526', 'kettlebell double alternating hang clean', 'upper arms', '上臂', '50', 'kettlebell', 'forearms', 'biceps', '肱二头肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang straight down in front of your body. In one fluid motion, explosively extend your hips and knees while shrugging your shoulders. As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides. Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0526-a4F9Oyc.jpg', '/static/exercises/gifs/0526-a4F9Oyc.gif', '© Gym visual — https://gymvisual.com/', '901590'),
('100527', '壶铃双侧挺举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。稍微弯曲膝盖并启动核心。将壶铃压过头顶，充分伸展手臂。弯曲膝盖并快速半蹲。爆发性地伸展臀部和膝盖，将壶铃举过头顶。锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。站直并回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0527', 'kettlebell double jerk', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebells overhead, fully extending your arms. Bend your knees and quickly drop into a partial squat. Explosively extend your hips and knees, driving the kettlebells overhead. Lock out your arms and catch the kettlebells overhead with your knees slightly bent. Stand up straight and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0527-tznL2Ad.jpg', '/static/exercises/gifs/0527-tznL2Ad.gif', '© Gym visual — https://gymvisual.com/', '901587'),
('100528', '壶铃双侧推推举', '肱三头肌', '壶铃', '未分级', '首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。稍微弯曲膝盖并启动核心。通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0528', 'kettlebell double push press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead. As the kettlebells reach the top, press them fully overhead, locking out your arms. Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0528-I4KkPdl.jpg', '/static/exercises/gifs/0528-I4KkPdl.gif', '© Gym visual — https://gymvisual.com/', '901590'),
('100529', '壶铃双侧抓举', '斜方肌', '壶铃', '未分级', '双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0529', 'kettlebell double snatch', 'shoulders', '肩部', '30', 'kettlebell', 'trapezius', 'delts', '三角肌', '["斜方肌","前臂","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up. In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0529-M74kdvm.jpg', '/static/exercises/gifs/0529-M74kdvm.gif', '© Gym visual — https://gymvisual.com/', '901589'),
('100530', '壶铃双侧风车式', '肩部', '壶铃', '未分级', '双脚分开与肩同宽站立，右手握住壶铃。将右臂伸过头顶，眼睛盯着壶铃。左脚向左旋转 45 度，右脚向右旋转 90 度。腰部向左弯曲，保持右臂伸过头顶。将壶铃向地面降低，伸向左脚。暂停片刻，然后启动核心并推动右脚返回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0530', 'kettlebell double windmill', 'waist', '腰腹', '60', 'kettlebell', 'shoulders', 'abs', '腹肌', '["肩部","腘绳肌"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Extend your right arm overhead, keeping your eyes on the kettlebell. Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right. Bend at the waist to the left, keeping your right arm extended overhead. Lower the kettlebell towards the ground, reaching towards your left foot. Pause for a moment, then engage your core and push through your right foot to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0530-OaE7CpD.jpg', '/static/exercises/gifs/0530-OaE7CpD.gif', '© Gym visual — https://gymvisual.com/', '901590'),
('100531', '壶铃伸展幅度单臂推举地板', '肱三头肌', '壶铃', '未分级', '首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。一只手握住壶铃，手掌朝向脚部。将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0531', 'kettlebell extended range one arm press on floor', 'chest', '胸部', '10', 'kettlebell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in one hand, with your palm facing towards your feet. Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight. Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0531-rseLfH3.jpg', '/static/exercises/gifs/0531-rseLfH3.gif', '© Gym visual — https://gymvisual.com/', '901601'),
('100532', '壶铃数字8字', '肩部', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。当壶铃向前移动时，将其传递到两腿之间的另一只手。继续以 8 字形动作将壶铃传递到双腿之间。在整个练习过程中保持稳定的节奏并调动核心力量。重复所需的重复次数。', 'exercise-dataset', '0532', 'kettlebell figure 8', 'waist', '腰腹', '60', 'kettlebell', 'shoulders', 'abs', '腹肌', '["肩部","前臂"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pass the kettlebell between your legs, switching hands as it reaches the back of your legs. As the kettlebell comes forward, pass it to the other hand between your legs. Continue passing the kettlebell between your legs in a figure 8 motion. Maintain a steady pace and engage your core throughout the exercise. Repeat for the desired number of repetitions.', '/static/exercises/images/0532-L4ay0PW.jpg', '/static/exercises/gifs/0532-L4ay0PW.gif', '© Gym visual — https://gymvisual.com/', '901592'),
('100533', '壶铃前蹲', '股四头肌', '壶铃', '未分级', '站立，双脚分开与肩同宽，脚趾稍微向外。双手将壶铃放在胸前，靠近身体。收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。通过脚跟发力站起来，在顶部挤压臀部。重复所需的重复次数。', 'exercise-dataset', '0533', 'kettlebell front squat', 'upper legs', '大腿', '40', 'kettlebell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the kettlebell with both hands in front of your chest, close to your body. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', '/static/exercises/images/0533-DB0n8AG.jpg', '/static/exercises/gifs/0533-DB0n8AG.gif', '© Gym visual — https://gymvisual.com/', '1593'),
('100534', '壶铃高脚杯深蹲', '股四头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手握住壶铃靠近胸部。保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。继续降低，直到大腿与地面平行，或者尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0534', 'kettlebell goblet squat', 'upper legs', '大腿', '40', 'kettlebell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0534-ZA8b5hc.jpg', '/static/exercises/gifs/0534-ZA8b5hc.gif', '© Gym visual — https://gymvisual.com/', '1594'),
('100535', '壶铃悬挂翻举', '臀肌', '壶铃', '未分级', '双脚分开与肩同宽站立，将壶铃放在大腿前面。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将壶铃放低至地面，使其在双腿之间摆动。快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0535', 'kettlebell hang clean', 'upper legs', '大腿', '40', 'kettlebell', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","股四头肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower the kettlebell towards the ground, allowing it to swing between your legs. Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm. Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions.', '/static/exercises/images/0535-LHWF7us.jpg', '/static/exercises/gifs/0535-LHWF7us.gif', '© Gym visual — https://gymvisual.com/', '901595'),
('100536', '壶铃弓步传递穿过', '股四头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手握住壶铃放在胸前。右脚向前迈出一步，将身体降低至弓步位置。当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。用右脚蹬地回到起始位置，同时将壶铃传回右手。在另一侧重复弓步，将壶铃传递到左大腿下方。继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。', 'exercise-dataset', '0536', 'kettlebell lunge pass through', 'upper legs', '大腿', '40', 'kettlebell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand. Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand. Repeat the lunge on the opposite side, passing the kettlebell under your left thigh. Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions.', '/static/exercises/images/0536-WKMQzCD.jpg', '/static/exercises/gifs/0536-WKMQzCD.gif', '© Gym visual — https://gymvisual.com/', '321598'),
('100537', '壶铃单臂翻举挺举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，正手握住。稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0537', 'kettlebell one arm clean and jerk', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs. Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0537-vzAxBtt.jpg', '/static/exercises/gifs/0537-vzAxBtt.gif', '© Gym visual — https://gymvisual.com/', '901603'),
('101298', '壶铃单臂地板推举', '肱三头肌', '壶铃', '未分级', '仰卧在地板上，膝盖弯曲，双脚平放在地面上。一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1298', 'kettlebell one arm floor press', 'chest', '胸部', '10', 'kettlebell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling. Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body. Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1298-rg59QCH.jpg', '/static/exercises/gifs/1298-rg59QCH.gif', '© Gym visual — https://gymvisual.com/', '901602'),
('100538', '壶铃单臂挺举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。稍微弯曲膝盖并启动核心。将壶铃沿直线压过头顶，充分伸展手臂。当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0538', 'kettlebell one arm jerk', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebell overhead in a straight line, fully extending your arm. As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum. As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips. Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead. Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead. Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions.', '/static/exercises/images/0538-S37C94C.jpg', '/static/exercises/gifs/0538-S37C94C.gif', '© Gym visual — https://gymvisual.com/', '901601'),
('100539', '壶铃单臂军事推举侧向', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。启动你的核心并保持背部挺直。将壶铃压过头顶，充分伸展手臂。在顶部暂停片刻，然后慢慢将壶铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0539', 'kettlebell one arm military press to the side', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Engage your core and keep your back straight. Press the kettlebell overhead, extending your arm fully. Pause for a moment at the top, then slowly lower the kettlebell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0539-yCvYdi7.jpg', '/static/exercises/gifs/0539-yCvYdi7.gif', '© Gym visual — https://gymvisual.com/', '901610'),
('100540', '壶铃单臂推推举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。稍微弯曲膝盖并启动核心。伸展手臂并完全伸展双腿，将壶铃压过头顶。弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0540', 'kettlebell one arm push press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level. Bend your knees slightly and engage your core. Press the kettlebell overhead by extending your arm and fully extending your legs. Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0540-osdXT3K.jpg', '/static/exercises/gifs/0540-osdXT3K.gif', '© Gym visual — https://gymvisual.com/', '901605'),
('100541', '壶铃单臂划船', '肱二头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃，正手握住。稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将壶铃放回起始位置。重复所需的重复次数，然后换边并用另一只手臂重复。', 'exercise-dataset', '0541', 'kettlebell one arm row', 'back', '背部', '20', 'kettlebell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', '/static/exercises/images/0541-g9AsZ8P.jpg', '/static/exercises/gifs/0541-g9AsZ8P.gif', '© Gym visual — https://gymvisual.com/', '401604'),
('100542', '壶铃单臂抓举', '斜方肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。将壶铃放回到双腿之间，然后重复所需的重复次数。', 'exercise-dataset', '0542', 'kettlebell one arm snatch', 'shoulders', '肩部', '30', 'kettlebell', 'trapezius', 'delts', '三角肌', '["斜方肌","前臂","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm. Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.', '/static/exercises/images/0542-aXcUyKb.jpg', '/static/exercises/gifs/0542-aXcUyKb.gif', '© Gym visual — https://gymvisual.com/', '901605'),
('100543', '壶铃海盗式抬腿双腿', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，一只手握住壶铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将壶铃举至肩膀高度，保持肘部靠近身体。将手臂完全伸过头顶，伸直肘部。将壶铃降低至肩膀高度，然后返回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0543', 'kettlebell pirate supper legs', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the kettlebell up to shoulder height, keeping your elbow close to your body. Extend your arm fully overhead, straightening your elbow. Lower the kettlebell back down to shoulder height, then return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0543-kuXhl0o.jpg', '/static/exercises/gifs/0543-kuXhl0o.gif', '© Gym visual — https://gymvisual.com/', '901606'),
('100544', '壶铃手枪式深蹲', '股四头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手握住壶铃放在胸前。将左脚抬离地面并向前伸展，保持与地面平行。慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0544', 'kettlebell pistol squat', 'upper legs', '大腿', '40', 'kettlebell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Lift your left foot off the ground and extend it forward, keeping it parallel to the ground. Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended. Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0544-5bpPTHv.jpg', '/static/exercises/gifs/0544-5bpPTHv.gif', '© Gym visual — https://gymvisual.com/', '1605'),
('100545', '壶铃增强式俯卧撑', '肱三头肌', '壶铃', '未分级', '从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。将胸部压向地面，保持肘部靠近身体。爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。重复所需的重复次数。', 'exercise-dataset', '0545', 'kettlebell plyo push-up', 'chest', '胸部', '10', 'kettlebell', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a high plank position with your hands on the kettlebells, shoulder-width apart. Lower your chest towards the ground, keeping your elbows close to your body. Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully. Land softly back on the kettlebells and immediately lower your chest back down for the next repetition. Repeat for the desired number of repetitions.', '/static/exercises/images/0545-ktf3nvW.jpg', '/static/exercises/gifs/0545-ktf3nvW.gif', '© Gym visual — https://gymvisual.com/', '81606'),
('100546', '壶铃坐姿推举', '肱三头肌', '壶铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。每只手握住一个壶铃，与肩同高，手掌朝前。将壶铃压过头顶，充分伸展手臂。将壶铃降低至肩膀高度。重复所需的重复次数。', 'exercise-dataset', '0546', 'kettlebell seated press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder height, palms facing forward. Press the kettlebells overhead, fully extending your arms. Lower the kettlebells back to shoulder height. Repeat for the desired number of repetitions.', '/static/exercises/images/0546-BkxB8LW.jpg', '/static/exercises/gifs/0546-BkxB8LW.gif', '© Gym visual — https://gymvisual.com/', '901607'),
('101438', '壶铃坐姿双臂军事推举', '肱三头肌', '壶铃', '未分级', '坐在长凳上，背部挺直，双脚平放在地上。每只手握住一个壶铃，与肩同高，手掌朝前。完全伸展双臂，将壶铃压过头顶。在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。重复所需的重复次数。', 'exercise-dataset', '1438', 'kettlebell seated two arm military press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder level with your palms facing forward. Press the kettlebells overhead by extending your arms fully. Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/1438-ZEkjZDi.jpg', '/static/exercises/gifs/1438-ZEkjZDi.gif', '© Gym visual — https://gymvisual.com/', '901614'),
('100547', '壶铃跷跷板式推举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。继续交替按压动作，形成跷跷板状的运动。重复所需的重复次数。', 'exercise-dataset', '0547', 'kettlebell seesaw press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead while keeping the other kettlebell at shoulder height. Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead. Continue alternating the pressing motion, creating a seesaw-like movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0547-UDm6cGl.jpg', '/static/exercises/gifs/0547-UDm6cGl.gif', '© Gym visual — https://gymvisual.com/', '901609'),
('100548', '壶铃相扑式高位拉', '肩部', '壶铃', '未分级', '站立，双脚分开比肩宽，脚趾朝外。双手握住壶铃放在身体前方，手臂向下伸展。弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0548', 'kettlebell sumo high pull', 'back', '背部', '20', 'kettlebell', 'shoulders', 'traps', '斜方肌', '["肩部","臀肌","腘绳肌"]', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Hold a kettlebell with both hands in front of your body, arms extended downwards. Bend your knees and lower your hips into a squat position, keeping your back straight. Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin. As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0548-8ARQ9Hw.jpg', '/static/exercises/gifs/0548-8ARQ9Hw.gif', '© Gym visual — https://gymvisual.com/', '901612'),
('100549', '壶铃摆动', '腘绳肌', '壶铃', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。双手握住壶铃放在身体前方，双臂伸展。稍微弯曲膝盖并铰接臀部，将臀部向后推。将壶铃在两腿之间向后摆动，保持手臂伸直并保持背部平坦。利用臀部产生的动量，向前推动臀部并将壶铃摆动到肩膀高度。让壶铃在双腿之间向下摆动，然后重复该动作达到所需的重复次数。', 'exercise-dataset', '0549', 'kettlebell swing', 'upper legs', '大腿', '40', 'kettlebell', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","核心肌群"]', 'Stand with your feet shoulder-width apart, toes pointed slightly outward. Hold the kettlebell with both hands in front of your body, arms extended. Bend your knees slightly and hinge at the hips, pushing your butt back. Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back. Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips. Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.', '/static/exercises/images/0549-UHJlbu3.jpg', '/static/exercises/gifs/0549-UHJlbu3.gif', '© Gym visual — https://gymvisual.com/', '901609'),
('100550', '壶铃深蹲推举', '股四头肌', '壶铃', '未分级', '首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。在动作的最高点锁定你的手臂，完全伸展你的肘部。通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0550', 'kettlebell thruster', 'shoulders', '肩部', '30', 'kettlebell', 'quadriceps', 'delts', '三角肌', '["股四头肌","臀肌","核心肌群"]', 'Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other. Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead. Lock out your arms at the top of the movement, fully extending your elbows. Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/0550-yWxMvB5.jpg', '/static/exercises/gifs/0550-yWxMvB5.gif', '© Gym visual — https://gymvisual.com/', '901610'),
('100551', '壶铃土耳其式起身向上深蹲式', '股四头肌', '壶铃', '未分级', '首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。弯曲右膝，将右脚平放在地面上，保持左腿伸展。压右脚，将臀部抬离地面，进入桥位。将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。将躯干向左旋转，将左手放在地面上以获得支撑。压右脚和左手，将躯干抬离地面，形成跪姿。从跪姿站起来，保持壶铃伸过头顶。反向运动以返回到起始位置。从左手的壶铃开始，在另一侧重复练习。', 'exercise-dataset', '0551', 'kettlebell turkish get up (squat style)', 'upper legs', '大腿', '40', 'kettlebell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","核心肌群"]', 'Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder. Bend your right knee and place your right foot flat on the ground, keeping your left leg extended. Pressing through your right foot, lift your hips off the ground, coming into a bridge position. Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground. Rotate your torso to the left, bringing your left hand to the ground for support. Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position. From the kneeling position, stand up, keeping the kettlebell extended overhead. Reverse the movement to return to the starting position. Repeat the exercise on the other side, starting with the kettlebell in your left hand.', '/static/exercises/images/0551-Ha7SZ3y.jpg', '/static/exercises/gifs/0551-Ha7SZ3y.gif', '© Gym visual — https://gymvisual.com/', '1619'),
('100552', '壶铃双臂翻举', '斜方肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。将壶铃放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '0552', 'kettlebell two arm clean', 'shoulders', '肩部', '30', 'kettlebell', 'traps', 'delts', '三角肌', '["斜方肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0552-7Ba7bQ2.jpg', '/static/exercises/gifs/0552-7Ba7bQ2.gif', '© Gym visual — https://gymvisual.com/', '901616'),
('100553', '壶铃双臂军事推举', '肱三头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。启动你的核心并将壶铃压过头顶，充分伸展你的手臂。在顶部暂停片刻，然后慢慢将壶铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0553', 'kettlebell two arm military press', 'shoulders', '肩部', '30', 'kettlebell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward. Engage your core and press the kettlebells overhead, fully extending your arms. Pause for a moment at the top, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0553-blBXysN.jpg', '/static/exercises/gifs/0553-blBXysN.gif', '© Gym visual — https://gymvisual.com/', '901619'),
('101345', '壶铃双臂划船', '肱二头肌', '壶铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。臀部向前弯曲，保持背部挺直，核心肌群参与。将壶铃拉向胸部，将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将壶铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1345', 'kettlebell two arm row', 'back', '背部', '20', 'kettlebell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull the kettlebells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1345-wf24o8S.jpg', '/static/exercises/gifs/1345-wf24o8S.gif', '© Gym visual — https://gymvisual.com/', '901618'),
('100554', '壶铃风车式', '腹斜肌', '壶铃', '未分级', '双脚分开与肩同宽站立，右手握住壶铃举过头顶。将左脚向外旋转约 45 度，并保持右脚指向前方。将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0554', 'kettlebell windmill', 'waist', '腰腹', '60', 'kettlebell', 'obliques', 'abs', '腹肌', '["腹斜肌","肩部"]', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead. Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward. Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell. Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side. Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0554-9Tkqa9O.jpg', '/static/exercises/gifs/0554-9Tkqa9O.gif', '© Gym visual — https://gymvisual.com/', '901615'),
('100555', '踢腿向外坐', '股四头肌', '自重', '未分级', '坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。启动腿筋，将脚抬离地面，并将双腿伸直到身前。在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。重复所需的重复次数。', 'exercise-dataset', '0555', 'kick out sit', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'hamstrings', '腘绳肌', '["股四头肌","臀肌"]', 'Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle. Lean back slightly and place your hands on the edge of the bench or chair for support. Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you. Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body. Repeat for the desired number of repetitions.', '/static/exercises/images/0555-v7p5bYl.jpg', '/static/exercises/gifs/0555-v7p5bYl.gif', '© Gym visual — https://gymvisual.com/', '900918'),
('100558', '摆动借力肌肉向上', '肱二头肌', '自重', '未分级', '首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。启动你的核心并使用摆动动作来产生动力。当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。弯曲手臂并控制下降，将自己放回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0558', 'kipping muscle up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","肱三头肌","肩部","核心肌群"]', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and use a swinging motion to generate momentum. As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement. Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms. Lower yourself back down to the starting position by bending your arms and controlling the descent. Repeat for the desired number of repetitions.', '/static/exercises/images/0558-pM07UxU.jpg', '/static/exercises/gifs/0558-pM07UxU.gif', '© Gym visual — https://gymvisual.com/', '900919'),
('103640', '膝触碰卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将肩胛骨抬离地面，并将右手伸向左膝盖。返回起始位置并重复，这次将左手伸向右膝盖。继续交替进行所需的重复次数。', 'exercise-dataset', '3640', 'knee touch crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee. Return to the starting position and repeat, this time reaching your left hand towards your right knee. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3640-dTg95eZ.jpg', '/static/exercises/gifs/3640-dTg95eZ.gif', '© Gym visual — https://gymvisual.com/', '80920'),
('101420', '跪姿跳跃深蹲', '股四头肌', '杠铃', '未分级', '首先跪在地上，双脚分开与臀部同宽，脚趾向前。将杠铃放在上背部，将其放在肩膀上。启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。轻轻地回到地面，弯曲膝盖以吸收冲击力。立即进入下一个重复，重复跳蹲动作。', 'exercise-dataset', '1420', 'kneeling jump squat', 'upper legs', '大腿', '40', 'barbell', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward. Hold a barbell across your upper back, resting it on your shoulders. Engage your core and glutes, then explosively jump up into the air, extending your hips and knees. As you jump, push through your toes and fully extend your ankles, knees, and hips. Land softly back on the ground, bending your knees to absorb the impact. Immediately go into the next repetition, repeating the jump squat motion.', '/static/exercises/images/1420-UgDm3oy.jpg', '/static/exercises/gifs/1420-UgDm3oy.gif', '© Gym visual — https://gymvisual.com/', '1021'),
('101346', '跪姿背阔肌拉伸', '肩部', '自重', '未分级', '跪在地上，膝盖分开与臀部同宽，脚趾向后。将双臂伸过头顶，手指交叉。保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。保持伸展动作 20-30 秒，然后回到起始位置。在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。继续交替进行所需的重复次数。', 'exercise-dataset', '1346', 'kneeling lat stretch', 'back', '背部', '20', 'body weight', 'shoulders', 'lats', '背阔肌', '["肩部","肱三头肌"]', 'Kneel on the ground with your knees hip-width apart and your toes pointing back. Extend your arms overhead and interlace your fingers. Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1346-f38OEuO.jpg', '/static/exercises/gifs/1346-f38OEuO.gif', '© Gym visual — https://gymvisual.com/', '900922'),
('103239', '跪姿平板支撑触碰肩部（男）', '肩部', '自重', '未分级', '从跪姿开始，双手放在地上，与肩同宽。将双腿伸到身后，用脚趾支撑，将身体抬起成平板支撑姿势。保持核心参与并保持臀部稳定，将一只手抬离地面并拍打另一侧的肩膀。将手放回地面并用另一只手重复此操作。继续交替进行所需的重复次数。', 'exercise-dataset', '3239', 'kneeling plank tap shoulder (male)', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌"]', 'Start in a kneeling position with your hands on the ground, shoulder-width apart. Extend your legs behind you, resting on your toes, and lift your body into a plank position. Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder. Return the hand to the ground and repeat with the other hand. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3239-h1ezqSu.jpg', '/static/exercises/gifs/3239-h1ezqSu.gif', '© Gym visual — https://gymvisual.com/', '927'),
('103211', '跪姿俯卧撑（男）', '肱三头肌', '自重', '未分级', '首先跪在地上，双手与肩同宽，手指指向前方。将双腿伸到身后，放在脚掌上，使身体从头到脚跟形成一条直线。弯曲肘部，保持核心靠近身体两侧，将身体压向地面。继续降低，直到胸部刚好高于地面，然后伸直手臂，将其推回起始位置。重复所需的重复次数。', 'exercise-dataset', '3211', 'kneeling push-up (male)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward. Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels. Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides. Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3211-ZOuKWir.jpg', '/static/exercises/gifs/3211-ZOuKWir.gif', '© Gym visual — https://gymvisual.com/', '80924'),
('103288', '韩式臂屈伸', '肱三头肌', '自重', '未分级', '将自己定位在两个双杠之间，双臂伸展并支撑体重。弯曲肘部降低身体，直到上臂与地面平行。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '3288', 'korean dips', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Position yourself between two parallel bars with your arms extended and supporting your body weight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3288-rWoBmi5.jpg', '/static/exercises/gifs/3288-rWoBmi5.gif', '© Gym visual — https://gymvisual.com/', '320923'),
('103418', 'L式引体向上', '肱二头肌', '自重', '未分级', '正手握住引体向上杆，握距略宽于肩宽。双臂完全伸展，身体伸直。收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3418', 'l-pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight. Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3418-d1GgzTU.jpg', '/static/exercises/gifs/3418-d1GgzTU.gif', '© Gym visual — https://gymvisual.com/', '922'),
('103419', 'L式坐地板', '髋屈肌', '自重', '未分级', '坐在地板上，双腿伸到身前。将双手放在臀部旁边的地板上，手指指向前方。启动你的核心并将双腿抬离地面，保持伸直。尝试使双腿与地面平行，与身体形成“L”形。尽可能长时间地保持这个姿势。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3419', 'l-sit on floor', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the floor with your legs extended in front of you. Place your hands on the floor beside your hips, fingers pointing forward. Engage your core and lift your legs off the ground, keeping them straight. Try to bring your legs parallel to the floor, forming an ''L'' shape with your body. Hold this position for as long as you can. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3419-UpWmA5E.jpg', '/static/exercises/gifs/3419-UpWmA5E.gif', '© Gym visual — https://gymvisual.com/', '900927'),
('100562', '地雷管180度', '腹斜肌', '杠铃', '未分级', '双脚分开与肩同宽站立，双手握住杠铃于胸前。稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。继续这个扭转动作，两侧交替，达到所需的重复次数。', 'exercise-dataset', '0562', 'landmine 180', 'waist', '腰腹', '60', 'barbell', 'obliques', 'abs', '腹肌', '["腹斜肌","股四头肌"]', 'Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest. Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip. As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder. Continue this twisting motion, alternating sides, for the desired number of repetitions.', '/static/exercises/images/0562-QYysSLV.jpg', '/static/exercises/gifs/0562-QYysSLV.gif', '© Gym visual — https://gymvisual.com/', '901026'),
('103237', '地雷管侧平举', '斜方肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，将其放在肩膀前面。保持核心收紧并保持背部挺直，将杠铃向上举起并远离身体，将其提升至肩膀高度。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3237', 'landmine lateral raise', 'shoulders', '肩部', '30', 'barbell', 'traps', 'delts', '三角肌', '["斜方肌","上背部"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the barbell with an overhand grip, resting it on the front of your shoulders. Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3237-eXMFHww.jpg', '/static/exercises/gifs/3237-eXMFHww.gif', '© Gym visual — https://gymvisual.com/', '161029'),
('103300', '前倾水平支撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手分开与肩同宽，身体伸直。启动你的核心，慢慢地将你的重心向前移动，让你的肩膀越过你的手。向前倾时，保持肘部稍微弯曲，身体伸直。保持这个姿势几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3300', 'lean planche', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌","肱三头肌"]', 'Start in a push-up position with your hands shoulder-width apart and your body straight. Engage your core and slowly shift your weight forward, bringing your shoulders past your hands. Keep your elbows slightly bent and your body straight as you lean forward. Hold this position for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3300-LYJodFS.jpg', '/static/exercises/gifs/3300-LYJodFS.gif', '© Gym visual — https://gymvisual.com/', '900928'),
('102271', '左侧锁握拳击', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。左手举起以保护脸部，右手握住下巴。旋转臀部并以左脚为轴心，同时以出拳动作向前伸展左臂。扭转你的躯干并调动你的核心肌肉以产生出拳的力量。将手臂拉回到起始位置，然后重复所需的重复次数。', 'exercise-dataset', '2271', 'left hook. boxing', 'shoulders', '肩部', '30', 'body weight', 'biceps', 'delts', '三角肌', '["肱二头肌","肱三头肌","前臂"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Keep your left hand up to protect your face and your right hand by your chin. Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion. Twist your torso and engage your core muscles to generate power in the punch. Snap your arm back to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/2271-hoXt6wv.jpg', '/static/exercises/gifs/2271-hoXt6wv.gif', '© Gym visual — https://gymvisual.com/', '900931'),
('100570', '腿拉平凳训练凳', '髋屈肌', '自重', '未分级', '坐在平坦的长凳上，双腿在身前伸直。将双手放在臀部旁边的长凳上以获得支撑。收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0570', 'leg pull in flat bench', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Sit on a flat bench with your legs extended straight out in front of you. Place your hands on the bench beside your hips for support. Engage your abs and lift your legs off the ground, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0570-OyoZ3Pu.jpg', '/static/exercises/gifs/0570-OyoZ3Pu.gif', '© Gym visual — https://gymvisual.com/', '900936'),
('101576', '腿向上腘绳肌拉伸', '臀肌', '自重', '未分级', '平躺，双腿伸展。弯曲一侧膝盖，将其靠近胸部，握住大腿或小腿。尽可能伸直腿，同时保持腿抬高。保持拉伸 20-30 秒。换另一条腿重复上述步骤。', 'exercise-dataset', '1576', 'leg up hamstring stretch', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Lie flat on your back with your legs extended. Bend one knee and bring it towards your chest, holding onto your thigh or shin. Straighten your leg as much as possible while keeping it elevated. Hold the stretch for 20-30 seconds. Repeat with the other leg.', '/static/exercises/images/1576-sU5BrfP.jpg', '/static/exercises/gifs/1576-sU5BrfP.gif', '© Gym visual — https://gymvisual.com/', '900935'),
('102287', '器械交替腿举', '腘绳肌', '固定器械', '未分级', '将杠杆机的座椅和脚踏平台调整到您想要的位置。坐在机器上，背部靠在靠背上，双脚放在脚踏板上。将手放在机器的手柄或侧面以保持稳定性。将一只脚推到脚平台上，伸展腿直到几乎完全伸直。暂停片刻，然后慢慢弯曲腿，回到起始位置。换另一条腿重复上述步骤。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '2287', 'lever alternate leg press', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌"]', 'Adjust the seat and foot platform of the leverage machine to your desired position. Sit on the machine with your back against the backrest and your feet on the foot platform. Place your hands on the handles or sides of the machine for stability. Push one foot against the foot platform, extending your leg until it is almost fully straight. Pause for a moment, then slowly bend your leg and return to the starting position. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/2287-V07qpXy.jpg', '/static/exercises/gifs/2287-V07qpXy.gif', '© Gym visual — https://gymvisual.com/', '241336'),
('100571', '器械交替窄距握坐姿划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度和踏板位置以确保正确对齐。坐在机器上，背部挺直，双脚平放在踏板上。紧紧握住手柄，手掌相对。在整个练习过程中保持挺胸、肩膀向后。将一个手柄拉向您的躯干，同时保持另一个手柄静止。在动作结束时将肩胛骨挤压在一起。慢慢地将手柄返回到起始位置，并在另一侧重复此操作。继续交替进行所需的重复次数。', 'exercise-dataset', '0571', 'lever alternating narrow grip seated row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your back straight and feet flat on the footplate. Grasp the handles with a narrow grip, palms facing each other. Keep your chest up and shoulders back throughout the exercise. Pull one handle towards your torso while keeping the other handle stationary. Squeeze your shoulder blades together at the end of the movement. Slowly return the handle to the starting position and repeat with the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0571-w2oRpuH.jpg', '/static/exercises/gifs/0571-w2oRpuH.gif', '© Gym visual — https://gymvisual.com/', '241341'),
('100572', '器械辅助反手引体向上', '肱二头肌', '固定器械', '未分级', '将杠杆机调整至您想要的阻力水平。站在脚踏板上，正手握住手柄，握距略宽于肩宽。双臂完全伸展，保持身体挺直。收紧背部肌肉，将身体拉向手柄，以胸部为主导。继续拉，直到下巴位于手柄上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0572', 'lever assisted chin-up', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the leverage machine to your desired resistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your body straight. Engage your back muscles and pull your body up towards the handles, leading with your chest. Continue pulling until your chin is above the handles. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0572-MaMuGH6.jpg', '/static/exercises/gifs/0572-MaMuGH6.gif', '© Gym visual — https://gymvisual.com/', '901336'),
('100573', '器械山羊挺身', '臀肌', '固定器械', '未分级', '调整机器以适合您的身体尺寸和运动范围。坐在机器上，背部靠在垫子上，双脚固定。将手放在手柄或握杆上。启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。在底部位置暂停片刻，感觉下背部有拉伸感。使用背部肌肉，慢慢将躯干抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0573', 'lever back extension', 'back', '背部', '20', 'leverage machine', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Adjust the machine to fit your body size and range of motion. Sit on the machine with your back against the pad and your feet secured. Place your hands on the handles or grip bars. Engage your core and slowly lean forward, allowing your back to round slightly. Pause for a moment at the bottom position, feeling a stretch in your lower back. Using your back muscles, slowly raise your torso back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0573-rUXfn3R.jpg', '/static/exercises/gifs/0573-rUXfn3R.gif', '© Gym visual — https://gymvisual.com/', '481337'),
('100574', '器械俯身划船', '肱二头肌', '杠铃', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。正手握住杠铃，双手分开略宽于肩宽。臀部向前弯曲，保持背部挺直，挺胸。将杠铃拉向下胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0574', 'lever bent over row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up. Pull the barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0574-X3cqyXz.jpg', '/static/exercises/gifs/0574-X3cqyXz.gif', '© Gym visual — https://gymvisual.com/', '161040'),
('103200', '器械俯身划船V字杆', '肱二头肌', '固定器械', '未分级', '调整座椅高度并将自己面向机器。正手握住 V 形杆，保持背部挺直，膝盖稍微弯曲。将 V 形杆拉向腹部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢释放重量回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3200', 'lever bent-over row with v-bar', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and position yourself facing the machine. Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent. Pull the v-bar towards your abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the weight back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3200-LuBEORI.jpg', '/static/exercises/gifs/3200-LuBEORI.gif', '© Gym visual — https://gymvisual.com/', '901343'),
('100575', '器械肱二头肌弯举', '前臂', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。反手握住手柄，手掌朝上，肘部靠近身体两侧。呼气并向上弯曲手柄，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将手柄放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0575', 'lever bicep curl', 'upper arms', '上臂', '50', 'leverage machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides. Exhale and curl the handles upward, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0575-q6y3OhV.jpg', '/static/exercises/gifs/0575-q6y3OhV.gif', '© Gym visual — https://gymvisual.com/', '81340'),
('102289', '器械小腿推举', '腘绳肌', '固定器械', '未分级', '调整杠杆机的座椅，使肩膀与杠杆垫对齐。将脚趾放在杠杆垫上，脚跟悬在边缘上。抓住手柄或侧面支撑以保持稳定性。伸展脚踝，收缩小腿肌肉，将杠杆垫向下推。在动作的底部停顿片刻。让脚后跟重新抬起，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2289', 'lever calf press', 'lower legs', '小腿', '70', 'leverage machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad. Place your toes on the lever pad, with your heels hanging off the edge. Grasp the handles or side supports for stability. Push the lever pad down by extending your ankles, contracting your calf muscles. Pause for a moment at the bottom of the movement. Slowly return to the starting position by allowing your heels to rise back up. Repeat for the desired number of repetitions.', '/static/exercises/images/2289-7B4F5nZ.jpg', '/static/exercises/gifs/2289-7B4F5nZ.gif', '© Gym visual — https://gymvisual.com/', '901341'),
('100577', '器械胸推', '肱三头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，背部平放在垫子上。正手握住手柄，肘部呈 90 度角。向前推动手柄，直到手臂完全伸展，运动过程中呼气。动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。重复所需的重复次数。', 'exercise-dataset', '0577', 'lever chest press', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', '/static/exercises/images/0577-T0yTjgW.jpg', '/static/exercises/gifs/0577-T0yTjgW.gif', '© Gym visual — https://gymvisual.com/', '161342'),
('100576', '器械胸推', '肱三头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，背部平放在垫子上。正手握住手柄，肘部呈 90 度角。向前推动手柄，直到手臂完全伸展，运动过程中呼气。动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。重复所需的重复次数。', 'exercise-dataset', '0576', 'lever chest press', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', '/static/exercises/images/0576-DOoWcnA.jpg', '/static/exercises/gifs/0576-DOoWcnA.gif', '© Gym visual — https://gymvisual.com/', '161343'),
('100578', '器械硬拉', '腘绳肌', '固定器械', '未分级', '将座椅高度和脚踏板调整到您想要的位置。坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。抓住把手或座椅侧面以保持稳定性。收紧臀肌和腿筋，并通过脚后跟推动举重。保持背部挺直，避免圆肩。在动作的最高点完全伸展臀部，挤压臀部。以受控的方式降低重量，保持臀肌和腿筋的张力。重复所需的重复次数。', 'exercise-dataset', '0578', 'lever deadlift', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Adjust the seat height and foot platform to your desired position. Sit on the machine with your back against the pad and your feet flat on the foot platform. Grasp the handles or the sides of the seat for stability. Engage your glutes and hamstrings, and push through your heels to lift the weight up. Keep your back straight and avoid rounding your shoulders. Extend your hips fully at the top of the movement, squeezing your glutes. Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings. Repeat for the desired number of repetitions.', '/static/exercises/images/0578-GUT8I22.jpg', '/static/exercises/gifs/0578-GUT8I22.gif', '© Gym visual — https://gymvisual.com/', '81342'),
('101300', '器械下斜胸推', '肱三头肌', '固定器械', '未分级', '将杠杆机的座椅高度和靠背调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚平放在地板上。正手握住手柄，双手之间的距离略大于肩宽。向前推动手柄并使其远离身体，直到双臂完全伸展。慢慢地将手柄放回胸部，保持肘部稍微弯曲。在底部暂停片刻，然后将手柄推回起始位置。重复所需的重复次数。', 'exercise-dataset', '1300', 'lever decline chest press', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended. Slowly lower the handles back towards your chest, keeping your elbows slightly bent. Pause for a moment at the bottom, then push the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1300-vsVoPHt.jpg', '/static/exercises/gifs/1300-vsVoPHt.gif', '© Gym visual — https://gymvisual.com/', '161347'),
('101253', '器械骑驴式提踵', '腘绳肌', '固定器械', '未分级', '将杠杆机调节至适合您身体的高度。面向机器定位，脚趾放在脚踏平台上，脚后跟悬在边缘。将手放在手柄或支撑杆上以保持稳定性。用脚掌收紧小腿并尽可能高地抬起脚后跟。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1253', 'lever donkey calf raise', 'lower legs', '小腿', '70', 'leverage machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the leverage machine to the appropriate height for your body. Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge. Place your hands on the handles or the support bars for stability. Engage your calves and lift your heels as high as possible, using the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1253-C9LuR4A.jpg', '/static/exercises/gifs/1253-C9LuR4A.gif', '© Gym visual — https://gymvisual.com/', '1348'),
('100579', '器械前侧下拉', '肱二头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。正手握住手柄，握距略宽于肩宽。坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0579', 'lever front pulldown', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back. Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0579-7F1DVzn.jpg', '/static/exercises/gifs/0579-7F1DVzn.gif', '© Gym visual — https://gymvisual.com/', '81347'),
('100580', '器械无握把耸肩', '肩部', '固定器械', '未分级', '调整座椅高度并将自己放在杠杆机上。手掌朝内，抓住手柄，双臂完全伸展。保持背部挺直，呼气并尽可能抬高肩膀。保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0580', 'lever gripless shrug', 'back', '背部', '20', 'leverage machine', 'shoulders', 'traps', '斜方肌', '["肩部","前臂"]', 'Adjust the seat height and position yourself on the leverage machine. Grasp the handles with your palms facing inwards and your arms fully extended. Keeping your back straight, exhale and elevate your shoulders as high as possible. Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0580-f91FwXG.jpg', '/static/exercises/gifs/0580-f91FwXG.gif', '© Gym visual — https://gymvisual.com/', '561348'),
('101439', '器械无握把耸肩版本第二式', '肩部', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。正手握住手柄或杆，保持手臂伸直。保持背部挺直，将肩膀尽可能高地抬向耳朵。保持收缩一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1439', 'lever gripless shrug v. 2', 'back', '背部', '20', 'leverage machine', 'shoulders', 'traps', '斜方肌', '["肩部","前臂"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles or bars with an overhand grip, keeping your arms straight. Keeping your back straight, lift your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1439-cbuFJrn.jpg', '/static/exercises/gifs/1439-cbuFJrn.gif', '© Gym visual — https://gymvisual.com/', '561353'),
('102288', '器械握力器双手', '肱二头肌', '固定器械', '未分级', '调整座椅高度并握住杠杆机的手柄。保持背部挺直，双脚平放在地面上。呼气并挤压手柄，收缩前臂。保持收缩一秒钟，然后慢慢释放并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2288', 'lever gripper hands', 'lower arms', '前臂', '80', 'leverage machine', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Adjust the seat height and grip the handles of the leverage machine. Keep your back straight and your feet flat on the ground. Exhale and squeeze the handles, contracting your forearms. Hold the contraction for a second, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2288-mKwcrHn.jpg', '/static/exercises/gifs/2288-mKwcrHn.gif', '© Gym visual — https://gymvisual.com/', '161350'),
('101615', '器械锤式握牧师凳弯举', '前臂', '固定器械', '未分级', '调整座椅高度并将自己放在杠杆机上。将你的上臂放在讲道垫上，确保你的胸部压在上面。用锤子握把抓住手柄（手掌相对）。保持上臂静止，呼气并将手柄卷向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1615', 'lever hammer grip preacher curl', 'upper arms', '上臂', '50', 'leverage machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the seat height and position yourself on the leverage machine. Place your upper arms on the preacher pad, ensuring your chest is pressed against it. Grasp the handles with a hammer grip (palms facing each other). Keeping your upper arms stationary, exhale and curl the handles towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1615-OAguZoG.jpg', '/static/exercises/gifs/1615-OAguZoG.gif', '© Gym visual — https://gymvisual.com/', '81355'),
('100581', '器械高位划船', '肱二头肌', '固定器械', '未分级', '将座椅高度和脚踏板调整至舒适的位置。坐在机器上，胸部靠在垫子上，双脚平放在脚踏平台上。正手握住手柄，握距略宽于肩宽。保持背部挺直并启动核心肌群。将手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0581', 'lever high row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","后侧DELTOIDS"]', 'Adjust the seat height and foot platform to a comfortable position. Sit on the machine with your chest against the pad and your feet flat on the foot platform. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0581-nZZZy9m.jpg', '/static/exercises/gifs/0581-nZZZy9m.gif', '© Gym visual — https://gymvisual.com/', '901352'),
('102286', '器械伸髋版本第二式', '腘绳肌', '固定器械', '未分级', '调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。将脚放在脚踏板上并握住手柄以保持稳定。启动臀肌和腿筋，然后推动脚踏板以伸展臀部并向后抬起双腿。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2286', 'lever hip extension v. 2', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your feet on the footrests and grip the handles for stability. Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward. Pause for a moment at the top, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2286-OPqShYN.jpg', '/static/exercises/gifs/2286-OPqShYN.gif', '© Gym visual — https://gymvisual.com/', '901357'),
('102611', '器械水平单腿举', '股四头肌', '固定器械', '未分级', '调整机器座椅，使双脚放在踏板上时膝盖呈 90 度角。坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。将手放在机器的手柄或侧面以保持稳定性。伸展腿，使背部紧靠靠背，将踏板推离身体。在完全伸展位置暂停片刻，然后慢慢弯曲腿回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '2611', 'lever horizontal one leg press', 'upper legs', '大腿', '40', 'leverage machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate. Place your hands on the handles or sides of the machine for stability. Push the footplate away from your body by extending your leg, keeping your back against the backrest. Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/2611-9KU9TYF.jpg', '/static/exercises/gifs/2611-9KU9TYF.gif', '© Gym visual — https://gymvisual.com/', '241358'),
('101299', '器械上斜胸推', '肩部', '固定器械', '未分级', '将杠杆机的座椅和靠背调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚平放在地板上。正手握住手柄，双手之间的距离略大于肩宽。向前推动手柄并使其远离身体，直到双臂完全伸展。暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。重复所需的重复次数。', 'exercise-dataset', '1299', 'lever incline chest press', 'chest', '胸部', '10', 'leverage machine', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the seat and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended. Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/1299-jHAnWmT.jpg', '/static/exercises/gifs/1299-jHAnWmT.gif', '© Gym visual — https://gymvisual.com/', '161357'),
('101479', '器械上斜胸推版本第二式', '肱三头肌', '固定器械', '未分级', '将杠杆机上的座椅高度和靠背角度调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚平放在地板上。正手握住手柄，双手之间的距离略大于肩宽。向前推动手柄并远离身体，直到手臂完全伸展，但不要锁定肘部。在完全伸展的位置暂停片刻，然后慢慢弯曲肘部并将手柄放回胸部。重复所需的重复次数。', 'exercise-dataset', '1479', 'lever incline chest press v. 2', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and backrest angle on the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows. Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/1479-o17Jfkt.jpg', '/static/exercises/gifs/1479-o17Jfkt.gif', '© Gym visual — https://gymvisual.com/', '161362'),
('100582', '器械跪姿腿弯举', '臀肌', '固定器械', '未分级', '调整机器以适合您的身体并选择所需的重量。面朝下跪在机器上，膝盖放在垫子上，双脚固定在脚垫下。抓住机器的手柄或侧面以保持稳定性。保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。在动作的最高点暂停片刻，挤压你的腿筋。吸气，慢慢将双腿放回起始位置，充分伸展膝盖。重复所需的重复次数。', 'exercise-dataset', '0582', 'lever kneeling leg curl', 'upper legs', '大腿', '40', 'leverage machine', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Adjust the machine to fit your body and select the desired weight. Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees. Pause for a moment at the top of the movement, squeezing your hamstrings. Inhale and slowly lower your legs back to the starting position, fully extending your knees. Repeat for the desired number of repetitions.', '/static/exercises/images/0582-nnmCTLN.jpg', '/static/exercises/gifs/0582-nnmCTLN.gif', '© Gym visual — https://gymvisual.com/', '481359'),
('100583', '器械跪姿转体', '腹斜肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。抓住机器的手柄或侧面以保持稳定性。保持核心参与，将躯干尽可能舒适地向一侧扭转。暂停片刻，然后慢慢回到起始位置。向另一侧重复扭转。继续交替进行所需的重复次数。', 'exercise-dataset', '0583', 'lever kneeling twist', 'waist', '腰腹', '60', 'leverage machine', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward. Grasp the handles or the sides of the machine for stability. Keeping your core engaged, twist your torso to one side as far as comfortably possible. Pause for a moment, then slowly return to the starting position. Repeat the twist to the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0583-sZOR9EV.jpg', '/static/exercises/gifs/0583-sZOR9EV.gif', '© Gym visual — https://gymvisual.com/', '901358'),
('100584', '器械侧平举', '斜方肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。正手握住手柄并保持手臂伸直。呼气并将手臂向两侧抬起，直到与地板平行。在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0584', 'lever lateral raise', 'shoulders', '肩部', '30', 'leverage machine', 'traps', 'delts', '三角肌', '["斜方肌","上背部"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Exhale and raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0584-dRTfGZT.jpg', '/static/exercises/gifs/0584-dRTfGZT.gif', '© Gym visual — https://gymvisual.com/', '161359'),
('100585', '器械腿屈伸', '腘绳肌', '固定器械', '未分级', '调整机器的座椅高度和靠背以适合您的身体。坐在机器上，背部靠在靠背上，双脚放在脚垫上。抓住手柄或侧杆以保持稳定性。伸直膝盖，举起重物，向前伸展双腿。在顶部暂停片刻，然后慢慢将重量放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0585', 'lever leg extension', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'quads', '股四头肌', '["腘绳肌"]', 'Adjust the seat height and backrest of the machine to fit your body. Sit on the machine with your back against the backrest and your feet on the footpad. Grasp the handles or sidebars for stability. Extend your legs forward by straightening your knees, lifting the weight. Pause for a moment at the top, then slowly lower the weight back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0585-my33uHU.jpg', '/static/exercises/gifs/0585-my33uHU.gif', '© Gym visual — https://gymvisual.com/', '401360'),
('100586', '器械仰卧腿弯举', '小腿肌群', '固定器械', '未分级', '调整机器以适合您的身体并选择所需的重量。面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。抓住机器的手柄或侧面以保持稳定性。保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。挤压腿筋时，保持收缩位置短暂停顿。吸气并缓慢地将控制杆降低回起始位置。重复所需的重复次数。', 'exercise-dataset', '0586', 'lever lying leg curl', 'upper legs', '大腿', '40', 'leverage machine', 'calves', 'hamstrings', '腘绳肌', '["小腿肌群"]', 'Adjust the machine to fit your body and select the desired weight. Lie face down on the machine with your legs straight and your heels against the padded lever. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0586-17lJ1kr.jpg', '/static/exercises/gifs/0586-17lJ1kr.gif', '© Gym visual — https://gymvisual.com/', '481363'),
('103195', '器械仰卧双单腿弯举', '臀肌', '固定器械', '未分级', '调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。将双腿放在脚踝上方的杠杆垫上。抓住机器两侧的手柄以提供支撑。保持上半身不动，呼气并将双腿向上弯曲至臀部。在顶部停顿片刻，然后吸气，慢慢降低双腿回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3195', 'lever lying two-one leg curl', 'upper legs', '大腿', '40', 'leverage machine', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your legs on the lever pad, just above your ankles. Grasp the handles on the sides of the machine for support. Keeping your upper body still, exhale and curl your legs up towards your glutes. Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3195-UXpKJoq.jpg', '/static/exercises/gifs/3195-UXpKJoq.gif', '© Gym visual — https://gymvisual.com/', '481366'),
('100587', '器械军事推举', '肱三头肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在靠背上。正手握住手柄，双手之间的距离略大于肩宽。向上推动手柄，直到手臂完全伸展，但不要锁住肘部。在顶部暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0587', 'lever military press', 'shoulders', '肩部', '30', 'leverage machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上部胸部"]', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles upward until your arms are fully extended, but do not lock your elbows. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0587-CggQhII.jpg', '/static/exercises/gifs/0587-CggQhII.gif', '© Gym visual — https://gymvisual.com/', '901363'),
('100588', '器械窄距握坐姿划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度和脚踏板以确保形状正确。坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。紧紧握住手柄，手掌相对。保持背部挺直并稍微向前倾斜。将手柄拉向躯干，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢松开手柄并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0588', 'lever narrow grip seated row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footrests to ensure proper form. Sit on the machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with a narrow grip, palms facing each other. Keep your back straight and lean slightly forward. Pull the handles towards your torso, squeezing your shoulder blades together. Pause for a moment at the peak of the movement. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0588-IGjKj1v.jpg', '/static/exercises/gifs/0588-IGjKj1v.gif', '© Gym visual — https://gymvisual.com/', '241368'),
('100589', '器械单臂俯身划船', '肱二头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲，正手握住杠铃。臀部向前弯曲，保持背部挺直，头部抬起。让杠铃悬挂在你面前，双臂完全伸展。将杠铃拉向胸部，保持肘部靠近身体。在动作的最高点将肩胛骨挤压在一起。将杠铃降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0589', 'lever one arm bent over row', 'back', '背部', '20', 'barbell', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip. Bend forward at the hips, keeping your back straight and your head up. Let the barbell hang in front of you with your arms fully extended. Pull the barbell up towards your chest, keeping your elbows close to your body. Squeeze your shoulder blades together at the top of the movement. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0589-Fhdtwf3.jpg', '/static/exercises/gifs/0589-Fhdtwf3.gif', '© Gym visual — https://gymvisual.com/', '161071'),
('101356', '器械单臂侧向高位划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度并将自己面向机器。用一只手抓住手柄并保持背部挺直。将手柄拉向身体，保持肘部靠近身体两侧。在动作的最高点挤压背部肌肉。慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1356', 'lever one arm lateral high row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Adjust the seat height and position yourself facing the machine. Grasp the handle with one hand and keep your back straight. Pull the handle towards your body, keeping your elbow close to your side. Squeeze your back muscles at the top of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1356-OIFMAp1.jpg', '/static/exercises/gifs/1356-OIFMAp1.gif', '© Gym visual — https://gymvisual.com/', '901372'),
('101347', '器械单臂侧向宽距下拉', '肱二头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。正手握住手柄，完全伸展手臂，保持肘部轻微弯曲。将手柄向下拉，穿过身体向对面的臀部方向拉，在动作底部挤压背阔肌。慢慢地将手柄返回到起始位置，完全伸展手臂。重复所需的重复次数，然后换边。', 'exercise-dataset', '1347', 'lever one arm lateral wide pulldown', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow. Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement. Slowly return the handle to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1347-tTuZSDT.jpg', '/static/exercises/gifs/1347-tTuZSDT.gif', '© Gym visual — https://gymvisual.com/', '81373'),
('100590', '器械单臂肩上推举', '肱三头肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。用一只手抓住杠杆手柄，并将肘部置于 90 度角。向上按下控制杆，直到手臂完全伸过头顶。在顶部暂停片刻，然后慢慢将控制杆放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '0590', 'lever one arm shoulder press', 'shoulders', '肩部', '30', 'leverage machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the lever handle with one hand and position your elbow at a 90-degree angle. Press the lever upward until your arm is fully extended overhead. Pause for a moment at the top, then slowly lower the lever back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/0590-2KGnL6M.jpg', '/static/exercises/gifs/0590-2KGnL6M.gif', '© Gym visual — https://gymvisual.com/', '1372'),
('100591', '器械正握肱三头肌臂屈伸', '胸肌', '固定器械', '未分级', '将机器调整到合适的高度并将身体固定到位。正手握住手柄，调整身体位置，使手臂完全伸展。弯曲肘部降低身体，保持上臂靠近身体两侧。继续降低，直到上臂与地板平行。暂停片刻，然后伸展肘部将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0591', 'lever overhand triceps dip', 'upper arms', '上臂', '50', 'leverage machine', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Adjust the machine to the appropriate height and secure your body in position. Grasp the handles with an overhand grip and position your body so that your arms are fully extended. Lower your body by bending your elbows, keeping your upper arms close to your sides. Continue lowering until your upper arms are parallel to the floor. Pause for a moment, then push yourself back up to the starting position by extending your elbows. Repeat for the desired number of repetitions.', '/static/exercises/images/0591-D5yqP2p.jpg', '/static/exercises/gifs/0591-D5yqP2p.gif', '© Gym visual — https://gymvisual.com/', '481371'),
('100592', '器械牧师凳弯举', '前臂', '固定器械', '未分级', '调整座椅高度并将自己放在杠杆机上。将上臂放在垫子上，并用反手握住手柄。保持背部挺直，并将肘部放在垫子上。呼气并将前臂向上臂弯曲，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0592', 'lever preacher curl', 'upper arms', '上臂', '50', 'leverage machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the seat height and position yourself on the leverage machine. Place your upper arms on the pad and grip the handles with an underhand grip. Keep your back straight and your elbows positioned on the pad. Exhale and curl your forearms towards your upper arms, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0592-b6hQYMb.jpg', '/static/exercises/gifs/0592-b6hQYMb.gif', '© Gym visual — https://gymvisual.com/', '81370'),
('101614', '器械牧师凳弯举版本第二式', '前臂', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，上臂放在垫子上，胸部靠在支撑物上。反手握住手柄，握距略宽于肩宽。保持上臂静止，呼气，同时将手柄向肩膀卷曲，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将手柄放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1614', 'lever preacher curl v. 2', 'upper arms', '上臂', '50', 'leverage machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart. Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale as you slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1614-ye84CTU.jpg', '/static/exercises/gifs/1614-ye84CTU.gif', '© Gym visual — https://gymvisual.com/', '81375'),
('102285', '器械上拉', '肱三头肌', '固定器械', '未分级', '将杠杆机的座椅和手柄调整到舒适的位置。坐在机器上，背部靠在垫子上，并用正手握住手柄。保持手臂稍微弯曲，核心肌群参与。慢慢地将手柄拉向胸部，挤压背阔肌。在收缩高峰时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2285', 'lever pullover', 'back', '背部', '20', 'leverage machine', 'triceps', 'lats', '背阔肌', '["肱三头肌","肩部"]', 'Adjust the seat and handles of the leverage machine to a comfortable position. Sit on the machine with your back against the pad and grasp the handles with an overhand grip. Keep your arms slightly bent and your core engaged. Slowly pull the handles towards your chest, squeezing your lats. Pause for a moment at the peak contraction, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2285-4U7iLb5.jpg', '/static/exercises/gifs/2285-4U7iLb5.gif', '© Gym visual — https://gymvisual.com/', '901370'),
('102736', '器械反向握侧向下拉', '肱二头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。正手握住手柄，握距略宽于肩宽。坐直，挺胸，肩膀向后，保持下背部轻微的拱形。将手柄向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2736', 'lever reverse grip lateral pulldown', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back. Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2736-ky8FLU8.jpg', '/static/exercises/gifs/2736-ky8FLU8.gif', '© Gym visual — https://gymvisual.com/', '81377'),
('101616', '器械反向握牧师凳弯举', '前臂', '固定器械', '未分级', '调整座椅高度并将自己放在杠杆机上。反手握住手柄，手掌朝上。将上臂放在牧师垫上，确保肘部完全伸展。保持上臂静止，呼气并将手柄卷向肩膀。在动作的最高点暂停片刻，挤压你的二头肌。吸气，慢慢将手柄放回起始位置，充分伸展肘部。重复所需的重复次数。', 'exercise-dataset', '1616', 'lever reverse grip preacher curl', 'upper arms', '上臂', '50', 'leverage machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the seat height and position yourself on the leverage machine. Grasp the handles with an underhand grip, palms facing up. Rest your upper arms on the preacher pad, ensuring your elbows are fully extended. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your elbows. Repeat for the desired number of repetitions.', '/static/exercises/images/1616-kj3hy6W.jpg', '/static/exercises/gifs/1616-kj3hy6W.gif', '© Gym visual — https://gymvisual.com/', '81378'),
('101348', '器械反向握垂直划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度和踏板位置以确保正确对齐。坐在机器上，胸部靠在垫子上，双脚平放在踏板上。反手握住手柄，手掌朝上。保持背部挺直并启动核心肌群。将手柄拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1348', 'lever reverse grip vertical row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an underhand grip, palms facing up. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1348-ZqNOWQ6.jpg', '/static/exercises/gifs/1348-ZqNOWQ6.gif', '© Gym visual — https://gymvisual.com/', '901379'),
('100593', '器械反向超伸展', '腘绳肌', '固定器械', '未分级', '调整杠杆机以适合您的身体并将双脚固定在脚垫中。面朝下躺在机器上，上半身悬在机器边缘，臀部放在垫子上。双臂交叉放在胸前或放在脑后。用臀部和腿筋将双腿向上抬起，直到它们与地面平行。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0593', 'lever reverse hyperextension', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Adjust the leverage machine to fit your body and secure your feet in the foot pads. Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad. Cross your arms over your chest or place them behind your head. Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0593-Krmb3cB.jpg', '/static/exercises/gifs/0593-Krmb3cB.gif', '© Gym visual — https://gymvisual.com/', '901376'),
('101349', '器械反向T杠划船', '肱二头肌', '固定器械', '未分级', '调整杠杆机上的座椅高度和踏板位置。坐在机器上，胸部靠在垫子上，双脚平放在踏板上。正手握住手柄，握距略宽于肩宽。保持背部挺直并启动核心肌群。将手柄拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1349', 'lever reverse t-bar row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footplate position on the leverage machine. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1349-BgljGjd.jpg', '/static/exercises/gifs/1349-BgljGjd.gif', '© Gym visual — https://gymvisual.com/', '321379'),
('102315', '器械旋转式小腿', '比目鱼肌', '固定器械', '未分级', '调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。将脚趾放在踏板上，脚跟悬在踏板边缘。抓住机器的手柄或侧面以保持稳定性。用脚掌推动，尽可能高地抬高脚后跟。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2315', 'lever rotary calf', 'lower legs', '小腿', '70', 'leverage machine', 'soleus', 'calves', '小腿肌群', '["比目鱼肌","踝关节稳定肌"]', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate. Place your toes on the footplate, with your heels hanging off the edge. Grasp the handles or the sides of the machine for stability. Push through the balls of your feet, raising your heels as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2315-MrgP9L6.jpg', '/static/exercises/gifs/2315-MrgP9L6.gif', '© Gym visual — https://gymvisual.com/', '901378'),
('102335', '器械坐姿小腿推举', '比目鱼肌', '固定器械', '未分级', '调整机器的座椅，使您的肩膀与杠杆垫对齐。将脚趾放在平台的下部，并将膝盖放在杠杆垫下方。抓住座椅两侧的把手以保持稳定性。伸展脚踝，将杠杆垫压下，尽可能高地抬起脚后跟。在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2335', 'lever seated calf press', 'lower legs', '小腿', '70', 'leverage machine', 'soleus', 'calves', '小腿肌群', '["比目鱼肌","腘绳肌"]', 'Adjust the seat of the machine so that your shoulders are aligned with the lever pad. Place your toes on the lower portion of the platform and position your knees under the lever pad. Grasp the handles on the sides of the seat for stability. Press the lever pad down by extending your ankles, lifting your heels as high as possible. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2335-Ie9UGty.jpg', '/static/exercises/gifs/2335-Ie9UGty.gif', '© Gym visual — https://gymvisual.com/', '901381'),
('100594', '器械坐姿提踵', '比目鱼肌', '固定器械', '未分级', '调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。将脚趾放在踏板上，脚跟悬在踏板边缘。抓住把手或座椅侧面以保持稳定性。推动脚掌，将脚后跟尽可能抬高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0594', 'lever seated calf raise', 'lower legs', '小腿', '70', 'leverage machine', 'soleus', 'calves', '小腿肌群', '["比目鱼肌","踝关节稳定肌"]', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate. Place your toes on the footplate with your heels hanging off the edge. Grasp the handles or the sides of the seat for stability. Push through the balls of your feet to raise your heels as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0594-bOOdeyc.jpg', '/static/exercises/gifs/0594-bOOdeyc.gif', '© Gym visual — https://gymvisual.com/', '1382'),
('101452', '器械坐姿卷腹', '腹斜肌', '固定器械', '未分级', '坐在杠杆机上，背部靠在垫子上，双脚平放在地板上。抓住手柄或将手放在侧垫上以获得支撑。收紧腹肌并慢慢向后倾斜，让垫子随着您一起移动。一旦你的上半身呈 45 度角，收缩腹肌并向前卷腹，使胸部靠近膝盖。在顶部停顿片刻，然后慢慢松开并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1452', 'lever seated crunch', 'waist', '腰腹', '60', 'leverage machine', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on the leverage machine with your back against the pad and your feet flat on the floor. Grasp the handles or place your hands on the side pads for support. Engage your abs and slowly lean back, allowing the pad to move with you. Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1452-Wgaz7pm.jpg', '/static/exercises/gifs/1452-Wgaz7pm.gif', '© Gym visual — https://gymvisual.com/', '81381'),
('100595', '器械坐姿卷腹胸部垫上', '腹斜肌', '固定器械', '未分级', '根据您的舒适度调整座椅高度和胸垫位置。坐在机器上，背部靠在胸垫上，双脚平放在地板上。抓住手柄或侧杆以保持稳定性。收紧腹肌并慢慢向后倾斜，让胸垫随着您一起移动。在最大收缩时暂停片刻，感受腹肌的紧张感。收缩腹肌并将自己拉回来，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0595', 'lever seated crunch (chest pad)', 'waist', '腰腹', '60', 'leverage machine', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Adjust the seat height and chest pad position according to your comfort. Sit on the machine with your back against the chest pad and your feet flat on the floor. Grasp the handles or side bars for stability. Engage your abs and slowly lean back, allowing the chest pad to move with you. Pause for a moment at the maximum contraction, feeling the tension in your abs. Slowly return to the starting position by contracting your abs and pulling yourself back up. Repeat for the desired number of repetitions.', '/static/exercises/images/0595-ZnJHhMk.jpg', '/static/exercises/gifs/0595-ZnJHhMk.gif', '© Gym visual — https://gymvisual.com/', '81386'),
('103760', '器械坐姿卷腹版本第二式', '腹斜肌', '固定器械', '未分级', '坐在杠杆机上，背部靠在垫子上，双脚固定在脚垫下。将手放在把手上或座椅两侧以获得支撑。收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。在动作的最高点暂停片刻，挤压腹肌。慢慢回到起始位置，让背部稍微弯曲。重复所需的重复次数。', 'exercise-dataset', '3760', 'lever seated crunch v. 2', 'waist', '腰腹', '60', 'leverage machine', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Sit on the leverage machine with your back against the pad and your feet secured under the footpads. Place your hands on the handles or the sides of the seat for support. Engage your abs and slowly crunch forward, bringing your chest towards your knees. Pause for a moment at the top of the movement, squeezing your abs. Slowly return to the starting position, allowing your back to round slightly. Repeat for the desired number of repetitions.', '/static/exercises/images/3760-eXFXCY0.jpg', '/static/exercises/gifs/3760-eXFXCY0.gif', '© Gym visual — https://gymvisual.com/', '81387'),
('101451', '器械坐姿臂屈伸', '胸肌', '固定器械', '未分级', '调整座椅高度，使双脚平放在地面上，膝盖呈 90 度角。手掌朝下，抓住杠杆机的手柄，双臂完全伸展。弯曲肘部，慢慢降低身体，直到上臂与地面平行。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '1451', 'lever seated dip', 'upper arms', '上臂', '50', 'leverage machine', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle. Grasp the handles of the leverage machine with your palms facing down and your arms fully extended. Slowly lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1451-BRImeP8.jpg', '/static/exercises/gifs/1451-BRImeP8.gif', '© Gym visual — https://gymvisual.com/', '481384'),
('100596', '器械坐姿飞鸟', '三角肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。旋前抓住手柄，并保持肘部稍微弯曲。呼气并将手柄向前推，将它们放在胸前。暂停片刻，挤压胸部肌肉。吸气并慢慢回到起始位置，让胸部肌肉伸展。重复所需的重复次数。', 'exercise-dataset', '0596', 'lever seated fly', 'chest', '胸部', '10', 'leverage machine', 'deltoids', 'pectorals', '胸肌', '["三角肌","斜方肌"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with a pronated grip and keep your elbows slightly bent. Exhale and push the handles forward, bringing them together in front of your chest. Pause for a moment, squeezing your chest muscles. Inhale and slowly return to the starting position, allowing your chest muscles to stretch. Repeat for the desired number of repetitions.', '/static/exercises/images/0596-v3xmPAR.jpg', '/static/exercises/gifs/0596-v3xmPAR.gif', '© Gym visual — https://gymvisual.com/', '901385'),
('103759', '器械坐姿早安式', '腘绳肌', '固定器械', '未分级', '调整座椅高度，使臀部略高于膝盖。坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。抓住把手或座椅侧面以保持稳定性。保持背部挺直，从臀部开始慢慢向前倾斜，直到上半身与地面平行。暂停片刻，然后通过推动臀肌和腿筋慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3759', 'lever seated good morning', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Adjust the seat height so that your hips are slightly higher than your knees. Sit on the machine with your back against the pad and your feet flat on the footrests. Grasp the handles or the sides of the seat for stability. Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground. Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings. Repeat for the desired number of repetitions.', '/static/exercises/images/3759-XsCcxCC.jpg', '/static/exercises/gifs/3759-XsCcxCC.gif', '© Gym visual — https://gymvisual.com/', '901388'),
('100597', '器械坐姿髋外展', '臀肌', '固定器械', '未分级', '调整座椅高度，使膝盖成 90 度角。坐在机器上，背部靠在靠背上，双脚放在脚踏板上。将手放在侧手柄上以保持稳定性。启动外展肌并慢慢将双腿分开，远离身体中线。动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0597', 'lever seated hip abduction', 'upper legs', '大腿', '40', 'leverage machine', 'glutes', 'abductors', '外展肌群', '["臀肌","腘绳肌"]', 'Adjust the seat height so that your knees are at a 90-degree angle. Sit on the machine with your back against the backrest and your feet on the footrests. Place your hands on the side handles for stability. Engage your abductors and slowly push your legs apart, away from the midline of your body. Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0597-CHpahtl.jpg', '/static/exercises/gifs/0597-CHpahtl.gif', '© Gym visual — https://gymvisual.com/', '901389'),
('100598', '器械坐姿髋内收', '腘绳肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在靠背上。将脚放在脚踏板上并抓住手柄以保持稳定。收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。在收缩高峰时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0598', 'lever seated hip adduction', 'upper legs', '大腿', '40', 'leverage machine', 'hamstrings', 'adductors', '内收肌群', '["腘绳肌","臀肌"]', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Place your feet on the footrests and grasp the handles for stability. Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs. Pause for a moment at the peak contraction, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0598-oHsrypV.jpg', '/static/exercises/gifs/0598-oHsrypV.gif', '© Gym visual — https://gymvisual.com/', '901390'),
('100599', '器械坐姿腿弯举', '小腿肌群', '固定器械', '未分级', '调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。将小腿放在带衬垫的杠杆下方，就在脚踝上方。抓住机器两侧的手柄以提供支撑。保持大腿不动，呼气并尽可能向上弯曲双腿。挤压腿筋时，保持收缩位置短暂停顿。吸气并缓慢地将控制杆降低回起始位置。重复所需的重复次数。', 'exercise-dataset', '0599', 'lever seated leg curl', 'upper legs', '大腿', '40', 'leverage machine', 'calves', 'hamstrings', '腘绳肌', '["小腿肌群"]', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your lower legs under the padded lever, just above your ankles. Grasp the handles on the sides of the machine for support. Keeping your upper legs stationary, exhale and curl your legs up as far as possible. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0599-Zg3XY7P.jpg', '/static/exercises/gifs/0599-Zg3XY7P.gif', '© Gym visual — https://gymvisual.com/', '481391'),
('100600', '器械坐姿举腿卷腹', '髋屈肌', '固定器械', '未分级', '坐在杠杆机上，背部靠在靠背上，双脚放在脚踏板上。抓住手柄或侧杆以保持稳定性。收紧腹肌，慢慢地将双腿抬向胸部，同时向前卷曲躯干。在顶部停顿片刻，然后慢慢降低双腿和躯干回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0600', 'lever seated leg raise crunch', 'waist', '腰腹', '60', 'leverage machine', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the leverage machine with your back against the backrest and your feet on the footrests. Grasp the handles or sidebars for stability. Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time. Pause for a moment at the top, then slowly lower your legs and torso back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0600-PQ2AtC3.jpg', '/static/exercises/gifs/0600-PQ2AtC3.gif', '© Gym visual — https://gymvisual.com/', '81394'),
('100602', '器械坐姿反向飞鸟', '斜方肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。正手握住手柄，并保持手臂稍微弯曲。呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0602', 'lever seated reverse fly', 'shoulders', '肩部', '30', 'leverage machine', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and keep your arms slightly bent. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0602-myfUsKf.jpg', '/static/exercises/gifs/0602-myfUsKf.gif', '© Gym visual — https://gymvisual.com/', '321393'),
('100601', '器械坐姿反向飞鸟平行握握', '斜方肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。平行握住手柄，手掌相对，并保持手臂稍微弯曲。呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0601', 'lever seated reverse fly (parallel grip)', 'shoulders', '肩部', '30', 'leverage machine', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0601-xiHiJcA.jpg', '/static/exercises/gifs/0601-xiHiJcA.gif', '© Gym visual — https://gymvisual.com/', '321398'),
('101350', '器械坐姿划船', '肱二头肌', '固定器械', '未分级', '将座椅高度和脚踏板调整到舒适的位置。坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。正手握住手柄，距离与肩同宽。保持背部挺直，核心肌群参与。将手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻。慢慢松开手柄并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1350', 'lever seated row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footrests to a comfortable position. Sit on the machine with your chest against the pad and your feet on the footrests. Grasp the handles with an overhand grip, shoulder-width apart. Keep your back straight and your core engaged. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1350-7I6LNUG.jpg', '/static/exercises/gifs/1350-7I6LNUG.gif', '© Gym visual — https://gymvisual.com/', '241393'),
('101385', '器械坐姿深蹲提踵腿举器械', '股四头肌', '固定器械', '未分级', '调整压腿机的座椅，使双脚放在踏板上时膝盖稍微弯曲。坐在机器上，背部靠在靠背上，双脚平放在踏板上，与肩同宽。将脚趾和脚掌放在踏板上，使脚后跟远离边缘。松开安全手柄，并通过伸展膝盖将踏板推离您。一旦膝盖完全伸展，弯曲小腿，慢慢降低脚后跟。在底部停顿片刻，然后通过伸展小腿将踏板向后推。重复所需的重复次数。', 'exercise-dataset', '1385', 'lever seated squat calf raise on leg press machine', 'lower legs', '小腿', '70', 'leverage machine', 'quadriceps', 'calves', '小腿肌群', '["股四头肌","腘绳肌","臀肌"]', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate. Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart. Place your toes and the balls of your feet on the footplate, keeping your heels off the edge. Release the safety handles and push the footplate away from you by extending your knees. Once your knees are fully extended, slowly lower your heels by flexing your calves. Pause for a moment at the bottom, then push the footplate back up by extending your calves. Repeat for the desired number of repetitions.', '/static/exercises/images/1385-IeDEXTe.jpg', '/static/exercises/gifs/1385-IeDEXTe.gif', '© Gym visual — https://gymvisual.com/', '1406'),
('100603', '器械肩上推举', '肱三头肌', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在靠背上。正手握住手柄，并将双手置于肩部水平。向上推动手柄，直到手臂完全伸展，但不要锁住肘部。在顶部暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0603', 'lever shoulder press', 'shoulders', '肩部', '30', 'leverage machine', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Grasp the handles with an overhand grip and position your hands at shoulder level. Push the handles upward until your arms are fully extended, but do not lock your elbows. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0603-67n3r98.jpg', '/static/exercises/gifs/0603-67n3r98.gif', '© Gym visual — https://gymvisual.com/', '1395'),
('100869', '器械肩上推举版本第二式', '肱三头肌', '固定器械', '未分级', '将杠杆机的座椅高度和靠背调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚平放在地板上。正手握住机器的手柄，握距略宽于肩宽。向上和向前推动手柄，直到手臂完全伸展，但未锁定。在顶部暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0869', 'lever shoulder press v. 2', 'shoulders', '肩部', '30', 'leverage machine', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart. Push the handles upward and forward until your arms are fully extended, but not locked. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0869-vqsbmL0.jpg', '/static/exercises/gifs/0869-vqsbmL0.gif', '© Gym visual — https://gymvisual.com/', '1400'),
('102318', '器械肩上推举版本第三式', '肱三头肌', '固定器械', '未分级', '将杠杆机的座椅高度和靠背调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚平放在地板上。正手握住机器的手柄，握距略宽于肩宽。向上和向前推动手柄，直到手臂完全伸展，但未锁定。在顶部暂停片刻，然后慢慢将手柄放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2318', 'lever shoulder press v. 3', 'shoulders', '肩部', '30', 'leverage machine', 'triceps', 'delts', '三角肌', '["肱三头肌","胸肌"]', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart. Push the handles upward and forward until your arms are fully extended, but not locked. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2318-dNFYIU1.jpg', '/static/exercises/gifs/2318-dNFYIU1.gif', '© Gym visual — https://gymvisual.com/', '1401'),
('100604', '器械耸肩', '肩部', '固定器械', '未分级', '调整座椅高度，将自己放在杠杆机上，背部靠在垫子上。正手握住手柄并保持手臂伸直。保持背部挺直，将肩膀尽可能高地抬向耳朵。保持收缩一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0604', 'lever shrug', 'back', '背部', '20', 'leverage machine', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Adjust the seat height and position yourself on the leverage machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Keeping your back straight, lift your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0604-ZZKbeMw.jpg', '/static/exercises/gifs/0604-ZZKbeMw.gif', '© Gym visual — https://gymvisual.com/', '561396'),
('100605', '器械站姿提踵', '比目鱼肌', '固定器械', '未分级', '将机器调整到您的高度，双脚分开与肩同宽站立。将肩膀放在护垫下方，并握住手柄以保持稳定。伸展脚踝，将脚后跟尽可能抬高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0605', 'lever standing calf raise', 'lower legs', '小腿', '70', 'leverage machine', 'soleus', 'calves', '小腿肌群', '["比目鱼肌","踝关节稳定肌"]', 'Adjust the machine to your height and stand with your feet shoulder-width apart. Place your shoulders under the pads and hold onto the handles for stability. Raise your heels as high as possible by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0605-ykUOVze.jpg', '/static/exercises/gifs/0605-ykUOVze.gif', '© Gym visual — https://gymvisual.com/', '1401'),
('103758', '器械站姿胸推', '肩部', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，双脚平放在地面上。正手握住手柄，并将双手置于胸部水平。向前推动手柄，直到手臂完全伸展，保持肘部稍微弯曲。暂停片刻，然后慢慢地将手柄拉回到胸部，在整个动作过程中保持控制。重复所需的重复次数。', 'exercise-dataset', '3758', 'lever standing chest press', 'chest', '胸部', '10', 'leverage machine', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the seat height and position yourself on the machine with your feet flat on the ground. Grasp the handles with an overhand grip and position your hands at chest level. Push the handles forward until your arms are fully extended, keeping your elbows slightly bent. Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/3758-WbNq5Xu.jpg', '/static/exercises/gifs/3758-WbNq5Xu.gif', '© Gym visual — https://gymvisual.com/', '161402'),
('100606', '器械T杠划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度和踏板位置以确保正确对齐。坐在机器上，胸部靠在垫子上，双脚平放在踏板上。正手握住手柄，握距略宽于肩宽。保持背部挺直并启动核心肌群。将手柄拉向躯干，将肩胛骨挤压在一起。在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0606', 'lever t bar row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your torso, squeezing your shoulder blades together. Pause for a moment at the peak contraction, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0606-aaXr7ld.jpg', '/static/exercises/gifs/0606-aaXr7ld.gif', '© Gym visual — https://gymvisual.com/', '901403'),
('101351', '器械T字杆反向握划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。正手握住手柄，握距略宽于肩宽。保持背部挺直并启动核心肌群。将手柄拉向胸部，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1351', 'lever t-bar reverse grip row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1351-FVM1AUZ.jpg', '/static/exercises/gifs/1351-FVM1AUZ.gif', '© Gym visual — https://gymvisual.com/', '901406'),
('100607', '器械肱三头肌臂屈伸', '肩部', '固定器械', '未分级', '调整座椅高度并将自己放在机器上，背部靠在垫子上。正手握住手柄，并将手臂完全伸展到身前。保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。在底部暂停片刻，然后伸展双臂将手柄推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0607', 'lever triceps extension', 'upper arms', '上臂', '50', 'leverage machine', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and fully extend your arms in front of you. Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows. Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0607-Ser9eQp.jpg', '/static/exercises/gifs/0607-Ser9eQp.gif', '© Gym visual — https://gymvisual.com/', '401403'),
('101313', '器械单侧划船', '肱二头肌', '固定器械', '未分级', '调整座椅高度并将自己面向机器。正手握住手柄并保持背部挺直。将手柄拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1313', 'lever unilateral row', 'back', '背部', '20', 'leverage machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the seat height and position yourself facing the machine. Grasp the handles with an overhand grip and keep your back straight. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1313-oROuvrX.jpg', '/static/exercises/gifs/1313-oROuvrX.gif', '© Gym visual — https://gymvisual.com/', '901404'),
('100609', '伦敦式桥式', '肩部', '绳索', '未分级', '将绳子连接到高锚点。背对锚点站立，双脚与肩同宽。正手握住绳子，手掌朝下。稍微向前倾，保持背部挺直，核心参与。将绳子拉向身体，将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0609', 'london bridge', 'back', '背部', '20', 'rope', 'shoulders', 'upper back', '上背部', '["肩部","肱二头肌","前臂"]', 'Attach the rope to a high anchor point. Stand facing away from the anchor point with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing down. Lean forward slightly, keeping your back straight and core engaged. Pull the rope towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0609-bLyQokI.jpg', '/static/exercises/gifs/0609-bLyQokI.gif', '© Gym visual — https://gymvisual.com/', '901903'),
('103013', '低位臀桥地板', '腘绳肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将手臂放在身体两侧，手掌朝下。启动臀肌和核心肌群，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。在顶部暂停片刻，挤压臀部。慢慢地将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3013', 'low glute bridge on floor', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","核心肌群"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your arms by your sides, palms facing down. Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3013-u0cNiij.jpg', '/static/exercises/gifs/3013-u0cNiij.gif', '© Gym visual — https://gymvisual.com/', '641010'),
('101352', '下部后侧弯举', '臀肌', '自重', '未分级', '平躺，双腿伸直，双臂放在身体两侧。收紧臀肌和腿筋，慢慢将上半身抬离地面，向上弯曲背部。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1352', 'lower back curl', 'back', '背部', '20', 'body weight', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Lie flat on your stomach with your legs extended and your arms by your sides. Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1352-ANbbry2.jpg', '/static/exercises/gifs/1352-ANbbry2.gif', '© Gym visual — https://gymvisual.com/', '901007'),
('103582', '弓步跳跃', '股四头肌', '自重', '未分级', '首先站立，双脚分开与肩同宽。右脚向前迈出一步，将身体降低至弓步位置。右脚蹬地，跳到空中，在空中改变脚的位置。左脚向前轻柔落地，并立即将身体降低至弓步位置。继续在弓步和跳跃之间交替进行所需的重复次数。', 'exercise-dataset', '3582', 'lunge with jump', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing with your feet shoulder-width apart. Take a step forward with your right foot, lowering your body into a lunge position. Push off with your right foot and jump into the air, switching the position of your feet mid-air. Land softly with your left foot forward and immediately lower your body into a lunge position. Continue alternating between lunges and jumps for the desired number of repetitions.', '/static/exercises/images/3582-PM1PZjg.jpg', '/static/exercises/gifs/3582-PM1PZjg.gif', '© Gym visual — https://gymvisual.com/', '321008'),
('101688', '弓步转体', '股四头肌', '自重', '未分级', '首先站立，双脚分开与肩同宽。右脚向前迈出一步，将身体降低至弓步位置。当你弓步时，将你的躯干向右扭转，将你的左肘拉向你的右膝盖。暂停片刻，然后回到起始位置。在另一侧重复，左脚向前迈出，并将躯干向左扭转。继续交替进行所需的重复次数。', 'exercise-dataset', '1688', 'lunge with twist', 'waist', '腰腹', '60', 'body weight', 'quadriceps', 'abs', '腹肌', '["股四头肌","臀肌","腘绳肌"]', 'Start by standing with your feet shoulder-width apart. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge, twist your torso to the right, bringing your left elbow towards your right knee. Pause for a moment, then return to the starting position. Repeat on the other side, stepping forward with your left foot and twisting your torso to the left. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1688-K9VL0Jq.jpg', '/static/exercises/gifs/1688-K9VL0Jq.gif', '© Gym visual — https://gymvisual.com/', '901009'),
('100613', '仰卧侧向股四头肌拉伸', '腘绳肌', '自重', '未分级', '侧躺，双腿伸直。弯曲上面的那条腿，用手抓住脚踝或脚。轻轻地将脚踝或脚拉向臀部，直到感觉到股四头肌有拉伸感。保持拉伸 20-30 秒。松开拉伸并在另一侧重复。', 'exercise-dataset', '0613', 'lying (side) quads stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'quads', '股四头肌', '["腘绳肌"]', 'Lie on your side with your legs straight. Bend your top leg and grab your ankle or foot with your hand. Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other side.', '/static/exercises/images/0613-BWnJR72.jpg', '/static/exercises/gifs/0613-BWnJR72.gif', '© Gym visual — https://gymvisual.com/', '901012'),
('102312', '仰卧肘膝', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。同时，将右腿伸直并抬离地面。暂停片刻，然后回到起始位置。重复该动作，这次将左肘移向右膝盖并伸展左腿。继续交替进行所需的重复次数。', 'exercise-dataset', '2312', 'lying elbow to knee', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee. At the same time, extend your right leg straight out and lift it off the ground. Pause for a moment, then return to the starting position. Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2312-AQIhRjM.jpg', '/static/exercises/gifs/2312-AQIhRjM.gif', '© Gym visual — https://gymvisual.com/', '901013'),
('100620', '仰卧举腿平凳训练凳', '髋屈肌', '自重', '未分级', '平躺在平坦的长凳上，背部紧贴长凳。将双手放在臀部下方以获得支撑。保持双腿伸直并拢，然后将它们抬向天花板。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0620', 'lying leg raise flat bench', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on a flat bench with your back pressed against it. Place your hands under your glutes for support. Keep your legs straight and together, and lift them up towards the ceiling. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0620-WhuFnR7.jpg', '/static/exercises/gifs/0620-WhuFnR7.gif', '© Gym visual — https://gymvisual.com/', '241016'),
('100865', '仰卧腿髋部上举', '髋屈肌', '自重', '未分级', '平躺，双腿伸展，双臂放在身体两侧。将双手放在臀部下方以获得支撑。启动你的核心并将双腿抬离地面，将它们抬向天花板。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0865', 'lying leg-hip raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your core and lift your legs off the ground, raising them towards the ceiling. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0865-9IxJdtC.jpg', '/static/exercises/gifs/0865-9IxJdtC.gif', '© Gym visual — https://gymvisual.com/', '901013'),
('101301', '器械内侧胸推', '肱三头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，背部平放在垫子上。正手握住手柄，肘部呈 90 度角。向前推动手柄，直到手臂完全伸展，运动过程中呼气。动作结束时暂停片刻，然后慢慢回到起始位置，同时吸气。重复所需的重复次数。', 'exercise-dataset', '1301', 'machine inner chest press', 'chest', '胸部', '10', 'leverage machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', '/static/exercises/images/1301-wDN97Ca.jpg', '/static/exercises/gifs/1301-wDN97Ca.gif', '© Gym visual — https://gymvisual.com/', '161416'),
('100624', '原地踏步坐靠墙', '股四头肌', '自重', '未分级', '背靠墙站立，双脚分开与臀部同宽。慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。将右脚抬离地面，并将膝盖靠近胸部。将右脚放低，将左脚抬离地面，将膝盖靠近胸部。继续交替抬起右脚和左脚，达到所需的重复次数。', 'exercise-dataset', '0624', 'march sit (wall)', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your back against a wall and your feet hip-width apart. Slowly slide your back down the wall until your knees are bent at a 90-degree angle. Lift your right foot off the ground and bring your knee towards your chest. Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest. Continue alternating between lifting your right and left foot for the desired number of repetitions.', '/static/exercises/images/0624-sVQCCeG.jpg', '/static/exercises/gifs/0624-sVQCCeG.gif', '© Gym visual — https://gymvisual.com/', '901015'),
('101353', '药球接杠过顶抛下抗阻', '肩部', '药球', '未分级', '双脚分开与肩同宽站立，双手握住健身球，与胸部齐平。稍微弯曲膝盖并启动核心。将身体降低至蹲姿，保持背部挺直、挺胸。爆发性伸展臀部和腿部，同时将药球扔过头顶。在动作的最高点释放球并在下降的过程中接住它。将身体放回蹲姿，然后重复所需的重复次数。', 'exercise-dataset', '1353', 'medicine ball catch and overhead throw', 'back', '背部', '20', 'medicine ball', 'shoulders', 'lats', '背阔肌', '["肩部","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level. Bend your knees slightly and engage your core. Lower your body into a squat position, keeping your back straight and chest up. Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead. Release the ball at the top of the movement and catch it on the way down. Lower your body back into the squat position and repeat for the desired number of repetitions.', '/static/exercises/images/1353-PsVS1QP.jpg', '/static/exercises/gifs/1353-PsVS1QP.gif', '© Gym visual — https://gymvisual.com/', '901922'),
('101302', '药球胸部传递', '肩部', '药球', '未分级', '双脚分开与肩同宽站立，将健身球保持在胸部水平。向前伸展双臂，用力将药球推离胸部。当你释放球时，用你的手臂和躯干将球从后脚转移到前脚。当球从墙壁或伙伴身上反弹时接住球，并立即重复该动作。继续进行所需的重复次数。', 'exercise-dataset', '1302', 'medicine ball chest pass', 'chest', '胸部', '10', 'medicine ball', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Stand with your feet shoulder-width apart, holding the medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest with force. As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot. Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement. Continue for the desired number of repetitions.', '/static/exercises/images/1302-aDoFKrE.jpg', '/static/exercises/gifs/1302-aDoFKrE.gif', '© Gym visual — https://gymvisual.com/', '901919'),
('101303', '药球胸部推从第三式点支撑站姿', '肩部', '药球', '未分级', '以三点姿势开始，一只手放在健身球上，另一只手放在地上。伸展双腿并将身体摆成一条直线。将胸部压向地面，同时保持背部挺直。将药球推离身体，完全伸展手臂。返回起始位置并重复所需的重复次数。', 'exercise-dataset', '1303', 'medicine ball chest push from 3 point stance', 'chest', '胸部', '10', 'medicine ball', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground. Extend your legs and position your body in a straight line. Lower your chest towards the ground while keeping your back straight. Push the medicine ball away from your body, extending your arm fully. Return to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/1303-dCJnuVq.jpg', '/static/exercises/gifs/1303-dCJnuVq.gif', '© Gym visual — https://gymvisual.com/', '901928'),
('101304', '药球胸部推多次反应', '肱三头肌', '药球', '未分级', '双脚分开与肩同宽站立，将药球举至胸部水平。向前伸展双臂，将药球推离胸部。暂停片刻，然后慢慢地将健身球放回胸前。重复所需的重复次数。', 'exercise-dataset', '1304', 'medicine ball chest push multiple response', 'chest', '胸部', '10', 'medicine ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest. Pause for a moment, then slowly bring the medicine ball back to your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/1304-7aolH9D.jpg', '/static/exercises/gifs/1304-7aolH9D.gif', '© Gym visual — https://gymvisual.com/', '901925'),
('101305', '药球胸部推单侧反应', '肱三头肌', '药球', '未分级', '双脚分开与肩同宽站立，将健身球保持在胸部水平。向前伸展双臂，将药球推离胸部。暂停片刻，然后慢慢地将健身球放回胸前。重复所需的重复次数。', 'exercise-dataset', '1305', 'medicine ball chest push single response', 'chest', '胸部', '10', 'medicine ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Stand with your feet shoulder-width apart, holding the medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest. Pause for a moment, then slowly bring the medicine ball back to your chest. Repeat for the desired number of repetitions.', '/static/exercises/images/1305-jeHtrlO.jpg', '/static/exercises/gifs/1305-jeHtrlO.gif', '© Gym visual — https://gymvisual.com/', '901926'),
('101312', '药球胸部推跑放手', '肱三头肌', '药球', '未分级', '双脚分开与肩同宽站立，将药球举至胸部水平。右脚向前迈出一步，同时向前推动药球，充分伸展双臂。当你向前推动球时，松开它并让它向前滚动。快速向前跑，在球落地之前接住球。接住球后，将其放回胸前，左脚向前重复该动作。继续交替双腿并重复练习达到所需的重复次数。', 'exercise-dataset', '1312', 'medicine ball chest push with run release', 'chest', '胸部', '10', 'medicine ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level. Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully. As you push the ball forward, release it and let it roll forward. Quickly run forward and catch the ball before it hits the ground. Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward. Continue alternating legs and repeating the exercise for the desired number of repetitions.', '/static/exercises/images/1312-pX9Elbe.jpg', '/static/exercises/gifs/1312-pX9Elbe.gif', '© Gym visual — https://gymvisual.com/', '901929'),
('101701', '药球窄距握俯卧撑', '胸肌', '药球', '未分级', '从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。推回起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1701', 'medicine ball close grip push up', 'upper arms', '上臂', '50', 'medicine ball', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Push back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1701-8K7m2SS.jpg', '/static/exercises/gifs/1701-8K7m2SS.gif', '© Gym visual — https://gymvisual.com/', '901928'),
('101354', '药球过顶砸球', '肩部', '药球', '未分级', '双脚分开与肩同宽站立，双手握住药球举过头顶。启动你的核心并保持背部挺直。稍微弯曲膝盖，用力将药球摔到你面前的地面上。当你击球时，用你的整个身体来产生力量，包括你的肩膀和核心。接住球的弹跳并重复所需的重复次数。', 'exercise-dataset', '1354', 'medicine ball overhead slam', 'back', '背部', '20', 'medicine ball', 'shoulders', 'upper back', '上背部', '["肩部","核心肌群"]', 'Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head. Engage your core and keep your back straight. Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you. As you slam the ball down, use your entire body to generate power, including your shoulders and core. Catch the ball on the bounce and repeat for the desired number of repetitions.', '/static/exercises/images/1354-oHg8eop.jpg', '/static/exercises/gifs/1354-oHg8eop.gif', '© Gym visual — https://gymvisual.com/', '901925'),
('101750', '药球仰卧胸部抛下抗阻', '胸肌', '药球', '未分级', '平躺在长凳上，膝盖弯曲，双脚平放在地上。双手握住药球，将手臂伸直至胸部上方。将健身球降低到胸部，保持肘部靠近身体。爆发性地将药球向上推，充分伸展双臂并将球扔得尽可能高。接住药球并重复所需的重复次数。', 'exercise-dataset', '1750', 'medicine ball supine chest throw', 'upper arms', '上臂', '50', 'medicine ball', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Lie flat on your back on a bench with your knees bent and feet flat on the ground. Hold the medicine ball with both hands, extending your arms straight up above your chest. Lower the medicine ball towards your chest, keeping your elbows close to your body. Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible. Catch the medicine ball and repeat for the desired number of repetitions.', '/static/exercises/images/1750-Al3tP0D.jpg', '/static/exercises/gifs/1750-Al3tP0D.gif', '© Gym visual — https://gymvisual.com/', '901928'),
('100627', '混合握法握反手引体向上', '肱二头肌', '自重', '未分级', '反握（手掌朝向自己）抓住引体向上杆，双手之间的距离略大于肩宽。悬挂在杠上，双臂完全伸展，双脚离开地面。调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0627', 'mixed grip chin-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', '/static/exercises/images/0627-T8UpLkb.jpg', '/static/exercises/gifs/0627-T8UpLkb.gif', '© Gym visual — https://gymvisual.com/', '901025'),
('103217', '改良式印度式俯卧撑（男）', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚分开与臀部同宽。将身体向地面降低，弯曲肘部并保持核心参与。当你降低身体时，将你的重心向后转移，并将臀部向上抬向天花板，与你的身体形成一个倒V形。继续降低身体，直到胸部刚好高于地面，然后反向运动，将臀部向下推，并伸展手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3217', 'modified hindu push-up (male)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart. Lower your body towards the ground, bending your elbows and keeping your core engaged. As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body. Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3217-epOSYUZ.jpg', '/static/exercises/gifs/3217-epOSYUZ.gif', '© Gym visual — https://gymvisual.com/', '81028'),
('101421', '改良式俯卧撑下部双臂', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。暂停片刻，然后用手掌推动前臂，使其回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1421', 'modified push up to lower arms', 'lower arms', '前臂', '80', 'body weight', 'triceps', 'forearms', '前臂肌群', '["肱三头肌","胸肌","肩部"]', 'Start in a push-up position with your hands directly under your shoulders and your body in a straight line. Lower your body down towards the ground by bending your elbows, keeping them close to your sides. Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders. Pause for a moment, then push through your palms to lift your forearms back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1421-arvaszz.jpg', '/static/exercises/gifs/1421-arvaszz.gif', '© Gym visual — https://gymvisual.com/', '901033'),
('100628', '怪兽式行走', '腘绳肌', '自重', '未分级', '在脚踝周围放置一根阻力带。双脚分开与肩同宽站立，稍微弯曲膝盖。右脚向一侧迈出一步，保持阻力带的张力。左脚跟随，向一侧迈步以返回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0628', 'monster walk', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Place a resistance band around your ankles. Stand with your feet shoulder-width apart and slightly bend your knees. Take a step to the side with your right foot, maintaining tension on the resistance band. Follow with your left foot, stepping to the side to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0628-O95afRA.jpg', '/static/exercises/gifs/0628-O95afRA.gif', '© Gym visual — https://gymvisual.com/', '901026'),
('100630', '登山跑', '核心肌群', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。启动你的核心并将你的右膝盖靠近你的胸部，然后快速切换并将你的左膝盖靠近你的胸部。继续以跑步动作交替双腿，保持臀部较低，核心肌群参与。在整个练习过程中保持稳定的节奏和均匀的呼吸。重复所需的重复次数。', 'exercise-dataset', '0630', 'mountain climber', 'cardio', '有氧', '90', 'body weight', 'core', 'cardiovascular system', '心肺系统', '["核心肌群","肩部","肱三头肌"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest. Continue alternating legs in a running motion, keeping your hips low and your core engaged. Maintain a steady pace and breathe evenly throughout the exercise. Repeat for the desired number of repetitions.', '/static/exercises/images/0630-RJgzwny.jpg', '/static/exercises/gifs/0630-RJgzwny.gif', '© Gym visual — https://gymvisual.com/', '321027'),
('100631', '肌肉向上', '肱二头肌', '自重', '未分级', '首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。启动核心肌群，将身体拉向杠铃杆，以胸部为主导。当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。继续将自己向上拉，直到胸部位于杠铃上方并且手臂完全弯曲。通过慢慢降低自己回到起始位置来反转动作。重复所需的重复次数。', 'exercise-dataset', '0631', 'muscle up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","肱三头肌","肩部","胸肌"]', 'Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended. Engage your core and pull your body up towards the bar, leading with your chest. As you reach the top of the movement, transition your grip so that your palms are facing towards you. Continue pulling yourself up until your chest is above the bar and your arms are fully flexed. Reverse the movement by slowly lowering yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0631-yJUHKTn.jpg', '/static/exercises/gifs/0631-yJUHKTn.gif', '© Gym visual — https://gymvisual.com/', '901028'),
('101401', '肌肉向上垂直杆', '肱二头肌', '自重', '未分级', '首先悬挂在垂直杆上，手掌背对自己，手臂完全伸展。启动核心肌群，将身体拉向杠铃杆，以胸部为主导。当你站起来时，稍微向后倾斜，并将肘部移向身体两侧。继续拉，直到胸部到达杠铃并且肘部完全弯曲。在最高点暂停片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1401', 'muscle-up (on vertical bar)', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","肱三头肌","前臂"]', 'Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended. Engage your core and pull your body up towards the bar, leading with your chest. As you pull yourself up, lean back slightly and bring your elbows towards your sides. Continue pulling until your chest reaches the bar and your elbows are fully bent. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1401-Af0EW2I.jpg', '/static/exercises/gifs/1401-Af0EW2I.gif', '© Gym visual — https://gymvisual.com/', '901033'),
('102328', '窄距俯卧撑健身球', '胸肌', '瑞士球', '未分级', '将稳定球放在地面上，将自己置于俯卧撑位置，双手放在球上，距离略窄于肩宽。调动你的核心力量，让你的身体从头到脚保持在一条直线上。弯曲肘部，使胸部靠近球，使胸部靠近球。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '2328', 'narrow push-up on exercise ball', 'upper arms', '上臂', '50', 'stability ball', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart. Engage your core and keep your body in a straight line from head to toe. Lower your chest towards the ball by bending your elbows, keeping them close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2328-4cWjYEN.jpg', '/static/exercises/gifs/2328-4cWjYEN.gif', '© Gym visual — https://gymvisual.com/', '901936'),
('101403', '颈部侧向拉伸', '斜方肌', '自重', '未分级', '站直或坐直，肩膀放松。将头向一侧倾斜，将耳朵靠近肩膀。保持拉伸 15-30 秒。在另一侧重复。每侧进行 2-4 组。', 'exercise-dataset', '1403', 'neck side stretch', 'neck', '颈部', '100', 'body weight', 'trapezius', 'levator scapulae', '肩胛提肌', '["斜方肌","STERNOCLEIDOMASTOID"]', 'Stand or sit up straight with your shoulders relaxed. Tilt your head to one side, bringing your ear towards your shoulder. Hold the stretch for 15-30 seconds. Repeat on the other side. Perform 2-4 sets on each side.', '/static/exercises/images/1403-x2chWLO.jpg', '/static/exercises/gifs/1403-x2chWLO.gif', '© Gym visual — https://gymvisual.com/', '901033'),
('100634', '离心卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0634', 'negative crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0634-szIn2UK.jpg', '/static/exercises/gifs/0634-szIn2UK.gif', '© Gym visual — https://gymvisual.com/', '81032'),
('101495', '腹斜肌卷腹版本第二式', '腹斜肌', '自重', '未分级', '仰卧，膝盖弯曲，双脚平放在地上。将双手放在脑后或交叉放在胸前。收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。暂停片刻，然后将肩胛骨放回起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '1495', 'oblique crunch v. 2', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Lie on your back with your knees bent and feet flat on the ground. Place your hands behind your head or cross them over your chest. Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side. Pause for a moment, then lower your shoulder blades back down to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1495-cJgSTmh.jpg', '/static/exercises/gifs/1495-cJgSTmh.gif', '© Gym visual — https://gymvisual.com/', '81037'),
('100635', '腹斜肌卷腹地板', '腹斜肌', '自重', '未分级', '仰卧，膝盖弯曲，双脚平放在地板上。将双手放在脑后或交叉放在胸前。收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。暂停片刻，然后将肩胛骨放回到地板上。在另一侧重复，每次重复时交替进行。', 'exercise-dataset', '0635', 'oblique crunches floor', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Lie on your back with your knees bent and feet flat on the floor. Place your hands behind your head or cross them over your chest. Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side. Pause for a moment, then lower your shoulder blades back down to the floor. Repeat on the other side, alternating sides with each repetition.', '/static/exercises/images/0635-QUDd8WS.jpg', '/static/exercises/gifs/0635-QUDd8WS.gif', '© Gym visual — https://gymvisual.com/', '81036'),
('100636', '奥林匹克杠铃锤式弯举', '前臂', '奥林匹克杠铃', '未分级', '站直，双脚分开与肩同宽，正手握住奥林匹克杠铃。让杠铃悬挂在大腿前面，手掌与身体保持一臂距离。保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。挤压二头肌时，保持收缩位置短暂停顿。吸气并慢慢开始将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0636', 'olympic barbell hammer curl', 'upper arms', '上臂', '50', 'olympic barbell', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip. Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0636-o1ntciW.jpg', '/static/exercises/gifs/0636-o1ntciW.gif', '© Gym visual — https://gymvisual.com/', '81939'),
('100637', '奥林匹克杠铃肱三头肌臂屈伸', '肩部', '奥林匹克杠铃', '未分级', '首先，双脚分开与肩同宽站立，并用正手握住杠铃。将杠铃举过头顶，充分伸展双臂。保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。暂停片刻，然后将手臂伸回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0637', 'olympic barbell triceps extension', 'upper arms', '上臂', '50', 'olympic barbell', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip. Raise the barbell above your head, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0637-wu5LXwz.jpg', '/static/exercises/gifs/0637-wu5LXwz.gif', '© Gym visual — https://gymvisual.com/', '401940'),
('101355', '单臂抵住靠墙', '肩部', '自重', '未分级', '面向墙壁站立，双脚分开与肩同宽。将一只手臂伸直到身前，将手掌靠在墙上。启动你的核心，身体向前倾斜，保持手臂伸直，背部平坦。用手掌慢慢推向墙壁，激活背阔肌。保持该姿势几秒钟，然后松开并用另一只手臂重复该动作。', 'exercise-dataset', '1355', 'one arm against wall', 'back', '背部', '20', 'body weight', 'shoulders', 'lats', '背阔肌', '["肩部","肱三头肌"]', 'Stand facing a wall with your feet shoulder-width apart. Extend one arm straight out in front of you and place your palm against the wall. Engage your core and lean your body forward, keeping your arm straight and your back flat. Slowly push against the wall with your palm, activating your lat muscles. Hold the position for a few seconds, then release and repeat with the other arm.', '/static/exercises/images/1355-ZZTGMKh.jpg', '/static/exercises/gifs/1355-ZZTGMKh.gif', '© Gym visual — https://gymvisual.com/', '901041'),
('100638', '单臂反手引体向上', '肱二头肌', '自重', '未分级', '面向引体向上杆站立，双脚分开与肩同宽。抬起手，用反握方式抓住杠铃，一只手握住杠铃，另一只手握住手腕以提供支撑。悬挂在杠上，手臂完全伸展，保持身体伸直，核心肌群参与。弯曲肘部并挤压背部肌肉，将自己拉向杠铃。继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。重复所需的重复次数，然后换臂重复。', 'exercise-dataset', '0638', 'one arm chin-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Stand facing a pull-up bar with your feet shoulder-width apart. Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support. Hang from the bar with your arm fully extended, keeping your body straight and your core engaged. Pull yourself up towards the bar by bending your elbow and squeezing your back muscles. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', '/static/exercises/images/0638-HjdqmZa.jpg', '/static/exercises/gifs/0638-HjdqmZa.gif', '© Gym visual — https://gymvisual.com/', '901040'),
('100639', '单臂臂屈伸', '胸肌', '自重', '未分级', '背对长凳或椅子站立，双脚分开与肩同宽。将一只手放在身后的长凳或椅子上，手指指向您的身体。将双腿向前方伸展，脚跟保持在地面上。弯曲肘部，将身体放低至地面，使背部靠近长凳或椅子。在底部停顿片刻，然后用手掌推直手臂，回到起始位置。重复所需的重复次数，然后换边并用另一只手臂重复。', 'exercise-dataset', '0639', 'one arm dip', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Stand facing away from a bench or chair, with your feet shoulder-width apart. Place one hand on the bench or chair behind you, fingers pointing towards your body. Extend your legs out in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair. Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', '/static/exercises/images/0639-FAoIFMw.jpg', '/static/exercises/gifs/0639-FAoIFMw.gif', '© Gym visual — https://gymvisual.com/', '481041'),
('100640', '单臂砸球药球', '肩部', '药球', '未分级', '双脚分开与肩同宽站立，一只手将健身球放在腰前。稍微弯曲膝盖并启动核心。将健身球举过头顶，充分伸展手臂。用力将药球摔到地上，用你的核心和肩膀产生力量。抓住弹起的实心球，然后重复所需的重复次数。', 'exercise-dataset', '0640', 'one arm slam (with medicine ball)', 'waist', '腰腹', '60', 'medicine ball', 'shoulders', 'abs', '腹肌', '["肩部","后侧"]', 'Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist. Bend your knees slightly and engage your core. Raise the medicine ball above your head, fully extending your arm. Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power. Catch the medicine ball on the bounce and repeat for the desired number of repetitions.', '/static/exercises/images/0640-jCrtE9b.jpg', '/static/exercises/gifs/0640-jCrtE9b.gif', '© Gym visual — https://gymvisual.com/', '901948'),
('101773', '单臂毛巾划船', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖微曲，单手握住毛巾。腰部向前弯曲，保持背部挺直，核心肌群参与。完全伸展手臂，让毛巾挂在您面前。将毛巾拉向胸部，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢将毛巾放回起始位置。重复所需的重复次数，然后换臂。', 'exercise-dataset', '1773', 'one arm towel row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arm fully, allowing the towel to hang in front of you. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the towel back to the starting position. Repeat for the desired number of repetitions, then switch arms.', '/static/exercises/images/1773-bKWbrTA.jpg', '/static/exercises/gifs/1773-bKWbrTA.gif', '© Gym visual — https://gymvisual.com/', '901045'),
('101386', '单腿骑驴式提踵', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，脚趾指向前方。将双手放在稳定的表面上以获得支撑，例如墙壁或酒吧。将一条腿抬离地面，保持膝盖稍微弯曲。使用小腿肌肉，尽可能高地抬高脚跟。在顶部停顿片刻，然后慢慢降低脚跟。重复所需的重复次数，然后换腿。', 'exercise-dataset', '1386', 'one leg donkey calf raise', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart, toes pointing forward. Place your hands on a stable surface for support, such as a wall or a bar. Lift one leg off the ground, keeping your knee slightly bent. Raise your heel as high as possible, using your calf muscles. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/1386-A2upspL.jpg', '/static/exercises/gifs/1386-A2upspL.gif', '© Gym visual — https://gymvisual.com/', '1048'),
('101387', '单腿地板提踵', '踝部肌群', '自重', '未分级', '双脚分开与臀部同宽站立，双手放在墙壁或坚固的物体上以保持平衡。将一只脚抬离地面并用另一只脚保持平衡。慢慢地将脚跟抬离地面，将身体抬起到脚掌上。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1387', 'one leg floor calf raise', 'lower legs', '小腿', '70', 'body weight', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance. Lift one foot off the ground and balance on the other foot. Slowly raise your heel off the ground, lifting your body up onto the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1387-0jp9Rlz.jpg', '/static/exercises/gifs/1387-0jp9Rlz.gif', '© Gym visual — https://gymvisual.com/', '1049'),
('101476', '单腿深蹲', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。向前伸出一条腿，使其离开地面。弯曲站立的腿并降低身体，就像坐回椅子上一样。保持挺胸、背部挺直。推动脚后跟返回到起始位置。换另一条腿重复上述步骤。', 'exercise-dataset', '1476', 'one leg squat', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Extend one leg forward, keeping it off the ground. Bend your standing leg and lower your body down as if sitting back into a chair. Keep your chest up and your back straight. Push through your heel to return to the starting position. Repeat with the other leg.', '/static/exercises/images/1476-C31LMnP.jpg', '/static/exercises/gifs/1476-C31LMnP.gif', '© Gym visual — https://gymvisual.com/', '1046'),
('100641', '奥蒂斯式向上', '髋屈肌', '负重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0641', 'otis up', 'waist', '腰腹', '60', 'weighted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0641-UVL20oz.jpg', '/static/exercises/gifs/0641-UVL20oz.gif', '© Gym visual — https://gymvisual.com/', '901945'),
('100642', '外侧腿踢腿俯卧撑', '股四头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。当你向后推时，将一条腿踢向一侧，完全伸展并启动臀部。将腿恢复到起始位置并重复俯卧撑，每次重复时交替腿。继续交替踢腿和俯卧撑，达到所需的重复次数。', 'exercise-dataset', '0642', 'outside leg kick push-up', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged. As you push back up, kick one leg out to the side, extending it fully and engaging your glutes. Return your leg to the starting position and repeat the push-up, alternating legs with each repetition. Continue alternating leg kicks and push-ups for the desired number of repetitions.', '/static/exercises/images/0642-jNU1gFQ.jpg', '/static/exercises/gifs/0642-jNU1gFQ.gif', '© Gym visual — https://gymvisual.com/', '901050'),
('100643', '过顶肱三头肌拉伸', '肩部', '自重', '未分级', '站立或坐直，双脚分开与肩同宽。将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。保持拉伸 15-30 秒，然后放松。在另一侧重复。', 'exercise-dataset', '0643', 'overhead triceps stretch', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand or sit upright with your feet shoulder-width apart. Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade. With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', '/static/exercises/images/0643-Z5YStHW.jpg', '/static/exercises/gifs/0643-Z5YStHW.gif', '© Gym visual — https://gymvisual.com/', '901049'),
('103147', '骨盆骨盆倾斜', '下背部', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在身体两侧。收紧腹肌，向上倾斜骨盆，将下背部压入地面。保持这个姿势几秒钟，专注于收缩腹肌。释放倾斜并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3147', 'pelvic tilt', 'waist', '腰腹', '60', 'body weight', 'lower back', 'abs', '腹肌', '["下背部"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides. Engage your abs and tilt your pelvis upward, pressing your lower back into the ground. Hold this position for a few seconds, focusing on contracting your abs. Release the tilt and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3147-NKJ8o6x.jpg', '/static/exercises/gifs/3147-NKJ8o6x.gif', '© Gym visual — https://gymvisual.com/', '901048'),
('101422', '骨盆骨盆倾斜转入桥式', '腘绳肌', '自重', '未分级', '仰卧，膝盖弯曲，双脚平放在地上。将手臂放在身体两侧，手掌朝下。调动你的臀肌和核心肌肉。向上倾斜骨盆，将臀部抬离地面。保持桥位置几秒钟。慢慢地将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1422', 'pelvic tilt into bridge', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","核心肌群"]', 'Lie on your back with your knees bent and feet flat on the ground. Place your arms by your sides with your palms facing down. Engage your glutes and core muscles. Tilt your pelvis upward, lifting your hips off the ground. Hold the bridge position for a few seconds. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1422-D9qe7CM.jpg', '/static/exercises/gifs/1422-D9qe7CM.gif', '© Gym visual — https://gymvisual.com/', '901053'),
('101388', '腓骨肌拉伸', '踝部肌群', '绳索', '未分级', '坐在地上，双腿在身前伸展。将绳子绕在脚掌上，并用手握住绳子的末端。轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。保持拉伸 15-30 秒。释放绳子上的张力，然后在另一条腿上重复拉伸。重复所需的重复次数。', 'exercise-dataset', '1388', 'peroneals stretch', 'lower legs', '小腿', '70', 'rope', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Sit on the ground with your legs extended in front of you. Loop the rope around the ball of your foot and hold the ends of the rope with your hands. Gently pull the rope towards you, flexing your foot and stretching your calf muscles. Hold the stretch for 15-30 seconds. Release the tension on the rope and repeat the stretch on the other leg. Repeat for the desired number of repetitions.', '/static/exercises/images/1388-XhfS1DZ.jpg', '/static/exercises/gifs/1388-XhfS1DZ.gif', '© Gym visual — https://gymvisual.com/', '901950'),
('103662', '折刀式转眼镜蛇式俯卧撑', '核心肌群', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。收紧核心肌群，将臀部抬向天花板，与身体形成倒V字形。弯曲肘部，使上半身靠近地面，使上半身靠近地面。当你下降时，将你的重心向前移动，并通过伸直手臂并抬起胸部来过渡到眼镜蛇姿势。通过弯曲肘部并将胸部放回到地面来扭转运动。双手用力推回到倒V字形。通过将臀部放回地面继续运动，回到起始俯卧撑位置。重复所需的重复次数。', 'exercise-dataset', '3662', 'pike-to-cobra push-up', 'upper legs', '大腿', '40', 'body weight', 'core', 'glutes', '臀肌', '["核心肌群","肩部","肱三头肌"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body. Lower your upper body towards the ground by bending your elbows, keeping them close to your body. As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up. Reverse the movement by bending your elbows and lowering your chest back down towards the ground. Push through your hands to return to the inverted V position. Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position. Repeat for the desired number of repetitions.', '/static/exercises/images/3662-XPUDTt7.jpg', '/static/exercises/gifs/3662-XPUDTt7.gif', '© Gym visual — https://gymvisual.com/', '901051'),
('101306', '增强式俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手分开略宽于肩宽。弯曲肘部，将胸部压向地面，保持身体呈一条直线。爆发性地推离地面，利用胸部肌肉将上半身推离地面。双手回到起始位置，轻轻落地。重复所需的重复次数。', 'exercise-dataset', '1306', 'plyo push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your chest towards the ground by bending your elbows, keeping your body in a straight line. Push explosively off the ground, using your chest muscles to propel your upper body off the ground. Land softly with your hands back in the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1306-Snj1wSv.jpg', '/static/exercises/gifs/1306-Snj1wSv.gif', '© Gym visual — https://gymvisual.com/', '901054'),
('101687', '后侧踏步过顶伸展触碰', '臀肌', '自重', '未分级', '站立，双脚分开与臀部同宽，双臂放在身体两侧。右脚向后退一步，用脚掌着地。弯曲左膝并将身体降低至弓步位置。当你降低弓步时，同时将手臂举过头顶。在弓步底部暂停片刻，然后通过推动左脚跟并将右脚向前拉回到起始位置。在另一侧重复该动作，左脚向后退一步并弯曲右膝盖。继续交替进行所需的重复次数。', 'exercise-dataset', '1687', 'posterior step to overhead reach', 'waist', '腰腹', '60', 'body weight', 'glutes', 'abs', '腹肌', '["臀肌","腘绳肌","股四头肌","肩部"]', 'Stand with your feet hip-width apart and your arms by your sides. Take a step back with your right foot, landing on the ball of your foot. Bend your left knee and lower your body into a lunge position. As you lower into the lunge, simultaneously reach your arms overhead. Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward. Repeat the movement on the other side, stepping back with your left foot and bending your right knee. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1687-ErqK3UL.jpg', '/static/exercises/gifs/1687-ErqK3UL.gif', '© Gym visual — https://gymvisual.com/', '901059'),
('101389', '后侧胫骨前肌拉伸', '腘绳肌', '绳索', '未分级', '坐在地上，双腿在身前伸展。将绳子绕在脚掌上，并用手握住绳子的末端。轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。保持拉伸 20-30 秒。释放绳子上的张力并放松脚。在另一条腿上重复该拉伸动作。', 'exercise-dataset', '1389', 'posterior tibialis stretch', 'lower legs', '小腿', '70', 'rope', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Sit on the ground with your legs extended in front of you. Loop the rope around the ball of your foot and hold the ends of the rope with your hands. Gently pull the rope towards you, flexing your foot and stretching your calf muscles. Hold the stretch for 20-30 seconds. Release the tension on the rope and relax your foot. Repeat the stretch on the other leg.', '/static/exercises/images/1389-DEEqoI2.jpg', '/static/exercises/gifs/1389-DEEqoI2.gif', '© Gym visual — https://gymvisual.com/', '901956'),
('103119', '如厕式深蹲', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。在整个动作过程中保持挺胸、背部挺直。降低自己，直到大腿与地面平行或尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3119', 'potty squat', 'waist', '腰腹', '60', 'body weight', 'quadriceps', 'abs', '腹肌', '["股四头肌","臀肌"]', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair. Keep your chest up and your back straight throughout the movement. Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3119-75Bgtjy.jpg', '/static/exercises/gifs/3119-75Bgtjy.gif', '© Gym visual — https://gymvisual.com/', '901055'),
('103132', '如厕式深蹲支撑', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。抓住稳定的支撑物，例如椅子或墙壁，以保持平衡。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。在整个动作过程中保持挺胸、背部挺直。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3132', 'potty squat with support', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Hold onto a stable support, such as a chair or wall, for balance. Lower your body down into a squat position by bending your knees and pushing your hips back. Keep your chest up and your back straight throughout the movement. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3132-b63ZzGe.jpg', '/static/exercises/gifs/3132-b63ZzGe.gif', '© Gym visual — https://gymvisual.com/', '1060'),
('100648', '力量式翻举', '臀肌', '杠铃', '未分级', '首先将杠铃放在你面前的地面上，双脚分开与肩同宽。弯腰，正手握住杠铃，握距略宽于肩宽。将杠铃提离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。当杠铃到达大腿中部时，爆发性地将其向上拉，耸肩并将肘部拉高并向两侧拉。当杠铃到达最高点时，迅速下降到其下方，旋转肘部，以前蹲姿势将杠铃接在肩膀上。握住杠铃站起来，充分伸展臀部和膝盖。将杠铃放回起始位置，在整个运动过程中保持对重量的控制。重复所需的重复次数。', 'exercise-dataset', '0648', 'power clean', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","股四头肌","小腿肌群"]', 'Start with the barbell on the ground in front of you, with your feet shoulder-width apart. Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees. As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides. As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position. Stand up with the barbell, fully extending your hips and knees. Lower the barbell back down to the starting position, keeping control of the weight throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0648-SiWCcTN.jpg', '/static/exercises/gifs/0648-SiWCcTN.gif', '© Gym visual — https://gymvisual.com/', '901157'),
('103665', '力量式点支撑平板支撑', '肩部', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。启动你的核心并挤压你的臀肌以保持稳定的位置。将身体放低到前臂上，一次一只手臂，从头到脚保持一条直线。保持这个姿势所需的时间，保持核心肌群和臀肌的参与。要返回到起始位置，请推动前臂并将身体抬回到高位平板支撑位置。重复所需的重复次数。', 'exercise-dataset', '3665', 'power point plank', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌","臀肌"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe. Engage your core and squeeze your glutes to maintain a stable position. Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe. Hold this position for the desired amount of time, keeping your core and glutes engaged. To return to the starting position, push through your forearms and lift your body back up into a high plank position. Repeat for the desired number of repetitions.', '/static/exercises/images/3665-hCjGsRQ.jpg', '/static/exercises/gifs/3665-hCjGsRQ.gif', '© Gym visual — https://gymvisual.com/', '1060'),
('103203', '囚徒式半程坐向上（男）', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3203', 'prisoner half sit-up (male)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3203-mgejmGP.jpg', '/static/exercises/gifs/3203-mgejmGP.gif', '© Gym visual — https://gymvisual.com/', '161063'),
('101707', '俯卧转体瑞士球', '腹斜肌', '瑞士球', '未分级', '首先，面朝下躺在稳定球上，双脚分开与肩同宽，脚趾接触地面。将双手放在脑后或交叉放在胸前。启动核心肌肉，慢慢将上半身抬离球，保持背部挺直。将躯干旋转到一侧，使肩膀靠近臀部。在整个运动过程中保持臀部和腿部稳定。暂停片刻，然后回到起始位置。重复旋转到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '1707', 'prone twist on stability ball', 'waist', '腰腹', '60', 'stability ball', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground. Place your hands behind your head or cross them over your chest. Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight. Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement. Pause for a moment, then return to the starting position. Repeat the rotation to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/1707-1IG6gVF.jpg', '/static/exercises/gifs/1707-1IG6gVF.gif', '© Gym visual — https://gymvisual.com/', '901966'),
('100651', '引体向上中立握握', '肱二头肌', '自重', '未分级', '用中立握法（手掌相对）悬挂在引体向上杆上，双臂完全伸展。启动你的核心并将肩胛骨挤压在一起。弯曲肘部并将肘部向下推向臀部，将身体向上拉向杠铃。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0651', 'pull up (neutral grip)', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', '/static/exercises/images/0651-0V2YQjW.jpg', '/static/exercises/gifs/0651-0V2YQjW.gif', '© Gym visual — https://gymvisual.com/', '901065'),
('100650', '拉瑞士球', '髋屈肌', '瑞士球', '未分级', '首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。将双手放在稳定球的两侧以获得支撑。收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。重复所需的重复次数。', 'exercise-dataset', '0650', 'pull-in (on stability ball)', 'waist', '腰腹', '60', 'stability ball', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands on the sides of the stability ball for support. Engage your abs and slowly roll your hips forward, bringing your knees towards your chest. Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0650-UQr48Oi.jpg', '/static/exercises/gifs/0650-UQr48Oi.gif', '© Gym visual — https://gymvisual.com/', '901966'),
('100652', '引体向上', '肱二头肌', '自重', '未分级', '悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。启动你的核心并将肩胛骨挤压在一起。弯曲肘部并将胸部拉向杠铃杆，将身体向上拉向杠铃杆。在动作的最高点暂停，然后慢慢降低身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0652', 'pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Hang from a pull-up bar with your palms facing away from you and your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar. Pause at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0652-lBDjFxJ.jpg', '/static/exercises/gifs/0652-lBDjFxJ.gif', '© Gym visual — https://gymvisual.com/', '1061'),
('101689', '推拉自重', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，身体呈一条直线。弯曲肘部，将胸部压向地面，保持身体伸直。推动手掌以伸展手臂并返回到起始位置。从俯卧撑位置开始，弯曲肘部，将胸部拉向地面，保持身体伸直。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1689', 'push and pull bodyweight', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","三角肌"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your palms to extend your arms and return to the starting position. From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1689-wXvUZC8.jpg', '/static/exercises/gifs/1689-wXvUZC8.gif', '© Gym visual — https://gymvisual.com/', '901068'),
('103638', '推跑', '股四头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。弯曲肘部，将胸部压向地面，保持身体伸直。用手推动以伸展手臂并返回到起始位置。快速将一个膝盖靠近胸部，然后快速切换并将另一只膝盖靠近胸部。继续尽可能快地交替膝盖，同时保持良好的姿势。继续所需的持续时间或重复次数。', 'exercise-dataset', '3638', 'push to run', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your hands to extend your arms and return to the starting position. Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest. Continue alternating knees as fast as you can while maintaining good form. Continue for the desired duration or number of repetitions.', '/static/exercises/images/3638-PrQbjvB.jpg', '/static/exercises/gifs/3638-PrQbjvB.gif', '© Gym visual — https://gymvisual.com/', '481067'),
('101307', '俯卧撑BOSU球', '肱三头肌', 'BOSU球', '未分级', '将博苏球平放在地上，平面朝上。将自己置于俯卧撑位置，双手放在博苏球的外边缘。弯曲肘部，调动核心力量，将身体向博苏球方向降低。伸展双臂，将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1307', 'push up on bosu ball', 'chest', '胸部', '10', 'bosu ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Place the bosu ball on the ground with the flat side facing up. Position yourself in a push-up position with your hands on the outer edges of the bosu ball. Engage your core and lower your body down towards the bosu ball by bending your elbows. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1307-wVompEp.jpg', '/static/exercises/gifs/1307-wVompEp.gif', '© Gym visual — https://gymvisual.com/', '901972'),
('100662', '俯卧撑', '肱三头肌', '自重', '未分级', '从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。弯曲肘部，调动核心力量，将身体压向地面，保持身体呈一条直线。当你的胸部刚好高于地面时，暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0662', 'push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","三角肌","核心肌群"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line. Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0662-I4hDWkc.jpg', '/static/exercises/gifs/0662-I4hDWkc.gif', '© Gym visual — https://gymvisual.com/', '81065'),
('100653', '俯卧撑BOSU球', '肱三头肌', 'BOSU球', '未分级', '将博苏球平放在地上，平面朝上。将自己置于俯卧撑位置，双手放在博苏球的外边缘。弯曲肘部，调动核心力量，将身体向博苏球方向降低。伸展双臂，将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0653', 'push-up (bosu ball)', 'chest', '胸部', '10', 'bosu ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Place the bosu ball on the ground with the flat side facing up. Position yourself in a push-up position with your hands on the outer edges of the bosu ball. Engage your core and lower your body down towards the bosu ball by bending your elbows. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0653-2kr2lWy.jpg', '/static/exercises/gifs/0653-2kr2lWy.gif', '© Gym visual — https://gymvisual.com/', '81970'),
('100655', '俯卧撑瑞士球', '肱三头肌', '瑞士球', '未分级', '将稳定球放在地上，面朝下，双手放在球上，与肩同宽。将双腿伸直在身后，用脚趾保持平衡。弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0655', 'push-up (on stability ball)', 'chest', '胸部', '10', 'stability ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart. Extend your legs straight out behind you, balancing on your toes. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0655-Y4BRNQF.jpg', '/static/exercises/gifs/0655-Y4BRNQF.gif', '© Gym visual — https://gymvisual.com/', '81973'),
('100656', '俯卧撑瑞士球', '肱三头肌', '瑞士球', '未分级', '将稳定球放在地上，面朝下，双手放在球上，与肩同宽。将双腿伸直在身后，用脚趾保持平衡。弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。在底部暂停片刻，然后伸直手臂将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0656', 'push-up (on stability ball)', 'chest', '胸部', '10', 'stability ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart. Extend your legs straight out behind you, balancing on your toes. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0656-tgryw5Y.jpg', '/static/exercises/gifs/0656-tgryw5Y.gif', '© Gym visual — https://gymvisual.com/', '81974'),
('100659', '俯卧撑靠墙', '肱三头肌', '自重', '未分级', '面向墙壁站立，距离大约一臂距离。将双手放在墙上，与肩同高，距离略宽于肩宽。后退几英尺，保持身体挺直，双脚分开与臀部同宽。弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。推回起始位置，伸直手臂。重复所需的重复次数。', 'exercise-dataset', '0659', 'push-up (wall)', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","三角肌"]', 'Stand facing a wall, about arm''s length away. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart. Step back a few feet, keeping your body straight and your feet hip-width apart. Bend your elbows and lower your chest towards the wall, keeping your body in a straight line. Push back up to the starting position, straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0659-LEH9jxP.jpg', '/static/exercises/gifs/0659-LEH9jxP.gif', '© Gym visual — https://gymvisual.com/', '81071'),
('100658', '俯卧撑靠墙版本第二式', '肱三头肌', '自重', '未分级', '面向墙壁站立，距离大约一臂距离。将双手放在墙上，与肩同高，距离略宽于肩宽。双脚向后退一步，保持与臀部同宽。收紧核心肌群，保持身体从头到脚跟呈一条直线。弯曲肘部，将胸部向墙壁降低，保持身体挺直。暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0658', 'push-up (wall) v. 2', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Stand facing a wall, about arm''s length away. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart. Step back with your feet, keeping them hip-width apart. Engage your core and keep your body in a straight line from head to heels. Bend your elbows and lower your chest towards the wall, keeping your body straight. Pause for a moment, then push yourself back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0658-NCmbLCw.jpg', '/static/exercises/gifs/0658-NCmbLCw.gif', '© Gym visual — https://gymvisual.com/', '81076'),
('100660', '俯卧撑窄距握离地哑铃', '胸肌', '哑铃', '未分级', '从俯卧撑位置开始，双手并拢，直接放在肩膀下方。每只手握住一个哑铃，将其放在地上。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0660', 'push-up close-grip off dumbbell', 'upper arms', '上臂', '50', 'dumbbell', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start in a push-up position with your hands placed close together, directly under your shoulders. Hold a dumbbell in each hand, resting them on the ground. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0660-KZXAtKQ.jpg', '/static/exercises/gifs/0660-KZXAtKQ.gif', '© Gym visual — https://gymvisual.com/', '901277'),
('100661', '俯卧撑内侧腿踢腿', '股四头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。弯曲肘部，将身体降低到地面，保持背部挺直，核心肌群参与。当你向后推时，将一条腿抬离地面并将其踢向一侧，保持伸直。将腿放下并重复俯卧撑，然后换另一条腿。每次重复俯卧撑时继续交替踢腿。', 'exercise-dataset', '0661', 'push-up inside leg kick', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged. As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight. Lower your leg back down and repeat the push-up, then switch to the other leg. Continue alternating leg kicks with each push-up repetition.', '/static/exercises/images/0661-0br45wL.jpg', '/static/exercises/gifs/0661-0br45wL.gif', '© Gym visual — https://gymvisual.com/', '901078'),
('100663', '俯卧撑药球', '肱三头肌', '药球', '未分级', '从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0663', 'push-up medicine ball', 'chest', '胸部', '10', 'medicine ball', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0663-W8KAlkI.jpg', '/static/exercises/gifs/0663-W8KAlkI.gif', '© Gym visual — https://gymvisual.com/', '81977'),
('101467', '俯卧撑下部双臂', '胸肌', '自重', '未分级', '从平板支撑位置开始，前臂放在地面上，肘部位于肩膀正下方。调动你的核心力量，让你的身体从头到脚保持在一条直线上。弯曲肘部，使胸部靠近地面，使胸部靠近地面。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1467', 'push-up on lower arms', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start in a plank position with your forearms on the ground and elbows directly below your shoulders. Engage your core and keep your body in a straight line from head to toe. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1467-4Jt8QsQ.jpg', '/static/exercises/gifs/1467-4Jt8QsQ.gif', '© Gym visual — https://gymvisual.com/', '901080'),
('103145', '俯卧撑加强式', '肱三头肌', '自重', '未分级', '从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。一旦你的胸部刚好高于地面，用力推动你的手臂，伸展你的手臂并抬起你的上半身。在动作的最高点，将上背部推向天花板，从而伸展肩胛骨。暂停片刻，然后通过缩回肩胛骨并将身体放回起始位置来反转动作。重复所需的重复次数。', 'exercise-dataset', '3145', 'push-up plus', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up. At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling. Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3145-pvBMLHA.jpg', '/static/exercises/gifs/3145-pvBMLHA.gif', '© Gym visual — https://gymvisual.com/', '81077'),
('100664', '俯卧撑侧平板支撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。弯曲肘部，将身体降低到地面，保持核心参与。推回到起始位置。将体重转移到左手上，然后将身体向右旋转，将右臂举向天花板。保持侧板姿势几秒钟，然后返回到起始位置。在另一侧重复俯卧撑和侧板支撑。继续交替进行所需的重复次数。', 'exercise-dataset', '0664', 'push-up to side plank', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌","肱三头肌"]', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping your core engaged. Push back up to the starting position. Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling. Hold the side plank position for a few seconds, then return to the starting position. Repeat the push-up and side plank on the opposite side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0664-KhHJ338.jpg', '/static/exercises/gifs/0664-KhHJ338.gif', '© Gym visual — https://gymvisual.com/', '1082'),
('103533', '股四头肌', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。保持挺胸、背部挺直。降低身体直到大腿与地面平行。推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3533', 'quads', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart. Lower your body by bending your knees and pushing your hips back as if sitting on a chair. Keep your chest up and your back straight. Lower yourself until your thighs are parallel to the ground. Push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3533-6YUfHPL.jpg', '/static/exercises/gifs/3533-6YUfHPL.gif', '© Gym visual — https://gymvisual.com/', '901077'),
('103201', '四分之一程坐向上', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3201', 'quarter sit-up', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3201-enxnJcM.jpg', '/static/exercises/gifs/3201-enxnJcM.gif', '© Gym visual — https://gymvisual.com/', '161080'),
('103552', '快速双脚版本第二式', '小腿肌群', '自重', '未分级', '双脚分开与肩同宽站立，双臂放在身体两侧。首先快速上下移动双脚，就像原地跑步一样。保持动作快速而轻盈，重点放在脚掌上。继续所需的持续时间或重复次数。', 'exercise-dataset', '3552', 'quick feet v. 2', 'upper legs', '大腿', '40', 'body weight', 'calves', 'quads', '股四头肌', '["小腿肌群","腘绳肌"]', 'Stand with your feet shoulder-width apart and your arms by your sides. Begin by rapidly moving your feet up and down, as if you were running in place. Keep your movements quick and light, focusing on staying on the balls of your feet. Continue for the desired duration or number of repetitions.', '/static/exercises/images/3552-mweqJin.jpg', '/static/exercises/gifs/3552-mweqJin.gif', '© Gym visual — https://gymvisual.com/', '901085'),
('100666', '上举单侧臂俯卧撑', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。将一只手臂伸直至一侧，与地面平行。弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。推回起始位置，使用胸部肌肉抬起身体。另一只手臂伸出，重复上述动作。', 'exercise-dataset', '0666', 'raise single arm push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Extend one arm straight out to the side, parallel to the ground. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged. Push back up to the starting position, using your chest muscles to lift your body. Repeat with the other arm extended.', '/static/exercises/images/0666-13TpY4H.jpg', '/static/exercises/gifs/0666-13TpY4H.gif', '© Gym visual — https://gymvisual.com/', '81086'),
('100668', '后侧下斜桥式', '腘绳肌', '自重', '未分级', '仰卧，双脚平放在地上，膝盖弯曲。将手臂放在身体两侧，手掌朝下。收紧臀肌和腿筋，将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。保持这个姿势几秒钟，然后慢慢地将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0668', 'rear decline bridge', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Lie on your back with your feet flat on the ground and your knees bent. Place your arms by your sides with your palms facing down. Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Hold this position for a few seconds, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0668-UpAlold.jpg', '/static/exercises/gifs/0668-UpAlold.gif', '© Gym visual — https://gymvisual.com/', '901085'),
('100669', '后侧三角肌拉伸', '斜方肌', '自重', '未分级', '站直，双脚分开与肩同宽。将右臂伸过胸部，将左手放在右肘上。轻轻地将右臂拉向左肩，感受右肩的拉伸。保持拉伸 15-30 秒，然后放松。在另一侧重复。', 'exercise-dataset', '0669', 'rear deltoid stretch', 'shoulders', '肩部', '30', 'body weight', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌"]', 'Stand tall with your feet shoulder-width apart. Extend your right arm across your chest, placing your left hand on your right elbow. Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', '/static/exercises/images/0669-xifhB5W.jpg', '/static/exercises/gifs/0669-xifhB5W.gif', '© Gym visual — https://gymvisual.com/', '401086'),
('100670', '后侧引体向上', '肱二头肌', '自重', '未分级', '正手握住引体向上杆，握距略宽于肩宽。悬挂在杠上，双臂完全伸展，身体伸直。收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0670', 'rear pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0670-CbFSYC1.jpg', '/static/exercises/gifs/0670-CbFSYC1.gif', '© Gym visual — https://gymvisual.com/', '1085'),
('101582', '仰卧大幅脚尖姿势绳索', '小腿肌群', '绳索', '未分级', '仰卧，双腿伸展，双臂放在身体两侧。将绳子绕在右脚掌上，并用手握住绳子的末端。慢慢地将右腿抬向胸部，保持膝盖伸直，脚弯曲。保持伸展几秒钟，然后慢慢将腿放回起始位置。左腿重复上述动作。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '1582', 'reclining big toe pose with rope', 'upper legs', '大腿', '40', 'rope', 'calves', 'hamstrings', '腘绳肌', '["小腿肌群","臀肌"]', 'Lie on your back with your legs extended and your arms by your sides. Loop the rope around the ball of your right foot and hold the ends of the rope with your hands. Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed. Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position. Repeat with your left leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/1582-K5xgdvI.jpg', '/static/exercises/gifs/1582-K5xgdvI.gif', '© Gym visual — https://gymvisual.com/', '901994'),
('103236', '阻力带弹力带髋部推髋双膝（女）', '腘绳肌', '阻力带', '未分级', '首先跪在地上，膝盖分开与臀部同宽，双脚弯曲。将阻力带缠绕在大腿上，就在膝盖上方。将双手放在臀部或向前伸展以保持平衡。调动你的臀肌和核心肌肉。当你将膝盖抬离地面时，向前推动臀部并挤压臀部，伸展臀部直到大腿与地面平行。保持该姿势片刻，然后慢慢将膝盖放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3236', 'resistance band hip thrusts on knees (female)', 'upper legs', '大腿', '40', 'resistance band', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Start by kneeling on the ground with your knees hip-width apart and your feet flexed. Wrap the resistance band around your thighs, just above your knees. Place your hands on your hips or extend them out in front of you for balance. Engage your glutes and core muscles. Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground. Hold the position for a moment, then slowly lower your knees back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3236-Pjbc0Kt.jpg', '/static/exercises/gifs/3236-Pjbc0Kt.gif', '© Gym visual — https://gymvisual.com/', '561997'),
('103007', '阻力带弹力带腿屈伸', '腘绳肌', '阻力带', '未分级', '将阻力带固定在坚固的锚点上，并将其固定在脚踝上。面向锚点站立，双脚分开与肩同宽。保持核心参与并保持上半身稳定，将腿伸直到身前。在顶部暂停片刻，然后慢慢地将腿放回起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '3007', 'resistance band leg extension', 'upper legs', '大腿', '40', 'resistance band', 'hamstrings', 'quads', '股四头肌', '["腘绳肌"]', 'Attach the resistance band to a sturdy anchor point and secure it around your ankle. Stand facing the anchor point with your feet shoulder-width apart. Keeping your core engaged and your upper body stable, extend your leg straight out in front of you. Pause for a moment at the top, then slowly return your leg to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/3007-Y1MsI1l.jpg', '/static/exercises/gifs/3007-Y1MsI1l.gif', '© Gym visual — https://gymvisual.com/', '401992'),
('103123', '阻力带弹力带坐姿肱二头肌弯举', '前臂', '阻力带', '未分级', '坐在椅子或长凳上，背部挺直，双脚平放在地面上。反手握住阻力带，手掌朝上，手臂向下伸展到身体两侧。保持上臂静止，呼气并将阻力带向上卷向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并慢慢降低阻力带回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3123', 'resistance band seated biceps curl', 'upper arms', '上臂', '50', 'resistance band', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides. Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the resistance band back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3123-XFc3vpY.jpg', '/static/exercises/gifs/3123-XFc3vpY.gif', '© Gym visual — https://gymvisual.com/', '1995'),
('103124', '阻力带弹力带坐姿胸推', '肩部', '阻力带', '未分级', '坐在椅子或长凳上，背部挺直，双脚平放在地面上。每只手握住阻力带手柄，手掌朝下，肘部弯曲成 90 度角。向前伸展双臂，将阻力带推离胸部。动作结束时暂停片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3124', 'resistance band seated chest press', 'chest', '胸部', '10', 'resistance band', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle. Extend your arms forward, pushing the resistance band away from your chest. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3124-4x5Okof.jpg', '/static/exercises/gifs/3124-4x5Okof.gif', '© Gym visual — https://gymvisual.com/', '161996'),
('103006', '阻力带弹力带坐姿髋外展', '臀肌', '阻力带', '未分级', '坐在椅子或长凳上，背部挺直，双脚平放在地面上。将阻力带缠绕在大腿上，就在膝盖上方。将双手放在椅子或长凳的两侧以获得支撑。启动外展肌（大腿外侧肌肉），并克服弹力带的阻力，慢慢将膝盖分开。动作结束时暂停片刻，然后慢慢将膝盖放回一起。重复所需的重复次数。', 'exercise-dataset', '3006', 'resistance band seated hip abduction', 'upper legs', '大腿', '40', 'resistance band', 'glutes', 'abductors', '外展肌群', '["臀肌","腘绳肌"]', 'Sit on a chair or bench with your back straight and feet flat on the ground. Wrap the resistance band around your thighs, just above your knees. Place your hands on the sides of the chair or bench for support. Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band. Pause for a moment at the end of the movement, then slowly bring your knees back together. Repeat for the desired number of repetitions.', '/static/exercises/images/3006-0xDpB4L.jpg', '/static/exercises/gifs/3006-0xDpB4L.gif', '© Gym visual — https://gymvisual.com/', '901997'),
('103122', '阻力带弹力带坐姿肩上推举', '肱三头肌', '阻力带', '未分级', '坐在椅子或长凳上，背部挺直，双脚平放在地面上。双手握住阻力带，手掌朝前，将其拉至肩部水平。将弹力带压过头顶，充分伸展双臂。在顶部停顿片刻，然后慢慢将弹力带降低至肩部水平。重复所需的重复次数。', 'exercise-dataset', '3122', 'resistance band seated shoulder press', 'shoulders', '肩部', '30', 'resistance band', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level. Press the band overhead, extending your arms fully. Pause for a moment at the top, then slowly lower the band back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/3122-S93zLTG.jpg', '/static/exercises/gifs/3122-S93zLTG.gif', '© Gym visual — https://gymvisual.com/', '1998'),
('103144', '阻力带弹力带坐姿直后侧划船', '肱二头肌', '阻力带', '未分级', '坐在地板上，双腿伸展，将阻力带绕在脚上。双手握住阻力带的两端，手掌相对。保持背部挺直，稍微向后倾斜，锻炼核心肌群。将阻力带拉向胸部，将肩胛骨挤压在一起。在最高点停顿片刻，然后慢慢释放张力，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3144', 'resistance band seated straight back row', 'back', '背部', '20', 'resistance band', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Sit on the floor with your legs extended and loop the resistance band around your feet. Hold the ends of the resistance band with your hands, palms facing each other. Keep your back straight and lean slightly back, engaging your core. Pull the resistance band towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3144-Nu7jqFE.jpg', '/static/exercises/gifs/3144-Nu7jqFE.gif', '© Gym visual — https://gymvisual.com/', '902001'),
('100872', '反向卷腹', '髋屈肌', '自重', '未分级', '平躺，双臂沿着身体两侧伸展。弯曲膝盖，将脚抬离地面，使大腿垂直于地板。收缩腹肌，将臀部卷离地板，使膝盖靠近胸部。在顶部暂停片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0872', 'reverse crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your arms extended along your sides. Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor. Contract your abs and curl your hips off the floor, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0872-nCU1Ekp.jpg', '/static/exercises/gifs/0872-nCU1Ekp.gif', '© Gym visual — https://gymvisual.com/', '81094'),
('100672', '反向臂屈伸', '胸肌', '自重', '未分级', '将自己定位在两个双杠之间，双臂完全伸展，身体伸直。弯曲肘部降低身体，直到上臂与地面平行。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0672', 'reverse dip', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Position yourself between two parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0672-NZ5Qqkz.jpg', '/static/exercises/gifs/0672-NZ5Qqkz.gif', '© Gym visual — https://gymvisual.com/', '481095'),
('100673', '反向握器械高位下拉', '肱二头肌', '固定器械', '未分级', '调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。反手握住手柄，握距略宽于肩宽。坐直，挺胸，肩膀向后，保持下背部轻微的拱形。将手柄向下拉向胸部，将肩胛骨挤压在一起。在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0673', 'reverse grip machine lat pulldown', 'back', '背部', '20', 'leverage machine', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back. Pull the handles down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0673-ecpY0rH.jpg', '/static/exercises/gifs/0673-ecpY0rH.gif', '© Gym visual — https://gymvisual.com/', '81502'),
('100674', '反向握引体向上', '肱二头肌', '自重', '未分级', '双手分开与肩同宽，反握抓住引体向上杆。悬挂在杠上，双臂完全伸展，身体伸直。调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0674', 'reverse grip pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an underhand grip, hands shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0674-YAk5dIw.jpg', '/static/exercises/gifs/0674-YAk5dIw.gif', '© Gym visual — https://gymvisual.com/', '1099'),
('100675', '反向超伸展伸展瑞士球', '腘绳肌', '瑞士球', '未分级', '面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。将双手放在身前的地面上以保持稳定。调动臀肌和腿筋，将双腿尽可能高地抬向天花板。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0675', 'reverse hyper extension (on stability ball)', 'upper legs', '大腿', '40', 'stability ball', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you. Place your hands on the ground in front of you for stability. Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0675-vM5YS2g.jpg', '/static/exercises/gifs/0675-vM5YS2g.gif', '© Gym visual — https://gymvisual.com/', '902006'),
('101423', '反向超伸展平凳训练凳', '腘绳肌', '自重', '未分级', '脸朝下躺在平坦的长凳上，臀部位于边缘，双腿悬在长凳上。抓住长凳以保持稳定。保持双腿伸直，尽可能将它们抬向天花板。在动作的最高点挤压臀部。慢慢地将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1423', 'reverse hyper on flat bench', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench. Hold onto the bench for stability. Keeping your legs straight, raise them up towards the ceiling as high as you can. Squeeze your glutes at the top of the movement. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1423-OrETs32.jpg', '/static/exercises/gifs/1423-OrETs32.gif', '© Gym visual — https://gymvisual.com/', '901105'),
('103663', '反向平板支撑腿抬举', '臀肌', '自重', '未分级', '坐在地上，双腿向前伸展，双手放在身后的地面上，手指指向脚部。双手用力，将臀部抬离地面，进入反向平板支撑位置。启动你的核心并将一条腿抬离地面，将其笔直向上伸向天花板。保持一会儿，然后将腿放下。换另一条腿重复上述步骤。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '3663', 'reverse plank with leg lift', 'waist', '腰腹', '60', 'body weight', 'glutes', 'abs', '腹肌', '["臀肌","腘绳肌","肩部"]', 'Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet. Press through your hands and lift your hips off the ground, coming into a reverse plank position. Engage your core and lift one leg off the ground, extending it straight up towards the ceiling. Hold for a moment, then lower your leg back down. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/3663-tFToB7l.jpg', '/static/exercises/gifs/3663-tFToB7l.gif', '© Gym visual — https://gymvisual.com/', '1106'),
('100677', '吊环臂屈伸', '胸肌', '自重', '未分级', '首先，将手臂完全伸展，身体伸直，挂在吊环上。弯曲肘部，降低身体，直到肩膀低于肘部。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0677', 'ring dips', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Start by hanging from the rings with your arms fully extended and your body straight. Lower your body by bending your elbows until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0677-ezTvXcr.jpg', '/static/exercises/gifs/0677-ezTvXcr.gif', '© Gym visual — https://gymvisual.com/', '481101'),
('102571', '摇摆青蛙式拉伸', '腘绳肌', '自重', '未分级', '首先跪在地上，膝盖分开与臀部同宽。将双手放在身前的地面上以获得支撑。慢慢向前倾，将重心转移到双手上，并将双腿伸到身后。当你将臀部向后推向天花板时，保持背部挺直并收紧臀部。保持这个姿势几秒钟，感受臀部的拉伸。弯曲膝盖并降低臀部，慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2571', 'rocking frog stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Start by kneeling on the ground with your knees hip-width apart. Place your hands on the ground in front of you for support. Slowly lean forward, shifting your weight onto your hands and extending your legs behind you. Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling. Hold this position for a few seconds, feeling a stretch in your glutes. Slowly return to the starting position by bending your knees and lowering your hips back down. Repeat for the desired number of repetitions.', '/static/exercises/images/2571-2Dk4xQV.jpg', '/static/exercises/gifs/2571-2Dk4xQV.gif', '© Gym visual — https://gymvisual.com/', '901104'),
('100678', '洛奇式引体向上下拉', '肱二头肌', '自重', '未分级', '站在引体向上杆前，双脚分开与肩同宽。向上伸手，正手握住杠铃，握距略宽于肩宽。悬挂在杠上，双臂完全伸展，身体伸直。调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0678', 'rocky pull-up pulldown', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Stand in front of a pull-up bar with your feet shoulder-width apart. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0678-cQ19bBP.jpg', '/static/exercises/gifs/0678-cQ19bBP.gif', '© Gym visual — https://gymvisual.com/', '1105'),
('102208', '滚轮后侧拉伸', '腘绳肌', '泡沫轴', '未分级', '首先坐在地上，双腿在身前伸展。将滚轮垂直于您的身体放置，位于臀部下方。慢慢向后滚动你的身体，让滚轮向上移动你的背部。继续滚动，直到滚轮到达您的上背部。暂停片刻，然后慢慢滚回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2208', 'roller back stretch', 'back', '背部', '20', 'roller', 'hamstrings', 'spine', '竖脊肌', '["腘绳肌","臀肌"]', 'Start by sitting on the ground with your legs extended in front of you. Place the roller perpendicular to your body, just below your glutes. Slowly roll your body backwards, allowing the roller to move up your back. Continue rolling until the roller reaches your upper back. Pause for a moment, then slowly roll back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2208-isofgzg.jpg', '/static/exercises/gifs/2208-isofgzg.gif', '© Gym visual — https://gymvisual.com/', '902006'),
('102204', '滚轮身体锯式', '肩部', '泡沫轴', '未分级', '从平板支撑位置开始，前臂放在滚轴上，身体呈一条直线。启动你的核心并缓慢向前滚动滚轮，在保持控制的同时尽可能地伸展你的身体。在最远点暂停片刻，然后慢慢地将滚轮滚回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2204', 'roller body saw', 'waist', '腰腹', '60', 'roller', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌","核心肌群"]', 'Start in a plank position with your forearms on the roller and your body in a straight line. Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control. Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2204-XeMvLgE.jpg', '/static/exercises/gifs/2204-XeMvLgE.gif', '© Gym visual — https://gymvisual.com/', '902007'),
('102205', '滚轮髋部背阔肌拉伸', '腘绳肌', '泡沫轴', '未分级', '首先跪在地上，将滚轮放在臀部下方。将双手放在滚轮上以获得支撑。慢慢地向前滚动滚轮，伸展臀部并伸展臀部。保持伸展几秒钟，然后滚回起始位置。重复所需的重复次数。', 'exercise-dataset', '2205', 'roller hip lat stretch', 'upper legs', '大腿', '40', 'roller', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Start by kneeling on the ground with the roller positioned under your hips. Place your hands on the roller for support. Slowly roll the roller forward, extending your hips and stretching your glutes. Hold the stretch for a few seconds, then roll back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2205-0L2KwtI.jpg', '/static/exercises/gifs/2205-0L2KwtI.gif', '© Gym visual — https://gymvisual.com/', '902010'),
('102202', '滚轮髋部拉伸', '腘绳肌', '泡沫轴', '未分级', '首先坐在地上，双腿在身前伸展。将滚轮放在臀部下方、膝盖上方。向后倾斜，双手放在身后的地面上以获得支撑。收紧臀部，慢慢向前滚动滚轮，弯曲膝盖并将其拉向胸部。动作结束时暂停片刻，感受臀部的拉伸。慢慢地将滚轮滚回起始位置，伸展双腿。重复所需的重复次数。', 'exercise-dataset', '2202', 'roller hip stretch', 'upper legs', '大腿', '40', 'roller', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Start by sitting on the ground with your legs extended in front of you. Place the roller under your glutes, just above your knees. Lean back and place your hands on the ground behind you for support. Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest. Pause for a moment at the end of the movement, feeling a stretch in your glutes. Slowly roll the roller back to the starting position, extending your legs. Repeat for the desired number of repetitions.', '/static/exercises/images/2202-oMypNrz.jpg', '/static/exercises/gifs/2202-oMypNrz.gif', '© Gym visual — https://gymvisual.com/', '902009'),
('102206', '滚轮反向卷腹', '髋屈肌', '泡沫轴', '未分级', '平躺，双臂伸直过头顶，双腿伸直在身前。将滚筒放在双脚之间，并用脚趾抓住它。收紧腹肌，将双腿抬离地面，将膝盖向胸部弯曲，将滚轮向身体方向滚动。在顶部停顿片刻，然后慢慢将双腿放回起始位置，将滚轮滚离身体。重复所需的重复次数。', 'exercise-dataset', '2206', 'roller reverse crunch', 'waist', '腰腹', '60', 'roller', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you. Place the roller between your feet and grip it with your toes. Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body. Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body. Repeat for the desired number of repetitions.', '/static/exercises/images/2206-SKXQAx3.jpg', '/static/exercises/gifs/2206-SKXQAx3.gif', '© Gym visual — https://gymvisual.com/', '82010'),
('102203', '滚轮坐姿肩部屈肌下压后缩', '三角肌', '泡沫轴', '未分级', '坐在平坦的表面上，双腿在身前伸展。双手握住滚轮，掌心朝下，将其放在大腿上。稍微向前倾，将滚轮滚离身体，将手臂伸直在身前。暂停片刻，然后慢慢将滚轮向身体方向滚动，弯曲手臂，将滚轮拉回到大腿处。重复所需的重复次数。', 'exercise-dataset', '2203', 'roller seated shoulder flexor depresor retractor', 'chest', '胸部', '10', 'roller', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Sit on a flat surface with your legs extended in front of you. Hold the roller with both hands, palms facing down, and place it on your thighs. Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you. Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs. Repeat for the desired number of repetitions.', '/static/exercises/images/2203-8coXSYU.jpg', '/static/exercises/gifs/2203-8coXSYU.gif', '© Gym visual — https://gymvisual.com/', '902017'),
('102209', '滚轮坐姿单侧腿肩部屈肌下压后缩', '三角肌', '泡沫轴', '未分级', '坐在平坦的表面上，双腿在身前伸展。双手握住滚轮，掌心朝下，将其放在大腿上。稍微向后倾斜并锻炼核心肌肉。将滚轮抬高至肩部高度，保持手臂伸直。慢慢地将滚轮放回到大腿处。重复所需的重复次数。', 'exercise-dataset', '2209', 'roller seated single leg shoulder flexor depresor retractor', 'chest', '胸部', '10', 'roller', 'deltoids', 'pectorals', '胸肌', '["三角肌","肱三头肌"]', 'Sit on a flat surface with your legs extended in front of you. Hold the roller with both hands, palms facing down, and place it on your thighs. Lean back slightly and engage your core muscles. Raise the roller up to shoulder level, keeping your arms straight. Slowly lower the roller back down to your thighs. Repeat for the desired number of repetitions.', '/static/exercises/images/2209-CjETvlw.jpg', '/static/exercises/gifs/2209-CjETvlw.gif', '© Gym visual — https://gymvisual.com/', '902022'),
('102207', '滚轮侧向背阔肌拉伸', '肩部', '泡沫轴', '未分级', '双脚分开与肩同宽站立，双手握住滚轮放在身体前方。稍微弯曲膝盖，髋部向前转动，保持背部挺直。向前伸展双臂，将滚轮向脚部方向滚动，感受背阔肌的拉伸。保持拉伸几秒钟，然后慢慢地将滚轮滚动回起始位置。重复所需的重复次数。', 'exercise-dataset', '2207', 'roller side lat stretch', 'back', '背部', '20', 'roller', 'shoulders', 'lats', '背阔肌', '["肩部","肱三头肌"]', 'Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats. Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2207-c3Pfhti.jpg', '/static/exercises/gifs/2207-c3Pfhti.gif', '© Gym visual — https://gymvisual.com/', '902015'),
('100680', '绳索攀爬', '前臂', '绳索', '未分级', '面向绳子站立，双脚分开与肩同宽。用双手抓住绳子，手掌朝向自己。稍微弯曲膝盖并启动核心。开始通过交替的双手动作将自己拉上绳子。用双腿协助向上运动。继续攀爬，直到到达所需的高度或绳索的顶部。要下降，请在控制下降的同时反转双手的动作。重复所需的重复次数。', 'exercise-dataset', '0680', 'rope climb', 'back', '背部', '20', 'rope', 'forearms', 'upper back', '上背部', '["前臂","肱二头肌","肩部"]', 'Stand facing the rope with your feet shoulder-width apart. Grab the rope with both hands, palms facing towards you. Bend your knees slightly and engage your core. Begin pulling yourself up the rope by alternating hand-over-hand movements. Use your legs to assist in the upward movement. Continue climbing until you reach the desired height or the top of the rope. To descend, reverse the hand-over-hand movement while controlling your descent. Repeat for the desired number of repetitions.', '/static/exercises/images/0680-yaAxcQr.jpg', '/static/exercises/gifs/0680-yaAxcQr.gif', '© Gym visual — https://gymvisual.com/', '902012'),
('100685', '跑', '股四头肌', '自重', '未分级', '首先站直，双脚分开与臀部同宽。启动你的核心并保持上半身放松。开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。保持稳定的步伐并继续慢跑所需的时间或距离。记住在整个练习过程中深呼吸并保持良好的姿势。', 'exercise-dataset', '0685', 'run', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet. Maintain a steady pace and continue jogging for the desired duration or distance. Remember to breathe deeply and maintain good posture throughout the exercise.', '/static/exercises/images/0685-oLrKqDH.jpg', '/static/exercises/gifs/0685-oLrKqDH.gif', '© Gym visual — https://gymvisual.com/', '481111'),
('100684', '跑器械', '股四头肌', '自重', '未分级', '首先站直，双脚分开与臀部同宽。启动你的核心并保持上半身放松。开始原地慢跑，将膝盖抬向胸部，然后轻轻落在脚掌上。保持稳定的步伐并继续慢跑所需的时间或距离。记住在整个练习过程中深呼吸并保持良好的姿势。', 'exercise-dataset', '0684', 'run (equipment)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet. Maintain a steady pace and continue jogging for the desired duration or distance. Remember to breathe deeply and maintain good posture throughout the exercise.', '/static/exercises/images/0684-y5p0H8a.jpg', '/static/exercises/gifs/0684-y5p0H8a.gif', '© Gym visual — https://gymvisual.com/', '481114'),
('101585', '跑者拉伸', '小腿肌群', '自重', '未分级', '双脚分开与臀部同宽站立。右脚向前迈出一步，保持左脚踩地。弯曲右膝，降低身体，保持左腿伸直。将双手放在右大腿上以获得支撑。保持拉伸 20-30 秒，然后换边重复。', 'exercise-dataset', '1585', 'runners stretch', 'upper legs', '大腿', '40', 'body weight', 'calves', 'hamstrings', '腘绳肌', '["小腿肌群","股四头肌"]', 'Stand with your feet hip-width apart. Take a step forward with your right foot, keeping your left foot planted. Bend your right knee and lower your body down, keeping your left leg straight. Place your hands on your right thigh for support. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '/static/exercises/images/1585-0mB6wHO.jpg', '/static/exercises/gifs/1585-0mB6wHO.gif', '© Gym visual — https://gymvisual.com/', '901115'),
('100687', '俄罗斯转体', '腹斜肌', '自重', '未分级', '坐在地上，膝盖弯曲，双脚平放在地板上。稍微向后倾斜，同时保持背部挺直并且核心参与。如果需要，双手合拢放在胸前或举重物。将脚抬离地面，在坐骨上保持平衡。将你的躯干向右扭转，将你的手或重量移向身体的右侧。暂停片刻，然后将躯干向左扭转，将手或体重移向身体的左侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0687', 'russian twist', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on the ground with your knees bent and feet flat on the floor. Lean back slightly while keeping your back straight and your core engaged. Hold your hands together in front of your chest or hold a weight if desired. Lift your feet off the ground, balancing on your sit bones. Twist your torso to the right, bringing your hands or weight towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0687-XVDdcoj.jpg', '/static/exercises/gifs/0687-XVDdcoj.gif', '© Gym visual — https://gymvisual.com/', '401116'),
('103012', '肩胛骨臂屈伸', '菱形肌', '自重', '未分级', '首先站立，双脚分开与肩同宽，双臂在身前伸展。稍微弯曲膝盖，髋部向前转动，保持背部挺直。弯曲肘部并缩回肩胛骨来降低身体，就像你试图在它们之间挤一支铅笔一样。在底部停顿片刻，然后双手用力，伸展肘部，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3012', 'scapula dips', 'back', '背部', '20', 'body weight', 'rhomboids', 'traps', '斜方肌', '["菱形肌","三角肌"]', 'Start by standing with your feet shoulder-width apart and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them. Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3012-7xeukSt.jpg', '/static/exercises/gifs/3012-7xeukSt.gif', '© Gym visual — https://gymvisual.com/', '901117'),
('103021', '肩胛骨俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。将胸部压向地面，保持肘部靠近身体。当你下降时，将肩胛骨挤压在一起并将胸部向前推。在底部停顿片刻，然后推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3021', 'scapula push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'serratus anterior', '前锯肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Lower your chest towards the ground, keeping your elbows close to your body. As you lower, squeeze your shoulder blades together and push your chest forward. Pause for a moment at the bottom, then push back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3021-jV65tKx.jpg', '/static/exercises/gifs/3021-jV65tKx.gif', '© Gym visual — https://gymvisual.com/', '81118'),
('100688', '肩胛引体向上', '肱二头肌', '自重', '未分级', '首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。通过向下拉和向后拉动肩胛骨来缩回肩胛骨。启动背部肌肉，将身体拉向杠铃杆，重点是将肩胛骨挤压在一起。在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0688', 'scapular pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'traps', '斜方肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended. Retract your shoulder blades by pulling them down and back. Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0688-uTBt1HV.jpg', '/static/exercises/gifs/0688-uTBt1HV.gif', '© Gym visual — https://gymvisual.com/', '1119'),
('103219', '剪刀跳跳跃（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。跳离地面，同时将右腿交叉到左腿前面。落地时，快速换腿，将左腿交叉在右腿前面。继续交替双腿并尽可能快地跳跃。重复所需的重复次数。', 'exercise-dataset', '3219', 'scissor jumps (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Jump off the ground and simultaneously cross your right leg in front of your left leg. As you land, quickly switch legs, crossing your left leg in front of your right leg. Continue alternating legs and jumping as quickly as possible. Repeat for the desired number of repetitions.', '/static/exercises/images/3219-Eh2v5Iu.jpg', '/static/exercises/gifs/3219-Eh2v5Iu.gif', '© Gym visual — https://gymvisual.com/', '561122'),
('101390', '坐姿小腿拉伸（男）', '腘绳肌', '自重', '未分级', '坐在椅子或长凳的边缘，双脚平放在地面上。将一只腿伸直在身前，脚跟保持在地面上。稍微向前倾，感受小腿肌肉的拉伸。保持拉伸 20-30 秒。换腿并重复拉伸。', 'exercise-dataset', '1390', 'seated calf stretch (male)', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Sit on the edge of a chair or bench with your feet flat on the ground. Extend one leg straight out in front of you, keeping your heel on the ground. Lean forward slightly, feeling a stretch in your calf muscle. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', '/static/exercises/images/1390-17bqEXD.jpg', '/static/exercises/gifs/1390-17bqEXD.gif', '© Gym visual — https://gymvisual.com/', '901125'),
('101424', '坐姿臀肌拉伸', '腘绳肌', '自重', '未分级', '坐在地上，双腿在身前伸展。弯曲右膝，将右脚踝交叉在左大腿上。将右手放在身后的地面上以获得支撑。用左手轻轻按下右膝盖以加深伸展。保持拉伸 30 秒到 1 分钟。换边并重复。', 'exercise-dataset', '1424', 'seated glute stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Sit on the ground with your legs extended in front of you. Bend your right knee and cross your right ankle over your left thigh. Place your right hand on the ground behind you for support. With your left hand, gently press down on your right knee to deepen the stretch. Hold the stretch for 30 seconds to 1 minute. Switch sides and repeat.', '/static/exercises/images/1424-DeDThfG.jpg', '/static/exercises/gifs/1424-DeDThfG.gif', '© Gym visual — https://gymvisual.com/', '901124'),
('100689', '坐姿举腿', '髋屈肌', '自重', '未分级', '坐在平坦的长凳上，背部挺直，双脚平放在地面上。将双手放在长凳两侧以获得支撑。保持双腿伸直，慢慢将它们抬起到您面前，直到它们与地面平行。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0689', 'seated leg raise', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on a flat bench with your back straight and your feet flat on the ground. Place your hands on the sides of the bench for support. Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0689-Hgs6Nl1.jpg', '/static/exercises/gifs/0689-Hgs6Nl1.gif', '© Gym visual — https://gymvisual.com/', '241125'),
('100690', '坐姿下部后侧拉伸', '臀肌', '自重', '未分级', '坐在椅子边缘，双脚平放在地面上。将双手放在大腿上或椅子两侧以获得支撑。从臀部开始慢慢向前倾斜，保持背部挺直。感受下背部的拉伸并保持 20-30 秒。慢慢回到起始位置并重复所需的重复次数。', 'exercise-dataset', '0690', 'seated lower back stretch', 'back', '背部', '20', 'body weight', 'glutes', 'lats', '背阔肌', '["臀肌","腘绳肌"]', 'Sit on the edge of a chair with your feet flat on the ground. Place your hands on your thighs or on the sides of the chair for support. Slowly lean forward from your hips, keeping your back straight. Feel the stretch in your lower back and hold for 20-30 seconds. Slowly return to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/0690-QFmz6ch.jpg', '/static/exercises/gifs/0690-QFmz6ch.gif', '© Gym visual — https://gymvisual.com/', '901128'),
('102567', '坐姿梨状肌拉伸', '腘绳肌', '自重', '未分级', '坐在地上，双腿在身前伸展。弯曲右膝，将右脚放在左膝外侧。将左肘放在右膝外侧，轻轻地将躯干向右扭转。保持拉伸 20-30 秒，然后换边重复。', 'exercise-dataset', '2567', 'seated piriformis stretch', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌"]', 'Sit on the ground with your legs extended in front of you. Bend your right knee and place your right foot on the outside of your left knee. Place your left elbow on the outside of your right knee and gently twist your torso to the right. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '/static/exercises/images/2567-QY39eBr.jpg', '/static/exercises/gifs/2567-QY39eBr.gif', '© Gym visual — https://gymvisual.com/', '901127'),
('100691', '坐姿侧向卷腹靠墙', '腹斜肌', '自重', '未分级', '坐在地板上，背靠墙，双腿在身前伸展。弯曲膝盖，将双脚平放在地板上，与臀部同宽。将双手放在脑后，肘部朝外。收紧腹肌并向一侧倾斜，将肘部靠近臀部。暂停片刻，然后回到起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '0691', 'seated side crunch (wall)', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Sit on the floor with your back against a wall and your legs extended in front of you. Bend your knees and place your feet flat on the floor, hip-width apart. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lean to one side, bringing your elbow towards your hip. Pause for a moment, then return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0691-Y9hNPcN.jpg', '/static/exercises/gifs/0691-Y9hNPcN.gif', '© Gym visual — https://gymvisual.com/', '81130'),
('101587', '坐姿宽距角度姿势组合', '股四头肌', '自重', '未分级', '坐在地上，双腿大角度伸展。弯曲你的脚并锻炼你的股四头肌。将双手放在身后的地面上以获得支撑。保持背部挺直，从臀部向前倾。继续向前倾斜，直到感觉到腿筋被拉伸。保持这个姿势几个呼吸。慢慢释放拉伸并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1587', 'seated wide angle pose sequence', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'hamstrings', '腘绳肌', '["股四头肌","小腿肌群"]', 'Sit on the ground with your legs extended in a wide angle. Flex your feet and engage your quadriceps. Place your hands on the ground behind you for support. Keeping your back straight, lean forward from your hips. Continue leaning forward until you feel a stretch in your hamstrings. Hold this position for a few breaths. Slowly release the stretch and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1587-HIgYKAB.jpg', '/static/exercises/gifs/1587-HIgYKAB.gif', '© Gym visual — https://gymvisual.com/', '901133'),
('100697', '自助辅助反向腿弯举', '臀肌', '自重', '未分级', '平躺在垫子或长凳上，双腿伸展。将双手放在身体两侧或臀部下方以获得支撑。弯曲膝盖，将脚抬离地面，将大腿靠近胸部。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0697', 'self assisted inverse leg curl', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Lie flat on your back on a mat or bench with your legs extended. Place your hands by your sides or under your glutes for support. Bend your knees and lift your feet off the ground, bringing your thighs towards your chest. Pause for a moment at the top, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0697-GwYwElT.jpg', '/static/exercises/gifs/0697-GwYwElT.gif', '© Gym visual — https://gymvisual.com/', '481134'),
('101766', '自助辅助反向腿弯举', '臀肌', '自重', '未分级', '面朝下躺在腿弯举机上，双腿伸展，脚踝钩在带衬垫的杠杆下。将双手放在机器的侧手柄上以获得支撑。保持上半身静止，呼气并尽可能向上弯曲双腿。挤压腿筋时，保持收缩位置短暂停顿。吸气时慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1766', 'self assisted inverse leg curl', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever. Place your hands on the side handles of the machine for support. Keeping your upper body stationary, exhale and curl your legs upward as far as possible. Hold the contracted position for a brief pause as you squeeze your hamstrings. Slowly lower your legs back to the starting position while inhaling. Repeat for the desired number of repetitions.', '/static/exercises/images/1766-ZSY3MsL.jpg', '/static/exercises/gifs/1766-ZSY3MsL.gif', '© Gym visual — https://gymvisual.com/', '481135'),
('100696', '自助辅助反向腿弯举地板', '臀肌', '自重', '未分级', '平躺，双腿伸展，双臂放在身体两侧。弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。将臀部抬离地面，锻炼臀肌和腿筋。慢慢地将双腿向臀部弯曲，保持臀部抬起。在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。将臀部放回地面。重复所需的重复次数。', 'exercise-dataset', '0696', 'self assisted inverse leg curl (on floor)', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","小腿肌群"]', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and place your feet flat on the ground, hip-width apart. Lift your hips off the ground, engaging your glutes and hamstrings. Slowly curl your legs towards your glutes, keeping your hips lifted. Pause for a moment at the top, then slowly extend your legs back to the starting position. Lower your hips back down to the ground. Repeat for the desired number of repetitions.', '/static/exercises/images/0696-E4PwJqI.jpg', '/static/exercises/gifs/0696-E4PwJqI.gif', '© Gym visual — https://gymvisual.com/', '481140'),
('103222', '半深蹲跳跃（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。弯曲膝盖并将身体降低至蹲姿。爆发性跳跃，伸展臀部和膝盖，同时摆动手臂以获得动力。脚掌轻轻落地，然后立即进入下一个重复动作。重复所需的重复次数。', 'exercise-dataset', '3222', 'semi squat jump (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively, extending your hips and knees while swinging your arms for momentum. Land softly on the balls of your feet and immediately go into the next repetition. Repeat for the desired number of repetitions.', '/static/exercises/images/3222-6FMU51h.jpg', '/static/exercises/gifs/3222-6FMU51h.gif', '© Gym visual — https://gymvisual.com/', '561135'),
('103656', '短程步幅跑', '股四头肌', '自重', '未分级', '找一个空地或跑步机来进行锻炼。站直，双脚分开与臀部同宽。开始原地慢跑，抬起膝盖并挥动手臂。几秒钟后，开始小步前进，保持快速的步伐。继续小步跑所需的时间或距离。', 'exercise-dataset', '3656', 'short stride run', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Find an open space or a treadmill to perform the exercise. Stand tall with your feet hip-width apart. Start jogging in place, lifting your knees high and pumping your arms. After a few seconds, start taking short strides forward, maintaining a quick pace. Continue running with short strides for the desired duration or distance.', '/static/exercises/images/3656-CcWEoWV.jpg', '/static/exercises/gifs/3656-CcWEoWV.gif', '© Gym visual — https://gymvisual.com/', '481134'),
('101763', '肩部握引体向上', '肱二头肌', '自重', '未分级', '握距与肩同宽，抓住引体向上杆，手掌背向自己。双臂完全伸展，自由悬挂。启动背部肌肉，将身体向上拉向杠铃，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1763', 'shoulder grip pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with a shoulder-width grip, palms facing away from you. Hang freely with your arms fully extended. Engage your back muscles and pull your body up towards the bar until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1763-YtgD7Xq.jpg', '/static/exercises/gifs/1763-YtgD7Xq.gif', '© Gym visual — https://gymvisual.com/', '1135'),
('103699', '肩部触碰', '肩部', '自重', '未分级', '从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。启动你的核心并将右手抬离地面，伸手拍打你的左肩。将右手放回地面，然后用左手轻拍右肩，重复此操作。继续交替轻拍肩膀，同时保持臀部和躯干稳定。重复所需的重复次数。', 'exercise-dataset', '3699', 'shoulder tap', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌"]', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder. Place your right hand back on the ground and repeat with your left hand tapping your right shoulder. Continue alternating shoulder taps while keeping your hips and torso stable. Repeat for the desired number of repetitions.', '/static/exercises/images/3699-yRpV5TC.jpg', '/static/exercises/gifs/3699-yRpV5TC.gif', '© Gym visual — https://gymvisual.com/', '901134'),
('100699', '肩部触碰俯卧撑', '肱三头肌', '自重', '未分级', '从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。当你向后推时，将右手抬离地面并轻拍左肩。将右手放回地面并重复俯卧撑，这次抬起左手并拍打右肩。每次重复俯卧撑时，继续交替拍肩。在整个练习过程中保持核心稳定并避免臀部过度旋转。重复所需的重复次数。', 'exercise-dataset', '0699', 'shoulder tap push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","核心肌群"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you push back up, lift your right hand off the ground and tap your left shoulder. Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder. Continue alternating shoulder taps with each push-up repetition. Maintain a stable core and avoid excessive hip rotation throughout the exercise. Repeat for the desired number of repetitions.', '/static/exercises/images/0699-qEse6fe.jpg', '/static/exercises/gifs/0699-qEse6fe.gif', '© Gym visual — https://gymvisual.com/', '81137'),
('101774', '侧向桥式髋外展', '臀肌', '自重', '未分级', '侧躺，双腿伸展并叠放在一起。用前臂支撑自己，将肘部保持在肩膀正下方。启动你的核心并将臀部抬离地面，从头到脚形成一条直线。在保持核心肌群参与的同时，尽可能高地抬起上面的那条腿，但不要旋转臀部。在顶部停顿片刻，然后将腿放下。重复所需的重复次数，然后换边。', 'exercise-dataset', '1774', 'side bridge hip abduction', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'abductors', '外展肌群', '["臀肌","腹斜肌"]', 'Lie on your side with your legs extended and stacked on top of each other. Prop yourself up on your forearm, keeping your elbow directly below your shoulder. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. While keeping your core engaged, lift your top leg as high as possible without rotating your hips. Pause for a moment at the top, then lower your leg back down. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1774-WL4EmxJ.jpg', '/static/exercises/gifs/1774-WL4EmxJ.gif', '© Gym visual — https://gymvisual.com/', '901140'),
('100705', '侧向桥式版本第二式', '腹斜肌', '自重', '未分级', '侧躺，双腿伸展并叠放在一起。将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。启动你的核心并将臀部抬离地面，从头到脚形成一条直线。保持此位置所需的时间。将臀部放低至起始位置。在另一侧重复。', 'exercise-dataset', '0705', 'side bridge v. 2', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","臀肌"]', 'Lie on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. Hold this position for the desired amount of time. Lower your hips back down to the starting position. Repeat on the other side.', '/static/exercises/images/0705-RKjH6Lt.jpg', '/static/exercises/gifs/0705-RKjH6Lt.gif', '© Gym visual — https://gymvisual.com/', '901141'),
('100709', '侧向髋部平行握双杠', '腹斜肌', '自重', '未分级', '站在两根平行杠之间，双脚分开与肩同宽。将双手放在横杆上，将身体抬离地面，用手臂支撑体重。收紧腹肌，慢慢将双腿向一侧抬起，保持伸直。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0709', 'side hip (on parallel bars)', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Stand between two parallel bars with your feet shoulder-width apart. Place your hands on the bars and lift your body off the ground, supporting your weight on your arms. Engage your abs and slowly lift your legs to the side, keeping them straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0709-jTkSc6o.jpg', '/static/exercises/gifs/0709-jTkSc6o.gif', '© Gym visual — https://gymvisual.com/', '901144'),
('100710', '侧向髋外展', '臀肌', '自重', '未分级', '双脚分开与肩同宽站立，双手放在臀部。将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。在顶部暂停片刻，然后慢慢将腿放回起始位置。在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '0710', 'side hip abduction', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'abductors', '外展肌群', '["臀肌","股四头肌"]', 'Stand with your feet shoulder-width apart and your hands on your hips. Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0710-7WaDzyL.jpg', '/static/exercises/gifs/0710-7WaDzyL.gif', '© Gym visual — https://gymvisual.com/', '901141'),
('101358', '侧向仰卧地板拉伸', '腹斜肌', '自重', '未分级', '侧躺，双腿伸直，下臂伸直过头顶。弯曲上面的膝盖，将脚放在下面的腿前面的地面上。将上臂伸过头顶，抓住稳定的东西，例如墙壁或一件家具。慢慢地将下面的腿抬离地面，保持伸直，直到感觉到身体一侧有拉伸感。保持拉伸 20-30 秒，然后慢慢将腿放下。在另一侧重复。', 'exercise-dataset', '1358', 'side lying floor stretch', 'back', '背部', '20', 'body weight', 'obliques', 'lats', '背阔肌', '["腹斜肌","臀肌"]', 'Lie on your side with your legs straight and your bottom arm extended straight overhead. Bend your top knee and place your foot on the ground in front of your bottom leg. Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture. Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side. Hold the stretch for 20-30 seconds, then slowly lower your leg back down. Repeat on the other side.', '/static/exercises/images/1358-jDOKRM5.jpg', '/static/exercises/gifs/1358-jDOKRM5.gif', '© Gym visual — https://gymvisual.com/', '901144'),
('103667', '侧向仰卧髋内收（男）', '臀肌', '自重', '未分级', '侧躺，双腿伸直并叠放在一起。将下臂放在头下方以获得支撑。启动内收肌并尽可能高地抬起上面的腿，但不要旋转臀部或向后倾斜。在顶部暂停片刻，然后慢慢将腿放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '3667', 'side lying hip adduction (male)', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'adductors', '内收肌群', '["臀肌","腘绳肌"]', 'Lie on your side with your legs straight and stacked on top of each other. Place your bottom arm under your head for support. Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/3667-c8f5cSY.jpg', '/static/exercises/gifs/3667-c8f5cSY.gif', '© Gym visual — https://gymvisual.com/', '901147'),
('101775', '侧平板支撑髋内收', '腹斜肌', '自重', '未分级', '首先侧躺，双腿伸展并叠放在一起。用前臂支撑自己，将肘部保持在肩膀正下方。启动你的核心并将臀部抬离地面，从头到脚形成一条直线。在保持侧平板支撑位置的同时，将上面的腿抬向天花板，保持笔直。慢慢地将腿放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1775', 'side plank hip adduction', 'upper legs', '大腿', '40', 'body weight', 'obliques', 'adductors', '内收肌群', '["腹斜肌","臀肌"]', 'Start by lying on your side with your legs extended and stacked on top of each other. Prop yourself up on your forearm, keeping your elbow directly below your shoulder. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight. Slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1775-VO2qeJg.jpg', '/static/exercises/gifs/1775-VO2qeJg.gif', '© Gym visual — https://gymvisual.com/', '901146'),
('100716', '侧向推颈部拉伸', '斜方肌', '自重', '未分级', '站直或坐直，肩膀放松。将头向右倾斜，将右耳靠近右肩。将右手放在头部左侧，轻轻施加压力以增加拉伸。保持拉伸 15-30 秒。在另一侧重复，将头向左倾斜并用左手施加压力。每侧重复拉伸 2-3 次。', 'exercise-dataset', '0716', 'side push neck stretch', 'neck', '颈部', '100', 'body weight', 'trapezius', 'levator scapulae', '肩胛提肌', '["斜方肌","STERNOCLEIDOMASTOID"]', 'Stand or sit up straight with your shoulders relaxed. Tilt your head to the right, bringing your right ear towards your right shoulder. Place your right hand on the left side of your head and gently apply pressure to increase the stretch. Hold the stretch for 15-30 seconds. Repeat on the other side, tilting your head to the left and applying pressure with your left hand. Repeat the stretch 2-3 times on each side.', '/static/exercises/images/0716-oQRJYkC.jpg', '/static/exercises/gifs/0716-oQRJYkC.gif', '© Gym visual — https://gymvisual.com/', '901147'),
('100717', '侧向俯卧撑', '肩部', '自重', '未分级', '首先侧躺，双腿伸展并叠放在一起。将下面的手放在肩膀正下方的地面上，手指指向前方。用下面的手将身体抬离地面，保持双腿伸直，核心肌群参与。将上臂伸向天花板，形成从头部到脚后跟的直线。有控制地降低身体回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0717', 'side push-up', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部","胸肌","核心肌群"]', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your bottom hand on the ground directly under your shoulder, fingers pointing forward. Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged. Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0717-wpbD28t.jpg', '/static/exercises/gifs/0717-wpbD28t.gif', '© Gym visual — https://gymvisual.com/', '901144'),
('100721', '侧向手腕拉拉伸', '手腕', '自重', '未分级', '双脚分开与肩同宽站立，双臂在身前伸展。将右臂向侧面伸出，与地面平行，手掌朝下。用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。保持拉伸 15-30 秒，然后放松。在另一侧重复。', 'exercise-dataset', '0721', 'side wrist pull stretch', 'lower arms', '前臂', '80', 'body weight', 'wrists', 'forearms', '前臂肌群', '["手腕","手部"]', 'Stand with your feet shoulder-width apart and your arms extended in front of you. Extend your right arm out to the side, parallel to the ground, with your palm facing down. With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', '/static/exercises/images/0721-UtmIqcI.jpg', '/static/exercises/gifs/0721-UtmIqcI.gif', '© Gym visual — https://gymvisual.com/', '901149'),
('100720', '侧向侧向引体', '肱二头肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住引体向上杆，双手之间的距离略大于肩宽。悬挂在杠上，双臂完全伸展，身体放松。弯曲肘部并将下巴朝向杠铃杆，将自己拉起，同时保持身体挺直。一旦你的下巴高于杠铃，就将自己放低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0720', 'side-to-side chin', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body relaxed. Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight. Once your chin is above the bar, lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0720-isAAZWA.jpg', '/static/exercises/gifs/0720-isAAZWA.gif', '© Gym visual — https://gymvisual.com/', '901146'),
('103213', '侧向侧向脚尖触碰（男）', '腹斜肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂向两侧伸展。腰部向右弯曲，将右手伸向右脚，同时保持左手向一侧延伸。返回起始位置，然后腰部向左弯曲，将左手伸向左脚，同时保持右手向侧面延伸。重复左右弯曲动作达到所需的重复次数。', 'exercise-dataset', '3213', 'side-to-side toe touch (male)', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Stand with your feet shoulder-width apart and your arms extended to the sides. Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side. Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side. Repeat the side-to-side bending motion for the desired number of repetitions.', '/static/exercises/images/3213-WCAvOfC.jpg', '/static/exercises/gifs/3213-WCAvOfC.gif', '© Gym visual — https://gymvisual.com/', '901151'),
('100725', '单侧臂俯卧撑', '肱三头肌', '自重', '未分级', '从俯卧撑位置开始，双手分开与肩同宽，一只手比另一只手稍宽。弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。当你降低身体时，将你的重心转移到一侧，并将另一只手臂抬离地面，将其笔直延伸到一侧。推动胸部和三头肌，将身体抬回到起始位置，同时将伸出的手臂放回地面。重复该动作，每次重复时交替伸展手臂。', 'exercise-dataset', '0725', 'single arm push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight. As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side. Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground. Repeat the movement, alternating the arm you extend with each repetition.', '/static/exercises/images/0725-MUic5zN.jpg', '/static/exercises/gifs/0725-MUic5zN.gif', '© Gym visual — https://gymvisual.com/', '81150'),
('103645', '单侧腿桥式伸直腿', '腘绳肌', '自重', '未分级', '仰卧，膝盖弯曲，双脚平放在地上。将一条腿伸直在您面前。收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。在顶部保持片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '3645', 'single leg bridge with outstretched leg', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌"]', 'Lie on your back with your knees bent and feet flat on the ground. Extend one leg straight out in front of you. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. Hold for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/3645-rmEukuS.jpg', '/static/exercises/gifs/3645-rmEukuS.gif', '© Gym visual — https://gymvisual.com/', '901157'),
('100727', '单侧腿提踵哑铃', '踝部肌群', '哑铃', '未分级', '双脚分开与臀部同宽站立，一只手握住哑铃。将一只脚抬离地面并用另一只脚保持平衡。使用小腿肌肉，慢慢地将脚跟抬高，尽可能高。在顶部停顿片刻，然后慢慢降低脚跟。重复所需的重复次数，然后换另一条腿。', 'exercise-dataset', '0727', 'single leg calf raise (on a dumbbell)', 'lower legs', '小腿', '70', 'dumbbell', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand with your feet hip-width apart and hold a dumbbell in one hand. Lift one foot off the ground and balance on the other foot. Slowly raise your heel as high as possible, using your calf muscles. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch to the other leg.', '/static/exercises/images/0727-fKZgDEO.jpg', '/static/exercises/gifs/0727-fKZgDEO.gif', '© Gym visual — https://gymvisual.com/', '1360'),
('100730', '单侧腿平台滑动', '臀肌', '自重', '未分级', '首先将一只脚站在平台或滑板上。稍微弯曲膝盖，将脚向后滑动到平台上，伸展腿。在整个运动过程中保持核心参与并保持笔直姿势。将脚滑回初始位置，慢慢返回起始位置。重复该动作达到所需的重复次数，然后换腿。', 'exercise-dataset', '0730', 'single leg platform slide', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","股四头肌"]', 'Start by standing with one foot on a platform or slide board. Bend your knee slightly and slide the foot on the platform backward, extending your leg. Keep your core engaged and maintain a straight posture throughout the movement. Slowly return to the starting position by sliding your foot back to the initial position. Repeat the movement for the desired number of repetitions, then switch legs.', '/static/exercises/images/0730-LNE3wfo.jpg', '/static/exercises/gifs/0730-LNE3wfo.gif', '© Gym visual — https://gymvisual.com/', '901155'),
('101759', '单侧腿深蹲手枪式（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂在身前伸展。将右脚抬离地面并向前伸展。弯曲左膝并将臀部向后推，慢慢降低身体。降低身体时，保持挺胸、背部挺直。降低直到左大腿与地面平行，或者尽可能降低到您能舒服的高度。在底部停顿片刻，然后推动左脚跟回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '1759', 'single leg squat (pistol) male', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and arms extended in front of you. Lift your right foot off the ground and extend it forward. Slowly lower your body down by bending your left knee and pushing your hips back. Keep your chest up and your back straight as you lower yourself down. Lower until your left thigh is parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/1759-nqs5HGV.jpg', '/static/exercises/gifs/1759-nqs5HGV.gif', '© Gym visual — https://gymvisual.com/', '1158'),
('101489', '西西深蹲', '小腿肌群', '自重', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。如果需要，请抓住一个稳定的物体以保持平衡。弯曲膝盖并向后倾斜，慢慢降低身体，保持躯干直立。继续降低，直到大腿与地面平行或尽可能舒适地下降。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1489', 'sissy squat', 'upper legs', '大腿', '40', 'body weight', 'calves', 'quads', '股四头肌', '["小腿肌群","臀肌"]', 'Stand with your feet shoulder-width apart and your toes pointing slightly outward. Hold onto a stable object for balance if needed. Slowly lower your body by bending your knees and leaning back, keeping your torso upright. Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1489-xdYPUtE.jpg', '/static/exercises/gifs/1489-xdYPUtE.gif', '© Gym visual — https://gymvisual.com/', '1153'),
('100735', '坐向上版本第二式', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0735', 'sit-up v. 2', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0735-Bn6TXyO.jpg', '/static/exercises/gifs/0735-Bn6TXyO.gif', '© Gym visual — https://gymvisual.com/', '161156'),
('103679', '坐向上双臂胸部', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。双臂交叉于胸前。收紧腹肌，将上半身抬离地面，靠近膝盖。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3679', 'sit-up with arms on chest', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Cross your arms over your chest. Engaging your abs, lift your upper body off the ground towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3679-6ZCiYWQ.jpg', '/static/exercises/gifs/3679-6ZCiYWQ.gif', '© Gym visual — https://gymvisual.com/', '161161'),
('103361', '滑冰式跳跃', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。稍微弯曲膝盖，向右跳，右脚着地。落地时，将左腿摆动到右腿后面，并用左脚趾敲击地面。立即向左侧跳跃，左脚着地。落地时，将右腿摆动到左腿后面，并用右脚趾敲击地面。继续交替两侧，跳跃并用每条腿敲击地面。重复所需的重复次数。', 'exercise-dataset', '3361', 'skater hops', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump to the right, landing on your right foot. As you land, swing your left leg behind your right leg and tap the ground with your left toes. Immediately jump to the left, landing on your left foot. As you land, swing your right leg behind your left leg and tap the ground with your right toes. Continue alternating sides, jumping and tapping the ground with each leg. Repeat for the desired number of repetitions.', '/static/exercises/images/3361-zfNHMN9.jpg', '/static/exercises/gifs/3361-zfNHMN9.gif', '© Gym visual — https://gymvisual.com/', '901156'),
('102142', '滑雪式功率车', '肩部', '滑雪机', '未分级', '将座椅高度和脚踏板调整到舒适的位置。正手握住手柄，手掌朝下。坐直，双脚平放在脚踏板上。将手臂伸直在身前，保持肘部稍微弯曲。收紧三头肌并将手柄向下推向大腿。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2142', 'ski ergometer', 'upper arms', '上臂', '50', 'skierg machine', 'shoulders', 'triceps', '肱三头肌', '["肩部","前臂"]', 'Adjust the seat height and footrests to a comfortable position. Grasp the handles with an overhand grip, palms facing down. Sit up straight with your feet flat on the footrests. Extend your arms straight out in front of you, keeping your elbows slightly bent. Engage your triceps and push the handles down towards your thighs. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2142-vpQaQkH.jpg', '/static/exercises/gifs/2142-vpQaQkH.gif', '© Gym visual — https://gymvisual.com/', '902057'),
('103671', '滑雪式踏步', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。稍微弯曲膝盖并保持背部挺直。跳到右侧，右脚着地，同时将左腿摆动到右腿后面。立即向左侧跳，左脚着地，同时将右腿摆动到左腿后面。继续从一侧到另一侧交替跳跃，模仿滑雪动作。重复所需的重复次数。', 'exercise-dataset', '3671', 'ski step', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Bend your knees slightly and keep your back straight. Jump to the right, landing on your right foot while swinging your left leg behind your right leg. Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg. Continue alternating jumps from side to side, mimicking a skiing motion. Repeat for the desired number of repetitions.', '/static/exercises/images/3671-5MRH8H2.jpg', '/static/exercises/gifs/3671-5MRH8H2.gif', '© Gym visual — https://gymvisual.com/', '901158'),
('103304', '翻转猫式', '肩部', '自重', '未分级', '首先，将双臂完全伸展，身体放松地悬挂在杆上。收紧核心并抬起双腿，使膝盖靠近胸部。继续将双腿举过头顶，让身体穿过手臂。一旦双腿完全伸过头顶，就开始将它们放回起始位置。当你降低双腿时，让你的身体通过手臂向后移动，直到你再次完全伸展手臂悬挂。重复所需的重复次数。', 'exercise-dataset', '3304', 'skin the cat', 'back', '背部', '20', 'body weight', 'shoulders', 'upper back', '上背部', '["肩部","核心肌群"]', 'Start by hanging from a bar with your arms fully extended and your body relaxed. Engage your core and lift your legs up, bringing your knees towards your chest. Continue to lift your legs up and over your head, allowing your body to pass through the arms. Once your legs are fully extended over your head, begin to lower them back down towards the starting position. As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again. Repeat for the desired number of repetitions.', '/static/exercises/images/3304-MSfvriJ.jpg', '/static/exercises/gifs/3304-MSfvriJ.gif', '© Gym visual — https://gymvisual.com/', '901161'),
('101425', '雪橇机45度度单腿举', '股四头肌', '雪橇机', '未分级', '将雪橇机调整至 45 度角。坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。将一只脚放在踏板上并伸展腿，将雪橇推离您。慢慢弯曲膝盖，将雪橇放回起始位置。换另一条腿重复上述步骤。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '1425', 'sled 45 degrees one leg press', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the sled machine to a 45-degree angle. Sit on the sled machine with your back against the pad and your feet on the footplate. Place one foot on the footplate and extend your leg, pushing the sled away from you. Slowly bend your knee and lower the sled back to the starting position. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/1425-WWD6FzI.jpg', '/static/exercises/gifs/1425-WWD6FzI.gif', '© Gym visual — https://gymvisual.com/', '242068'),
('100738', '雪橇机45度小腿推举', '腘绳肌', '雪橇机', '未分级', '将雪橇机调整至 45 度角。将脚放在雪橇平台上，脚趾朝前。伸展脚踝和小腿，将雪橇平台推离您。在顶部暂停片刻，然后慢慢将雪橇平台放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0738', 'sled 45в° calf press', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Adjust the sled machine to a 45-degree angle. Place your feet on the sled platform with your toes pointing forward. Push the sled platform away from you by extending your ankles and calves. Pause for a moment at the top, then slowly lower the sled platform back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0738-qCNVnaU.jpg', '/static/exercises/gifs/0738-qCNVnaU.gif', '© Gym visual — https://gymvisual.com/', '902065'),
('100739', '雪橇机45度腿举', '股四头肌', '雪橇机', '未分级', '将雪橇机的座椅和脚踏板调整到舒适的位置。坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。握住座椅两侧的把手以保持稳定性。伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。重复所需的重复次数。', 'exercise-dataset', '0739', 'sled 45в° leg press', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat and footplate of the sled machine to a comfortable position. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push the footplate away from your body by extending your legs, keeping your heels on the footplate. Continue pushing until your legs are almost fully extended, but without locking your knees. Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees. Repeat for the desired number of repetitions.', '/static/exercises/images/0739-10Z2DXU.jpg', '/static/exercises/gifs/0739-10Z2DXU.gif', '© Gym visual — https://gymvisual.com/', '242066'),
('101464', '雪橇机45度腿举后侧视角', '股四头肌', '雪橇机', '未分级', '调整雪橇机的座椅，使膝盖成45度角。坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。握住座椅两侧的把手以保持稳定性。伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。在完全伸展的位置暂停片刻。慢慢弯曲膝盖，将踏板放回到身体的方向，控制动作。重复所需的重复次数。', 'exercise-dataset', '1464', 'sled 45в° leg press (back pov)', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat of the sled machine so that your knees are at a 45-degree angle. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push the footplate away from your body by extending your legs, keeping your heels on the footplate. Pause for a moment at the fully extended position. Slowly bend your knees and lower the footplate back towards your body, controlling the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/1464-yn2lLSI.jpg', '/static/exercises/gifs/1464-yn2lLSI.gif', '© Gym visual — https://gymvisual.com/', '242071'),
('101463', '雪橇机45度腿举侧向视角', '股四头肌', '雪橇机', '未分级', '调整雪橇机的座椅，使双脚放在踏板上时膝盖呈90度角。坐在雪橇机上，背部平放在靠背上，双脚与肩同宽放在踏板上。握住座椅两侧的把手以保持稳定性。推动脚踏板以伸展双腿，将其完全伸直。在顶部停顿片刻，然后慢慢弯曲膝盖，将踏板放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1463', 'sled 45° leg press (side pov)', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate. Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push against the footplate to extend your legs, straightening them completely. Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1463-2Qh2J1e.jpg', '/static/exercises/gifs/1463-2Qh2J1e.gif', '© Gym visual — https://gymvisual.com/', '242072'),
('100740', '雪橇机45度腿宽距推举', '股四头肌', '雪橇机', '未分级', '将雪橇机调整至 45 度角。坐在雪橇机上，背部靠在垫子上，双脚放在脚踏平台上。双脚分开的距离比肩宽。推动脚部平台以伸展双腿并伸直膝盖。动作结束时暂停片刻，然后慢慢弯曲膝盖回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0740', 'sled 45в° leg wide press', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the sled machine to a 45-degree angle. Sit on the sled machine with your back against the pad and your feet on the foot platform. Position your feet wider than shoulder-width apart. Push against the foot platform to extend your legs and straighten your knees. Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0740-tj41Nu6.jpg', '/static/exercises/gifs/0740-tj41Nu6.gif', '© Gym visual — https://gymvisual.com/', '902071'),
('101391', '雪橇机小腿推举腿举', '腘绳肌', '雪橇机', '未分级', '调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。将双脚与肩同宽放在雪橇上，脚趾指向前方。松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。重复所需的重复次数。', 'exercise-dataset', '1391', 'sled calf press on leg press', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","股四头肌"]', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled. Place your feet shoulder-width apart on the sled, with your toes pointing forward. Release the safety handles and push the sled away from you by extending your knees and ankles. Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles. Repeat for the desired number of repetitions.', '/static/exercises/images/1391-ykHcWme.jpg', '/static/exercises/gifs/1391-ykHcWme.gif', '© Gym visual — https://gymvisual.com/', '902074'),
('100741', '雪橇机窄距哈克深蹲', '股四头肌', '雪橇机', '未分级', '将雪橇机调整到舒适的重量，并将背部靠在垫子上。将双脚分开与肩同宽放在平台上，脚趾稍微向外。握住机器两侧的手柄以保持稳定性。弯曲膝盖和臀部，调动核心力量，慢慢降低身体，保持背部挺直。继续降低，直到大腿与地面平行或略低于地面。在底部停顿片刻，然后用脚跟推动双腿并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0741', 'sled closer hack squat', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the sled machine to a comfortable weight and position yourself with your back against the pad. Place your feet shoulder-width apart on the platform, toes slightly pointed outwards. Grip the handles on the sides of the machine for stability. Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0741-gf3ZjB9.jpg', '/static/exercises/gifs/0741-gf3ZjB9.gif', '© Gym visual — https://gymvisual.com/', '2071'),
('100742', '雪橇机向前角度式提踵', '腘绳肌', '雪橇机', '未分级', '将雪橇机调整到舒适的重量，然后将自己放在机器上，脚趾放在平台上，脚后跟悬空。将手放在机器的手柄或侧面上以获得支撑。收紧小腿，慢慢地尽可能高地抬起脚后跟，克服雪橇的阻力。在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0742', 'sled forward angled calf raise', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off. Place your hands on the handles or the sides of the machine for support. Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0742-XDOiFns.jpg', '/static/exercises/gifs/0742-XDOiFns.gif', '© Gym visual — https://gymvisual.com/', '2074'),
('100743', '雪橇机哈克深蹲', '股四头肌', '雪橇机', '未分级', '将雪橇机调整到适合您身高的舒适位置。双脚与肩同宽站立在平台上，脚趾稍微向外。握住手柄或杆以保持稳定性。弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。继续降低，直到大腿与地面平行或略低于地面。暂停片刻，然后用脚后跟将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0743', 'sled hack squat', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the sled machine to a comfortable position for your height. Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards. Hold onto the handles or bars for stability. Lower your body by bending your knees and hips, keeping your back straight and chest up. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to raise your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0743-Qa55kX1.jpg', '/static/exercises/gifs/0743-Qa55kX1.gif', '© Gym visual — https://gymvisual.com/', '2071'),
('102334', '雪橇机仰卧小腿推举', '腘绳肌', '雪橇机', '未分级', '将雪橇机调整至舒适的重量。坐在雪橇机上，背部靠在垫子上，双脚放在平台上。将脚趾和脚掌放在平台边缘，脚跟悬空。伸展脚踝，将平台推离您，保持膝盖稍微弯曲。继续用力，直到小腿完全收缩。保持收缩一会儿，然后慢慢将平台放回起始位置。重复所需的重复次数。', 'exercise-dataset', '2334', 'sled lying calf press', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the sled machine to a comfortable weight. Sit on the sled machine with your back against the pad and your feet on the platform. Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off. Push the platform away from you by extending your ankles, keeping your knees slightly bent. Continue pushing until your calves are fully contracted. Hold the contraction for a moment, then slowly lower the platform back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2334-g376LuL.jpg', '/static/exercises/gifs/2334-g376LuL.gif', '© Gym visual — https://gymvisual.com/', '902074'),
('100744', '雪橇机仰卧深蹲', '股四头肌', '雪橇机', '未分级', '将雪橇机调整至舒适的重量。仰卧在雪橇机上，双脚放在踏板上。双脚分开与肩同宽，并稍微向外倾斜。握住雪橇机的手柄以保持稳定。调动你的臀肌和核心肌肉。脚后跟用力，双腿伸直，抬起雪橇。弯曲膝盖和臀部，将雪橇放回原位。重复所需的重复次数。', 'exercise-dataset', '0744', 'sled lying squat', 'upper legs', '大腿', '40', 'sled machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the sled machine to a comfortable weight. Lie on your back on the sled machine with your feet on the footplate. Position your feet shoulder-width apart and slightly angled outwards. Grip the handles of the sled machine for stability. Engage your glutes and core muscles. Push through your heels and extend your legs to lift the sled. Lower the sled back down by bending your knees and hips. Repeat for the desired number of repetitions.', '/static/exercises/images/0744-9n2149Z.jpg', '/static/exercises/gifs/0744-9n2149Z.gif', '© Gym visual — https://gymvisual.com/', '2073'),
('101392', '雪橇机单腿小腿推举腿举', '腘绳肌', '雪橇机', '未分级', '调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。坐在机器上，背部靠在靠背上，双脚放在雪橇上，与肩同宽。将脚趾和脚掌放在雪橇上，保持脚跟离开。伸展脚踝，保持膝盖稍微弯曲，将雪橇向前推。在顶部停顿片刻，然后通过弯曲脚踝慢慢将雪橇放回原处。重复所需的重复次数。', 'exercise-dataset', '1392', 'sled one leg calf press on leg press', 'lower legs', '小腿', '70', 'sled machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled. Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart. Place your toes and the balls of your feet on the sled, keeping your heels off. Push the sled forward by extending your ankles, keeping your knees slightly bent. Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles. Repeat for the desired number of repetitions.', '/static/exercises/images/1392-u0pLNgz.jpg', '/static/exercises/gifs/1392-u0pLNgz.gif', '© Gym visual — https://gymvisual.com/', '902084'),
('101496', '大锤锤式', '前臂', '锤铃', '未分级', '双脚分开与肩同宽站立，双手握住大锤。启动你的核心并保持背部挺直。使用核心和上半身的力量，将大锤向下挥向地面。当你向下挥杆时，转动臀部并将力量传递到锤子上。重复所需的重复次数。', 'exercise-dataset', '1496', 'sledge hammer', 'waist', '腰腹', '60', 'hammer', 'forearms', 'abs', '腹肌', '["前臂","肩部"]', 'Stand with your feet shoulder-width apart and hold the sledge hammer with both hands. Engage your core and keep your back straight. Swing the sledge hammer down towards the ground, using your core and upper body strength. As you swing down, pivot your hips and transfer the force to the hammer. Repeat for the desired number of repetitions.', '/static/exercises/images/1496-REXmfVC.jpg', '/static/exercises/gifs/1496-REXmfVC.gif', '© Gym visual — https://gymvisual.com/', '902073'),
('100746', '史密斯机后侧耸肩', '肩部', '史密斯机', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住杠铃，双手间距略宽于肩宽。保持手臂伸直，让杠铃挂在大腿前面。将肩膀向耳朵方向伸直，挤压斜方肌顶部。保持一会儿，然后将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0746', 'smith back shrug', 'back', '背部', '20', 'smith machine', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your arms straight and allow the barbell to hang in front of your thighs. Lift your shoulders straight up towards your ears, squeezing your traps at the top. Hold for a moment, then lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0746-MzNnwx9.jpg', '/static/exercises/gifs/0746-MzNnwx9.gif', '© Gym visual — https://gymvisual.com/', '561676'),
('100747', '史密斯机颈后颈部推举', '肱三头肌', '史密斯机', '未分级', '调整史密斯机的座椅高度，使杠铃与肩部齐平。双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上抬起并向后退一步，保持稳定的姿势。将杠铃降低到颈后，保持肘部向前。将杠铃向上推过头顶，直到双臂完全伸展。在顶部暂停片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0747', 'smith behind neck press', 'shoulders', '肩部', '30', 'smith machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the seat height of the smith machine so that the bar is at shoulder level. Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and step back, maintaining a stable stance. Lower the bar down to the back of your neck, keeping your elbows pointing forward. Press the bar up overhead until your arms are fully extended. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0747-Gpn4ADc.jpg', '/static/exercises/gifs/0747-Gpn4ADc.gif', '© Gym visual — https://gymvisual.com/', '901679'),
('100748', '史密斯机卧推', '肱三头肌', '史密斯机', '未分级', '将史密斯机杆的高度调整至胸部水平。平躺在长凳上，双脚牢牢踩在地上。正手握住杠铃，握距略宽于肩宽。松开杠铃并将其向胸部降低，保持肘部内收。当杠铃接触到你的胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0748', 'smith bench press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the height of the smith machine bar to chest level. Lie flat on the bench with your feet firmly planted on the ground. Grip the bar with an overhand grip slightly wider than shoulder-width apart. Unrack the bar and lower it towards your chest, keeping your elbows tucked in. Pause for a moment when the bar touches your chest. Push the bar back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0748-trqKQv2.jpg', '/static/exercises/gifs/0748-trqKQv2.gif', '© Gym visual — https://gymvisual.com/', '1678'),
('100749', '史密斯机屈曲膝早安式', '腘绳肌', '史密斯机', '未分级', '首先站立，双脚分开与肩同宽，脚趾指向前方。将杠铃放在上背部，放在斜方肌上。稍微弯曲膝盖，髋部向前转动，保持背部挺直。降低躯干直到与地面平行，感觉腿筋被拉伸。启动臀肌和腿筋，将躯干抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0749', 'smith bent knee good morning', 'upper legs', '大腿', '40', 'smith machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","下背部"]', 'Start by standing with your feet shoulder-width apart, toes pointing forward. Place the barbell across your upper back, resting it on your traps. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Engage your glutes and hamstrings to raise your torso back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0749-1bQkKZK.jpg', '/static/exercises/gifs/0749-1bQkKZK.gif', '© Gym visual — https://gymvisual.com/', '901683'),
('101359', '史密斯机俯身划船', '肱二头肌', '史密斯机', '未分级', '将史密斯机设置为与臀部高度相同的杠铃。面向杠铃站立，双脚分开与肩同宽。稍微弯曲膝盖，髋部向前转动，保持背部挺直。正手握住杠铃，双手距离略宽于肩宽。将杠铃拉向下胸部，将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1359', 'smith bent over row', 'back', '背部', '20', 'smith machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up the smith machine with the bar at hip height. Stand facing the bar with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Pull the bar towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1359-ZX9UZmj.jpg', '/static/exercises/gifs/1359-ZX9UZmj.gif', '© Gym visual — https://gymvisual.com/', '161682'),
('100750', '史密斯机椅上深蹲', '臀肌', '史密斯机', '未分级', '将史密斯机杆的高度调整到舒适的位置。站立，双脚分开与肩同宽，脚趾稍微向外。将杠铃放在上背部，放在斜方肌上。通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。继续降低，直到大腿与地面平行，或者尽可能低。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0750', 'smith chair squat', 'upper legs', '大腿', '40', 'smith machine', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Adjust the height of the smith machine bar to a comfortable position. Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0750-Gu2rNJd.jpg', '/static/exercises/gifs/0750-Gu2rNJd.gif', '© Gym visual — https://gymvisual.com/', '1681'),
('100751', '史密斯机窄握卧推', '胸肌', '史密斯机', '未分级', '调整座椅高度，将自己放在长凳上，双脚平放在地面上。紧紧握住杠铃，握距略窄于肩宽。将杠铃向胸部降低，保持肘部靠近身体。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0751', 'smith close-grip bench press', 'upper arms', '上臂', '50', 'smith machine', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Adjust the seat height and position yourself on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0751-WcHl7ru.jpg', '/static/exercises/gifs/0751-WcHl7ru.gif', '© Gym visual — https://gymvisual.com/', '901684'),
('100752', '史密斯机硬拉', '腘绳肌', '史密斯机', '未分级', '将史密斯机设置为与臀部高度相同的杠铃。双脚分开与肩同宽站立，脚趾稍微向外。弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。站直，充分伸展臀部和膝盖。通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。重复所需的重复次数。', 'exercise-dataset', '0752', 'smith deadlift', 'upper legs', '大腿', '40', 'smith machine', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","下背部"]', 'Set up the smith machine with the bar at hip height. Stand with your feet shoulder-width apart, toes pointing slightly outward. Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart. Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body. Stand up straight, fully extending your hips and knees. Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight. Repeat for the desired number of repetitions.', '/static/exercises/images/0752-UfePqpx.jpg', '/static/exercises/gifs/0752-UfePqpx.gif', '© Gym visual — https://gymvisual.com/', '81681'),
('100753', '史密斯机下斜卧推', '肱三头肌', '史密斯机', '未分级', '将下斜凳调整至所需角度。躺在长凳上，双脚固定在脚垫下。正手握住杠铃，握距略宽于肩宽。松开杠铃，慢慢将其降低到胸部，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0753', 'smith decline bench press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the decline bench to the desired angle. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0753-ETZfAbZ.jpg', '/static/exercises/gifs/0753-ETZfAbZ.gif', '© Gym visual — https://gymvisual.com/', '1686'),
('100754', '史密斯机下斜反向握推举', '肱三头肌', '史密斯机', '未分级', '将史密斯机调整至下降位置。躺在长凳上，双脚固定在脚垫下。反握抓住杠铃，双手分开略宽于肩宽。松开杠铃并将其向胸部降低，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0754', 'smith decline reverse-grip press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the smith machine to a decline position. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0754-MY9P1WA.jpg', '/static/exercises/gifs/0754-MY9P1WA.gif', '© Gym visual — https://gymvisual.com/', '901687'),
('101433', '史密斯机前蹲翻举握', '股四头肌', '史密斯机', '未分级', '将杠铃置于肩高的史密斯机上。面向杠铃站立，双脚与肩同宽。正手握住杠铃，握距略宽于肩宽。后退一步，将杠铃放在前肩上，放在锁骨和三角肌上。保持挺胸、背部挺直、核心收紧。弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。继续降低，直到大腿与地面平行或略低于地面。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1433', 'smith front squat (clean grip)', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群","核心肌群"]', 'Set up the smith machine with the barbell at shoulder height. Stand facing the barbell with your feet shoulder-width apart. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids. Keep your chest up, back straight, and core engaged. Lower your body by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1433-lFhb2Rw.jpg', '/static/exercises/gifs/1433-lFhb2Rw.gif', '© Gym visual — https://gymvisual.com/', '1690'),
('103281', '史密斯机全程深蹲', '股四头肌', '史密斯机', '未分级', '将杠铃置于肩高的史密斯机上。站立，双脚分开与肩同宽，脚趾稍微向外。走到杠铃下方，将其放在上背部上方，放在斜方肌上。双手握住杠铃，距离略大于肩宽。松开杠铃并后退一步，保持稳定的姿势。保持胸部挺直，核心参与，通过将臀部向后推并弯曲膝盖来开始深蹲。降低你的身体，直到你的大腿与地面平行，或者在你的灵活性允许的范围内尽可能低。在底部停顿片刻，然后用脚后跟恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '3281', 'smith full squat', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Set up the smith machine with the barbell at shoulder height. Stand with your feet shoulder-width apart, toes slightly turned out. Step under the bar and position it across your upper back, resting on your traps. Grip the bar with your hands slightly wider than shoulder-width apart. Unrack the bar and take a step back, maintaining a stable stance. Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees. Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows. Pause for a moment at the bottom, then drive through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3281-NNoHCEA.jpg', '/static/exercises/gifs/3281-NNoHCEA.gif', '© Gym visual — https://gymvisual.com/', '1687'),
('100755', '史密斯机哈克深蹲', '股四头肌', '史密斯机', '未分级', '将史密斯机上的杠铃调整到适合您身体的高度。双脚分开与肩同宽站立，脚趾稍微向外。将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。正手握住杠铃，握距略宽于肩宽。当你打开杠铃时，启动你的核心并保持挺胸。后退一步，双脚分开的距离略大于肩宽。弯曲膝盖，降低身体，保持挺胸、背部挺直。继续下降，直到大腿与地面平行或略低于地面。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0755', 'smith hack squat', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the barbell on the smith machine to an appropriate height for your body. Stand with your feet shoulder-width apart, toes slightly pointed outwards. Position yourself under the barbell, resting it on your upper traps and shoulders. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Engage your core and keep your chest up as you unrack the barbell. Take a step back and position your feet slightly wider than shoulder-width apart. Bend your knees and lower your body down, keeping your chest up and back straight. Continue descending until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0755-ZuPXtCK.jpg', '/static/exercises/gifs/0755-ZuPXtCK.gif', '© Gym visual — https://gymvisual.com/', '1688'),
('100756', '史密斯机髋部上举', '臀肌', '史密斯机', '未分级', '将自己放在史密斯机上，背部靠在垫子上，双脚分开与肩同宽。将双手放在杠铃上，距离略宽于肩宽。启动你的核心肌群和臀大肌，然后通过脚后跟将臀部抬离地面。继续提升，直到身体从膝盖到肩膀形成一条直线。在顶部保持片刻，然后慢慢将臀部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0756', 'smith hip raise', 'waist', '腰腹', '60', 'smith machine', 'glutes', 'abs', '腹肌', '["臀肌","腘绳肌"]', 'Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart. Place your hands on the barbell, slightly wider than shoulder-width apart. Engage your core and glutes, then push through your heels to raise your hips off the ground. Continue lifting until your body forms a straight line from your knees to your shoulders. Hold for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0756-CqhoytW.jpg', '/static/exercises/gifs/0756-CqhoytW.gif', '© Gym visual — https://gymvisual.com/', '901689'),
('100757', '史密斯机上斜卧推', '肩部', '史密斯机', '未分级', '将长凳调整至 30-45 度倾斜。坐在长凳上，背部平放在垫子上，双脚牢牢踩在地上。正手握住杠铃，握距略宽于肩宽。松开杠铃，慢慢地将其降低到上胸部，保持肘部稍微内收。在底部停顿片刻，然后将杠铃推回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0757', 'smith incline bench press', 'chest', '胸部', '10', 'smith machine', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Adjust the bench to a 30-45 degree incline. Sit on the bench with your back flat against the pad and feet firmly on the ground. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0757-5v7KYld.jpg', '/static/exercises/gifs/0757-5v7KYld.gif', '© Gym visual — https://gymvisual.com/', '1692'),
('100758', '史密斯机上斜反向握推举', '肱三头肌', '史密斯机', '未分级', '将史密斯机的座椅调整到舒适的倾斜角度。坐在机器上，背部靠在垫子上，双脚平放在地面上。正手握住杠铃，握距略宽于肩宽。松开杠铃并将其缓慢降低至胸部，同时保持肘部内收。当杠铃位于胸部正上方时，暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '0758', 'smith incline reverse-grip press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the seat of the smith machine to a comfortable incline angle. Sit on the machine with your back against the pad and your feet flat on the ground. Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart. Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the bar is just above your chest. Push the bar back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0758-78VqWQK.jpg', '/static/exercises/gifs/0758-78VqWQK.gif', '© Gym visual — https://gymvisual.com/', '901693'),
('100759', '史密斯机上斜肩部上举', '三角肌', '史密斯机', '未分级', '将史密斯机调整至倾斜位置。面向机器站立，双脚分开与肩同宽。正手握住杠铃，握距略宽于肩宽。保持背部挺直，核心参与。将杠铃举向天花板，用肘部引导。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0759', 'smith incline shoulder raises', 'chest', '胸部', '10', 'smith machine', 'deltoids', 'serratus anterior', '前锯肌', '["三角肌","斜方肌"]', 'Adjust the smith machine to an incline position. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and core engaged. Raise the barbell up towards the ceiling, leading with your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0759-ayAHcEm.jpg', '/static/exercises/gifs/0759-ayAHcEm.gif', '© Gym visual — https://gymvisual.com/', '901694'),
('100760', '史密斯机腿举', '股四头肌', '史密斯机', '未分级', '将史密斯机的座椅和脚踏板调整到舒适的位置。坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。抓住机器的手柄或侧面以保持稳定性。伸展双腿，使背部紧靠靠背，将脚踏板推离您。在完全伸展的位置暂停片刻。慢慢弯曲膝盖，将脚踏板向您的方向放低，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0760', 'smith leg press', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat and footplate of the smith machine to a comfortable position. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grasp the handles or sides of the machine for stability. Push the footplate away from you by extending your legs, keeping your back against the backrest. Pause for a moment at the fully extended position. Slowly bend your knees and lower the footplate back towards you, returning to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0760-7zdxRTl.jpg', '/static/exercises/gifs/0760-7zdxRTl.gif', '© Gym visual — https://gymvisual.com/', '241693'),
('101434', '史密斯机低位杆深蹲', '股四头肌', '史密斯机', '未分级', '将史密斯机与杠铃设置在一个高度，以便您可以将其舒适地放在上背部。站立，双脚分开与肩同宽，脚趾稍微向外转动。走到杠铃下方，将其放在上背部上方，将其放在斜方肌上。双手握住杠铃，距离略大于肩宽。伸直双腿并从架子上退后，将杠铃松开。深呼吸并支撑你的核心。通过向后推臀部并弯曲膝盖来开始深蹲。降低身体，直到大腿与地面平行或稍低于地面。在整个动作过程中保持挺胸、背部挺直。通过脚后跟站起来，伸展臀部和膝盖。重复所需的重复次数。', 'exercise-dataset', '1434', 'smith low bar squat', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back. Stand with your feet shoulder-width apart, toes slightly turned outwards. Step under the bar and position it across your upper back, resting it on your traps. Grip the bar with your hands slightly wider than shoulder-width apart. Unrack the bar by straightening your legs and stepping back from the rack. Take a deep breath and brace your core. Initiate the squat by pushing your hips back and bending your knees. Lower your body until your thighs are parallel to the ground or slightly below. Keep your chest up and your back straight throughout the movement. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', '/static/exercises/images/1434-RGLscZM.jpg', '/static/exercises/gifs/1434-RGLscZM.gif', '© Gym visual — https://gymvisual.com/', '1696'),
('101683', '史密斯机器械肱二头肌弯举', '前臂', '史密斯机', '未分级', '将史密斯机杆的高度调整到腰部水平。面对史密斯机站立，双脚与肩同宽。反手握住杠铃，双手间距略大于肩宽。保持肘部靠近身体两侧，上臂保持静止。呼气并将杠铃向上卷向肩膀，收缩二头肌。在动作的最高点暂停片刻，挤压你的二头肌。吸气并慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1683', 'smith machine bicep curl', 'upper arms', '上臂', '50', 'smith machine', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Adjust the height of the smith machine bar to be at waist level. Stand facing the smith machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1683-zILLZ98.jpg', '/static/exercises/gifs/1683-zILLZ98.gif', '© Gym visual — https://gymvisual.com/', '81697'),
('101625', '史密斯机器械下斜窄握卧推', '胸肌', '史密斯机', '未分级', '将史密斯机上的长凳调整至下降位置。躺在长凳上，双脚牢牢踩在地上。紧紧握住杠铃，握距略窄于肩宽。松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。当杠铃位于胸部正上方时，暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1625', 'smith machine decline close grip bench press', 'upper arms', '上臂', '50', 'smith machine', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Adjust the bench on the smith machine to a decline position. Lie down on the bench with your feet firmly planted on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell is just above your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1625-yB9SvIF.jpg', '/static/exercises/gifs/1625-yB9SvIF.gif', '© Gym visual — https://gymvisual.com/', '901704'),
('101752', '史密斯机器械上斜肱三头肌伸展', '肩部', '史密斯机', '未分级', '调整史密斯机的座椅，使杠铃处于肩部高度。坐在长凳上，背部靠在垫子上，双脚平放在地上。正手握住杠铃，握距略宽于肩宽。充分伸展双臂，将杠铃从架子上提起，并将其保持在胸部正上方。慢慢地将杠铃降低到前额，保持肘部靠近头部。在底部暂停片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1752', 'smith machine incline tricep extension', 'upper arms', '上臂', '50', 'smith machine', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Adjust the seat of the smith machine so that the bar is at shoulder height. Sit on the bench with your back against the pad and your feet flat on the ground. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Extend your arms fully, lifting the bar off the rack and holding it directly above your chest. Lower the bar slowly towards your forehead, keeping your elbows close to your head. Pause for a moment at the bottom, then push the bar back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1752-o8aOcrz.jpg', '/static/exercises/gifs/1752-o8aOcrz.gif', '© Gym visual — https://gymvisual.com/', '901701'),
('101626', '史密斯机器械反向下斜窄握卧推', '肱三头肌', '史密斯机', '未分级', '将史密斯机调整至下降位置。躺在长凳上，双脚固定在脚垫下。紧紧握住杠铃，握距略窄于肩宽。松开杠铃，慢慢将其降低到胸部，保持肘部内收。在底部停顿片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1626', 'smith machine reverse decline close grip bench press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the smith machine to a decline position. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1626-QyO6Uma.jpg', '/static/exercises/gifs/1626-QyO6Uma.gif', '© Gym visual — https://gymvisual.com/', '1708'),
('100761', '史密斯机窄距划船', '肱二头肌', '史密斯机', '未分级', '调整座椅高度并将自己放在机器上，双脚平放在地板上。正手握住手柄，握距略窄于肩宽。当您将手柄拉向身体时，保持背部挺直，挺胸，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0761', 'smith narrow row', 'back', '背部', '20', 'smith machine', 'biceps', 'upper back', '上背部', '["肱二头肌","后侧DELTOIDS"]', 'Adjust the seat height and position yourself on the machine with your feet flat on the floor. Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart. Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0761-JGKowMS.jpg', '/static/exercises/gifs/0761-JGKowMS.gif', '© Gym visual — https://gymvisual.com/', '901699'),
('101360', '史密斯机单臂划船', '肱二头肌', '史密斯机', '未分级', '将史密斯机杆的高度调整至腰部水平。面对史密斯机站立，双脚与肩同宽。稍微弯曲膝盖，髋部向前转动，保持背部挺直。用一只手正手握住杠铃，手掌朝下。保持肘部靠近身体，将杠铃拉向腰部，将肩胛骨挤压在一起。在动作的最高点暂停片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数，然后换到另一只手臂。', 'exercise-dataset', '1360', 'smith one arm row', 'back', '背部', '20', 'smith machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Adjust the height of the smith machine bar to waist level. Stand facing the smith machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with one hand using an overhand grip, with your palm facing down. Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', '/static/exercises/images/1360-Q4DSJPC.jpg', '/static/exercises/gifs/1360-Q4DSJPC.gif', '© Gym visual — https://gymvisual.com/', '401702'),
('101393', '史密斯机单腿地板提踵', '腘绳肌', '史密斯机', '未分级', '将自己放在史密斯机杆下方的地板上，背对机器。将脚掌放在凸起的表面上，例如举重板或杠铃块。将史密斯机杆放在小腿上，就在脚踝上方。用手握住横杆以保持稳定。伸展脚踝，将脚后跟抬离地面，抬起身体。在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1393', 'smith one leg floor calf raise', 'lower legs', '小腿', '70', 'smith machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Position yourself on the floor under the smith machine bar, facing away from the machine. Place the balls of your feet on a raised surface, such as a weight plate or block. Position the smith machine bar across your lower legs, just above your ankles. Hold onto the bar with your hands for stability. Raise your heels off the ground by extending your ankles, lifting your body up. Pause at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1393-9GXrTE6.jpg', '/static/exercises/gifs/1393-9GXrTE6.gif', '© Gym visual — https://gymvisual.com/', '1707'),
('100762', '史密斯机三角肌后束划船', '斜方肌', '史密斯机', '未分级', '调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地面上。正手握住手柄，握距略宽于肩宽。将手柄拉向胸部，将肩胛骨挤压在一起，保持背部挺直，核心肌群参与。在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0762', 'smith rear delt row', 'shoulders', '肩部', '30', 'smith machine', 'trapezius', 'delts', '三角肌', '["斜方肌","菱形肌","肱二头肌"]', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0762-nFUwqG6.jpg', '/static/exercises/gifs/0762-nFUwqG6.gif', '© Gym visual — https://gymvisual.com/', '401704'),
('100763', '史密斯机反向小腿上举', '腘绳肌', '史密斯机', '未分级', '将史密斯机杆调整到略低于肩膀的高度。面向杠铃站立，双脚分开与臀部同宽，脚趾向前。将脚掌放在台阶或平台的边缘，脚后跟悬空。握住杠铃以提供支撑，保持背部挺直，核心肌群参与。尽可能高地抬高脚后跟，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0763', 'smith reverse calf raises', 'lower legs', '小腿', '70', 'smith machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Adjust the smith machine bar to a height just below your shoulders. Stand facing the bar with your feet hip-width apart and toes pointing forward. Place the balls of your feet on the edge of a step or platform, with your heels hanging off. Hold onto the bar for support, keeping your back straight and core engaged. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0763-ywaNfuh.jpg', '/static/exercises/gifs/0763-ywaNfuh.gif', '© Gym visual — https://gymvisual.com/', '1705'),
('101394', '史密斯机反向小腿上举', '腘绳肌', '史密斯机', '未分级', '将史密斯机杆调整到略低于肩膀的高度。面向杠铃站立，双脚分开与臀部同宽，脚趾向前。将脚掌放在台阶或平台的边缘，脚后跟悬空。抓住横杆以获得支撑。尽可能高地抬高脚跟，将身体抬起到脚趾上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1394', 'smith reverse calf raises', 'lower legs', '小腿', '70', 'smith machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Adjust the smith machine bar to a height just below your shoulders. Stand facing the bar with your feet hip-width apart and toes pointing forward. Place the balls of your feet on the edge of a step or platform, with your heels hanging off. Hold onto the bar for support. Raise your heels as high as possible, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1394-Lsqrgh4.jpg', '/static/exercises/gifs/1394-Lsqrgh4.gif', '© Gym visual — https://gymvisual.com/', '1706'),
('101361', '史密斯机反向握俯身划船', '肱二头肌', '史密斯机', '未分级', '将史密斯机设置为与臀部高度相同的杠铃。面向杠铃站立，双脚分开与肩同宽。稍微弯曲膝盖，髋部向前转动，保持背部挺直。反手握住杠铃，双手与肩同宽。将杠铃拉向下胸部，将肩胛骨挤压在一起。在顶部暂停片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1361', 'smith reverse grip bent over row', 'back', '背部', '20', 'smith machine', 'biceps', 'upper back', '上背部', '["肱二头肌","前臂"]', 'Set up the smith machine with the bar at hip height. Stand facing the bar with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with an underhand grip, hands shoulder-width apart. Pull the bar towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1361-aaxA3cm.jpg', '/static/exercises/gifs/1361-aaxA3cm.gif', '© Gym visual — https://gymvisual.com/', '161711'),
('100764', '史密斯机反向握推举', '肱三头肌', '史密斯机', '未分级', '将史密斯机杆的高度调整至胸部水平。面向杠铃站立，双脚分开与肩同宽。正手握住杠铃，双手距离略宽于肩宽。退后一步，膝盖稍微弯曲。在整个练习过程中保持挺胸并保持核心参与。将杠铃向胸部方向降低，保持肘部内收。在底部暂停片刻，然后将杠铃推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0764', 'smith reverse-grip press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the height of the smith machine bar to chest level. Stand facing the bar with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Step back and position yourself with a slight bend in your knees. Keep your chest up and core engaged throughout the exercise. Lower the bar towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the bar back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0764-zK8Fu1W.jpg', '/static/exercises/gifs/0764-zK8Fu1W.gif', '© Gym visual — https://gymvisual.com/', '901706'),
('101395', '史密斯机坐姿单腿提踵', '腘绳肌', '史密斯机', '未分级', '坐在机器上，背部靠在垫子上，双脚放在脚踏板上。将一条腿放在脚踏板上，另一条腿离开脚踏板。使用小腿肌肉，尽可能高地抬高脚跟。在顶部暂停片刻，然后慢慢将脚跟放回起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '1395', 'smith seated one leg calf raise', 'lower legs', '小腿', '70', 'smith machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌"]', 'Sit on the machine with your back against the pad and your feet on the footrest. Place one leg on the footrest and keep the other leg off the footrest. Using your calf muscles, raise your heel as high as possible. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/1395-0S75mYG.jpg', '/static/exercises/gifs/1395-0S75mYG.gif', '© Gym visual — https://gymvisual.com/', '1713'),
('100765', '史密斯机坐姿肩上推举', '肱三头肌', '史密斯机', '未分级', '调整座椅高度，使手柄与肩部齐平。坐在机器上，背部靠在垫子上，双脚平放在地板上。正手握住手柄，将其提离支撑物，充分伸展双臂。将手柄降低至肩部水平，保持肘部稍微弯曲。将手柄向上推过头顶，直到手臂完全伸展。在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。重复所需的重复次数。', 'exercise-dataset', '0765', 'smith seated shoulder press', 'shoulders', '肩部', '30', 'smith machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the seat height so that the handles are at shoulder level. Sit on the machine with your back against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully. Lower the handles down to shoulder level, keeping your elbows slightly bent. Press the handles up overhead until your arms are fully extended. Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0765-xUwnBMT.jpg', '/static/exercises/gifs/0765-xUwnBMT.gif', '© Gym visual — https://gymvisual.com/', '1710'),
('101426', '史密斯机坐姿腕弯举', '肱二头肌', '史密斯机', '未分级', '坐在史密斯机前的长凳上，双脚平放在地面上。反握抓住杠铃，双手与肩同宽。将前臂放在大腿上，让手腕悬垂。慢慢向上弯曲手腕，将杠铃拉向前臂。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1426', 'smith seated wrist curl', 'lower arms', '前臂', '80', 'smith machine', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","BRACHIALIS"]', 'Sit on a bench in front of a Smith machine with your feet flat on the ground. Grasp the barbell with an underhand grip, hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off. Slowly curl your wrists upward, bringing the barbell towards your forearms. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1426-B6dAO1t.jpg', '/static/exercises/gifs/1426-B6dAO1t.gif', '© Gym visual — https://gymvisual.com/', '1711'),
('100766', '史密斯机肩上推举', '肱三头肌', '史密斯机', '未分级', '调整座椅高度，将自己放在史密斯机上，双脚分开与肩同宽。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。向上推杠铃，直到手臂完全伸过头顶。在顶部暂停片刻，然后慢慢将杠铃放回至肩部水平。重复所需的重复次数。', 'exercise-dataset', '0766', 'smith shoulder press', 'shoulders', '肩部', '30', 'smith machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward. Press the bar upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the bar back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0766-903mzG8.jpg', '/static/exercises/gifs/0766-903mzG8.gif', '© Gym visual — https://gymvisual.com/', '1710'),
('100767', '史密斯机耸肩', '肩部', '史密斯机', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住杠铃，双手间距略宽于肩宽。保持双臂伸直，肩膀放松。将肩膀向耳朵方向抬起，在顶部挤压斜方肌。保持一会儿，然后慢慢将肩膀放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0767', 'smith shrug', 'back', '背部', '20', 'smith machine', 'shoulders', 'traps', '斜方肌', '["肩部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your arms straight and your shoulders relaxed. Lift your shoulders up towards your ears, squeezing your traps at the top. Hold for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0767-OUQ0ZyW.jpg', '/static/exercises/gifs/0767-OUQ0ZyW.gif', '© Gym visual — https://gymvisual.com/', '561709'),
('100768', '史密斯机单侧腿分腿蹲', '臀肌', '史密斯机', '未分级', '站在史密斯机前，双脚分开与肩同宽。将一只脚放在身后的长凳或台阶上，脚趾向前。握住史密斯机杆以保持稳定性。弯曲前膝盖，将身体降低到弓步位置，保持背部挺直。在底部停顿片刻，然后推动前脚跟回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0768', 'smith single leg split squat', 'upper legs', '大腿', '40', 'smith machine', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌"]', 'Stand in front of the smith machine with your feet shoulder-width apart. Place one foot behind you on a bench or step, with your toes pointing forward. Hold onto the smith machine bar for stability. Bend your front knee and lower your body down into a lunge position, keeping your back straight. Pause for a moment at the bottom, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0768-wWFspEi.jpg', '/static/exercises/gifs/0768-wWFspEi.gif', '© Gym visual — https://gymvisual.com/', '1716'),
('100769', '史密斯机冲刺跑弓步', '股四头肌', '史密斯机', '未分级', '将杠铃置于臀部高度的史密斯机上。背对机器站立，双脚与肩同宽。右脚向后退一步，将其放在杠铃上，将脚尖放在杠上。弯曲左膝，将身体降低到弓步位置，保持背部挺直。推动左脚跟返回到起始位置。在另一侧重复，左脚向后退一步。继续交替进行所需的重复次数。', 'exercise-dataset', '0769', 'smith sprint lunge', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Set up the smith machine with the barbell at hip height. Stand facing away from the machine with your feet shoulder-width apart. Step back with your right foot and place it on the barbell, resting the top of your foot on the bar. Bend your left knee and lower your body into a lunge position, keeping your back straight. Push through your left heel to return to the starting position. Repeat on the other side, stepping back with your left foot. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0769-HsjbB1z.jpg', '/static/exercises/gifs/0769-HsjbB1z.gif', '© Gym visual — https://gymvisual.com/', '321713'),
('100770', '史密斯机深蹲', '股四头肌', '史密斯机', '未分级', '将史密斯机和杠铃设置在适合深蹲的高度。站立，双脚分开与肩同宽，脚趾稍微向外。将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。宽握距握住杠铃，握距略宽于肩宽。启动你的核心并打开杠铃，后退以清理架子。保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。降低身体，直到大腿与地面平行或稍低于地面。在底部停顿片刻，然后用脚后跟恢复到起始位置。重复所需的重复次数。', 'exercise-dataset', '0770', 'smith squat', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Set up the smith machine with the barbell at an appropriate height for your squat. Stand with your feet shoulder-width apart, toes slightly turned out. Position yourself under the barbell, resting it on your upper traps and shoulders. Grip the barbell with a wide grip, slightly wider than shoulder-width apart. Engage your core and unrack the barbell, stepping back to clear the rack. Keeping your chest up and back straight, initiate the squat by bending at the hips and knees. Lower your body until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then drive through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0770-jFtipLl.jpg', '/static/exercises/gifs/0770-jFtipLl.gif', '© Gym visual — https://gymvisual.com/', '1712'),
('100771', '史密斯机站姿后侧腕弯举', '肱二头肌', '史密斯机', '未分级', '面对史密斯机站立，双脚与肩同宽。正手握住杠铃，双手与肩同宽。保持背部挺直，肘部靠近身体。慢慢向上弯曲手腕，将杠铃拉向身体。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0771', 'smith standing back wrist curl', 'lower arms', '前臂', '80', 'smith machine', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Stand facing the smith machine with your feet shoulder-width apart. Grasp the barbell with an overhand grip, hands shoulder-width apart. Keep your back straight and your elbows close to your body. Slowly curl your wrists upwards, bringing the barbell towards your body. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0771-hfmQ0Tz.jpg', '/static/exercises/gifs/0771-hfmQ0Tz.gif', '© Gym visual — https://gymvisual.com/', '1719'),
('100772', '史密斯机站姿颈后头后军事推举', '肱三头肌', '史密斯机', '未分级', '调整史密斯机的座椅高度，使杠铃与肩部齐平。双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上抬起并向后退一步，保持稳定的姿势。将杠铃放在脑后，放在斜方肌上部。在整个练习过程中保持核心收紧并抬起胸部。伸展双臂，完全伸直，将杠铃推过头顶。在动作的最高点稍作停顿，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0772', 'smith standing behind head military press', 'shoulders', '肩部', '30', 'smith machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Adjust the seat height of the smith machine so that the bar is at shoulder level. Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and step back, maintaining a stable stance. Position the bar behind your head, resting on your upper traps. Keep your core engaged and your chest lifted throughout the exercise. Press the bar overhead by extending your arms, fully straightening them. Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0772-ht8xDrP.jpg', '/static/exercises/gifs/0772-ht8xDrP.gif', '© Gym visual — https://gymvisual.com/', '901722'),
('100773', '史密斯机站姿腿提踵', '腘绳肌', '史密斯机', '未分级', '将史密斯机杆调整到一个高度，使您能够双脚平放在地面上且肩膀位于杆下方。将自己置于杠铃下方，双脚分开与肩同宽，脚趾向前。将双手放在横杆上以保持稳定。收紧小腿，慢慢将脚跟抬离地面，将身体抬起到脚趾上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0773', 'smith standing leg calf raise', 'lower legs', '小腿', '70', 'smith machine', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar. Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward. Place your hands on the bar for stability. Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0773-6MaEjVA.jpg', '/static/exercises/gifs/0773-6MaEjVA.gif', '© Gym visual — https://gymvisual.com/', '1721'),
('100774', '史密斯机站姿军事推举', '肱三头肌', '史密斯机', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。正手握住杠铃，握距略宽于肩宽。将杠铃从架子上提起，并将其降至与肩同高，手掌朝前。向上推杠铃，直到手臂完全伸过头顶。在顶部停顿片刻，然后慢慢将杠铃放回至肩部水平。重复所需的重复次数。', 'exercise-dataset', '0774', 'smith standing military press', 'shoulders', '肩部', '30', 'smith machine', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward. Press the barbell upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the barbell back down to shoulder level. Repeat for the desired number of repetitions.', '/static/exercises/images/0774-jjUPrze.jpg', '/static/exercises/gifs/0774-jjUPrze.gif', '© Gym visual — https://gymvisual.com/', '901720'),
('103142', '史密斯机相扑式深蹲', '股四头肌', '史密斯机', '未分级', '将杠铃置于臀部高度的史密斯机上。站立，双脚分开比肩宽，脚趾朝外。将自己置于杠铃下方，将其放在上背部和肩膀上。当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3142', 'smith sumo squat', 'upper legs', '大腿', '40', 'smith machine', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Set up the smith machine with the barbell at hip height. Stand with your feet wider than shoulder-width apart, toes pointing outwards. Position yourself under the barbell, resting it on your upper back and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3142-dzz6BiV.jpg', '/static/exercises/gifs/3142-dzz6BiV.gif', '© Gym visual — https://gymvisual.com/', '1719'),
('101396', '史密斯机脚尖上举', '踝部肌群', '史密斯机', '未分级', '将史密斯机杆调整到一个高度，让您可以舒适地站立，双脚平放在地面上。将自己置于杠铃下方，肩膀位于杠铃正下方，双脚分开与肩同宽。将脚掌放在升高的平台或重量板上，脚后跟悬在边缘。正手握住杠铃，握距略宽于肩宽。在整个练习过程中启动你的核心并保持背部挺直。慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1396', 'smith toe raise', 'lower legs', '小腿', '70', 'smith machine', 'ankles', 'calves', '小腿肌群', '["踝部肌群","SHINS"]', 'Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground. Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart. Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and keep your back straight throughout the exercise. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1396-Y4QlY8z.jpg', '/static/exercises/gifs/1396-Y4QlY8z.gif', '© Gym visual — https://gymvisual.com/', '901720'),
('100775', '史密斯机直立划船', '斜方肌', '史密斯机', '未分级', '双脚分开与肩同宽站立，面向史密斯机。正手握住杠铃，双手间距略宽于肩宽。保持背部挺直，核心肌群参与。将杠铃拉向下巴，用肘部引导。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0775', 'smith upright row', 'shoulders', '肩部', '30', 'smith machine', 'traps', 'delts', '三角肌', '["斜方肌","肱二头肌"]', 'Stand with your feet shoulder-width apart, facing the smith machine. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the barbell up towards your chin, leading with your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0775-1DN3iz4.jpg', '/static/exercises/gifs/0775-1DN3iz4.gif', '© Gym visual — https://gymvisual.com/', '481721'),
('101308', '史密斯机宽握卧推', '肱三头肌', '史密斯机', '未分级', '将史密斯机上的长凳调整到舒适的位置。躺在长凳上，双脚平放在地上。宽握距抓住杠铃，握距略宽于肩宽。松开杠铃并将其慢慢降低到胸部，保持肘部向两侧伸出。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1308', 'smith wide grip bench press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the bench to a comfortable position on the smith machine. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1308-zoOvPcx.jpg', '/static/exercises/gifs/1308-zoOvPcx.gif', '© Gym visual — https://gymvisual.com/', '1726'),
('101309', '史密斯机宽距握下斜卧推', '肱三头肌', '史密斯机', '未分级', '将下斜凳调整至所需角度。躺在长凳上，双脚固定在脚垫下。宽握距抓住杠铃，握距略宽于肩宽。松开杠铃并将其慢慢降低到胸部，保持肘部朝外。当杠铃触及胸部时暂停片刻。将杠铃推回到起始位置，完全伸展双臂。重复所需的重复次数。', 'exercise-dataset', '1309', 'smith wide grip decline bench press', 'chest', '胸部', '10', 'smith machine', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Adjust the decline bench to the desired angle. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1309-wi2H9QX.jpg', '/static/exercises/gifs/1309-wi2H9QX.gif', '© Gym visual — https://gymvisual.com/', '1729'),
('100776', '抓举拉', '腘绳肌', '杠铃', '未分级', '双脚分开与肩同宽站立，杠铃放在你面前的地面上。弯曲膝盖并以臀部为铰链，降低至下蹲位置，用正手握住杠铃。当你通过脚后跟将杠铃抬离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。当杠铃到达臀部水平时，爆发性地将其向上拉，耸肩并将肘部向两侧拉高。当杠铃到达最高点时，迅速落到杠铃下方，将自己拉成深蹲位置。双臂完全伸展，膝盖弯曲，将杠铃举过头顶。伸展臀部和膝盖站起来，将杠铃保持在头顶上方。通过反向运动将杠铃降低回起始位置。重复所需的重复次数。', 'exercise-dataset', '0776', 'snatch pull', 'upper legs', '大腿', '40', 'barbell', 'hamstrings', 'quads', '股四头肌', '["腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and the barbell on the ground in front of you. Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip. Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees. As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides. As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position. Catch the barbell overhead with your arms fully extended and your knees bent. Stand up by extending your hips and knees, keeping the barbell overhead. Lower the barbell back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0776-dG5Smob.jpg', '/static/exercises/gifs/0776-dG5Smob.gif', '© Gym visual — https://gymvisual.com/', '901322'),
('100777', '拼字式脚轮式', '腹斜肌', '哑铃', '未分级', '双脚分开与肩同宽站立，一只手握住哑铃。稍微弯曲膝盖，腰部向前转动，保持背部挺直。将哑铃伸向另一只脚的手臂，同时旋转躯干。返回起始位置并在另一侧重复。继续交替进行所需的重复次数。', 'exercise-dataset', '0777', 'spell caster', 'waist', '腰腹', '60', 'dumbbell', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Bend your knees slightly and hinge forward at the waist, keeping your back straight. Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so. Return to the starting position and repeat on the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0777-p9cCe2r.jpg', '/static/exercises/gifs/0777-p9cCe2r.gif', '© Gym visual — https://gymvisual.com/', '901423'),
('101362', '斯芬克斯式', '臀肌', '自重', '未分级', '面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。收紧核心肌群，将胸部抬离地面，将前臂和脚趾保持在地板上。保持这个姿势几秒钟，确保颈部保持在中立位置。慢慢地将胸部放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1362', 'sphinx', 'back', '背部', '20', 'body weight', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders. Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor. Hold this position for a few seconds, making sure to keep your neck in a neutral position. Slowly lower your chest back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1362-DIVyqrU.jpg', '/static/exercises/gifs/1362-DIVyqrU.gif', '© Gym visual — https://gymvisual.com/', '901222'),
('100778', '蜘蛛式爬行俯卧撑', '核心肌群', '自重', '未分级', '从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。将右膝靠近右肘，使其离开地面。当您将右膝向后拉时，同时弯曲肘部将身体降低到地面。推回起始位置，然后将左膝朝向左肘重复此动作。继续交替进行所需的重复次数。', 'exercise-dataset', '0778', 'spider crawl push up', 'upper legs', '大腿', '40', 'body weight', 'core', 'glutes', '臀肌', '["核心肌群","胸肌","肩部"]', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Bring your right knee towards your right elbow, keeping it off the ground. As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows. Push back up to the starting position and repeat with your left knee towards your left elbow. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0778-P9GFBME.jpg', '/static/exercises/gifs/0778-P9GFBME.gif', '© Gym visual — https://gymvisual.com/', '901229'),
('101363', '脊柱拉伸', '腘绳肌', '自重', '未分级', '坐在地上，双腿在身前伸展。将双手放在身后的地面上，手指指向身体。启动你的核心并慢慢向后倾斜，保持背部挺直。继续向后倾斜，直到感觉到脊柱被拉伸。保持伸展几秒钟，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1363', 'spine stretch', 'back', '背部', '20', 'body weight', 'hamstrings', 'spine', '竖脊肌', '["腘绳肌","臀肌"]', 'Sit on the ground with your legs extended in front of you. Place your hands on the ground behind you, fingers pointing towards your body. Engage your core and slowly lean back, keeping your back straight. Continue leaning back until you feel a stretch in your spine. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1363-JbC2iaV.jpg', '/static/exercises/gifs/1363-JbC2iaV.gif', '© Gym visual — https://gymvisual.com/', '901226'),
('102329', '脊柱转体', '腹斜肌', '自重', '未分级', '坐在地上，双腿在身前伸展。弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。将双手放在脑后，肘部朝外。收紧腹肌，慢慢向右扭转躯干，将右肘拉向左膝盖。扭转结束时暂停片刻，然后慢慢回到起始位置。向左侧重复扭转，将左肘拉向右膝盖。继续交替进行所需的重复次数。', 'exercise-dataset', '2329', 'spine twist', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on the ground with your legs extended in front of you. Bend your knees and place your feet flat on the ground, hip-width apart. Place your hands behind your head with your elbows pointing outwards. Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the left side, bringing your left elbow towards your right knee. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2329-2jl9K55.jpg', '/static/exercises/gifs/2329-2jl9K55.gif', '© Gym visual — https://gymvisual.com/', '901227'),
('102368', '分腿深蹲', '臀肌', '自重', '未分级', '双脚分开与肩同宽站立。一只脚向前迈出一步，并将其放在另一只脚前面约两英尺处。弯曲膝盖和臀部，降低身体，保持背部挺直。继续降低，直到前大腿与地面平行，后膝盖悬停在地面上方。暂停片刻，然后推动前脚跟回到起始位置。重复所需的重复次数，然后换腿并重复。', 'exercise-dataset', '2368', 'split squats', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Take a step forward with one foot and place it about two feet in front of the other foot. Lower your body by bending your knees and hips, keeping your back straight. Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground. Pause for a moment, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', '/static/exercises/images/2368-9E25EOx.jpg', '/static/exercises/gifs/2368-9E25EOx.gif', '© Gym visual — https://gymvisual.com/', '1228'),
('100786', '深蹲挺举', '臀肌', '杠铃', '未分级', '首先将杠铃放在肩膀上，双脚分开与肩同宽。将身体降低至蹲姿，保持挺胸，膝盖位于脚趾上方。当你到达深蹲底部时，爆发性地用腿发力，并将杠铃推过头顶。当杠铃到达最高点时，迅速落入分体位置，一脚向前，一脚向后。双臂完全伸展，后膝盖稍微接触地面，将杠铃举过头顶。从分开的位置站起来，将双脚重新并拢。将杠铃放回肩膀处，然后重复所需的重复次数。', 'exercise-dataset', '0786', 'squat jerk', 'upper legs', '大腿', '40', 'barbell', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群","核心肌群"]', 'Start with the barbell resting on your shoulders, with your feet shoulder-width apart. Lower your body into a squat position, keeping your chest up and your knees tracking over your toes. As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead. As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back. Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground. Stand up from the split position, bringing your feet back together. Lower the barbell back to your shoulders and repeat for the desired number of repetitions.', '/static/exercises/images/0786-IMRsOCn.jpg', '/static/exercises/gifs/0786-IMRsOCn.gif', '© Gym visual — https://gymvisual.com/', '1329'),
('101705', '深蹲BOSU球', '臀肌', 'BOSU球', '未分级', '将博苏球平放在地上。双脚分开与肩同宽站立，将自己放在博苏球的顶部。弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。保持挺胸，将体重放在脚后跟上。降低身体直到大腿与地面平行。暂停片刻，然后用力推动脚后跟，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1705', 'squat on bosu ball', 'upper legs', '大腿', '40', 'bosu ball', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Place the bosu ball on the ground with the flat side up. Stand with your feet shoulder-width apart and position yourself on top of the bosu ball. Lower your body down by bending your knees and hips, as if sitting back into a chair. Keep your chest up and your weight on your heels. Lower yourself until your thighs are parallel to the ground. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1705-T2fA5Ir.jpg', '/static/exercises/gifs/1705-T2fA5Ir.gif', '© Gym visual — https://gymvisual.com/', '2134'),
('101685', '深蹲过顶伸展触碰', '臀肌', '自重', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。当你从深蹲中站起来时，将手臂伸过头顶，伸向天花板。放下手臂并弯曲膝盖再次蹲下，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1685', 'squat to overhead reach', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","核心肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Lower your body down into a squat position by bending your knees and pushing your hips back. As you come up from the squat, extend your arms overhead, reaching towards the ceiling. Return to the starting position by lowering your arms and bending your knees to squat down again. Repeat for the desired number of repetitions.', '/static/exercises/images/1685-QChZi3x.jpg', '/static/exercises/gifs/1685-QChZi3x.gif', '© Gym visual — https://gymvisual.com/', '1235'),
('101686', '深蹲过顶伸展触碰转体', '臀肌', '自重', '未分级', '站立，双脚分开与肩同宽，脚趾稍微外翻。弯曲膝盖并将臀部向后推，将身体降低至蹲姿。当你从深蹲中站起来时，将手臂举过头顶并将躯干扭转到一侧。返回起始位置并重复下蹲，这次将躯干扭转到另一侧。每次深蹲重复时继续交替进行。', 'exercise-dataset', '1686', 'squat to overhead reach with twist', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","核心肌群"]', 'Stand with your feet shoulder-width apart and toes slightly turned out. Lower your body into a squat position by bending your knees and pushing your hips back. As you come up from the squat, raise your arms overhead and twist your torso to one side. Return to the starting position and repeat the squat, this time twisting your torso to the opposite side. Continue alternating sides with each squat repetition.', '/static/exercises/images/1686-5BZHW9s.jpg', '/static/exercises/gifs/1686-5BZHW9s.gif', '© Gym visual — https://gymvisual.com/', '1240'),
('102297', '瑞士球卷腹全程幅度双手颈后头后', '髋屈肌', '瑞士球', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。将双手放在脑后，肘部朝外。收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。在顶部停顿片刻，然后慢慢降低上半身回到起始位置。重复所需的重复次数。', 'exercise-dataset', '2297', 'stability ball crunch (full range hands behind head)', 'waist', '腰腹', '60', 'stability ball', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly lower your upper body back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2297-Gn5FwYT.jpg', '/static/exercises/gifs/2297-Gn5FwYT.gif', '© Gym visual — https://gymvisual.com/', '82145'),
('103291', '斯塔德式推举', '肩部', '自重', '未分级', '首先站立，双脚分开与肩同宽，双臂伸过头顶。稍微弯曲膝盖并启动核心。将身体降低至蹲姿，同时保持手臂伸过头顶。当你蹲下时，将手臂向下压向地面，锻炼三头肌。在深蹲底部停顿片刻，然后用脚后跟站起来，同时将手臂举过头顶。重复所需的重复次数。', 'exercise-dataset', '3291', 'stalder press', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部","核心肌群"]', 'Start by standing with your feet shoulder-width apart and your arms extended overhead. Bend your knees slightly and engage your core. Lower your body down into a squat position while keeping your arms extended overhead. As you squat down, press your arms down towards the ground, engaging your triceps. Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead. Repeat for the desired number of repetitions.', '/static/exercises/images/3291-zd4P4B2.jpg', '/static/exercises/gifs/3291-zd4P4B2.gif', '© Gym visual — https://gymvisual.com/', '901234'),
('103669', '站姿弓箭手式', '肩部', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双臂伸直至前方，与肩同高，与地面平行。将躯干向右旋转，保持双臂伸展，背部挺直。旋转时，向前伸展右臂，向后伸展左臂，模仿拉弓弦的动作。保持该姿势片刻，然后回到起始位置。重复该动作，这次将躯干向左旋转，左臂向前伸展，右臂向后伸展。继续交替进行所需的重复次数。', 'exercise-dataset', '3669', 'standing archer', 'back', '背部', '20', 'body weight', 'shoulders', 'upper back', '上背部', '["肩部","肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you at shoulder height, parallel to the ground. Rotate your torso to the right, keeping your arms extended and your back straight. As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring. Hold the position for a moment, then return to the starting position. Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/3669-JF8AkMX.jpg', '/static/exercises/gifs/3669-JF8AkMX.gif', '© Gym visual — https://gymvisual.com/', '901235'),
('100788', '站姿颈后颈部推举', '肱三头肌', '杠铃', '未分级', '双脚分开与肩同宽站立，用正手握法将杠铃握在颈后。保持背部挺直，核心参与。伸展手臂，充分伸展肘部，将杠铃推过头顶。在顶部停顿片刻，然后慢慢将杠铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0788', 'standing behind neck press', 'shoulders', '肩部', '30', 'barbell', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip. Keep your back straight and core engaged. Press the barbell overhead by extending your arms, fully extending your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0788-xDh0lJr.jpg', '/static/exercises/gifs/0788-xDh0lJr.gif', '© Gym visual — https://gymvisual.com/', '901340'),
('101490', '站姿提踵楼梯', '踝部肌群', '自重', '未分级', '站在台阶或坚固平台的边缘，脚后跟悬垂，脚趾放在台阶上。如果需要，抓住栏杆或墙壁以保持平衡。慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1490', 'standing calf raise (on a staircase)', 'lower legs', '小腿', '70', 'body weight', 'ankles', 'calves', '小腿肌群', '["踝部肌群","双脚"]', 'Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step. Hold onto a railing or wall for balance if needed. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1490-6HmFgmx.jpg', '/static/exercises/gifs/1490-6HmFgmx.gif', '© Gym visual — https://gymvisual.com/', '1245'),
('101397', '站姿小腿', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，脚趾指向前方。将脚后跟抬离地面，尽可能高，用脚趾站立。保持该姿势片刻，然后慢慢降低脚跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1397', 'standing calves', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart, toes pointing forward. Raise your heels off the ground as high as possible, standing on your toes. Hold the position for a moment, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1397-XIHEoCG.jpg', '/static/exercises/gifs/1397-XIHEoCG.gif', '© Gym visual — https://gymvisual.com/', '901238'),
('101398', '站姿小腿小腿拉伸', '腘绳肌', '自重', '未分级', '面朝墙壁或坚固物体站立，距离大约一臂远。将手放在与肩同高的墙壁或物体上。一只脚向后退一步，保持脚跟平放在地面上。稍微弯曲前膝盖并向前倾斜，保持后腿伸直。您应该感觉到小腿肌肉有拉伸感。保持拉伸 20-30 秒。在另一条腿上重复。', 'exercise-dataset', '1398', 'standing calves calf stretch', 'lower legs', '小腿', '70', 'body weight', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand facing a wall or sturdy object, about an arm''s length away. Place your hands on the wall or object at shoulder height. Step back with one foot, keeping your heel flat on the ground. Bend your front knee slightly and lean forward, keeping your back leg straight. You should feel a stretch in your calf muscle. Hold the stretch for 20-30 seconds. Repeat on the other leg.', '/static/exercises/images/1398-qOKcgVP.jpg', '/static/exercises/gifs/1398-qOKcgVP.gif', '© Gym visual — https://gymvisual.com/', '901243'),
('101599', '站姿腘绳肌小腿拉伸拉力带', '小腿肌群', '绳索', '未分级', '站直，双脚分开与肩同宽。用双手握住带子并将其放在脚掌周围。保持腿伸直，从臀部慢慢向前倾斜，保持背部挺直。感受腿筋和小腿肌肉的拉伸。保持拉伸 20-30 秒。放松拉伸并用另一条腿重复。重复所需的重复次数。', 'exercise-dataset', '1599', 'standing hamstring and calf stretch with strap', 'upper legs', '大腿', '40', 'rope', 'calves', 'hamstrings', '腘绳肌', '["小腿肌群"]', 'Stand upright with your feet shoulder-width apart. Hold the strap with both hands and place it around the ball of your foot. Keep your leg straight and slowly lean forward from your hips, keeping your back straight. Feel the stretch in your hamstring and calf muscles. Hold the stretch for 20-30 seconds. Release the stretch and repeat with the other leg. Repeat for the desired number of repetitions.', '/static/exercises/images/1599-xTjr103.jpg', '/static/exercises/gifs/1599-xTjr103.gif', '© Gym visual — https://gymvisual.com/', '902150'),
('100794', '站姿侧向拉伸', '肩部', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双臂伸直至两侧，与地面平行。慢慢将上半身向一侧倾斜，感觉侧面和背阔肌有拉伸感。保持拉伸 15-30 秒。返回起始位置并在另一侧重复。重复所需的重复次数。', 'exercise-dataset', '0794', 'standing lateral stretch', 'back', '背部', '20', 'body weight', 'shoulders', 'lats', '背阔肌', '["肩部","腹斜肌"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out to the sides, parallel to the ground. Slowly lean your upper body to one side, feeling a stretch in your side and lats. Hold the stretch for 15-30 seconds. Return to the starting position and repeat on the other side. Repeat for the desired number of repetitions.', '/static/exercises/images/0794-1jXLYEw.jpg', '/static/exercises/gifs/0794-1jXLYEw.gif', '© Gym visual — https://gymvisual.com/', '901243'),
('101364', '站姿骨盆骨盆倾斜', '腹肌', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双手放在臀部或垂在身体两侧。调动核心肌肉并向前倾斜骨盆，将下背部推向身后的墙壁。保持该位置几秒钟，然后松开并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1364', 'standing pelvic tilt', 'back', '背部', '20', 'body weight', 'abdominals', 'spine', '竖脊肌', '["腹肌"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Place your hands on your hips or let them hang by your sides. Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you. Hold the position for a few seconds, then release and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1364-cuKYxhu.jpg', '/static/exercises/gifs/1364-cuKYxhu.gif', '© Gym visual — https://gymvisual.com/', '901244'),
('100795', '站姿单侧腿弯举', '臀肌', '自重', '未分级', '站立，双脚分开与臀部同宽，双手放在臀部。将体重转移到左腿上，将右脚抬离地面，弯曲膝盖。慢慢地将右脚跟卷向臀部，挤压腿筋。在顶部暂停片刻，然后慢慢将右脚放回起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0795', 'standing single leg curl', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌"]', 'Stand with your feet hip-width apart and your hands on your hips. Shift your weight onto your left leg and lift your right foot off the ground, bending your knee. Slowly curl your right heel towards your glutes, squeezing your hamstring. Pause for a moment at the top, then slowly lower your right foot back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0795-C5jncD2.jpg', '/static/exercises/gifs/0795-C5jncD2.gif', '© Gym visual — https://gymvisual.com/', '481247'),
('100796', '站姿健腹轮滚轮前伸', '下背部', '健腹轮', '未分级', '首先，站直，双脚分开与肩同宽，滚轮位于您的前方。弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0796', 'standing wheel rollerout', 'waist', '腰腹', '60', 'wheel roller', 'lower back', 'abs', '腹肌', '["下背部","肩部"]', 'Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you. Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged. Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible. Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0796-KtRomty.jpg', '/static/exercises/gifs/0796-KtRomty.gif', '© Gym visual — https://gymvisual.com/', '562146'),
('103223', '星形跳跃（男）', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂放在身体两侧。稍微弯曲膝盖并爆发性地跳起来。跳跃时，张开双腿，将手臂向两侧伸展，与身体形成星形。膝盖轻轻弯曲，脚掌轻轻着地。重复所需的重复次数。', 'exercise-dataset', '3223', 'star jump (male)', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend your knees slightly and jump up explosively. As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body. Land softly on the balls of your feet with your knees slightly bent. Repeat for the desired number of repetitions.', '/static/exercises/images/3223-HtfCpfi.jpg', '/static/exercises/gifs/3223-HtfCpfi.gif', '© Gym visual — https://gymvisual.com/', '561247'),
('102138', '固定式自行车跑版本第三式', '股四头肌', '健身车', '未分级', '调整座椅高度和位置以确保正确对齐。将脚放在踏板上，并用带子（如果有）将其固定。以舒适的速度开始踩踏板。保持稳定的节奏并根据需要增加阻力。调动核心肌肉以保持稳定性和正确的姿势。继续踩踏板达到所需的锻炼时间。逐渐减小阻力并减速，然后完全停止。锻炼后伸展双腿并放松。', 'exercise-dataset', '2138', 'stationary bike run v. 3', 'cardio', '有氧', '90', 'stationary bike', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat height and position to ensure proper alignment. Place your feet on the pedals and secure them with the straps if available. Start pedaling at a comfortable pace. Maintain a steady rhythm and increase the resistance as desired. Engage your core muscles to maintain stability and proper posture. Continue pedaling for the desired duration of your workout. Gradually decrease the resistance and slow down before coming to a complete stop. Stretch your legs and cool down after the workout.', '/static/exercises/images/2138-H1PESYI.jpg', '/static/exercises/gifs/2138-H1PESYI.gif', '© Gym visual — https://gymvisual.com/', '82152'),
('100798', '固定式自行车行走', '股四头肌', '固定器械', '未分级', '调整固定自行车上的座椅高度和位置，以确保正确对齐。将脚放在踏板上，并用带子（如果有）将其固定。以舒适的速度开始踩踏，保持背部挺直，核心参与。保持稳定的节奏，并根据需要增加阻力水平。继续踩踏您的有氧运动所需的持续时间。通过逐渐降低步速和阻力水平来冷静下来。锻炼后伸展腿部肌肉，以防止紧绷并促进恢复。', 'exercise-dataset', '0798', 'stationary bike walk', 'cardio', '有氧', '90', 'leverage machine', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the seat height and position on the stationary bike to ensure proper alignment. Place your feet on the pedals and secure them with the straps if available. Start pedaling at a comfortable pace, keeping your back straight and core engaged. Maintain a steady rhythm and increase the resistance level if desired. Continue pedaling for the desired duration of your cardio workout. Cool down by gradually reducing your pace and resistance level. Stretch your leg muscles after the workout to prevent tightness and promote recovery.', '/static/exercises/images/0798-a8VDgLw.jpg', '/static/exercises/gifs/0798-a8VDgLw.gif', '© Gym visual — https://gymvisual.com/', '81649'),
('103314', '分腿马耳他式', '肩部', '自重', '未分级', '首先，悬挂在一对环上，双臂完全伸展，身体呈一条直线。双腿分开，形成跨坐姿势。启动你的核心并慢慢降低你的身体，直到你的手臂与地面平行。保持这个姿势几秒钟，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3314', 'straddle maltese', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","胸肌"]', 'Start by hanging from a pair of rings with your arms fully extended and your body in a straight line. Spread your legs wide apart, forming a straddle position. Engage your core and slowly lower your body until your arms are parallel to the ground. Hold this position for a few seconds, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3314-HfqciZF.jpg', '/static/exercises/gifs/3314-HfqciZF.gif', '© Gym visual — https://gymvisual.com/', '901248'),
('103298', '分腿水平支撑', '肩部', '自重', '未分级', '从俯卧撑位置开始，双手与肩同宽，双脚分开。启动你的核心，慢慢地将你的重心向前移动，将你的肩膀放在你的手上。弯曲肘部，将身体放低至地面，保持肘部靠近身体两侧。在底部停顿片刻，然后双手用力伸直手臂，将身体抬回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3298', 'straddle planche', 'waist', '腰腹', '60', 'body weight', 'shoulders', 'abs', '腹肌', '["肩部","肱三头肌","胸肌"]', 'Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart. Engage your core and slowly shift your weight forward, bringing your shoulders over your hands. Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3298-BL3GHeY.jpg', '/static/exercises/gifs/3298-BL3GHeY.gif', '© Gym visual — https://gymvisual.com/', '901249'),
('101427', '直腿外侧髋部外展肌', '臀肌', '自重', '未分级', '侧躺，双腿伸直并叠放在一起。将下臂放在头下方以获得支撑。启动你的核心并尽可能高地抬起你的上腿，不要旋转你的臀部或向后倾斜。在顶部暂停片刻，然后慢慢将腿放回起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '1427', 'straight leg outer hip abductor', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'abductors', '外展肌群', '["臀肌","腘绳肌"]', 'Lie on your side with your legs straight and stacked on top of each other. Place your bottom arm under your head for support. Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/1427-mQ1tBXn.jpg', '/static/exercises/gifs/1427-mQ1tBXn.gif', '© Gym visual — https://gymvisual.com/', '901256'),
('100803', '超人式俯卧撑', '核心肌群', '自重', '未分级', '从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。收紧核心，将身体降低到地面，保持肘部靠近身体两侧。当你降低身体时，同时将右臂和左腿抬离地面，笔直向外伸展。在顶部暂停片刻，然后放下手臂和腿，同时将自己推回起始位置。重复该动作，这次抬起左臂和右腿。继续交替进行所需的重复次数。', 'exercise-dataset', '0803', 'superman push-up', 'chest', '胸部', '10', 'body weight', 'core', 'pectorals', '胸肌', '["核心肌群","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lower your body towards the ground, keeping your elbows close to your sides. As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out. Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position. Repeat the movement, this time lifting your left arm and right leg. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0803-4GqRrAk.jpg', '/static/exercises/gifs/0803-4GqRrAk.gif', '© Gym visual — https://gymvisual.com/', '81251'),
('100805', '悬吊腹肌前倾伸展', '腹斜肌', '自重', '未分级', '将悬挂训练器连接到高锚点并将带子调整至腰部高度。背对锚点站立，并握住手柄，双臂向前伸展。腰部向前倾，保持身体挺直，核心肌群参与。尽可能降低身体，同时保持腹肌的控制和紧张。在底部停顿片刻，然后慢慢抬起身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0805', 'suspended abdominal fallout', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Attach a suspension trainer to a high anchor point and adjust the straps to waist height. Stand facing away from the anchor point and hold the handles with your arms extended in front of you. Lean forward at the waist, keeping your body straight and your core engaged. Lower your body as far as you can while maintaining control and tension in your abs. Pause for a moment at the bottom, then slowly raise your body back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0805-X3TCNEU.jpg', '/static/exercises/gifs/0805-X3TCNEU.gif', '© Gym visual — https://gymvisual.com/', '901254'),
('100806', '悬吊俯卧撑', '肱三头肌', '自重', '未分级', '找到一个悬挂训练器并将其调整到合适的高度。背对锚点站立，并用正手握住手柄。双脚向前走，身体向前倾斜，直到悬架训练器支撑您的体重。保持身体从头到脚跟伸直，核心部位收紧，胸部朝手柄方向降低。推动你的胸部和手臂回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0806', 'suspended push-up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部","核心肌群"]', 'Find a suspension trainer and adjust it to an appropriate height. Stand facing away from the anchor point and hold the handles with an overhand grip. Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer. Keep your body straight from head to heels, engage your core, and lower your chest towards the handles. Push through your chest and arms to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0806-IaGQCrC.jpg', '/static/exercises/gifs/0806-IaGQCrC.gif', '© Gym visual — https://gymvisual.com/', '81253'),
('100807', '悬吊反向卷腹', '髋屈肌', '自重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。收紧核心肌群，将膝盖抬向胸部，将骨盆卷向胸腔。在顶部暂停片刻，然后慢慢将膝盖放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0807', 'suspended reverse crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage. Pause for a moment at the top, then slowly lower your knees back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0807-R1WYG5D.jpg', '/static/exercises/gifs/0807-R1WYG5D.gif', '© Gym visual — https://gymvisual.com/', '81256'),
('100808', '悬吊划船', '肱二头肌', '自重', '未分级', '将悬挂训练器设置在适当的高度。面向锚点站立，双脚分开与肩同宽。正手握住手柄，手掌相对。向后倾斜，保持身体挺直，脚后跟着地。将胸部拉向手柄，将肩胛骨挤压在一起。在顶部停顿片刻，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0808', 'suspended row', 'back', '背部', '20', 'body weight', 'biceps', 'upper back', '上背部', '["肱二头肌","肩部"]', 'Set up a suspension trainer at an appropriate height. Stand facing the anchor point with your feet shoulder-width apart. Hold the handles with an overhand grip, palms facing each other. Lean back, keeping your body straight and your heels on the ground. Pull your chest towards the handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0808-4OaumBr.jpg', '/static/exercises/gifs/0808-4OaumBr.gif', '© Gym visual — https://gymvisual.com/', '901255'),
('100809', '悬吊分腿蹲', '臀肌', '自重', '未分级', '背对悬吊训练器站立，双脚与肩同宽。向前伸展一条腿，将脚背放在悬吊训练器的脚托中。弯曲站立的腿，将身体降低到弓步位置，保持胸部向上，膝盖与脚趾对齐。推动脚后跟返回到起始位置。重复所需的重复次数，然后换腿。', 'exercise-dataset', '0809', 'suspended split squat', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand facing away from a suspension trainer with your feet shoulder-width apart. Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer. Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes. Push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', '/static/exercises/images/0809-QpXqiq8.jpg', '/static/exercises/gifs/0809-QpXqiq8.gif', '© Gym visual — https://gymvisual.com/', '1258'),
('103433', '游泳式踢腿版本第二式（男）', '腘绳肌', '自重', '未分级', '脸朝下躺在垫子上，双臂伸过头顶。启动核心肌群，同时将胸部和腿部抬离地面。以扑动的动作上下踢腿，就像在游泳一样。继续踢所需的重复次数。将胸部和双腿放低至起始位置。', 'exercise-dataset', '3433', 'swimmer kicks v. 2 (male)', 'upper legs', '大腿', '40', 'body weight', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","小腿肌群"]', 'Lie face down on a mat with your arms extended overhead. Engage your core and lift your chest and legs off the ground simultaneously. Kick your legs up and down in a fluttering motion, as if you were swimming. Continue kicking for the desired number of repetitions. Lower your chest and legs back down to the starting position.', '/static/exercises/images/3433-SP3hUez.jpg', '/static/exercises/gifs/3433-SP3hUez.gif', '© Gym visual — https://gymvisual.com/', '901263'),
('103318', '摆动360度', '肩部', '自重', '未分级', '站立，双脚分开与肩同宽，膝盖稍微弯曲。将双臂伸直在身前，与地面平行。启动你的核心并以圆周运动摆动你的手臂，同时旋转你的躯干。继续圆周运动，摆动手臂并旋转躯干，达到所需的重复次数。记住在整个练习过程中保持呼吸。', 'exercise-dataset', '3318', 'swing 360', 'cardio', '有氧', '90', 'body weight', 'shoulders', 'cardiovascular system', '心肺系统', '["肩部","核心肌群"]', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold your arms straight out in front of you, parallel to the ground. Engage your core and swing your arms in a circular motion, rotating your torso as you do so. Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions. Remember to breathe throughout the exercise.', '/static/exercises/images/3318-tnaj0mT.jpg', '/static/exercises/gifs/3318-tnaj0mT.gif', '© Gym visual — https://gymvisual.com/', '901258'),
('101753', '三训练凳臂屈伸', '胸肌', '自重', '未分级', '坐在长凳上，双手抓住边缘，手指指向前方。将臀部滑离长凳，用手支撑体重。弯曲肘部并降低身体，直到上臂与地面平行。将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1753', 'three bench dip', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on a bench with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body until your upper arms are parallel to the ground. Push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1753-DQ0cqkT.jpg', '/static/exercises/gifs/1753-DQ0cqkT.gif', '© Gym visual — https://gymvisual.com/', '481261'),
('102459', '轮胎翻转', '腘绳肌', '轮胎', '未分级', '双脚分开与肩同宽站立，面向轮胎。弯曲膝盖并以臀部为铰链，降低至蹲姿。向下伸手，用双手抓住轮胎的底部边缘，手指朝向您。调动你的臀部和腿部肌肉，并爆发性地推动你的腿，将轮胎抬离地面。当轮胎翻转时，用上半身的力量引导轮胎并保持控制。轮胎完全翻转后，迅速后退并重置姿势。重复所需的重复次数。', 'exercise-dataset', '2459', 'tire flip', 'upper legs', '大腿', '40', 'tire', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","核心肌群"]', 'Stand with your feet shoulder-width apart, facing the tire. Bend your knees and hinge at the hips, lowering into a squat position. Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you. Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground. As the tire flips over, use your upper body strength to guide it and maintain control. Once the tire is fully flipped, quickly step back and reset your stance. Repeat for the desired number of repetitions.', '/static/exercises/images/2459-oZjMu1t.jpg', '/static/exercises/gifs/2459-oZjMu1t.gif', '© Gym visual — https://gymvisual.com/', '902160'),
('100811', '六角杠杆硬拉', '腘绳肌', '六角杠铃', '未分级', '双脚分开与肩同宽站立，将陷阱杆放在你面前的地面上。弯曲臀部和膝盖，降低身体高度，并用正手握住陷阱杆的手柄。当你开始通过伸展臀部和膝盖将陷阱杆抬离地面时，保持背部挺直，挺胸。当你举起时，专注于通过脚后跟发力，并在运动的最高点挤压臀部。弯曲臀部和膝盖，将陷阱杆放回地面，在整个运动过程中保持背部挺直。重复所需的重复次数。', 'exercise-dataset', '0811', 'trap bar deadlift', 'upper legs', '大腿', '40', 'trap bar', 'hamstrings', 'glutes', '臀肌', '["腘绳肌","股四头肌","下背部"]', 'Stand with your feet shoulder-width apart and the trap bar on the ground in front of you. Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip. Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees. As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement. Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/0811-jQGwmxN.jpg', '/static/exercises/gifs/0811-jQGwmxN.gif', '© Gym visual — https://gymvisual.com/', '82163'),
('100814', '肱三头肌臂屈伸', '胸肌', '自重', '未分级', '坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。将臀部滑离长凳，用手支撑体重。弯曲肘部，将身体放低至地面，保持背部靠近长凳。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0814', 'triceps dip', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0814-X6C6i5Y.jpg', '/static/exercises/gifs/0814-X6C6i5Y.gif', '© Gym visual — https://gymvisual.com/', '481262'),
('100812', '肱三头肌臂屈伸训练凳腿', '胸肌', '自重', '未分级', '坐在长凳边缘，双手抓住边缘，手指指向前方。双脚向前走，将臀部滑离长凳，然后伸直手臂。弯曲肘部，将身体放低至地面，保持背部靠近长凳。推动手掌以伸直手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0812', 'triceps dip (bench leg)', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward. Walk your feet forward, sliding your butt off the bench, and straighten your arms. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0812-VuoerH0.jpg', '/static/exercises/gifs/0812-VuoerH0.gif', '© Gym visual — https://gymvisual.com/', '481267'),
('100813', '肱三头肌臂屈伸之间训练凳之间', '胸肌', '自重', '未分级', '坐在长凳上，双手抓住长凳边缘，手指指向前方。将臀部滑离长凳，用手支撑体重。弯曲肘部，将身体放低至地面，保持背部靠近长凳。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0813', 'triceps dip (between benches)', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0813-Wgbn9qo.jpg', '/static/exercises/gifs/0813-Wgbn9qo.gif', '© Gym visual — https://gymvisual.com/', '481268'),
('100815', '肱三头肌臂屈伸地板', '胸肌', '自重', '未分级', '坐在椅子或长凳的边缘，双手放在臀部旁边，手指指向前方。将你的屁股从椅子前面滑下来，双腿伸到你面前。伸直手臂，保持肘部稍微弯曲，以保持三头肌和肘关节的张力。慢慢弯曲你的肘部，将你的身体向地板降低，直到你的肘部成大约 90 度角。一旦到达动作的底部，向下压入椅子以伸直肘部，返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0815', 'triceps dips floor', 'upper arms', '上臂', '50', 'body weight', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward. Slide your butt off the front of the chair with your legs extended in front of you. Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints. Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle. Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0815-7aVz15j.jpg', '/static/exercises/gifs/0815-7aVz15j.gif', '© Gym visual — https://gymvisual.com/', '481267'),
('100816', '肱三头肌推举', '肩部', '自重', '未分级', '双脚分开与肩同宽站立，膝盖稍微弯曲。将双臂伸直在身前，与地面平行。弯曲肘部，将身体放低至地面，保持上臂靠近身体两侧。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0816', 'triceps press', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you, parallel to the ground. Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0816-fSrPP6B.jpg', '/static/exercises/gifs/0816-fSrPP6B.gif', '© Gym visual — https://gymvisual.com/', '901266'),
('100817', '肱三头肌拉伸', '肩部', '自重', '未分级', '站立或坐直，背部挺直。将一只手臂伸过头顶，肘部弯曲。将另一只手放在弯曲的肘部上，然后轻轻地将其拉向头部。保持拉伸 15-30 秒，感受三头肌的轻微拉伸。松开拉伸并在另一只手臂上重复。', 'exercise-dataset', '0817', 'triceps stretch', 'upper arms', '上臂', '50', 'body weight', 'shoulders', 'triceps', '肱三头肌', '["肩部"]', 'Stand or sit upright with your back straight. Extend one arm overhead, bending it at the elbow. Place your opposite hand on the bent elbow and gently pull it towards your head. Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps. Release the stretch and repeat on the other arm.', '/static/exercises/images/0817-uOV3Itw.jpg', '/static/exercises/gifs/0817-uOV3Itw.gif', '© Gym visual — https://gymvisual.com/', '901267'),
('100871', '团身卷腹', '髋屈肌', '自重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将双手放在脑后，肘部朝外。收紧腹肌，将肩胛骨抬离地面，将膝盖靠近胸部，同时将上半身卷向膝盖。在顶部停顿片刻，然后慢慢降低肩胛骨并将双腿伸展回起始位置。重复所需的重复次数。', 'exercise-dataset', '0871', 'tuck crunch', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees. Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0871-BMMolZ3.jpg', '/static/exercises/gifs/0871-BMMolZ3.gif', '© Gym visual — https://gymvisual.com/', '81268'),
('100818', '双把手把手平行握握高位下拉', '肱二头肌', '绳索器械', '未分级', '调整座椅高度并将自己面向电缆机。正手握住手柄，双手与肩同宽。坐下来，将大腿放在大腿垫下方，保持双脚平放在地板上。稍微向后倾斜，挺胸，保持脊柱中立。将手柄向下拉至上胸部，将肩胛骨挤压在一起。在动作的底部暂停片刻，感受背阔肌的收缩。慢慢松开手柄并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0818', 'twin handle parallel grip lat pulldown', 'back', '背部', '20', 'cable', 'biceps', 'lats', '背阔肌', '["肱二头肌","菱形肌","后侧DELTOIDS"]', 'Adjust the seat height and position yourself facing the cable machine. Grasp the handles with an overhand grip, hands shoulder-width apart. Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor. Lean back slightly and keep your chest up, maintaining a neutral spine. Pull the handles down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0818-rkg41Fb.jpg', '/static/exercises/gifs/0818-rkg41Fb.gif', '© Gym visual — https://gymvisual.com/', '81577'),
('101466', '转体髋部抬举', '腹斜肌', '自重', '未分级', '仰卧，膝盖弯曲，双脚平放在地上。将双手放在身体两侧以获得支撑。收紧臀部并将臀部抬离地面，从膝盖到肩膀形成一条直线。在保持臀部抬起的同时，将下半身扭转到右侧，使膝盖靠近地面。返回起始位置并向左侧重复扭转。继续交替扭转所需的重复次数。', 'exercise-dataset', '1466', 'twist hip lift', 'upper legs', '大腿', '40', 'body weight', 'obliques', 'glutes', '臀肌', '["腹斜肌","腘绳肌"]', 'Lie on your back with your knees bent and feet flat on the ground. Place your hands by your sides for support. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground. Return to the starting position and repeat the twist to the left side. Continue alternating twists for the desired number of repetitions.', '/static/exercises/images/1466-AX1kB0o.jpg', '/static/exercises/gifs/1466-AX1kB0o.gif', '© Gym visual — https://gymvisual.com/', '901272'),
('102802', '扭转举腿', '腹斜肌', '自重', '未分级', '平躺，双腿伸展，双臂放在身体两侧。将双手放在臀部下方以获得支撑。收紧腹肌，将双腿抬离地面，保持伸直。当你抬起双腿时，将臀部扭向一侧，将双腿拉向对面的肩膀。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复这个动作，这次将臀部扭到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '2802', 'twisted leg raise', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your abs and lift both legs off the ground, keeping them straight. As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat the movement, this time twisting your hips to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2802-C0eCeEt.jpg', '/static/exercises/gifs/2802-C0eCeEt.gif', '© Gym visual — https://gymvisual.com/', '241273'),
('102801', '扭转举腿（女）', '腹斜肌', '自重', '未分级', '平躺，双腿伸展，双臂放在身体两侧。弯曲膝盖，将双腿抬离地面，将它们拉向胸部。当你抬起双腿时，将臀部扭向一侧，将膝盖移向另一侧的肩膀。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复这个动作，这次将臀部扭到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '2801', 'twisted leg raise (female)', 'waist', '腰腹', '60', 'body weight', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and lift your legs off the ground, bringing them towards your chest. As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat the movement, this time twisting your hips to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2801-yT9tk17.jpg', '/static/exercises/gifs/2801-yT9tk17.gif', '© Gym visual — https://gymvisual.com/', '241276'),
('103231', '双脚尖触碰（男）', '腘绳肌', '自重', '未分级', '双脚分开与肩同宽站立，双臂向两侧伸展。腰部向前弯曲，保持背部挺直，膝盖稍微弯曲。双手向下伸向脚趾，保持双腿伸直。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3231', 'two toe touch (male)', 'back', '背部', '20', 'body weight', 'hamstrings', 'spine', '竖脊肌', '["腘绳肌","臀肌"]', 'Stand with your feet shoulder-width apart and your arms extended out to the sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with both hands, keeping your legs straight. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3231-p195zsJ.jpg', '/static/exercises/gifs/3231-p195zsJ.gif', '© Gym visual — https://gymvisual.com/', '901277'),
('101365', '上部后侧拉伸', '肩部', '自重', '未分级', '站直，双脚分开与肩同宽。将双臂伸直在身前，与地面平行。手指交叉，手掌旋转远离身体。慢慢地将手臂举过头顶，保持它们伸直并彼此平行。当你举起手臂时，将肩胛骨挤压在一起。保持拉伸 15-30 秒，然后松开并重复。', 'exercise-dataset', '1365', 'upper back stretch', 'back', '背部', '20', 'body weight', 'shoulders', 'upper back', '上背部', '["肩部"]', 'Stand up straight with your feet shoulder-width apart. Extend your arms straight in front of you, parallel to the ground. Interlace your fingers and rotate your palms away from your body. Slowly raise your arms overhead, keeping them straight and parallel to each other. As you raise your arms, squeeze your shoulder blades together. Hold the stretch for 15-30 seconds, then release and repeat.', '/static/exercises/images/1365-GSDioYu.jpg', '/static/exercises/gifs/1365-GSDioYu.gif', '© Gym visual — https://gymvisual.com/', '901276'),
('101366', '向上面向犬式', '肩部', '自重', '未分级', '脸朝下躺在地板上，双腿伸到身后。将双手放在下肋骨旁边的地板上，手指指向前方。双手用力按在地板上，伸直手臂，将躯干和大腿抬离地面。向后和向下转动肩膀，打开胸部，将目光转向天花板。保持这个姿势几次呼吸，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1366', 'upward facing dog', 'back', '背部', '20', 'body weight', 'shoulders', 'spine', '竖脊肌', '["肩部","胸肌"]', 'Lie face down on the floor with your legs extended behind you. Place your hands on the floor next to your lower ribs, fingers pointing forward. Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground. Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling. Hold this position for a few breaths, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1366-01qpYSe.jpg', '/static/exercises/gifs/1366-01qpYSe.gif', '© Gym visual — https://gymvisual.com/', '901277'),
('103420', 'V字坐地板', '髋屈肌', '自重', '未分级', '坐在地板上，双腿伸到身前。稍微向后倾斜，将双腿抬离地面，保持伸直。同时，将上半身抬离地面，并将手臂伸向腿部。保持这个姿势几秒钟，然后慢慢降低上半身和双腿回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3420', 'v-sit on floor', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Sit on the floor with your legs extended in front of you. Lean back slightly and lift your legs off the ground, keeping them straight. Simultaneously, lift your upper body off the ground and reach your arms towards your legs. Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3420-ZuXu4Eq.jpg', '/static/exercises/gifs/3420-ZuXu4Eq.gif', '© Gym visual — https://gymvisual.com/', '901278'),
('100826', '垂直举腿平行握双杠', '髋屈肌', '自重', '未分级', '悬挂在双杠上，双臂完全伸展，身体伸直。启动你的核心并将双腿抬起到你面前，保持伸直。继续抬起，直到双腿与地面平行或稍高。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0826', 'vertical leg raise (on parallel bars)', 'waist', '腰腹', '60', 'body weight', 'hip flexors', 'abs', '腹肌', '["髋屈肌"]', 'Hang from the parallel bars with your arms fully extended and your body straight. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or slightly higher. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0826-ZNgOYQU.jpg', '/static/exercises/gifs/0826-ZNgOYQU.gif', '© Gym visual — https://gymvisual.com/', '241285'),
('102141', '行走椭圆机交叉训练机', '股四头肌', '椭圆机', '未分级', '将椭圆机的阻力水平和倾斜度调整到您想要的设置。踩上机器的踏板并轻轻握住手柄。首先用脚向下压，然后将手柄拉向身体。继续这个动作，交替推和拉，以模拟行走或跑步动作。在整个练习过程中保持稳定的步伐并保持核心参与。继续进行有氧运动所需的持续时间。下车前逐渐降低机器的强度和速度。', 'exercise-dataset', '2141', 'walk elliptical cross trainer', 'cardio', '有氧', '90', 'elliptical machine', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Adjust the resistance level and incline of the elliptical machine to your desired settings. Step onto the pedals of the machine and grip the handles lightly. Begin by pushing down with your feet and pulling the handles towards your body. Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion. Maintain a steady pace and keep your core engaged throughout the exercise. Continue for the desired duration of your cardio workout. Gradually decrease the intensity and speed of the machine before stepping off.', '/static/exercises/images/2141-rjtuP6X.jpg', '/static/exercises/gifs/2141-rjtuP6X.gif', '© Gym visual — https://gymvisual.com/', '162182'),
('103655', '行走高位双膝弓步', '股四头肌', '自重', '未分级', '双脚分开与臀部同宽站立。将右膝尽可能高地抬向胸部，同时用左腿保持平衡。右脚向前迈出一步，身体降低成弓步姿势，双膝弯曲成 90 度角。用右脚推出，并将左膝抬向胸部。左脚向前迈出一步，将身体降低至弓步位置。继续交替双腿并向前冲刺，保持核心参与并保持稳定的步伐。重复所需的重复次数。', 'exercise-dataset', '3655', 'walking high knees lunge', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Stand with your feet hip-width apart. Lift your right knee up towards your chest as high as you can while balancing on your left leg. Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle. Push off with your right foot and bring your left knee up towards your chest. Step forward with your left foot and lower your body into a lunge position. Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace. Repeat for the desired number of repetitions.', '/static/exercises/images/3655-J9zIWig.jpg', '/static/exercises/gifs/3655-J9zIWig.gif', '© Gym visual — https://gymvisual.com/', '901283'),
('101460', '行走弓步', '股四头肌', '自重', '未分级', '双脚分开与肩同宽站立。右腿向前迈出一步，将身体降低至弓步位置。保持躯干直立，前膝与脚踝对齐。右脚蹬地，左脚向前，左腿呈弓步姿势。继续交替双腿向前行走，保持受控且稳定的步伐。重复所需的重复次数。', 'exercise-dataset', '1460', 'walking lunge', 'upper legs', '大腿', '40', 'body weight', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Take a step forward with your right leg, lowering your body into a lunge position. Keep your torso upright and your front knee aligned with your ankle. Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg. Continue alternating legs and walking forward, maintaining a controlled and steady pace. Repeat for the desired number of repetitions.', '/static/exercises/images/1460-IZVHb27.jpg', '/static/exercises/gifs/1460-IZVHb27.gif', '© Gym visual — https://gymvisual.com/', '321280'),
('103666', '行走上斜跑步机', '股四头肌', '固定器械', '未分级', '将跑步机的倾斜度调整到您想要的强度。站在跑步机上，双脚分开与肩同宽。开始以舒适的步伐行走，确保保持正确的姿势。在整个练习过程中，调动核心肌肉并保持背部挺直。继续在倾斜跑步机上行走，完成有氧运动所需的时间。逐渐降低跑步机的坡度和速度，使其冷却后再停止。', 'exercise-dataset', '3666', 'walking on incline treadmill', 'cardio', '有氧', '90', 'leverage machine', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Adjust the incline level on the treadmill to your desired intensity. Stand on the treadmill with your feet shoulder-width apart. Start walking at a comfortable pace, ensuring that you maintain proper form. Engage your core muscles and keep your back straight throughout the exercise. Continue walking on the incline treadmill for the desired duration of your cardio workout. Gradually decrease the incline and speed of the treadmill to cool down before stopping.', '/static/exercises/images/3666-rjiM4L3.jpg', '/static/exercises/gifs/3666-rjiM4L3.gif', '© Gym visual — https://gymvisual.com/', '1685'),
('102311', '行走登阶机', '股四头肌', '登阶机', '未分级', '将步进机调整到舒适的水平。走上机器，将双手放在扶手上以获得支撑。开始行走时，将一只脚放在台阶上，然后将另一只脚放在台阶上，双腿交替。保持直立姿势并锻炼核心肌肉。继续步行所需的时间或距离。当您对锻炼感到更加舒适时，逐渐增加强度或速度。完成练习后记得冷静下来并伸展身体。', 'exercise-dataset', '2311', 'walking on stepmill', 'cardio', '有氧', '90', 'stepmill machine', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","臀肌","小腿肌群"]', 'Adjust the stepmill machine to a comfortable level. Step onto the machine and place your hands on the handrails for support. Start walking by placing one foot on a step and then the other, alternating between legs. Maintain an upright posture and engage your core muscles. Continue walking for the desired duration or distance. Gradually increase the intensity or speed as you become more comfortable with the exercise. Remember to cool down and stretch after completing the exercise.', '/static/exercises/images/2311-j9Q5crt.jpg', '/static/exercises/gifs/2311-j9Q5crt.gif', '© Gym visual — https://gymvisual.com/', '902184'),
('100830', '负重训练凳臂屈伸', '胸肌', '负重', '未分级', '坐在长凳上，双手抓住边缘，手指指向前方。将臀部滑离长凳，用手支撑体重。弯曲肘部降低身体，直到上臂与地板平行。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '0830', 'weighted bench dip', 'upper arms', '上臂', '50', 'weighted', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on a bench with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/0830-MU9HnE7.jpg', '/static/exercises/gifs/0830-MU9HnE7.gif', '© Gym visual — https://gymvisual.com/', '482185'),
('102987', '负重窄距握反手引体向上臂屈伸深蹲架', '肱二头肌', '负重', '未分级', '站在俯卧撑前面，用反握抓住双杠，双手与肩同宽。悬挂在杠上，双臂完全伸展，双脚离开地面，身体伸直。收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体两侧。继续拉，直到下巴高于杠铃，然后暂停片刻。慢慢地将身体放回起始位置，充分伸展双臂。重复所需的重复次数。', 'exercise-dataset', '2987', 'weighted close grip chin-up on dip cage', 'back', '背部', '20', 'weighted', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart. Hang from the bars with your arms fully extended, feet off the ground, and body straight. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides. Continue pulling until your chin is above the bars, then pause for a moment. Slowly lower your body back down to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2987-Gk1r408.jpg', '/static/exercises/gifs/2987-Gk1r408.gif', '© Gym visual — https://gymvisual.com/', '902194'),
('103643', '负重哥萨克深蹲（男）', '股四头肌', '负重', '未分级', '站立时双脚分开比肩宽，脚趾稍微向外。用双手将重物放在胸前。将您的体重转移到一侧，并通过弯曲您转移一侧的膝盖来降低身体，同时保持另一条腿伸直。尽可能降低身体高度，同时保持平衡并挺胸。推动弯曲腿的脚跟以返回到起始位置。在另一侧重复，双腿之间交替。', 'exercise-dataset', '3643', 'weighted cossack squats (male)', 'upper legs', '大腿', '40', 'weighted', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet wider than shoulder-width apart and toes pointing slightly outward. Hold a weight in front of your chest with both hands. Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight. Go as low as you can while maintaining balance and keeping your chest up. Push through the heel of the bent leg to return to the starting position. Repeat on the other side, alternating between legs.', '/static/exercises/images/3643-GWoKnIm.jpg', '/static/exercises/gifs/3643-GWoKnIm.gif', '© Gym visual — https://gymvisual.com/', '2189'),
('100832', '负重卷腹', '腹斜肌', '负重', '未分级', '平躺，膝盖弯曲，双脚平放在地上。将杠铃片或哑铃放在胸前。收紧腹肌，将上半身抬离地面，向前卷曲，直到肩胛骨离开地面。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0832', 'weighted crunch', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌"]', 'Lie flat on your back with your knees bent and feet flat on the ground. Hold a weight plate or dumbbell on your chest. Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0832-s8nrDXF.jpg', '/static/exercises/gifs/0832-s8nrDXF.gif', '© Gym visual — https://gymvisual.com/', '82186'),
('103670', '负重下斜坐向上', '髋屈肌', '负重', '未分级', '平躺在倾斜的长凳上，双脚固定在脚垫下。将双手放在脑后或放在胸前。收紧腹肌，慢慢将上半身抬离长凳，向前卷曲，直到躯干垂直于地面。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '3670', 'weighted decline sit-up', 'waist', '腰腹', '60', 'weighted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Lie flat on a decline bench with your feet secured under the foot pads. Place your hands behind your head or across your chest. Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3670-EZeDVzO.jpg', '/static/exercises/gifs/3670-EZeDVzO.gif', '© Gym visual — https://gymvisual.com/', '162189'),
('100833', '负重骑驴式提踵', '腘绳肌', '负重', '未分级', '站在一个升高的平台上，脚趾放在边缘，脚后跟悬垂。抓住一个稳定的物体作为支撑。伸展脚踝，将脚后跟尽可能抬高。在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0833', 'weighted donkey calf raise', 'lower legs', '小腿', '70', 'weighted', 'hamstrings', 'calves', '小腿肌群', '["腘绳肌","臀肌"]', 'Stand on a raised platform with your toes on the edge and your heels hanging off. Hold onto a stable object for support. Raise your heels as high as possible by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0833-LmaFNZS.jpg', '/static/exercises/gifs/0833-LmaFNZS.gif', '© Gym visual — https://gymvisual.com/', '2192'),
('101310', '负重下落俯卧撑', '肱三头肌', '负重', '未分级', '从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。将胸部压向地面，保持肘部靠近身体。一旦你的胸部刚好高于地面，爆发性地把自己推起来，将双手抬离地面。当你向上推时，快速将双手移至两侧并稍微向前，让你的身体向地面落下。将双手置于更宽的位置，然后立即再次将胸部降低到地面。重复俯卧撑动作，下降并用双手抓住自己在较窄的位置。继续在更宽和更窄的手位置之间交替，以达到所需的重复次数。', 'exercise-dataset', '1310', 'weighted drop push up', 'chest', '胸部', '10', 'weighted', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Lower your chest towards the ground, keeping your elbows close to your body. Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground. As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground. Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again. Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position. Continue alternating between the wider and narrower hand positions for the desired number of repetitions.', '/static/exercises/images/1310-PSlvNMs.jpg', '/static/exercises/gifs/1310-PSlvNMs.gif', '© Gym visual — https://gymvisual.com/', '902193'),
('102135', '负重前侧平板支撑', '肩部', '负重', '未分级', '首先脸朝下躺在地板上。将前臂放在地面上，肘部直接位于肩膀下方。将双腿伸直在身后，脚趾着地。启动你的核心并将你的身体抬离地面，用前臂和脚趾保持平衡。保持身体从头部到脚跟呈一条直线。保持此位置所需的时间。将身体放低至起始位置。重复所需的重复次数。', 'exercise-dataset', '2135', 'weighted front plank', 'waist', '腰腹', '60', 'weighted', 'shoulders', 'abs', '腹肌', '["肩部","下背部"]', 'Start by lying face down on the floor. Place your forearms on the ground, with your elbows directly under your shoulders. Extend your legs straight out behind you, with your toes on the ground. Engage your core and lift your body off the ground, balancing on your forearms and toes. Keep your body in a straight line from your head to your heels. Hold this position for the desired amount of time. Lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/2135-VBAWRPG.jpg', '/static/exercises/gifs/2135-VBAWRPG.gif', '© Gym visual — https://gymvisual.com/', '2192'),
('100834', '负重前侧上举', '肱二头肌', '负重', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0834', 'weighted front raise', 'shoulders', '肩部', '30', 'weighted', 'biceps', 'delts', '三角肌', '["肱二头肌","前臂"]', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0834-e4aFmFY.jpg', '/static/exercises/gifs/0834-e4aFmFY.gif', '© Gym visual — https://gymvisual.com/', '242193'),
('100866', '负重悬垂腿髋部上举', '髋屈肌', '负重', '未分级', '悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。启动你的核心并将双腿抬起到你面前，保持伸直。继续抬起，直到双腿与地面平行或稍高。在顶部暂停片刻，然后慢慢将双腿放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0866', 'weighted hanging leg-hip raise', 'waist', '腰腹', '60', 'weighted', 'hip flexors', 'abs', '腹肌', '["髋屈肌","下背部"]', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or slightly higher. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0866-QOA0FD0.jpg', '/static/exercises/gifs/0866-QOA0FD0.gif', '© Gym visual — https://gymvisual.com/', '902196'),
('100835', '负重超伸展瑞士球', '臀肌', '负重', '未分级', '将自己面朝下放在稳定球上，臀部放在球上，双脚靠在墙上以保持稳定。将双手放在脑后或交叉放在胸前。启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体形成一条直线。在顶部停顿片刻，然后慢慢将上半身放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0835', 'weighted hyperextension (on stability ball)', 'back', '背部', '20', 'weighted', 'glutes', 'spine', '竖脊肌', '["臀肌","腘绳肌"]', 'Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability. Place your hands behind your head or cross them over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0835-8urJS9b.jpg', '/static/exercises/gifs/0835-8urJS9b.gif', '© Gym visual — https://gymvisual.com/', '902199'),
('103641', '负重跪姿踏步摆动', '肱三头肌', '负重', '未分级', '从跪姿开始，膝盖分开与臀部同宽，背部挺直。每只手各握一个重物，双臂在身前笔直向下伸展。启动你的核心肌群，将重物向上举过头顶，保持手臂伸直。将重量放回起始位置，然后重复所需的重复次数。', 'exercise-dataset', '3641', 'weighted kneeling step with swing', 'shoulders', '肩部', '30', 'weighted', 'triceps', 'delts', '三角肌', '["肱三头肌","核心肌群"]', 'Start in a kneeling position with your knees hip-width apart and your back straight. Hold a weight in each hand, with your arms extended straight down in front of you. Engage your core and swing the weights up and overhead, keeping your arms straight. Lower the weights back down to the starting position and repeat for the desired number of repetitions.', '/static/exercises/images/3641-7uFJuXp.jpg', '/static/exercises/gifs/3641-7uFJuXp.gif', '© Gym visual — https://gymvisual.com/', '902200'),
('103644', '负重弓步摆动', '股四头肌', '负重', '未分级', '双脚分开与肩同宽站立，每只手各握一个重物。右脚向前迈出一步，将身体降低至弓步位置。当你向前冲时，向前和向上摆动重物，保持手臂伸直。用右脚推出并返回到起始位置，将重物向下摆动。用左脚重复上述动作，并继续交替双腿，完成所需的重复次数。', 'exercise-dataset', '3644', 'weighted lunge with swing', 'upper legs', '大腿', '40', 'weighted', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, holding a weight in each hand. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge forward, swing the weights forward and upward, keeping your arms straight. Push off with your right foot and return to the starting position, swinging the weights back down. Repeat with your left foot and continue alternating legs for the desired number of repetitions.', '/static/exercises/images/3644-5WiFcYk.jpg', '/static/exercises/gifs/3644-5WiFcYk.gif', '© Gym visual — https://gymvisual.com/', '322199'),
('103286', '负重肌肉向上', '肱二头肌', '负重', '未分级', '首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。启动核心肌群，将身体拉向杠铃杆，以胸部为主导。当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。继续拉起自己，直到胸部到达杠铃，然后暂停片刻。慢慢地将自己放回到起始位置，在整个运动过程中保持控制。重复所需的重复次数。', 'exercise-dataset', '3286', 'weighted muscle up', 'back', '背部', '20', 'weighted', 'biceps', 'lats', '背阔肌', '["肱二头肌","肱三头肌","肩部","胸肌"]', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart. Engage your core and pull your body up towards the bar, leading with your chest. As you reach the top of the movement, transition your grip so that your palms are facing towards you. Continue pulling yourself up until your chest reaches the bar, then pause for a moment. Slowly lower yourself back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', '/static/exercises/images/3286-JsOV1SU.jpg', '/static/exercises/gifs/3286-JsOV1SU.gif', '© Gym visual — https://gymvisual.com/', '902198'),
('103312', '负重肌肉向上杆', '肱二头肌', '负重', '未分级', '首先悬挂在引体向上杆上，手掌背向自己，双手之间的距离略大于肩宽。启动你的核心并将肩胛骨向下拉和向后拉。弯曲肘部，将胸部拉向杠铃杆，保持身体挺直。当你的胸部到达杠铃时，用手向下推并将肘部向后推，将身体提升到杠铃上方。在动作的最高点暂停，然后慢慢降低回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3312', 'weighted muscle up (on bar)', 'back', '背部', '20', 'weighted', 'biceps', 'lats', '背阔肌', '["肱二头肌","肱三头肌","肩部","前臂"]', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your elbows and pull your chest towards the bar, keeping your body straight. Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/3312-MCkqdKE.jpg', '/static/exercises/gifs/3312-MCkqdKE.gif', '© Gym visual — https://gymvisual.com/', '902203'),
('103290', '负重单手引体向上', '肱二头肌', '负重', '未分级', '正手握住引体向上杆，握距略宽于肩宽。悬挂在杠上，手臂完全伸展，身体伸直。弯曲肘部并挤压背部肌肉，调动核心力量，将身体拉向杠铃杆。继续拉，直到下巴位于杠铃上方。有控制地降低身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '3290', 'weighted one hand pull up', 'back', '背部', '20', 'weighted', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arm fully extended and your body straight. Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles. Continue pulling until your chin is above the bar. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', '/static/exercises/images/3290-fXfqg1E.jpg', '/static/exercises/gifs/3290-fXfqg1E.gif', '© Gym visual — https://gymvisual.com/', '902204'),
('100840', '负重过顶卷腹瑞士球', '腹斜肌', '负重', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。双手握住杠铃片或哑铃，并将手臂伸过头顶。收紧腹肌，慢慢向前弯曲躯干，使胸部靠近膝盖。在顶部暂停片刻，然后慢慢将躯干放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0840', 'weighted overhead crunch (on stability ball)', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a weight plate or dumbbell with both hands and extend your arms overhead. Engage your abs and slowly curl your torso forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly lower your torso back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0840-xmM75XG.jpg', '/static/exercises/gifs/0840-xmM75XG.gif', '© Gym visual — https://gymvisual.com/', '82207'),
('100841', '负重引体向上', '肱二头肌', '负重', '未分级', '正手握住引体向上杆，握距略宽于肩宽。悬挂在杠上，双臂完全伸展，身体伸直。收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0841', 'weighted pull-up', 'back', '背部', '20', 'weighted', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0841-HMzLjXx.jpg', '/static/exercises/gifs/0841-HMzLjXx.gif', '© Gym visual — https://gymvisual.com/', '2200'),
('100844', '负重绕环臂', '肱三头肌', '负重', '未分级', '双脚分开与肩同宽站立，每只手各握一个哑铃。稍微弯曲膝盖，髋部向前转动，保持背部挺直。将手臂向两侧举起，肘部保持轻微弯曲。继续举起手臂，直到它们与地面平行。在顶部暂停片刻，然后慢慢将手臂放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0844', 'weighted round arm', 'shoulders', '肩部', '30', 'weighted', 'triceps', 'delts', '三角肌', '["肱三头肌","上背部"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows. Continue lifting your arms until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0844-VLYXo8S.jpg', '/static/exercises/gifs/0844-VLYXo8S.gif', '© Gym visual — https://gymvisual.com/', '902203'),
('100846', '负重俄罗斯转体', '腹斜肌', '负重', '未分级', '坐在地上，膝盖弯曲，双脚平放在地板上。双手握住重物球或健身球放在胸前。稍微向后倾斜，保持背部挺直，核心肌群参与。慢慢地将你的躯干向右扭转，将重物或药球拉向右侧的地板。暂停片刻，然后将躯干向左扭转，将重物或健身球拉向左侧的地板。继续交替进行所需的重复次数。', 'exercise-dataset', '0846', 'weighted russian twist', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on the ground with your knees bent and your feet flat on the floor. Hold a weight or medicine ball with both hands in front of your chest. Lean back slightly, keeping your back straight and your core engaged. Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side. Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0846-fZFZ704.jpg', '/static/exercises/gifs/0846-fZFZ704.gif', '© Gym visual — https://gymvisual.com/', '402204'),
('100845', '负重俄罗斯转体双腿向上', '腹斜肌', '负重', '未分级', '坐在地上，膝盖弯曲，双脚离开地面，保持双腿并拢。用双手将重物放在胸前，保持肘部稍微弯曲。稍微向后倾斜以锻炼核心肌肉。将躯干向右扭转，将重量移向右侧地面。暂停片刻，然后将躯干向左扭转，将重量转移到左侧地面。继续交替进行所需的重复次数。', 'exercise-dataset', '0845', 'weighted russian twist (legs up)', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","髋屈肌"]', 'Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together. Hold the weight with both hands in front of your chest, keeping your elbows slightly bent. Lean back slightly to engage your core muscles. Twist your torso to the right, bringing the weight towards the ground on your right side. Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0845-WU9BLIs.jpg', '/static/exercises/gifs/0845-WU9BLIs.gif', '© Gym visual — https://gymvisual.com/', '402209'),
('102371', '负重俄罗斯转体版本第二式', '腹斜肌', '负重', '未分级', '坐在地上，膝盖弯曲，双脚平放在地板上。用双手将重物放在胸前。稍微向后倾斜以锻炼核心肌肉。将躯干向右扭转，将重量移至身体右侧。暂停片刻，然后将躯干向左扭转，将重量移向身体的左侧。继续交替进行所需的重复次数。', 'exercise-dataset', '2371', 'weighted russian twist v. 2', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on the ground with your knees bent and feet flat on the floor. Hold the weight with both hands in front of your chest. Lean back slightly to engage your core muscles. Twist your torso to the right, bringing the weight towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/2371-YIUAtYf.jpg', '/static/exercises/gifs/2371-YIUAtYf.gif', '© Gym visual — https://gymvisual.com/', '402210'),
('100847', '负重坐姿肱二头肌弯举瑞士球', '前臂', '药球', '未分级', '坐在稳定球上，双脚平放在地面上，背部挺直。反手握住健身球，手掌朝上，让手臂垂在身体两侧。保持上臂静止，呼气并将药球向上卷向肩膀。在顶部暂停片刻，挤压你的二头肌。吸气并缓慢地将健身球放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0847', 'weighted seated bicep curl (on stability ball)', 'upper arms', '上臂', '50', 'medicine ball', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides. Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the medicine ball back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0847-b4b6afT.jpg', '/static/exercises/gifs/0847-b4b6afT.gif', '© Gym visual — https://gymvisual.com/', '82215'),
('100849', '负重坐姿转体瑞士球', '腹斜肌', '负重', '未分级', '坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。双手靠近胸部握住杠铃片或哑铃。启动你的核心并慢慢地将你的躯干旋转到一侧，保持臀部稳定。旋转结束时暂停片刻，然后慢慢回到起始位置。重复旋转到另一侧。继续交替进行所需的重复次数。', 'exercise-dataset', '0849', 'weighted seated twist (on stability ball)', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a weight plate or dumbbell with both hands close to your chest. Engage your core and slowly rotate your torso to one side, keeping your hips stable. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat the rotation to the other side. Continue alternating sides for the desired number of repetitions.', '/static/exercises/images/0849-s34Y4LR.jpg', '/static/exercises/gifs/0849-s34Y4LR.gif', '© Gym visual — https://gymvisual.com/', '902214'),
('100850', '负重侧向侧屈瑞士球', '腹斜肌', '负重', '未分级', '坐在稳定球上，双脚分开与肩同宽，平放在地面上。一只手握住重物，另一只手放在臀部上。启动你的核心，慢慢向受重侧侧弯，保持背部挺直。在底部停顿片刻，然后慢慢回到起始位置。重复所需的重复次数，然后换边。', 'exercise-dataset', '0850', 'weighted side bend (on stability ball)', 'waist', '腰腹', '60', 'weighted', 'obliques', 'abs', '腹肌', '["腹斜肌","下背部"]', 'Sit on a stability ball with your feet shoulder-width apart and flat on the ground. Hold a weight in one hand and place your other hand on your hip. Engage your core and slowly bend sideways towards the weighted side, keeping your back straight. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', '/static/exercises/images/0850-6bOA1Oi.jpg', '/static/exercises/gifs/0850-6bOA1Oi.gif', '© Gym visual — https://gymvisual.com/', '902215'),
('100851', '负重西西深蹲', '臀肌', '负重', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。用双手将重物放在胸前，或将杠铃放在上背部。保持挺胸，核心收紧，弯曲膝盖和臀部，慢慢降低身体。继续降低，直到大腿与地面平行或尽可能低。在底部停顿片刻，然后推动脚后跟回到起始位置。重复所需的重复次数。', 'exercise-dataset', '0851', 'weighted sissy squat', 'upper legs', '大腿', '40', 'weighted', 'glutes', 'quads', '股四头肌', '["臀肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart and your toes pointing slightly outward. Hold a weight in front of your chest with both hands, or place a barbell across your upper back. Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0851-0lQnxMZ.jpg', '/static/exercises/gifs/0851-0lQnxMZ.gif', '© Gym visual — https://gymvisual.com/', '2210'),
('100852', '负重深蹲', '股四头肌', '负重', '未分级', '双脚分开与肩同宽站立，脚趾稍微向外。将重物放在胸前或肩膀上。收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。推动脚后跟站起来，在顶部挤压臀部。重复所需的重复次数。', 'exercise-dataset', '0852', 'weighted squat', 'upper legs', '大腿', '40', 'weighted', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Hold a weight in front of your chest or on your shoulders. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Push through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', '/static/exercises/images/0852-JZuApnB.jpg', '/static/exercises/gifs/0852-JZuApnB.gif', '© Gym visual — https://gymvisual.com/', '2209'),
('100853', '负重站姿弯举', '前臂', '负重', '未分级', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。保持肘部靠近躯干，并在将哑铃弯举至肩部水平时呼气。在顶部暂停片刻，然后吸气，慢慢将重量放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0853', 'weighted standing curl', 'upper arms', '上臂', '50', 'weighted', 'forearms', 'biceps', '肱二头肌', '["前臂"]', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level. Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0853-M5Y7GPg.jpg', '/static/exercises/gifs/0853-M5Y7GPg.gif', '© Gym visual — https://gymvisual.com/', '82212'),
('100854', '负重站姿手挤压', '肱二头肌', '负重', '未分级', '双脚分开与肩同宽站立，每只手各握一个重物。将双臂伸直在身前，手掌相对。尽可能用力将双手握在一起，用力接触前臂。按住挤压几秒钟，然后松开。重复所需的重复次数。', 'exercise-dataset', '0854', 'weighted standing hand squeeze', 'lower arms', '前臂', '80', 'weighted', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Stand with your feet shoulder-width apart and hold a weight in each hand. Extend your arms straight in front of you, palms facing each other. Squeeze your hands together as hard as you can, engaging your forearms. Hold the squeeze for a few seconds, then release. Repeat for the desired number of repetitions.', '/static/exercises/images/0854-bjqbauy.jpg', '/static/exercises/gifs/0854-bjqbauy.gif', '© Gym visual — https://gymvisual.com/', '902215'),
('103313', '负重直杆臂屈伸', '肱三头肌', '负重', '未分级', '将自己置于双杠之间，双臂完全伸展，身体伸直。弯曲肘部降低身体，直到上臂与地面平行。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '3313', 'weighted straight bar dip', 'chest', '胸部', '10', 'weighted', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Position yourself between parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3313-Ff18ItA.jpg', '/static/exercises/gifs/3313-Ff18ItA.gif', '© Gym visual — https://gymvisual.com/', '322216'),
('103642', '负重拉伸弓步', '股四头肌', '负重', '未分级', '双脚分开与肩同宽站立。右脚向前迈出一步，保持背部挺直。弯曲膝盖降低身体，直到右大腿与地面平行。推动右脚跟回到起始位置。左腿重复上述动作。继续交替双腿达到所需的重复次数。', 'exercise-dataset', '3642', 'weighted stretch lunge', 'upper legs', '大腿', '40', 'weighted', 'quadriceps', 'glutes', '臀肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Stand with your feet shoulder-width apart. Take a step forward with your right foot, keeping your back straight. Lower your body by bending your knees until your right thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg. Continue alternating legs for the desired number of repetitions.', '/static/exercises/images/3642-13VW2VO.jpg', '/static/exercises/gifs/3642-13VW2VO.gif', '© Gym visual — https://gymvisual.com/', '322215'),
('100856', '负重斯文德推举', '肩部', '负重', '未分级', '双脚分开与肩同宽站立，双手将杠铃片放在胸前。保持肘部稍微弯曲，手掌相对。将配重板直接压在您面前，完全伸展双臂。动作结束时暂停片刻，然后慢慢将配重板放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0856', 'weighted svend press', 'chest', '胸部', '10', 'weighted', 'shoulders', 'pectorals', '胸肌', '["肩部","肱三头肌"]', 'Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands. Keep your elbows slightly bent and your palms facing each other. Press the weight plate straight out in front of you, fully extending your arms. Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0856-I1OBLnn.jpg', '/static/exercises/gifs/0856-I1OBLnn.gif', '© Gym visual — https://gymvisual.com/', '902216'),
('101754', '负重三训练凳臂屈伸', '胸肌', '负重', '未分级', '坐在长凳边缘，双手抓住边缘，手指指向前方。双脚向前走，将臀部滑离长凳，并用手臂支撑体重。弯曲肘部降低身体，使背部靠近长凳。在底部暂停片刻，然后将自己推回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1754', 'weighted three bench dips', 'upper arms', '上臂', '50', 'weighted', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward. Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms. Lower your body by bending your elbows, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1754-gtO1ErP.jpg', '/static/exercises/gifs/1754-gtO1ErP.gif', '© Gym visual — https://gymvisual.com/', '482219'),
('101755', '负重肱三头肌臂屈伸', '胸肌', '负重', '未分级', '坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。将你的屁股从长凳前面滑下来，双腿在你面前伸展。保持背部靠近长凳，肘部稍微弯曲。弯曲肘部降低身体，直到上臂与地板平行。伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '1755', 'weighted tricep dips', 'upper arms', '上臂', '50', 'weighted', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the front of the bench with your legs extended in front of you. Keep your back close to the bench and your elbows slightly bent. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/1755-bZq4bwK.jpg', '/static/exercises/gifs/1755-bZq4bwK.gif', '© Gym visual — https://gymvisual.com/', '482218'),
('101767', '负重肱三头肌臂屈伸高位平行握双杠', '胸肌', '负重', '未分级', '将自己定位在两个双杠之间，双手握住杠，双臂完全伸展。弯曲肘部并降低身体，直到上臂与地面平行。暂停片刻，然后用手掌推直手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1767', 'weighted triceps dip on high parallel bars', 'upper arms', '上臂', '50', 'weighted', 'chest', 'triceps', '肱三头肌', '["胸肌","肩部"]', 'Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended. Bend your elbows and lower your body until your upper arms are parallel to the ground. Pause for a moment, then push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1767-K1vlode.jpg', '/static/exercises/gifs/1767-K1vlode.gif', '© Gym visual — https://gymvisual.com/', '482227'),
('100857', '健腹轮滚轮前伸', '下背部', '健腹轮', '未分级', '跪在地板上，将滚轮放在您面前。将双手放在滚轮的手柄上，并将手臂伸直至前方。调动你的核心肌肉，慢慢向前滚动轮子，保持背部挺直，腹肌紧张。继续向前滚动，直到身体完全伸展并且手臂举过头顶。暂停片刻，然后慢慢地将轮子向膝盖方向滚动，保持控制并保持腹肌接合。重复所需的重复次数。', 'exercise-dataset', '0857', 'wheel rollerout', 'waist', '腰腹', '60', 'wheel roller', 'lower back', 'abs', '腹肌', '["下背部"]', 'Kneel on the floor and place the wheel roller in front of you. Place your hands on the handles of the wheel roller and extend your arms straight out in front of you. Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight. Continue rolling forward until your body is fully extended and your arms are overhead. Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged. Repeat for the desired number of repetitions.', '/static/exercises/images/0857-NAgVB3t.jpg', '/static/exercises/gifs/0857-NAgVB3t.gif', '© Gym visual — https://gymvisual.com/', '562218'),
('103637', '健腹轮跑', '股四头肌', '自重', '未分级', '从平板支撑位置开始，双手放在方向盘上，身体伸直。启动你的核心并通过伸展双臂开始向前滚动轮子。继续滚动，直到身体完全伸展并且手臂举过头顶。使用你的核心和手臂将轮子拉回你的身体，从而扭转运动。重复所需的重复次数。', 'exercise-dataset', '3637', 'wheel run', 'cardio', '有氧', '90', 'body weight', 'quadriceps', 'cardiovascular system', '心肺系统', '["股四头肌","腘绳肌","小腿肌群"]', 'Start in a plank position with your hands on the wheel and your body straight. Engage your core and start rolling the wheel forward by extending your arms. Continue rolling until your body is fully extended and your arms are overhead. Reverse the movement by pulling the wheel back towards your body, using your core and arms. Repeat for the desired number of repetitions.', '/static/exercises/images/3637-km2Ljzj.jpg', '/static/exercises/gifs/3637-km2Ljzj.gif', '© Gym visual — https://gymvisual.com/', '481319'),
('101429', '宽距握引体向上', '肱二头肌', '自重', '未分级', '悬挂在引体向上杆上，手掌背向自己，双手之间的距离比肩宽。启动你的核心并将肩胛骨挤压在一起。将身体向上拉向杠铃，直到下巴位于杠铃上方。有控制地降低身体回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1429', 'wide grip pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar until your chin is above the bar. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', '/static/exercises/images/1429-Qqi7bko.jpg', '/static/exercises/gifs/1429-Qqi7bko.gif', '© Gym visual — https://gymvisual.com/', '1322'),
('101367', '宽距握后侧引体向上', '肱二头肌', '自重', '未分级', '正手宽握抓住引体向上杆，双手间距略宽于肩宽。悬挂在杠上，双臂完全伸展，身体伸直。调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。继续拉，直到下巴位于杠铃上方。在顶部停顿片刻，然后慢慢将身体放回起始位置。重复所需的重复次数。', 'exercise-dataset', '1367', 'wide grip rear pull-up', 'back', '背部', '20', 'body weight', 'biceps', 'lats', '背阔肌', '["肱二头肌","前臂"]', 'Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1367-OYFhXVD.jpg', '/static/exercises/gifs/1367-OYFhXVD.gif', '© Gym visual — https://gymvisual.com/', '1325'),
('101311', '宽距手俯卧撑', '肱三头肌', '自重', '未分级', '从高平板支撑位置开始，双手分开比肩宽。保持身体从头到脚呈一条直线。弯曲肘部，将胸部压向地面，使其靠近身体两侧。推动手掌以伸展手臂并返回到起始位置。重复所需的重复次数。', 'exercise-dataset', '1311', 'wide hand push up', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Start in a high plank position with your hands wider than shoulder-width apart. Keep your body in a straight line from head to toe. Lower your chest towards the ground by bending your elbows, keeping them close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/1311-JmMVpR3.jpg', '/static/exercises/gifs/1311-JmMVpR3.gif', '© Gym visual — https://gymvisual.com/', '901326'),
('102363', '宽握双杠臂屈伸高位平行握双杠', '肱三头肌', '自重', '未分级', '将自己置于双杠上，双臂完全伸展，身体悬浮在空中。稍微向前倾，弯曲肘部降低身体，直到胸部位于杠铃上方。暂停片刻，然后伸直手臂，将自己推回起始位置。重复所需的重复次数。', 'exercise-dataset', '2363', 'wide-grip chest dip on high parallel bars', 'chest', '胸部', '10', 'body weight', 'triceps', 'pectorals', '胸肌', '["肱三头肌","肩部"]', 'Position yourself on the parallel bars with your arms fully extended and your body suspended in the air. Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', '/static/exercises/images/2363-O2K9Vb5.jpg', '/static/exercises/gifs/2363-O2K9Vb5.gif', '© Gym visual — https://gymvisual.com/', '321333'),
('100858', '绕环冲刺跑', '股四头肌', '自重', '未分级', '找一个空地或跑道来进行练习。首先站立，双脚分开与肩同宽。开始尽可能快地跑步，挥动手臂并抬起膝盖。继续冲刺特定的距离或时间。休息并重复所需的重复次数。', 'exercise-dataset', '0858', 'wind sprints', 'waist', '腰腹', '60', 'body weight', 'quadriceps', 'abs', '腹肌', '["股四头肌","腘绳肌","小腿肌群"]', 'Find an open space or a track to perform the exercise. Start by standing with your feet shoulder-width apart. Begin running as fast as you can, pumping your arms and driving your knees up. Continue sprinting for a specific distance or time period. Rest and repeat for the desired number of repetitions.', '/static/exercises/images/0858-Qoujh3Q.jpg', '/static/exercises/gifs/0858-Qoujh3Q.gif', '© Gym visual — https://gymvisual.com/', '901324'),
('101604', '全球式最大全程拉伸', '臀肌', '自重', '未分级', '从弓步位置开始，右脚向前，左脚向后。将双手放在右脚两侧的地面上。将左膝降低到地面并伸展右腿，保持右脚平放在地面上。向右旋转你的躯干，将你的右臂伸向天花板。保持这个姿势几秒钟，然后回到起始位置。换边并重复拉伸，左脚向前。', 'exercise-dataset', '1604', 'world greatest stretch', 'upper legs', '大腿', '40', 'body weight', 'glutes', 'hamstrings', '腘绳肌', '["臀肌","股四头肌","小腿肌群"]', 'Start in a lunge position with your right foot forward and your left foot back. Place your hands on the ground on either side of your right foot. Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground. Rotate your torso to the right, reaching your right arm up towards the ceiling. Hold this position for a few seconds, then return to the starting position. Switch sides and repeat the stretch with your left foot forward.', '/static/exercises/images/1604-DFGXwZr.jpg', '/static/exercises/gifs/1604-DFGXwZr.gif', '© Gym visual — https://gymvisual.com/', '901327'),
('101428', '手腕环绕', '手部', '自重', '未分级', '将双臂伸直在身前。双手握拳。以圆周运动旋转手腕，保持手臂静止。继续手腕转圈达到所需的重复次数。', 'exercise-dataset', '1428', 'wrist circles', 'lower arms', '前臂', '80', 'body weight', 'hands', 'forearms', '前臂肌群', '["手部","手腕"]', 'Extend your arms straight out in front of you. Make a fist with both hands. Rotate your wrists in a circular motion, keeping your arms still. Continue the wrist circles for the desired number of repetitions.', '/static/exercises/images/1428-2zNKRUB.jpg', '/static/exercises/gifs/1428-2zNKRUB.gif', '© Gym visual — https://gymvisual.com/', '901326'),
('100859', '手腕滚轮', '肱二头肌', '负重', '未分级', '将重物固定在绳子或杆的一端。用双手握住绳子或杆的另一端，手掌朝下。双脚分开与肩同宽站立，双臂完全伸展在身前。弯曲手腕，慢慢地将重物向上滚动到手上。在顶部暂停片刻，然后慢慢将重量放回起始位置。重复所需的重复次数。', 'exercise-dataset', '0859', 'wrist rollerer', 'lower arms', '前臂', '80', 'weighted', 'biceps', 'forearms', '前臂肌群', '["肱二头肌","肱三头肌"]', 'Attach a weight to one end of a rope or bar. Hold the other end of the rope or bar with both hands, palms facing down. Stand with your feet shoulder-width apart and your arms fully extended in front of you. Slowly roll the weight up towards your hands by flexing your wrists. Pause for a moment at the top, then slowly lower the weight back down to the starting position. Repeat for the desired number of repetitions.', '/static/exercises/images/0859-bd5b860.jpg', '/static/exercises/gifs/0859-bd5b860.gif', '© Gym visual — https://gymvisual.com/', '902227')
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    muscle_group = VALUES(muscle_group),
    equipment = VALUES(equipment),
    instructions = VALUES(instructions),
    name_en = VALUES(name_en),
    category_code = VALUES(category_code),
    category_name = VALUES(category_name),
    category_sort = VALUES(category_sort),
    equipment_code = VALUES(equipment_code),
    muscle_group_code = VALUES(muscle_group_code),
    target_code = VALUES(target_code),
    target_name = VALUES(target_name),
    secondary_muscles = VALUES(secondary_muscles),
    instructions_en = VALUES(instructions_en),
    image_url = VALUES(image_url),
    gif_url = VALUES(gif_url),
    attribution = VALUES(attribution),
    popularity_rank = VALUES(popularity_rank);
